@dataclass(frozen=True)
class ReleaseGateSettings:
    mode: str
    evidence_dir: Path
    expected_topic: str
    expected_rule_version: str
    host_contract_path: Path
    vm_contract_path: Path
    kafka_env_file: Path
    preauthorization_capsule_path: Path | None = None
    preproduction_capsule_path: Path | None = None
    group_binding_receipt_dir: Path = (
        Path.home() / ".hermes" / "pnc_agent" / "receipts" / "g1q3_rca"
    )
    host_repo_root: Path = REPO_ROOT
    workspace_repo_root: Path = DEFAULT_WORKSPACE_REPO_ROOT
    vm_repo_root: str = DEFAULT_VM_REPO_ROOT
    vm_worker_repo_root: str = DEFAULT_VM_WORKER_REPO_ROOT
    evidence_max_age_seconds: int = DEFAULT_EVIDENCE_MAX_AGE_SECONDS
    shadow_soak_min_seconds: int = DEFAULT_SHADOW_SOAK_MIN_SECONDS
    min_storage_horizon_days: int = DEFAULT_MIN_STORAGE_HORIZON_DAYS
    target_cases_per_day: int = DEFAULT_TARGET_CASES_PER_DAY
    min_capacity_horizon_days: float = DEFAULT_MIN_CAPACITY_HORIZON_DAYS

    def __post_init__(self) -> None:
        if self.mode not in ALLOWED_MODES:
            raise ValueError(f"mode must be one of: {', '.join(sorted(ALLOWED_MODES))}")
        if not self.expected_topic.strip():
            raise ValueError("expected_topic must not be empty")
        if any(marker in self.expected_topic for marker in (",", "\n", "\r")):
            raise ValueError("expected_topic must name one exact topic")
        if not self.expected_rule_version.strip():
            raise ValueError("expected_rule_version must not be empty")
        for field_name in ("vm_repo_root", "vm_worker_repo_root"):
            raw_path = str(getattr(self, field_name) or "").strip()
            parsed_path = PurePosixPath(raw_path)
            if (
                not raw_path
                or not parsed_path.is_absolute()
                or ".." in parsed_path.parts
                or "\x00" in raw_path
                or "\n" in raw_path
                or "\r" in raw_path
            ):
                raise ValueError(f"{field_name} must be one safe absolute POSIX path")
        if self.evidence_max_age_seconds < 1:
            raise ValueError("evidence_max_age_seconds must be positive")
        if self.shadow_soak_min_seconds < 1:
            raise ValueError("shadow_soak_min_seconds must be positive")
        if self.min_storage_horizon_days < 1:
            raise ValueError("min_storage_horizon_days must be positive")
        if (
            isinstance(self.target_cases_per_day, bool)
            or not isinstance(self.target_cases_per_day, int)
            or self.target_cases_per_day < 1
        ):
            raise ValueError("target_cases_per_day must be a positive integer")
        if (
            isinstance(self.min_capacity_horizon_days, bool)
            or not isinstance(self.min_capacity_horizon_days, (int, float))
            or not math.isfinite(float(self.min_capacity_horizon_days))
            or self.min_capacity_horizon_days <= 0
        ):
            raise ValueError("min_capacity_horizon_days must be positive")
        if self.mode in {
            "preauthorization",
            "preproduction",
            *CANARY_MODES,
            *PRODUCTION_MODES,
        }:
            if self.evidence_max_age_seconds > DEFAULT_EVIDENCE_MAX_AGE_SECONDS:
                raise ValueError("release evidence freshness policy cannot be weakened")
            if self.shadow_soak_min_seconds < DEFAULT_SHADOW_SOAK_MIN_SECONDS:
                raise ValueError("shadow soak policy cannot be weakened")
            if self.min_storage_horizon_days < DEFAULT_MIN_STORAGE_HORIZON_DAYS:
                raise ValueError("storage horizon policy cannot be weakened")
            if self.target_cases_per_day < DEFAULT_TARGET_CASES_PER_DAY:
                raise ValueError("target case volume policy cannot be weakened")
            if self.min_capacity_horizon_days < DEFAULT_MIN_CAPACITY_HORIZON_DAYS:
                raise ValueError("capacity horizon policy cannot be weakened")


BuildProvenanceVerifier = Callable[
    [ReleaseGateSettings],
    Mapping[str, Any],
]
RemoteReaderLiveVerifier = Callable[
    [ReleaseGateSettings],
    Mapping[str, Any],
]


@dataclass(frozen=True)
class CutoverConfig:
    legacy_auto_execution_disabled: bool | None
    legacy_daily_quota: int | None
    legacy_governance_download_enabled: bool | None
    delivery_collector_enabled: bool | None = None
    delivery_dispatcher_enabled: bool | None = None
    issue_capture_enabled: bool | None = None
    issue_capture_root_configured: bool = False
    manual_intake_enabled: bool | None = None
    manual_chat_ids: tuple[str, ...] = ()
    manual_operator_enabled: bool | None = None
    manual_operator_user_ids: tuple[str, ...] = ()
    manual_operator_rate_limit: int | None = None
    manual_operator_rate_window_seconds: int | None = None
    activation_required: bool | None = None

    @classmethod
    def from_env(cls, env: Mapping[str, str]) -> "CutoverConfig":
        disabled = _optional_boolean(env, "HERMES_RCA_LEGACY_AUTO_EXECUTION_DISABLED")
        governance_enabled = _optional_boolean(env, "G1Q3_GOVERNANCE_DOWNLOAD_ENABLED")
        delivery_collector_enabled = _optional_boolean(
            env, "HERMES_RCA_DELIVERY_COLLECTOR_ENABLED"
        )
        delivery_dispatcher_enabled = _optional_boolean(
            env, "HERMES_RCA_DELIVERY_DISPATCHER_ENABLED"
        )
        issue_capture_enabled = _optional_boolean(
            env, "HERMES_G1Q3_ISSUE_CAPTURE_ENABLED"
        )
        manual_intake_enabled = _optional_boolean(
            env, "HERMES_RCA_MANUAL_INTAKE_ENABLED"
        )
        manual_operator_enabled = _optional_boolean(
            env, "HERMES_RCA_MANUAL_OPERATOR_ENABLED"
        )
        activation_required = _optional_boolean(
            env, "HERMES_RCA_ACTIVATION_REQUIRED"
        )
        manual_chat_ids = _normalized_manual_chat_ids(
            tuple(
                item.strip()
                for item in str(env.get("HERMES_RCA_MANUAL_CHAT_IDS", "")).split(",")
                if item.strip()
            )
        )
        manual_operator_user_ids = _normalized_manual_operator_user_ids(
            tuple(
                item.strip()
                for item in str(
                    env.get("HERMES_RCA_MANUAL_OPERATOR_USER_IDS", "")
                ).split(",")
                if item.strip()
            )
        )
        manual_operator_rate_limit = _optional_positive_integer(
            env, "HERMES_RCA_MANUAL_OPERATOR_RATE_LIMIT"
        )
        manual_operator_rate_window_seconds = _optional_positive_integer(
            env, "HERMES_RCA_MANUAL_OPERATOR_RATE_WINDOW_SECONDS"
        )
        issue_capture_root_configured = bool(
            str(env.get("HERMES_G1Q3_ISSUE_CAPTURE_ROOT", "")).strip()
        )
        raw_quota = str(env.get("HERMES_G1Q3_AUTO_DOWNLOAD_DAILY_QUOTA", "")).strip()
        quota: int | None = None
        if raw_quota:
            try:
                quota = int(raw_quota)
            except ValueError as exc:
                raise ValueError(
                    "HERMES_G1Q3_AUTO_DOWNLOAD_DAILY_QUOTA must be an integer"
                ) from exc
            if quota < 0:
                raise ValueError(
                    "HERMES_G1Q3_AUTO_DOWNLOAD_DAILY_QUOTA must be non-negative"
                )
        return cls(
            legacy_auto_execution_disabled=disabled,
            legacy_daily_quota=quota,
            legacy_governance_download_enabled=governance_enabled,
            delivery_collector_enabled=delivery_collector_enabled,
            delivery_dispatcher_enabled=delivery_dispatcher_enabled,
            issue_capture_enabled=issue_capture_enabled,
            issue_capture_root_configured=issue_capture_root_configured,
            manual_intake_enabled=manual_intake_enabled,
            manual_chat_ids=manual_chat_ids,
            manual_operator_enabled=manual_operator_enabled,
            manual_operator_user_ids=manual_operator_user_ids,
            manual_operator_rate_limit=manual_operator_rate_limit,
            manual_operator_rate_window_seconds=(manual_operator_rate_window_seconds),
            activation_required=activation_required,
        )

    def public_dict(self) -> dict[str, Any]:
        return {
            "legacy_auto_execution_disabled": self.legacy_auto_execution_disabled,
            "legacy_daily_quota": self.legacy_daily_quota,
            "legacy_governance_download_enabled": (
                self.legacy_governance_download_enabled
            ),
            "delivery_collector_enabled": self.delivery_collector_enabled,
            "delivery_dispatcher_enabled": self.delivery_dispatcher_enabled,
            "issue_capture_enabled": self.issue_capture_enabled,
            "issue_capture_root_configured": self.issue_capture_root_configured,
            "manual_intake_enabled": self.manual_intake_enabled,
            "manual_chat_ids": list(self.manual_chat_ids),
            "manual_operator_enabled": self.manual_operator_enabled,
            "manual_operator_user_count": len(self.manual_operator_user_ids),
            "manual_operator_user_ids_sha256": _sha256_json(
                list(self.manual_operator_user_ids)
            ),
            "manual_operator_rate_limit": self.manual_operator_rate_limit,
            "manual_operator_rate_window_seconds": (
                self.manual_operator_rate_window_seconds
            ),
            "activation_required": self.activation_required,
        }


class _Checks:
    def __init__(self) -> None:
        self.items: list[dict[str, Any]] = []

    def pass_(self, name: str, detail: Mapping[str, Any] | None = None) -> None:
        self.items.append({
            "name": name,
            "ok": True,
            "code": "pass",
            "detail": dict(detail or {}),
        })

    def fail(
        self,
        name: str,
        code: str,
        detail: Mapping[str, Any] | None = None,
    ) -> None:
        self.items.append({
            "name": name,
            "ok": False,
            "code": code,
            "detail": dict(detail or {}),
        })


def _optional_boolean(env: Mapping[str, str], name: str) -> bool | None:
    raw = str(env.get(name, "")).strip().lower()
    if not raw:
        return None
    if raw in {"1", "true", "yes", "on"}:
        return True
    if raw in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"{name} must be true or false")


def _optional_positive_integer(env: Mapping[str, str], name: str) -> int | None:
    raw = str(env.get(name, "")).strip()
    if not raw:
        return None
    try:
        value = int(raw)
    except ValueError as exc:
        raise ValueError(f"{name} must be a positive integer") from exc
    if value < 1:
        raise ValueError(f"{name} must be a positive integer")
    return value


def _canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    )


def _sha256_json(value: Any) -> str:
    return hashlib.sha256(_canonical_json(value).encode("utf-8")).hexdigest()


def _remote_soak_canonical_json_bytes(value: Any) -> bytes:
    try:
        return json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise EvidenceError("remote_reader_soak_json_invalid") from exc


def _remote_soak_sha256(value: Any) -> str:
    return hashlib.sha256(_remote_soak_canonical_json_bytes(value)).hexdigest()


def _remote_soak_merkle_root(record_hashes: Sequence[str]) -> str:
    if not record_hashes:
        raise EvidenceError("remote_reader_soak_case_volume_insufficient")
    try:
        level = [
            hashlib.sha256(
                REMOTE_READER_SOAK_MERKLE_LEAF_PREFIX + bytes.fromhex(digest)
            ).digest()
            for digest in record_hashes
            if _sha256_digest(digest, "remote_reader_soak.record_hash")
        ]
    except ValueError as exc:
        raise EvidenceError("remote_reader_soak_case_hash_invalid") from exc
    while len(level) > 1:
        if len(level) % 2:
            level.append(level[-1])
        level = [
            hashlib.sha256(
                REMOTE_READER_SOAK_MERKLE_NODE_PREFIX
                + level[index]
                + level[index + 1]
            ).digest()
            for index in range(0, len(level), 2)
        ]
    return level[0].hex()


def _stable_trigger_source_id(storage_source_kind: str, dedupe_key: str) -> str:
    return "g1q3-rca-source-v1-" + _sha256_json({
        "source_kind": storage_source_kind,
        "dedupe": dedupe_key,
    })


def _normalized_manual_chat_ids(value: Sequence[str]) -> tuple[str, ...]:
    normalized = tuple(
        sorted({str(item or "").strip() for item in value if str(item or "").strip()})
    )
    fixed = {G1Q3_RCA_GROUP_ID, PNC_ALL_BUSINESS_TEST_GROUP_ID}
    if normalized and not set(normalized).issubset(fixed):
        raise EvidenceError("manual_chat_allowlist_invalid")
    return normalized


def _normalized_manual_operator_user_ids(value: Sequence[str]) -> tuple[str, ...]:
    normalized = tuple(
        sorted({str(item or "").strip() for item in value if str(item or "").strip()})
    )
    if any(
        re.fullmatch(r"ou_[A-Za-z0-9_-]{1,255}", user_id) is None
        for user_id in normalized
    ):
        raise ValueError(
            "HERMES_RCA_MANUAL_OPERATOR_USER_IDS must contain Feishu open IDs"
        )
    return normalized


def _sha256_execution_request(value: Any) -> str:
    canonical = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _mapping(value: Any, field: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise EvidenceError("invalid_evidence_format", f"{field} must be an object")
    return value


def _require_fixed_cifs_storage_contract(
    value: Mapping[str, Any], *, field: str, blocker: str
) -> None:
    mount = _mapping(value.get("mount_evidence"), f"{field}.mount_evidence")
    if (
        any(
            value.get(key) is not expected
            if isinstance(expected, bool)
            else value.get(key) != expected
            for key, expected in FIXED_CIFS_STORAGE_CONTRACT.items()
        )
        or set(mount)
        != set(FIXED_CIFS_MOUNT_EVIDENCE) | FIXED_CIFS_MOUNT_EVIDENCE_DYNAMIC_KEYS
        or any(
            mount.get(key) is not expected
            if isinstance(expected, bool)
            else mount.get(key) != expected
            for key, expected in FIXED_CIFS_MOUNT_EVIDENCE.items()
        )
    ):
        raise EvidenceError(blocker)
    try:
        _exact_int(
            mount.get("device_id"), f"{field}.mount_evidence.device_id", minimum=1
        )
    except EvidenceError as exc:
        raise EvidenceError(blocker) from exc
    if re.fullmatch(r"mnt:\[[0-9]+\]", str(mount.get("mount_namespace") or "")) is None:
        raise EvidenceError(blocker)


def _required_text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise EvidenceError("invalid_evidence_format", f"{field} must be a string")
    return value.strip()


def _exact_int(value: Any, field: str, *, minimum: int = 0) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
        raise EvidenceError(
            "invalid_evidence_format", f"{field} must be an integer >= {minimum}"
        )
    return value


def _number(value: Any, field: str, *, minimum: float = 0.0) -> float:
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(float(value))
        or float(value) < minimum
    ):
        raise EvidenceError(
            "invalid_evidence_format", f"{field} must be a finite number >= {minimum}"
        )
    return float(value)


def _sha256_digest(value: Any, field: str) -> str:
    digest = _required_text(value, field)
    if (
        len(digest) != 64
        or digest != digest.lower()
        or any(character not in "0123456789abcdef" for character in digest)
    ):
        raise EvidenceError("invalid_evidence_format", f"{field} must be a SHA-256")
    return digest


def _timestamp(value: Any, field: str) -> datetime:
    text = _required_text(value, field)
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError as exc:
        raise EvidenceError(
            "invalid_evidence_format", f"{field} must be an ISO-8601 timestamp"
        ) from exc
    if parsed.tzinfo is None:
        raise EvidenceError(
            "invalid_evidence_format", f"{field} must include a timezone"
        )
    return parsed.astimezone(timezone.utc)


def _require_fresh(
    body: Mapping[str, Any],
    *,
    now: datetime,
    max_age_seconds: int,
    artifact: str,
) -> str:
    observed = _timestamp(body.get("observed_at"), f"{artifact}.observed_at")
    now_utc = now.astimezone(timezone.utc)
    age = (now_utc - observed).total_seconds()
    if age < -30:
        raise EvidenceError(f"{artifact}_from_future")
    if age > max_age_seconds:
        raise EvidenceError(f"{artifact}_stale")
    return observed.isoformat()


def _require_schema(body: Mapping[str, Any], expected: str, artifact: str) -> None:
    if body.get("schema_version") != expected:
        raise EvidenceError(f"{artifact}_schema_mismatch")


def _strict_json_loads(raw: str, *, artifact: str) -> Any:
    def unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate_json_key")
            result[key] = value
        return result

    def reject_constant(_value: str) -> None:
        raise ValueError("invalid_json_constant")

    try:
        value = json.loads(
            raw,
            object_pairs_hook=unique_object,
            parse_constant=reject_constant,
        )
    except (json.JSONDecodeError, RecursionError, ValueError) as exc:
        raise EvidenceError(f"{artifact}_invalid_json") from exc
    stack: list[tuple[Any, int]] = [(value, 1)]
    while stack:
        item, depth = stack.pop()
        if depth > MAX_EVIDENCE_JSON_NESTING:
            raise EvidenceError(f"{artifact}_json_too_deep")
        if isinstance(item, dict):
            stack.extend((child, depth + 1) for child in item.values())
        elif isinstance(item, list):
            stack.extend((child, depth + 1) for child in item)
    return value


def _check_remote_execution_request(
    value: Any,
    *,
    field: str,
    expected_admission: Mapping[str, Any],
    expected_origin_source_id: str,
    expected_origin_storage_kind: str,
) -> dict[str, Any]:
    """Validate the immutable remote-read ABI without exposing resource IDs."""
    request = _mapping(value, field)
    if find_rca_legacy_download_violation(request):
        raise EvidenceError("remote_request_legacy_download_field_present")
    expected = FIXED_REMOTE_ACCESS_CONTRACT
    if set(request) != {
        "schema_version",
        "request_kind",
        "work_item",
        "case",
        "data",
        "evidence",
        "execution_policy",
        "source_refs",
        "toolchain",
    }:
        raise EvidenceError("remote_request_shape_invalid")
    if request.get("schema_version") != expected["request_schema_version"]:
        raise EvidenceError("remote_request_schema_mismatch")
    if request.get("request_kind") != "issue_intake":
        raise EvidenceError("remote_request_kind_mismatch")

    admission_refs = _mapping(
        expected_admission.get("source_refs"), "expected_admission.source_refs"
    )
    submission_key = _required_text(
        expected_admission.get("submission_key"), "expected_admission.submission_key"
    )
    business_key = _required_text(
        expected_admission.get("business_key"), "expected_admission.business_key"
    )
    work_item = _mapping(request.get("work_item"), f"{field}.work_item")
    if set(work_item) != {
        "project_key",
        "work_item_type",
        "work_item_id",
        "url",
        "title",
        "status",
        "owners",
    }:
        raise EvidenceError("remote_request_work_item_shape_invalid")
    if (
        work_item.get("project_key") != admission_refs.get("project_key")
        or work_item.get("work_item_type") != admission_refs.get("work_item_type_key")
        or work_item.get("work_item_id") != admission_refs.get("work_item_id")
    ):
        raise EvidenceError("remote_request_work_item_identity_mismatch")

    source_refs = _mapping(request.get("source_refs"), f"{field}.source_refs")
    expected_source_refs = {
        "task_id": submission_key,
        "source_kind": expected_origin_storage_kind,
        "origin_source_id": expected_origin_source_id,
        "rule_version": admission_refs.get("rule_version"),
        "generation": expected_admission.get("generation"),
        "business_key": business_key,
        "submission_key": submission_key,
    }
    event_uid = ""
    if expected_origin_storage_kind == "kafka_workflow_event":
        event_uid = (
            f"{admission_refs.get('topic')}:{admission_refs.get('partition')}:"
            f"{admission_refs.get('offset')}"
        )
        expected_source_refs.update({
            "source_event_id": event_uid,
            "topic": admission_refs.get("topic"),
            "partition": admission_refs.get("partition"),
            "offset": admission_refs.get("offset"),
        })
    elif (
        expected_origin_storage_kind != "feishu_group_manual"
        or admission_refs.get("topic") != ""
        or admission_refs.get("partition") is not None
        or admission_refs.get("offset") is not None
    ):
        raise EvidenceError("remote_request_origin_source_invalid")
    if source_refs != expected_source_refs:
        raise EvidenceError("remote_request_source_refs_mismatch")

    data = _mapping(request.get("data"), f"{field}.data")
    if set(data) != {"data_access", "artifact_root", "artifact_cifs_root"}:
        raise EvidenceError("remote_request_data_shape_invalid")
    access = _mapping(data.get("data_access"), f"{field}.data.data_access")
    if set(access) != {
        "schema_version",
        "mode",
        "transport",
        "references",
        "source",
        "reader_contract",
    }:
        raise EvidenceError("remote_request_data_access_shape_invalid")
    if access.get("schema_version") != expected["data_access_schema_version"]:
        raise EvidenceError("remote_request_data_access_schema_mismatch")
    if access.get("mode") != expected["mode"]:
        raise EvidenceError("remote_request_data_access_mode_mismatch")
    if access.get("transport") != expected["transport"]:
        raise EvidenceError("remote_request_transport_mismatch")

    references = access.get("references")
    if not isinstance(references, list) or not 1 <= len(references) <= 16:
        raise EvidenceError("remote_request_references_invalid")
    reference_kinds: list[str] = []
    reader_classes: list[str] = []
    canonical_references: set[str] = set()
    for index, raw_reference in enumerate(references):
        reference = _mapping(
            raw_reference, f"{field}.data.data_access.references[{index}]"
        )
        kind = reference.get("kind")
        if kind == "event":
            expected_keys = {"kind", "event_uuid", "reader_class"}
            locator_field = "event_uuid"
            reader_class = "RemoteEventReader"
        elif kind == "clip":
            expected_keys = {"kind", "clip_uuid", "reader_class"}
            locator_field = "clip_uuid"
            reader_class = "RemoteClipReader"
        else:
            raise EvidenceError("remote_request_reference_kind_invalid")
        if set(reference) != expected_keys:
            raise EvidenceError("remote_request_reference_shape_invalid")
        _required_text(reference.get(locator_field), f"{field}.{locator_field}")
        if reference.get("reader_class") != reader_class:
            raise EvidenceError("remote_request_reader_class_mismatch")
        canonical = _canonical_json(reference)
        if canonical in canonical_references:
            raise EvidenceError("remote_request_reference_duplicate")
        canonical_references.add(canonical)
        reference_kinds.append(str(kind))
        reader_classes.append(reader_class)

    source = _mapping(access.get("source"), f"{field}.data.data_access.source")
    if set(source) != {"field", "value_sha256"}:
        raise EvidenceError("remote_request_source_shape_invalid")
    if source.get("field") != expected["source_field"]:
        raise EvidenceError("remote_request_source_field_mismatch")
    _sha256_digest(source.get("value_sha256"), f"{field}.source.value_sha256")

    reader = _mapping(
        access.get("reader_contract"), f"{field}.data.data_access.reader_contract"
    )
    expected_reader = {
        "distribution": expected["distribution"],
        "required_version": expected["required_version"],
        "mdi_download_allowed": False,
        "fallback": "forbidden",
        "completeness": expected["completeness"],
    }
    if reader != expected_reader:
        raise EvidenceError("remote_request_reader_contract_mismatch")

    artifact_root = f"/mnt/tmp/{submission_key}/"
    artifact_cifs_root = (
        "//hfs1.minieye.tech/department-pnc_team-planning_algo-driving/tmp/"
        f"{submission_key}/"
    )
    if (
        data.get("artifact_root") != artifact_root
        or data.get("artifact_cifs_root") != artifact_cifs_root
    ):
        raise EvidenceError("remote_request_artifact_root_mismatch")

    policy = _mapping(request.get("execution_policy"), f"{field}.execution_policy")
    required_policy = {
        "mode": expected["mode"],
        "data_access_mode": expected["mode"],
        "allow_download": False,
        "input_materialization": "forbidden",
        "derived_artifacts_allowed": True,
        "allow_feishu_writeback": False,
        "artifact_root": artifact_root,
        "translate_baseline": "production",
    }
    if any(policy.get(key) != required for key, required in required_policy.items()):
        raise EvidenceError("remote_request_execution_policy_mismatch")
    if not isinstance(policy.get("group_response_cap"), str) or not isinstance(
        policy.get("translate_contract_path"), str
    ):
        raise EvidenceError("remote_request_execution_policy_mismatch")
    _mapping(request.get("case"), f"{field}.case")
    _mapping(request.get("evidence"), f"{field}.evidence")
    _mapping(request.get("toolchain"), f"{field}.toolchain")

    try:
        data_access_sha256 = canonical_data_access_sha256(access)
    except DerivedCapacityReservationError as exc:
        raise EvidenceError("remote_request_data_access_contract_invalid") from exc

    return {
        "schema_version": expected["request_schema_version"],
        "data_access_schema_version": expected["data_access_schema_version"],
        "mode": expected["mode"],
        "transport": expected["transport"],
        "reader_distribution": expected["distribution"],
        "reader_required_version": expected["required_version"],
        "reference_count": len(references),
        "reference_kinds": sorted(set(reference_kinds)),
        "reader_classes": sorted(set(reader_classes)),
        "submission_key": submission_key,
        "business_key": business_key,
        "origin_source_id": expected_origin_source_id,
        "origin_storage_source_kind": expected_origin_storage_kind,
        "event_uid": event_uid,
        "artifact_root": artifact_root,
        "artifact_cifs_root": artifact_cifs_root,
        "data_access_sha256": data_access_sha256,
        "request_sha256": _sha256_execution_request(request),
    }


def _load_evidence(
    evidence_dir: Path,
    filename: str,
    evidence_hashes: dict[str, str],
) -> dict[str, Any]:
    path = evidence_dir / filename
    if not path.is_file():
        raise EvidenceError(f"{path.stem}_missing")
    try:
        if path.stat().st_size > MAX_EVIDENCE_BYTES:
            raise EvidenceError(f"{path.stem}_too_large")
        raw = path.read_text(encoding="utf-8")
        body = _strict_json_loads(raw, artifact=path.stem)
    except EvidenceError:
        raise
    except (OSError, UnicodeError) as exc:
        raise EvidenceError(f"{path.stem}_invalid_json") from exc
    result = _mapping(body, path.stem)
    evidence_hashes[filename] = hashlib.sha256(raw.encode("utf-8")).hexdigest()
    return result


def _secure_read_evidence_json_at(
    directory_fd: int,
    filename: str,
    *,
    artifact: str,
    max_bytes: int,
) -> dict[str, Any]:
    if (
        not isinstance(filename, str)
        or not filename
        or Path(filename).name != filename
        or filename in {".", ".."}
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,254}", filename) is None
    ):
        raise EvidenceError(f"{artifact}_filename_invalid")
    nofollow = getattr(os, "O_NOFOLLOW", None)
    if nofollow is None:
        raise EvidenceError(f"{artifact}_secure_open_unavailable")
    flags = os.O_RDONLY | nofollow
    flags |= getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    try:
        fd = os.open(filename, flags, dir_fd=directory_fd)
    except FileNotFoundError as exc:
        raise EvidenceError(f"{artifact}_missing") from exc
    except OSError as exc:
        raise EvidenceError(f"{artifact}_unsafe_file") from exc
    try:
        before = os.fstat(fd)
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_uid != os.getuid()
            or stat.S_IMODE(before.st_mode) != 0o600
            or before.st_nlink != 1
        ):
            raise EvidenceError(f"{artifact}_unsafe_file")
        if before.st_size < 1 or before.st_size > max_bytes:
            raise EvidenceError(f"{artifact}_size_invalid")
        chunks: list[bytes] = []
        observed_size = 0
        while observed_size <= max_bytes:
            chunk = os.read(fd, min(64 * 1024, max_bytes + 1 - observed_size))
            if not chunk:
                break
            chunks.append(chunk)
            observed_size += len(chunk)
        raw = b"".join(chunks)
        after = os.fstat(fd)
        current = os.stat(filename, dir_fd=directory_fd, follow_symlinks=False)
        stable_fields = (
            "st_dev",
            "st_ino",
            "st_mode",
            "st_nlink",
            "st_uid",
            "st_size",
            "st_mtime_ns",
            "st_ctime_ns",
        )
        if (
            len(raw) != before.st_size
            or len(raw) > max_bytes
            or any(getattr(before, field) != getattr(after, field) for field in stable_fields)
            or any(getattr(after, field) != getattr(current, field) for field in stable_fields)
        ):
            raise EvidenceError(f"{artifact}_changed_during_read")
    except EvidenceError:
        raise
    except OSError as exc:
        raise EvidenceError(f"{artifact}_read_failed") from exc
    finally:
        os.close(fd)
    try:
        decoded = raw.decode("utf-8")
    except UnicodeError as exc:
        raise EvidenceError(f"{artifact}_invalid_json") from exc
    body = _mapping(
        _strict_json_loads(decoded, artifact=artifact),
        artifact,
    )
    return {
        "body": body,
        "size_bytes": len(raw),
        "raw_sha256": hashlib.sha256(raw).hexdigest(),
        "file_identity": {
            "device": before.st_dev,
            "inode": before.st_ino,
            "size_bytes": before.st_size,
            "mtime_ns": before.st_mtime_ns,
            "ctime_ns": before.st_ctime_ns,
        },
    }


def _open_secure_evidence_directory(evidence_dir: Path, *, artifact: str) -> int:
    nofollow = getattr(os, "O_NOFOLLOW", None)
    directory = getattr(os, "O_DIRECTORY", None)
    if nofollow is None or directory is None:
        raise EvidenceError(f"{artifact}_secure_open_unavailable")
    flags = os.O_RDONLY | nofollow | directory | getattr(os, "O_CLOEXEC", 0)
    path = evidence_dir.expanduser().absolute()
    fd = -1
    try:
        initial = os.lstat(path)
        if (
            not stat.S_ISDIR(initial.st_mode)
            or stat.S_ISLNK(initial.st_mode)
            or initial.st_uid != os.getuid()
            or initial.st_nlink < 1
            or stat.S_IMODE(initial.st_mode) & 0o022
            or path.resolve(strict=True) != path
        ):
            raise OSError("evidence directory trust boundary invalid")
        fd = os.open(path, flags)
        opened = os.fstat(fd)
        if (
            not stat.S_ISDIR(opened.st_mode)
            or opened.st_dev != initial.st_dev
            or opened.st_ino != initial.st_ino
            or opened.st_mode != initial.st_mode
            or opened.st_uid != initial.st_uid
            or opened.st_nlink != initial.st_nlink
        ):
            raise OSError("evidence directory changed while opening")
        return fd
    except OSError as exc:
        if fd >= 0:
            os.close(fd)
        raise EvidenceError(f"{artifact}_directory_invalid") from exc


def _load_canonical_owner_only_evidence(
    evidence_dir: Path,
    filename: str,
    *,
    artifact: str,
    evidence_hashes: dict[str, str],
) -> dict[str, Any]:
    directory_fd = _open_secure_evidence_directory(evidence_dir, artifact=artifact)
    try:
        observed = _secure_read_evidence_json_at(
            directory_fd,
            filename,
            artifact=artifact,
            max_bytes=MAX_EVIDENCE_BYTES,
        )
    finally:
        os.close(directory_fd)
    body = _mapping(observed.get("body"), artifact)
    canonical_file = _remote_soak_canonical_json_bytes(body) + b"\n"
    if (
        observed.get("size_bytes") != len(canonical_file)
        or observed.get("raw_sha256")
        != hashlib.sha256(canonical_file).hexdigest()
    ):
        raise EvidenceError(f"{artifact}_not_canonical")
    evidence_hashes[filename] = str(observed["raw_sha256"])
    return body


def _load_remote_reader_soak_manifest(
    evidence_dir: Path,
    evidence_hashes: dict[str, str],
) -> dict[str, Any]:
    return _load_canonical_owner_only_evidence(
        evidence_dir,
        REMOTE_READER_SOAK_MANIFEST_FILENAME,
        artifact="remote_reader_soak_manifest",
        evidence_hashes=evidence_hashes,
    )


def _load_remote_reader_workload_provenance(
    evidence_dir: Path,
    evidence_hashes: dict[str, str],
) -> dict[str, dict[str, Any]]:
    artifacts = {
        "census": (
            REMOTE_READER_WORKLOAD_CENSUS_FILENAME,
            "remote_reader_workload_census",
        ),
        "mapping": (
            REMOTE_READER_DOMAIN_MAPPING_FILENAME,
            "remote_reader_domain_mapping",
        ),
        "approval": (
            REMOTE_READER_DOMAIN_MAPPING_APPROVAL_FILENAME,
            "remote_reader_domain_mapping_approval",
        ),
        "receipt": (
            REMOTE_READER_WORKLOAD_EXPORT_RECEIPT_FILENAME,
            "remote_reader_workload_export_receipt",
        ),
    }
    return {
        name: _load_canonical_owner_only_evidence(
            evidence_dir,
            filename,
            artifact=artifact,
            evidence_hashes=evidence_hashes,
        )
        for name, (filename, artifact) in artifacts.items()
    }


def _committed_canary_material(
    *,
    spec: _CommittedCanaryEvidenceSpec,
    receipt_canonical_sha256: str,
    files: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    return {
        "schema_version": CANARY_EVIDENCE_COMMIT_SCHEMA_VERSION,
        "evidence_role": spec.evidence_role,
        "receipt_canonical_sha256": receipt_canonical_sha256,
        "files": {
            name: {
                "schema_version": files[name]["schema_version"],
                "size_bytes": files[name]["size_bytes"],
                "raw_sha256": files[name]["raw_sha256"],
            }
            for name in ("receipt", "sources")
        },
    }


def _load_committed_canary_evidence(
    evidence_dir: Path,
    evidence_role: str,
    evidence_hashes: dict[str, str],
) -> dict[str, Any]:
    spec = COMMITTED_CANARY_EVIDENCE_SPECS.get(evidence_role)
    if spec is None:
        raise EvidenceError("canary_evidence_role_invalid")
    artifact = Path(spec.manifest_filename).stem
    directory_fd = _open_secure_evidence_directory(evidence_dir, artifact=artifact)
    try:
        manifest_observation = _secure_read_evidence_json_at(
            directory_fd,
            spec.manifest_filename,
            artifact=artifact,
            max_bytes=MAX_CANARY_EVIDENCE_COMMIT_BYTES,
        )
        manifest = manifest_observation["body"]
        if set(manifest) != {
            "schema_version",
            "evidence_role",
            "commit_id",
            "published_at",
            "receipt_canonical_sha256",
            "files",
        }:
            raise EvidenceError(f"{artifact}_shape_invalid")
        if (
            manifest.get("schema_version") != CANARY_EVIDENCE_COMMIT_SCHEMA_VERSION
            or manifest.get("evidence_role") != spec.evidence_role
        ):
            raise EvidenceError(f"{artifact}_contract_invalid")
        commit_id = _sha256_digest(
            manifest.get("commit_id"),
            f"{artifact}.commit_id",
        )
        published_at = _timestamp(
            manifest.get("published_at"),
            f"{artifact}.published_at",
        ).isoformat()
        receipt_canonical_sha256 = _sha256_digest(
            manifest.get("receipt_canonical_sha256"),
            f"{artifact}.receipt_canonical_sha256",
        )
        raw_files = _mapping(manifest.get("files"), f"{artifact}.files")
        if set(raw_files) != {"receipt", "sources"}:
            raise EvidenceError(f"{artifact}_files_invalid")
        expected_files = {
            "receipt": (
                f"{spec.receipt_stem}.{commit_id}.json",
                spec.receipt_schema_version,
            ),
            "sources": (
                f"{spec.sources_stem}.{commit_id}.json",
                spec.sources_schema_version,
            ),
        }
        files: dict[str, dict[str, Any]] = {}
        for name in ("receipt", "sources"):
            descriptor = _mapping(
                raw_files.get(name),
                f"{artifact}.files.{name}",
            )
            if set(descriptor) != {
                "filename",
                "schema_version",
                "size_bytes",
                "raw_sha256",
            }:
                raise EvidenceError(f"{artifact}_{name}_descriptor_invalid")
            filename = _required_text(
                descriptor.get("filename"),
                f"{artifact}.files.{name}.filename",
            )
            if (
                Path(filename).name != filename
                or filename in {".", ".."}
                or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,254}", filename)
                is None
            ):
                raise EvidenceError(f"{artifact}_{name}_filename_invalid")
            expected_filename, expected_schema = expected_files[name]
            if (
                filename != expected_filename
                or descriptor.get("schema_version") != expected_schema
            ):
                raise EvidenceError(f"{artifact}_{name}_binding_invalid")
            files[name] = {
                "filename": filename,
                "schema_version": expected_schema,
                "size_bytes": _exact_int(
                    descriptor.get("size_bytes"),
                    f"{artifact}.files.{name}.size_bytes",
                    minimum=1,
                ),
                "raw_sha256": _sha256_digest(
                    descriptor.get("raw_sha256"),
                    f"{artifact}.files.{name}.raw_sha256",
                ),
            }
        observations: dict[str, dict[str, Any]] = {}
        for name in ("receipt", "sources"):
            observed = _secure_read_evidence_json_at(
                directory_fd,
                files[name]["filename"],
                artifact=f"{artifact}_{name}",
                max_bytes=MAX_EVIDENCE_BYTES,
            )
            if (
                observed["size_bytes"] != files[name]["size_bytes"]
                or observed["raw_sha256"] != files[name]["raw_sha256"]
                or observed["body"].get("schema_version")
                != files[name]["schema_version"]
            ):
                raise EvidenceError(f"{artifact}_{name}_content_mismatch")
            observations[name] = observed
        observed_receipt_canonical_sha256 = _sha256_json(
            observations["receipt"]["body"]
        )
        if observed_receipt_canonical_sha256 != receipt_canonical_sha256:
            raise EvidenceError(f"{artifact}_receipt_canonical_mismatch")
        expected_commit_id = _sha256_json(
            _committed_canary_material(
                spec=spec,
                receipt_canonical_sha256=receipt_canonical_sha256,
                files=files,
            )
        )
        if commit_id != expected_commit_id:
            raise EvidenceError(f"{artifact}_commit_id_mismatch")
    finally:
        os.close(directory_fd)

    evidence_hashes[spec.manifest_filename] = manifest_observation["raw_sha256"]
    for name in ("receipt", "sources"):
        evidence_hashes[files[name]["filename"]] = observations[name]["raw_sha256"]
    binding = {
        "evidence_role": spec.evidence_role,
        "commit_id": commit_id,
        "manifest_filename": spec.manifest_filename,
        "manifest_raw_sha256": manifest_observation["raw_sha256"],
        "manifest_file_identity": manifest_observation["file_identity"],
        "files": {
            name: {
                **files[name],
                "file_identity": observations[name]["file_identity"],
            }
            for name in ("receipt", "sources")
        },
    }
    return {
        **binding,
        "published_at": published_at,
        "receipt_canonical_sha256": receipt_canonical_sha256,
        "receipt": observations["receipt"]["body"],
        "sources": observations["sources"]["body"],
        "binding_sha256": _sha256_json(binding),
    }


def _recheck_committed_canary_evidence(
    evidence_dir: Path,
    expected: Mapping[str, Any],
) -> dict[str, Any]:
    evidence_role = _required_text(
        expected.get("evidence_role"),
        "committed_canary_evidence.evidence_role",
    )
    observed_hashes: dict[str, str] = {}
    try:
        observed = _load_committed_canary_evidence(
            evidence_dir,
            evidence_role,
            observed_hashes,
        )
    except EvidenceError as exc:
        raise EvidenceError(
            "manual_gateway_runtime_barrier_evidence_changed"
        ) from exc
    binding_fields = (
        "evidence_role",
        "commit_id",
        "manifest_filename",
        "manifest_raw_sha256",
        "manifest_file_identity",
        "files",
        "binding_sha256",
    )
    if any(observed.get(field) != expected.get(field) for field in binding_fields):
        raise EvidenceError("manual_gateway_runtime_barrier_evidence_changed")
    return observed


def _broker_authorized_operations(value: Any, *, resource: str) -> list[str]:
    if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
        raise EvidenceError(f"broker_metadata_{resource}_authorization_invalid")
    operations = sorted(set(value))
    operation_set = set(operations)
    if (
        value != operations
        or not operation_set.issubset(KNOWN_AUTHORIZED_OPERATIONS)
        or not REQUIRED_AUTHORIZED_OPERATIONS.issubset(operation_set)
        or operation_set & MUTATING_AUTHORIZED_OPERATIONS
    ):
        raise EvidenceError(f"broker_metadata_{resource}_authorization_invalid")
    return operations


def _broker_topology(
    body: Mapping[str, Any],
    *,
    minimum_replication_factor: int,
) -> tuple[list[int], list[dict[str, Any]], int]:
    artifact = "broker_metadata"
    raw_partitions = body.get("partitions")
    if not isinstance(raw_partitions, list) or not raw_partitions:
        raise EvidenceError("broker_metadata_partitions_missing")
    partitions = [
        _exact_int(value, f"{artifact}.partitions", minimum=0)
        for value in raw_partitions
    ]
    if partitions != list(range(len(partitions))):
        raise EvidenceError("broker_metadata_partitions_not_contiguous")

    raw_topology = body.get("partition_topology")
    if not isinstance(raw_topology, list) or len(raw_topology) != len(partitions):
        raise EvidenceError("broker_metadata_topology_invalid")
    topology: list[dict[str, Any]] = []
    replication_factors: set[int] = set()
    for expected_partition, raw_item in zip(partitions, raw_topology, strict=True):
        item = _mapping(raw_item, f"{artifact}.partition_topology")
        if set(item) != {
            "partition",
            "leader_id",
            "leader_epoch",
            "replicas",
            "isr",
            "offline_replicas",
        }:
            raise EvidenceError("broker_metadata_topology_invalid")
        partition = _exact_int(
            item.get("partition"), f"{artifact}.topology.partition", minimum=0
        )
        leader_id = _exact_int(
            item.get("leader_id"), f"{artifact}.topology.leader_id", minimum=0
        )
        leader_epoch = _exact_int(
            item.get("leader_epoch"),
            f"{artifact}.topology.leader_epoch",
            minimum=0,
        )
        if partition != expected_partition:
            raise EvidenceError("broker_metadata_topology_invalid")

        normalized: dict[str, list[int]] = {}
        for field in ("replicas", "isr", "offline_replicas"):
            raw_values = item.get(field)
            if not isinstance(raw_values, list):
                raise EvidenceError("broker_metadata_topology_invalid")
            values = [
                _exact_int(
                    value,
                    f"{artifact}.topology.{field}",
                    minimum=0,
                )
                for value in raw_values
            ]
            if values != sorted(set(values)):
                raise EvidenceError("broker_metadata_topology_invalid")
            normalized[field] = values
        if (
            not normalized["replicas"]
            or normalized["isr"] != normalized["replicas"]
            or normalized["offline_replicas"]
            or leader_id not in normalized["isr"]
        ):
            raise EvidenceError("broker_metadata_topology_unhealthy")
        replication_factors.add(len(normalized["replicas"]))
        topology.append({
            "partition": partition,
            "leader_id": leader_id,
            "leader_epoch": leader_epoch,
            **normalized,
        })

    if len(replication_factors) != 1:
        raise EvidenceError("broker_metadata_replication_factor_inconsistent")
    replication_factor = replication_factors.pop()
    reported_replication_factor = _exact_int(
        body.get("replication_factor"),
        f"{artifact}.replication_factor",
        minimum=1,
    )
    if reported_replication_factor != replication_factor:
        raise EvidenceError("broker_metadata_replication_factor_mismatch")
    if replication_factor < minimum_replication_factor:
        raise EvidenceError("broker_metadata_replication_factor_below_policy")
    return partitions, topology, replication_factor


def _expected_broker_probe(
    *,
    consumer: ConsumerConfig,
    kafka_env_file: Path,
) -> tuple[BrokerProbeConfig, dict[str, Any]]:
    try:
        source, env_observation = load_kafka_preflight_environment(kafka_env_file)
        probe = BrokerProbeConfig.from_env(source)
    except (OSError, ValueError) as exc:
        raise EvidenceError("broker_metadata_env_file_invalid") from exc
    if probe.minimum_replication_factor < MIN_KAFKA_REPLICATION_FACTOR:
        raise EvidenceError("broker_metadata_replication_policy_too_weak")
    if (
        probe.bootstrap_servers != consumer.bootstrap_servers
        or probe.topic != consumer.topic
        or probe.username != consumer.username
        or probe.password != consumer.password
        or probe.configured_group_id != consumer.group_id
        or probe.api_version != consumer.api_version
        or probe.security_protocol != consumer.security_protocol
        or probe.sasl_mechanism != consumer.sasl_mechanism
        or probe.request_timeout_ms
        != min(consumer.request_timeout_ms, MAX_PREFLIGHT_REQUEST_TIMEOUT_MS)
    ):
        raise EvidenceError("broker_metadata_consumer_config_mismatch")
    return probe, env_observation


def _check_broker_metadata(
    body: Mapping[str, Any],
    *,
    consumer: ConsumerConfig,
    kafka_env_file: Path,
    host_repo_root: Path,
    expected_topic: str,
    now: datetime,
    max_age_seconds: int,
) -> tuple[list[int], dict[str, Any]]:
    artifact = "broker_metadata"
    _require_schema(body, BROKER_METADATA_SCHEMA_VERSION, artifact)
    if set(body) != BROKER_METADATA_FIELDS:
        raise EvidenceError("broker_metadata_shape_invalid")
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if (
        body.get("topic_authorized") is not True
        or body.get("topic_healthy") is not True
        or body.get("group_authorized") is not True
    ):
        raise EvidenceError("broker_metadata_authorization_or_health_invalid")

    probe, expected_env_observation = _expected_broker_probe(
        consumer=consumer,
        kafka_env_file=kafka_env_file,
    )
    if body.get("topic") != expected_topic or probe.topic != expected_topic:
        raise EvidenceError("broker_metadata_topic_mismatch")
    if body.get("group_id") != probe.configured_group_id:
        raise EvidenceError("broker_metadata_group_mismatch")
    if (
        body.get("cluster_id") != probe.expected_cluster_id
        or body.get("expected_cluster_id") != probe.expected_cluster_id
    ):
        raise EvidenceError("broker_metadata_cluster_mismatch")

    topic_operations = _broker_authorized_operations(
        body.get("topic_authorized_operations"), resource="topic"
    )
    group_operations = _broker_authorized_operations(
        body.get("group_authorized_operations"), resource="group"
    )
    partitions, topology, replication_factor = _broker_topology(
        body,
        minimum_replication_factor=probe.minimum_replication_factor,
    )

    collector = _mapping(body.get("collector"), f"{artifact}.collector")
    if set(collector) != KAFKA_PREFLIGHT_COLLECTOR_FIELDS:
        raise EvidenceError("broker_metadata_collector_shape_invalid")
    if (
        collector.get("schema_version")
        != KAFKA_PREFLIGHT_COLLECTOR_SCHEMA_VERSION
    ):
        raise EvidenceError("broker_metadata_collector_schema_mismatch")
    source_path = host_repo_root / "scripts" / "pnc_rca_kafka_preflight.py"
    try:
        expected_source_sha256 = hashlib.sha256(source_path.read_bytes()).hexdigest()
    except OSError as exc:
        raise EvidenceError("broker_metadata_collector_source_unreadable") from exc
    if collector.get("source_sha256") != expected_source_sha256:
        raise EvidenceError("broker_metadata_collector_source_mismatch")
    if collector.get("dependency_versions") != {"kafka-python": "3.0.7"}:
        raise EvidenceError("broker_metadata_collector_dependency_mismatch")
    expected_probe_config = probe.public_dict()
    if collector.get("config") != expected_probe_config:
        raise EvidenceError("broker_metadata_collector_config_mismatch")
    if collector.get("connection_config_sha256") != _sha256_json(
        expected_probe_config
    ):
        raise EvidenceError("broker_metadata_collector_config_hash_mismatch")
    if collector.get("env_file") != expected_env_observation:
        raise EvidenceError("broker_metadata_collector_env_mismatch")
    if collector.get("side_effect_contract") != KAFKA_PREFLIGHT_SIDE_EFFECT_CONTRACT:
        raise EvidenceError("broker_metadata_collector_side_effect_contract_invalid")

    return partitions, {
        "observed_at": observed_at,
        "cluster_id": probe.expected_cluster_id,
        "topic": expected_topic,
        "group_id": probe.configured_group_id,
        "partitions": partitions,
        "partition_topology": topology,
        "replication_factor": replication_factor,
        "minimum_replication_factor": probe.minimum_replication_factor,
        "topic_authorized_operations": topic_operations,
        "group_authorized_operations": group_operations,
        "collector_source_sha256": expected_source_sha256,
    }


def _partition_offsets(value: Any, field: str) -> dict[int, int]:
    mapping = _mapping(value, field)
    if not mapping:
        raise EvidenceError("t0_offsets_empty")
    result: dict[int, int] = {}
    for raw_partition, raw_offset in mapping.items():
        if not isinstance(raw_partition, str) or not raw_partition.isdigit():
            raise EvidenceError("t0_offsets_partition_invalid")
        partition = int(raw_partition)
        if str(partition) != raw_partition:
            raise EvidenceError("t0_offsets_partition_not_canonical")
        result[partition] = _exact_int(
            raw_offset, f"{field}.{raw_partition}", minimum=0
        )
    return result


def _check_t0_offsets(
    body: Mapping[str, Any],
    *,
    consumer: ConsumerConfig,
    expected_topic: str,
    broker_partitions: Sequence[int],
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    artifact = "t0_offsets"
    _require_schema(body, T0_OFFSETS_SCHEMA_VERSION, artifact)
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("explicit_t0") is not True:
        raise EvidenceError("t0_offsets_not_explicit")
    if body.get("topic") != expected_topic:
        raise EvidenceError("t0_offsets_topic_mismatch")
    if body.get("group_id") != FIXED_KAFKA_GROUP_ID:
        raise EvidenceError("t0_offsets_group_mismatch")
    offsets = _partition_offsets(body.get("partition_offsets"), "partition_offsets")
    configured = dict(consumer.initial_offsets)
    if offsets != configured:
        raise EvidenceError("t0_offsets_consumer_mismatch")
    if sorted(offsets) != list(broker_partitions):
        raise EvidenceError("t0_offsets_partition_set_mismatch")
    return {
        "observed_at": observed_at,
        "group_id": FIXED_KAFKA_GROUP_ID,
        "partition_count": len(offsets),
        "partition_offsets_sha256": _sha256_json({
            str(key): offsets[key] for key in sorted(offsets)
        }),
    }


def _check_workflow_fixtures(
    body: Mapping[str, Any],
    *,
    consumer: ConsumerConfig,
    expected_topic: str,
    expected_rule_version: str,
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    artifact = "workflow_fixtures"
    _require_schema(body, WORKFLOW_FIXTURES_SCHEMA_VERSION, artifact)
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("topic") != expected_topic:
        raise EvidenceError("workflow_fixtures_topic_mismatch")
    if body.get("creation_rule_version") != expected_rule_version:
        raise EvidenceError("workflow_fixtures_rule_mismatch")
    fixtures = body.get("fixtures")
    if not isinstance(fixtures, list) or len(fixtures) < 3:
        raise EvidenceError("workflow_fixtures_insufficient")

    names: set[str] = set()
    decisions: dict[str, int] = {"accepted": 0, "filtered": 0, "invalid": 0}
    for index, raw_fixture in enumerate(fixtures):
        fixture = _mapping(raw_fixture, f"fixtures[{index}]")
        name = _required_text(fixture.get("name"), f"fixtures[{index}].name")
        if name in names:
            raise EvidenceError("workflow_fixture_name_duplicate")
        names.add(name)
        topic = _required_text(fixture.get("topic"), f"fixtures[{index}].topic")
        value = fixture.get("value")
        if not isinstance(value, dict):
            raise EvidenceError("workflow_fixture_value_invalid")
        expected_decision = _required_text(
            fixture.get("expected_decision"),
            f"fixtures[{index}].expected_decision",
        )
        expected_reason = _required_text(
            fixture.get("expected_reason"), f"fixtures[{index}].expected_reason"
        )
        if expected_decision not in decisions:
            raise EvidenceError("workflow_fixture_decision_invalid")
        result = classify_workflow_event(
            topic=topic,
            value=value,
            policy=consumer.policy,
        )
        if result.decision != expected_decision or result.reason != expected_reason:
            raise EvidenceError("workflow_fixture_replay_mismatch", name)
        decisions[result.decision] += 1
    if any(count < 1 for count in decisions.values()):
        raise EvidenceError("workflow_fixture_decision_coverage_missing")
    return {
        "observed_at": observed_at,
        "fixture_count": len(fixtures),
        "decisions": decisions,
    }


def _check_shadow_soak(
    body: Mapping[str, Any],
    *,
    now: datetime,
    max_age_seconds: int,
    minimum_duration_seconds: int,
    minimum_storage_horizon_days: int,
    expected_partitions: Sequence[int],
    target_cases_per_day: int,
    expected_build_manifest_sha256: str,
    expected_config_sha256: str,
) -> dict[str, Any]:
    artifact = "shadow_soak"
    _require_schema(body, SHADOW_SOAK_SCHEMA_VERSION, artifact)
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("ok") is not True:
        raise EvidenceError("shadow_soak_not_ok")
    if _exact_int(body.get("error_count"), "shadow_soak.error_count") != 0:
        raise EvidenceError("shadow_soak_errors_present")
    duration = _exact_int(
        body.get("duration_seconds"), "shadow_soak.duration_seconds", minimum=1
    )
    if duration < minimum_duration_seconds:
        raise EvidenceError("shadow_soak_too_short")
    records_seen = _exact_int(
        body.get("records_seen"), "shadow_soak.records_seen", minimum=1
    )
    if records_seen < max(100, target_cases_per_day):
        raise EvidenceError("shadow_soak_record_volume_insufficient")
    if body.get("build_manifest_sha256") != expected_build_manifest_sha256:
        raise EvidenceError("shadow_soak_build_manifest_mismatch")
    if body.get("config_sha256") != expected_config_sha256:
        raise EvidenceError("shadow_soak_config_mismatch")
    records_committed = _exact_int(
        body.get("records_committed"),
        "shadow_soak.records_committed",
        minimum=0,
    )
    if records_committed != records_seen:
        raise EvidenceError("shadow_soak_commit_count_mismatch")
    for field in (
        "ingest_errors",
        "commit_errors",
        "pending_records",
        "rebalance_callback_errors",
    ):
        if _exact_int(body.get(field), f"shadow_soak.{field}", minimum=0) != 0:
            raise EvidenceError(f"shadow_soak_{field}_present")
    assignment_count = _exact_int(
        body.get("assignment_count"),
        "shadow_soak.assignment_count",
        minimum=1,
    )
    assigned = body.get("assigned_partitions")
    if not isinstance(assigned, list):
        raise EvidenceError("shadow_soak_assignment_missing")
    assigned_partitions = [
        _exact_int(value, "shadow_soak.assigned_partitions", minimum=0)
        for value in assigned
    ]
    if assigned_partitions != sorted(
        set(assigned_partitions)
    ) or assigned_partitions != list(expected_partitions):
        raise EvidenceError("shadow_soak_partition_coverage_mismatch")
    raw_decisions = _mapping(body.get("decision_counts"), "shadow_soak.decision_counts")
    expected_decisions = {"accepted", "filtered", "invalid", "deduped"}
    if set(raw_decisions) != expected_decisions:
        raise EvidenceError("shadow_soak_decision_counts_invalid")
    decision_counts = {
        key: _exact_int(raw_decisions[key], f"shadow_soak.decision_counts.{key}")
        for key in sorted(expected_decisions)
    }
    if sum(decision_counts.values()) != records_seen:
        raise EvidenceError("shadow_soak_decision_count_mismatch")
    if decision_counts["accepted"] < target_cases_per_day:
        raise EvidenceError("shadow_soak_accepted_volume_insufficient")
    burst_records = _exact_int(
        body.get("burst_records"), "shadow_soak.burst_records", minimum=1
    )
    burst_duration = _exact_int(
        body.get("burst_duration_seconds"),
        "shadow_soak.burst_duration_seconds",
        minimum=1,
    )
    if burst_records < max(100, target_cases_per_day // 2) or burst_duration > 60:
        raise EvidenceError("shadow_soak_burst_insufficient")
    lag_peak = _exact_int(
        body.get("consumer_lag_peak"), "shadow_soak.consumer_lag_peak", minimum=0
    )
    lag_end = _exact_int(
        body.get("consumer_lag_end"), "shadow_soak.consumer_lag_end", minimum=0
    )
    lag_recovery_seconds = _number(
        body.get("lag_recovery_seconds"),
        "shadow_soak.lag_recovery_seconds",
        minimum=0.0,
    )
    if lag_end != 0 or lag_recovery_seconds > 60:
        raise EvidenceError("shadow_soak_lag_recovery_failed")
    latency = _mapping(
        body.get("ingest_commit_latency_ms"),
        "shadow_soak.ingest_commit_latency_ms",
    )
    latency_values = {
        field: _number(
            latency.get(field),
            f"shadow_soak.ingest_commit_latency_ms.{field}",
            minimum=0.0,
        )
        for field in ("p50", "p95", "p99", "max")
    }
    if not (
        latency_values["p50"]
        <= latency_values["p95"]
        <= latency_values["p99"]
        <= latency_values["max"]
        and latency_values["p95"] <= 1_000
        and latency_values["p99"] <= 3_000
        and latency_values["max"] <= 10_000
    ):
        raise EvidenceError("shadow_soak_latency_slo_failed")
    rss_peak = _exact_int(
        body.get("process_rss_peak_bytes"),
        "shadow_soak.process_rss_peak_bytes",
        minimum=1,
    )
    if rss_peak > 512 * 1024 * 1024:
        raise EvidenceError("shadow_soak_rss_slo_failed")
    restart_count = _exact_int(
        body.get("restart_count"), "shadow_soak.restart_count", minimum=1
    )
    recovered_after_restart = _exact_int(
        body.get("recovered_pending_records"),
        "shadow_soak.recovered_pending_records",
        minimum=1,
    )
    measurement_scope = body.get("control_db_measurement_scope")
    if measurement_scope != "sqlite_db_wal_shm_total":
        raise EvidenceError("shadow_soak_control_db_measurement_scope_invalid")
    db_bytes_start = _exact_int(
        body.get("control_db_bytes_start"),
        "shadow_soak.control_db_bytes_start",
        minimum=0,
    )
    db_bytes_end = _exact_int(
        body.get("control_db_bytes_end"),
        "shadow_soak.control_db_bytes_end",
        minimum=0,
    )
    if db_bytes_end < db_bytes_start:
        raise EvidenceError("shadow_soak_control_db_size_regressed")
    projected_growth = _exact_int(
        body.get("projected_db_growth_bytes_per_day"),
        "shadow_soak.projected_db_growth_bytes_per_day",
        minimum=1,
    )
    observed_daily_growth = math.ceil(
        (db_bytes_end - db_bytes_start) * 86_400 / duration
    )
    if projected_growth < observed_daily_growth:
        raise EvidenceError("shadow_soak_projected_growth_understated")
    control_db_free_bytes = _exact_int(
        body.get("control_db_free_bytes"),
        "shadow_soak.control_db_free_bytes",
        minimum=1,
    )
    reported_horizon = _number(
        body.get("projected_storage_horizon_days"),
        "shadow_soak.projected_storage_horizon_days",
        minimum=0.0,
    )
    computed_horizon = control_db_free_bytes / projected_growth
    reporting_tolerance = max(0.01, computed_horizon * 0.01)
    if reported_horizon > computed_horizon + reporting_tolerance:
        raise EvidenceError("shadow_soak_storage_horizon_overstated")
    if (
        reported_horizon < minimum_storage_horizon_days
        or computed_horizon < minimum_storage_horizon_days
    ):
        raise EvidenceError("shadow_soak_storage_horizon_insufficient")
    return {
        "observed_at": observed_at,
        "duration_seconds": duration,
        "error_count": 0,
        "records_seen": records_seen,
        "records_committed": records_committed,
        "decision_counts": decision_counts,
        "target_cases_per_day": target_cases_per_day,
        "burst_records": burst_records,
        "burst_duration_seconds": burst_duration,
        "consumer_lag_peak": lag_peak,
        "consumer_lag_end": lag_end,
        "lag_recovery_seconds": lag_recovery_seconds,
        "ingest_commit_latency_ms": latency_values,
        "process_rss_peak_bytes": rss_peak,
        "restart_count": restart_count,
        "recovered_pending_records": recovered_after_restart,
        "assignment_count": assignment_count,
        "assigned_partitions": assigned_partitions,
        "ingest_errors": 0,
        "commit_errors": 0,
        "pending_records": 0,
        "rebalance_callback_errors": 0,
        "control_db_measurement_scope": "sqlite_db_wal_shm_total",
        "control_db_bytes_start": db_bytes_start,
        "control_db_bytes_end": db_bytes_end,
        "projected_db_growth_bytes_per_day": projected_growth,
        "control_db_free_bytes": control_db_free_bytes,
        "projected_storage_horizon_days": reported_horizon,
        "computed_storage_horizon_days": round(computed_horizon, 3),
        "minimum_storage_horizon_days": minimum_storage_horizon_days,
    }


def _numeric_version_at_least(value: str, minimum: tuple[int, int, int]) -> bool:
    match = re.match(r"^(\d+)\.(\d+)\.(\d+)", value)
    return bool(match and tuple(int(part) for part in match.groups()) >= minimum)


def _check_remote_reader_health(
    body: Mapping[str, Any],
    *,
    now: datetime,
    max_age_seconds: int,
    production: bool,
) -> dict[str, Any]:
    artifact = "remote_reader_health"
    _require_schema(body, REMOTE_READER_HEALTH_SCHEMA_VERSION, artifact)
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("ok") is not True or body.get("errors") != []:
        raise EvidenceError("remote_reader_health_not_ok")
    if (
        _exact_int(
            body.get("mdi_invocation_count"),
            "remote_reader_health.mdi_invocation_count",
            minimum=0,
        )
        != 0
    ):
        raise EvidenceError("remote_reader_health_mdi_invoked")
    source = _machine_evidence_source(
        body.get("source"),
        field="remote_reader_health.source",
        expected_component="pnc_rca_remote_reader_preflight",
    )

    runtime = _mapping(body.get("runtime"), "remote_reader_health.runtime")
    python_executable = _required_text(
        runtime.get("python_executable"),
        "remote_reader_health.runtime.python_executable",
    )
    required_python_executable = _required_text(
        runtime.get("required_python_executable"),
        "remote_reader_health.runtime.required_python_executable",
    )
    resolved_required_python_executable = _required_text(
        runtime.get("resolved_required_python_executable"),
        "remote_reader_health.runtime.resolved_required_python_executable",
    )
    module_path = _required_text(
        runtime.get("module_path"), "remote_reader_health.runtime.module_path"
    )
    if not PurePosixPath(python_executable).is_absolute():
        raise EvidenceError("remote_reader_python_executable_invalid")
    if not PurePosixPath(module_path).is_absolute():
        raise EvidenceError("remote_reader_module_path_invalid")
    if (
        runtime.get("execution_mode") != FIXED_REMOTE_READER_EXECUTION_MODE
        or runtime.get("dependency_domain") != FIXED_REMOTE_READER_DEPENDENCY_DOMAIN
        or required_python_executable != FIXED_REMOTE_READER_REQUIRED_PYTHON
        or python_executable != resolved_required_python_executable
        or runtime.get("reader_import_scope") != FIXED_REMOTE_READER_IMPORT_SCOPE
        or _exact_int(
            runtime.get("timeout_seconds"),
            "remote_reader_health.runtime.timeout_seconds",
            minimum=1,
        )
        != 120
    ):
        raise EvidenceError("remote_reader_dependency_domain_mismatch")
    expected_module_suffix = (
        f"/{PurePosixPath(REMOTE_READER_WHEEL_RELATIVE).name}/pdcl_pyclip/reader.py"
    )
    if expected_module_suffix not in module_path:
        raise EvidenceError("remote_reader_module_path_unpinned")
    python_version = _required_text(
        runtime.get("python_version"), "remote_reader_health.python_version"
    )
    if runtime.get("distribution") != FIXED_REMOTE_ACCESS_CONTRACT["distribution"]:
        raise EvidenceError("remote_reader_distribution_mismatch")
    if runtime.get("version") != FIXED_REMOTE_ACCESS_CONTRACT["required_version"]:
        raise EvidenceError("remote_reader_version_mismatch")
    if runtime.get("upstream_version") != FIXED_REMOTE_READER_UPSTREAM_VERSION:
        raise EvidenceError("remote_reader_upstream_version_mismatch")
    if (
        runtime.get("upstream_wheel_sha256")
        != FIXED_REMOTE_READER_UPSTREAM_WHEEL_SHA256
        or runtime.get("upstream_reader_module_sha256")
        != FIXED_REMOTE_READER_UPSTREAM_MODULE_SHA256
        or runtime.get("source_commit") != FIXED_REMOTE_READER_SOURCE_COMMIT
    ):
        raise EvidenceError("remote_reader_upstream_provenance_mismatch")
    sanitized_wheel_sha256 = _sha256_digest(
        runtime.get("sanitized_wheel_sha256"),
        "remote_reader_health.runtime.sanitized_wheel_sha256",
    )
    patch_sha256 = _sha256_digest(
        runtime.get("patch_sha256"), "remote_reader_health.runtime.patch_sha256"
    )
    sanitized_reader_module_sha256 = _sha256_digest(
        runtime.get("sanitized_reader_module_sha256"),
        "remote_reader_health.runtime.sanitized_reader_module_sha256",
    )
    if (
        runtime.get("sanitized_source_commit")
        != FIXED_REMOTE_READER_SANITIZED_SOURCE_COMMIT
        or patch_sha256 != FIXED_REMOTE_READER_PATCH_SHA256
        or sanitized_reader_module_sha256 != FIXED_REMOTE_READER_SANITIZED_MODULE_SHA256
    ):
        raise EvidenceError("remote_reader_sanitized_provenance_mismatch")
    if sanitized_wheel_sha256 == FIXED_REMOTE_READER_UPSTREAM_WHEEL_SHA256:
        raise EvidenceError("remote_reader_unsanitized_wheel_forbidden")
    if production and (
        not APPROVED_SANITIZED_WHEEL_SHA256
        or sanitized_wheel_sha256 != APPROVED_SANITIZED_WHEEL_SHA256
    ):
        raise EvidenceError("remote_reader_sanitized_wheel_not_pinned")
    security = _mapping(
        runtime.get("security_attestation"),
        "remote_reader_health.runtime.security_attestation",
    )
    if security != {
        "credentials_source": "environment_only",
        "auto_mount": False,
        "privileged_subprocess": False,
    }:
        raise EvidenceError("remote_reader_security_attestation_failed")
    runtime_environment = _mapping(
        runtime.get("runtime_environment"),
        "remote_reader_health.runtime.runtime_environment",
    )
    expected_runtime_environment = {
        "endpoint_variable": "PDCL_BASE_URL",
        "endpoint_source": "environment_only",
        "endpoint_present": True,
        "endpoint_valid": True,
        "credentials_source": "environment_only",
        "credentials_present": True,
        "cache_mount_variable": "PDCL_CACHE_MOUNT_POINT",
        "cache_mount_source": "environment_only_pre_mounted",
        "cache_mount_present": True,
        "legacy_endpoint_variables_accepted": False,
        "cache_mount_ready": True,
    }
    if runtime_environment != expected_runtime_environment:
        raise EvidenceError("remote_reader_runtime_environment_unverified")
    sanitization_scan = _mapping(
        runtime.get("sanitization_scan"),
        "remote_reader_health.runtime.sanitization_scan",
    )
    for field in ("storage_module_sha256", "config_module_sha256"):
        _sha256_digest(
            sanitization_scan.get(field),
            f"remote_reader_health.runtime.sanitization_scan.{field}",
        )
    if (
        sanitization_scan.get("storage_module_sha256")
        != FIXED_REMOTE_READER_SANITIZED_STORAGE_SHA256
        or sanitization_scan.get("config_module_sha256")
        != FIXED_REMOTE_READER_SANITIZED_CONFIG_SHA256
    ):
        raise EvidenceError("remote_reader_sanitized_source_hash_mismatch")
    if any(
        sanitization_scan.get(field) is not False
        for field in (
            "subprocess_present",
            "sudo_present",
            "apt_present",
            "static_sts_literal_present",
        )
    ):
        raise EvidenceError("remote_reader_sanitization_scan_failed")
    dependencies = _mapping(
        runtime.get("dependencies"), "remote_reader_health.runtime.dependencies"
    )
    if set(dependencies) != {"mcap", "protobuf", "typer", "pdcl_dss"}:
        raise EvidenceError("remote_reader_dependency_set_mismatch")
    if dependencies.get("mcap") != {
        "requirement": "==1.2.2",
        "installed_version": "1.2.2",
    } or dependencies.get("protobuf") != {
        "requirement": "==3.20.3",
        "installed_version": "3.20.3",
    }:
        raise EvidenceError("remote_reader_dependency_version_mismatch")
    if dependencies.get("typer") != {
        "requirement": "==0.20.0",
        "installed_version": "0.20.0",
    } or dependencies.get("pdcl_dss") != {
        "requirement": "==0.1.44",
        "installed_version": "0.1.44",
    }:
        raise EvidenceError("remote_reader_dependency_version_mismatch")

    raw_classes = _mapping(
        body.get("reader_classes"), "remote_reader_health.reader_classes"
    )
    expected_classes = {"RemoteClipReader", "RemoteEventReader"}
    if set(raw_classes) != expected_classes:
        raise EvidenceError("remote_reader_classes_incomplete")
    base_parameters = [
        "self",
        "topics",
        "start_time",
        "end_time",
        "log_time_order",
        "reverse",
    ]
    expected_signatures = {
        "RemoteClipReader": base_parameters,
        "RemoteEventReader": base_parameters + ["max_messages", "deadline_monotonic"],
    }
    class_summary: dict[str, dict[str, Any]] = {}
    for class_name in sorted(expected_classes):
        class_receipt = _mapping(
            raw_classes[class_name],
            f"remote_reader_health.reader_classes.{class_name}",
        )
        if class_receipt.get("importable") is not True:
            raise EvidenceError("remote_reader_class_not_importable")
        if class_receipt.get("module") != "pdcl_pyclip.reader":
            raise EvidenceError("remote_reader_class_module_mismatch")
        if (
            class_receipt.get("iter_messages_parameters")
            != expected_signatures[class_name]
        ):
            raise EvidenceError("remote_reader_iter_messages_signature_mismatch")
        features = _mapping(
            class_receipt.get("features"),
            f"remote_reader_health.reader_classes.{class_name}.features",
        )
        expected_features = (
            {
                "bounded_messages": False,
                "deadline_monotonic": False,
                "sequential_clip_iteration": False,
            }
            if class_name == "RemoteClipReader"
            else {
                "bounded_messages": True,
                "deadline_monotonic": True,
                "sequential_clip_iteration": True,
            }
        )
        if features != expected_features:
            raise EvidenceError("remote_reader_feature_contract_mismatch")
        class_summary[class_name] = {
            "importable": True,
            "module": "pdcl_pyclip.reader",
            "iter_messages_parameters": expected_signatures[class_name],
            "features": expected_features,
        }
    api = _mapping(body.get("api_contract"), "remote_reader_health.api_contract")
    if api.get("time_unit") != "nanoseconds" or api.get("window") != "[start,end)":
        raise EvidenceError("remote_reader_time_contract_mismatch")
    if api.get("topic_filter") is not True:
        raise EvidenceError("remote_reader_topic_filter_missing")
    resource_policy = _mapping(
        runtime.get("resource_policy"), "remote_reader_health.runtime.resource_policy"
    )
    if resource_policy != {
        "event_clip_iteration": "sequential",
        "max_open_readers_per_event": 1,
        "hard_timeout_boundary": "adapter_subprocess",
        "hard_timeout_seconds": 120,
        "termination_verified": True,
    }:
        raise EvidenceError("remote_reader_resource_policy_mismatch")

    fingerprint_material = {
        "runtime": runtime,
        "reader_classes": class_summary,
        "api_contract": api,
    }
    reader_fingerprint = _sha256_digest(
        body.get("reader_fingerprint"), "remote_reader_health.reader_fingerprint"
    )
    if reader_fingerprint != _sha256_json(fingerprint_material):
        raise EvidenceError("remote_reader_fingerprint_mismatch")

    fixture = _mapping(
        body.get("fixture_preflight"), "remote_reader_health.fixture_preflight"
    )
    if fixture.get("ok") is not True or fixture.get("errors") != []:
        raise EvidenceError("remote_reader_fixture_preflight_failed")
    if fixture.get("reader_fingerprint") != reader_fingerprint:
        raise EvidenceError("remote_reader_fixture_fingerprint_mismatch")
    tested_classes = fixture.get("reader_classes")
    if tested_classes != sorted(expected_classes):
        raise EvidenceError("remote_reader_fixture_class_coverage_missing")
    topics = fixture.get("topics")
    if (
        not isinstance(topics, list)
        or not topics
        or topics != sorted(set(topics))
        or not all(isinstance(topic, str) and topic for topic in topics)
    ):
        raise EvidenceError("remote_reader_fixture_topics_invalid")
    if _exact_int(
        fixture.get("message_count"),
        "remote_reader_health.fixture_preflight.message_count",
        minimum=1,
    ) < len(topics):
        raise EvidenceError("remote_reader_fixture_message_count_invalid")
    if fixture.get("time_window_filter") is not True:
        raise EvidenceError("remote_reader_fixture_time_filter_failed")

    return {
        "observed_at": observed_at,
        "source": source,
        "python_executable": python_executable,
        "python_version": python_version,
        "required_python_executable": required_python_executable,
        "resolved_required_python_executable": resolved_required_python_executable,
        "execution_mode": FIXED_REMOTE_READER_EXECUTION_MODE,
        "dependency_domain": FIXED_REMOTE_READER_DEPENDENCY_DOMAIN,
        "reader_import_scope": FIXED_REMOTE_READER_IMPORT_SCOPE,
        "module_path": module_path,
        "distribution": runtime["distribution"],
        "version": runtime["version"],
        "reader_classes": sorted(expected_classes),
        "iter_messages_signatures": expected_signatures,
        "fixture_topics": topics,
        "fixture_message_count": fixture["message_count"],
        "mdi_invocation_count": 0,
        "reader_fingerprint": reader_fingerprint,
        "sanitized_wheel_sha256": sanitized_wheel_sha256,
        "patch_sha256": patch_sha256,
        "sanitized_reader_module_sha256": sanitized_reader_module_sha256,
        "dependency_versions": {
            name.replace("pdcl_dss", "pdcl-dss"): str(
                dependency.get("installed_version") or ""
            )
            for name, dependency in dependencies.items()
        },
        "runtime_environment": expected_runtime_environment,
    }


def _check_requested_scope(value: Any, *, field: str) -> dict[str, Any]:
    scope = _mapping(value, field)
    if set(scope) != {"source", "requirements"}:
        raise EvidenceError("remote_requested_scope_shape_invalid")
    if scope.get("source") != "vm_evaluator_scope_contract":
        raise EvidenceError("remote_requested_scope_source_mismatch")
    requirements = _mapping(scope.get("requirements"), f"{field}.requirements")
    expected_keys = {
        "schema_version",
        "requirements_contract_version",
        "requirements_contract_hash",
        "function_domain",
        "requested_topics",
        "channel_allowlist",
        "frame_lookup",
        "frame_channel_allowlist",
        "requested_window",
        "evaluator_fingerprints",
        "requirements_hash",
    }
    if set(requirements) != expected_keys:
        raise EvidenceError("remote_requested_scope_requirements_shape_invalid")
    if requirements.get("schema_version") != REMOTE_REQUIREMENTS_SCHEMA_VERSION:
        raise EvidenceError("remote_requested_scope_requirements_schema_mismatch")
    if (
        requirements.get("requirements_contract_version")
        != REMOTE_REQUIREMENTS_CONTRACT_VERSION
    ):
        raise EvidenceError("remote_requested_scope_contract_version_mismatch")
    contract_sha256 = _sha256_digest(
        requirements.get("requirements_contract_hash"),
        f"{field}.requirements.requirements_contract_hash",
    )
    function_domain = _required_text(
        requirements.get("function_domain"),
        f"{field}.requirements.function_domain",
    )
    if function_domain not in {"ACC", "LCC", "AEB", "FCW", "AEB_FCW", "DNP"}:
        raise EvidenceError("remote_requested_scope_function_domain_invalid")

    def string_set(name: str) -> list[str]:
        items = requirements.get(name)
        if (
            not isinstance(items, list)
            or not items
            or items != sorted(set(items))
            or not all(isinstance(item, str) and item for item in items)
        ):
            raise EvidenceError(f"remote_requested_scope_{name}_invalid")
        return items

    topics = string_set("requested_topics")
    channels = string_set("channel_allowlist")
    if requirements.get("frame_lookup") != {}:
        raise EvidenceError("remote_requested_scope_frame_lookup_invalid")
    if requirements.get("frame_channel_allowlist") != []:
        raise EvidenceError("remote_requested_scope_frame_channel_allowlist_invalid")
    window = _mapping(
        requirements.get("requested_window"),
        f"{field}.requirements.requested_window",
    )
    canonical_window = {
        "mode": "full_reference",
        "start_time_ns": None,
        "end_time_ns": None,
    }
    if window != canonical_window:
        raise EvidenceError("remote_requested_scope_window_invalid")
    fingerprints = _mapping(
        requirements.get("evaluator_fingerprints"),
        f"{field}.requirements.evaluator_fingerprints",
    )
    if not fingerprints:
        raise EvidenceError("remote_requested_scope_evaluator_fingerprints_missing")
    normalized_fingerprints: dict[str, str] = {}
    for path, digest in fingerprints.items():
        if not isinstance(path, str):
            raise EvidenceError("remote_requested_scope_evaluator_path_invalid")
        parsed_path = PurePosixPath(path)
        if (
            parsed_path.is_absolute()
            or ".." in parsed_path.parts
            or not path.startswith(("api/g1q3_rca/", "g1q3_rca/"))
        ):
            raise EvidenceError("remote_requested_scope_evaluator_path_invalid")
        normalized_fingerprints[path] = _sha256_digest(
            digest, f"{field}.requirements.evaluator_fingerprints.{path}"
        )
    normalized_fingerprints = dict(sorted(normalized_fingerprints.items()))
    if dict(fingerprints) != normalized_fingerprints:
        raise EvidenceError("remote_requested_scope_evaluator_fingerprints_invalid")
    requirements_material = {
        "schema_version": REMOTE_REQUIREMENTS_SCHEMA_VERSION,
        "requirements_contract_version": REMOTE_REQUIREMENTS_CONTRACT_VERSION,
        "requirements_contract_hash": contract_sha256,
        "function_domain": function_domain,
        "requested_topics": topics,
        "channel_allowlist": channels,
        "frame_lookup": {},
        "frame_channel_allowlist": [],
        "requested_window": canonical_window,
        "evaluator_fingerprints": normalized_fingerprints,
    }
    requirements_hash = _sha256_digest(
        requirements.get("requirements_hash"),
        f"{field}.requirements.requirements_hash",
    )
    if requirements_hash != _sha256_json(requirements_material):
        raise EvidenceError("remote_requested_scope_requirements_hash_mismatch")
    normalized_requirements = {
        **requirements_material,
        "requirements_hash": requirements_hash,
    }
    normalized = {
        "source": "vm_evaluator_scope_contract",
        "requirements": normalized_requirements,
        "contract_sha256": contract_sha256,
        "requirements_hash": requirements_hash,
        "function_domain": function_domain,
        "topics": topics,
        "channels": channels,
        "window": canonical_window,
    }
    normalized["scope_sha256"] = _sha256_json({
        "source": scope["source"],
        "requirements": normalized_requirements,
    })
    return normalized


def _remote_soak_object(
    value: Any,
    *,
    field: str,
    keys: set[str],
    blocker: str,
) -> dict[str, Any]:
    parsed = _mapping(value, field)
    if set(parsed) != keys:
        raise EvidenceError(blocker)
    return parsed


def _remote_soak_timestamp(value: Any, field: str) -> datetime:
    parsed = _timestamp(value, field)
    if value != parsed.strftime("%Y-%m-%dT%H:%M:%S.%fZ"):
        raise EvidenceError("remote_reader_soak_timestamp_not_canonical")
    return parsed


def _remote_soak_commit(value: Any, field: str) -> str:
    text = _required_text(value, field)
    if re.fullmatch(r"[0-9a-f]{40}", text) is None:
        raise EvidenceError("remote_reader_soak_candidate_binding_invalid")
    return text


def _remote_soak_identifier(value: Any, field: str) -> str:
    text = _required_text(value, field)
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}", text) is None:
        raise EvidenceError("remote_reader_soak_case_identity_invalid")
    return text


def _remote_soak_count_map(value: Any, field: str) -> dict[str, int]:
    parsed = _mapping(value, field)
    return {
        str(key): _exact_int(item, f"{field}.{key}", minimum=1)
        for key, item in parsed.items()
    }


def _check_remote_reader_workload_provenance(
    artifacts: Mapping[str, Mapping[str, Any]],
    *,
    workload_manifest: Mapping[str, Any],
    evidence_hashes: Mapping[str, str],
    expected_host_commit: str,
    expected_exporter_sha256: str,
) -> dict[str, Any]:
    artifact = "remote_reader_workload_provenance"
    if (
        re.fullmatch(r"[0-9a-f]{40}", expected_host_commit or "") is None
        or re.fullmatch(r"[0-9a-f]{64}", expected_exporter_sha256 or "") is None
    ):
        raise EvidenceError("remote_reader_workload_build_unverified")
    if set(artifacts) != {"census", "mapping", "approval", "receipt"}:
        raise EvidenceError("remote_reader_workload_provenance_shape_invalid")

    census = _remote_soak_object(
        artifacts.get("census"),
        field=f"{artifact}.census",
        keys={
            "schema_version",
            "observed_at",
            "source",
            "feishu",
            "taxonomy",
            "dnp_keyword_policy",
            "statistics",
            "security",
        },
        blocker="remote_reader_workload_census_shape_invalid",
    )
    if census.get("schema_version") != REMOTE_READER_WORKLOAD_CENSUS_SCHEMA_VERSION:
        raise EvidenceError("remote_reader_workload_census_schema_invalid")
    census_at = _remote_soak_timestamp(
        census.get("observed_at"), f"{artifact}.census.observed_at"
    )
    source = _remote_soak_object(
        census.get("source"),
        field=f"{artifact}.census.source",
        keys={
            "component",
            "component_commit",
            "module",
            "module_sha256",
            "committed_match",
            "module_clean",
        },
        blocker="remote_reader_workload_census_source_invalid",
    )
    component_commit = _remote_soak_commit(
        source.get("component_commit"), f"{artifact}.census.source.component_commit"
    )
    module_sha256 = _sha256_digest(
        source.get("module_sha256"), f"{artifact}.census.source.module_sha256"
    )
    if (
        source.get("component") != "rca_issue_workload_export"
        or source.get("module") != REMOTE_READER_WORKLOAD_EXPORT_MODULE
        or source.get("committed_match") is not True
        or source.get("module_clean") is not True
        or component_commit != expected_host_commit
        or module_sha256 != expected_exporter_sha256
    ):
        raise EvidenceError("remote_reader_workload_census_source_mismatch")

    feishu = _remote_soak_object(
        census.get("feishu"),
        field=f"{artifact}.census.feishu",
        keys={
            "host",
            "authenticated",
            "project_key",
            "work_item_type",
            "selected_fields",
            "mutation_performed",
            "attachment_read_performed",
            "page_size",
            "page_count",
            "session_provenance",
        },
        blocker="remote_reader_workload_census_feishu_invalid",
    )
    if (
        feishu.get("host") != "project.feishu.cn"
        or feishu.get("authenticated") is not True
        or feishu.get("project_key") != "t03o4q"
        or feishu.get("work_item_type") != "issue"
        or feishu.get("selected_fields")
        != [
            "work_item_id",
            "name",
            "field_c7f370",
            "field_4bf24b",
            "field_e776bb",
            "field_93aa63",
        ]
        or feishu.get("mutation_performed") is not False
        or feishu.get("attachment_read_performed") is not False
    ):
        raise EvidenceError("remote_reader_workload_census_feishu_mismatch")
    page_size = _exact_int(
        feishu.get("page_size"), f"{artifact}.census.feishu.page_size", minimum=1
    )
    page_count = _exact_int(
        feishu.get("page_count"), f"{artifact}.census.feishu.page_count", minimum=1
    )
    if page_size > 50:
        raise EvidenceError("remote_reader_workload_census_page_size_invalid")
    sessions = feishu.get("session_provenance")
    if not isinstance(sessions, list) or len(sessions) != page_count:
        raise EvidenceError("remote_reader_workload_census_session_invalid")
    returned_total = 0
    expected_offset = 0
    observed_source_counts: set[int] = set()
    for index, raw_session in enumerate(sessions):
        session = _remote_soak_object(
            raw_session,
            field=f"{artifact}.census.feishu.session_provenance.{index}",
            keys={
                "offset",
                "requested",
                "returned",
                "observed_source_count",
                "query_sha256",
                "session_id_sha256",
            },
            blocker="remote_reader_workload_census_session_invalid",
        )
        offset = _exact_int(
            session.get("offset"),
            f"{artifact}.census.feishu.session_provenance.{index}.offset",
            minimum=0,
        )
        requested = _exact_int(
            session.get("requested"),
            f"{artifact}.census.feishu.session_provenance.{index}.requested",
            minimum=1,
        )
        returned = _exact_int(
            session.get("returned"),
            f"{artifact}.census.feishu.session_provenance.{index}.returned",
            minimum=1,
        )
        observed_count = _exact_int(
            session.get("observed_source_count"),
            (
                f"{artifact}.census.feishu.session_provenance.{index}."
                "observed_source_count"
            ),
            minimum=1,
        )
        _sha256_digest(
            session.get("query_sha256"),
            f"{artifact}.census.feishu.session_provenance.{index}.query_sha256",
        )
        _sha256_digest(
            session.get("session_id_sha256"),
            f"{artifact}.census.feishu.session_provenance.{index}.session_id_sha256",
        )
        if (
            offset != expected_offset
            or requested > page_size
            or returned > requested
            or (index < page_count - 1 and returned != requested)
        ):
            raise EvidenceError("remote_reader_workload_census_session_invalid")
        expected_offset += returned
        returned_total += returned
        observed_source_counts.add(observed_count)

    taxonomy = _remote_soak_object(
        census.get("taxonomy"),
        field=f"{artifact}.census.taxonomy",
        keys={
            "field_key",
            "field_name",
            "field_type",
            "options",
            "sha256",
            "leaf_count",
        },
        blocker="remote_reader_workload_taxonomy_invalid",
    )
    raw_options = taxonomy.get("options")
    if not isinstance(raw_options, list) or not raw_options:
        raise EvidenceError("remote_reader_workload_taxonomy_invalid")
    normalized_options: list[dict[str, list[str]]] = []
    option_identities: set[tuple[tuple[str, ...], tuple[str, ...]]] = set()
    option_paths: set[tuple[str, ...]] = set()
    for index, raw_option in enumerate(raw_options):
        option = _remote_soak_object(
            raw_option,
            field=f"{artifact}.census.taxonomy.options.{index}",
            keys={"option_ids", "option_path"},
            blocker="remote_reader_workload_taxonomy_invalid",
        )
        option_ids = option.get("option_ids")
        option_path = option.get("option_path")
        if (
            not isinstance(option_ids, list)
            or not isinstance(option_path, list)
            or not option_ids
            or len(option_ids) != len(option_path)
            or not all(isinstance(item, str) and item for item in option_ids)
            or not all(isinstance(item, str) and item for item in option_path)
        ):
            raise EvidenceError("remote_reader_workload_taxonomy_invalid")
        identity = (tuple(option_ids), tuple(option_path))
        if identity in option_identities or tuple(option_path) in option_paths:
            raise EvidenceError("remote_reader_workload_taxonomy_duplicate")
        option_identities.add(identity)
        option_paths.add(tuple(option_path))
        normalized_options.append(
            {"option_ids": list(option_ids), "option_path": list(option_path)}
        )
    if normalized_options != sorted(
        normalized_options, key=lambda item: (item["option_path"], item["option_ids"])
    ):
        raise EvidenceError("remote_reader_workload_taxonomy_order_invalid")
    taxonomy_material = {
        "field_key": "field_e776bb",
        "field_name": _required_text(
            taxonomy.get("field_name"), f"{artifact}.census.taxonomy.field_name"
        ),
        "field_type": "tree-select",
        "options": normalized_options,
    }
    taxonomy_sha256 = _sha256_digest(
        taxonomy.get("sha256"), f"{artifact}.census.taxonomy.sha256"
    )
    if (
        taxonomy.get("field_key") != "field_e776bb"
        or taxonomy.get("field_type") != "tree-select"
        or _exact_int(
            taxonomy.get("leaf_count"),
            f"{artifact}.census.taxonomy.leaf_count",
            minimum=1,
        )
        != len(normalized_options)
        or taxonomy_sha256 != _remote_soak_sha256(taxonomy_material)
    ):
        raise EvidenceError("remote_reader_workload_taxonomy_hash_mismatch")

    dnp_keyword_policy = _remote_soak_object(
        census.get("dnp_keyword_policy"),
        field=f"{artifact}.census.dnp_keyword_policy",
        keys={"field_keys", "keywords", "match_mode", "sha256"},
        blocker="remote_reader_workload_dnp_keyword_policy_invalid",
    )
    dnp_keyword_policy_material = {
        "field_keys": ["name", "field_c7f370", "field_4bf24b"],
        "keywords": ["规划", "SPP", "OOI"],
        "match_mode": "nfkc_casefold_cjk_substring_ascii_token",
    }
    if (
        {key: dnp_keyword_policy.get(key) for key in dnp_keyword_policy_material}
        != dnp_keyword_policy_material
        or dnp_keyword_policy.get("sha256")
        != _remote_soak_sha256(dnp_keyword_policy_material)
    ):
        raise EvidenceError("remote_reader_workload_dnp_keyword_policy_invalid")

    statistics = _remote_soak_object(
        census.get("statistics"),
        field=f"{artifact}.census.statistics",
        keys={
            "initial_source_count",
            "minimum_observed_source_count",
            "maximum_observed_source_count",
            "target_records",
            "records_seen",
            "source_scan_complete",
            "unique_work_items_seen",
            "valid_work_item_count",
            "valid_reference_candidate_count",
            "unique_reference_count",
            "duplicate_reference_candidate_count",
            "snapshot_stable",
            "categories",
            "reader_class_counts",
            "reference_kind_counts",
            "dnp_keyword_matches",
            "rejection_reasons",
        },
        blocker="remote_reader_workload_census_statistics_invalid",
    )
    source_count = _exact_int(
        statistics.get("initial_source_count"),
        f"{artifact}.census.statistics.initial_source_count",
        minimum=200,
    )
    records_seen = _exact_int(
        statistics.get("records_seen"),
        f"{artifact}.census.statistics.records_seen",
        minimum=200,
    )
    unique_seen = _exact_int(
        statistics.get("unique_work_items_seen"),
        f"{artifact}.census.statistics.unique_work_items_seen",
        minimum=200,
    )
    valid_work_items = _exact_int(
        statistics.get("valid_work_item_count"),
        f"{artifact}.census.statistics.valid_work_item_count",
        minimum=200,
    )
    reference_candidates = _exact_int(
        statistics.get("valid_reference_candidate_count"),
        f"{artifact}.census.statistics.valid_reference_candidate_count",
        minimum=200,
    )
    unique_references = _exact_int(
        statistics.get("unique_reference_count"),
        f"{artifact}.census.statistics.unique_reference_count",
        minimum=200,
    )
    duplicate_references = _exact_int(
        statistics.get("duplicate_reference_candidate_count"),
        f"{artifact}.census.statistics.duplicate_reference_candidate_count",
        minimum=0,
    )
    if (
        statistics.get("source_scan_complete") is not True
        or statistics.get("snapshot_stable") is not True
        or source_count != records_seen
        or source_count != unique_seen
        or source_count != returned_total
        or observed_source_counts != {source_count}
        or _exact_int(
            statistics.get("minimum_observed_source_count"),
            f"{artifact}.census.statistics.minimum_observed_source_count",
            minimum=200,
        )
        != source_count
        or _exact_int(
            statistics.get("maximum_observed_source_count"),
            f"{artifact}.census.statistics.maximum_observed_source_count",
            minimum=200,
        )
        != source_count
        or _exact_int(
            statistics.get("target_records"),
            f"{artifact}.census.statistics.target_records",
            minimum=200,
        )
        != source_count
        or valid_work_items > source_count
        or unique_references > reference_candidates
        or reference_candidates - unique_references != duplicate_references
    ):
        raise EvidenceError("remote_reader_workload_census_snapshot_invalid")
    reader_counts = _remote_soak_count_map(
        statistics.get("reader_class_counts"),
        f"{artifact}.census.statistics.reader_class_counts",
    )
    reference_kind_counts = _remote_soak_count_map(
        statistics.get("reference_kind_counts"),
        f"{artifact}.census.statistics.reference_kind_counts",
    )
    if (
        set(reader_counts) != {"RemoteClipReader", "RemoteEventReader"}
        or set(reference_kind_counts) != {"clip", "event"}
        or reader_counts["RemoteClipReader"] != reference_kind_counts["clip"]
        or reader_counts["RemoteEventReader"] != reference_kind_counts["event"]
        or sum(reader_counts.values()) != reference_candidates
    ):
        raise EvidenceError("remote_reader_workload_census_reader_counts_invalid")
    raw_categories = statistics.get("categories")
    if not isinstance(raw_categories, list) or not raw_categories:
        raise EvidenceError("remote_reader_workload_census_categories_invalid")
    normalized_category_paths: list[tuple[str, ...]] = []
    category_work_items = 0
    category_candidates = 0
    category_reader_totals: Counter[str] = Counter()
    category_dnp_candidates = 0
    category_candidate_counts: dict[tuple[str, ...], int] = {}
    category_dnp_candidate_counts: dict[tuple[str, ...], int] = {}
    for index, raw_category in enumerate(raw_categories):
        category = _remote_soak_object(
            raw_category,
            field=f"{artifact}.census.statistics.categories.{index}",
            keys={
                "option_path",
                "record_count",
                "valid_work_item_count",
                "valid_reference_candidate_count",
                "unique_reference_count",
                "duplicate_reference_candidate_count",
                "reader_class_counts",
                "dnp_keyword_reference_candidate_count",
            },
            blocker="remote_reader_workload_census_categories_invalid",
        )
        category_path = category.get("option_path")
        if (
            not isinstance(category_path, list)
            or not category_path
            or not all(isinstance(item, str) and item for item in category_path)
            or tuple(category_path) not in option_paths
            or tuple(category_path) in normalized_category_paths
        ):
            raise EvidenceError("remote_reader_workload_census_categories_invalid")
        normalized_category_paths.append(tuple(category_path))
        record_count = _exact_int(
            category.get("record_count"),
            f"{artifact}.census.statistics.categories.{index}.record_count",
            minimum=1,
        )
        category_valid = _exact_int(
            category.get("valid_work_item_count"),
            f"{artifact}.census.statistics.categories.{index}.valid_work_item_count",
            minimum=0,
        )
        category_candidate_count = _exact_int(
            category.get("valid_reference_candidate_count"),
            (
                f"{artifact}.census.statistics.categories.{index}."
                "valid_reference_candidate_count"
            ),
            minimum=0,
        )
        category_unique = _exact_int(
            category.get("unique_reference_count"),
            f"{artifact}.census.statistics.categories.{index}.unique_reference_count",
            minimum=0,
        )
        category_duplicate = _exact_int(
            category.get("duplicate_reference_candidate_count"),
            (
                f"{artifact}.census.statistics.categories.{index}."
                "duplicate_reference_candidate_count"
            ),
            minimum=0,
        )
        category_readers = _mapping(
            category.get("reader_class_counts"),
            f"{artifact}.census.statistics.categories.{index}.reader_class_counts",
        )
        normalized_category_readers = {
            str(name): _exact_int(
                count,
                (
                    f"{artifact}.census.statistics.categories.{index}."
                    f"reader_class_counts.{name}"
                ),
                minimum=1,
            )
            for name, count in category_readers.items()
        }
        category_dnp_count = _exact_int(
            category.get("dnp_keyword_reference_candidate_count"),
            (
                f"{artifact}.census.statistics.categories.{index}."
                "dnp_keyword_reference_candidate_count"
            ),
            minimum=0,
        )
        if (
            not set(normalized_category_readers).issubset(reader_counts)
            or category_valid > record_count
            or category_unique > category_candidate_count
            or category_candidate_count - category_unique != category_duplicate
            or sum(normalized_category_readers.values()) != category_candidate_count
            or category_dnp_count > category_candidate_count
        ):
            raise EvidenceError("remote_reader_workload_census_categories_invalid")
        category_work_items += category_valid
        category_candidates += category_candidate_count
        category_reader_totals.update(normalized_category_readers)
        category_dnp_candidates += category_dnp_count
        category_candidate_counts[tuple(category_path)] = category_candidate_count
        category_dnp_candidate_counts[tuple(category_path)] = category_dnp_count
    if (
        normalized_category_paths != sorted(normalized_category_paths)
        or category_work_items != valid_work_items
        or category_candidates != reference_candidates
        or dict(category_reader_totals) != reader_counts
    ):
        raise EvidenceError("remote_reader_workload_census_categories_invalid")
    dnp_keyword_matches = _remote_soak_object(
        statistics.get("dnp_keyword_matches"),
        field=f"{artifact}.census.statistics.dnp_keyword_matches",
        keys={
            "record_count",
            "valid_work_item_count",
            "reference_candidate_count",
            "keyword_record_counts",
            "keyword_valid_work_item_counts",
            "keyword_reference_candidate_counts",
            "rejection_reasons",
        },
        blocker="remote_reader_workload_dnp_keyword_counts_invalid",
    )
    dnp_count_maps: list[dict[str, int]] = []
    for name in (
        "keyword_record_counts",
        "keyword_valid_work_item_counts",
        "keyword_reference_candidate_counts",
    ):
        raw_count_map = _mapping(
            dnp_keyword_matches.get(name),
            f"{artifact}.census.statistics.dnp_keyword_matches.{name}",
        )
        if set(raw_count_map) != {"规划", "SPP", "OOI"}:
            raise EvidenceError("remote_reader_workload_dnp_keyword_counts_invalid")
        dnp_count_maps.append(
            {
                keyword: _exact_int(
                    raw_count_map.get(keyword),
                    (
                        f"{artifact}.census.statistics.dnp_keyword_matches."
                        f"{name}.{keyword}"
                    ),
                    minimum=0,
                )
                for keyword in ("规划", "SPP", "OOI")
            }
        )
    dnp_record_count = _exact_int(
        dnp_keyword_matches.get("record_count"),
        f"{artifact}.census.statistics.dnp_keyword_matches.record_count",
        minimum=50,
    )
    dnp_valid_count = _exact_int(
        dnp_keyword_matches.get("valid_work_item_count"),
        f"{artifact}.census.statistics.dnp_keyword_matches.valid_work_item_count",
        minimum=50,
    )
    dnp_candidate_count = _exact_int(
        dnp_keyword_matches.get("reference_candidate_count"),
        f"{artifact}.census.statistics.dnp_keyword_matches.reference_candidate_count",
        minimum=50,
    )
    _remote_soak_count_map(
        dnp_keyword_matches.get("rejection_reasons"),
        f"{artifact}.census.statistics.dnp_keyword_matches.rejection_reasons",
    )
    if (
        dnp_valid_count > dnp_record_count
        or dnp_candidate_count > reference_candidates
        or category_dnp_candidates != dnp_candidate_count
        or any(
            any(value > union for value in count_map.values())
            for count_map, union in zip(
                dnp_count_maps,
                (dnp_record_count, dnp_valid_count, dnp_candidate_count),
                strict=True,
            )
        )
    ):
        raise EvidenceError("remote_reader_workload_dnp_keyword_counts_invalid")
    _remote_soak_count_map(
        statistics.get("rejection_reasons"),
        f"{artifact}.census.statistics.rejection_reasons",
    )
    security = _remote_soak_object(
        census.get("security"),
        field=f"{artifact}.census.security",
        keys={
            "raw_issue_payload_persisted",
            "raw_pdcl_field_persisted",
            "raw_dnp_keyword_fields_persisted",
            "description_or_attachment_persisted",
            "credential_or_token_persisted",
            "input_materialized",
            "input_materialized_bytes",
        },
        blocker="remote_reader_workload_census_security_invalid",
    )
    if security != {
        "raw_issue_payload_persisted": False,
        "raw_pdcl_field_persisted": False,
        "raw_dnp_keyword_fields_persisted": False,
        "description_or_attachment_persisted": False,
        "credential_or_token_persisted": False,
        "input_materialized": False,
        "input_materialized_bytes": 0,
    }:
        raise EvidenceError("remote_reader_workload_census_security_invalid")

    mapping = _remote_soak_object(
        artifacts.get("mapping"),
        field=f"{artifact}.mapping",
        keys={
            "schema_version",
            "project_key",
            "work_item_type",
            "field_key",
            "taxonomy_sha256",
            "approval",
            "rules",
        },
        blocker="remote_reader_domain_mapping_shape_invalid",
    )
    if (
        mapping.get("schema_version") != REMOTE_READER_DOMAIN_MAPPING_SCHEMA_VERSION
        or mapping.get("project_key") != "t03o4q"
        or mapping.get("work_item_type") != "issue"
        or mapping.get("field_key") != "field_e776bb"
        or mapping.get("taxonomy_sha256") != taxonomy_sha256
    ):
        raise EvidenceError("remote_reader_domain_mapping_binding_mismatch")
    mapping_approval = _remote_soak_object(
        mapping.get("approval"),
        field=f"{artifact}.mapping.approval",
        keys={"authority", "approved_by", "approved_at", "receipt_sha256"},
        blocker="remote_reader_domain_mapping_approval_invalid",
    )
    approved_by = _required_text(
        mapping_approval.get("approved_by"), f"{artifact}.mapping.approval.approved_by"
    )
    if len(approved_by) > 128 or mapping_approval.get("authority") != "PDCL/data owner":
        raise EvidenceError("remote_reader_domain_mapping_approval_invalid")
    approved_at = _remote_soak_timestamp(
        mapping_approval.get("approved_at"), f"{artifact}.mapping.approval.approved_at"
    )
    approval_sha256 = _sha256_digest(
        mapping_approval.get("receipt_sha256"),
        f"{artifact}.mapping.approval.receipt_sha256",
    )
    raw_rules = mapping.get("rules")
    if not isinstance(raw_rules, list) or not raw_rules:
        raise EvidenceError("remote_reader_domain_mapping_rules_invalid")
    normalized_rules: list[dict[str, Any]] = []
    mapped_identities: set[tuple[tuple[str, ...], tuple[str, ...]]] = set()
    mapped_domains: set[str] = set()
    for index, raw_rule in enumerate(raw_rules):
        rule = _remote_soak_object(
            raw_rule,
            field=f"{artifact}.mapping.rules.{index}",
            keys={"function_domain", "option_ids", "option_path"},
            blocker="remote_reader_domain_mapping_rules_invalid",
        )
        domain = _required_text(
            rule.get("function_domain"), f"{artifact}.mapping.rules.{index}.function_domain"
        )
        option_ids = rule.get("option_ids")
        option_path = rule.get("option_path")
        if (
            domain not in {"ACC", "LCC", "AEB", "FCW"}
            or not isinstance(option_ids, list)
            or not isinstance(option_path, list)
            or not option_ids
            or len(option_ids) != len(option_path)
            or not all(isinstance(item, str) and item for item in option_ids)
            or not all(isinstance(item, str) and item for item in option_path)
        ):
            raise EvidenceError("remote_reader_domain_mapping_rules_invalid")
        identity = (tuple(option_ids), tuple(option_path))
        if identity not in option_identities or identity in mapped_identities:
            raise EvidenceError("remote_reader_domain_mapping_rules_invalid")
        mapped_identities.add(identity)
        mapped_domains.add(domain)
        normalized_rules.append(
            {
                "function_domain": domain,
                "option_ids": list(option_ids),
                "option_path": list(option_path),
            }
        )
    if (
        not {"ACC", "LCC"}.issubset(mapped_domains)
        or not mapped_domains.intersection({"AEB", "FCW"})
        or normalized_rules != raw_rules
    ):
        raise EvidenceError("remote_reader_domain_mapping_quota_coverage_missing")
    mapping_rules_material = {
        "schema_version": mapping["schema_version"],
        "project_key": mapping["project_key"],
        "work_item_type": mapping["work_item_type"],
        "field_key": mapping["field_key"],
        "taxonomy_sha256": mapping["taxonomy_sha256"],
        "rules": normalized_rules,
    }
    mapping_rules_sha256 = _remote_soak_sha256(mapping_rules_material)
    mapped_option_paths = {identity[1] for identity in mapped_identities}

    approval = _remote_soak_object(
        artifacts.get("approval"),
        field=f"{artifact}.approval",
        keys={
            "schema_version",
            "authority",
            "approved_by",
            "approved_at",
            "mapping_rules_sha256",
        },
        blocker="remote_reader_domain_mapping_approval_shape_invalid",
    )
    if (
        approval.get("schema_version")
        != REMOTE_READER_DOMAIN_MAPPING_APPROVAL_SCHEMA_VERSION
        or approval.get("authority") != mapping_approval.get("authority")
        or approval.get("approved_by") != approved_by
        or approval.get("approved_at") != mapping_approval.get("approved_at")
        or approval.get("mapping_rules_sha256") != mapping_rules_sha256
        or evidence_hashes.get(REMOTE_READER_DOMAIN_MAPPING_APPROVAL_FILENAME)
        != approval_sha256
        or census_at > approved_at
    ):
        raise EvidenceError("remote_reader_domain_mapping_approval_mismatch")

    receipt = _remote_soak_object(
        artifacts.get("receipt"),
        field=f"{artifact}.receipt",
        keys={
            "schema_version",
            "generated_at",
            "source",
            "census",
            "taxonomy_sha256",
            "dnp_keyword_policy",
            "mapping",
            "selection",
            "manifest",
            "security",
        },
        blocker="remote_reader_workload_export_receipt_shape_invalid",
    )
    if (
        receipt.get("schema_version")
        != REMOTE_READER_WORKLOAD_EXPORT_RECEIPT_SCHEMA_VERSION
        or receipt.get("source") != source
        or receipt.get("taxonomy_sha256") != taxonomy_sha256
        or receipt.get("dnp_keyword_policy") != dnp_keyword_policy
        or receipt.get("security") != security
    ):
        raise EvidenceError("remote_reader_workload_export_receipt_mismatch")
    receipt_at = _remote_soak_timestamp(
        receipt.get("generated_at"), f"{artifact}.receipt.generated_at"
    )
    if approved_at > receipt_at:
        raise EvidenceError("remote_reader_workload_export_receipt_timestamp_invalid")
    receipt_census = _remote_soak_object(
        receipt.get("census"),
        field=f"{artifact}.receipt.census",
        keys={"body_sha256", "file_sha256"},
        blocker="remote_reader_workload_export_receipt_census_invalid",
    )
    if (
        receipt_census.get("body_sha256") != _remote_soak_sha256(census)
        or receipt_census.get("file_sha256")
        != evidence_hashes.get(REMOTE_READER_WORKLOAD_CENSUS_FILENAME)
    ):
        raise EvidenceError("remote_reader_workload_export_receipt_census_mismatch")
    receipt_mapping = _remote_soak_object(
        receipt.get("mapping"),
        field=f"{artifact}.receipt.mapping",
        keys={"artifact_sha256", "rules_material_sha256", "approval"},
        blocker="remote_reader_workload_export_receipt_mapping_invalid",
    )
    if (
        receipt_mapping.get("artifact_sha256")
        != evidence_hashes.get(REMOTE_READER_DOMAIN_MAPPING_FILENAME)
        or receipt_mapping.get("rules_material_sha256") != mapping_rules_sha256
        or receipt_mapping.get("approval") != mapping_approval
    ):
        raise EvidenceError("remote_reader_workload_export_receipt_mapping_mismatch")

    manifest = _mapping(workload_manifest, f"{artifact}.manifest")
    manifest_source = _mapping(manifest.get("source"), f"{artifact}.manifest.source")
    manifest_at = _remote_soak_timestamp(
        manifest.get("generated_at"), f"{artifact}.manifest.generated_at"
    )
    if (
        manifest_at != receipt_at
        or manifest_source.get("component_commit") != component_commit
        or manifest_source.get("artifact_sha256") != module_sha256
    ):
        raise EvidenceError("remote_reader_workload_manifest_source_mismatch")
    receipt_manifest = _remote_soak_object(
        receipt.get("manifest"),
        field=f"{artifact}.receipt.manifest",
        keys={"schema_version", "body_sha256", "file_sha256", "case_count"},
        blocker="remote_reader_workload_export_receipt_manifest_invalid",
    )
    manifest_cases = manifest.get("cases")
    if not isinstance(manifest_cases, list):
        raise EvidenceError("remote_reader_workload_export_receipt_manifest_invalid")
    if (
        receipt_manifest.get("schema_version") != REMOTE_READER_SOAK_MANIFEST_SCHEMA_VERSION
        or receipt_manifest.get("body_sha256") != _remote_soak_sha256(manifest)
        or receipt_manifest.get("file_sha256")
        != evidence_hashes.get(REMOTE_READER_SOAK_MANIFEST_FILENAME)
        or _exact_int(
            receipt_manifest.get("case_count"),
            f"{artifact}.receipt.manifest.case_count",
            minimum=200,
        )
        != len(manifest_cases)
    ):
        raise EvidenceError("remote_reader_workload_export_receipt_manifest_mismatch")

    selected_domain_counts: Counter[str] = Counter()
    selected_reader_counts: Counter[str] = Counter()
    selected_work_items: set[str] = set()
    selected_references: set[tuple[str, str]] = set()
    for index, raw_case in enumerate(manifest_cases):
        case = _mapping(raw_case, f"{artifact}.manifest.cases.{index}")
        work_item_id = _remote_soak_identifier(
            case.get("work_item_id"), f"{artifact}.manifest.cases.{index}.work_item_id"
        )
        function_domain = _required_text(
            case.get("function_domain"),
            f"{artifact}.manifest.cases.{index}.function_domain",
        )
        quota_domain = "AEB_FCW" if function_domain in {"AEB", "FCW"} else function_domain
        access = _mapping(
            case.get("data_access"), f"{artifact}.manifest.cases.{index}.data_access"
        )
        references = access.get("references")
        if not isinstance(references, list) or len(references) != 1:
            raise EvidenceError("remote_reader_workload_export_receipt_selection_invalid")
        reference = _mapping(
            references[0], f"{artifact}.manifest.cases.{index}.reference"
        )
        kind = str(reference.get("kind") or "")
        locator_field = "clip_uuid" if kind == "clip" else "event_uuid" if kind == "event" else ""
        locator = str(reference.get(locator_field) or "") if locator_field else ""
        reader_class = str(reference.get("reader_class") or "")
        if (
            quota_domain not in REMOTE_READER_SOAK_DOMAIN_QUOTAS
            or function_domain not in mapped_domains | {"DNP"}
            or reader_class not in REMOTE_READER_SOAK_READER_QUOTAS
            or not locator
            or reader_class
            != (
                "RemoteClipReader" if kind == "clip" else "RemoteEventReader"
            )
            or work_item_id in selected_work_items
            or (kind, locator) in selected_references
        ):
            raise EvidenceError("remote_reader_workload_export_receipt_selection_invalid")
        selected_work_items.add(work_item_id)
        selected_references.add((kind, locator))
        selected_domain_counts[quota_domain] += 1
        selected_reader_counts[reader_class] += 1
    selection = _remote_soak_object(
        receipt.get("selection"),
        field=f"{artifact}.receipt.selection",
        keys={
            "eligible_reference_candidates",
            "dnp_keyword_reference_candidates",
            "dnp_keyword_selected_cases",
            "unmapped_category_counts",
            "case_count",
            "unique_work_items",
            "unique_references",
            "domain_counts",
            "reader_class_counts",
        },
        blocker="remote_reader_workload_export_receipt_selection_invalid",
    )
    eligible_candidates = _exact_int(
        selection.get("eligible_reference_candidates"),
        f"{artifact}.receipt.selection.eligible_reference_candidates",
        minimum=200,
    )
    expected_eligible_candidates = sum(
        (
            count
            if path in mapped_option_paths
            else category_dnp_candidate_counts[path]
        )
        for path, count in category_candidate_counts.items()
    )
    if eligible_candidates != expected_eligible_candidates:
        raise EvidenceError("remote_reader_workload_export_receipt_selection_invalid")
    unmapped = selection.get("unmapped_category_counts")
    if not isinstance(unmapped, list):
        raise EvidenceError("remote_reader_workload_export_receipt_selection_invalid")
    normalized_unmapped: list[dict[str, Any]] = []
    for index, raw_item in enumerate(unmapped):
        item = _remote_soak_object(
            raw_item,
            field=f"{artifact}.receipt.selection.unmapped_category_counts.{index}",
            keys={"option_path", "reference_count"},
            blocker="remote_reader_workload_export_receipt_selection_invalid",
        )
        option_path = item.get("option_path")
        if (
            not isinstance(option_path, list)
            or tuple(option_path) not in option_paths
        ):
            raise EvidenceError("remote_reader_workload_export_receipt_selection_invalid")
        reference_count = _exact_int(
            item.get("reference_count"),
            f"{artifact}.receipt.selection.unmapped_category_counts.{index}.reference_count",
            minimum=1,
        )
        normalized_unmapped.append(
            {"option_path": list(option_path), "reference_count": reference_count}
        )
    expected_unmapped = [
        {
            "option_path": list(path),
            "reference_count": count - category_dnp_candidate_counts[path],
        }
        for path, count in sorted(category_candidate_counts.items())
        if path not in mapped_option_paths
        and count - category_dnp_candidate_counts[path] > 0
    ]
    if normalized_unmapped != expected_unmapped:
        raise EvidenceError("remote_reader_workload_export_receipt_selection_invalid")
    if (
        _exact_int(
            selection.get("dnp_keyword_reference_candidates"),
            f"{artifact}.receipt.selection.dnp_keyword_reference_candidates",
            minimum=50,
        )
        != dnp_candidate_count
        or _exact_int(
            selection.get("dnp_keyword_selected_cases"),
            f"{artifact}.receipt.selection.dnp_keyword_selected_cases",
            minimum=50,
        )
        != selected_domain_counts["DNP"]
        or _exact_int(
            selection.get("case_count"),
            f"{artifact}.receipt.selection.case_count",
            minimum=200,
        )
        != len(manifest_cases)
        or _exact_int(
            selection.get("unique_work_items"),
            f"{artifact}.receipt.selection.unique_work_items",
            minimum=200,
        )
        != len(selected_work_items)
        or _exact_int(
            selection.get("unique_references"),
            f"{artifact}.receipt.selection.unique_references",
            minimum=200,
        )
        != len(selected_references)
        or _remote_soak_count_map(
            selection.get("domain_counts"),
            f"{artifact}.receipt.selection.domain_counts",
        )
        != dict(sorted(selected_domain_counts.items()))
        or _remote_soak_count_map(
            selection.get("reader_class_counts"),
            f"{artifact}.receipt.selection.reader_class_counts",
        )
        != dict(sorted(selected_reader_counts.items()))
        or dict(selected_domain_counts) != REMOTE_READER_SOAK_DOMAIN_QUOTAS
        or any(
            selected_reader_counts[name] < count
            for name, count in REMOTE_READER_SOAK_READER_QUOTAS.items()
        )
    ):
        raise EvidenceError("remote_reader_workload_export_receipt_selection_mismatch")
    return {
        "exporter_commit": component_commit,
        "exporter_module_sha256": module_sha256,
        "census_file_sha256": evidence_hashes[
            REMOTE_READER_WORKLOAD_CENSUS_FILENAME
        ],
        "taxonomy_sha256": taxonomy_sha256,
        "mapping_file_sha256": evidence_hashes[
            REMOTE_READER_DOMAIN_MAPPING_FILENAME
        ],
        "mapping_rules_sha256": mapping_rules_sha256,
        "approval_receipt_sha256": approval_sha256,
        "approved_by": approved_by,
        "manifest_sha256": _remote_soak_sha256(manifest),
        "case_count": len(manifest_cases),
        "source_record_count": source_count,
        "unique_source_references": unique_references,
    }


def _check_kafka_e2e_frame_census(
    *,
    path_value: str,
    expected_sha256: str,
    manifest_task_id: str,
    expected_work_item_ids: Sequence[str],
    replay_observed_at: datetime,
) -> dict[str, Any]:
    blocker = "kafka_recent_replay_e2e_frame_census_invalid"
    path = Path(path_value).expanduser().absolute()
    try:
        raw, census = _load_owner_only_json(
            path,
            artifact="kafka_recent_replay_e2e_frame_census",
        )
    except (EvidenceError, OSError, ValueError) as exc:
        raise EvidenceError(blocker) from exc
    if (
        hashlib.sha256(raw).hexdigest() != expected_sha256
        or set(census)
        != {
            "schema_version",
            "generated_at",
            "task_id",
            "source",
            "summary",
            "records",
            "contains_raw_field_values",
            "contains_credentials",
            "mutation_performed",
        }
        or census.get("schema_version")
        != KAFKA_FEISHU_FRAME_CENSUS_SCHEMA_VERSION
        or census.get("task_id") != manifest_task_id
        or census.get("contains_raw_field_values") is not False
        or census.get("contains_credentials") is not False
        or census.get("mutation_performed") is not False
        or _timestamp(census.get("generated_at"), f"{blocker}.generated_at")
        > replay_observed_at
    ):
        raise EvidenceError(blocker)
    source = _remote_soak_object(
        census.get("source"),
        field=f"{blocker}.source",
        keys={
            "kind",
            "project_key",
            "work_item_type_key",
            "selected_field_keys",
        },
        blocker=blocker,
    )
    if source != {
        "kind": "official_meegle_read_only",
        "project_key": "t03o4q",
        "work_item_type_key": "issue",
        "selected_field_keys": [
            "field_1fda45",
            "field_9193cb",
            "field_8c912e",
        ],
    }:
        raise EvidenceError(blocker)

    expected_count = len(expected_work_item_ids)
    summary = _remote_soak_object(
        census.get("summary"),
        field=f"{blocker}.summary",
        keys={
            "expected_work_items",
            "observed_work_items",
            "fetch_status_counts",
            "frame_reference_kind_counts",
            "result_field_nonempty_count",
            "report_field_nonempty_count",
        },
        blocker=blocker,
    )
    records = census.get("records")
    if not isinstance(records, list) or len(records) != expected_count:
        raise EvidenceError(blocker)
    observed_ids: list[str] = []
    kind_counts: Counter[str] = Counter()
    result_count = 0
    report_count = 0
    for index, raw_record in enumerate(records):
        record = _mapping(raw_record, f"{blocker}.records.{index}")
        base_keys = {
            "work_item_id",
            "fetch_status",
            "frame_field_present",
            "result_field_present",
            "report_field_present",
            "frame_value_sha256",
            "frame_reference_kind",
        }
        kind = record.get("frame_reference_kind")
        if kind == "frame_id":
            expected_keys = base_keys | {"frame_id"}
        elif kind == "front_camera_timestamp":
            expected_keys = base_keys | {
                "management_timestamp",
                "management_timestamp_unit",
                "timezone",
                "max_delta_us",
            }
        else:
            raise EvidenceError(blocker)
        if set(record) != expected_keys:
            raise EvidenceError(blocker)
        work_item_id = _required_text(
            record.get("work_item_id"),
            f"{blocker}.records.{index}.work_item_id",
        )
        if (
            not work_item_id.isdigit()
            or int(work_item_id) <= 0
            or record.get("fetch_status") != "ok"
            or record.get("frame_field_present") is not True
            or not isinstance(record.get("result_field_present"), bool)
            or not isinstance(record.get("report_field_present"), bool)
        ):
            raise EvidenceError(blocker)
        _sha256_digest(
            record.get("frame_value_sha256"),
            f"{blocker}.records.{index}.frame_value_sha256",
        )
        if kind == "frame_id":
            frame_id = _required_text(
                record.get("frame_id"),
                f"{blocker}.records.{index}.frame_id",
            )
            if not frame_id.isdigit() or int(frame_id) <= 0:
                raise EvidenceError(blocker)
        elif (
            _exact_int(
                record.get("management_timestamp"),
                f"{blocker}.records.{index}.management_timestamp",
                minimum=1,
            )
            < 946_684_800_000_000
            or record.get("management_timestamp_unit")
            != "microseconds_since_unix_epoch"
            or record.get("timezone") != "Asia/Shanghai"
            or _exact_int(
                record.get("max_delta_us"),
                f"{blocker}.records.{index}.max_delta_us",
                minimum=1,
            )
            != 100_000
        ):
            raise EvidenceError(blocker)
        observed_ids.append(work_item_id)
        kind_counts[kind] += 1
        result_count += int(record["result_field_present"])
        report_count += int(record["report_field_present"])
    if (
        sorted(observed_ids, key=int) != list(expected_work_item_ids)
        or summary.get("expected_work_items") != expected_count
        or summary.get("observed_work_items") != expected_count
        or summary.get("fetch_status_counts") != {"ok": expected_count}
        or summary.get("frame_reference_kind_counts")
        != dict(sorted(kind_counts.items()))
        or summary.get("result_field_nonempty_count") != result_count
        or summary.get("report_field_nonempty_count") != report_count
    ):
        raise EvidenceError(blocker)
    return {
        "frame_census_sha256": expected_sha256,
        "frame_reference_parseable": expected_count,
        "frame_reference_kind_counts": dict(sorted(kind_counts.items())),
    }


def _check_kafka_e2e_feishu_source(
    *,
    manifest_task_id: str,
    source: Mapping[str, str],
    expected_work_item_ids: Sequence[str],
    window_started_at: datetime,
    replay_observed_at: datetime,
) -> dict[str, Any]:
    blocker = "kafka_recent_replay_e2e_source_invalid"
    receipt_path = Path(source["feishu_receipt_path"]).expanduser().absolute()
    try:
        raw_receipt, receipt = _load_owner_only_json(
            receipt_path,
            artifact="kafka_recent_replay_e2e_feishu_receipt",
        )
    except (EvidenceError, OSError, ValueError) as exc:
        raise EvidenceError(blocker) from exc
    if (
        hashlib.sha256(raw_receipt).hexdigest()
        != source["feishu_receipt_sha256"]
        or set(receipt)
        != {
            "schema_version",
            "observed_at",
            "task_id",
            "source_class",
            "official_source",
            "user_evidence",
            "result",
            "privacy",
            "side_effects",
        }
        or receipt.get("schema_version")
        != KAFKA_FEISHU_E2E_RECEIPT_SCHEMA_VERSION
        or receipt.get("task_id") != manifest_task_id
        or receipt.get("source_class") != "live_observation"
    ):
        raise EvidenceError(blocker)
    receipt_observed_at = _timestamp(
        receipt.get("observed_at"), f"{blocker}.observed_at"
    )
    if not window_started_at <= receipt_observed_at <= replay_observed_at:
        raise EvidenceError(blocker)

    official = _remote_soak_object(
        receipt.get("official_source"),
        field=f"{blocker}.official_source",
        keys={
            "client",
            "project_key",
            "project_simple_name",
            "work_item_type_key",
            "status_key",
            "source_type",
            "plugin_source",
            "operation_type",
            "op_record_module",
        },
        blocker=blocker,
    )
    if official != {
        "client": "meegle",
        "project_key": source["project_key"],
        "project_simple_name": source["project_simple_name"],
        "work_item_type_key": source["work_item_type_key"],
        "status_key": "OPEN",
        "source_type": "plugin",
        "plugin_source": source["feishu_plugin_source"],
        "operation_type": "create",
        "op_record_module": "work_item_mod",
    }:
        raise EvidenceError(blocker)

    privacy = _remote_soak_object(
        receipt.get("privacy"),
        field=f"{blocker}.privacy",
        keys={
            "credential_persisted",
            "person_identity_persisted",
            "raw_frame_reference_persisted",
            "raw_pdcl_reference_persisted",
            "raw_title_persisted",
        },
        blocker=blocker,
    )
    side_effects = _remote_soak_object(
        receipt.get("side_effects"),
        field=f"{blocker}.side_effects",
        keys={"feishu_write", "kafka_read", "production_mutation"},
        blocker=blocker,
    )
    if privacy != {
        "credential_persisted": False,
        "person_identity_persisted": False,
        "raw_frame_reference_persisted": False,
        "raw_pdcl_reference_persisted": False,
        "raw_title_persisted": False,
    } or side_effects != {
        "feishu_write": False,
        "kafka_read": False,
        "production_mutation": False,
    }:
        raise EvidenceError(blocker)

    user_evidence = _remote_soak_object(
        receipt.get("user_evidence"),
        field=f"{blocker}.user_evidence",
        keys={"screenshot_path", "screenshot_sha256"},
        blocker=blocker,
    )
    screenshot_sha256 = _sha256_digest(
        user_evidence.get("screenshot_sha256"),
        f"{blocker}.user_evidence.screenshot_sha256",
    )
    screenshot_path = Path(
        _required_text(
            user_evidence.get("screenshot_path"),
            f"{blocker}.user_evidence.screenshot_path",
        )
    ).expanduser().absolute()
    try:
        raw_screenshot, screenshot_info = _stable_regular_file_observation(
            screenshot_path,
            artifact="kafka_recent_replay_e2e_screenshot",
            require_owner=True,
        )
    except (EvidenceError, OSError, ValueError) as exc:
        raise EvidenceError(blocker) from exc
    if (
        screenshot_sha256 != source["screenshot_sha256"]
        or hashlib.sha256(raw_screenshot).hexdigest() != screenshot_sha256
        or stat.S_IMODE(screenshot_info.st_mode) & 0o022
    ):
        raise EvidenceError(blocker)

    result = _remote_soak_object(
        receipt.get("result"),
        field=f"{blocker}.result",
        keys={
            "expected",
            "work_items_found",
            "pdcl_field_present",
            "function_field_present",
            "frame_field_present",
            "frame_reference_parseable",
            "frame_census_path",
            "frame_census_sha256",
            "creation_records_found",
            "all_exactly_one_creation_record",
            "all_identity_fields_match",
            "items",
        },
        blocker=blocker,
    )
    expected_count = len(expected_work_item_ids)
    if (
        any(
            _exact_int(result.get(name), f"{blocker}.result.{name}", minimum=1)
            != expected_count
            for name in (
                "expected",
                "work_items_found",
                "pdcl_field_present",
                "function_field_present",
                "frame_field_present",
                "frame_reference_parseable",
                "creation_records_found",
            )
        )
        or result.get("all_exactly_one_creation_record") is not True
        or result.get("all_identity_fields_match") is not True
    ):
        raise EvidenceError(blocker)
    raw_items = result.get("items")
    if not isinstance(raw_items, list) or len(raw_items) != expected_count:
        raise EvidenceError(blocker)
    observed_work_item_ids: list[str] = []
    for index, raw_item in enumerate(raw_items):
        item = _remote_soak_object(
            raw_item,
            field=f"{blocker}.result.items.{index}",
            keys={"work_item_id", "create_time", "operation_time_ms"},
            blocker=blocker,
        )
        work_item_id = _required_text(
            item.get("work_item_id"),
            f"{blocker}.result.items.{index}.work_item_id",
        )
        if not work_item_id.isdigit() or int(work_item_id) <= 0:
            raise EvidenceError(blocker)
        created_at = _timestamp(
            item.get("create_time"),
            f"{blocker}.result.items.{index}.create_time",
        )
        operation_time_ms = _exact_int(
            item.get("operation_time_ms"),
            f"{blocker}.result.items.{index}.operation_time_ms",
            minimum=1,
        )
        operation_at = datetime.fromtimestamp(
            operation_time_ms / 1000,
            tz=timezone.utc,
        )
        if (
            not window_started_at <= created_at <= replay_observed_at
            or not window_started_at <= operation_at <= replay_observed_at
            or abs((created_at - operation_at).total_seconds()) > 5
        ):
            raise EvidenceError(blocker)
        observed_work_item_ids.append(work_item_id)
    if sorted(observed_work_item_ids, key=int) != list(expected_work_item_ids):
        raise EvidenceError(blocker)
    frame_census_path = _required_text(
        result.get("frame_census_path"),
        f"{blocker}.result.frame_census_path",
    )
    if not Path(frame_census_path).expanduser().is_absolute():
        raise EvidenceError(blocker)
    frame_census_sha256 = _sha256_digest(
        result.get("frame_census_sha256"),
        f"{blocker}.result.frame_census_sha256",
    )
    frame_census = _check_kafka_e2e_frame_census(
        path_value=frame_census_path,
        expected_sha256=frame_census_sha256,
        manifest_task_id=manifest_task_id,
        expected_work_item_ids=expected_work_item_ids,
        replay_observed_at=replay_observed_at,
    )
    return {
        "feishu_receipt_sha256": source["feishu_receipt_sha256"],
        "screenshot_sha256": screenshot_sha256,
        "verified_work_item_count": expected_count,
        **frame_census,
    }


def _check_kafka_recent_replay(
    body: Mapping[str, Any],
    *,
    consumer: ConsumerConfig,
    kafka_env_file: Path,
    expected_partitions: Sequence[int],
    expected_host_commit: str,
    expected_module_sha256: str,
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    artifact = "kafka_recent_replay"
    _require_schema(body, KAFKA_RECENT_REPLAY_SCHEMA_VERSION, artifact)
    if set(body) != {
        "schema_version",
        "observed_at",
        "source",
        "config",
        "window",
        "limits",
        "transport",
        "result",
    }:
        raise EvidenceError("kafka_recent_replay_shape_invalid")
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    source = _remote_soak_object(
        body.get("source"),
        field=f"{artifact}.source",
        keys={
            "component",
            "component_commit",
            "module",
            "module_sha256",
            "committed_match",
            "module_clean",
        },
        blocker="kafka_recent_replay_source_invalid",
    )
    if (
        source.get("component") != "pnc_rca_kafka_recent_replay"
        or source.get("component_commit") != expected_host_commit
        or source.get("module") != KAFKA_RECENT_REPLAY_MODULE
        or source.get("module_sha256") != expected_module_sha256
        or source.get("committed_match") is not True
        or source.get("module_clean") is not True
    ):
        raise EvidenceError("kafka_recent_replay_source_mismatch")

    config = _remote_soak_object(
        body.get("config"),
        field=f"{artifact}.config",
        keys={"topic", "cluster_binding", "policy_sha256"},
        blocker="kafka_recent_replay_config_invalid",
    )
    cluster_binding = _remote_soak_object(
        config.get("cluster_binding"),
        field=f"{artifact}.config.cluster_binding",
        keys={
            "bootstrap_servers_sha256",
            "principal_sha256",
            "env_file",
        },
        blocker="kafka_recent_replay_config_invalid",
    )
    try:
        _env, expected_env_observation = load_kafka_preflight_environment(
            kafka_env_file
        )
    except (OSError, ValueError) as exc:
        raise EvidenceError("kafka_recent_replay_env_unavailable") from exc
    if (
        config.get("topic") != consumer.topic
        or config.get("policy_sha256") != _sha256_json(consumer.policy.to_dict())
        or cluster_binding.get("bootstrap_servers_sha256")
        != _sha256_json(list(consumer.bootstrap_servers))
        or cluster_binding.get("principal_sha256") != _sha256_json(consumer.username)
        or cluster_binding.get("env_file") != expected_env_observation
    ):
        raise EvidenceError("kafka_recent_replay_config_mismatch")

    window = _remote_soak_object(
        body.get("window"),
        field=f"{artifact}.window",
        keys={
            "days",
            "started_at",
            "ended_at",
            "start_timestamp_ms",
            "partitions",
        },
        blocker="kafka_recent_replay_window_invalid",
    )
    started_at = _timestamp(window.get("started_at"), f"{artifact}.window.started_at")
    ended_at = _timestamp(window.get("ended_at"), f"{artifact}.window.ended_at")
    observed = _timestamp(body.get("observed_at"), f"{artifact}.observed_at")
    if (
        _exact_int(window.get("days"), f"{artifact}.window.days", minimum=7) != 7
        or ended_at != observed
        or ended_at - started_at != timedelta(days=7)
        or _exact_int(
            window.get("start_timestamp_ms"),
            f"{artifact}.window.start_timestamp_ms",
            minimum=1,
        )
        != int(started_at.timestamp() * 1000)
    ):
        raise EvidenceError("kafka_recent_replay_window_invalid")
    raw_partitions = window.get("partitions")
    if not isinstance(raw_partitions, list):
        raise EvidenceError("kafka_recent_replay_partitions_invalid")
    expected_partition_list = sorted(int(value) for value in expected_partitions)
    partition_records = 0
    normalized_partitions: list[int] = []
    for index, raw_partition in enumerate(raw_partitions):
        partition = _remote_soak_object(
            raw_partition,
            field=f"{artifact}.window.partitions.{index}",
            keys={
                "partition",
                "beginning_offset",
                "window_start_offset",
                "fixed_end_offset",
                "records_scanned",
            },
            blocker="kafka_recent_replay_partitions_invalid",
        )
        partition_id = _exact_int(
            partition.get("partition"),
            f"{artifact}.window.partitions.{index}.partition",
            minimum=0,
        )
        beginning = _exact_int(
            partition.get("beginning_offset"),
            f"{artifact}.window.partitions.{index}.beginning_offset",
            minimum=0,
        )
        start = _exact_int(
            partition.get("window_start_offset"),
            f"{artifact}.window.partitions.{index}.window_start_offset",
            minimum=0,
        )
        end = _exact_int(
            partition.get("fixed_end_offset"),
            f"{artifact}.window.partitions.{index}.fixed_end_offset",
            minimum=0,
        )
        count = _exact_int(
            partition.get("records_scanned"),
            f"{artifact}.window.partitions.{index}.records_scanned",
            minimum=0,
        )
        if beginning > start or start > end or count > end - start:
            raise EvidenceError("kafka_recent_replay_partitions_invalid")
        normalized_partitions.append(partition_id)
        partition_records += count
    if normalized_partitions != expected_partition_list:
        raise EvidenceError("kafka_recent_replay_partition_coverage_mismatch")

    limits = _remote_soak_object(
        body.get("limits"),
        field=f"{artifact}.limits",
        keys={"max_messages", "max_bytes", "max_seconds"},
        blocker="kafka_recent_replay_limits_invalid",
    )
    max_messages = _exact_int(
        limits.get("max_messages"), f"{artifact}.limits.max_messages", minimum=1
    )
    max_bytes = _exact_int(
        limits.get("max_bytes"), f"{artifact}.limits.max_bytes", minimum=1
    )
    max_seconds = _exact_int(
        limits.get("max_seconds"), f"{artifact}.limits.max_seconds", minimum=1
    )
    if max_messages > 10_000 or max_bytes > 128 * 1024 * 1024 or max_seconds > 300:
        raise EvidenceError("kafka_recent_replay_limits_invalid")
    transport = body.get("transport")
    if not isinstance(transport, Mapping) or set(transport) != {
        "assignment",
        "group_id",
        "subscribed",
        "group_joined",
        "enable_auto_commit",
        "commit_performed",
        "allow_auto_create_topics",
        "isolation_level",
        "request_timeout_ms",
        "bootstrap_timeout_ms",
    }:
        raise EvidenceError("kafka_recent_replay_transport_invalid")
    bounded_request_timeout = _exact_int(
        transport.get("request_timeout_ms"),
        f"{artifact}.transport.request_timeout_ms",
        minimum=1,
    )
    bounded_bootstrap_timeout = _exact_int(
        transport.get("bootstrap_timeout_ms"),
        f"{artifact}.transport.bootstrap_timeout_ms",
        minimum=1,
    )
    if {
        key: value
        for key, value in transport.items()
        if key not in {"request_timeout_ms", "bootstrap_timeout_ms"}
    } != {
        "assignment": "explicit",
        "group_id": None,
        "subscribed": False,
        "group_joined": False,
        "enable_auto_commit": False,
        "commit_performed": False,
        "allow_auto_create_topics": False,
        "isolation_level": "read_committed",
    } or not (
        bounded_request_timeout <= 5_000
        and bounded_bootstrap_timeout == bounded_request_timeout
    ):
        raise EvidenceError("kafka_recent_replay_transport_invalid")

    result = _remote_soak_object(
        body.get("result"),
        field=f"{artifact}.result",
        keys={
            "stop_reason",
            "records_scanned",
            "raw_bytes_scanned",
            "decision_counts",
            "reason_counts",
            "records",
            "shadow_store",
            "production_mutation_performed",
            "raw_payload_persisted_to_output",
            "temporary_store_destroyed",
            "e2e_canary",
        },
        blocker="kafka_recent_replay_result_invalid",
    )
    records_scanned = _exact_int(
        result.get("records_scanned"),
        f"{artifact}.result.records_scanned",
        minimum=1,
    )
    raw_bytes = _exact_int(
        result.get("raw_bytes_scanned"),
        f"{artifact}.result.raw_bytes_scanned",
        minimum=1,
    )
    if (
        records_scanned > max_messages
        or raw_bytes > max_bytes
        or records_scanned != partition_records
        or result.get("stop_reason")
        not in {
            "partition_end_offsets_reached",
            "message_limit_reached",
            "byte_limit_reached",
            "time_limit_reached",
        }
        or result.get("production_mutation_performed") is not False
        or result.get("raw_payload_persisted_to_output") is not False
        or result.get("temporary_store_destroyed") is not True
    ):
        raise EvidenceError("kafka_recent_replay_result_invalid")
    raw_records = result.get("records")
    if not isinstance(raw_records, list) or len(raw_records) != records_scanned:
        raise EvidenceError("kafka_recent_replay_records_invalid")
    decision_counts: Counter[str] = Counter()
    reason_counts: Counter[str] = Counter()
    coordinates: set[tuple[int, int]] = set()
    observed_bytes = 0
    trigger_count = 0
    outbox_count = 0
    expected_e2e_record_count = 0
    for index, raw_record in enumerate(raw_records):
        record = _remote_soak_object(
            raw_record,
            field=f"{artifact}.result.records.{index}",
            keys={
                "partition",
                "offset",
                "timestamp_ms",
                "value_bytes",
                "value_sha256",
                "decision",
                "reason",
                "event_uid_sha256",
                "business_key_sha256",
                "submission_key_sha256",
                "trigger_created",
                "outbox_created",
                "expected_e2e_work_item",
            },
            blocker="kafka_recent_replay_records_invalid",
        )
        partition = _exact_int(
            record.get("partition"),
            f"{artifact}.result.records.{index}.partition",
            minimum=0,
        )
        offset = _exact_int(
            record.get("offset"),
            f"{artifact}.result.records.{index}.offset",
            minimum=0,
        )
        coordinate = (partition, offset)
        decision = _required_text(
            record.get("decision"), f"{artifact}.result.records.{index}.decision"
        )
        reason = _required_text(
            record.get("reason"), f"{artifact}.result.records.{index}.reason"
        )
        value_bytes = _exact_int(
            record.get("value_bytes"),
            f"{artifact}.result.records.{index}.value_bytes",
            minimum=1,
        )
        timestamp_ms = record.get("timestamp_ms")
        if timestamp_ms is not None:
            _exact_int(
                timestamp_ms,
                f"{artifact}.result.records.{index}.timestamp_ms",
                minimum=0,
            )
        if (
            partition not in expected_partition_list
            or coordinate in coordinates
            or decision not in {"accepted", "filtered", "invalid", "deduped"}
            or not isinstance(record.get("trigger_created"), bool)
            or not isinstance(record.get("outbox_created"), bool)
            or not isinstance(record.get("expected_e2e_work_item"), bool)
        ):
            raise EvidenceError("kafka_recent_replay_records_invalid")
        _sha256_digest(
            record.get("value_sha256"),
            f"{artifact}.result.records.{index}.value_sha256",
        )
        _sha256_digest(
            record.get("event_uid_sha256"),
            f"{artifact}.result.records.{index}.event_uid_sha256",
        )
        for field in ("business_key_sha256", "submission_key_sha256"):
            value = record.get(field)
            if value is not None:
                _sha256_digest(value, f"{artifact}.result.records.{index}.{field}")
        if decision == "accepted" and (
            record.get("business_key_sha256") is None
            or record.get("submission_key_sha256") is None
        ):
            raise EvidenceError("kafka_recent_replay_records_invalid")
        coordinates.add(coordinate)
        decision_counts[decision] += 1
        reason_counts[reason] += 1
        observed_bytes += value_bytes
        trigger_count += int(record["trigger_created"])
        outbox_count += int(record["outbox_created"])
        expected_e2e_record_count += int(record["expected_e2e_work_item"])

    e2e = _remote_soak_object(
        result.get("e2e_canary"),
        field=f"{artifact}.result.e2e_canary",
        keys={
            "required",
            "manifest",
            "expected_work_item_ids",
            "matched_work_item_ids",
            "missing_work_item_ids",
            "unexpected_accepted_work_items",
            "complete",
        },
        blocker="kafka_recent_replay_e2e_invalid",
    )
    manifest_observation = _remote_soak_object(
        e2e.get("manifest"),
        field=f"{artifact}.result.e2e_canary.manifest",
        keys={"path", "sha256", "mode", "size", "work_item_count", "source"},
        blocker="kafka_recent_replay_e2e_manifest_invalid",
    )
    manifest_path = Path(
        _required_text(
            manifest_observation.get("path"),
            f"{artifact}.result.e2e_canary.manifest.path",
        )
    ).expanduser()
    if (
        not manifest_path.is_absolute()
        or manifest_observation.get("mode") != "0600"
    ):
        raise EvidenceError("kafka_recent_replay_e2e_manifest_invalid")
    expected_manifest_sha256 = _sha256_digest(
        manifest_observation.get("sha256"),
        f"{artifact}.result.e2e_canary.manifest.sha256",
    )
    raw_manifest, manifest_body = _load_owner_only_json(
        manifest_path,
        artifact="kafka_recent_replay_e2e_manifest",
    )
    if (
        len(raw_manifest)
        != _exact_int(
            manifest_observation.get("size"),
            f"{artifact}.result.e2e_canary.manifest.size",
            minimum=1,
        )
        or hashlib.sha256(raw_manifest).hexdigest() != expected_manifest_sha256
        or manifest_body.get("schema_version")
        != KAFKA_E2E_CANARY_MANIFEST_SCHEMA_VERSION
        or set(manifest_body)
        != {
            "schema_version",
            "generated_at",
            "task_id",
            "source",
            "work_item_ids",
            "required_kafka_evidence",
            "contains_raw_title",
            "contains_raw_pdcl_reference",
            "contains_credential",
        }
        or manifest_body.get("required_kafka_evidence")
        != {
            "window_days": 7,
            "all_work_items_observed": True,
            "all_work_items_accepted": True,
            "all_triggers_created_or_deduplicated": True,
            "shadow_outbox_only": True,
            "commit_performed": False,
        }
        or manifest_body.get("contains_raw_title") is not False
        or manifest_body.get("contains_raw_pdcl_reference") is not False
        or manifest_body.get("contains_credential") is not False
    ):
        raise EvidenceError("kafka_recent_replay_e2e_manifest_invalid")
    manifest_generated_at = _timestamp(
        manifest_body.get("generated_at"),
        f"{artifact}.result.e2e_canary.manifest.generated_at",
    )
    manifest_task_id = _required_text(
        manifest_body.get("task_id"),
        f"{artifact}.result.e2e_canary.manifest.task_id",
    )
    if manifest_generated_at > observed or len(manifest_task_id) > 128:
        raise EvidenceError("kafka_recent_replay_e2e_manifest_invalid")
    expected_ids = e2e.get("expected_work_item_ids")
    matched_ids = e2e.get("matched_work_item_ids")
    missing_ids = e2e.get("missing_work_item_ids")
    manifest_ids = manifest_body.get("work_item_ids")
    if not all(
        isinstance(value, list)
        for value in (expected_ids, matched_ids, missing_ids, manifest_ids)
    ):
        raise EvidenceError("kafka_recent_replay_e2e_invalid")

    def valid_work_item_ids(values: Sequence[Any]) -> list[str]:
        normalized = [str(value).strip() for value in values]
        if (
            not normalized
            or any(
                not value.isdigit() or int(value) <= 0 or len(value) > 32
                for value in normalized
            )
            or len(normalized) != len(set(normalized))
        ):
            raise EvidenceError("kafka_recent_replay_e2e_invalid")
        return sorted(normalized, key=int)

    expected_id_list = valid_work_item_ids(expected_ids)
    matched_id_list = valid_work_item_ids(matched_ids)
    manifest_id_list = valid_work_item_ids(manifest_ids)
    source_identity = _mapping(
        manifest_body.get("source"),
        f"{artifact}.result.e2e_canary.manifest.source",
    )
    observed_source_identity = _mapping(
        manifest_observation.get("source"),
        f"{artifact}.result.e2e_canary.manifest.observed_source",
    )
    source_fields = {
        name: _required_text(
            source_identity.get(name),
            f"{artifact}.result.e2e_canary.manifest.source.{name}",
        )
        for name in (
            "project_key",
            "project_simple_name",
            "work_item_type_key",
            "feishu_plugin_source",
            "feishu_receipt_path",
            "screenshot_sha256",
            "feishu_receipt_sha256",
        )
    }
    if set(source_identity) != set(source_fields) or observed_source_identity != (
        source_fields
    ):
        raise EvidenceError("kafka_recent_replay_e2e_manifest_invalid")
    if not Path(source_fields["feishu_receipt_path"]).expanduser().is_absolute():
        raise EvidenceError("kafka_recent_replay_e2e_manifest_invalid")
    for name in ("screenshot_sha256", "feishu_receipt_sha256"):
        _sha256_digest(
            source_fields[name],
            f"{artifact}.result.e2e_canary.manifest.source.{name}",
        )
    expected_count = _exact_int(
        manifest_observation.get("work_item_count"),
        f"{artifact}.result.e2e_canary.manifest.work_item_count",
        minimum=1,
    )
    if (
        e2e.get("required") is not True
        or e2e.get("complete") is not True
        or missing_ids != []
        or expected_id_list != matched_id_list
        or expected_id_list != manifest_id_list
        or len(expected_id_list) != expected_count
        or expected_e2e_record_count < expected_count
        or source_fields["project_key"] not in consumer.policy.project_keys
        or source_fields["project_simple_name"]
        not in consumer.policy.project_simple_names
        or source_fields["work_item_type_key"]
        not in consumer.policy.work_item_type_keys
        or isinstance(e2e.get("unexpected_accepted_work_items"), bool)
        or not isinstance(e2e.get("unexpected_accepted_work_items"), int)
        or e2e["unexpected_accepted_work_items"] < 0
    ):
        raise EvidenceError("kafka_recent_replay_e2e_incomplete")
    feishu_source = _check_kafka_e2e_feishu_source(
        manifest_task_id=manifest_task_id,
        source=source_fields,
        expected_work_item_ids=expected_id_list,
        window_started_at=started_at,
        replay_observed_at=observed,
    )
    if (
        dict(sorted(decision_counts.items())) != result.get("decision_counts")
        or dict(sorted(reason_counts.items())) != result.get("reason_counts")
        or observed_bytes != raw_bytes
        or decision_counts["accepted"] < 1
        or trigger_count < 1
        or outbox_count < 1
    ):
        raise EvidenceError("kafka_recent_replay_chain_incomplete")
    shadow_store = _remote_soak_object(
        result.get("shadow_store"),
        field=f"{artifact}.result.shadow_store",
        keys={"inbox", "outbox", "replay_raw_retained"},
        blocker="kafka_recent_replay_shadow_store_invalid",
    )
    raw_inbox = _mapping(
        shadow_store.get("inbox"), f"{artifact}.result.shadow_store.inbox"
    )
    raw_outbox = _mapping(
        shadow_store.get("outbox"), f"{artifact}.result.shadow_store.outbox"
    )
    inbox = {
        str(name): _exact_int(
            count,
            f"{artifact}.result.shadow_store.inbox.{name}",
            minimum=0,
        )
        for name, count in raw_inbox.items()
    }
    outbox = {
        str(name): _exact_int(
            count,
            f"{artifact}.result.shadow_store.outbox.{name}",
            minimum=0,
        )
        for name, count in raw_outbox.items()
    }
    if (
        sum(inbox.values()) != records_scanned
        or outbox.get("shadow", 0) < outbox_count
    ):
        raise EvidenceError("kafka_recent_replay_shadow_store_invalid")
    return {
        "observed_at": observed_at,
        "window_days": 7,
        "topic": consumer.topic,
        "partitions": expected_partition_list,
        "records_scanned": records_scanned,
        "raw_bytes_scanned": raw_bytes,
        "accepted": decision_counts["accepted"],
        "triggers_created": trigger_count,
        "shadow_outbox_created": outbox_count,
        "e2e_work_items_matched": expected_count,
        "e2e_manifest_sha256": expected_manifest_sha256,
        **feishu_source,
        "feishu_plugin_source": source_fields["feishu_plugin_source"],
        "commit_performed": False,
        "production_mutation_performed": False,
    }


def _remote_soak_candidate_binding(
    value: Any,
    *,
    field: str,
    expected_vm_commit: str,
    expected_vm_tree: str,
) -> dict[str, Any]:
    candidate = _remote_soak_object(
        value,
        field=field,
        keys={
            "base_commit",
            "base_tree",
            "execution_commit",
            "execution_tree",
            "clean",
        },
        blocker="remote_reader_soak_candidate_binding_invalid",
    )
    normalized = {
        "base_commit": _remote_soak_commit(
            candidate.get("base_commit"), f"{field}.base_commit"
        ),
        "base_tree": _remote_soak_commit(
            candidate.get("base_tree"), f"{field}.base_tree"
        ),
        "execution_commit": _remote_soak_commit(
            candidate.get("execution_commit"), f"{field}.execution_commit"
        ),
        "execution_tree": _remote_soak_commit(
            candidate.get("execution_tree"), f"{field}.execution_tree"
        ),
        "clean": candidate.get("clean"),
    }
    if (
        normalized["base_commit"] != REMOTE_READER_SOAK_BASE_COMMIT
        or normalized["base_tree"] != REMOTE_READER_SOAK_BASE_TREE
        or normalized["execution_commit"] != expected_vm_commit
        or normalized["execution_tree"] != expected_vm_tree
        or normalized["clean"] is not True
    ):
        raise EvidenceError("remote_reader_soak_candidate_binding_mismatch")
    return normalized


def _remote_soak_sampled_concurrency(
    records: Sequence[Mapping[str, Any]],
    *,
    samples_total: int,
    sample_interval_seconds: int,
    reserve: int,
) -> dict[str, int]:
    step_ms = sample_interval_seconds * 1000
    difference = [0] * (samples_total + 1)
    for record in records:
        timing = _mapping(record.get("timing"), "remote_reader_soak.case.timing")
        start = _exact_int(
            timing.get("offset_start_ms"),
            "remote_reader_soak.case.timing.offset_start_ms",
            minimum=0,
        )
        end = _exact_int(
            timing.get("offset_end_ms"),
            "remote_reader_soak.case.timing.offset_end_ms",
            minimum=0,
        )
        first = max(0, math.ceil(start / step_ms))
        last_exclusive = min(samples_total, math.ceil(end / step_ms))
        if first < last_exclusive:
            difference[first] += 1
            difference[last_exclusive] -= 1
    active = 0
    peak = 0
    samples_at_reserve = 0
    current_run = 0
    longest_run = 0
    over_admission_count = 0
    for index in range(samples_total):
        active += difference[index]
        peak = max(peak, active)
        if active > reserve:
            over_admission_count += 1
        if active >= reserve:
            samples_at_reserve += 1
            current_run += 1
            longest_run = max(longest_run, current_run)
        else:
            current_run = 0
    return {
        "peak": peak,
        "samples_at_or_above_reserved": samples_at_reserve,
        "longest_sustained_seconds_at_or_above_reserved": (
            longest_run * sample_interval_seconds
        ),
        "over_admission_count": over_admission_count,
    }


def _check_remote_reader_soak_manifest(
    value: Mapping[str, Any],
    *,
    summary: Mapping[str, Any],
    records: Sequence[Mapping[str, Any]],
    attempted: int,
    soak_started_at: datetime,
) -> dict[str, Any]:
    artifact = "remote_reader_soak_manifest"
    manifest = _remote_soak_object(
        value,
        field=artifact,
        keys={
            "schema_version",
            "generated_at",
            "source",
            "domain_quotas",
            "reader_class_quotas",
            "cases",
        },
        blocker="remote_reader_soak_manifest_shape_invalid",
    )
    if manifest.get("schema_version") != REMOTE_READER_SOAK_MANIFEST_SCHEMA_VERSION:
        raise EvidenceError("remote_reader_soak_manifest_schema_invalid")
    generated_at = _remote_soak_timestamp(
        manifest.get("generated_at"), f"{artifact}.generated_at"
    )
    if generated_at > soak_started_at:
        raise EvidenceError(
            "remote_reader_soak_manifest_generated_after_soak_start"
        )
    source = _remote_soak_object(
        manifest.get("source"),
        field=f"{artifact}.source",
        keys={
            "generation_mode",
            "component",
            "component_commit",
            "artifact_sha256",
        },
        blocker="remote_reader_soak_manifest_source_invalid",
    )
    _remote_soak_commit(
        source.get("component_commit"), f"{artifact}.source.component_commit"
    )
    source_artifact_sha256 = _sha256_digest(
        source.get("artifact_sha256"), f"{artifact}.source.artifact_sha256"
    )
    if (
        source.get("generation_mode") != "machine_generated"
        or source.get("component") != "rca_issue_workload_export"
        or source != summary.get("source")
    ):
        raise EvidenceError("remote_reader_soak_manifest_source_mismatch")
    if (
        manifest.get("domain_quotas")
        != dict(sorted(REMOTE_READER_SOAK_DOMAIN_QUOTAS.items()))
        or manifest.get("reader_class_quotas")
        != dict(sorted(REMOTE_READER_SOAK_READER_QUOTAS.items()))
    ):
        raise EvidenceError("remote_reader_soak_manifest_quota_mismatch")

    raw_cases = manifest.get("cases")
    if not isinstance(raw_cases, list) or len(raw_cases) != attempted:
        raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
    if len(records) != attempted:
        raise EvidenceError("remote_reader_soak_manifest_case_mismatch")

    case_ids: set[str] = set()
    work_item_ids: set[str] = set()
    reference_bindings: set[str] = set()
    for index, (raw_case, soak_record) in enumerate(zip(raw_cases, records)):
        case = _remote_soak_object(
            raw_case,
            field=f"{artifact}.cases.{index}",
            keys={"case_id", "work_item_id", "function_domain", "data_access"},
            blocker="remote_reader_soak_manifest_case_mismatch",
        )
        case_id = _remote_soak_identifier(
            case.get("case_id"), f"{artifact}.cases.{index}.case_id"
        )
        work_item_id = _remote_soak_identifier(
            case.get("work_item_id"), f"{artifact}.cases.{index}.work_item_id"
        )
        function_domain = str(case.get("function_domain") or "").strip().upper()
        if function_domain not in {"ACC", "LCC", "AEB", "FCW", "DNP"}:
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
        quota_domain = (
            "AEB_FCW" if function_domain in {"AEB", "FCW"} else function_domain
        )

        data_access = _remote_soak_object(
            case.get("data_access"),
            field=f"{artifact}.cases.{index}.data_access",
            keys={
                "schema_version",
                "mode",
                "transport",
                "references",
                "source",
                "reader_contract",
            },
            blocker="remote_reader_soak_manifest_case_mismatch",
        )
        if (
            data_access.get("schema_version")
            != FIXED_REMOTE_ACCESS_CONTRACT["data_access_schema_version"]
            or data_access.get("mode") != "remote_read"
            or data_access.get("transport") != "pdcl_pyclip"
        ):
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
        access_source = _remote_soak_object(
            data_access.get("source"),
            field=f"{artifact}.cases.{index}.data_access.source",
            keys={"field", "value_sha256"},
            blocker="remote_reader_soak_manifest_case_mismatch",
        )
        if access_source.get("field") != "问题数据地址_PDCL":
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
        _sha256_digest(
            access_source.get("value_sha256"),
            f"{artifact}.cases.{index}.data_access.source.value_sha256",
        )
        if data_access.get("reader_contract") != {
            "distribution": "pdcl_pyclip",
            "required_version": "0.1.6+rca.2",
            "mdi_download_allowed": False,
            "fallback": "forbidden",
            "completeness": "full_requested_scope",
        }:
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")

        references = data_access.get("references")
        if not isinstance(references, list) or len(references) != 1:
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
        reference = _mapping(
            references[0], f"{artifact}.cases.{index}.data_access.references.0"
        )
        kind = str(reference.get("kind") or "")
        expected_reference = {
            "clip": ("clip_uuid", "RemoteClipReader"),
            "event": ("event_uuid", "RemoteEventReader"),
        }.get(kind)
        if expected_reference is None:
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
        locator_field, reader_class = expected_reference
        if set(reference) != {"kind", locator_field, "reader_class"}:
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
        raw_locator = reference.get(locator_field)
        locator = raw_locator.strip() if isinstance(raw_locator, str) else ""
        if (
            not locator
            or len(locator) > 512
            or raw_locator != locator
            or "\x00" in locator
            or reference.get("reader_class") != reader_class
        ):
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
        locator_sha256 = hashlib.sha256(locator.encode("utf-8")).hexdigest()
        reference_material = {
            "kind": kind,
            "reader_class": reader_class,
            "locator_field": locator_field,
            "locator_sha256": locator_sha256,
        }
        reference_binding = _remote_soak_sha256(reference_material)
        manifest_record_sha256 = _remote_soak_sha256(case)
        soak_reference = _mapping(
            soak_record.get("reference"), f"{artifact}.soak_records.{index}.reference"
        )
        if (
            case_id in case_ids
            or work_item_id in work_item_ids
            or reference_binding in reference_bindings
            or soak_record.get("case_id") != case_id
            or soak_record.get("work_item_id") != work_item_id
            or soak_record.get("function_domain") != function_domain
            or soak_record.get("quota_domain") != quota_domain
            or soak_record.get("workload_manifest_record_sha256")
            != manifest_record_sha256
            or soak_reference != {
                **reference_material,
                "reference_binding_sha256": reference_binding,
            }
        ):
            raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
        case_ids.add(case_id)
        work_item_ids.add(work_item_id)
        reference_bindings.add(reference_binding)

    if [case["case_id"] for case in raw_cases] != sorted(case_ids):
        raise EvidenceError("remote_reader_soak_manifest_case_mismatch")
    manifest_sha256 = _remote_soak_sha256(manifest)
    if summary.get("sha256") != manifest_sha256:
        raise EvidenceError("remote_reader_soak_manifest_hash_mismatch")
    return {
        "generated_at": generated_at.strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
        "sha256": manifest_sha256,
        "case_count": len(raw_cases),
        "source": dict(source),
        "source_artifact_sha256": source_artifact_sha256,
        "source_artifact_verification": "producer_locator_only",
    }


def _check_remote_reader_soak(
    body: Mapping[str, Any],
    *,
    workload_manifest_body: Mapping[str, Any],
    expected_reader_fingerprint: str,
    expected_vm_commit: str,
    expected_vm_tree: str,
    expected_remote_reader_health_sha256: str,
    remote_reader_health_detail: Mapping[str, Any],
    dispatcher: DispatcherConfig,
    target_cases_per_day: int,
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    artifact = "remote_reader_soak"
    top = _remote_soak_object(
        body,
        field=artifact,
        keys={
            "schema_version",
            "observed_at",
            "ok",
            "source",
            "candidate_binding",
            "dependency_binding",
            "workload_manifest",
            "policy",
            "started_at",
            "ended_at",
            "duration_seconds",
            "attempted_cases",
            "completed_cases",
            "concurrency_peak",
            "concurrency_profile",
            "temporal_profile",
            "capacity_lifecycle",
            "workload_mix",
            "case_evidence",
            "zero_invariants",
            "latency_ms",
            "throughput",
            "resources",
            "errors",
        },
        blocker="remote_reader_soak_shape_invalid",
    )
    _require_schema(top, REMOTE_READER_SOAK_SCHEMA_VERSION, artifact)
    observed_at_text = _required_text(top.get("observed_at"), f"{artifact}.observed_at")
    observed_at_dt = _remote_soak_timestamp(observed_at_text, f"{artifact}.observed_at")
    _require_fresh(top, now=now, max_age_seconds=max_age_seconds, artifact=artifact)
    if top.get("ok") is not True or top.get("errors") != []:
        raise EvidenceError("remote_reader_soak_not_ok")

    source = _remote_soak_object(
        top.get("source"),
        field=f"{artifact}.source",
        keys={
            "generation_mode",
            "component",
            "component_commit",
            "component_tree",
            "module",
            "module_sha256",
            "entrypoint",
            "entrypoint_sha256",
            "schema",
            "schema_sha256",
        },
        blocker="remote_reader_soak_source_invalid",
    )
    source_commit = _remote_soak_commit(
        source.get("component_commit"), f"{artifact}.source.component_commit"
    )
    source_tree = _remote_soak_commit(
        source.get("component_tree"), f"{artifact}.source.component_tree"
    )
    module_sha256 = _sha256_digest(
        source.get("module_sha256"), f"{artifact}.source.module_sha256"
    )
    entrypoint_sha256 = _sha256_digest(
        source.get("entrypoint_sha256"), f"{artifact}.source.entrypoint_sha256"
    )
    schema_sha256 = _sha256_digest(
        source.get("schema_sha256"), f"{artifact}.source.schema_sha256"
    )
    local_schema_path = REPO_ROOT / REMOTE_READER_SOAK_HOST_SCHEMA
    if (
        local_schema_path.is_symlink()
        or not local_schema_path.is_file()
        or local_schema_path.stat().st_size > 1024 * 1024
    ):
        raise EvidenceError("remote_reader_soak_host_schema_invalid")
    local_schema_sha256 = hashlib.sha256(local_schema_path.read_bytes()).hexdigest()
    if (
        source.get("generation_mode") != "machine_generated"
        or source.get("component") != "pnc_rca_remote_reader_soak"
        or source.get("module") != REMOTE_READER_SOAK_MODULE
        or source.get("entrypoint") != REMOTE_READER_SOAK_ENTRYPOINT
        or source.get("schema") != REMOTE_READER_SOAK_VM_SCHEMA
        or module_sha256 != REMOTE_READER_SOAK_MODULE_SHA256
        or entrypoint_sha256 != REMOTE_READER_SOAK_ENTRYPOINT_SHA256
        or schema_sha256 != REMOTE_READER_SOAK_SCHEMA_SHA256
        or local_schema_sha256 != REMOTE_READER_SOAK_SCHEMA_SHA256
        or source_commit != expected_vm_commit
        or source_tree != expected_vm_tree
    ):
        raise EvidenceError("remote_reader_soak_source_mismatch")

    candidate = _remote_soak_candidate_binding(
        top.get("candidate_binding"),
        field=f"{artifact}.candidate_binding",
        expected_vm_commit=expected_vm_commit,
        expected_vm_tree=expected_vm_tree,
    )
    if (
        source_commit != candidate["execution_commit"]
        or source_tree != candidate["execution_tree"]
    ):
        raise EvidenceError("remote_reader_soak_source_candidate_mismatch")

    dependency = _mapping(
        top.get("dependency_binding"), f"{artifact}.dependency_binding"
    )
    required_dependency_keys = {
        "distribution",
        "version",
        "wheel_sha256",
        "runtime_proof_sha256",
        "dependency_doctor_sha256",
        "remote_reader_health_sha256",
        "fingerprint_material",
        "reader_fingerprint_material",
        "fingerprint",
        "reader_fingerprint",
    }
    if set(dependency) != required_dependency_keys:
        raise EvidenceError("remote_reader_soak_dependency_binding_invalid")
    wheel_sha256 = _sha256_digest(
        dependency.get("wheel_sha256"), f"{artifact}.dependency_binding.wheel_sha256"
    )
    runtime_proof_sha256 = _sha256_digest(
        dependency.get("runtime_proof_sha256"),
        f"{artifact}.dependency_binding.runtime_proof_sha256",
    )
    dependency_doctor_sha256 = _sha256_digest(
        dependency.get("dependency_doctor_sha256"),
        f"{artifact}.dependency_binding.dependency_doctor_sha256",
    )
    health_sha256 = _sha256_digest(
        dependency.get("remote_reader_health_sha256"),
        f"{artifact}.dependency_binding.remote_reader_health_sha256",
    )
    dependency_fingerprint = _sha256_digest(
        dependency.get("fingerprint"), f"{artifact}.dependency_binding.fingerprint"
    )
    soak_reader_fingerprint = _sha256_digest(
        dependency.get("reader_fingerprint"),
        f"{artifact}.dependency_binding.reader_fingerprint",
    )
    if (
        dependency.get("distribution") != "pdcl_pyclip"
        or dependency.get("version") != "0.1.6+rca.2"
        or wheel_sha256
        != str(remote_reader_health_detail.get("sanitized_wheel_sha256") or "")
        or health_sha256 != expected_remote_reader_health_sha256
        or str(remote_reader_health_detail.get("reader_fingerprint") or "")
        != expected_reader_fingerprint
    ):
        raise EvidenceError("remote_reader_soak_dependency_binding_mismatch")
    fingerprint_material = _mapping(
        dependency.get("fingerprint_material"),
        f"{artifact}.dependency_binding.fingerprint_material",
    )
    expected_material_keys = {
        "remote_reader_health_sha256",
        "remote_reader_health_reader_fingerprint",
        "dependency_doctor_sha256",
        "distribution",
        "version",
        "sanitized_policy",
        "sanitized_patch_commit",
        "wheel_sha256",
        "source_hashes",
        "dependencies",
        "runtime",
        "runtime_environment",
        "runtime_proof_sha256",
    }
    if set(fingerprint_material) != expected_material_keys:
        raise EvidenceError("remote_reader_soak_dependency_material_invalid")
    runtime_environment = _mapping(
        fingerprint_material.get("runtime_environment"),
        f"{artifact}.dependency_binding.runtime_environment",
    )
    if (
        fingerprint_material.get("remote_reader_health_sha256") != health_sha256
        or fingerprint_material.get("remote_reader_health_reader_fingerprint")
        != expected_reader_fingerprint
        or fingerprint_material.get("dependency_doctor_sha256")
        != dependency_doctor_sha256
        or fingerprint_material.get("distribution") != dependency.get("distribution")
        or fingerprint_material.get("version") != dependency.get("version")
        or fingerprint_material.get("wheel_sha256") != wheel_sha256
        or fingerprint_material.get("runtime_proof_sha256")
        != runtime_proof_sha256
        or runtime_environment
        != remote_reader_health_detail.get("runtime_environment")
        or _remote_soak_sha256(fingerprint_material) != dependency_fingerprint
    ):
        raise EvidenceError("remote_reader_soak_dependency_material_mismatch")
    source_hashes = _mapping(
        fingerprint_material.get("source_hashes"),
        f"{artifact}.dependency_binding.source_hashes",
    )
    if not source_hashes:
        raise EvidenceError("remote_reader_soak_dependency_material_invalid")
    for path, digest in source_hashes.items():
        if (
            not isinstance(path, str)
            or not path
            or PurePosixPath(path).is_absolute()
            or ".." in PurePosixPath(path).parts
        ):
            raise EvidenceError("remote_reader_soak_dependency_source_invalid")
        _sha256_digest(digest, f"{artifact}.dependency_binding.source_hashes.{path}")
    dependency_versions = _mapping(
        fingerprint_material.get("dependencies"),
        f"{artifact}.dependency_binding.dependencies",
    )
    if dependency_versions != {
        "mcap": "1.2.2",
        "pdcl-dss": "0.1.44",
        "protobuf": "3.20.3",
        "typer": "0.20.0",
    }:
        raise EvidenceError("remote_reader_soak_dependency_versions_mismatch")
    dependency_runtime = _mapping(
        fingerprint_material.get("runtime"),
        f"{artifact}.dependency_binding.runtime",
    )
    if (
        dependency_runtime.get("execution_mode") != "isolated_subprocess"
        or dependency_runtime.get("reader_import_scope") != "sidecar_only"
        or _exact_int(
            dependency_runtime.get("timeout_seconds"),
            f"{artifact}.dependency_binding.runtime.timeout_seconds",
            minimum=1,
        )
        != 120
    ):
        raise EvidenceError("remote_reader_soak_dependency_runtime_mismatch")
    reader_material = _mapping(
        dependency.get("reader_fingerprint_material"),
        f"{artifact}.dependency_binding.reader_fingerprint_material",
    )
    if set(reader_material) != {
        "distribution",
        "version",
        "wheel_sha256",
        "source_hashes",
        "api",
        "runtime_environment",
        "remote_reader_health_reader_fingerprint",
    } or (
        reader_material.get("distribution") != dependency.get("distribution")
        or reader_material.get("version") != dependency.get("version")
        or reader_material.get("wheel_sha256") != wheel_sha256
        or reader_material.get("source_hashes") != source_hashes
        or reader_material.get("runtime_environment") != runtime_environment
        or reader_material.get("remote_reader_health_reader_fingerprint")
        != expected_reader_fingerprint
        or _remote_soak_sha256(reader_material) != soak_reader_fingerprint
    ):
        raise EvidenceError("remote_reader_soak_reader_fingerprint_mismatch")
    reader_api = _mapping(
        reader_material.get("api"), f"{artifact}.dependency_binding.reader_api"
    )
    if set(reader_api) != {"RemoteClipReader", "RemoteEventReader"}:
        raise EvidenceError("remote_reader_soak_reader_class_diversity_missing")
    for name, receipt in reader_api.items():
        parsed_receipt = _mapping(
            receipt, f"{artifact}.dependency_binding.reader_api.{name}"
        )
        if parsed_receipt.get("missing_methods") != []:
            raise EvidenceError("remote_reader_soak_reader_api_incomplete")

    manifest = _remote_soak_object(
        top.get("workload_manifest"),
        field=f"{artifact}.workload_manifest",
        keys={
            "schema_version",
            "sha256",
            "case_count",
            "unique_work_items",
            "unique_references",
            "domain_counts",
            "reader_class_counts",
            "source",
        },
        blocker="remote_reader_soak_manifest_invalid",
    )
    if manifest.get("schema_version") != REMOTE_READER_SOAK_MANIFEST_SCHEMA_VERSION:
        raise EvidenceError("remote_reader_soak_manifest_schema_invalid")
    manifest_sha256 = _sha256_digest(
        manifest.get("sha256"), f"{artifact}.workload_manifest.sha256"
    )
    manifest_source = _remote_soak_object(
        manifest.get("source"),
        field=f"{artifact}.workload_manifest.source",
        keys={
            "generation_mode",
            "component",
            "component_commit",
            "artifact_sha256",
        },
        blocker="remote_reader_soak_manifest_source_invalid",
    )
    if (
        manifest_source.get("generation_mode") != "machine_generated"
        or manifest_source.get("component") != "rca_issue_workload_export"
    ):
        raise EvidenceError("remote_reader_soak_manifest_source_invalid")
    _remote_soak_commit(
        manifest_source.get("component_commit"),
        f"{artifact}.workload_manifest.source.component_commit",
    )
    _sha256_digest(
        manifest_source.get("artifact_sha256"),
        f"{artifact}.workload_manifest.source.artifact_sha256",
    )

    expected_policy = {
        "duration_seconds": 86_400,
        "min_cases": 200,
        "domain_quotas": REMOTE_READER_SOAK_DOMAIN_QUOTAS,
        "reader_class_quotas": REMOTE_READER_SOAK_READER_QUOTAS,
        "max_concurrency": 4,
        "per_case_timeout_seconds": 120,
        "minimum_seconds_at_reserve": 900,
        "minimum_longest_sustained_seconds": 300,
        "temporal_bucket_seconds": 3_600,
        "minimum_temporal_buckets": 24,
        "maximum_temporal_gap_seconds": 3_600,
        "max_clips": 16,
        "max_messages": 250_000,
        "max_scanned_messages": 1_000_000,
        "max_output_bytes": 750_000_000,
        "retry_count": 0,
        "input_materialization": "forbidden",
        "fallback": "forbidden",
    }
    if top.get("policy") != expected_policy:
        raise EvidenceError("remote_reader_soak_policy_mismatch")

    started_at = _remote_soak_timestamp(
        top.get("started_at"), f"{artifact}.started_at"
    )
    ended_at = _remote_soak_timestamp(top.get("ended_at"), f"{artifact}.ended_at")
    duration = _exact_int(
        top.get("duration_seconds"), f"{artifact}.duration_seconds", minimum=1
    )
    if (
        ended_at <= started_at
        or abs((ended_at - started_at).total_seconds() - duration) > 1
        or duration < expected_policy["duration_seconds"]
        or abs((ended_at - observed_at_dt).total_seconds()) > 1
    ):
        raise EvidenceError("remote_reader_soak_duration_inconsistent")
    attempted = _exact_int(
        top.get("attempted_cases"), f"{artifact}.attempted_cases", minimum=1
    )
    completed = _exact_int(
        top.get("completed_cases"), f"{artifact}.completed_cases", minimum=0
    )
    if attempted < max(200, target_cases_per_day) or completed != attempted:
        raise EvidenceError("remote_reader_soak_case_volume_insufficient")
    concurrency_peak = _exact_int(
        top.get("concurrency_peak"), f"{artifact}.concurrency_peak", minimum=1
    )
    if (
        concurrency_peak != expected_policy["max_concurrency"]
        or concurrency_peak != dispatcher.storage_concurrency_reserve_cases
    ):
        raise EvidenceError("remote_reader_soak_concurrency_mismatch")

    case_evidence = _remote_soak_object(
        top.get("case_evidence"),
        field=f"{artifact}.case_evidence",
        keys={
            "record_schema",
            "records",
            "record_count",
            "record_hashes",
            "merkle_algorithm",
            "merkle_root",
        },
        blocker="remote_reader_soak_case_evidence_invalid",
    )
    records = case_evidence.get("records")
    record_hashes = case_evidence.get("record_hashes")
    if not isinstance(records, list) or not isinstance(record_hashes, list):
        raise EvidenceError("remote_reader_soak_case_evidence_invalid")
    record_count = _exact_int(
        case_evidence.get("record_count"),
        f"{artifact}.case_evidence.record_count",
        minimum=1,
    )
    if (
        case_evidence.get("record_schema")
        != REMOTE_READER_SOAK_CASE_SCHEMA_VERSION
        or record_count != attempted
        or len(records) != attempted
        or len(record_hashes) != attempted
        or case_evidence.get("merkle_algorithm")
        != REMOTE_READER_SOAK_MERKLE_ALGORITHM
    ):
        raise EvidenceError("remote_reader_soak_case_evidence_inconsistent")

    case_keys = {
        "schema_version",
        "case_id",
        "work_item_id",
        "function_domain",
        "quota_domain",
        "workload_manifest_record_sha256",
        "reference",
        "requested_scope",
        "requested_scope_binding",
        "candidate_binding",
        "dependency_fingerprint",
        "reader_fingerprint",
        "remote_receipt",
        "materialization",
        "timing",
        "record_sha256",
    }
    normalized_records: list[dict[str, Any]] = []
    case_ids: set[str] = set()
    work_item_ids: set[str] = set()
    reference_bindings: set[str] = set()
    manifest_record_hashes: set[str] = set()
    domain_counts: Counter[str] = Counter()
    reader_counts: Counter[str] = Counter()
    reference_counts: Counter[str] = Counter()
    messages_total = 0
    bytes_total = 0
    durations_ms: list[int] = []
    for index, raw_record in enumerate(records):
        record = _remote_soak_object(
            raw_record,
            field=f"{artifact}.case_evidence.records.{index}",
            keys=case_keys,
            blocker="remote_reader_soak_case_shape_invalid",
        )
        if record.get("schema_version") != REMOTE_READER_SOAK_CASE_SCHEMA_VERSION:
            raise EvidenceError("remote_reader_soak_case_schema_invalid")
        case_id = _remote_soak_identifier(
            record.get("case_id"), f"{artifact}.case.{index}.case_id"
        )
        work_item_id = _remote_soak_identifier(
            record.get("work_item_id"), f"{artifact}.case.{index}.work_item_id"
        )
        function_domain = _required_text(
            record.get("function_domain"), f"{artifact}.case.{index}.function_domain"
        )
        quota_domain = _required_text(
            record.get("quota_domain"), f"{artifact}.case.{index}.quota_domain"
        )
        expected_quota_domain = (
            "AEB_FCW" if function_domain in {"AEB", "FCW", "AEB_FCW"} else function_domain
        )
        if (
            function_domain not in {"ACC", "LCC", "AEB", "FCW", "AEB_FCW", "DNP"}
            or quota_domain != expected_quota_domain
            or quota_domain not in REMOTE_READER_SOAK_DOMAIN_QUOTAS
        ):
            raise EvidenceError("remote_reader_soak_case_domain_invalid")
        manifest_record_sha256 = _sha256_digest(
            record.get("workload_manifest_record_sha256"),
            f"{artifact}.case.{index}.workload_manifest_record_sha256",
        )
        reference = _remote_soak_object(
            record.get("reference"),
            field=f"{artifact}.case.{index}.reference",
            keys={
                "kind",
                "reader_class",
                "locator_field",
                "locator_sha256",
                "reference_binding_sha256",
            },
            blocker="remote_reader_soak_case_reference_invalid",
        )
        kind = str(reference.get("kind") or "")
        reader_class = str(reference.get("reader_class") or "")
        locator_field = str(reference.get("locator_field") or "")
        expected_reader = {
            "clip": ("RemoteClipReader", "clip_uuid"),
            "event": ("RemoteEventReader", "event_uuid"),
        }.get(kind)
        locator_sha256 = _sha256_digest(
            reference.get("locator_sha256"),
            f"{artifact}.case.{index}.reference.locator_sha256",
        )
        reference_binding = _sha256_digest(
            reference.get("reference_binding_sha256"),
            f"{artifact}.case.{index}.reference.reference_binding_sha256",
        )
        if (
            expected_reader is None
            or (reader_class, locator_field) != expected_reader
            or reference_binding
            != _remote_soak_sha256({
                "kind": kind,
                "reader_class": reader_class,
                "locator_field": locator_field,
                "locator_sha256": locator_sha256,
            })
        ):
            raise EvidenceError("remote_reader_soak_case_reference_binding_invalid")

        scope = _check_requested_scope(
            record.get("requested_scope"),
            field=f"{artifact}.case.{index}.requested_scope",
        )
        scope_binding = _remote_soak_object(
            record.get("requested_scope_binding"),
            field=f"{artifact}.case.{index}.requested_scope_binding",
            keys={
                "requirements_contract_sha256",
                "requirements_sha256",
                "requested_scope_sha256",
            },
            blocker="remote_reader_soak_case_scope_binding_invalid",
        )
        expected_requirements_sha256 = REMOTE_READER_SOAK_REQUIREMENTS_SHA256.get(
            function_domain
        )
        if (
            expected_requirements_sha256 is None
            or scope["function_domain"] != function_domain
            or scope_binding.get("requirements_contract_sha256")
            != scope["contract_sha256"]
            or scope_binding.get("requirements_sha256") != scope["requirements_hash"]
            or scope_binding.get("requested_scope_sha256")
            != _remote_soak_sha256(record["requested_scope"])
            or scope["contract_sha256"]
            != REMOTE_READER_SOAK_REQUIREMENTS_CONTRACT_SHA256
            or scope["requirements_hash"] != expected_requirements_sha256
        ):
            raise EvidenceError("remote_reader_soak_case_scope_mismatch")
        case_candidate = _remote_soak_candidate_binding(
            record.get("candidate_binding"),
            field=f"{artifact}.case.{index}.candidate_binding",
            expected_vm_commit=expected_vm_commit,
            expected_vm_tree=expected_vm_tree,
        )
        if case_candidate != candidate:
            raise EvidenceError("remote_reader_soak_case_candidate_mismatch")
        if (
            record.get("dependency_fingerprint") != dependency_fingerprint
            or record.get("reader_fingerprint") != soak_reader_fingerprint
        ):
            raise EvidenceError("remote_reader_soak_case_dependency_mismatch")

        receipt = _remote_soak_object(
            record.get("remote_receipt"),
            field=f"{artifact}.case.{index}.remote_receipt",
            keys={
                "schema_version",
                "status",
                "relative_path",
                "sha256",
                "completeness",
                "exhausted",
                "message_count",
                "bytes",
            },
            blocker="remote_reader_soak_case_receipt_invalid",
        )
        relative_path = _required_text(
            receipt.get("relative_path"),
            f"{artifact}.case.{index}.remote_receipt.relative_path",
        )
        parsed_relative = PurePosixPath(relative_path)
        if (
            receipt.get("schema_version") != "g1q3_rca_remote_read_receipt_v1"
            or receipt.get("status") != "completed"
            or receipt.get("completeness") != "full_requested_scope"
            or receipt.get("exhausted") is not True
            or parsed_relative.is_absolute()
            or ".." in parsed_relative.parts
            or not relative_path.startswith("cases/")
            or not relative_path.endswith("/remote_read_receipt.json")
            or "\x00" in relative_path
        ):
            raise EvidenceError("remote_reader_soak_case_receipt_invalid")
        _sha256_digest(
            receipt.get("sha256"), f"{artifact}.case.{index}.remote_receipt.sha256"
        )
        message_count = _exact_int(
            receipt.get("message_count"),
            f"{artifact}.case.{index}.remote_receipt.message_count",
            minimum=1,
        )
        byte_count = _exact_int(
            receipt.get("bytes"),
            f"{artifact}.case.{index}.remote_receipt.bytes",
            minimum=1,
        )

        materialization = _mapping(
            record.get("materialization"),
            f"{artifact}.case.{index}.materialization",
        )
        if materialization != {
            "input_materialized": False,
            "input_materialized_bytes": 0,
            "mdi_invocation_count": 0,
            "download_invocation_count": 0,
            "fallback_count": 0,
            "retained_stream_cache_bytes": 0,
            "observation": "remote_receipt_verified_stream_cache_removed_v1",
        }:
            raise EvidenceError("remote_reader_soak_case_materialization_present")
        timing = _remote_soak_object(
            record.get("timing"),
            field=f"{artifact}.case.{index}.timing",
            keys={
                "started_at",
                "ended_at",
                "duration_ms",
                "offset_start_ms",
                "offset_end_ms",
            },
            blocker="remote_reader_soak_case_timing_invalid",
        )
        case_started = _remote_soak_timestamp(
            timing.get("started_at"), f"{artifact}.case.{index}.timing.started_at"
        )
        case_ended = _remote_soak_timestamp(
            timing.get("ended_at"), f"{artifact}.case.{index}.timing.ended_at"
        )
        duration_ms = _exact_int(
            timing.get("duration_ms"),
            f"{artifact}.case.{index}.timing.duration_ms",
            minimum=0,
        )
        offset_start = _exact_int(
            timing.get("offset_start_ms"),
            f"{artifact}.case.{index}.timing.offset_start_ms",
            minimum=0,
        )
        offset_end = _exact_int(
            timing.get("offset_end_ms"),
            f"{artifact}.case.{index}.timing.offset_end_ms",
            minimum=0,
        )
        if (
            case_ended < case_started
            or case_started < started_at
            or case_ended > ended_at + timedelta(seconds=1)
            or duration_ms > expected_policy["per_case_timeout_seconds"] * 1000
            or offset_end < offset_start
            or offset_end > duration * 1000 + 1000
            or abs((offset_end - offset_start) - duration_ms) > 1
            or abs(
                (case_started - started_at).total_seconds() * 1000
                - offset_start
            )
            > 30_000
            or abs(
                (case_ended - started_at).total_seconds() * 1000
                - offset_end
            )
            > 30_000
        ):
            raise EvidenceError("remote_reader_soak_case_timing_invalid")
        record_sha256 = _sha256_digest(
            record.get("record_sha256"), f"{artifact}.case.{index}.record_sha256"
        )
        record_material = dict(record)
        record_material.pop("record_sha256")
        if record_sha256 != _remote_soak_sha256(record_material):
            raise EvidenceError("remote_reader_soak_case_hash_mismatch")
        if record_hashes[index] != record_sha256:
            raise EvidenceError("remote_reader_soak_case_hash_order_mismatch")
        if (
            case_id in case_ids
            or work_item_id in work_item_ids
            or reference_binding in reference_bindings
            or manifest_record_sha256 in manifest_record_hashes
        ):
            raise EvidenceError("remote_reader_soak_case_duplicate")
        case_ids.add(case_id)
        work_item_ids.add(work_item_id)
        reference_bindings.add(reference_binding)
        manifest_record_hashes.add(manifest_record_sha256)
        domain_counts[quota_domain] += 1
        reader_counts[reader_class] += 1
        reference_counts[kind] += 1
        messages_total += message_count
        bytes_total += byte_count
        durations_ms.append(duration_ms)
        normalized_records.append(record)

    if [record["case_id"] for record in normalized_records] != sorted(case_ids):
        raise EvidenceError("remote_reader_soak_case_order_invalid")
    normalized_hashes = [
        _sha256_digest(digest, f"{artifact}.case_evidence.record_hashes")
        for digest in record_hashes
    ]
    merkle_root = _sha256_digest(
        case_evidence.get("merkle_root"), f"{artifact}.case_evidence.merkle_root"
    )
    if merkle_root != _remote_soak_merkle_root(normalized_hashes):
        raise EvidenceError("remote_reader_soak_merkle_mismatch")

    for domain, minimum in REMOTE_READER_SOAK_DOMAIN_QUOTAS.items():
        if domain_counts.get(domain, 0) < minimum:
            raise EvidenceError("remote_reader_soak_domain_quota_insufficient")
    for reader_class, minimum in REMOTE_READER_SOAK_READER_QUOTAS.items():
        if reader_counts.get(reader_class, 0) < minimum:
            raise EvidenceError("remote_reader_soak_reader_quota_insufficient")
    if set(reference_counts) != {"clip", "event"}:
        raise EvidenceError("remote_reader_soak_reference_diversity_missing")
    manifest_detail = _check_remote_reader_soak_manifest(
        workload_manifest_body,
        summary=manifest,
        records=normalized_records,
        attempted=attempted,
        soak_started_at=started_at,
    )
    manifest_case_binding_sha256 = _remote_soak_sha256({
        "manifest_sha256": manifest_detail["sha256"],
        "case_merkle_root": merkle_root,
        "source": manifest_detail["source"],
    })

    expected_domain_counts = dict(sorted(domain_counts.items()))
    expected_reader_counts = dict(sorted(reader_counts.items()))
    expected_reference_counts = dict(sorted(reference_counts.items()))
    manifest_domain_counts = _remote_soak_count_map(
        manifest.get("domain_counts"), f"{artifact}.workload_manifest.domain_counts"
    )
    manifest_reader_counts = _remote_soak_count_map(
        manifest.get("reader_class_counts"),
        f"{artifact}.workload_manifest.reader_class_counts",
    )
    if (
        _exact_int(
            manifest.get("case_count"),
            f"{artifact}.workload_manifest.case_count",
            minimum=1,
        )
        != attempted
        or _exact_int(
            manifest.get("unique_work_items"),
            f"{artifact}.workload_manifest.unique_work_items",
            minimum=1,
        )
        != len(work_item_ids)
        or _exact_int(
            manifest.get("unique_references"),
            f"{artifact}.workload_manifest.unique_references",
            minimum=1,
        )
        != len(reference_bindings)
        or manifest_domain_counts != expected_domain_counts
        or manifest_reader_counts != expected_reader_counts
    ):
        raise EvidenceError("remote_reader_soak_manifest_aggregate_mismatch")

    workload_mix = _remote_soak_object(
        top.get("workload_mix"),
        field=f"{artifact}.workload_mix",
        keys={
            "reader_class_cases",
            "function_domain_cases",
            "reference_kind_cases",
            "unique_work_items",
            "unique_data_references",
        },
        blocker="remote_reader_soak_workload_mix_invalid",
    )
    if (
        _remote_soak_count_map(
            workload_mix.get("reader_class_cases"),
            f"{artifact}.workload_mix.reader_class_cases",
        )
        != expected_reader_counts
        or _remote_soak_count_map(
            workload_mix.get("function_domain_cases"),
            f"{artifact}.workload_mix.function_domain_cases",
        )
        != expected_domain_counts
        or _remote_soak_count_map(
            workload_mix.get("reference_kind_cases"),
            f"{artifact}.workload_mix.reference_kind_cases",
        )
        != expected_reference_counts
        or workload_mix.get("unique_work_items") != len(work_item_ids)
        or workload_mix.get("unique_data_references") != len(reference_bindings)
    ):
        raise EvidenceError("remote_reader_soak_workload_mix_inconsistent")

    zero_invariants = _mapping(
        top.get("zero_invariants"), f"{artifact}.zero_invariants"
    )
    expected_zero_keys = {
        "error_count",
        "input_materialized_count",
        "input_materialized_bytes",
        "retained_stream_cache_bytes",
        "mdi_invocation_count",
        "download_invocation_count",
        "fallback_count",
        "timeout_count",
        "rate_limit_count",
        "reconnect_count",
        "retry_count",
        "completeness_failure_count",
    }
    if set(zero_invariants) != expected_zero_keys or any(
        _exact_int(value, f"{artifact}.zero_invariants.{key}", minimum=0) != 0
        for key, value in zero_invariants.items()
    ):
        raise EvidenceError("remote_reader_soak_zero_invariant_failed")

    concurrency_profile = _remote_soak_object(
        top.get("concurrency_profile"),
        field=f"{artifact}.concurrency_profile",
        keys={
            "reserved_cases",
            "peak",
            "sample_interval_seconds",
            "samples_total",
            "samples_at_or_above_reserved",
            "longest_sustained_seconds_at_or_above_reserved",
            "over_admission_count",
        },
        blocker="remote_reader_soak_concurrency_profile_invalid",
    )
    sample_interval = _exact_int(
        concurrency_profile.get("sample_interval_seconds"),
        f"{artifact}.concurrency_profile.sample_interval_seconds",
        minimum=1,
    )
    samples_total = _exact_int(
        concurrency_profile.get("samples_total"),
        f"{artifact}.concurrency_profile.samples_total",
        minimum=1,
    )
    sampled = _remote_soak_sampled_concurrency(
        normalized_records,
        samples_total=samples_total,
        sample_interval_seconds=sample_interval,
        reserve=concurrency_peak,
    )
    if (
        concurrency_profile.get("reserved_cases") != concurrency_peak
        or concurrency_profile.get("peak") != sampled["peak"]
        or sample_interval != 10
        or samples_total != math.ceil(duration / sample_interval)
        or concurrency_profile.get("samples_at_or_above_reserved")
        != sampled["samples_at_or_above_reserved"]
        or concurrency_profile.get(
            "longest_sustained_seconds_at_or_above_reserved"
        )
        != sampled["longest_sustained_seconds_at_or_above_reserved"]
        or concurrency_profile.get("over_admission_count")
        != sampled["over_admission_count"]
        or sampled["peak"] != concurrency_peak
        or sampled["samples_at_or_above_reserved"] * sample_interval < 900
        or sampled["longest_sustained_seconds_at_or_above_reserved"] < 300
        or sampled["over_admission_count"] != 0
    ):
        raise EvidenceError("remote_reader_soak_sustained_concurrency_insufficient")

    temporal_profile = _remote_soak_object(
        top.get("temporal_profile"),
        field=f"{artifact}.temporal_profile",
        keys={
            "bucket_seconds",
            "minimum_buckets",
            "minimum_cases_per_bucket",
            "scheduler_tolerance_seconds",
            "bucket_start_counts",
            "covered_bucket_count",
            "first_bucket_covered",
            "last_bucket_covered",
            "maximum_start_gap_ms",
            "maximum_allowed_start_gap_ms",
        },
        blocker="remote_reader_soak_temporal_profile_invalid",
    )
    bucket_seconds = expected_policy["temporal_bucket_seconds"]
    minimum_buckets = expected_policy["minimum_temporal_buckets"]
    bucket_width_ms = bucket_seconds * 1000
    coverage_end_ms = minimum_buckets * bucket_width_ms
    expected_bucket_counts = {str(index): 0 for index in range(minimum_buckets)}
    start_offsets = sorted(
        _exact_int(
            record["timing"]["offset_start_ms"],
            f"{artifact}.temporal_profile.offset_start_ms",
            minimum=0,
        )
        for record in normalized_records
    )
    for offset_ms in start_offsets:
        if offset_ms < coverage_end_ms:
            expected_bucket_counts[str(offset_ms // bucket_width_ms)] += 1
    gaps = [start_offsets[0]] if start_offsets else []
    gaps.extend(
        current - previous
        for previous, current in zip(start_offsets, start_offsets[1:])
    )
    maximum_start_gap_ms = max(gaps, default=0)
    maximum_allowed_start_gap_ms = (
        expected_policy["maximum_temporal_gap_seconds"] + 30
    ) * 1000
    bucket_start_counts = _mapping(
        temporal_profile.get("bucket_start_counts"),
        f"{artifact}.temporal_profile.bucket_start_counts",
    )
    if any(
        not isinstance(value, int) or isinstance(value, bool)
        for value in bucket_start_counts.values()
    ):
        raise EvidenceError("remote_reader_soak_temporal_profile_invalid")
    if (
        temporal_profile.get("bucket_seconds") != bucket_seconds
        or temporal_profile.get("minimum_buckets") != minimum_buckets
        or temporal_profile.get("minimum_cases_per_bucket") != concurrency_peak
        or temporal_profile.get("scheduler_tolerance_seconds") != 30
        or bucket_start_counts != expected_bucket_counts
        or temporal_profile.get("covered_bucket_count") != minimum_buckets
        or temporal_profile.get("first_bucket_covered") is not True
        or temporal_profile.get("last_bucket_covered") is not True
        or any(count < concurrency_peak for count in expected_bucket_counts.values())
        or temporal_profile.get("maximum_start_gap_ms") != maximum_start_gap_ms
        or temporal_profile.get("maximum_allowed_start_gap_ms")
        != maximum_allowed_start_gap_ms
        or maximum_start_gap_ms > maximum_allowed_start_gap_ms
    ):
        raise EvidenceError("remote_reader_soak_temporal_coverage_insufficient")

    lifecycle = _remote_soak_object(
        top.get("capacity_lifecycle"),
        field=f"{artifact}.capacity_lifecycle",
        keys={
            "reservation_count",
            "activation_count",
            "release_count",
            "terminal_proven_count",
            "peak_held_cases",
            "held_bytes_leak_count",
            "stale_lease_count",
            "fence_conflict_count",
            "release_failure_count",
        },
        blocker="remote_reader_soak_capacity_lifecycle_invalid",
    )
    for field in (
        "reservation_count",
        "activation_count",
        "release_count",
        "terminal_proven_count",
    ):
        if lifecycle.get(field) != attempted:
            raise EvidenceError("remote_reader_soak_capacity_lifecycle_incomplete")
    if lifecycle.get("peak_held_cases") != concurrency_peak or any(
        lifecycle.get(field) != 0
        for field in (
            "held_bytes_leak_count",
            "stale_lease_count",
            "fence_conflict_count",
            "release_failure_count",
        )
    ):
        raise EvidenceError("remote_reader_soak_capacity_lifecycle_failure")

    latency = _remote_soak_object(
        top.get("latency_ms"),
        field=f"{artifact}.latency_ms",
        keys={"p50", "p95", "p99", "max"},
        blocker="remote_reader_soak_latency_invalid",
    )
    sorted_latencies = sorted(durations_ms)

    def percentile(percent: float) -> float:
        return float(sorted_latencies[max(0, math.ceil(percent * attempted) - 1)])

    expected_latency = {
        "p50": percentile(0.50),
        "p95": percentile(0.95),
        "p99": percentile(0.99),
        "max": float(sorted_latencies[-1]),
    }
    reported_latency = {
        field: _number(latency.get(field), f"{artifact}.latency_ms.{field}")
        for field in expected_latency
    }
    if reported_latency != expected_latency or reported_latency["max"] > 120_000:
        raise EvidenceError("remote_reader_soak_latency_slo_failed")

    throughput = _remote_soak_object(
        top.get("throughput"),
        field=f"{artifact}.throughput",
        keys={
            "messages_total",
            "bytes_total",
            "messages_per_second",
            "bytes_per_second",
        },
        blocker="remote_reader_soak_throughput_invalid",
    )
    messages_per_second = _number(
        throughput.get("messages_per_second"),
        f"{artifact}.throughput.messages_per_second",
    )
    bytes_per_second = _number(
        throughput.get("bytes_per_second"),
        f"{artifact}.throughput.bytes_per_second",
    )
    if (
        throughput.get("messages_total") != messages_total
        or throughput.get("bytes_total") != bytes_total
        or not math.isclose(
            messages_per_second, messages_total / duration, rel_tol=1e-12
        )
        or not math.isclose(bytes_per_second, bytes_total / duration, rel_tol=1e-12)
    ):
        raise EvidenceError("remote_reader_soak_throughput_inconsistent")

    resources = _remote_soak_object(
        top.get("resources"),
        field=f"{artifact}.resources",
        keys={
            "rss_peak_bytes",
            "fd_peak",
            "fd_limit",
            "open_reader_peak",
            "concurrency_peak",
        },
        blocker="remote_reader_soak_resources_invalid",
    )
    rss_peak = _exact_int(
        resources.get("rss_peak_bytes"),
        f"{artifact}.resources.rss_peak_bytes",
        minimum=1,
    )
    fd_peak = _exact_int(
        resources.get("fd_peak"), f"{artifact}.resources.fd_peak", minimum=1
    )
    fd_limit = _exact_int(
        resources.get("fd_limit"), f"{artifact}.resources.fd_limit", minimum=1
    )
    if (
        rss_peak > 4 * 1024**3
        or fd_peak >= fd_limit
        or fd_peak / fd_limit > 0.8
        or resources.get("open_reader_peak") != concurrency_peak
        or resources.get("concurrency_peak") != concurrency_peak
    ):
        raise EvidenceError("remote_reader_soak_resource_limit_failed")

    return {
        "observed_at": observed_at_text,
        "duration_seconds": duration,
        "attempted_cases": attempted,
        "completed_cases": completed,
        "target_cases_per_day": target_cases_per_day,
        "concurrency_peak": concurrency_peak,
        "candidate_commit": candidate["execution_commit"],
        "candidate_tree": candidate["execution_tree"],
        "module_sha256": module_sha256,
        "entrypoint_sha256": entrypoint_sha256,
        "schema_sha256": schema_sha256,
        "dependency_fingerprint": dependency_fingerprint,
        "reader_fingerprint": expected_reader_fingerprint,
        "soak_reader_fingerprint": soak_reader_fingerprint,
        "remote_reader_health_sha256": health_sha256,
        "dependency_doctor_sha256": dependency_doctor_sha256,
        "workload_manifest_sha256": manifest_sha256,
        "workload_manifest": manifest_detail,
        "case_merkle_root": merkle_root,
        "manifest_case_binding_sha256": manifest_case_binding_sha256,
        "workload_mix": {
            "reader_class_cases": expected_reader_counts,
            "function_domain_cases": expected_domain_counts,
            "reference_kind_cases": expected_reference_counts,
            "unique_work_items": len(work_item_ids),
            "unique_data_references": len(reference_bindings),
        },
        "concurrency_profile": dict(concurrency_profile),
        "temporal_profile": dict(temporal_profile),
        "capacity_lifecycle": dict(lifecycle),
        "latency_ms": expected_latency,
        "throughput": {
            "messages_total": messages_total,
            "bytes_total": bytes_total,
            "messages_per_second": messages_per_second,
            "bytes_per_second": bytes_per_second,
        },
        "resources": {
            "rss_peak_bytes": rss_peak,
            "fd_peak": fd_peak,
            "fd_limit": fd_limit,
            "open_reader_peak": concurrency_peak,
        },
        "zero_invariants": {key: 0 for key in sorted(expected_zero_keys)},
    }


def _check_canary_plan(
    body: Mapping[str, Any],
    *,
    expected_topic: str,
    expected_rule_version: str,
    configured_t0: Mapping[int, int],
    now: datetime,
    max_age_seconds: int,
) -> tuple[
    str,
    str,
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
]:
    artifact = "canary_plan"
    _require_schema(body, CANARY_PLAN_SCHEMA_VERSION, artifact)
    if set(body) != {
        "schema_version",
        "observed_at",
        "approved",
        "admission_mode",
        "promotion_budget",
        "slot_count",
        "slots",
        "topic",
        "creation_rule_version",
        "event_uid",
        "admission",
        "operator",
        "reason",
        "execution_request",
        "requested_scope",
    }:
        raise EvidenceError("canary_plan_shape_invalid")
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("approved") is not True:
        raise EvidenceError("canary_plan_not_approved")
    if body.get("admission_mode") != "direct_bounded":
        raise EvidenceError("canary_plan_admission_mode_invalid")
    if _exact_int(body.get("promotion_budget"), "canary_plan.promotion_budget") != 0:
        raise EvidenceError("canary_plan_promotion_limit_invalid")
    if _exact_int(body.get("slot_count"), "canary_plan.slot_count") != len(
        REQUIRED_ACTIVATION_SLOTS
    ):
        raise EvidenceError("canary_plan_slot_count_invalid")
    if body.get("topic") != expected_topic:
        raise EvidenceError("canary_plan_topic_mismatch")
    if body.get("creation_rule_version") != expected_rule_version:
        raise EvidenceError("canary_plan_rule_mismatch")
    try:
        admission = validate_rca_admission(
            _mapping(body.get("admission"), "canary_plan.admission")
        ).to_dict()
    except (EvidenceError, RcaAdmissionError) as exc:
        raise EvidenceError("canary_plan_admission_invalid") from exc
    event_uid = _required_text(body.get("event_uid"), "canary_plan.event_uid")
    parts = event_uid.rsplit(":", 2)
    if len(parts) != 3 or parts[0] != expected_topic:
        raise EvidenceError("canary_plan_event_uid_invalid")
    raw_partition, raw_offset = parts[1], parts[2]
    if (
        not raw_partition.isdigit()
        or not raw_offset.isdigit()
        or str(int(raw_partition)) != raw_partition
        or str(int(raw_offset)) != raw_offset
    ):
        raise EvidenceError("canary_plan_event_uid_invalid")
    partition = int(raw_partition)
    offset = int(raw_offset)
    if partition not in configured_t0:
        raise EvidenceError("canary_plan_partition_not_in_t0")
    if offset < configured_t0[partition]:
        raise EvidenceError("canary_plan_offset_before_t0")
    admission_refs = admission["source_refs"]
    if (
        admission.get("trigger_kind") != "issue_created"
        or admission.get("generation") != 1
        or admission_refs.get("topic") != expected_topic
        or admission_refs.get("partition") != partition
        or admission_refs.get("offset") != offset
        or admission_refs.get("rule_version") != expected_rule_version
    ):
        raise EvidenceError("canary_plan_admission_mismatch")
    raw_slots = _mapping(body.get("slots"), "canary_plan.slots")
    if set(raw_slots) != set(REQUIRED_ACTIVATION_SLOTS):
        raise EvidenceError("canary_plan_slot_set_invalid")
    expected_outcome = {
        "kafka_success": "success",
        "manual_success": "success",
        "manual_terminal_failure": "terminal_failed",
    }
    expected_entrypoint = {
        "kafka_success": "kafka_ingest",
        "manual_success": "manual_admit",
        "manual_terminal_failure": "manual_admit",
    }
    canonical_slots: dict[str, dict[str, Any]] = {}
    for slot_kind in sorted(REQUIRED_ACTIVATION_SLOTS):
        slot = _mapping(raw_slots.get(slot_kind), f"canary_plan.slots.{slot_kind}")
        if set(slot) != {
            "source_kind",
            "entrypoint",
            "source_identity",
            "source_identity_sha256",
            "max_admissions",
            "expected_admission",
            "expected_outcome",
        }:
            raise EvidenceError("canary_plan_slot_shape_invalid")
        source_kind = REQUIRED_ACTIVATION_SLOTS[slot_kind]
        if (
            slot.get("source_kind") != source_kind
            or slot.get("entrypoint") != expected_entrypoint[slot_kind]
            or slot.get("expected_outcome") != expected_outcome[slot_kind]
            or _exact_int(
                slot.get("max_admissions"),
                f"canary_plan.slots.{slot_kind}.max_admissions",
            )
            != 1
        ):
            raise EvidenceError("canary_plan_slot_contract_invalid")
        try:
            slot_admission = validate_rca_admission(
                _mapping(
                    slot.get("expected_admission"),
                    f"canary_plan.slots.{slot_kind}.expected_admission",
                )
            ).to_dict()
        except (EvidenceError, RcaAdmissionError) as exc:
            raise EvidenceError("canary_plan_slot_admission_invalid") from exc
        source_identity = _mapping(
            slot.get("source_identity"),
            f"canary_plan.slots.{slot_kind}.source_identity",
        )
        if source_kind == "kafka":
            if set(source_identity) != {"event_uid"}:
                raise EvidenceError("canary_plan_slot_identity_invalid")
            slot_event_uid = _required_text(
                source_identity.get("event_uid"),
                "canary_plan.slots.kafka_success.source_identity.event_uid",
            )
            if slot_event_uid != event_uid:
                raise EvidenceError("canary_plan_slot_identity_invalid")
            normalized_identity: dict[str, Any] = {
                "event_uid": event_uid,
                "offset": offset,
                "partition": partition,
                "topic": expected_topic,
            }
            if slot_admission != admission:
                raise EvidenceError("canary_plan_slot_admission_mismatch")
        else:
            manual_fields = {
                "chat_id",
                "requester_id",
                "message_id",
                "thread_id",
                "issue_url",
                "mode",
            }
            if set(source_identity) != manual_fields:
                raise EvidenceError("canary_plan_slot_identity_invalid")
            normalized_identity = {
                field: _required_text(
                    source_identity.get(field),
                    f"canary_plan.slots.{slot_kind}.source_identity.{field}",
                )
                for field in sorted(manual_fields)
            }
            normalized_identity["issue_url"] = normalized_identity[
                "issue_url"
            ].rstrip("/")
            refs = _mapping(
                slot_admission.get("source_refs"),
                f"canary_plan.slots.{slot_kind}.admission.source_refs",
            )
            expected_issue_url = (
                "https://project.feishu.cn/"
                f"{_required_text(refs.get('project_simple_name'), 'canary_plan.project_simple_name')}"
                "/issue/detail/"
                f"{_required_text(refs.get('work_item_id'), 'canary_plan.work_item_id')}"
            )
            if (
                slot_admission.get("trigger_kind") != "manual_issue_request"
                or slot_admission.get("generation") != 1
                or refs.get("topic") != ""
                or refs.get("partition") is not None
                or refs.get("offset") is not None
                or normalized_identity["chat_id"] != G1Q3_RCA_GROUP_ID
                or normalized_identity["thread_id"]
                != f"topic:{normalized_identity['message_id']}"
                or normalized_identity["issue_url"] != expected_issue_url
                or normalized_identity["mode"] != "run_or_join"
            ):
                raise EvidenceError("canary_plan_slot_identity_invalid")
        identity_sha256 = _sha256_json(normalized_identity)
        if slot.get("source_identity_sha256") != identity_sha256:
            raise EvidenceError("canary_plan_slot_identity_hash_invalid")
        canonical_slots[slot_kind] = {
            "source_kind": source_kind,
            "entrypoint": expected_entrypoint[slot_kind],
            "source_identity": normalized_identity,
            "source_identity_sha256": identity_sha256,
            "max_admissions": 1,
            "expected_admission": slot_admission,
            "expected_outcome": expected_outcome[slot_kind],
        }
    if (
        len(
            {
                slot["source_identity_sha256"]
                for slot in canonical_slots.values()
            }
        )
        != len(REQUIRED_ACTIVATION_SLOTS)
        or len(
            {
                slot["expected_admission"]["submission_key"]
                for slot in canonical_slots.values()
            }
        )
        != len(REQUIRED_ACTIVATION_SLOTS)
    ):
        raise EvidenceError("canary_plan_slots_not_independent")
    operator = _required_text(body.get("operator"), "canary_plan.operator")
    reason = _required_text(body.get("reason"), "canary_plan.reason")
    request_detail = _check_remote_execution_request(
        body.get("execution_request"),
        field="canary_plan.execution_request",
        expected_admission=admission,
        expected_origin_source_id=_stable_trigger_source_id(
            "kafka_workflow_event", event_uid
        ),
        expected_origin_storage_kind="kafka_workflow_event",
    )
    requested_scope = _check_requested_scope(
        body.get("requested_scope"), field="canary_plan.requested_scope"
    )
    return (
        event_uid,
        str(request_detail["request_sha256"]),
        admission,
        requested_scope,
        canonical_slots,
        {
            "observed_at": observed_at,
            "approved": True,
            "admission_mode": "direct_bounded",
            "promotion_budget": 0,
            "slot_count": len(canonical_slots),
            "slots": canonical_slots,
            "slots_sha256": _sha256_json(canonical_slots),
            "event_uid": event_uid,
            "partition": partition,
            "offset": offset,
            "t0_offset": configured_t0[partition],
            "operator": operator,
            "reason_sha256": hashlib.sha256(reason.encode("utf-8")).hexdigest(),
            "admission": {
                "business_key": admission["business_key"],
                "submission_key": admission["submission_key"],
                "generation": admission["generation"],
            },
            "execution_request": request_detail,
            "requested_scope": requested_scope,
        },
    )


def _check_remote_canary_read(
    value: Any,
    *,
    expected_reader_fingerprint: str,
    expected_reader_classes: Sequence[str],
    expected_requested_scope: Mapping[str, Any],
    expected_artifact_root: str,
) -> dict[str, Any]:
    wrapper = _mapping(value, "canary_receipt.remote_read")
    if set(wrapper) != {"reader_fingerprint", "receipt_sha256", "receipt"}:
        raise EvidenceError("canary_remote_read_wrapper_invalid")
    if wrapper.get("reader_fingerprint") != expected_reader_fingerprint:
        raise EvidenceError("canary_remote_read_fingerprint_mismatch")
    read = _mapping(wrapper.get("receipt"), "canary_receipt.remote_read.receipt")
    if wrapper.get("receipt_sha256") != _sha256_json(read):
        raise EvidenceError("canary_remote_read_receipt_hash_mismatch")
    expected_keys = {
        "schema_version",
        "mode",
        "read_strategy",
        "status",
        "completeness",
        "exhausted",
        "bounded",
        "requirements_hash",
        "requirements_contract_version",
        "requirements_contract_hash",
        "function_domain",
        "requested_topics",
        "requested_channels",
        "observed_channels",
        "topic_coverage",
        "requested_window",
        "reference_count",
        "references",
        "sampled_messages",
        "scanned_messages",
        "limits",
        "input_materialized",
        "mdi_download_attempted",
        "fallback_used",
        "derived_artifact_written",
        "downstream_full_rca_supported",
        "derived_stream_cache",
        "dependency",
        "execution_runtime",
        "data_access",
    }
    if set(read) != expected_keys:
        raise EvidenceError("canary_remote_read_receipt_shape_invalid")
    if (
        read.get("schema_version") != REMOTE_READ_RECEIPT_SCHEMA_VERSION
        or read.get("mode") != "remote_read"
        or read.get("read_strategy") != "bounded_remote_stream_cache"
        or read.get("status") != "completed"
    ):
        raise EvidenceError("canary_remote_read_not_completed")
    if (
        read.get("completeness") != FIXED_REMOTE_ACCESS_CONTRACT["completeness"]
        or read.get("exhausted") is not True
        or read.get("bounded") is not False
    ):
        raise EvidenceError("canary_remote_read_completeness_mismatch")
    if (
        read.get("input_materialized") is not False
        or read.get("mdi_download_attempted") is not False
        or read.get("fallback_used") is not False
    ):
        raise EvidenceError("canary_remote_read_mdi_invoked")
    if (
        read.get("derived_artifact_written") is not True
        or read.get("downstream_full_rca_supported") is not True
    ):
        raise EvidenceError("canary_remote_read_downstream_not_supported")

    requirements = _mapping(
        expected_requested_scope.get("requirements"),
        "canary_plan.requested_scope.requirements",
    )
    for field in (
        "requirements_hash",
        "requirements_contract_version",
        "requirements_contract_hash",
        "function_domain",
        "requested_topics",
        "requested_window",
    ):
        expected_field = "channel_allowlist" if field == "requested_channels" else field
        if read.get(field) != requirements.get(expected_field):
            raise EvidenceError("canary_remote_read_requested_scope_mismatch")
    requested_topics = read.get("requested_topics")
    requested_channels = read.get("requested_channels")
    observed_channels = read.get("observed_channels")
    if requested_channels != requirements.get("channel_allowlist"):
        raise EvidenceError("canary_remote_read_requested_scope_mismatch")
    if (
        not isinstance(observed_channels, list)
        or not observed_channels
        or observed_channels != sorted(set(observed_channels))
        or not set(observed_channels).issubset(set(requested_channels or []))
    ):
        raise EvidenceError("canary_remote_read_observed_channels_invalid")
    coverage = _mapping(
        read.get("topic_coverage"), "canary_receipt.remote_read.topic_coverage"
    )
    if set(coverage) != set(requested_topics or []):
        raise EvidenceError("canary_remote_read_topic_coverage_incomplete")
    covered_channels: set[str] = set()
    for topic in requested_topics:
        item = _mapping(coverage[topic], f"remote_read.topic_coverage.{topic}")
        if set(item) != {"allowed", "observed", "complete", "required"}:
            raise EvidenceError("canary_remote_read_topic_coverage_invalid")
        allowed = item.get("allowed")
        observed = item.get("observed")
        if (
            not isinstance(allowed, list)
            or not allowed
            or allowed != sorted(set(allowed))
            or not set(allowed).issubset(set(requested_channels))
            or not isinstance(observed, list)
            or not observed
            or observed != sorted(set(observed))
            or observed != sorted(set(allowed).intersection(observed_channels))
            or item.get("complete") is not True
            or item.get("required") is not True
        ):
            raise EvidenceError("canary_remote_read_topic_coverage_incomplete")
        covered_channels.update(observed)
    if covered_channels != set(observed_channels):
        raise EvidenceError("canary_remote_read_topic_coverage_invalid")

    limits = _mapping(read.get("limits"), "canary_receipt.remote_read.limits")
    expected_limits = {
        "max_clips": REMOTE_READ_MAX_CLIPS,
        "max_messages": REMOTE_READ_MAX_MESSAGES,
        "max_scanned_messages": REMOTE_READ_MAX_SCANNED_MESSAGES,
        "max_output_bytes": REMOTE_READ_MAX_OUTPUT_BYTES,
        "timeout_seconds": REMOTE_READ_TIMEOUT_SECONDS,
    }
    if limits != expected_limits:
        raise EvidenceError("canary_remote_read_limits_mismatch")

    references = read.get("references")
    reference_count = _exact_int(
        read.get("reference_count"),
        "canary_receipt.remote_read.reference_count",
        minimum=1,
    )
    if not isinstance(references, list) or len(references) != reference_count:
        raise EvidenceError("canary_remote_read_references_invalid")
    sampled_total = 0
    scanned_total = 0
    observed_reader_classes: set[str] = set()
    for index, raw_reference in enumerate(references):
        reference = _mapping(raw_reference, f"remote_read.references[{index}]")
        if set(reference) != {
            "kind",
            "reader_class",
            "reference_sha256",
            "sampled_messages",
            "scanned_messages",
            "status",
            "exhausted",
            "bounded",
            "scope_proof",
        }:
            raise EvidenceError("canary_remote_read_reference_shape_invalid")
        kind = reference.get("kind")
        reader_class = reference.get("reader_class")
        expected_reader = {
            "event": "RemoteEventReader",
            "clip": "RemoteClipReader",
        }.get(str(kind))
        if expected_reader is None or reader_class != expected_reader:
            raise EvidenceError("canary_remote_read_reader_class_mismatch")
        observed_reader_classes.add(str(reader_class))
        _sha256_digest(
            reference.get("reference_sha256"),
            f"remote_read.references[{index}].reference_sha256",
        )
        sampled_total += _exact_int(
            reference.get("sampled_messages"),
            f"remote_read.references[{index}].sampled_messages",
            minimum=0,
        )
        scanned_total += _exact_int(
            reference.get("scanned_messages"),
            f"remote_read.references[{index}].scanned_messages",
            minimum=0,
        )
        if (
            reference.get("status") != "exhausted"
            or reference.get("exhausted") is not True
            or reference.get("bounded") is not False
        ):
            raise EvidenceError("canary_remote_read_reference_not_exhausted")
        proof = _mapping(
            reference.get("scope_proof"),
            f"remote_read.references[{index}].scope_proof",
        )
        common_proof = {
            "schema_version",
            "kind",
            "complete",
            "limit_policy",
            "constructor_guard",
            "reader_source_sha256",
        }
        variant = (
            {"clip_count", "max_clips"}
            if kind == "event"
            else {"mcap_file_count", "mcap_file_limit"}
        )
        if set(proof) != common_proof | variant:
            raise EvidenceError("canary_remote_read_scope_proof_invalid")
        expected_guard = (
            "remote_event_clip_limit_exceeded"
            if kind == "event"
            else "remote_clip_mcap_limit_exceeded"
        )
        if (
            proof.get("schema_version") != REMOTE_SCOPE_PROOF_SCHEMA_VERSION
            or proof.get("kind") != kind
            or proof.get("complete") is not True
            or proof.get("limit_policy") != "reject_over_limit"
            or proof.get("constructor_guard") != expected_guard
        ):
            raise EvidenceError("canary_remote_read_scope_proof_invalid")
        _sha256_digest(
            proof.get("reader_source_sha256"),
            f"remote_read.references[{index}].scope_proof.reader_source_sha256",
        )
        if kind == "event":
            clip_count = _exact_int(
                proof.get("clip_count"), "remote_read.scope_proof.clip_count", minimum=1
            )
            if (
                proof.get("max_clips") != REMOTE_READ_MAX_CLIPS
                or clip_count > REMOTE_READ_MAX_CLIPS
            ):
                raise EvidenceError("canary_remote_read_scope_proof_invalid")
        elif proof.get("mcap_file_count") != 1 or proof.get("mcap_file_limit") != 1:
            raise EvidenceError("canary_remote_read_scope_proof_invalid")
    if observed_reader_classes != set(expected_reader_classes):
        raise EvidenceError("canary_remote_read_reader_class_mismatch")
    sampled_messages = _exact_int(
        read.get("sampled_messages"),
        "canary_receipt.remote_read.sampled_messages",
        minimum=1,
    )
    scanned_messages = _exact_int(
        read.get("scanned_messages"),
        "canary_receipt.remote_read.scanned_messages",
        minimum=sampled_messages,
    )
    if sampled_total != sampled_messages or scanned_total != scanned_messages:
        raise EvidenceError("canary_remote_read_message_count_mismatch")

    cache = _mapping(
        read.get("derived_stream_cache"),
        "canary_receipt.remote_read.derived_stream_cache",
    )
    if set(cache) != {
        "schema_version",
        "status",
        "kind",
        "path",
        "sha256",
        "bytes",
        "message_count",
        "schema_count",
        "channel_count",
        "atomic",
        "durable",
        *FIXED_CIFS_STORAGE_CONTRACT,
        "mount_evidence",
    }:
        raise EvidenceError("canary_remote_stream_cache_shape_invalid")
    expected_cache_path = f"{expected_artifact_root}{REMOTE_STREAM_CACHE_RELATIVE_PATH}"
    cache_bytes = _exact_int(
        cache.get("bytes"),
        "canary_receipt.remote_read.derived_stream_cache.bytes",
        minimum=1,
    )
    if (
        cache.get("schema_version") != REMOTE_STREAM_CACHE_SCHEMA_VERSION
        or cache.get("status") != "committed"
        or cache.get("kind") != "derived_remote_stream_cache"
        or cache.get("path") != expected_cache_path
        or cache_bytes > REMOTE_READ_MAX_OUTPUT_BYTES
        or cache.get("message_count") != sampled_messages
        or _exact_int(
            cache.get("schema_count"), "remote_stream_cache.schema_count", minimum=1
        )
        < 1
        or _exact_int(
            cache.get("channel_count"), "remote_stream_cache.channel_count", minimum=1
        )
        != len(observed_channels)
        or cache.get("atomic") is not True
        or cache.get("durable") is not True
    ):
        raise EvidenceError("canary_remote_stream_cache_invalid")
    _require_fixed_cifs_storage_contract(
        cache,
        field="canary_receipt.remote_read.derived_stream_cache",
        blocker="canary_remote_stream_cache_invalid",
    )
    cache_sha256 = _sha256_digest(
        cache.get("sha256"), "canary_receipt.remote_read.derived_stream_cache.sha256"
    )

    dependency = _mapping(
        read.get("dependency"), "canary_receipt.remote_read.dependency"
    )
    runtime = _mapping(
        read.get("execution_runtime"), "canary_receipt.remote_read.execution_runtime"
    )
    if dependency.get("status") != "ready" or dependency.get("runtime") != runtime:
        raise EvidenceError("canary_remote_read_dependency_invalid")
    if (
        runtime.get("execution_mode") != FIXED_REMOTE_READER_EXECUTION_MODE
        or runtime.get("dependency_domain") != FIXED_REMOTE_READER_DEPENDENCY_DOMAIN
        or runtime.get("required_python_executable")
        != FIXED_REMOTE_READER_REQUIRED_PYTHON
        or runtime.get("reader_import_scope") != FIXED_REMOTE_READER_IMPORT_SCOPE
        or runtime.get("timeout_seconds") != REMOTE_READ_TIMEOUT_SECONDS
    ):
        raise EvidenceError("canary_remote_read_runtime_mismatch")
    data_access = _mapping(
        read.get("data_access"), "canary_receipt.remote_read.data_access"
    )
    if (
        data_access.get("schema_version")
        != FIXED_REMOTE_ACCESS_CONTRACT["data_access_schema_version"]
        or data_access.get("mode") != "remote_read"
        or data_access.get("transport") != "pdcl_pyclip"
        or data_access.get("reference_count") != reference_count
        or sorted(data_access.get("reference_kinds") or [])
        != sorted({str(item["kind"]) for item in references})
        or re.search(
            r"\bmdi\b|event_uuid|clip_uuid", _canonical_json(data_access), re.I
        )
    ):
        raise EvidenceError("canary_remote_read_data_access_not_redacted")
    return {
        "status": "completed",
        "reader_fingerprint": expected_reader_fingerprint,
        "receipt_sha256": wrapper["receipt_sha256"],
        "requirements_hash": requirements["requirements_hash"],
        "requirements_contract_hash": requirements["requirements_contract_hash"],
        "function_domain": requirements["function_domain"],
        "requested_topics": requested_topics,
        "requested_channels": requested_channels,
        "observed_channels": observed_channels,
        "topic_coverage": dict(coverage),
        "requested_window": requirements["requested_window"],
        "reference_count": reference_count,
        "reader_classes": sorted(observed_reader_classes),
        "sampled_messages": sampled_messages,
        "scanned_messages": scanned_messages,
        "completeness": FIXED_REMOTE_ACCESS_CONTRACT["completeness"],
        "derived_stream_cache": {
            "path": expected_cache_path,
            "sha256": cache_sha256,
            "bytes": cache_bytes,
            "message_count": sampled_messages,
        },
        "derived_stream_cache_receipt": dict(cache),
        "input_materialized": False,
        "mdi_download_attempted": False,
        "fallback_used": False,
        "downstream_full_rca_supported": True,
    }


def _check_canary_capacity_lifecycle(
    value: Any,
    *,
    request_detail: Mapping[str, Any],
) -> dict[str, Any]:
    lifecycle = _mapping(value, "canary_receipt.derived_capacity_lifecycle")
    if set(lifecycle) != {
        "schema_version",
        "full_receipts",
        "reserved",
        "activate",
        "release",
        "audit",
    } or lifecycle.get("schema_version") != ("g1q3_rca_capacity_lifecycle_artifact_v2"):
        raise EvidenceError("canary_derived_capacity_lifecycle_shape_invalid")
    try:
        reservation_request = DerivedCapacityReservationRequest(
            submission_key=str(request_detail["submission_key"]),
            task_id=str(request_detail["submission_key"]),
            business_key=str(request_detail["business_key"]),
            data_access_sha256=str(request_detail["data_access_sha256"]),
            artifact_root=str(request_detail["artifact_root"]),
            expected_artifact_cache_bytes=(FIXED_STORAGE_EXPECTED_ARTIFACT_CACHE_BYTES),
        )
    except DerivedCapacityReservationError as exc:
        raise EvidenceError("canary_derived_capacity_request_invalid") from exc

    full_receipts = _mapping(
        lifecycle.get("full_receipts"),
        "canary_receipt.derived_capacity_lifecycle.full_receipts",
    )
    if set(full_receipts) != {"reserved", "activate", "release"}:
        raise EvidenceError("canary_derived_capacity_full_receipts_invalid")
    decisions = {}
    for stage, expected_status in (
        ("reserved", "reserved"),
        ("activate", "active"),
        ("release", "released"),
    ):
        try:
            decision = validate_derived_capacity_reservation_receipt(
                _mapping(
                    full_receipts.get(stage),
                    f"canary_receipt.derived_capacity_lifecycle.full_receipts.{stage}",
                ),
                reservation_request,
            )
        except (EvidenceError, DerivedCapacityReservationError) as exc:
            raise EvidenceError(
                f"canary_derived_capacity_{stage}_receipt_invalid"
            ) from exc
        if decision.status != expected_status:
            raise EvidenceError("canary_derived_capacity_transition_invalid")
        decisions[stage] = decision

    receipt_hashes: dict[str, str] = {}
    common_identity: tuple[str, str, int] | None = None
    safe_expected_operations = {
        "reserved": "reserve_reference",
        "activate": "activate",
        "release": "release",
    }
    for stage in ("reserved", "activate", "release"):
        receipt = decisions[stage].receipt
        reservation = receipt["reservation"]
        receipt_hash = _sha256_json(receipt)
        receipt_hashes[stage] = receipt_hash
        expected_safe = {
            "schema_version": "g1q3_rca_capacity_lifecycle_receipt_v1",
            "operation": safe_expected_operations[stage],
            "receipt_sha256": receipt_hash,
            "reservation_id": receipt["reservation_id"],
            "submission_key": receipt["submission_key"],
            "fence": receipt["fence"],
            "status": receipt["status"],
            "contract_sha256": receipt["contract_sha256"],
            "run_id": reservation["run_id"],
            "requested_bytes": reservation["requested_bytes"],
            "held_bytes": reservation["held_bytes"],
            "observed_at": receipt["observed_at"],
            "created_at": reservation["created_at"],
            "updated_at": reservation["updated_at"],
            "lease_expires_at": reservation["lease_expires_at"],
            "activated_at": reservation["activated_at"],
            "released_at": reservation["released_at"],
        }
        if lifecycle.get(stage) != expected_safe:
            raise EvidenceError("canary_derived_capacity_safe_receipt_mismatch")
        identity = (
            str(receipt["reservation_id"]),
            str(receipt["contract_sha256"]),
            int(receipt["fence"]),
        )
        if common_identity is None:
            common_identity = identity
        elif identity != common_identity:
            raise EvidenceError("canary_derived_capacity_identity_mismatch")

    reserved = decisions["reserved"].receipt["reservation"]
    active = decisions["activate"].receipt["reservation"]
    released = decisions["release"].receipt["reservation"]
    requested_bytes = reservation_request.requested_bytes
    zero_bytes = {"tmp": 0, "hfs": 0, "total": 0}
    if (
        reserved["run_id"] != ""
        or active["run_id"] != reservation_request.task_id
        or released["run_id"] != reservation_request.task_id
        or reserved["requested_bytes"] != requested_bytes
        or active["requested_bytes"] != requested_bytes
        or released["requested_bytes"] != requested_bytes
        or reserved["held_bytes"] != requested_bytes
        or active["held_bytes"] != requested_bytes
        or released["held_bytes"] != zero_bytes
        or reserved["lease_expires_at"] is None
        or active["lease_expires_at"] is None
        or released["lease_expires_at"] is not None
    ):
        raise EvidenceError("canary_derived_capacity_lifecycle_invalid")

    created = _timestamp(reserved["created_at"], "capacity.reserved.created_at")
    reserved_updated = _timestamp(
        reserved["updated_at"], "capacity.reserved.updated_at"
    )
    reserved_observed = _timestamp(
        decisions["reserved"].receipt["observed_at"],
        "capacity.reserved.observed_at",
    )
    activated = _timestamp(active["activated_at"], "capacity.active.activated_at")
    active_updated = _timestamp(active["updated_at"], "capacity.active.updated_at")
    active_observed = _timestamp(
        decisions["activate"].receipt["observed_at"],
        "capacity.active.observed_at",
    )
    released_at = _timestamp(released["released_at"], "capacity.released.released_at")
    released_updated = _timestamp(
        released["updated_at"], "capacity.released.updated_at"
    )
    released_observed = _timestamp(
        decisions["release"].receipt["observed_at"],
        "capacity.released.observed_at",
    )
    if not (
        created
        <= reserved_updated
        <= reserved_observed
        <= activated
        <= active_updated
        <= active_observed
        <= released_at
        <= released_updated
        <= released_observed
    ):
        raise EvidenceError("canary_derived_capacity_timestamps_not_monotonic")

    audit = _mapping(
        lifecycle.get("audit"), "canary_receipt.derived_capacity_lifecycle.audit"
    )
    expected_audit = {
        "schema_version": "g1q3_rca_capacity_lifecycle_audit_v2",
        "transition": ["reserved", "active", "released"],
        "full_receipts_present": True,
        "full_receipts_hash_match": True,
        "reserved_receipt_referenced": True,
        "all_receipts_referenced": True,
        "same_reservation_fence_contract": True,
        "same_active_release_run_id": True,
        "same_reservation_fence_contract_run": True,
        "same_requested_bytes": True,
        "held_preserved_until_release": True,
        "timestamps_monotonic": True,
        "lease_closed": True,
        "released_held_bytes_zero": True,
        "terminal_state": "released",
        "terminal_proven": True,
    }
    if audit != expected_audit:
        raise EvidenceError("canary_derived_capacity_audit_invalid")
    return {
        "status": "released",
        "reservation_id": common_identity[0] if common_identity else "",
        "contract_sha256": common_identity[1] if common_identity else "",
        "fence": common_identity[2] if common_identity else 0,
        "requested_bytes": requested_bytes,
        "released_held_bytes": zero_bytes,
        "receipt_sha256": receipt_hashes,
        "lifecycle_sha256": _sha256_json(lifecycle),
        "terminal_proven": True,
    }


def _artifact_path_under_root(value: Any, *, field: str, artifact_root: str) -> str:
    raw = _required_text(value, field)
    path = PurePosixPath(raw)
    root = PurePosixPath(artifact_root)
    if not path.is_absolute() or str(path) != raw or path == root:
        raise EvidenceError("canary_pipeline_artifact_path_invalid", field)
    try:
        path.relative_to(root)
    except ValueError as exc:
        raise EvidenceError("canary_pipeline_artifact_path_invalid", field) from exc
    return raw


def _meter_stage_bytes(value: Any, *, field: str) -> dict[str, int]:
    body = _mapping(value, field)
    if set(body) != {"tmp", "hfs"}:
        raise EvidenceError("canary_stage_capacity_bytes_invalid", field)
    return {
        target: _exact_int(body.get(target), f"{field}.{target}", minimum=0)
        for target in ("tmp", "hfs")
    }


def _check_stage_capacity_meter(
    value: Any,
    *,
    artifact_root: str,
    submission_key: str,
    capacity_lifecycle_detail: Mapping[str, Any],
    remote_read_detail: Mapping[str, Any],
) -> dict[str, Any]:
    wrapper = _mapping(value, "canary_receipt.capacity_meter")
    if set(wrapper) != {"path", "sha256", "receipt"}:
        raise EvidenceError("canary_stage_capacity_wrapper_invalid")
    expected_path = f"{artifact_root}{STAGE_CAPACITY_METER_RELATIVE_PATH}"
    if wrapper.get("path") != expected_path:
        raise EvidenceError("canary_stage_capacity_path_mismatch")
    meter = _mapping(wrapper.get("receipt"), "canary_receipt.capacity_meter.receipt")
    meter_sha256 = _sha256_digest(
        wrapper.get("sha256"), "canary_receipt.capacity_meter.sha256"
    )
    if meter_sha256 != _sha256_json(meter):
        raise EvidenceError("canary_stage_capacity_hash_mismatch")
    if set(meter) != {
        "schema_version",
        "status",
        "accounting",
        "identity",
        "limits",
        "baseline",
        "stages",
        "peaks",
        "within_budget",
        "terminal",
    }:
        raise EvidenceError("canary_stage_capacity_shape_invalid")
    if meter.get("schema_version") != STAGE_CAPACITY_METER_SCHEMA_VERSION:
        raise EvidenceError("canary_stage_capacity_schema_unsupported")
    if meter.get("status") != "completed" or meter.get("within_budget") is not True:
        raise EvidenceError("canary_stage_capacity_not_completed")

    accounting = _mapping(
        meter.get("accounting"), "canary_receipt.capacity_meter.accounting"
    )
    if set(accounting) != {"mode", "tmp_root", "hfs_root", "relationship"}:
        raise EvidenceError("canary_stage_capacity_accounting_invalid")
    expected_tmp_root = artifact_root.rstrip("/")
    raw_hfs_root = _required_text(
        accounting.get("hfs_root"), "canary_receipt.capacity_meter.accounting.hfs_root"
    )
    hfs_path = PurePosixPath(raw_hfs_root)
    cases_root = PurePosixPath(expected_tmp_root) / "cases"
    try:
        case_relative = hfs_path.relative_to(cases_root)
    except ValueError as exc:
        raise EvidenceError("canary_stage_capacity_accounting_invalid") from exc
    if (
        accounting.get("mode") != STAGE_CAPACITY_ACCOUNTING_MODE
        or accounting.get("tmp_root") != expected_tmp_root
        or accounting.get("relationship") != "hfs_nested_in_tmp"
        or not hfs_path.is_absolute()
        or str(hfs_path) != raw_hfs_root
        or len(case_relative.parts) != 1
        or case_relative.name in {"", ".", ".."}
    ):
        raise EvidenceError("canary_stage_capacity_accounting_invalid")

    identity = _mapping(meter.get("identity"), "canary_receipt.capacity_meter.identity")
    if set(identity) != {
        "reservation_id",
        "submission_key",
        "fence",
        "contract_sha256",
        "run_id",
    }:
        raise EvidenceError("canary_stage_capacity_identity_mismatch")
    if identity != {
        "reservation_id": capacity_lifecycle_detail["reservation_id"],
        "submission_key": submission_key,
        "fence": capacity_lifecycle_detail["fence"],
        "contract_sha256": capacity_lifecycle_detail["contract_sha256"],
        "run_id": submission_key,
    }:
        raise EvidenceError("canary_stage_capacity_identity_mismatch")

    requested_bytes = _mapping(
        capacity_lifecycle_detail.get("requested_bytes"),
        "canary_receipt.derived_capacity_lifecycle.requested_bytes",
    )
    expected_limits = {
        "tmp_bytes": requested_bytes.get("tmp"),
        "hfs_bytes": requested_bytes.get("hfs"),
    }
    limits = _mapping(meter.get("limits"), "canary_receipt.capacity_meter.limits")
    if limits != expected_limits or any(
        not isinstance(value, int) or isinstance(value, bool) or value <= 0
        for value in limits.values()
    ):
        raise EvidenceError("canary_stage_capacity_limits_mismatch")

    baseline = _mapping(meter.get("baseline"), "canary_receipt.capacity_meter.baseline")
    if set(baseline) != {"created_at", "tmp_bytes", "hfs_bytes"}:
        raise EvidenceError("canary_stage_capacity_baseline_invalid")
    baseline_at = _timestamp(
        baseline.get("created_at"), "canary_receipt.capacity_meter.baseline.created_at"
    )
    for target in ("tmp", "hfs"):
        _exact_int(
            baseline.get(f"{target}_bytes"),
            f"canary_receipt.capacity_meter.baseline.{target}_bytes",
            minimum=0,
        )

    stages = _mapping(meter.get("stages"), "canary_receipt.capacity_meter.stages")
    if set(stages) != set(REQUIRED_CAPACITY_METER_STAGES):
        raise EvidenceError("canary_stage_capacity_stages_incomplete")
    previous_finished_at = baseline_at
    stage_details: dict[str, dict[str, Any]] = {}
    peak_observed = {"tmp": 0, "hfs": 0}
    previous_peak = {"tmp": 0, "hfs": 0}
    for stage_name in REQUIRED_CAPACITY_METER_STAGES:
        stage = _mapping(
            stages.get(stage_name),
            f"canary_receipt.capacity_meter.stages.{stage_name}",
        )
        if set(stage) != {
            "status",
            "finished_at",
            "artifact_receipt_path",
            "observed_bytes",
            "delta_bytes",
            "peak_delta_bytes",
            "within_budget",
        }:
            raise EvidenceError("canary_stage_capacity_stage_shape_invalid", stage_name)
        if stage.get("status") != "completed" or stage.get("within_budget") is not True:
            raise EvidenceError("canary_stage_capacity_stage_failed", stage_name)
        finished_at = _timestamp(
            stage.get("finished_at"),
            f"canary_receipt.capacity_meter.stages.{stage_name}.finished_at",
        )
        if finished_at < previous_finished_at:
            raise EvidenceError("canary_stage_capacity_timestamps_not_monotonic")
        previous_finished_at = finished_at
        receipt_path = _artifact_path_under_root(
            stage.get("artifact_receipt_path"),
            field=f"canary_receipt.capacity_meter.stages.{stage_name}.artifact_receipt_path",
            artifact_root=artifact_root,
        )
        observed = _meter_stage_bytes(
            stage.get("observed_bytes"),
            field=f"canary_receipt.capacity_meter.stages.{stage_name}.observed_bytes",
        )
        delta = _meter_stage_bytes(
            stage.get("delta_bytes"),
            field=f"canary_receipt.capacity_meter.stages.{stage_name}.delta_bytes",
        )
        peak = _meter_stage_bytes(
            stage.get("peak_delta_bytes"),
            field=f"canary_receipt.capacity_meter.stages.{stage_name}.peak_delta_bytes",
        )
        for target in ("tmp", "hfs"):
            if observed[target] < delta[target] or delta[target] > peak[target]:
                raise EvidenceError("canary_stage_capacity_bytes_invalid", stage_name)
            if peak[target] < previous_peak[target]:
                raise EvidenceError("canary_stage_capacity_peak_regressed", stage_name)
            if peak[target] > limits[f"{target}_bytes"]:
                raise EvidenceError("canary_stage_capacity_budget_exceeded", stage_name)
            peak_observed[target] = max(peak_observed[target], peak[target])
            previous_peak[target] = peak[target]
        stage_details[stage_name] = {
            "status": "completed",
            "finished_at": stage["finished_at"],
            "artifact_receipt_path": receipt_path,
            "observed_bytes": observed,
            "delta_bytes": delta,
            "peak_delta_bytes": peak,
        }

    peaks = _mapping(meter.get("peaks"), "canary_receipt.capacity_meter.peaks")
    if peaks != {
        "tmp_bytes": peak_observed["tmp"],
        "hfs_bytes": peak_observed["hfs"],
    }:
        raise EvidenceError("canary_stage_capacity_peaks_mismatch")
    if (
        stage_details["s2_remote_read"]["peak_delta_bytes"]["tmp"]
        < (remote_read_detail["derived_stream_cache"]["bytes"])
    ):
        raise EvidenceError("canary_stage_capacity_remote_cache_unmetered")

    terminal = _mapping(meter.get("terminal"), "canary_receipt.capacity_meter.terminal")
    if set(terminal) != {"tmp_cache", "hfs_artifacts"}:
        raise EvidenceError("canary_stage_capacity_terminal_invalid")
    tmp_cache = _mapping(
        terminal.get("tmp_cache"), "canary_receipt.capacity_meter.terminal.tmp_cache"
    )
    hfs_artifacts = _mapping(
        terminal.get("hfs_artifacts"),
        "canary_receipt.capacity_meter.terminal.hfs_artifacts",
    )
    if set(tmp_cache) != {"state", "bytes", "cleanup_policy"} or set(hfs_artifacts) != {
        "state",
        "bytes",
        "admission_policy",
    }:
        raise EvidenceError("canary_stage_capacity_terminal_invalid")
    tmp_bytes = _exact_int(
        tmp_cache.get("bytes"),
        "canary_receipt.capacity_meter.terminal.tmp_cache.bytes",
        minimum=1,
    )
    hfs_bytes = _exact_int(
        hfs_artifacts.get("bytes"),
        "canary_receipt.capacity_meter.terminal.hfs_artifacts.bytes",
        minimum=1,
    )
    if (
        tmp_cache.get("state") != "retained"
        or tmp_cache.get("cleanup_policy")
        != "retain_until_pipeline_terminal_then_governed_cleanup"
        or hfs_artifacts.get("state") != "retained"
        or hfs_artifacts.get("admission_policy")
        != "live_free_space_after_reservation_release"
        or tmp_bytes < remote_read_detail["derived_stream_cache"]["bytes"]
        or tmp_bytes > limits["tmp_bytes"]
        or hfs_bytes > limits["hfs_bytes"]
    ):
        raise EvidenceError("canary_stage_capacity_terminal_invalid")
    if stage_details["s2_remote_read"]["artifact_receipt_path"] != (
        f"{artifact_root}{REMOTE_READ_RECEIPT_RELATIVE_PATH}"
    ):
        raise EvidenceError("canary_stage_capacity_remote_read_stage_mismatch")
    return {
        "path": expected_path,
        "sha256": meter_sha256,
        "status": "completed",
        "accounting": dict(accounting),
        "identity": dict(identity),
        "limits": dict(limits),
        "stages": stage_details,
        "peaks": dict(peaks),
        "within_budget": True,
        "terminal": dict(terminal),
    }


def _check_pipeline_projection(
    value: Any,
    *,
    artifact_root: str,
    remote_read_detail: Mapping[str, Any],
    capacity_meter_detail: Mapping[str, Any],
) -> dict[str, Any]:
    pipeline = _mapping(value, "canary_receipt.pipeline")
    required_keys = {
        "status",
        "stage",
        "blocker",
        "remote_read_receipt",
        "remote_stream_cache",
        "downstream_stage_receipts",
        "capacity_usage",
    }
    if set(pipeline) != required_keys:
        raise EvidenceError("canary_pipeline_shape_invalid")
    if any(re.search(r"mdi|download", str(key), re.I) for key in pipeline):
        raise EvidenceError("canary_pipeline_legacy_download_field_present")
    if (
        pipeline.get("status") != "report_generated_need_review"
        or pipeline.get("stage") != "s6_report"
        or pipeline.get("blocker") is not None
    ):
        raise EvidenceError("canary_pipeline_not_completed")

    remote_receipt = _mapping(
        pipeline.get("remote_read_receipt"),
        "canary_receipt.pipeline.remote_read_receipt",
    )
    if remote_receipt != {
        "path": f"{artifact_root}{REMOTE_READ_RECEIPT_RELATIVE_PATH}",
        "sha256": remote_read_detail["receipt_sha256"],
    }:
        raise EvidenceError("canary_pipeline_remote_read_receipt_mismatch")
    if (
        pipeline.get("remote_stream_cache")
        != remote_read_detail["derived_stream_cache_receipt"]
    ):
        raise EvidenceError("canary_pipeline_remote_stream_cache_mismatch")

    downstream = _mapping(
        pipeline.get("downstream_stage_receipts"),
        "canary_receipt.pipeline.downstream_stage_receipts",
    )
    if set(downstream) != set(REQUIRED_DOWNSTREAM_STAGES):
        raise EvidenceError("canary_pipeline_downstream_stages_incomplete")
    normalized_downstream: dict[str, dict[str, Any]] = {}
    for stage_name in REQUIRED_DOWNSTREAM_STAGES:
        stage = _mapping(
            downstream.get(stage_name),
            f"canary_receipt.pipeline.downstream_stage_receipts.{stage_name}",
        )
        if set(stage) != {
            "status",
            "finished_at",
            "artifact_receipt_path",
            "artifact_receipt_sha256",
            "lineage",
        }:
            raise EvidenceError("canary_pipeline_downstream_stage_invalid", stage_name)
        receipt_path = _artifact_path_under_root(
            stage.get("artifact_receipt_path"),
            field=(
                "canary_receipt.pipeline.downstream_stage_receipts."
                f"{stage_name}.artifact_receipt_path"
            ),
            artifact_root=artifact_root,
        )
        expected_receipt_path = (
            f"{artifact_root}{stage_lineage_relative_path(stage_name)}"
        )
        meter_stage = capacity_meter_detail["stages"][
            RCA_STAGE_NAME_BY_SHORT[stage_name]
        ]
        try:
            lineage = validate_stage_lineage_receipt(
                stage.get("lineage"),
                expected_stage=RCA_STAGE_NAME_BY_SHORT[stage_name],
                artifact_root=artifact_root,
            )
        except StageLineageError as exc:
            raise EvidenceError(f"canary_{exc.code}", exc.detail) from exc
        if (
            stage.get("status") != "completed"
            or stage.get("finished_at") != meter_stage["finished_at"]
            or receipt_path != meter_stage["artifact_receipt_path"]
            or receipt_path != expected_receipt_path
            or lineage["finished_at"] != stage.get("finished_at")
        ):
            raise EvidenceError("canary_pipeline_downstream_stage_invalid", stage_name)
        normalized_downstream[stage_name] = {
            "status": "completed",
            "finished_at": stage["finished_at"],
            "artifact_receipt_path": receipt_path,
            "artifact_receipt_sha256": _sha256_digest(
                stage.get("artifact_receipt_sha256"),
                f"canary_receipt.pipeline.downstream_stage_receipts.{stage_name}.artifact_receipt_sha256",
            ),
            "lineage": lineage,
        }

    capacity_usage = _mapping(
        pipeline.get("capacity_usage"), "canary_receipt.pipeline.capacity_usage"
    )
    expected_capacity_usage = {
        "path": capacity_meter_detail["path"],
        "sha256": capacity_meter_detail["sha256"],
        "status": "completed",
        "within_budget": True,
        "limits": capacity_meter_detail["limits"],
        "peaks": capacity_meter_detail["peaks"],
        "terminal": capacity_meter_detail["terminal"],
    }
    if capacity_usage != expected_capacity_usage:
        raise EvidenceError("canary_pipeline_capacity_usage_mismatch")
    return {
        "status": "report_generated_need_review",
        "stage": "s6_report",
        "remote_read_receipt": dict(remote_receipt),
        "remote_stream_cache_sha256": remote_read_detail["derived_stream_cache"][
            "sha256"
        ],
        "downstream_stage_receipts": normalized_downstream,
        "capacity_usage": expected_capacity_usage,
    }


def _check_canary_capacity_admission(
    value: Any,
    *,
    expected_capacity_mode: str | None,
    expected_release_bom_sha256: str,
    now: datetime,
) -> dict[str, Any]:
    capacity = _mapping(value, "canary_receipt.vm.capacity_admission")
    base_fields = {
        "resource_class",
        "capacity_mode",
        "task_meta_sha256",
        "admission_receipt_sha256",
        "admission_schema_version",
        "admission_key_fingerprint",
        "queue_if_blocked",
        "resource_gate_bypass",
    }
    bootstrap_fields = {
        "bootstrap_epoch_id",
        "bootstrap_started_at",
        "bootstrap_deadline",
        "bootstrap_authorization_fingerprint",
        "release_bom_sha256",
        "release_approval_id",
        "max_concurrency",
        "daily_started_attempt_quota",
        "quota_timezone",
        "root_required_available_bytes",
        "delivery_required_available_bytes",
    }
    schema_version = str(capacity.get("admission_schema_version") or "")
    if schema_version == prod_admission.SCHEMA_VERSION:
        derived_mode = "steady"
        expected_fields = base_fields
    elif schema_version == prod_admission.BOOTSTRAP_SCHEMA_VERSION:
        derived_mode = "bootstrap"
        expected_fields = base_fields | bootstrap_fields
    else:
        raise EvidenceError("canary_vm_capacity_admission_schema_invalid")
    if (
        set(capacity) != expected_fields
        or capacity.get("resource_class") != "rca_prod"
        or capacity.get("capacity_mode") != derived_mode
        or capacity.get("admission_schema_version") != schema_version
        or capacity.get("queue_if_blocked") is not False
        or capacity.get("resource_gate_bypass") is not False
        or (expected_capacity_mode is not None and derived_mode != expected_capacity_mode)
    ):
        raise EvidenceError("canary_vm_capacity_admission_mode_mismatch")
    task_meta_sha256 = _sha256_digest(
        capacity.get("task_meta_sha256"),
        "canary_receipt.vm.capacity_admission.task_meta_sha256",
    )
    admission_receipt_sha256 = _sha256_digest(
        capacity.get("admission_receipt_sha256"),
        "canary_receipt.vm.capacity_admission.admission_receipt_sha256",
    )
    admission_key_fingerprint = _sha256_digest(
        capacity.get("admission_key_fingerprint"),
        "canary_receipt.vm.capacity_admission.admission_key_fingerprint",
    )
    detail = {
        "resource_class": "rca_prod",
        "capacity_mode": derived_mode,
        "task_meta_sha256": task_meta_sha256,
        "admission_receipt_sha256": admission_receipt_sha256,
        "admission_schema_version": schema_version,
        "admission_key_fingerprint": admission_key_fingerprint,
        "queue_if_blocked": False,
        "resource_gate_bypass": False,
    }
    if derived_mode == "bootstrap":
        fixed_bootstrap = {
            "max_concurrency": prod_bootstrap.MAX_CONCURRENCY,
            "daily_started_attempt_quota": (
                prod_bootstrap.DAILY_STARTED_ATTEMPT_QUOTA
            ),
            "quota_timezone": prod_bootstrap.QUOTA_TIMEZONE,
            "root_required_available_bytes": (
                prod_bootstrap.ROOT_REQUIRED_AVAILABLE_BYTES
            ),
            "delivery_required_available_bytes": (
                prod_bootstrap.DELIVERY_REQUIRED_AVAILABLE_BYTES
            ),
        }
        if any(
            capacity.get(field) != expected
            for field, expected in fixed_bootstrap.items()
        ):
            raise EvidenceError("canary_vm_bootstrap_capacity_binding_mismatch")
        epoch_id = _required_text(
            capacity.get("bootstrap_epoch_id"),
            "canary_receipt.vm.capacity_admission.bootstrap_epoch_id",
        )
        if prod_bootstrap.EPOCH_ID_RE.fullmatch(epoch_id) is None:
            raise EvidenceError("canary_vm_bootstrap_epoch_invalid")
        authorization_fingerprint = _sha256_digest(
            capacity.get("bootstrap_authorization_fingerprint"),
            "canary_receipt.vm.capacity_admission.bootstrap_authorization_fingerprint",
        )
        release_bom_sha256 = _sha256_digest(
            capacity.get("release_bom_sha256"),
            "canary_receipt.vm.capacity_admission.release_bom_sha256",
        )
        release_approval_id = _required_text(
            capacity.get("release_approval_id"),
            "canary_receipt.vm.capacity_admission.release_approval_id",
        )
        if expected_release_bom_sha256 and (
            release_bom_sha256 != expected_release_bom_sha256
        ):
            raise EvidenceError("canary_vm_bootstrap_release_bom_mismatch")
        try:
            started_at = prod_admission._timestamp(
                capacity.get("bootstrap_started_at")
            )
            deadline = prod_admission._timestamp(
                capacity.get("bootstrap_deadline")
            )
        except (TypeError, ValueError, OverflowError) as exc:
            raise EvidenceError("canary_vm_bootstrap_window_invalid") from exc
        if (
            deadline <= started_at
            or deadline - started_at > prod_bootstrap.MAX_EPOCH_DURATION
            or (
                expected_capacity_mode == "bootstrap"
                and not (started_at <= now <= deadline)
            )
        ):
            raise EvidenceError("canary_vm_bootstrap_window_invalid")
        detail.update({
            "bootstrap_epoch_id": epoch_id,
            "bootstrap_started_at": started_at.isoformat(),
            "bootstrap_deadline": deadline.isoformat(),
            "bootstrap_authorization_fingerprint": authorization_fingerprint,
            "release_bom_sha256": release_bom_sha256,
            "release_approval_id": release_approval_id,
            **fixed_bootstrap,
        })
    return detail


def _read_bootstrap_release_artifact(
    evidence_dir: Path,
    filename: str,
    *,
    evidence_hashes: dict[str, str],
) -> tuple[dict[str, Any], dict[str, Any]]:
    artifact = Path(filename).stem
    path = (evidence_dir / filename).expanduser().absolute()
    try:
        raw, info = _stable_regular_file_observation(
            path,
            artifact=artifact,
            expected_mode=0o600,
            require_owner=True,
        )
        body = _mapping(
            _strict_json_loads(raw.decode("utf-8"), artifact=artifact),
            artifact,
        )
    except EvidenceError:
        raise
    except UnicodeError as exc:
        raise EvidenceError(f"{artifact}_invalid_json") from exc
    raw_sha256 = hashlib.sha256(raw).hexdigest()
    evidence_hashes[filename] = raw_sha256
    return dict(body), {
        "sha256": raw_sha256,
        "size_bytes": len(raw),
        "device": info.st_dev,
        "inode": info.st_ino,
        "owner_uid": info.st_uid,
        "mode": stat.S_IMODE(info.st_mode),
    }


def _check_bootstrap_capacity_authorization(
    *,
    dispatcher: DispatcherConfig,
    evidence_dir: Path,
    evidence_hashes: dict[str, str],
    expected_release_bom_sha256: str,
    now: datetime,
    require_producer_window: bool = False,
) -> dict[str, Any]:
    if dispatcher.capacity_mode != "bootstrap":
        raise EvidenceError("bootstrap_capacity_dispatcher_mode_mismatch")
    release_plan, plan_observation = _read_bootstrap_release_artifact(
        evidence_dir,
        "release_plan.json",
        evidence_hashes=evidence_hashes,
    )
    manifest, manifest_observation = _read_bootstrap_release_artifact(
        evidence_dir,
        "release_prepare_manifest.json",
        evidence_hashes=evidence_hashes,
    )
    if set(manifest) != {
        "schema_version",
        "release_id",
        "created_at",
        "complete",
        "plan_only",
        "run_identity",
        "artifacts",
        "approval_receipt_sha256",
        "approval_request_sha256",
        "release_bom_sha256",
        "workspace_runtime_sha256",
        "future_runtime_sha256",
        "action_set_sha256",
        "side_effect_contract",
    } or (
        manifest.get("schema_version")
        != RELEASE_PREPARE_FINAL_MANIFEST_SCHEMA_VERSION
        or manifest.get("complete") is not True
        or manifest.get("plan_only") is not True
    ):
        raise EvidenceError("bootstrap_capacity_release_manifest_invalid")
    if set(release_plan) != {
        "schema_version",
        "release_id",
        "created_at",
        "mode",
        "executed",
        "approval",
        "bindings",
        "candidate_plist_sha256",
        "workspace_governance",
        "external_dependencies",
        "action_set",
        "action_set_sha256",
        "gate_validation",
        "rollback",
        "side_effect_contract",
    } or (
        release_plan.get("schema_version") != RELEASE_PREPARE_PLAN_SCHEMA_VERSION
        or release_plan.get("mode") != "plan_only"
        or release_plan.get("executed") is not False
    ):
        raise EvidenceError("bootstrap_capacity_release_plan_invalid")
    release_id = _required_text(
        manifest.get("release_id"), "bootstrap_capacity.release_id"
    )
    if (
        release_plan.get("release_id") != release_id
        or release_plan.get("created_at") != manifest.get("created_at")
    ):
        raise EvidenceError("bootstrap_capacity_release_identity_mismatch")
    _timestamp(manifest.get("created_at"), "bootstrap_capacity.created_at")
    approval_receipt_sha256 = _sha256_digest(
        manifest.get("approval_receipt_sha256"),
        "bootstrap_capacity.approval_receipt_sha256",
    )
    release_bom_sha256 = _sha256_digest(
        manifest.get("release_bom_sha256"),
        "bootstrap_capacity.release_bom_sha256",
    )
    plan_approval = _mapping(
        release_plan.get("approval"), "bootstrap_capacity.release_plan.approval"
    )
    plan_bindings = _mapping(
        release_plan.get("bindings"), "bootstrap_capacity.release_plan.bindings"
    )
    if (
        plan_approval.get("receipt_sha256") != approval_receipt_sha256
        or plan_bindings.get("release_bom_sha256") != release_bom_sha256
        or release_bom_sha256 != expected_release_bom_sha256
        or dispatcher.release_id != release_id
        or release_plan.get("action_set") != list(RELEASE_PREPARE_ACTION_SET)
        or release_plan.get("action_set_sha256")
        != _sha256_json(list(RELEASE_PREPARE_ACTION_SET))
        or manifest.get("action_set_sha256")
        != _sha256_json(list(RELEASE_PREPARE_ACTION_SET))
    ):
        raise EvidenceError("bootstrap_capacity_release_binding_mismatch")
    artifacts = _mapping(
        manifest.get("artifacts"), "bootstrap_capacity.release_manifest.artifacts"
    )
    if set(artifacts) != {
        "build_manifest.json",
        "cutover_plan.json",
        "release_plan.json",
    }:
        raise EvidenceError("bootstrap_capacity_release_artifacts_invalid")
    for filename in sorted(artifacts):
        descriptor = _mapping(
            artifacts.get(filename),
            f"bootstrap_capacity.release_manifest.artifacts.{filename}",
        )
        if set(descriptor) != {"sha256", "size_bytes", "schema_version"}:
            raise EvidenceError("bootstrap_capacity_release_artifacts_invalid")
        if filename == "release_plan.json":
            observation = plan_observation
            body = release_plan
        else:
            body, observation = _read_bootstrap_release_artifact(
                evidence_dir,
                filename,
                evidence_hashes=evidence_hashes,
            )
        if descriptor != {
            "sha256": observation["sha256"],
            "size_bytes": observation["size_bytes"],
            "schema_version": body.get("schema_version"),
        }:
            raise EvidenceError("bootstrap_capacity_release_artifacts_invalid")
    try:
        authorization = prod_bootstrap.load_bootstrap_authorization(
            now=now,
            expected_epoch_id=dispatcher.bootstrap_epoch_id,
            expected_release_bom_sha256=release_bom_sha256,
            expected_release_approval_id=dispatcher.release_id,
            expected_approval_evidence_sha256=approval_receipt_sha256,
        )
    except prod_bootstrap.RcaBootstrapAuthorizationError as exc:
        raise EvidenceError(f"bootstrap_capacity_{exc.code}") from exc
    if (
        authorization.get("bootstrap_epoch_id") != dispatcher.bootstrap_epoch_id
        or authorization.get("release_bom_sha256") != release_bom_sha256
        or authorization.get("release_approval_id") != release_id
        or authorization.get("approval_evidence_sha256")
        != approval_receipt_sha256
    ):
        raise EvidenceError("bootstrap_capacity_live_binding_mismatch")
    try:
        active_binding = prod_bootstrap.load_active_release_binding(
            path=dispatcher.active_release_binding_path,
            live_env_path=dispatcher.live_env_path,
            expected_release_id=release_id,
            expected_epoch_id=dispatcher.bootstrap_epoch_id,
        )
    except prod_bootstrap.RcaBootstrapAuthorizationError as exc:
        raise EvidenceError(f"bootstrap_capacity_{exc.code}") from exc
    if (
        active_binding.get("release_bom_sha256") != release_bom_sha256
        or active_binding.get("approval_evidence_sha256")
        != approval_receipt_sha256
        or active_binding.get("authorization_receipt_sha256")
        != authorization.get("authorization_receipt_sha256")
        or active_binding.get("authorization_fingerprint")
        != authorization.get("receipt_fingerprint")
    ):
        raise EvidenceError("bootstrap_capacity_active_release_binding_mismatch")
    producer_detail: dict[str, Any] | None = None
    if require_producer_window:
        producer_path = capacity_runtime.CapacityRuntimePaths.from_control_db(
            dispatcher.control_db_path
        ).producer_activation
        try:
            producer_path.lstat()
        except FileNotFoundError as exc:
            raise EvidenceError(
                "bootstrap_capacity_producer_receipt_required"
            ) from exc
        except OSError as exc:
            raise EvidenceError(
                "bootstrap_capacity_producer_receipt_invalid"
            ) from exc
        try:
            hmac_key = capacity_runtime.load_capacity_hmac_key()
            producer_receipt, producer_raw_sha256 = (
                capacity_evidence.read_and_validate_producer_activation(
                    producer_path,
                    hmac_key=hmac_key,
                    expected_release_id=release_id,
                    expected_bootstrap_epoch_id=dispatcher.bootstrap_epoch_id,
                    expected_release_bom_sha256=release_bom_sha256,
                    expected_active_release_binding_sha256=str(
                        active_binding["binding_receipt_sha256"]
                    ),
                )
            )
        except capacity_runtime.CapacityRuntimeError as exc:
            raise EvidenceError(f"bootstrap_capacity_{exc.code}") from exc
        except capacity_evidence.CapacitySampleEvidenceError as exc:
            raise EvidenceError(
                f"bootstrap_capacity_{exc.code}"
            ) from exc
        started_at = prod_admission._timestamp(authorization.get("started_at"))
        deadline = prod_admission._timestamp(authorization.get("deadline"))
        activated_at = prod_admission._timestamp(
            producer_receipt.get("activated_at")
        )
        if not started_at <= activated_at <= deadline:
            raise EvidenceError("bootstrap_capacity_producer_receipt_time_invalid")
        try:
            window = capacity_transition.validate_producer_deadline_window(
                activated_at=activated_at,
                deadline=deadline,
            )
        except capacity_transition.CapacityTransitionError as exc:
            if exc.code == "rca_capacity_producer_window_insufficient":
                raise EvidenceError(
                    "bootstrap_capacity_producer_window_insufficient"
                ) from exc
            raise EvidenceError(
                "bootstrap_capacity_producer_receipt_time_invalid"
            ) from exc
        try:
            live_horizon = capacity_transition.validate_producer_live_horizon(
                observed_at=now,
                deadline=deadline,
            )
        except capacity_transition.CapacityTransitionError as exc:
            if exc.code == "rca_capacity_producer_horizon_insufficient":
                raise EvidenceError(
                    "bootstrap_capacity_producer_horizon_insufficient"
                ) from exc
            raise EvidenceError(
                "bootstrap_capacity_producer_receipt_time_invalid"
            ) from exc
        producer_detail = {
            **window,
            "live_horizon": live_horizon,
            "receipt_sha256": producer_raw_sha256,
            "receipt_fingerprint": producer_receipt["receipt_fingerprint"],
        }
    detail = {
        "capacity_mode": "bootstrap",
        "authorization_path": str(
            prod_bootstrap.BOOTSTRAP_AUTHORIZATION_PATH.expanduser().absolute()
        ),
        "authorization_receipt_sha256": authorization.get(
            "authorization_receipt_sha256"
        ),
        "authorization_fingerprint": authorization.get("receipt_fingerprint"),
        "bootstrap_epoch_id": authorization.get("bootstrap_epoch_id"),
        "started_at": prod_admission._timestamp(
            authorization.get("started_at")
        ).isoformat(),
        "deadline": prod_admission._timestamp(
            authorization.get("deadline")
        ).isoformat(),
        "release_id": release_id,
        "release_bom_sha256": release_bom_sha256,
        "approval_evidence_sha256": approval_receipt_sha256,
        "active_release_binding_sha256": active_binding.get(
            "binding_receipt_sha256"
        ),
        "candidate_env_sha256": active_binding.get("candidate_env_sha256"),
        "release_plan_sha256": plan_observation["sha256"],
        "release_prepare_manifest_sha256": manifest_observation["sha256"],
        "max_concurrency": authorization.get("max_concurrency"),
        "daily_started_attempt_quota": authorization.get(
            "daily_started_attempt_quota"
        ),
        "quota_timezone": authorization.get("quota_timezone"),
    }
    if producer_detail is not None:
        detail["producer_activation"] = producer_detail
    return detail


def _bind_canary_bootstrap_authorization(
    canary_detail: Mapping[str, Any],
    authorization: Mapping[str, Any],
) -> None:
    vm_execution = _mapping(
        canary_detail.get("vm_execution"), "bootstrap_capacity.canary.vm_execution"
    )
    capacity = _mapping(
        vm_execution.get("capacity_admission"),
        "bootstrap_capacity.canary.capacity_admission",
    )
    if any(
        capacity.get(observed) != authorization.get(expected)
        for observed, expected in (
            ("bootstrap_epoch_id", "bootstrap_epoch_id"),
            ("bootstrap_started_at", "started_at"),
            ("bootstrap_deadline", "deadline"),
            ("bootstrap_authorization_fingerprint", "authorization_fingerprint"),
            ("release_bom_sha256", "release_bom_sha256"),
            ("release_approval_id", "release_id"),
        )
    ):
        raise EvidenceError("canary_vm_bootstrap_live_authorization_mismatch")


def _check_vm_fixed_service_execution(
    vm: Mapping[str, Any],
    *,
    submission_key: str,
    expected_request_sha256: str,
    expected_goal_sha256: str,
    expected_contract_sha256: str,
    expected_business_key: str,
    expected_generation: int,
    expected_source_refs: Mapping[str, Any],
    artifact_root: str,
    artifact_cifs_root: str,
    expected_vm_commit: str,
    expected_vm_worker_commit: str,
    expected_vm_service_entrypoint_sha256: str,
    expected_vm_worker_entrypoint_sha256: str,
    expected_capacity_mode: str | None,
    expected_release_bom_sha256: str,
    receipt_observed_at: datetime,
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    goal_path = f"/home/mini/.hermes/shared-state/tasks/{submission_key}/goal.md"
    execution_plane = _mapping(
        vm.get("execution_plane"), "canary_receipt.vm.execution_plane"
    )
    expected_execution_plane = {
        "lane": "heavy",
        "resource_class": "rca_prod",
        "risk_class": "high",
        "executor_type": "direct_cli",
        "agent_backend": "none",
        "codex_backend_enabled": False,
        "coding_agent_fallback_enabled": False,
        "fixed_cli_entrypoint": FIXED_RCA_SERVICE_ENTRYPOINT,
        "vm_worker_commit": expected_vm_worker_commit,
        "cwd": DEFAULT_VM_REPO_ROOT,
        "argv": [
            FIXED_RCA_SERVICE_RELATIVE_ENTRYPOINT,
            "--task-id",
            submission_key,
            "--goal-path",
            goal_path,
        ],
        "agent_invocation_count": 0,
        "fallback_invocation_count": 0,
    }
    if execution_plane != expected_execution_plane:
        raise EvidenceError("canary_vm_execution_plane_mismatch")

    capacity_admission = _check_canary_capacity_admission(
        vm.get("capacity_admission"),
        expected_capacity_mode=expected_capacity_mode,
        expected_release_bom_sha256=expected_release_bom_sha256,
        now=now,
    )

    execution_attestation = _mapping(
        vm.get("execution_attestation"),
        "canary_receipt.vm.execution_attestation",
    )
    expected_attestation_keys = {
        "schema_version",
        "available",
        "executor_type",
        "agent_backend",
        "codex_backend_enabled",
        "coding_agent_fallback_enabled",
        "openclaw_invocation_count",
        "codex_invocation_count",
        "fallback_invocation_count",
        "worker_source_commit",
        "worker_tree_clean",
        "worker_entrypoint_path",
        "worker_entrypoint_sha256",
        "argv",
        "cwd",
        "dispatched_at",
        "process_started_at",
        "task_id",
        "run_id",
        "worker_pid",
        "dispatch_receipt_sha256",
    }
    if set(execution_attestation) != expected_attestation_keys:
        raise EvidenceError("canary_vm_execution_attestation_shape_invalid")
    expected_argv = expected_execution_plane["argv"]
    if (
        execution_attestation.get("schema_version")
        != RCA_WORKER_EXECUTION_ATTESTATION_SCHEMA_VERSION
        or execution_attestation.get("available") is not True
        or execution_attestation.get("executor_type") != "direct_cli"
        or execution_attestation.get("agent_backend") != "none"
        or execution_attestation.get("codex_backend_enabled") is not False
        or execution_attestation.get("coding_agent_fallback_enabled") is not False
        or execution_attestation.get("openclaw_invocation_count") != 0
        or execution_attestation.get("codex_invocation_count") != 0
        or execution_attestation.get("fallback_invocation_count") != 0
        or execution_attestation.get("worker_source_commit")
        != expected_vm_worker_commit
        or execution_attestation.get("worker_tree_clean") is not True
        or execution_attestation.get("worker_entrypoint_path")
        != FIXED_RCA_WORKER_ENTRYPOINT
        or execution_attestation.get("argv") != expected_argv
        or execution_attestation.get("cwd") != DEFAULT_VM_REPO_ROOT
        or execution_attestation.get("task_id") != submission_key
    ):
        raise EvidenceError("canary_vm_execution_attestation_invalid")
    try:
        run_id = _required_text(
            execution_attestation.get("run_id"),
            "canary_receipt.vm.execution_attestation.run_id",
        )
        worker_pid = _exact_int(
            execution_attestation.get("worker_pid"),
            "canary_receipt.vm.execution_attestation.worker_pid",
            minimum=2,
        )
    except EvidenceError as exc:
        raise EvidenceError("canary_vm_execution_attestation_invalid") from exc
    try:
        worker_entrypoint_sha256 = _sha256_digest(
            execution_attestation.get("worker_entrypoint_sha256"),
            "canary_receipt.vm.execution_attestation.worker_entrypoint_sha256",
        )
        dispatched_at = _timestamp(
            execution_attestation.get("dispatched_at"),
            "canary_receipt.vm.execution_attestation.dispatched_at",
        )
        process_started_at = _timestamp(
            execution_attestation.get("process_started_at"),
            "canary_receipt.vm.execution_attestation.process_started_at",
        )
    except EvidenceError as exc:
        raise EvidenceError("canary_vm_execution_attestation_invalid") from exc
    if worker_entrypoint_sha256 != expected_vm_worker_entrypoint_sha256:
        raise EvidenceError("canary_vm_worker_entrypoint_hash_mismatch")
    if process_started_at < dispatched_at:
        raise EvidenceError("canary_vm_execution_attestation_timeline_invalid")
    if (
        dispatched_at > receipt_observed_at
        or process_started_at > receipt_observed_at
        or dispatched_at > now
        or process_started_at > now
    ):
        raise EvidenceError("canary_vm_execution_attestation_timeline_invalid")
    dispatch_receipt = {
        "schema_version": RCA_WORKER_DISPATCH_RECEIPT_SCHEMA_VERSION,
        "task_id": submission_key,
        "run_id": run_id,
        "argv": expected_argv,
        "cwd": DEFAULT_VM_REPO_ROOT,
        "dispatched_at": execution_attestation["dispatched_at"],
        "process_started_at": execution_attestation["process_started_at"],
        "worker_pid": worker_pid,
    }
    try:
        dispatch_receipt_sha256 = _sha256_digest(
            execution_attestation.get("dispatch_receipt_sha256"),
            "canary_receipt.vm.execution_attestation.dispatch_receipt_sha256",
        )
    except EvidenceError as exc:
        raise EvidenceError("canary_vm_execution_attestation_invalid") from exc
    if dispatch_receipt_sha256 != _sha256_json(dispatch_receipt):
        raise EvidenceError("canary_vm_dispatch_receipt_hash_mismatch")
    if (
        vm.get("run_id") != run_id
        or vm.get("dispatch_receipt_sha256") != dispatch_receipt_sha256
    ):
        raise EvidenceError("canary_vm_dispatch_receipt_binding_mismatch")

    worker_result_wrapper = _mapping(
        vm.get("worker_result"), "canary_receipt.vm.worker_result"
    )
    if set(worker_result_wrapper) != {"path", "sha256", "receipt"}:
        raise EvidenceError("canary_vm_worker_result_wrapper_invalid")
    expected_worker_result_path = (
        f"{DEFAULT_VM_WORKER_REPO_ROOT}/tasks/{submission_key}/local-result.json"
    )
    if worker_result_wrapper.get("path") != expected_worker_result_path:
        raise EvidenceError("canary_vm_worker_result_path_mismatch")
    worker_result_receipt = _mapping(
        worker_result_wrapper.get("receipt"),
        "canary_receipt.vm.worker_result.receipt",
    )
    worker_result_sha256 = _sha256_digest(
        worker_result_wrapper.get("sha256"),
        "canary_receipt.vm.worker_result.sha256",
    )
    if worker_result_sha256 != _sha256_json(worker_result_receipt):
        raise EvidenceError("canary_vm_worker_result_hash_mismatch")
    if set(worker_result_receipt) != {
        "task_id",
        "state",
        "completed_at",
        "exit_code",
        "summary",
        "result",
    }:
        raise EvidenceError("canary_vm_worker_result_shape_invalid")
    if (
        worker_result_receipt.get("task_id") != submission_key
        or worker_result_receipt.get("state") != "completed"
        or type(worker_result_receipt.get("exit_code")) is not int
        or worker_result_receipt.get("exit_code") != 0
    ):
        raise EvidenceError("canary_vm_worker_result_not_completed")
    _required_text(
        worker_result_receipt.get("summary"),
        "canary_receipt.vm.worker_result.receipt.summary",
    )
    worker_completed_at = _timestamp(
        worker_result_receipt.get("completed_at"),
        "canary_receipt.vm.worker_result.receipt.completed_at",
    )
    worker_result = _mapping(
        worker_result_receipt.get("result"),
        "canary_receipt.vm.worker_result.receipt.result",
    )
    worker_result_required_keys = {
        "schema_version",
        "task_id",
        "run_id",
        "repo_root",
        "canonical_task_dir",
        "goal_path",
        "host_inbox_root",
        "command",
        "runner_log",
        "artifact_root",
        "artifacts",
        "result_mode",
        "report_contract",
        "allowed_model_chain",
        "execution_route",
        "execution_attestation",
        "rca_submission_key",
        "rca_business_key",
        "rca_generation",
        "rca_contract_sha256",
        "rca_source_refs",
    }
    worker_result_optional_keys = {"external_artifacts", "resolved_snapshot"}
    if (
        not worker_result_required_keys.issubset(worker_result)
        or set(worker_result)
        - worker_result_required_keys
        - worker_result_optional_keys
    ):
        raise EvidenceError("canary_vm_worker_result_payload_shape_invalid")
    if (
        worker_result.get("schema_version") != RCA_WORKER_RESULT_SCHEMA_VERSION
        or worker_result.get("task_id") != submission_key
        or worker_result.get("run_id") != run_id
        or worker_result.get("repo_root") != DEFAULT_VM_REPO_ROOT
        or worker_result.get("canonical_task_dir")
        != f"/home/mini/.hermes/shared-state/tasks/{submission_key}"
        or worker_result.get("goal_path") != goal_path
        or worker_result.get("host_inbox_root")
        != "/home/mini/.hermes/shared-state/inbox"
        or worker_result.get("command") != expected_argv
        or worker_result.get("runner_log")
        != (
            f"{DEFAULT_VM_WORKER_REPO_ROOT}/tasks/{submission_key}/artifacts/runner.log"
        )
        or worker_result.get("artifact_root") != artifact_root.rstrip("/")
        or worker_result.get("result_mode") != "structured-result-artifact-only"
        or worker_result.get("report_contract") != "V4-V8"
        or worker_result.get("allowed_model_chain")
        != ["sub2api/gpt-5.5", "vtok/claude-opus-4-6"]
        or worker_result.get("execution_route") != "g1q3_rca_direct_cli"
        or worker_result.get("execution_attestation") != execution_attestation
        or worker_result.get("rca_submission_key") != submission_key
        or worker_result.get("rca_business_key") != expected_business_key
        or worker_result.get("rca_generation") != expected_generation
        or worker_result.get("rca_contract_sha256") != expected_contract_sha256
        or worker_result.get("rca_source_refs") != dict(expected_source_refs)
        or not isinstance(worker_result.get("artifacts"), list)
        or "error" in worker_result
    ):
        raise EvidenceError("canary_vm_worker_result_payload_invalid")
    _sha256_digest(
        worker_result.get("rca_contract_sha256"),
        "canary_receipt.vm.worker_result.receipt.result.rca_contract_sha256",
    )
    worker_observation_lag = (receipt_observed_at - worker_completed_at).total_seconds()
    if (
        worker_completed_at < process_started_at
        or worker_observation_lag < 0
        or worker_observation_lag > max_age_seconds
    ):
        raise EvidenceError("canary_vm_worker_result_timeline_invalid")
    execution_duration_seconds = (worker_completed_at - dispatched_at).total_seconds()
    if execution_duration_seconds > CANARY_MAX_EXECUTION_DURATION_SECONDS:
        raise EvidenceError("canary_vm_execution_duration_exceeded")

    wrapper = _mapping(vm.get("service_result"), "canary_receipt.vm.service_result")
    if set(wrapper) != {"path", "sha256", "receipt"}:
        raise EvidenceError("canary_vm_service_result_wrapper_invalid")
    expected_service_path = f"{artifact_root}rca_service_result.json"
    if wrapper.get("path") != expected_service_path:
        raise EvidenceError("canary_vm_service_result_path_mismatch")
    receipt = _mapping(
        wrapper.get("receipt"), "canary_receipt.vm.service_result.receipt"
    )
    receipt_sha256 = _sha256_digest(
        wrapper.get("sha256"), "canary_receipt.vm.service_result.sha256"
    )
    if receipt_sha256 != _sha256_json(receipt):
        raise EvidenceError("canary_vm_service_result_hash_mismatch")
    expected_keys = {
        "schema_version",
        "task_id",
        "status",
        "success",
        "goal_sha256",
        "request_sha256",
        "request_path",
        "output_dir",
        "artifact_cifs_root",
        "pipeline_result_path",
        "pipeline_status",
        "pipeline_stage",
        "blocker",
        "generated_at",
        "service_provenance",
        "request_storage",
        "worker_run_id",
        "worker_pid",
        "dispatch_receipt_sha256",
        *FIXED_CIFS_STORAGE_CONTRACT,
        "mount_evidence",
    }
    if set(receipt) != expected_keys:
        raise EvidenceError("canary_vm_service_result_shape_invalid")
    if (
        receipt.get("schema_version") != RCA_SERVICE_RESULT_SCHEMA_VERSION
        or receipt.get("task_id") != submission_key
        or receipt.get("status") != "completed"
        or receipt.get("success") is not True
        or receipt.get("request_sha256") != expected_request_sha256
        or receipt.get("request_path") != f"{artifact_root}rca_execution_request.json"
        or receipt.get("output_dir") != artifact_root.rstrip("/")
        or receipt.get("artifact_cifs_root") != artifact_cifs_root
        or receipt.get("pipeline_result_path") != f"{artifact_root}pipeline_result.json"
        or receipt.get("pipeline_status") != "report_generated_need_review"
        or receipt.get("pipeline_stage") != "s6_report"
        or receipt.get("blocker") is not None
        or receipt.get("worker_run_id") != run_id
        or receipt.get("worker_pid") != worker_pid
        or receipt.get("dispatch_receipt_sha256") != dispatch_receipt_sha256
    ):
        raise EvidenceError("canary_vm_service_result_not_completed")
    _require_fixed_cifs_storage_contract(
        receipt,
        field="canary_receipt.vm.service_result.receipt",
        blocker="canary_vm_service_storage_contract_invalid",
    )
    request_storage = _mapping(
        receipt.get("request_storage"),
        "canary_receipt.vm.service_result.receipt.request_storage",
    )
    if set(request_storage) != {
        "schema_version",
        "path",
        "sha256",
        "bytes",
        *FIXED_CIFS_STORAGE_CONTRACT,
        "mount_evidence",
    }:
        raise EvidenceError("canary_vm_request_storage_shape_invalid")
    try:
        request_storage_sha256 = _sha256_digest(
            request_storage.get("sha256"),
            "canary_receipt.vm.service_result.receipt.request_storage.sha256",
        )
        request_storage_bytes = _exact_int(
            request_storage.get("bytes"),
            "canary_receipt.vm.service_result.receipt.request_storage.bytes",
            minimum=1,
        )
    except EvidenceError as exc:
        raise EvidenceError("canary_vm_request_storage_invalid") from exc
    if (
        request_storage.get("schema_version") != STORAGE_FILE_RECEIPT_SCHEMA_VERSION
        or request_storage.get("path") != f"{artifact_root}rca_execution_request.json"
        or request_storage_bytes > MAX_EVIDENCE_BYTES
    ):
        raise EvidenceError("canary_vm_request_storage_invalid")
    _require_fixed_cifs_storage_contract(
        request_storage,
        field="canary_receipt.vm.service_result.receipt.request_storage",
        blocker="canary_vm_request_storage_invalid",
    )
    if any(
        request_storage.get(key) != receipt.get(key)
        for key in (*FIXED_CIFS_STORAGE_CONTRACT, "mount_evidence")
    ):
        raise EvidenceError("canary_vm_request_storage_binding_mismatch")
    goal_sha256 = _sha256_digest(
        receipt.get("goal_sha256"), "canary_receipt.vm.service_result.goal_sha256"
    )
    if goal_sha256 != expected_goal_sha256:
        raise EvidenceError("canary_vm_service_goal_hash_mismatch")
    service_provenance = _mapping(
        receipt.get("service_provenance"),
        "canary_receipt.vm.service_result.service_provenance",
    )
    if set(service_provenance) != {
        "schema_version",
        "available",
        "vm_source_commit",
        "vm_tree_clean",
        "service_entrypoint_path",
        "service_entrypoint_sha256",
    }:
        raise EvidenceError("canary_vm_service_provenance_shape_invalid")
    try:
        service_entrypoint_sha256 = _sha256_digest(
            service_provenance.get("service_entrypoint_sha256"),
            (
                "canary_receipt.vm.service_result.service_provenance."
                "service_entrypoint_sha256"
            ),
        )
    except EvidenceError as exc:
        raise EvidenceError("canary_vm_service_provenance_invalid") from exc
    if (
        service_provenance.get("schema_version")
        != RCA_SERVICE_PROVENANCE_SCHEMA_VERSION
        or service_provenance.get("available") is not True
        or service_provenance.get("vm_source_commit") != expected_vm_commit
        or service_provenance.get("vm_tree_clean") is not True
        or service_provenance.get("service_entrypoint_path")
        != FIXED_RCA_SERVICE_ENTRYPOINT
        or service_entrypoint_sha256 != expected_vm_service_entrypoint_sha256
    ):
        raise EvidenceError("canary_vm_service_provenance_invalid")
    generated_at = _timestamp(
        receipt.get("generated_at"), "canary_receipt.vm.service_result.generated_at"
    )
    if generated_at < process_started_at or generated_at > worker_completed_at:
        raise EvidenceError("canary_vm_service_result_timeline_invalid")
    return {
        "execution_plane": expected_execution_plane,
        "capacity_admission": capacity_admission,
        "execution_attestation": {
            "schema_version": RCA_WORKER_EXECUTION_ATTESTATION_SCHEMA_VERSION,
            "worker_source_commit": expected_vm_worker_commit,
            "worker_entrypoint_sha256": worker_entrypoint_sha256,
            "dispatched_at": dispatched_at.isoformat(),
            "process_started_at": process_started_at.isoformat(),
            "task_id": submission_key,
            "run_id": run_id,
            "worker_pid": worker_pid,
            "dispatch_receipt_sha256": dispatch_receipt_sha256,
            "agent_invocations": {
                "openclaw": 0,
                "codex": 0,
                "fallback": 0,
            },
        },
        "service_provenance": {
            "schema_version": RCA_SERVICE_PROVENANCE_SCHEMA_VERSION,
            "vm_source_commit": expected_vm_commit,
            "service_entrypoint_sha256": service_entrypoint_sha256,
        },
        "service_result_path": expected_service_path,
        "service_result_sha256": receipt_sha256,
        "worker_result_path": expected_worker_result_path,
        "worker_result_sha256": worker_result_sha256,
        "request_storage_sha256": request_storage_sha256,
        "mount_evidence": dict(receipt["mount_evidence"]),
        "goal_sha256": goal_sha256,
        "request_sha256": expected_request_sha256,
        "generated_at": generated_at.isoformat(),
        "execution_duration_seconds": execution_duration_seconds,
        "max_execution_duration_seconds": CANARY_MAX_EXECUTION_DURATION_SECONDS,
        "pipeline_status": "report_generated_need_review",
        "pipeline_stage": "s6_report",
    }


def _check_gateway_runtime_identity(
    value: Any,
    *,
    field: str,
) -> dict[str, Any]:
    identity = _mapping(value, field)
    if set(identity) != {
        "service_label",
        "pid",
        "process_create_time",
        "boot_time",
        "executable",
        "script",
        "cwd",
        "script_sha256",
        "runtime_files_sha256",
        "public_config_sha256",
        "loaded_runtime_sha256",
    }:
        raise EvidenceError("canary_gateway_runtime_identity_shape_invalid")
    if identity.get("service_label") != "ai.hermes.gateway":
        raise EvidenceError("canary_gateway_runtime_identity_invalid")
    _exact_int(identity.get("pid"), f"{field}.pid", minimum=1)
    process_create_time = _number(
        identity.get("process_create_time"),
        f"{field}.process_create_time",
        minimum=1,
    )
    boot_time = _number(
        identity.get("boot_time"), f"{field}.boot_time", minimum=1
    )
    if process_create_time < boot_time:
        raise EvidenceError("canary_gateway_runtime_identity_invalid")
    for path_field in ("executable", "script", "cwd"):
        path = _required_text(identity.get(path_field), f"{field}.{path_field}")
        if not Path(path).is_absolute() or "\x00" in path:
            raise EvidenceError("canary_gateway_runtime_identity_invalid")
    if not str(identity["script"]).endswith("/gateway/run.py"):
        raise EvidenceError("canary_gateway_runtime_identity_invalid")
    for digest_field in (
        "script_sha256",
        "runtime_files_sha256",
        "public_config_sha256",
        "loaded_runtime_sha256",
    ):
        _sha256_digest(identity.get(digest_field), f"{field}.{digest_field}")
    return dict(identity)


def _check_manual_authorization_evidence(
    value: Any,
    *,
    source: Mapping[str, Any],
    field: str,
    expected_manual_chat_ids: Sequence[str],
    expected_operator_config: CutoverConfig | None = None,
) -> dict[str, Any]:
    evidence = _mapping(value, field)
    if set(evidence) != {
        "schema_version",
        "receipt_path",
        "line_number",
        "file_raw_sha256",
        "record_sha256",
        "timestamp",
        "platform",
        "chat_id",
        "message_id",
        "requester_id",
        "decision",
        "route_surface",
        "risk_gate",
        "manual_authorization",
        "gateway_runtime_identity",
    }:
        raise EvidenceError("canary_trigger_authorization_shape_invalid")
    if evidence.get("schema_version") != "pnc_rca_manual_authorization_evidence_v2":
        raise EvidenceError("canary_trigger_authorization_schema_invalid")
    path = _required_text(evidence.get("receipt_path"), f"{field}.receipt_path")
    if not Path(path).is_absolute() or ".." in Path(path).parts or "\x00" in path:
        raise EvidenceError("canary_trigger_authorization_path_invalid")
    _exact_int(evidence.get("line_number"), f"{field}.line_number", minimum=1)
    _sha256_digest(evidence.get("file_raw_sha256"), f"{field}.file_raw_sha256")
    _sha256_digest(evidence.get("record_sha256"), f"{field}.record_sha256")
    authorization = _mapping(
        evidence.get("manual_authorization"), f"{field}.manual_authorization"
    )
    if set(authorization) != {
        "schema_version",
        "manual_intake_enabled",
        "manual_chat_allowlist_valid",
        "manual_chat_allowlist_sha256",
        "chat_allowed",
        "mention_verified",
        "debug_requested",
        "debug_enabled",
        "requester_allowed",
        "debug_user_allowlist_sha256",
        "manual_operator_rate_limit",
        "manual_operator_rate_window_seconds",
        "authorized",
    }:
        raise EvidenceError("canary_trigger_authorization_snapshot_shape_invalid")
    source_mode = str(source.get("mode") or "")
    debug_requested = source_mode == "debug"
    operator_requested = source_mode in {"rerun", "debug"}
    active_chat_ids = _normalized_manual_chat_ids(expected_manual_chat_ids)
    if (
        authorization.get("schema_version") != "pnc_rca_manual_authorization_v2"
        or authorization.get("manual_intake_enabled") is not True
        or authorization.get("manual_chat_allowlist_valid") is not True
        or source.get("chat_id") not in active_chat_ids
        or authorization.get("manual_chat_allowlist_sha256")
        != _sha256_json(list(active_chat_ids))
        or authorization.get("chat_allowed") is not True
        or authorization.get("mention_verified") is not True
        or authorization.get("debug_requested") is not debug_requested
        or authorization.get("requester_allowed") is not True
        or authorization.get("authorized") is not True
        or (debug_requested and authorization.get("debug_enabled") is not True)
    ):
        raise EvidenceError("canary_trigger_authorization_not_proven")
    _sha256_digest(
        authorization.get("debug_user_allowlist_sha256"),
        f"{field}.manual_authorization.debug_user_allowlist_sha256",
    )
    operator_rate_limit = _exact_int(
        authorization.get("manual_operator_rate_limit"),
        f"{field}.manual_authorization.manual_operator_rate_limit",
        minimum=1,
    )
    operator_rate_window_seconds = _exact_int(
        authorization.get("manual_operator_rate_window_seconds"),
        f"{field}.manual_authorization.manual_operator_rate_window_seconds",
        minimum=1,
    )
    if expected_operator_config is not None:
        operator_enabled = expected_operator_config.manual_operator_enabled
        expected_operator_users = expected_operator_config.manual_operator_user_ids
        expected_operator_sha256 = _sha256_json(list(expected_operator_users))
        expected_rate_limit = expected_operator_config.manual_operator_rate_limit
        expected_rate_window_seconds = (
            expected_operator_config.manual_operator_rate_window_seconds
        )
        if (
            operator_enabled is None
            or authorization.get("debug_enabled") is not operator_enabled
            or authorization.get("debug_user_allowlist_sha256")
            != expected_operator_sha256
            or (
                expected_rate_limit is not None
                and operator_rate_limit != expected_rate_limit
            )
            or (
                expected_rate_window_seconds is not None
                and operator_rate_window_seconds != expected_rate_window_seconds
            )
            or (
                operator_enabled is True
                and (
                    expected_rate_limit is None
                    or expected_rate_window_seconds is None
                )
            )
        ):
            raise EvidenceError("canary_manual_operator_config_mismatch")
        if operator_requested and (
            operator_enabled is not True
            or source.get("requester_id") not in expected_operator_users
        ):
            raise EvidenceError("canary_manual_operator_authorization_not_proven")
    decision_at = _timestamp(evidence.get("timestamp"), f"{field}.timestamp")
    source_at = _timestamp(source.get("created_at"), f"{field}.source_created_at")
    if decision_at > source_at:
        raise EvidenceError("canary_trigger_authorization_timestamp_invalid")
    if (
        evidence.get("platform") != source.get("platform")
        or evidence.get("chat_id") != source.get("chat_id")
        or evidence.get("message_id") != source.get("message_id")
        or evidence.get("requester_id") != source.get("requester_id")
        or evidence.get("decision") != "accepted"
        or evidence.get("route_surface") != "rca_manual_intake"
        or evidence.get("risk_gate") != "manual_intake_control_store"
    ):
        raise EvidenceError("canary_trigger_authorization_identity_mismatch")
    gateway_identity = _check_gateway_runtime_identity(
        evidence.get("gateway_runtime_identity"),
        field=f"{field}.gateway_runtime_identity",
    )
    if float(gateway_identity["process_create_time"]) > decision_at.timestamp():
        raise EvidenceError("canary_trigger_authorization_process_timeline_invalid")
    return dict(evidence)


def _check_trigger_source_projection(
    value: Any,
    *,
    field: str,
    expected_business_key: str,
    expected_generation: int,
    expected_manual_chat_ids: Sequence[str],
    expected_operator_config: CutoverConfig | None = None,
) -> dict[str, Any]:
    source = _mapping(value, field)
    if set(source) != {
        "source_id",
        "source_kind",
        "storage_source_kind",
        "source_dedupe_key",
        "payload_sha256",
        "platform",
        "chat_id",
        "thread_id",
        "message_id",
        "requester_id",
        "kafka_event_uid",
        "mode",
        "outcome",
        "created_at",
        "binding_role",
        "bound_at",
        "business_key",
        "generation",
        "authorization",
    }:
        raise EvidenceError("canary_trigger_source_shape_invalid")
    source_id = _required_text(source.get("source_id"), f"{field}.source_id")
    storage_kind = _required_text(
        source.get("storage_source_kind"), f"{field}.storage_source_kind"
    )
    dedupe_key = _required_text(
        source.get("source_dedupe_key"), f"{field}.source_dedupe_key"
    )
    if source_id != _stable_trigger_source_id(storage_kind, dedupe_key):
        raise EvidenceError("canary_trigger_source_id_invalid")
    _sha256_digest(source.get("payload_sha256"), f"{field}.payload_sha256")
    _timestamp(source.get("created_at"), f"{field}.created_at")
    _timestamp(source.get("bound_at"), f"{field}.bound_at")
    generation = _exact_int(source.get("generation"), f"{field}.generation", minimum=1)
    if (
        source.get("business_key") != expected_business_key
        or generation != expected_generation
        or source.get("binding_role") not in {"origin", "observer"}
    ):
        raise EvidenceError("canary_trigger_source_binding_invalid")

    if storage_kind == "kafka_workflow_event":
        event_uid = _required_text(
            source.get("kafka_event_uid"), f"{field}.kafka_event_uid"
        )
        parts = event_uid.rsplit(":", 2)
        if (
            len(parts) != 3
            or not parts[0]
            or not parts[1].isdigit()
            or not parts[2].isdigit()
            or str(int(parts[1])) != parts[1]
            or str(int(parts[2])) != parts[2]
            or dedupe_key != event_uid
            or source.get("source_kind") != "kafka_issue_created"
            or source.get("mode") != "issue_created"
            or source.get("outcome") != ""
            or any(
                source.get(key) != ""
                for key in (
                    "platform",
                    "chat_id",
                    "thread_id",
                    "message_id",
                    "requester_id",
                )
            )
            or source.get("authorization") is not None
        ):
            raise EvidenceError("canary_kafka_trigger_source_invalid")
    elif storage_kind == "feishu_group_manual":
        mode = source.get("mode")
        normalized_kind = (
            "manual_issue_request" if mode == "run_or_join" else "manual_retrigger"
        )
        thread_id = _required_text(source.get("thread_id"), f"{field}.thread_id")
        if (
            mode not in {"run_or_join", "rerun", "debug"}
            or source.get("source_kind") != normalized_kind
            or source.get("platform") != "feishu"
            or not _required_text(source.get("chat_id"), f"{field}.chat_id")
            or not thread_id.startswith("topic:")
            or not thread_id.removeprefix("topic:")
            or not _required_text(source.get("message_id"), f"{field}.message_id")
            or not _required_text(source.get("requester_id"), f"{field}.requester_id")
            or source.get("kafka_event_uid") is not None
            or dedupe_key != f"feishu:{source.get('message_id')}"
            or source.get("outcome")
            not in {"created", "joined", "rearmed", "catchup_attached"}
        ):
            raise EvidenceError("canary_manual_trigger_source_invalid")
        _check_manual_authorization_evidence(
            source.get("authorization"),
            source=source,
            field=f"{field}.authorization",
            expected_manual_chat_ids=expected_manual_chat_ids,
            expected_operator_config=expected_operator_config,
        )
    else:
        raise EvidenceError("canary_trigger_source_kind_invalid")
    return dict(source)


def _check_delivery_obligations(
    value: Any,
    *,
    admission: Mapping[str, Any],
    observed_source: Mapping[str, Any],
    primary_delivery: Mapping[str, Any],
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        raise EvidenceError("canary_delivery_obligations_invalid")
    obligations: list[dict[str, Any]] = []
    for index, raw in enumerate(value):
        obligation = _mapping(raw, f"canary_receipt.delivery_obligations[{index}]")
        if set(obligation) != {
            "subscription_key",
            "effect_kind",
            "target_key",
            "target",
            "required",
            "subscription_status",
            "delivery_id",
            "effect_key",
            "effect_status",
            "materialized_at",
            "completed_at",
            "remote_id",
        }:
            raise EvidenceError("canary_delivery_obligation_shape_invalid")
        if (
            obligation.get("required") is not True
            or obligation.get("subscription_status") != "materialized"
            or obligation.get("effect_status") != "succeeded"
        ):
            raise EvidenceError("canary_delivery_obligation_not_succeeded")
        for key in (
            "subscription_key",
            "target_key",
            "delivery_id",
            "effect_key",
            "remote_id",
        ):
            _required_text(obligation.get(key), f"delivery_obligation.{key}")
        _timestamp(
            obligation.get("materialized_at"), "delivery_obligation.materialized_at"
        )
        _timestamp(obligation.get("completed_at"), "delivery_obligation.completed_at")
        obligations.append(dict(obligation))
    kinds = {item.get("effect_kind") for item in obligations}
    expected_kinds = {"feishu_issue_comment"}
    if observed_source.get("storage_source_kind") == "feishu_group_manual":
        expected_kinds.add("feishu_thread_reply")
    if kinds != expected_kinds or len(obligations) != len(expected_kinds):
        raise EvidenceError("canary_delivery_obligations_incomplete")
    if len({item["delivery_id"] for item in obligations}) != 1:
        raise EvidenceError("canary_delivery_obligation_delivery_mismatch")
    refs = _mapping(
        admission.get("source_refs"), "canary_receipt.admission.source_refs"
    )
    for obligation in obligations:
        target = _mapping(obligation.get("target"), "delivery_obligation.target")
        if obligation["effect_kind"] == "feishu_issue_comment":
            expected_target = {
                "schema_version": "pnc_rca_delivery_target_v1",
                "platform": "feishu_project",
                "project_key": refs.get("project_key"),
                "work_item_type_key": refs.get("work_item_type_key"),
                "work_item_id": refs.get("work_item_id"),
                "output_cap": "L1",
            }
            if (
                obligation.get("effect_key") != primary_delivery.get("effect_key")
                or obligation.get("target_key") != primary_delivery.get("target_key")
                or obligation.get("remote_id")
                != _mapping(
                    primary_delivery.get("remote_receipt"),
                    "canary_receipt.delivery.remote_receipt",
                ).get("remote_id")
            ):
                raise EvidenceError("canary_issue_delivery_obligation_mismatch")
        else:
            root = str(observed_source.get("thread_id") or "").removeprefix("topic:")
            expected_target = {
                "schema_version": "pnc_rca_delivery_target_v1",
                "platform": "feishu",
                "chat_id": observed_source.get("chat_id"),
                "thread_id": observed_source.get("thread_id"),
                "reply_anchor_message_id": root,
                "source_message_id": observed_source.get("message_id"),
                "requester_id": observed_source.get("requester_id"),
                "reply_in_thread": True,
                "output_cap": "L1",
            }
            if obligation.get("target_key") != (
                f"feishu_thread:{observed_source.get('chat_id')}:{root}"
            ):
                raise EvidenceError("canary_thread_delivery_target_invalid")
        if target != expected_target:
            raise EvidenceError("canary_delivery_obligation_target_invalid")
    return obligations


def _check_canary_receipt(
    body: Mapping[str, Any],
    *,
    expected_execution_origin_id: str,
    expected_execution_origin_kind: str,
    expected_observed_source_id: str,
    expected_observed_source_kind: str,
    expected_manual_chat_ids: Sequence[str],
    expected_operator_config: CutoverConfig | None,
    expected_request_sha256: str,
    expected_admission: Mapping[str, Any],
    expected_reader_fingerprint: str,
    expected_requested_scope: Mapping[str, Any],
    expected_vm_commit: str,
    expected_vm_worker_commit: str,
    expected_vm_service_entrypoint_sha256: str,
    expected_vm_worker_entrypoint_sha256: str,
    expected_capacity_mode: str | None,
    expected_release_bom_sha256: str,
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    artifact = "canary_receipt"
    _require_schema(body, CANARY_RECEIPT_SCHEMA_VERSION, artifact)
    if set(body) != {
        "schema_version",
        "observed_at",
        "ok",
        "execution_origin",
        "observed_trigger_source",
        "admission",
        "execution_request",
        "remote_read",
        "derived_capacity_lifecycle",
        "capacity_meter",
        "pipeline",
        "submission_count",
        "submission_key",
        "outbox",
        "vm",
        "report",
        "delivery",
        "delivery_obligations",
    }:
        raise EvidenceError("canary_receipt_shape_invalid")
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("ok") is not True:
        raise EvidenceError("canary_receipt_not_ok")
    try:
        admission = validate_rca_admission(
            _mapping(body.get("admission"), "canary_receipt.admission")
        ).to_dict()
    except (EvidenceError, RcaAdmissionError) as exc:
        raise EvidenceError("canary_receipt_admission_invalid") from exc
    if admission != dict(expected_admission):
        raise EvidenceError("canary_receipt_admission_mismatch")
    business_key = _required_text(
        admission.get("business_key"), "canary_receipt.admission.business_key"
    )
    generation = _exact_int(
        admission.get("generation"),
        "canary_receipt.admission.generation",
        minimum=1,
    )
    execution_origin = _check_trigger_source_projection(
        body.get("execution_origin"),
        field="canary_receipt.execution_origin",
        expected_business_key=business_key,
        expected_generation=generation,
        expected_manual_chat_ids=expected_manual_chat_ids,
        expected_operator_config=expected_operator_config,
    )
    observed_source = _check_trigger_source_projection(
        body.get("observed_trigger_source"),
        field="canary_receipt.observed_trigger_source",
        expected_business_key=business_key,
        expected_generation=generation,
        expected_manual_chat_ids=expected_manual_chat_ids,
        expected_operator_config=expected_operator_config,
    )
    if (
        execution_origin.get("source_id") != expected_execution_origin_id
        or execution_origin.get("source_kind") != expected_execution_origin_kind
        or execution_origin.get("binding_role") != "origin"
        or observed_source.get("source_id") != expected_observed_source_id
        or observed_source.get("source_kind") != expected_observed_source_kind
        or (
            observed_source.get("source_id") == execution_origin.get("source_id")
            and observed_source.get("binding_role") != "origin"
        )
        or (
            observed_source.get("source_id") != execution_origin.get("source_id")
            and observed_source.get("binding_role") != "observer"
        )
    ):
        raise EvidenceError("canary_receipt_trigger_source_mismatch")
    execution_request = _mapping(
        body.get("execution_request"), "canary_receipt.execution_request"
    )
    request_detail = _check_remote_execution_request(
        execution_request,
        field="canary_receipt.execution_request",
        expected_admission=admission,
        expected_origin_source_id=str(execution_origin["source_id"]),
        expected_origin_storage_kind=str(execution_origin["storage_source_kind"]),
    )
    if request_detail["request_sha256"] != expected_request_sha256:
        raise EvidenceError("canary_receipt_execution_request_mismatch")
    remote_read_detail = _check_remote_canary_read(
        body.get("remote_read"),
        expected_reader_fingerprint=expected_reader_fingerprint,
        expected_reader_classes=request_detail["reader_classes"],
        expected_requested_scope=expected_requested_scope,
        expected_artifact_root=str(request_detail["artifact_root"]),
    )
    if _exact_int(body.get("submission_count"), "canary_receipt.submission_count") != 1:
        raise EvidenceError("canary_receipt_submission_count_invalid")
    submission_key = _required_text(
        body.get("submission_key"), "canary_receipt.submission_key"
    )
    if submission_key != admission["submission_key"]:
        raise EvidenceError("canary_receipt_submission_key_mismatch")
    try:
        expected_goal_sha256 = hashlib.sha256(
            build_rca_fixed_cli_goal(
                task_id=submission_key,
                admission=admission,
                execution_request=dict(execution_request),
            ).encode("utf-8")
        ).hexdigest()
        expected_contract_sha256 = canonical_rca_contract_sha256(
            dict(admission), dict(execution_request)
        )
    except (TypeError, ValueError) as exc:
        raise EvidenceError("canary_vm_service_goal_unverifiable") from exc
    capacity_lifecycle_detail = _check_canary_capacity_lifecycle(
        body.get("derived_capacity_lifecycle"), request_detail=request_detail
    )
    capacity_meter_detail = _check_stage_capacity_meter(
        body.get("capacity_meter"),
        artifact_root=str(request_detail["artifact_root"]),
        submission_key=submission_key,
        capacity_lifecycle_detail=capacity_lifecycle_detail,
        remote_read_detail=remote_read_detail,
    )
    pipeline_detail = _check_pipeline_projection(
        body.get("pipeline"),
        artifact_root=str(request_detail["artifact_root"]),
        remote_read_detail=remote_read_detail,
        capacity_meter_detail=capacity_meter_detail,
    )
    outbox = _mapping(body.get("outbox"), "canary_receipt.outbox")
    vm = _mapping(body.get("vm"), "canary_receipt.vm")
    report = _mapping(body.get("report"), "canary_receipt.report")
    delivery = _mapping(body.get("delivery"), "canary_receipt.delivery")
    delivery_obligations = body.get("delivery_obligations")
    if set(outbox) != {
        "ok",
        "submission_key",
        "origin_source_id",
        "status",
        "execution_request_sha256",
        "reserved_receipt_sha256",
    }:
        raise EvidenceError("canary_receipt_outbox_shape_invalid")
    if set(vm) != {
        "ok",
        "submission_key",
        "task_id",
        "terminal_state",
        "execution_request_sha256",
        "capacity_lifecycle_sha256",
        "run_id",
        "dispatch_receipt_sha256",
        "execution_plane",
        "capacity_admission",
        "execution_attestation",
        "worker_result",
        "service_result",
    }:
        raise EvidenceError("canary_receipt_vm_shape_invalid")
    if set(report) != {
        "ok",
        "submission_key",
        "artifact_set_id",
        "report_url",
        "manifest_sha256",
        "delivery_manifest",
        "index_html",
        "report_data_json",
        "html_validation",
        "artifact_policy",
        "browser_smoke",
    }:
        raise EvidenceError("canary_receipt_report_shape_invalid")
    if set(delivery) != {
        "ok",
        "submission_key",
        "artifact_set_id",
        "report_url",
        "effect_key",
        "target_key",
        "marker",
        "remote_receipt",
    }:
        raise EvidenceError("canary_receipt_delivery_shape_invalid")
    for stage_name, stage in (
        ("outbox", outbox),
        ("vm", vm),
        ("report", report),
        ("delivery", delivery),
    ):
        if stage.get("ok") is not True:
            raise EvidenceError(f"canary_receipt_{stage_name}_failed")
        if stage.get("submission_key") != submission_key:
            raise EvidenceError("canary_receipt_submission_key_mismatch")
    if outbox.get("status") != "completed":
        raise EvidenceError("canary_receipt_outbox_not_completed")
    if outbox.get("origin_source_id") != execution_origin.get("source_id"):
        raise EvidenceError("canary_receipt_outbox_origin_mismatch")
    if (
        outbox.get("execution_request_sha256") != expected_request_sha256
        or vm.get("execution_request_sha256") != expected_request_sha256
    ):
        raise EvidenceError("canary_receipt_execution_request_stage_mismatch")
    if (
        outbox.get("reserved_receipt_sha256")
        != capacity_lifecycle_detail["receipt_sha256"]["reserved"]
    ):
        raise EvidenceError("canary_receipt_reserved_capacity_stage_mismatch")
    if vm.get("task_id") != submission_key:
        raise EvidenceError("canary_receipt_vm_task_mismatch")
    if vm.get("terminal_state") != "completed":
        raise EvidenceError("canary_receipt_vm_not_completed")
    if (
        vm.get("capacity_lifecycle_sha256")
        != capacity_lifecycle_detail["lifecycle_sha256"]
    ):
        raise EvidenceError("canary_receipt_vm_capacity_lifecycle_mismatch")
    vm_execution_detail = _check_vm_fixed_service_execution(
        vm,
        submission_key=submission_key,
        expected_request_sha256=expected_request_sha256,
        expected_goal_sha256=expected_goal_sha256,
        expected_contract_sha256=expected_contract_sha256,
        expected_business_key=str(admission["business_key"]),
        expected_generation=_exact_int(
            admission.get("generation"),
            "canary_receipt.admission.generation",
            minimum=1,
        ),
        expected_source_refs=_mapping(
            admission.get("source_refs"), "canary_receipt.admission.source_refs"
        ),
        artifact_root=str(request_detail["artifact_root"]),
        artifact_cifs_root=str(request_detail["artifact_cifs_root"]),
        expected_vm_commit=expected_vm_commit,
        expected_vm_worker_commit=expected_vm_worker_commit,
        expected_vm_service_entrypoint_sha256=(expected_vm_service_entrypoint_sha256),
        expected_vm_worker_entrypoint_sha256=(expected_vm_worker_entrypoint_sha256),
        expected_capacity_mode=expected_capacity_mode,
        expected_release_bom_sha256=expected_release_bom_sha256,
        receipt_observed_at=_timestamp(observed_at, "canary_receipt.observed_at"),
        now=now,
        max_age_seconds=max_age_seconds,
    )
    if (
        vm_execution_detail["mount_evidence"]
        != remote_read_detail["derived_stream_cache_receipt"]["mount_evidence"]
    ):
        raise EvidenceError("canary_vm_remote_storage_mount_binding_mismatch")

    artifact_set_id = _required_text(
        report.get("artifact_set_id"), "canary_receipt.report.artifact_set_id"
    )
    report_url = _required_text(
        report.get("report_url"), "canary_receipt.report.report_url"
    )
    try:
        expected_report_url = build_report_url(submission_key, artifact_set_id)
    except DeliveryContractError as exc:
        raise EvidenceError("canary_receipt_report_url_invalid") from exc
    if report_url != expected_report_url:
        raise EvidenceError("canary_receipt_report_url_mismatch")
    manifest_sha256 = _sha256_digest(
        report.get("manifest_sha256"), "canary_receipt.report.manifest_sha256"
    )
    manifest_wrapper = _mapping(
        report.get("delivery_manifest"), "canary_receipt.report.delivery_manifest"
    )
    if set(manifest_wrapper) != {"size_bytes", "sha256", "body"}:
        raise EvidenceError("canary_receipt_delivery_manifest_shape_invalid")
    manifest_size_bytes = _exact_int(
        manifest_wrapper.get("size_bytes"),
        "canary_receipt.report.delivery_manifest.size_bytes",
        minimum=1,
    )
    if (
        _sha256_digest(
            manifest_wrapper.get("sha256"),
            "canary_receipt.report.delivery_manifest.sha256",
        )
        != manifest_sha256
    ):
        raise EvidenceError("canary_receipt_delivery_manifest_hash_mismatch")
    manifest_body = _mapping(
        manifest_wrapper.get("body"), "canary_receipt.report.delivery_manifest.body"
    )
    try:
        computed_artifact_set_id = compute_artifact_set_id(manifest_body)
    except DeliveryContractError as exc:
        raise EvidenceError("canary_receipt_artifact_set_derivation_invalid") from exc
    admission_refs = _mapping(
        admission.get("source_refs"), "canary_receipt.admission.source_refs"
    )
    if (
        manifest_body.get("schema_version") != DELIVERY_MANIFEST_SCHEMA_VERSION
        or manifest_body.get("sealed") is not True
        or manifest_body.get("deliverable_kind") != "html"
        or manifest_body.get("dependencies_complete") is not True
        or manifest_body.get("submission_key") != submission_key
        or manifest_body.get("business_key") != admission.get("business_key")
        or manifest_body.get("generation") != admission.get("generation")
        or manifest_body.get("project_key") != admission_refs.get("project_key")
        or manifest_body.get("work_item_type_key")
        != admission_refs.get("work_item_type_key")
        or manifest_body.get("work_item_id") != admission_refs.get("work_item_id")
        or manifest_body.get("artifact_root") != request_detail["artifact_root"]
        or manifest_body.get("artifact_set_id") != artifact_set_id
        or computed_artifact_set_id != artifact_set_id
        or manifest_body.get("report_url") != report_url
    ):
        raise EvidenceError("canary_receipt_artifact_set_derivation_mismatch")
    if report.get("html_validation") != "html_delivery_ready":
        raise EvidenceError("canary_receipt_html_validation_failed")
    if report.get("artifact_policy") != HTML_ARTIFACT_POLICY_VERSION:
        raise EvidenceError("canary_receipt_html_artifact_policy_mismatch")
    artifact_files: dict[str, dict[str, Any]] = {}
    for field in ("index_html", "report_data_json"):
        file_receipt = _mapping(report.get(field), f"canary_receipt.report.{field}")
        if set(file_receipt) != {"size_bytes", "sha256"}:
            raise EvidenceError("canary_receipt_report_file_shape_invalid")
        artifact_files[field] = {
            "size_bytes": _exact_int(
                file_receipt.get("size_bytes"),
                f"canary_receipt.report.{field}.size_bytes",
                minimum=1,
            ),
            "sha256": _sha256_digest(
                file_receipt.get("sha256"),
                f"canary_receipt.report.{field}.sha256",
            ),
        }

    manifest_artifacts = manifest_body.get("artifacts")
    if not isinstance(manifest_artifacts, list):
        raise EvidenceError("canary_receipt_delivery_manifest_artifacts_invalid")
    manifest_by_role = {
        item.get("role"): item
        for item in manifest_artifacts
        if isinstance(item, Mapping) and isinstance(item.get("role"), str)
    }
    expected_manifest_files = {
        "index_html": ("index.html", artifact_files["index_html"]),
        "report_data": ("report_data.json", artifact_files["report_data_json"]),
    }
    for role, (relative_path, file_receipt) in expected_manifest_files.items():
        item = manifest_by_role.get(role)
        if (
            not isinstance(item, Mapping)
            or item.get("path") != relative_path
            or item.get("size") != file_receipt["size_bytes"]
            or item.get("sha256") != file_receipt["sha256"]
            or item.get("required") is not True
        ):
            raise EvidenceError("canary_receipt_delivery_manifest_artifacts_invalid")

    lineage_value = {
        name: pipeline_detail["downstream_stage_receipts"][name]["lineage"]
        for name in REQUIRED_DOWNSTREAM_STAGES
    }
    lineage_finished_at = {
        name: pipeline_detail["downstream_stage_receipts"][name]["finished_at"]
        for name in REQUIRED_DOWNSTREAM_STAGES
    }
    remote_cache_receipt = remote_read_detail["derived_stream_cache_receipt"]
    expected_lineage_identity = {
        "task_id": submission_key,
        "submission_key": submission_key,
        "run_id": vm_execution_detail["execution_attestation"]["run_id"],
        "artifact_set_id": artifact_set_id,
        "request_sha256": expected_request_sha256,
        "rca_contract_sha256": expected_contract_sha256,
    }
    required_final_outputs = [
        {
            "kind": "delivery_manifest",
            "path": f"{request_detail['artifact_root']}delivery_manifest.json",
            "bytes": manifest_size_bytes,
            "sha256": manifest_sha256,
        },
        {
            "kind": "index_html",
            "path": f"{request_detail['artifact_root']}index.html",
            "bytes": artifact_files["index_html"]["size_bytes"],
            "sha256": artifact_files["index_html"]["sha256"],
        },
        {
            "kind": "report_data",
            "path": f"{request_detail['artifact_root']}report_data.json",
            "bytes": artifact_files["report_data_json"]["size_bytes"],
            "sha256": artifact_files["report_data_json"]["sha256"],
        },
    ]
    try:
        validate_stage_lineage_chain(
            lineage_value,
            artifact_root=str(request_detail["artifact_root"]),
            expected_identity=expected_lineage_identity,
            expected_finished_at=lineage_finished_at,
            remote_stream_cache={
                "kind": "derived_remote_stream_cache",
                "path": remote_cache_receipt["path"],
                "bytes": remote_cache_receipt["bytes"],
                "sha256": remote_cache_receipt["sha256"],
            },
            required_final_outputs=required_final_outputs,
        )
    except StageLineageError as exc:
        raise EvidenceError(f"canary_{exc.code}", exc.detail) from exc

    browser_smoke = _mapping(
        report.get("browser_smoke"), "canary_receipt.report.browser_smoke"
    )
    browser_zero_fields = {
        "unmanifested_request_count",
        "executable_script_count",
        "inline_event_handler_count",
        "external_active_document_count",
        "console_error_count",
        "runtime_exception_count",
        "log_error_count",
        "network_error_count",
    }
    if set(browser_smoke) != {
        "schema_version",
        "observed_at",
        "ok",
        "machine_generated",
        "source",
        "engine",
        "artifact_policy",
        "artifact_set_id",
        "report_url",
        "index_html_sha256",
        "manifest_sha256",
        "delivery_contract_sha256",
        "manifest_url_count",
        "manifest_url_set_sha256",
        "requested_urls",
        "request_list_sha256",
        "network_closure",
        "desktop_nonblank",
        "mobile_nonblank",
        "request_count",
        "browser",
        "viewports",
        "blockers",
        "evidence_sha256",
        *browser_zero_fields,
    }:
        raise EvidenceError("canary_receipt_browser_smoke_shape_invalid")
    _require_schema(
        browser_smoke,
        HTML_BROWSER_SMOKE_SCHEMA_VERSION,
        "canary_receipt_browser_smoke",
    )
    smoke_observed_at = _require_fresh(
        browser_smoke,
        now=now,
        max_age_seconds=max_age_seconds,
        artifact="canary_receipt_browser_smoke",
    )
    if (
        browser_smoke.get("ok") is not True
        or browser_smoke.get("machine_generated") is not True
        or browser_smoke.get("source") != "chromium_cdp_network_runtime_log"
        or browser_smoke.get("engine") != "chromium"
        or browser_smoke.get("artifact_policy") != HTML_ARTIFACT_POLICY_VERSION
        or browser_smoke.get("artifact_set_id") != artifact_set_id
        or browser_smoke.get("report_url") != report_url
        or browser_smoke.get("index_html_sha256")
        != artifact_files["index_html"]["sha256"]
        or browser_smoke.get("manifest_sha256") != manifest_sha256
        or browser_smoke.get("network_closure") != "manifest_allowlist"
        or browser_smoke.get("desktop_nonblank") is not True
        or browser_smoke.get("mobile_nonblank") is not True
        or browser_smoke.get("blockers") != []
    ):
        raise EvidenceError("canary_receipt_browser_smoke_failed")
    for field in (
        "executable_script_count",
        "inline_event_handler_count",
        "external_active_document_count",
        "unmanifested_request_count",
        "console_error_count",
        "runtime_exception_count",
        "log_error_count",
        "network_error_count",
    ):
        if (
            _exact_int(
                browser_smoke.get(field),
                f"canary_receipt.report.browser_smoke.{field}",
                minimum=0,
            )
            != 0
        ):
            raise EvidenceError("canary_receipt_browser_smoke_failed")

    requested_urls = browser_smoke.get("requested_urls")
    if (
        not isinstance(requested_urls, list)
        or not requested_urls
        or len(requested_urls) > 512
        or not all(isinstance(value, str) and value for value in requested_urls)
        or requested_urls != sorted(set(requested_urls))
        or report_url not in requested_urls
    ):
        raise EvidenceError("canary_receipt_browser_smoke_failed")
    try:
        for requested_url in requested_urls:
            validate_report_asset_url(
                requested_url,
                submission_key=submission_key,
                artifact_set_id=artifact_set_id,
            )
    except DeliveryContractError as exc:
        raise EvidenceError("canary_receipt_browser_smoke_failed") from exc
    if _sha256_json(requested_urls) != _sha256_digest(
        browser_smoke.get("request_list_sha256"),
        "canary_receipt.report.browser_smoke.request_list_sha256",
    ):
        raise EvidenceError("canary_receipt_browser_smoke_failed")
    manifest_url_count = _exact_int(
        browser_smoke.get("manifest_url_count"),
        "canary_receipt.report.browser_smoke.manifest_url_count",
        minimum=1,
    )
    request_count = _exact_int(
        browser_smoke.get("request_count"),
        "canary_receipt.report.browser_smoke.request_count",
        minimum=1,
    )
    if manifest_url_count > 512 or manifest_url_count < len(requested_urls):
        raise EvidenceError("canary_receipt_browser_smoke_failed")
    if request_count < len(requested_urls):
        raise EvidenceError("canary_receipt_browser_smoke_failed")
    _sha256_digest(
        browser_smoke.get("manifest_url_set_sha256"),
        "canary_receipt.report.browser_smoke.manifest_url_set_sha256",
    )

    viewport_specs = {
        "desktop": (1440, 1000, 1.0, False),
        "mobile": (390, 844, 3.0, True),
    }
    viewports = _mapping(
        browser_smoke.get("viewports"),
        "canary_receipt.report.browser_smoke.viewports",
    )
    if set(viewports) != set(viewport_specs):
        raise EvidenceError("canary_receipt_browser_smoke_failed")
    view_requested_urls: set[str] = set()
    summed_counts = {
        field: 0
        for field in (
            "request_count",
            "unmanifested_request_count",
            "executable_script_count",
            "inline_event_handler_count",
            "external_active_document_count",
            "console_error_count",
            "runtime_exception_count",
            "log_error_count",
            "network_error_count",
        )
    }
    for name, (width, height, scale, mobile) in viewport_specs.items():
        viewport = _mapping(
            viewports.get(name),
            f"canary_receipt.report.browser_smoke.viewports.{name}",
        )
        if set(viewport) != {
            "name",
            "width",
            "height",
            "device_scale_factor",
            "mobile",
            "nonblank",
            "request_count",
            "requested_urls",
            "request_list_sha256",
            "unmanifested_urls",
            "visible_element_count",
            "visible_text_length",
            "visible_media_count",
            "document_width",
            "document_height",
            "title_sha256",
            "index_html_sha256",
            "index_html_size_bytes",
            *browser_zero_fields,
        }:
            raise EvidenceError("canary_receipt_browser_smoke_failed")
        if (
            viewport.get("name") != name
            or viewport.get("width") != width
            or viewport.get("height") != height
            or viewport.get("device_scale_factor") != scale
            or viewport.get("mobile") is not mobile
            or viewport.get("nonblank") is not True
            or viewport.get("unmanifested_urls") != []
            or viewport.get("index_html_sha256")
            != artifact_files["index_html"]["sha256"]
            or viewport.get("index_html_size_bytes")
            != artifact_files["index_html"]["size_bytes"]
        ):
            raise EvidenceError("canary_receipt_browser_smoke_failed")
        view_urls = viewport.get("requested_urls")
        if (
            not isinstance(view_urls, list)
            or not view_urls
            or view_urls != sorted(set(view_urls))
            or not all(value in requested_urls for value in view_urls)
            or _sha256_json(view_urls) != viewport.get("request_list_sha256")
        ):
            raise EvidenceError("canary_receipt_browser_smoke_failed")
        view_requested_urls.update(view_urls)
        for field in summed_counts:
            summed_counts[field] += _exact_int(
                viewport.get(field),
                f"canary_receipt.report.browser_smoke.viewports.{name}.{field}",
                minimum=0,
            )
    if sorted(view_requested_urls) != requested_urls or any(
        browser_smoke.get(field) != value for field, value in summed_counts.items()
    ):
        raise EvidenceError("canary_receipt_browser_smoke_failed")

    browser = _mapping(
        browser_smoke.get("browser"), "canary_receipt.report.browser_smoke.browser"
    )
    if (
        set(browser) != {"executable", "product", "protocol_version"}
        or not str(browser.get("executable") or "").startswith("/")
        or not str(browser.get("product") or "").strip()
        or not str(browser.get("protocol_version") or "").strip()
    ):
        raise EvidenceError("canary_receipt_browser_smoke_failed")
    evidence_sha256 = _sha256_digest(
        browser_smoke.get("evidence_sha256"),
        "canary_receipt.report.browser_smoke.evidence_sha256",
    )
    evidence_material = dict(browser_smoke)
    evidence_material.pop("evidence_sha256", None)
    if _sha256_json(evidence_material) != evidence_sha256:
        raise EvidenceError("canary_receipt_browser_smoke_failed")

    if delivery.get("artifact_set_id") != artifact_set_id:
        raise EvidenceError("canary_receipt_artifact_set_mismatch")
    if delivery.get("report_url") != report_url:
        raise EvidenceError("canary_receipt_report_url_mismatch")
    effect_key = _required_text(
        delivery.get("effect_key"), "canary_receipt.delivery.effect_key"
    )
    target_key = _required_text(
        delivery.get("target_key"), "canary_receipt.delivery.target_key"
    )
    marker = _required_text(delivery.get("marker"), "canary_receipt.delivery.marker")
    expected_marker = f"[RCA_DELIVERY:{effect_key}:{artifact_set_id[-12:]}]"
    if marker != expected_marker:
        raise EvidenceError("canary_receipt_delivery_marker_invalid")
    remote_receipt = _mapping(
        delivery.get("remote_receipt"), "canary_receipt.delivery.remote_receipt"
    )
    if set(remote_receipt) != {"remote_id", "confirmed_field_keys"}:
        raise EvidenceError("canary_receipt_delivery_remote_receipt_shape_invalid")
    remote_id = _required_text(
        remote_receipt.get("remote_id"),
        "canary_receipt.delivery.remote_receipt.remote_id",
    )
    if remote_receipt.get("confirmed_field_keys") != [
        "field_9193cb",
        "field_8c912e",
    ]:
        raise EvidenceError("canary_receipt_delivery_result_fields_unconfirmed")
    obligations_detail = _check_delivery_obligations(
        delivery_obligations,
        admission=admission,
        observed_source=observed_source,
        primary_delivery=delivery,
    )
    legacy_violation = find_rca_legacy_download_violation(body)
    if legacy_violation:
        raise EvidenceError(
            "canary_receipt_legacy_download_field_present", legacy_violation
        )
    return {
        "observed_at": observed_at,
        "execution_origin": execution_origin,
        "observed_trigger_source": observed_source,
        "submission_count": 1,
        "submission_key": submission_key,
        "admission": {
            "business_key": admission["business_key"],
            "submission_key": admission["submission_key"],
            "generation": admission["generation"],
        },
        "execution_request": request_detail,
        "remote_read": remote_read_detail,
        "derived_capacity_lifecycle": capacity_lifecycle_detail,
        "capacity_meter": capacity_meter_detail,
        "pipeline": pipeline_detail,
        "outbox_status": "completed",
        "vm_terminal_state": "completed",
        "vm_execution": vm_execution_detail,
        "artifact_set_id": artifact_set_id,
        "report_url": report_url,
        "manifest_sha256": manifest_sha256,
        "artifact_files": artifact_files,
        "html_validation": "html_delivery_ready",
        "artifact_policy": HTML_ARTIFACT_POLICY_VERSION,
        "browser_smoke_observed_at": smoke_observed_at,
        "effect_key": effect_key,
        "target_key": target_key,
        "delivery_marker_sha256": hashlib.sha256(marker.encode("utf-8")).hexdigest(),
        "remote_id": remote_id,
        "delivery_obligations": obligations_detail,
    }


def validate_canary_receipt(
    body: Mapping[str, Any],
    *,
    expected_execution_origin_id: str,
    expected_execution_origin_kind: str,
    expected_observed_source_id: str,
    expected_observed_source_kind: str,
    expected_request_sha256: str,
    expected_admission: Mapping[str, Any],
    expected_reader_fingerprint: str,
    expected_requested_scope: Mapping[str, Any],
    expected_vm_commit: str,
    expected_vm_worker_commit: str,
    expected_vm_service_entrypoint_sha256: str,
    expected_vm_worker_entrypoint_sha256: str,
    now: datetime,
    max_age_seconds: int,
    expected_manual_chat_ids: Sequence[str] = (),
    expected_operator_config: CutoverConfig | None = None,
    expected_capacity_mode: str | None = None,
    expected_release_bom_sha256: str = "",
) -> dict[str, Any]:
    """Pure public validator shared by the receipt producer and release gate."""
    return _check_canary_receipt(
        body,
        expected_execution_origin_id=expected_execution_origin_id,
        expected_execution_origin_kind=expected_execution_origin_kind,
        expected_observed_source_id=expected_observed_source_id,
        expected_observed_source_kind=expected_observed_source_kind,
        expected_manual_chat_ids=expected_manual_chat_ids,
        expected_operator_config=expected_operator_config,
        expected_request_sha256=expected_request_sha256,
        expected_admission=expected_admission,
        expected_reader_fingerprint=expected_reader_fingerprint,
        expected_requested_scope=expected_requested_scope,
        expected_vm_commit=expected_vm_commit,
        expected_vm_worker_commit=expected_vm_worker_commit,
        expected_vm_service_entrypoint_sha256=(expected_vm_service_entrypoint_sha256),
        expected_vm_worker_entrypoint_sha256=(expected_vm_worker_entrypoint_sha256),
        expected_capacity_mode=expected_capacity_mode,
        expected_release_bom_sha256=expected_release_bom_sha256,
        now=now,
        max_age_seconds=max_age_seconds,
    )


def validate_manual_success_canary(
    body: Mapping[str, Any],
    *,
    expected_manual_chat_ids: Sequence[str],
    expected_operator_config: CutoverConfig,
    expected_reader_fingerprint: str,
    expected_requested_scope: Mapping[str, Any],
    expected_vm_commit: str,
    expected_vm_worker_commit: str,
    expected_vm_service_entrypoint_sha256: str,
    expected_vm_worker_entrypoint_sha256: str,
    expected_rule_version: str,
    expected_workflow_policy: Mapping[str, Any],
    now: datetime,
    max_age_seconds: int,
    expected_capacity_mode: str | None = None,
    expected_release_bom_sha256: str = "",
) -> dict[str, Any]:
    execution_origin = _mapping(
        body.get("execution_origin"), "manual_success_canary.execution_origin"
    )
    observed_source = _mapping(
        body.get("observed_trigger_source"),
        "manual_success_canary.observed_trigger_source",
    )
    admission = _mapping(body.get("admission"), "manual_success_canary.admission")
    execution_request = _mapping(
        body.get("execution_request"), "manual_success_canary.execution_request"
    )
    detail = validate_canary_receipt(
        body,
        expected_execution_origin_id=_required_text(
            execution_origin.get("source_id"), "manual_success_canary.origin.source_id"
        ),
        expected_execution_origin_kind="manual_issue_request",
        expected_observed_source_id=_required_text(
            observed_source.get("source_id"),
            "manual_success_canary.observed_source.source_id",
        ),
        expected_observed_source_kind="manual_issue_request",
        expected_request_sha256=_sha256_execution_request(execution_request),
        expected_admission=admission,
        expected_reader_fingerprint=expected_reader_fingerprint,
        expected_requested_scope=expected_requested_scope,
        expected_vm_commit=expected_vm_commit,
        expected_vm_worker_commit=expected_vm_worker_commit,
        expected_vm_service_entrypoint_sha256=(
            expected_vm_service_entrypoint_sha256
        ),
        expected_vm_worker_entrypoint_sha256=(
            expected_vm_worker_entrypoint_sha256
        ),
        now=now,
        max_age_seconds=max_age_seconds,
        expected_manual_chat_ids=expected_manual_chat_ids,
        expected_operator_config=expected_operator_config,
        expected_capacity_mode=expected_capacity_mode,
        expected_release_bom_sha256=expected_release_bom_sha256,
    )
    try:
        validated_admission = validate_rca_admission(admission).to_dict()
    except RcaAdmissionError as exc:
        raise EvidenceError("manual_success_canary_admission_invalid") from exc
    admission_refs = _mapping(
        validated_admission.get("source_refs"),
        "manual_success_canary.admission.source_refs",
    )
    policy_detail = _check_manual_admission_policy(
        validated_admission,
        expected_rule_version=expected_rule_version,
        expected_workflow_policy=expected_workflow_policy,
        artifact="manual_success_canary",
    )
    request_refs = _mapping(
        execution_request.get("source_refs"),
        "manual_success_canary.execution_request.source_refs",
    )
    validated_origin = _mapping(
        detail.get("execution_origin"), "manual_success_canary.validated_origin"
    )
    validated_observed = _mapping(
        detail.get("observed_trigger_source"),
        "manual_success_canary.validated_observed_source",
    )
    if (
        validated_origin != validated_observed
        or validated_origin.get("storage_source_kind") != "feishu_group_manual"
        or validated_origin.get("source_kind") != "manual_issue_request"
        or validated_origin.get("mode") != "run_or_join"
        or validated_origin.get("outcome") != "created"
        or validated_origin.get("binding_role") != "origin"
        or validated_origin.get("generation") != 1
        or validated_origin.get("chat_id") != G1Q3_RCA_GROUP_ID
        or validated_admission.get("trigger_kind") != "manual_issue_request"
        or validated_admission.get("generation") != 1
        or admission_refs.get("topic") != ""
        or admission_refs.get("partition") is not None
        or admission_refs.get("offset") is not None
        or request_refs.get("source_kind") != "feishu_group_manual"
        or request_refs.get("origin_source_id") != validated_origin.get("source_id")
        or any(
            key in request_refs
            for key in ("source_event_id", "topic", "partition", "offset")
        )
    ):
        raise EvidenceError("manual_success_canary_origin_invalid")
    if {
        item.get("effect_kind")
        for item in detail.get("delivery_obligations", [])
        if isinstance(item, Mapping)
    } != {"feishu_issue_comment", "feishu_thread_reply"}:
        raise EvidenceError("manual_success_canary_delivery_incomplete")
    detail["manual_policy"] = policy_detail
    return detail


def _check_manual_admission_policy(
    admission: Mapping[str, Any],
    *,
    expected_rule_version: str,
    expected_workflow_policy: Mapping[str, Any],
    artifact: str,
) -> dict[str, Any]:
    refs = _mapping(admission.get("source_refs"), f"{artifact}.admission.source_refs")
    policy = _mapping(expected_workflow_policy, f"{artifact}.workflow_policy")
    required_policy_keys = {
        "topic",
        "policy_version",
        "project_keys",
        "project_simple_names",
        "work_item_type_keys",
        "status_change_types",
        "transitions",
        "snapshot_patterns",
        "snapshot_sub_stages",
    }
    if set(policy) != required_policy_keys:
        raise EvidenceError(f"{artifact}_workflow_policy_invalid")
    project_keys = policy.get("project_keys")
    project_simple_names = policy.get("project_simple_names")
    work_item_type_keys = policy.get("work_item_type_keys")
    if (
        policy.get("policy_version") != expected_rule_version
        or refs.get("rule_version") != expected_rule_version
        or not isinstance(project_keys, list)
        or refs.get("project_key") not in project_keys
        or not isinstance(project_simple_names, list)
        or refs.get("project_simple_name") not in project_simple_names
        or not isinstance(work_item_type_keys, list)
        or refs.get("work_item_type_key") not in work_item_type_keys
    ):
        raise EvidenceError(f"{artifact}_admission_policy_mismatch")
    return {
        "creation_rule_version": expected_rule_version,
        "workflow_event_policy_sha256": _sha256_json(policy),
    }


def _canary_source_record(
    files: Mapping[str, Any],
    name: str,
    *,
    json_source: bool,
) -> dict[str, Any]:
    record = _mapping(files.get(name), f"canary_receipt_sources.files.{name}")
    expected_keys = {"path", "size_bytes", "raw_sha256"}
    if json_source:
        expected_keys.add("canonical_sha256")
    if set(record) != expected_keys:
        raise EvidenceError("canary_receipt_sources_file_shape_invalid")
    path = _required_text(record.get("path"), f"canary_receipt_sources.{name}.path")
    if (
        not PurePosixPath(path).is_absolute()
        or ".." in PurePosixPath(path).parts
        or "\\" in path
        or "\x00" in path
    ):
        raise EvidenceError("canary_receipt_sources_file_path_invalid")
    size_bytes = _exact_int(
        record.get("size_bytes"),
        f"canary_receipt_sources.{name}.size_bytes",
        minimum=1,
    )
    if size_bytes > REMOTE_READ_MAX_OUTPUT_BYTES:
        raise EvidenceError("canary_receipt_sources_file_size_invalid")
    result = {
        "path": path,
        "size_bytes": size_bytes,
        "raw_sha256": _sha256_digest(
            record.get("raw_sha256"),
            f"canary_receipt_sources.{name}.raw_sha256",
        ),
    }
    if json_source:
        if size_bytes > MAX_EVIDENCE_BYTES:
            raise EvidenceError("canary_receipt_sources_file_size_invalid")
        result["canonical_sha256"] = _sha256_digest(
            record.get("canonical_sha256"),
            f"canary_receipt_sources.{name}.canonical_sha256",
        )
    return result


def _read_bound_canary_local_source(
    record: Mapping[str, Any],
    *,
    expected_path: Path,
    expected_body: Mapping[str, Any],
    artifact: str,
) -> dict[str, Any]:
    expected = expected_path.expanduser().absolute()
    if record.get("path") != str(expected):
        raise EvidenceError("canary_receipt_sources_local_path_mismatch")
    descriptor = -1
    try:
        info = os.lstat(expected)
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISREG(info.st_mode):
            raise EvidenceError("canary_receipt_sources_local_file_invalid")
        if expected.resolve(strict=True) != expected:
            raise EvidenceError("canary_receipt_sources_local_file_invalid")
        if info.st_size <= 0 or info.st_size > MAX_EVIDENCE_BYTES:
            raise EvidenceError("canary_receipt_sources_local_file_invalid")
        descriptor = os.open(
            expected,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
        )
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_dev != info.st_dev
            or opened.st_ino != info.st_ino
            or opened.st_size != info.st_size
        ):
            raise EvidenceError("canary_receipt_sources_local_file_invalid")
        remaining = info.st_size
        chunks: list[bytes] = []
        while remaining:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise EvidenceError("canary_receipt_sources_local_file_invalid")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise EvidenceError("canary_receipt_sources_local_file_invalid")
        raw = b"".join(chunks)
    except EvidenceError:
        raise
    except OSError as exc:
        raise EvidenceError("canary_receipt_sources_local_file_invalid") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    try:
        decoded = raw.decode("utf-8")
    except UnicodeError as exc:
        raise EvidenceError("canary_receipt_sources_local_file_invalid") from exc
    body = _mapping(
        _strict_json_loads(decoded, artifact=artifact),
        f"canary_receipt_sources.{artifact}",
    )
    if body != dict(expected_body):
        raise EvidenceError("canary_receipt_sources_local_body_mismatch")
    if (
        record.get("size_bytes") != len(raw)
        or record.get("raw_sha256") != hashlib.sha256(raw).hexdigest()
        or record.get("canonical_sha256") != _sha256_json(body)
    ):
        raise EvidenceError("canary_receipt_sources_local_hash_mismatch")
    return {
        "path": str(expected),
        "size_bytes": len(raw),
        "raw_sha256": hashlib.sha256(raw).hexdigest(),
        "canonical_sha256": _sha256_json(body),
    }


def _read_bound_group_authorization_source(
    record: Mapping[str, Any],
    *,
    evidence: Mapping[str, Any],
    expected_root: Path,
) -> dict[str, Any]:
    path = Path(
        _required_text(evidence.get("receipt_path"), "authorization.receipt_path")
    ).expanduser()
    if record.get("path") != str(path):
        raise EvidenceError("canary_authorization_source_path_mismatch")
    configured_root = expected_root.expanduser().absolute()
    decision_at = _timestamp(
        evidence.get("timestamp"),
        "authorization.timestamp",
    )
    expected_filename = pnc_group_binding_receipt_filename(
        receipt_date=decision_at.date(),
        platform=evidence.get("platform"),
        chat_id=evidence.get("chat_id"),
        user_id=evidence.get("requester_id"),
        message_id=evidence.get("message_id"),
    )
    root_descriptor = -1
    try:
        root_info = os.lstat(configured_root)
        if (
            stat.S_ISLNK(root_info.st_mode)
            or not stat.S_ISDIR(root_info.st_mode)
            or root_info.st_uid != os.getuid()
            or stat.S_IMODE(root_info.st_mode) != 0o700
            or configured_root.resolve(strict=True) != configured_root
            or path.absolute().parent != configured_root
            or GROUP_BINDING_RECEIPT_FILENAME_RE.fullmatch(path.name) is None
            or path.name != expected_filename
        ):
            raise EvidenceError("canary_authorization_source_root_invalid")
        root_descriptor = os.open(
            configured_root,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0),
        )
        opened_root = os.fstat(root_descriptor)
        if (
            not stat.S_ISDIR(opened_root.st_mode)
            or (opened_root.st_dev, opened_root.st_ino)
            != (root_info.st_dev, root_info.st_ino)
            or opened_root.st_uid != os.getuid()
            or stat.S_IMODE(opened_root.st_mode) != 0o700
        ):
            raise EvidenceError("canary_authorization_source_root_invalid")
    except EvidenceError:
        if root_descriptor >= 0:
            os.close(root_descriptor)
        raise
    except OSError as exc:
        if root_descriptor >= 0:
            os.close(root_descriptor)
        raise EvidenceError("canary_authorization_source_root_invalid") from exc
    descriptor = -1
    try:
        info = os.lstat(path)
        if (
            stat.S_ISLNK(info.st_mode)
            or not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.getuid()
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) != 0o600
            or path.resolve(strict=True) != path.absolute()
            or info.st_size <= 0
            or info.st_size > MAX_EVIDENCE_BYTES
        ):
            raise EvidenceError("canary_authorization_source_invalid")
        descriptor = os.open(
            path.name,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=root_descriptor,
        )
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_dev != info.st_dev
            or opened.st_ino != info.st_ino
            or opened.st_size != info.st_size
            or opened.st_uid != os.getuid()
            or opened.st_nlink != 1
            or stat.S_IMODE(opened.st_mode) != 0o600
        ):
            raise EvidenceError("canary_authorization_source_invalid")
        remaining = opened.st_size
        chunks: list[bytes] = []
        while remaining:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise EvidenceError("canary_authorization_source_invalid")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise EvidenceError("canary_authorization_source_invalid")
        final_opened = os.fstat(descriptor)
        final_path = os.lstat(path)
        final_opened_root = os.fstat(root_descriptor)
        final_root = os.lstat(configured_root)
        if (
            final_opened.st_dev != info.st_dev
            or final_opened.st_ino != info.st_ino
            or final_opened.st_size != info.st_size
            or final_opened.st_mtime_ns != info.st_mtime_ns
            or final_path.st_dev != info.st_dev
            or final_path.st_ino != info.st_ino
            or final_path.st_size != info.st_size
            or final_path.st_mtime_ns != info.st_mtime_ns
            or final_path.st_uid != os.getuid()
            or final_path.st_nlink != 1
            or stat.S_IMODE(final_path.st_mode) != 0o600
            or (final_opened_root.st_dev, final_opened_root.st_ino)
            != (root_info.st_dev, root_info.st_ino)
            or (final_root.st_dev, final_root.st_ino)
            != (root_info.st_dev, root_info.st_ino)
            or final_root.st_uid != os.getuid()
            or stat.S_IMODE(final_root.st_mode) != 0o700
        ):
            raise EvidenceError("canary_authorization_source_invalid")
        raw = b"".join(chunks)
    except EvidenceError:
        raise
    except OSError as exc:
        raise EvidenceError("canary_authorization_source_invalid") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        if root_descriptor >= 0:
            os.close(root_descriptor)
    if len(raw) != info.st_size or len(raw) > MAX_EVIDENCE_BYTES:
        raise EvidenceError("canary_authorization_source_invalid")
    records: list[dict[str, Any]] = []
    for line in raw.splitlines():
        if not line.strip():
            continue
        try:
            decoded = line.decode("utf-8")
        except UnicodeError as exc:
            raise EvidenceError("canary_authorization_source_invalid") from exc
        item = _strict_json_loads(decoded, artifact="group_binding_authorization")
        records.append(_mapping(item, "group_binding_authorization.record"))
    canonical = _sha256_json({"records": records})
    if (
        record.get("size_bytes") != len(raw)
        or record.get("raw_sha256") != hashlib.sha256(raw).hexdigest()
        or record.get("canonical_sha256") != canonical
        or record.get("raw_sha256") != evidence.get("file_raw_sha256")
    ):
        raise EvidenceError("canary_authorization_source_hash_mismatch")
    line_number = _exact_int(
        evidence.get("line_number"), "authorization.line_number", minimum=1
    )
    if len(records) != 1 or line_number != 1:
        raise EvidenceError("canary_authorization_source_line_missing")
    selected = records[line_number - 1]
    if (
        _sha256_json(selected) != evidence.get("record_sha256")
        or selected.get("timestamp") != evidence.get("timestamp")
        or selected.get("platform") != evidence.get("platform")
        or selected.get("group_id") != evidence.get("chat_id")
        or selected.get("message_id") != evidence.get("message_id")
        or selected.get("requester") != evidence.get("requester_id")
        or selected.get("decision") != evidence.get("decision")
        or selected.get("route_surface") != evidence.get("route_surface")
        or selected.get("risk_gate") != evidence.get("risk_gate")
        or selected.get("manual_authorization") != evidence.get("manual_authorization")
        or selected.get("gateway_runtime_identity")
        != evidence.get("gateway_runtime_identity")
    ):
        raise EvidenceError("canary_authorization_source_record_mismatch")
    return {
        "path": str(path),
        "size_bytes": len(raw),
        "raw_sha256": hashlib.sha256(raw).hexdigest(),
        "canonical_sha256": canonical,
        "record_sha256": str(evidence["record_sha256"]),
    }


def _observe_live_database_identity(
    path: Path,
    *,
    unreadable_code: str,
    invalid_code: str,
) -> tuple[Path, os.stat_result]:
    configured_path = path.expanduser().absolute()
    descriptor = -1
    try:
        initial_info = os.lstat(configured_path)
        if (
            stat.S_ISLNK(initial_info.st_mode)
            or not stat.S_ISREG(initial_info.st_mode)
            or initial_info.st_size <= 0
        ):
            raise EvidenceError(invalid_code)
        resolved_path = configured_path.resolve(strict=True)
        if resolved_path != configured_path:
            raise EvidenceError(invalid_code)
        descriptor = os.open(
            configured_path,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0),
        )
        opened_info = os.fstat(descriptor)
        final_info = os.lstat(configured_path)
    except EvidenceError:
        raise
    except OSError as exc:
        raise EvidenceError(unreadable_code) from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    if (
        not stat.S_ISREG(opened_info.st_mode)
        or opened_info.st_size <= 0
        or stat.S_ISLNK(final_info.st_mode)
        or not stat.S_ISREG(final_info.st_mode)
        or final_info.st_size <= 0
        or (initial_info.st_dev, initial_info.st_ino)
        != (opened_info.st_dev, opened_info.st_ino)
        or (opened_info.st_dev, opened_info.st_ino)
        != (final_info.st_dev, final_info.st_ino)
    ):
        raise EvidenceError(invalid_code)
    return resolved_path, opened_info


def _read_live_canary_database_facts(
    *,
    control_db_path: Path,
    delivery_db_path: Path,
    evidence_dir: Path,
    group_binding_receipt_dir: Path,
    manual_chat_ids: Sequence[str],
    source_id: str,
    terminal_failure: bool,
) -> dict[str, Any]:
    try:
        from scripts.pnc_rca_canary_collector import (
            CanaryCollectionError,
            CollectorConfig,
            read_local_canary_database_facts,
        )

        facts = read_local_canary_database_facts(
            CollectorConfig(
                control_db_path=control_db_path,
                delivery_db_path=delivery_db_path,
                evidence_dir=evidence_dir,
                group_binding_receipt_dir=group_binding_receipt_dir,
                manual_chat_ids=tuple(manual_chat_ids),
            ),
            source_id,
            terminal_failure=terminal_failure,
        )
    except (ImportError, CanaryCollectionError, OSError, ValueError) as exc:
        detail = getattr(exc, "code", type(exc).__name__)
        raise EvidenceError("canary_database_live_requery_failed", str(detail)) from exc
    if not isinstance(facts, Mapping):
        raise EvidenceError("canary_database_live_requery_invalid")
    return dict(facts)


def _check_canary_runtime_transition_chain(
    facts: Mapping[str, Any],
    *,
    receipt: Mapping[str, Any],
) -> list[dict[str, Any]]:
    raw_transitions = facts.get("host_runtime_transitions")
    if not isinstance(raw_transitions, list):
        raise EvidenceError("canary_runtime_transition_shape_invalid")
    submission_key = _required_text(
        facts.get("submission_key"), "canary_runtime_transition.submission_key"
    )
    business_key = _required_text(
        facts.get("business_key"), "canary_runtime_transition.business_key"
    )
    generation = _exact_int(
        facts.get("generation"), "canary_runtime_transition.generation", minimum=1
    )
    outbox_id = _exact_int(
        facts.get("outbox_id"), "canary_runtime_transition.outbox_id", minimum=1
    )
    observed_at = _timestamp(
        receipt.get("observed_at"), "canary_runtime_transition.observed_at"
    )
    origin = _mapping(
        facts.get("execution_origin"), "canary_runtime_transition.execution_origin"
    )
    obligations_raw = facts.get("delivery_obligations")
    if not isinstance(obligations_raw, list) or not obligations_raw:
        raise EvidenceError("canary_runtime_transition_obligations_invalid")
    obligations = [
        _mapping(item, f"canary_runtime_transition.obligations[{index}]")
        for index, item in enumerate(obligations_raw)
    ]
    delivery_ids = {
        _required_text(item.get("delivery_id"), "canary_runtime_transition.delivery_id")
        for item in obligations
    }
    effect_keys = {
        _required_text(item.get("effect_key"), "canary_runtime_transition.effect_key")
        for item in obligations
    }
    if len(delivery_ids) != 1 or len(effect_keys) != len(obligations):
        raise EvidenceError("canary_runtime_transition_obligations_invalid")
    [delivery_id] = delivery_ids

    expected: dict[tuple[str, str, str], str] = {
        (
            "local.pnc.rca-outbox-dispatcher",
            "outbox_completed",
            str(outbox_id),
        ): "outbox",
        (
            "local.pnc.rca-delivery-collector",
            "delivery_created",
            delivery_id,
        ): "collector",
    }
    for effect_key in sorted(effect_keys):
        expected[(
            "local.pnc.rca-delivery-dispatcher",
            "effect_succeeded",
            effect_key,
        )] = f"effect:{effect_key}"
    if origin.get("storage_source_kind") == "kafka_workflow_event":
        event_uid = _required_text(
            origin.get("kafka_event_uid"),
            "canary_runtime_transition.kafka_event_uid",
        )
        expected[(
            "local.pnc.rca-kafka-consumer",
            "kafka_ingested",
            event_uid,
        )] = "kafka"
    elif origin.get("storage_source_kind") != "feishu_group_manual":
        raise EvidenceError("canary_runtime_transition_origin_invalid")

    projected: list[dict[str, Any]] = []
    observed: dict[tuple[str, str, str], datetime] = {}
    for index, raw in enumerate(raw_transitions):
        item = _mapping(raw, f"canary_runtime_transition.rows[{index}]")
        if set(item) != {
            "submission_key",
            "business_key",
            "generation",
            "service_label",
            "transition_kind",
            "entity_key",
            "runtime_identity",
            "runtime_identity_sha256",
            "transitioned_at",
        }:
            raise EvidenceError("canary_runtime_transition_shape_invalid")
        if (
            item.get("submission_key") != submission_key
            or item.get("business_key") != business_key
            or item.get("generation") != generation
        ):
            raise EvidenceError("canary_runtime_transition_identity_invalid")
        label = _required_text(
            item.get("service_label"), "canary_runtime_transition.service_label"
        )
        kind = _required_text(
            item.get("transition_kind"), "canary_runtime_transition.transition_kind"
        )
        entity_key = _required_text(
            item.get("entity_key"), "canary_runtime_transition.entity_key"
        )
        key = (label, kind, entity_key)
        if key not in expected or key in observed:
            raise EvidenceError("canary_runtime_transition_topology_invalid")
        identity = _mapping(
            item.get("runtime_identity"), "canary_runtime_transition.runtime_identity"
        )
        if (
            set(identity) != RUNTIME_IDENTITY_FIELDS
            or identity.get("service_label") != label
            or item.get("runtime_identity_sha256") != _sha256_json(identity)
        ):
            raise EvidenceError("canary_runtime_transition_runtime_identity_invalid")
        process_create_time = _number(
            identity.get("process_create_time"),
            "canary_runtime_transition.process_create_time",
            minimum=1,
        )
        transitioned_at = _timestamp(
            item.get("transitioned_at"), "canary_runtime_transition.transitioned_at"
        )
        if (
            process_create_time > transitioned_at.timestamp()
            or transitioned_at > observed_at
        ):
            raise EvidenceError("canary_runtime_transition_timeline_invalid")
        observed[key] = transitioned_at
        projected.append(dict(item))
    if set(observed) != set(expected):
        raise EvidenceError("canary_runtime_transition_chain_incomplete")

    by_role = {expected[key]: timestamp for key, timestamp in observed.items()}
    sequence = []
    if "kafka" in by_role:
        sequence.append(by_role["kafka"])
    sequence.extend((by_role["outbox"], by_role["collector"]))
    effect_times = [
        by_role[f"effect:{effect_key}"] for effect_key in sorted(effect_keys)
    ]
    if any(left > right for left, right in zip(sequence, sequence[1:])) or any(
        by_role["collector"] > effect_time for effect_time in effect_times
    ):
        raise EvidenceError("canary_runtime_transition_causality_invalid")
    return sorted(
        projected,
        key=lambda item: (
            str(item["service_label"]),
            str(item["transition_kind"]),
            str(item["entity_key"]),
        ),
    )


def _check_live_canary_database_binding(
    *,
    receipt: Mapping[str, Any],
    control_snapshot_sha256: str,
    delivery_snapshot_sha256: str,
    control_db_path: Path,
    delivery_db_path: Path,
    evidence_dir: Path,
    group_binding_receipt_dir: Path,
    manual_chat_ids: Sequence[str],
    expected_workflow_policy: Mapping[str, Any],
    terminal_failure: bool,
) -> dict[str, Any]:
    source = _mapping(
        receipt.get("observed_trigger_source"),
        "canary_database.observed_trigger_source",
    )
    source_id = _required_text(source.get("source_id"), "canary_database.source_id")
    facts = _read_live_canary_database_facts(
        control_db_path=control_db_path,
        delivery_db_path=delivery_db_path,
        evidence_dir=evidence_dir,
        group_binding_receipt_dir=group_binding_receipt_dir,
        manual_chat_ids=manual_chat_ids,
        source_id=source_id,
        terminal_failure=terminal_failure,
    )
    control_snapshot = _sha256_digest(
        facts.get("control_snapshot_sha256"),
        "canary_database.control_snapshot_sha256",
    )
    delivery_snapshot = _sha256_digest(
        facts.get("delivery_snapshot_sha256"),
        "canary_database.delivery_snapshot_sha256",
    )
    if (
        control_snapshot != control_snapshot_sha256
        or delivery_snapshot != delivery_snapshot_sha256
    ):
        raise EvidenceError("canary_database_snapshot_mismatch")
    if (
        facts.get("admission") != receipt.get("admission")
        or facts.get("submission_key") != receipt.get("submission_key")
        or facts.get("observed_trigger_source") != source
        or facts.get("workflow_policy") != dict(expected_workflow_policy)
    ):
        raise EvidenceError("canary_database_control_projection_mismatch")
    if terminal_failure:
        if (
            facts.get("business_key") != receipt.get("business_key")
            or facts.get("generation") != receipt.get("generation")
            or facts.get("watch") != receipt.get("watch")
            or facts.get("delivery_job") != receipt.get("delivery_job")
            or facts.get("delivery_obligations")
            != receipt.get("delivery_obligations")
        ):
            raise EvidenceError("canary_database_terminal_projection_mismatch")
    else:
        if facts.get("execution_origin") != receipt.get("execution_origin"):
            raise EvidenceError("canary_database_control_projection_mismatch")
        live_report = _mapping(facts.get("report"), "canary_database.report")
        receipt_report = _mapping(receipt.get("report"), "canary_database.receipt.report")
        live_delivery = _mapping(facts.get("delivery"), "canary_database.delivery")
        if (
            {key: receipt_report.get(key) for key in live_report} != live_report
            or live_delivery != receipt.get("delivery")
            or facts.get("delivery_obligations")
            != receipt.get("delivery_obligations")
        ):
            raise EvidenceError("canary_database_delivery_projection_mismatch")
    host_runtime_transitions = _check_canary_runtime_transition_chain(
        facts,
        receipt=receipt,
    )
    projection = {
        "source_id_sha256": hashlib.sha256(source_id.encode("utf-8")).hexdigest(),
        "control_snapshot_sha256": control_snapshot,
        "delivery_snapshot_sha256": delivery_snapshot,
        "control_projection_sha256": _sha256_json({
            key: facts.get(key)
            for key in (
                "admission",
                "workflow_policy",
                "submission_key",
                "business_key",
                "generation",
                "execution_origin",
                "observed_trigger_source",
            )
        }),
        "delivery_projection_sha256": _sha256_json({
            key: facts.get(key)
            for key in (
                "report",
                "delivery",
                "watch",
                "delivery_job",
                "delivery_obligations",
            )
            if key in facts
        }),
        "terminal_failure": terminal_failure,
        "host_runtime_transitions": host_runtime_transitions,
        "host_runtime_transitions_sha256": _sha256_json(
            host_runtime_transitions
        ),
    }
    projection["projection_sha256"] = _sha256_json(projection)
    return projection


def _check_canary_source_provenance(
    body: Mapping[str, Any],
    *,
    receipt: Mapping[str, Any],
    settings: ReleaseGateSettings,
    expected_collector_sha256: str,
    expected_control_db_path: Path,
    expected_delivery_db_path: Path,
    expected_reader_health: Mapping[str, Any],
    expected_workflow_policy: Mapping[str, Any],
    expected_manual_chat_ids: Sequence[str] = (),
) -> dict[str, Any]:
    artifact = "canary_receipt_sources"
    _require_schema(body, CANARY_SOURCE_PROVENANCE_SCHEMA_VERSION, artifact)
    if set(body) != {
        "schema_version",
        "collected_at",
        "read_only",
        "external_side_effects",
        "collector",
        "execution_origin_sha256",
        "observed_trigger_source_sha256",
        "submission_key_sha256",
        "control_database",
        "delivery_database",
        "remote_transport",
        "local_machine_sources",
        "receipt_sha256",
    }:
        raise EvidenceError("canary_receipt_sources_shape_invalid")
    if (
        body.get("read_only") is not True
        or body.get("external_side_effects") is not False
        or body.get("collected_at") != receipt.get("observed_at")
        or body.get("receipt_sha256") != _sha256_json(receipt)
    ):
        raise EvidenceError("canary_receipt_sources_receipt_binding_mismatch")

    execution_origin = _mapping(
        receipt.get("execution_origin"), "canary_receipt.execution_origin"
    )
    observed_source = _mapping(
        receipt.get("observed_trigger_source"),
        "canary_receipt.observed_trigger_source",
    )
    submission_key = _required_text(
        receipt.get("submission_key"), "canary_receipt.submission_key"
    )
    if (
        body.get("execution_origin_sha256") != _sha256_json(execution_origin)
        or body.get("observed_trigger_source_sha256") != _sha256_json(observed_source)
        or body.get("submission_key_sha256")
        != hashlib.sha256(submission_key.encode("utf-8")).hexdigest()
    ):
        raise EvidenceError("canary_receipt_sources_identity_hash_mismatch")

    expected_collector_digest = _sha256_digest(
        expected_collector_sha256,
        "canary_receipt_sources.expected_collector_sha256",
    )
    collector = _mapping(body.get("collector"), "canary_receipt_sources.collector")
    if set(collector) != {"path", "sha256"}:
        raise EvidenceError("canary_receipt_sources_collector_shape_invalid")
    collector_name, collector_path = _critical_path(
        settings.host_repo_root, CANARY_COLLECTOR_RELATIVE_PATH
    )
    try:
        live_collector_digest = hashlib.sha256(collector_path.read_bytes()).hexdigest()
    except OSError as exc:
        raise EvidenceError("canary_receipt_sources_collector_unreadable") from exc
    if (
        collector_name != CANARY_COLLECTOR_RELATIVE_PATH
        or collector.get("path") != str(collector_path)
        or collector.get("sha256") != expected_collector_digest
        or live_collector_digest != expected_collector_digest
    ):
        raise EvidenceError("canary_receipt_sources_collector_bom_mismatch")

    database_details: dict[str, dict[str, Any]] = {}
    for name, expected_path in (
        ("control_database", expected_control_db_path),
        ("delivery_database", expected_delivery_db_path),
    ):
        database = _mapping(body.get(name), f"canary_receipt_sources.{name}")
        if set(database) != {
            "path",
            "device",
            "inode",
            "size_bytes",
            "mtime_ns",
            "query_mode",
            "snapshot_sha256",
        }:
            raise EvidenceError("canary_receipt_sources_database_shape_invalid")
        resolved_path, resolved_info = _observe_live_database_identity(
            expected_path,
            unreadable_code="canary_receipt_sources_database_unreadable",
            invalid_code="canary_receipt_sources_database_invalid",
        )
        normalized_path = str(resolved_path)
        if (
            database.get("path") != normalized_path
            or database.get("query_mode") != "sqlite_mode_ro_query_only_transaction"
        ):
            raise EvidenceError("canary_receipt_sources_database_binding_mismatch")
        device = _exact_int(
            database.get("device"), f"{artifact}.{name}.device", minimum=1
        )
        inode = _exact_int(database.get("inode"), f"{artifact}.{name}.inode", minimum=1)
        if device != resolved_info.st_dev or inode != resolved_info.st_ino:
            raise EvidenceError("canary_receipt_sources_database_identity_mismatch")
        database_details[name] = {
            "path": normalized_path,
            "device": device,
            "inode": inode,
            "size_bytes": _exact_int(
                database.get("size_bytes"),
                f"{artifact}.{name}.size_bytes",
                minimum=1,
            ),
            "mtime_ns": _exact_int(
                database.get("mtime_ns"), f"{artifact}.{name}.mtime_ns", minimum=1
            ),
            "snapshot_sha256": _sha256_digest(
                database.get("snapshot_sha256"),
                f"{artifact}.{name}.snapshot_sha256",
            ),
        }
    if (
        database_details["control_database"]["path"]
        == database_details["delivery_database"]["path"]
    ):
        control_identity = database_details["control_database"]
        delivery_identity = database_details["delivery_database"]
        if any(
            control_identity[key] != delivery_identity[key]
            for key in ("path", "device", "inode")
        ):
            raise EvidenceError("canary_receipt_sources_database_identity_mismatch")

    remote = _mapping(
        body.get("remote_transport"), "canary_receipt_sources.remote_transport"
    )
    if set(remote) != {"kind", "operation", "execution_request_abi", "files"}:
        raise EvidenceError("canary_receipt_sources_remote_shape_invalid")
    if (
        remote.get("kind") != "ssh-mini-agent"
        or remote.get("operation") != "bounded_read_only"
    ):
        raise EvidenceError("canary_receipt_sources_remote_transport_invalid")
    request = _mapping(
        receipt.get("execution_request"), "canary_receipt.execution_request"
    )
    request_sha256 = _sha256_execution_request(request)
    abi = _mapping(
        remote.get("execution_request_abi"),
        "canary_receipt_sources.execution_request_abi",
    )
    if abi != {
        "canonicalization": "json_ensure_ascii_false_sort_keys_compact_v1",
        "sha256": request_sha256,
    }:
        raise EvidenceError("canary_receipt_sources_request_abi_mismatch")

    files = _mapping(remote.get("files"), "canary_receipt_sources.files")
    expected_file_names = (
        CANARY_REMOTE_JSON_SOURCE_NAMES | CANARY_REMOTE_DIGEST_SOURCE_NAMES
    )
    if set(files) != expected_file_names:
        raise EvidenceError("canary_receipt_sources_remote_file_set_invalid")
    normalized_files = {
        name: _canary_source_record(
            files,
            name,
            json_source=name in CANARY_REMOTE_JSON_SOURCE_NAMES,
        )
        for name in sorted(expected_file_names)
    }

    data = _mapping(request.get("data"), "canary_receipt.execution_request.data")
    artifact_root = _required_text(data.get("artifact_root"), "artifact_root")
    vm = _mapping(receipt.get("vm"), "canary_receipt.vm")
    capacity_admission = _mapping(
        vm.get("capacity_admission"),
        "canary_receipt.vm.capacity_admission",
    )
    worker_wrapper = _mapping(
        vm.get("worker_result"), "canary_receipt.vm.worker_result"
    )
    service_wrapper = _mapping(
        vm.get("service_result"), "canary_receipt.vm.service_result"
    )
    service_receipt = _mapping(
        service_wrapper.get("receipt"), "canary_receipt.vm.service_result.receipt"
    )
    request_storage = _mapping(
        service_receipt.get("request_storage"),
        "canary_receipt.vm.service_result.receipt.request_storage",
    )
    remote_read = _mapping(receipt.get("remote_read"), "canary_receipt.remote_read")
    remote_read_receipt = _mapping(
        remote_read.get("receipt"), "canary_receipt.remote_read.receipt"
    )
    stream_cache = _mapping(
        remote_read_receipt.get("derived_stream_cache"),
        "canary_receipt.remote_read.receipt.derived_stream_cache",
    )
    capacity_meter = _mapping(
        receipt.get("capacity_meter"), "canary_receipt.capacity_meter"
    )
    pipeline = _mapping(receipt.get("pipeline"), "canary_receipt.pipeline")
    report = _mapping(receipt.get("report"), "canary_receipt.report")
    manifest_wrapper = _mapping(
        report.get("delivery_manifest"), "canary_receipt.report.delivery_manifest"
    )
    manifest_body = _mapping(
        manifest_wrapper.get("body"), "canary_receipt.report.delivery_manifest.body"
    )
    smoke = _mapping(report.get("browser_smoke"), "canary_receipt.report.browser_smoke")
    downstream = _mapping(
        pipeline.get("downstream_stage_receipts"),
        "canary_receipt.pipeline.downstream_stage_receipts",
    )
    expected_paths = {
        "task_meta": (
            f"/home/mini/.hermes/shared-state/tasks/{submission_key}/meta.json"
        ),
        "worker_result": worker_wrapper.get("path"),
        "execution_request": f"{artifact_root}rca_execution_request.json",
        "remote_read": f"{artifact_root}{REMOTE_READ_RECEIPT_RELATIVE_PATH}",
        "capacity_lifecycle": (
            f"{artifact_root}derived_capacity_reservation_receipt.json"
        ),
        "capacity_meter": capacity_meter.get("path"),
        "pipeline": f"{artifact_root}pipeline_result.json",
        "service_result": service_wrapper.get("path"),
        "delivery_manifest": f"{artifact_root}delivery_manifest.json",
        "delivery_contract": f"{artifact_root}delivery_contract.json",
        "goal": f"/home/mini/.hermes/shared-state/tasks/{submission_key}/goal.md",
        "artifact_remote_stream_cache": stream_cache.get("path"),
        "artifact_index_html": f"{artifact_root}index.html",
        "artifact_report_data": f"{artifact_root}report_data.json",
        **{
            f"stage_{name}": _mapping(
                downstream.get(name), f"canary_receipt.pipeline.{name}"
            ).get("artifact_receipt_path")
            for name in REQUIRED_DOWNSTREAM_STAGES
        },
    }
    if any(
        normalized_files[name]["path"] != expected_path
        for name, expected_path in expected_paths.items()
    ):
        raise EvidenceError("canary_receipt_sources_remote_path_mismatch")

    expected_canonical_hashes = {
        "worker_result": worker_wrapper.get("sha256"),
        "execution_request": _sha256_json(request),
        "remote_read": remote_read.get("receipt_sha256"),
        "capacity_lifecycle": vm.get("capacity_lifecycle_sha256"),
        "capacity_meter": capacity_meter.get("sha256"),
        "service_result": service_wrapper.get("sha256"),
        "delivery_manifest": _sha256_json(manifest_body),
        **{
            f"stage_{name}": _sha256_json(
                _mapping(
                    _mapping(
                        downstream.get(name),
                        f"canary_receipt.pipeline.downstream_stage_receipts.{name}",
                    ).get("lineage"),
                    f"canary_receipt.pipeline.downstream_stage_receipts.{name}.lineage",
                )
            )
            for name in REQUIRED_DOWNSTREAM_STAGES
        },
    }
    if any(
        normalized_files[name].get("canonical_sha256") != expected_digest
        for name, expected_digest in expected_canonical_hashes.items()
    ):
        raise EvidenceError("canary_receipt_sources_remote_hash_mismatch")
    if (
        normalized_files["task_meta"]["raw_sha256"]
        != capacity_admission.get("task_meta_sha256")
        or normalized_files["execution_request"]["raw_sha256"]
        != request_storage.get("sha256")
        or normalized_files["execution_request"]["size_bytes"]
        != request_storage.get("bytes")
        or normalized_files["delivery_manifest"]["raw_sha256"]
        != report.get("manifest_sha256")
        or normalized_files["delivery_manifest"]["size_bytes"]
        != manifest_wrapper.get("size_bytes")
        or normalized_files["delivery_manifest"]["raw_sha256"]
        != manifest_wrapper.get("sha256")
        or normalized_files["delivery_contract"]["raw_sha256"]
        != smoke.get("delivery_contract_sha256")
        or normalized_files["goal"]["raw_sha256"] != service_receipt.get("goal_sha256")
        or normalized_files["artifact_remote_stream_cache"]["raw_sha256"]
        != stream_cache.get("sha256")
        or normalized_files["artifact_remote_stream_cache"]["size_bytes"]
        != stream_cache.get("bytes")
    ):
        raise EvidenceError("canary_receipt_sources_remote_hash_mismatch")
    for role, receipt_field in (
        ("index_html", "index_html"),
        ("report_data", "report_data_json"),
    ):
        report_file = _mapping(
            report.get(receipt_field), f"canary_receipt.{receipt_field}"
        )
        source_file = normalized_files[f"artifact_{role}"]
        if source_file["raw_sha256"] != report_file.get("sha256") or source_file[
            "size_bytes"
        ] != report_file.get("size_bytes"):
            raise EvidenceError("canary_receipt_sources_remote_hash_mismatch")
    for name in REQUIRED_DOWNSTREAM_STAGES:
        stage = _mapping(downstream.get(name), f"canary_receipt.pipeline.{name}")
        if normalized_files[f"stage_{name}"]["raw_sha256"] != stage.get(
            "artifact_receipt_sha256"
        ):
            raise EvidenceError("canary_receipt_sources_remote_hash_mismatch")

    local = _mapping(
        body.get("local_machine_sources"),
        "canary_receipt_sources.local_machine_sources",
    )
    if set(local) != {
        "remote_reader_health",
        "browser_smoke",
        "group_binding_authorizations",
    }:
        raise EvidenceError("canary_receipt_sources_local_file_set_invalid")
    normalized_local = {
        name: _canary_source_record(local, name, json_source=True)
        for name in ("remote_reader_health", "browser_smoke")
    }
    health_detail = _read_bound_canary_local_source(
        normalized_local["remote_reader_health"],
        expected_path=settings.evidence_dir / "remote_reader_health.json",
        expected_body=expected_reader_health,
        artifact="remote_reader_health",
    )
    smoke_detail = _read_bound_canary_local_source(
        normalized_local["browser_smoke"],
        expected_path=(
            settings.evidence_dir
            / "machine_sources"
            / submission_key
            / "browser_smoke.json"
        ),
        expected_body=smoke,
        artifact="browser_smoke",
    )
    expected_authorizations: dict[str, Mapping[str, Any]] = {}
    for source in (execution_origin, observed_source):
        if source.get("storage_source_kind") != "feishu_group_manual":
            continue
        source_id = _required_text(source.get("source_id"), "trigger_source.source_id")
        authorization = _mapping(
            source.get("authorization"), "trigger_source.authorization"
        )
        expected_authorizations[source_id] = authorization
    authorization_sources = _mapping(
        local.get("group_binding_authorizations"),
        "canary_receipt_sources.group_binding_authorizations",
    )
    if set(authorization_sources) != set(expected_authorizations):
        raise EvidenceError("canary_authorization_source_set_invalid")
    authorization_details = {
        source_id: _read_bound_group_authorization_source(
            _canary_source_record(
                authorization_sources,
                source_id,
                json_source=True,
            ),
            evidence=expected_authorizations[source_id],
            expected_root=settings.group_binding_receipt_dir,
        )
        for source_id in sorted(expected_authorizations)
    }
    live_database = _check_live_canary_database_binding(
        receipt=receipt,
        control_snapshot_sha256=database_details["control_database"][
            "snapshot_sha256"
        ],
        delivery_snapshot_sha256=database_details["delivery_database"][
            "snapshot_sha256"
        ],
        control_db_path=expected_control_db_path,
        delivery_db_path=expected_delivery_db_path,
        evidence_dir=settings.evidence_dir,
        group_binding_receipt_dir=settings.group_binding_receipt_dir,
        manual_chat_ids=expected_manual_chat_ids,
        expected_workflow_policy=expected_workflow_policy,
        terminal_failure=False,
    )
    return {
        "collected_at": body["collected_at"],
        "receipt_sha256": body["receipt_sha256"],
        "collector_sha256": expected_collector_digest,
        "remote_file_count": len(normalized_files),
        "local_file_count": len(normalized_local) + len(authorization_details),
        "control_snapshot_sha256": database_details["control_database"][
            "snapshot_sha256"
        ],
        "delivery_snapshot_sha256": database_details["delivery_database"][
            "snapshot_sha256"
        ],
        "remote_reader_health_sha256": health_detail["raw_sha256"],
        "browser_smoke_sha256": smoke_detail["raw_sha256"],
        "authorization_sources": authorization_details,
        "live_database": live_database,
        "read_only": True,
        "external_side_effects": False,
    }


def validate_canary_source_provenance(
    body: Mapping[str, Any],
    *,
    receipt: Mapping[str, Any],
    settings: ReleaseGateSettings,
    expected_collector_sha256: str,
    expected_control_db_path: Path,
    expected_delivery_db_path: Path,
    expected_reader_health: Mapping[str, Any],
    expected_workflow_policy: Mapping[str, Any],
    expected_manual_chat_ids: Sequence[str] = (),
) -> dict[str, Any]:
    """Validate source-machine evidence without running collectors or dispatchers."""
    return _check_canary_source_provenance(
        body,
        receipt=receipt,
        settings=settings,
        expected_collector_sha256=expected_collector_sha256,
        expected_control_db_path=expected_control_db_path,
        expected_delivery_db_path=expected_delivery_db_path,
        expected_reader_health=expected_reader_health,
        expected_workflow_policy=expected_workflow_policy,
        expected_manual_chat_ids=expected_manual_chat_ids,
    )


def _signed_exact_int(value: Any, field: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise EvidenceError("invalid_evidence_format", f"{field} must be an integer")
    return value


def _exact_json_float(value: Any, field: str) -> float:
    if not isinstance(value, float) or not math.isfinite(value):
        raise EvidenceError(
            "invalid_evidence_format", f"{field} must be a finite JSON float"
        )
    return value


def _machine_evidence_source(
    value: Any,
    *,
    field: str,
    expected_component: str,
) -> dict[str, str]:
    source = _mapping(value, field)
    if source.get("generation_mode") != "machine_generated":
        raise EvidenceError("capacity_evidence_not_machine_generated")
    component = _required_text(source.get("component"), f"{field}.component")
    if component != expected_component:
        raise EvidenceError("capacity_evidence_source_component_mismatch")
    commit = _required_text(source.get("component_commit"), f"{field}.component_commit")
    if (
        len(commit) != 40
        or commit != commit.lower()
        or any(character not in "0123456789abcdef" for character in commit)
    ):
        raise EvidenceError("capacity_evidence_source_commit_invalid")
    artifact_sha256 = _sha256_digest(
        source.get("artifact_sha256"), f"{field}.artifact_sha256"
    )
    return {
        "generation_mode": "machine_generated",
        "component": component,
        "component_commit": commit,
        "artifact_sha256": artifact_sha256,
    }


def _check_storage_target_formula(
    target: Mapping[str, Any],
    *,
    expected_artifact_cache_bytes: int,
    requested_cases: int,
    assumed_cases_per_day: int,
    reserve_percent: int,
    storage_observed_at: str,
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    prefix = "storage_admission.target"
    name = _required_text(target.get("name"), f"{prefix}.name")
    expected_name, path, multiplier_numerator, multiplier_denominator = (
        FIXED_STORAGE_TARGET
    )
    if name != expected_name or target.get("path") != path:
        raise EvidenceError("capacity_storage_target_path_mismatch")
    if target.get("capacity_scope") != FIXED_CAPACITY_SCOPE:
        raise EvidenceError("capacity_scope_mismatch")
    target_observed_at = _require_fresh(
        target,
        now=now,
        max_age_seconds=max_age_seconds,
        artifact="storage_target_task_output",
    )
    if target_observed_at != storage_observed_at:
        raise EvidenceError("capacity_storage_target_observation_mismatch")
    if target.get("ok") is not True or target.get("blocker") is not None:
        raise EvidenceError("capacity_storage_target_blocked")

    multiplier = _exact_json_float(target.get("multiplier"), f"{prefix}.multiplier")
    expected_multiplier = multiplier_numerator / multiplier_denominator
    if multiplier != expected_multiplier:
        raise EvidenceError("capacity_storage_target_formula_mismatch")
    bytes_per_case = _exact_int(
        target.get("bytes_per_case"), f"{prefix}.bytes_per_case", minimum=1
    )
    expected_bytes_per_case = (
        expected_artifact_cache_bytes * multiplier_numerator
        + multiplier_denominator
        - 1
    ) // multiplier_denominator
    required_bytes = _exact_int(
        target.get("required_bytes"), f"{prefix}.required_bytes", minimum=1
    )
    expected_required_bytes = expected_bytes_per_case * requested_cases

    block_size = _exact_int(
        target.get("filesystem_block_size_bytes"),
        f"{prefix}.filesystem_block_size_bytes",
        minimum=1,
    )
    total_bytes = _exact_int(
        target.get("total_bytes"), f"{prefix}.total_bytes", minimum=1
    )
    free_bytes = _exact_int(target.get("free_bytes"), f"{prefix}.free_bytes", minimum=0)
    available_bytes = _exact_int(
        target.get("available_bytes"), f"{prefix}.available_bytes", minimum=0
    )
    reserve_bytes = _exact_int(
        target.get("reserve_bytes"), f"{prefix}.reserve_bytes", minimum=0
    )
    admittable_bytes = _exact_int(
        target.get("admittable_bytes"), f"{prefix}.admittable_bytes", minimum=0
    )
    projected_available = _signed_exact_int(
        target.get("projected_available_after_request_bytes"),
        f"{prefix}.projected_available_after_request_bytes",
    )
    headroom = _signed_exact_int(
        target.get("headroom_after_request_bytes"),
        f"{prefix}.headroom_after_request_bytes",
    )
    max_additional_cases = _exact_int(
        target.get("max_additional_cases"),
        f"{prefix}.max_additional_cases",
        minimum=0,
    )
    horizon = _number(
        target.get("days_horizon_at_assumed_cases_per_day"),
        f"{prefix}.days_horizon_at_assumed_cases_per_day",
        minimum=0.0,
    )

    expected_reserve_bytes = (total_bytes * reserve_percent + 99) // 100
    expected_admittable_bytes = max(0, available_bytes - expected_reserve_bytes)
    expected_max_cases = expected_admittable_bytes // expected_bytes_per_case
    daily_bytes = expected_bytes_per_case * assumed_cases_per_day
    expected_horizon = (
        (expected_admittable_bytes * 1_000 // daily_bytes) / 1_000.0
        if expected_admittable_bytes
        else 0.0
    )
    filesystem_values = (total_bytes, free_bytes, available_bytes)
    formula_matches = (
        bytes_per_case == expected_bytes_per_case
        and required_bytes == expected_required_bytes
        and total_bytes >= free_bytes >= available_bytes
        and all(value % block_size == 0 for value in filesystem_values)
        and reserve_bytes == expected_reserve_bytes
        and admittable_bytes == expected_admittable_bytes
        and projected_available == available_bytes - expected_required_bytes
        and headroom == expected_admittable_bytes - expected_required_bytes
        and max_additional_cases == expected_max_cases
        and horizon == expected_horizon
        and expected_required_bytes <= expected_admittable_bytes
    )
    if not formula_matches:
        raise EvidenceError("capacity_storage_target_formula_mismatch")
    return {
        "name": name,
        "required_bytes": required_bytes,
        "max_additional_cases": max_additional_cases,
        "days_horizon_at_assumed_cases_per_day": horizon,
    }


def _check_queue_limit_provenance(
    body: Mapping[str, Any],
    *,
    limits: Mapping[str, Any],
    parsed_limits: Mapping[str, int],
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    source = _mapping(limits.get("source"), "queue_limits.source")
    if source.get("schema_version") != QUEUE_LIMITS_SOURCE_SCHEMA_VERSION:
        raise EvidenceError("capacity_queue_source_schema_mismatch")
    if source.get("source_kind") != QUEUE_LIMITS_SOURCE_KIND:
        raise EvidenceError("capacity_queue_source_kind_mismatch")

    scheduler = _mapping(body.get("scheduler_evidence"), "scheduler_evidence")
    _require_schema(scheduler, SCHEDULER_CAPACITY_SCHEMA_VERSION, "scheduler_evidence")
    scheduler_observed_at = _require_fresh(
        scheduler,
        now=now,
        max_age_seconds=max_age_seconds,
        artifact="scheduler_evidence",
    )
    scheduler_source = _machine_evidence_source(
        scheduler.get("source"),
        field="scheduler_evidence.source",
        expected_component="ssh-mini-submit",
    )
    if scheduler.get("service_id") != FIXED_SERVICE_ID:
        raise EvidenceError("capacity_scheduler_identity_mismatch")
    scheduler_epoch = _required_text(
        scheduler.get("scheduler_epoch"), "scheduler_evidence.scheduler_epoch"
    )
    if scheduler.get("capacity_enforcement") != "atomic_pre_submit":
        raise EvidenceError("capacity_scheduler_admission_not_enforced")
    _sha256_digest(
        scheduler.get("configuration_sha256"),
        "scheduler_evidence.configuration_sha256",
    )
    scheduler_limits = _mapping(
        scheduler.get("queue_limits"), "scheduler_evidence.queue_limits"
    )
    parsed_scheduler_limits = {
        key: _exact_int(
            scheduler_limits.get(key),
            f"scheduler_evidence.queue_limits.{key}",
            minimum=1,
        )
        for key in ("max_inflight", "max_queued", "max_batch_size")
    }
    if parsed_scheduler_limits != dict(parsed_limits):
        raise EvidenceError("capacity_scheduler_queue_limits_mismatch")
    scheduler_sha256 = _sha256_json(scheduler)
    if (
        _sha256_digest(
            source.get("scheduler_evidence_sha256"),
            "queue_limits.source.scheduler_evidence_sha256",
        )
        != scheduler_sha256
    ):
        raise EvidenceError("capacity_scheduler_evidence_hash_mismatch")

    if "reservation_evidence" in body:
        raise EvidenceError("capacity_legacy_reservation_evidence_present")
    if set(source) != {
        "schema_version",
        "source_kind",
        "scheduler_evidence_sha256",
    }:
        raise EvidenceError("capacity_queue_source_shape_invalid")
    return {
        "scheduler_observed_at": scheduler_observed_at,
        "scheduler_source": scheduler_source,
        "scheduler_epoch": scheduler_epoch,
        "reservation_mode": "forbidden",
    }


def _check_capacity_receipt(
    body: Mapping[str, Any],
    *,
    dispatcher: DispatcherConfig,
    now: datetime,
    max_age_seconds: int,
    target_cases_per_day: int,
    min_capacity_horizon_days: float,
) -> dict[str, Any]:
    artifact = "capacity_receipt"
    _require_schema(body, CAPACITY_RECEIPT_SCHEMA_VERSION, artifact)
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("ok") is not True:
        raise EvidenceError("capacity_receipt_not_ok")
    limits = _mapping(body.get("queue_limits"), "queue_limits")
    parsed_limits = {
        key: _exact_int(limits.get(key), f"queue_limits.{key}", minimum=1)
        for key in ("max_inflight", "max_queued", "max_batch_size")
    }
    if parsed_limits["max_inflight"] > parsed_limits["max_queued"]:
        raise EvidenceError("capacity_queue_limits_inconsistent")
    if dispatcher.batch_size > parsed_limits["max_batch_size"]:
        raise EvidenceError("capacity_dispatcher_batch_exceeds_limit")
    if parsed_limits["max_inflight"] != dispatcher.storage_concurrency_reserve_cases:
        raise EvidenceError("capacity_inflight_reserve_mismatch")

    storage = _mapping(body.get("storage_admission"), "storage_admission")
    if storage.get("schema_version") != "g1q3_rca_storage_admission_v2":
        raise EvidenceError("capacity_storage_admission_schema_mismatch")
    storage_observed_at = _require_fresh(
        storage,
        now=now,
        max_age_seconds=max_age_seconds,
        artifact="storage_admission",
    )
    if storage.get("ok") is not True or storage.get("status") != "pass":
        raise EvidenceError("capacity_storage_admission_failed")
    if storage.get("blockers") != []:
        raise EvidenceError("capacity_storage_admission_blocked")
    if storage.get("side_effects") != "none_read_only_statvfs":
        raise EvidenceError("capacity_storage_admission_not_read_only")
    if storage.get("capacity_scope") != FIXED_CAPACITY_SCOPE:
        raise EvidenceError("capacity_scope_mismatch")

    policy = _mapping(storage.get("policy"), "storage_admission.policy")
    requested_cases = _exact_int(
        policy.get("requested_cases"),
        "storage_admission.policy.requested_cases",
        minimum=1,
    )
    if requested_cases != dispatcher.storage_concurrency_reserve_cases:
        raise EvidenceError("capacity_requested_cases_config_mismatch")
    if (
        _exact_int(
            policy.get("concurrency_reserve_cases"),
            "storage_admission.policy.concurrency_reserve_cases",
            minimum=1,
        )
        != dispatcher.storage_concurrency_reserve_cases
    ):
        raise EvidenceError("capacity_concurrency_reserve_config_mismatch")
    if policy.get("requested_cases_scope") != (
        "this_admission_capacity_reservation_only"
    ):
        raise EvidenceError("capacity_requested_cases_scope_mismatch")
    assumed_cases_per_day = _exact_int(
        policy.get("assumed_cases_per_day"),
        "storage_admission.policy.assumed_cases_per_day",
        minimum=1,
    )
    if assumed_cases_per_day < target_cases_per_day:
        raise EvidenceError("capacity_assumed_cases_per_day_below_target")
    if assumed_cases_per_day != dispatcher.storage_cases_per_day:
        raise EvidenceError("capacity_assumed_cases_per_day_config_mismatch")
    if policy.get("assumed_cases_per_day_scope") != ("days_horizon_calculation_only"):
        raise EvidenceError("capacity_assumed_cases_per_day_scope_mismatch")
    if (
        _exact_int(
            policy.get("input_materialization_bytes_per_case"),
            "storage_admission.policy.input_materialization_bytes_per_case",
            minimum=0,
        )
        != 0
    ):
        raise EvidenceError("capacity_input_materialization_not_zero")
    if policy.get("input_materialization") != "forbidden":
        raise EvidenceError("capacity_input_materialization_not_forbidden")
    expected_artifact_cache_bytes = _exact_int(
        policy.get("expected_derived_artifact_bytes_per_case"),
        "storage_admission.policy.expected_derived_artifact_bytes_per_case",
        minimum=1,
    )
    if (
        expected_artifact_cache_bytes
        != dispatcher.storage_expected_artifact_cache_bytes
    ):
        raise EvidenceError("capacity_artifact_cache_size_config_mismatch")
    if policy.get("input_unit") != "bytes":
        raise EvidenceError("capacity_input_unit_mismatch")
    if (
        _exact_int(
            policy.get("gb_definition_bytes"),
            "storage_admission.policy.gb_definition_bytes",
            minimum=1,
        )
        != 1_000_000_000
    ):
        raise EvidenceError("capacity_gb_definition_mismatch")
    reserve_ratio = _exact_json_float(
        policy.get("reserve_ratio"), "storage_admission.policy.reserve_ratio"
    )
    reserve_percent = _exact_json_float(
        policy.get("reserve_percent"), "storage_admission.policy.reserve_percent"
    )
    if (
        reserve_percent != float(dispatcher.storage_reserve_percent)
        or reserve_ratio != dispatcher.storage_reserve_percent / 100.0
    ):
        raise EvidenceError("capacity_reserve_percent_config_mismatch")
    if (
        _exact_json_float(
            policy.get("task_output_multiplier"),
            "storage_admission.policy.task_output_multiplier",
        )
        != 3.25
    ):
        raise EvidenceError("capacity_storage_multiplier_mismatch")
    logical_multipliers = _mapping(
        policy.get("logical_budget_multipliers"),
        "storage_admission.policy.logical_budget_multipliers",
    )
    expected_multipliers = {
        "derived_cache": 1.0,
        "derived_artifacts_and_publisher": 2.25,
        "total": 3.25,
    }
    if set(logical_multipliers) != set(expected_multipliers) or any(
        _exact_json_float(
            logical_multipliers.get(field),
            f"storage_admission.policy.logical_budget_multipliers.{field}",
        )
        != expected
        for field, expected in expected_multipliers.items()
    ):
        raise EvidenceError("capacity_storage_multiplier_mismatch")
    logical_bytes = _mapping(
        policy.get("logical_budget_bytes_per_case"),
        "storage_admission.policy.logical_budget_bytes_per_case",
    )
    expected_artifacts_and_publisher = (expected_artifact_cache_bytes * 9 + 3) // 4
    expected_bytes_per_case = (
        expected_artifact_cache_bytes + expected_artifacts_and_publisher
    )
    expected_logical_bytes = {
        "derived_cache": expected_artifact_cache_bytes,
        "derived_artifacts_and_publisher": expected_artifacts_and_publisher,
        "total": expected_bytes_per_case,
    }
    if set(logical_bytes) != set(expected_logical_bytes) or any(
        _exact_int(
            logical_bytes.get(field),
            f"storage_admission.policy.logical_budget_bytes_per_case.{field}",
            minimum=1,
        )
        != expected
        for field, expected in expected_logical_bytes.items()
    ):
        raise EvidenceError("capacity_storage_logical_budget_mismatch")

    target = _mapping(storage.get("target"), "storage_admission.target")
    target_summary = _check_storage_target_formula(
        target,
        expected_artifact_cache_bytes=expected_artifact_cache_bytes,
        requested_cases=requested_cases,
        assumed_cases_per_day=assumed_cases_per_day,
        reserve_percent=dispatcher.storage_reserve_percent,
        storage_observed_at=storage_observed_at,
        now=now,
        max_age_seconds=max_age_seconds,
    )

    required_bytes_total = _exact_int(
        storage.get("required_bytes_total"),
        "storage_admission.required_bytes_total",
        minimum=1,
    )
    expected_required_bytes_total = requested_cases * expected_bytes_per_case
    if required_bytes_total != expected_required_bytes_total or (
        required_bytes_total != int(target_summary["required_bytes"])
    ):
        raise EvidenceError("capacity_required_bytes_total_formula_mismatch")
    max_additional_cases = _exact_int(
        storage.get("max_additional_cases"),
        "storage_admission.max_additional_cases",
        minimum=0,
    )
    if max_additional_cases != int(target_summary["max_additional_cases"]):
        raise EvidenceError("capacity_max_additional_cases_inconsistent")
    if max_additional_cases < parsed_limits["max_inflight"]:
        raise EvidenceError("capacity_max_additional_cases_below_inflight")
    capacity_horizon = _number(
        storage.get("days_horizon_at_assumed_cases_per_day"),
        "storage_admission.days_horizon_at_assumed_cases_per_day",
        minimum=0.0,
    )
    if capacity_horizon != float(
        target_summary["days_horizon_at_assumed_cases_per_day"]
    ):
        raise EvidenceError("capacity_horizon_inconsistent")
    if capacity_horizon < min_capacity_horizon_days:
        raise EvidenceError("capacity_horizon_insufficient")

    try:
        validate_storage_admission(
            storage,
            StorageAdmissionRequest(
                requested_cases=dispatcher.storage_concurrency_reserve_cases,
                assumed_cases_per_day=dispatcher.storage_cases_per_day,
                expected_artifact_cache_bytes=(
                    dispatcher.storage_expected_artifact_cache_bytes
                ),
                reserve_percent=dispatcher.storage_reserve_percent,
                timeout_seconds=dispatcher.storage_timeout_seconds,
            ),
        )
    except ValueError as exc:
        raise EvidenceError("capacity_storage_admission_invalid", str(exc)) from exc

    provenance = _check_queue_limit_provenance(
        body,
        limits=limits,
        parsed_limits=parsed_limits,
        now=now,
        max_age_seconds=max_age_seconds,
    )
    return {
        "observed_at": observed_at,
        "storage_observed_at": storage_observed_at,
        "storage_admission": "pass",
        "capacity_scope": FIXED_CAPACITY_SCOPE,
        "input_materialization_bytes_per_case": 0,
        "expected_derived_artifact_bytes_per_case": expected_artifact_cache_bytes,
        "assumed_cases_per_day": assumed_cases_per_day,
        "target_cases_per_day": target_cases_per_day,
        "required_bytes_total": required_bytes_total,
        "max_additional_cases": max_additional_cases,
        "capacity_horizon_days": capacity_horizon,
        "minimum_capacity_horizon_days": min_capacity_horizon_days,
        "queue_limits": parsed_limits,
        "queue_limit_provenance": provenance,
    }


def _commit_sha(value: Any, field: str) -> str:
    commit = _required_text(value, field)
    if (
        len(commit) != 40
        or commit != commit.lower()
        or any(character not in "0123456789abcdef" for character in commit)
    ):
        raise EvidenceError("build_manifest_commit_invalid")
    return commit


def _git_object_id(value: Any, field: str) -> str:
    object_id = _required_text(value, field)
    if (
        len(object_id) not in {40, 64}
        or object_id != object_id.lower()
        or any(character not in "0123456789abcdef" for character in object_id)
    ):
        raise EvidenceError("build_manifest_git_object_invalid", field)
    return object_id


def _git_output(repo_root: Path, arguments: Sequence[str]) -> str:
    try:
        return _git_output_bytes(repo_root, arguments).decode("utf-8").strip()
    except UnicodeError as exc:
        raise EvidenceError("build_manifest_git_verification_failed") from exc


def _git_output_bytes(repo_root: Path, arguments: Sequence[str]) -> bytes:
    try:
        result = subprocess.run(
            ["git", "-C", str(repo_root), *arguments],
            check=False,
            capture_output=True,
            timeout=5,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise EvidenceError("build_manifest_git_unavailable") from exc
    if result.returncode != 0:
        raise EvidenceError("build_manifest_git_verification_failed")
    return bytes(result.stdout)


def _stable_regular_file_observation(
    path: Path,
    *,
    artifact: str,
    expected_mode: int | None = None,
    require_owner: bool = False,
    allow_empty: bool = False,
    max_bytes: int = MAX_EVIDENCE_BYTES,
) -> tuple[bytes, os.stat_result]:
    absolute = path.expanduser().absolute()
    nofollow = getattr(os, "O_NOFOLLOW", None)
    if nofollow is None:
        raise EvidenceError(f"{artifact}_invalid")
    descriptor = -1
    try:
        initial = os.lstat(absolute)
        if (
            stat.S_ISLNK(initial.st_mode)
            or not stat.S_ISREG(initial.st_mode)
            or initial.st_nlink != 1
            or (require_owner and initial.st_uid != os.getuid())
            or (
                expected_mode is not None
                and stat.S_IMODE(initial.st_mode) != expected_mode
            )
            or initial.st_size < 0
            or (not allow_empty and initial.st_size == 0)
            or initial.st_size > max_bytes
            or absolute.resolve(strict=True) != absolute
        ):
            raise EvidenceError(f"{artifact}_invalid")
        descriptor = os.open(
            absolute,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | nofollow,
        )
        opened = os.fstat(descriptor)
        stable_fields = (
            "st_dev",
            "st_ino",
            "st_mode",
            "st_nlink",
            "st_uid",
            "st_size",
            "st_mtime_ns",
            "st_ctime_ns",
        )
        if any(
            getattr(initial, field) != getattr(opened, field)
            for field in stable_fields
        ):
            raise EvidenceError(f"{artifact}_unstable")
        remaining = opened.st_size
        chunks: list[bytes] = []
        while remaining:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise EvidenceError(f"{artifact}_unstable")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise EvidenceError(f"{artifact}_unstable")
        final_opened = os.fstat(descriptor)
        final_path = os.lstat(absolute)
        if any(
            getattr(initial, field) != getattr(final_opened, field)
            or getattr(initial, field) != getattr(final_path, field)
            for field in stable_fields
        ):
            raise EvidenceError(f"{artifact}_unstable")
        raw = b"".join(chunks)
        if len(raw) != initial.st_size:
            raise EvidenceError(f"{artifact}_unstable")
        return raw, initial
    except EvidenceError:
        raise
    except OSError as exc:
        raise EvidenceError(f"{artifact}_invalid") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)


def _workspace_execution_file_observation(
    root: Path,
    *,
    commit: str,
    relative: str,
) -> dict[str, Any]:
    artifact = "build_manifest_workspace_closure_file"
    stage = _git_output(root, ["ls-files", "--stage", "--", relative])
    match = re.fullmatch(
        r"(100644|100755) ([0-9a-f]{40,64}) 0\t(.+)",
        stage,
    )
    if match is None or match.group(3) != relative:
        raise EvidenceError(f"{artifact}_untracked")
    path = (root / relative).absolute()
    raw, _info = _stable_regular_file_observation(path, artifact=artifact)
    try:
        committed_raw = _git_output_bytes(root, ["cat-file", "blob", f"{commit}:{relative}"])
    except EvidenceError as exc:
        raise EvidenceError(f"{artifact}_cross_commit") from exc
    if raw != committed_raw:
        raise EvidenceError("build_manifest_workspace_closure_dirty")
    return {
        "relative_path": relative,
        "path": str(path),
        "commit": commit,
        "git_mode": match.group(1),
        "tracked": True,
        "regular_file": True,
        "symlink": False,
        "sha256": hashlib.sha256(raw).hexdigest(),
    }


def _workspace_git_provenance(repo_root: Path) -> dict[str, Any]:
    component = "workspace"
    root = repo_root.expanduser().resolve()
    if not root.is_dir():
        raise EvidenceError("build_manifest_workspace_repo_missing")
    try:
        git_root = Path(_git_output(root, ["rev-parse", "--show-toplevel"])).resolve()
        commit = _commit_sha(
            _git_output(root, ["rev-parse", "--verify", "HEAD"]),
            "build_provenance.workspace.commit",
        )
        scoped_status = _git_output_bytes(
            root,
            [
                "status",
                "--porcelain=v1",
                "-z",
                "--untracked-files=all",
                "--",
                *WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS,
            ],
        )
        if scoped_status:
            raise EvidenceError("build_manifest_workspace_closure_dirty")
        files = {
            relative: _workspace_execution_file_observation(
                root,
                commit=commit,
                relative=relative,
            )
            for relative in WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS
        }
        unscoped_status = _git_output_bytes(
            root,
            [
                "status",
                "--porcelain=v1",
                "--untracked-files=all",
                "--",
                ".",
                *(
                    f":(exclude){relative}"
                    for relative in WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS
                ),
            ],
        )
        scoped_status_after = _git_output_bytes(
            root,
            [
                "status",
                "--porcelain=v1",
                "-z",
                "--untracked-files=all",
                "--",
                *WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS,
            ],
        )
        files_after = {
            relative: _workspace_execution_file_observation(
                root,
                commit=commit,
                relative=relative,
            )
            for relative in WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS
        }
        commit_after = _commit_sha(
            _git_output(root, ["rev-parse", "--verify", "HEAD"]),
            "build_provenance.workspace.commit_after_status",
        )
    except EvidenceError as exc:
        if exc.code.startswith("build_manifest_workspace_"):
            raise
        raise EvidenceError("build_manifest_workspace_git_unavailable") from exc
    if git_root != root:
        raise EvidenceError("build_manifest_workspace_repo_root_mismatch")
    if commit_after != commit or files_after != files:
        raise EvidenceError("build_manifest_workspace_repo_unstable")
    if scoped_status_after:
        raise EvidenceError("build_manifest_workspace_closure_dirty")
    closure = {
        "schema_version": WORKSPACE_EXECUTION_CLOSURE_SCHEMA_VERSION,
        "commit": commit,
        "relative_paths": list(WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS),
        "files": files,
        "scoped_clean": True,
        "scoped_status_sha256": EMPTY_GIT_STATUS_SHA256,
    }
    unscoped_count = len(unscoped_status.splitlines())
    return {
        "source": "local_git_scoped_closure",
        "repo_root": str(root),
        "commit": commit,
        "stable": True,
        "execution_closure": closure,
        "execution_closure_sha256": _sha256_json(closure),
        "unscoped_drift": {
            "classification": "DRIFT-PREEXISTING",
            "dirty_count": unscoped_count,
            "status_sha256": hashlib.sha256(unscoped_status).hexdigest(),
            "blocking": False,
        },
    }


def _external_dependency_observation(
    name: str,
    contract: Mapping[str, Any],
) -> dict[str, Any]:
    path_value = contract.get("path")
    expected_mode = contract.get("mode")
    if (
        not isinstance(path_value, Path)
        or not path_value.is_absolute()
        or isinstance(expected_mode, bool)
        or not isinstance(expected_mode, int)
    ):
        raise EvidenceError(f"build_manifest_external_{name}_contract_invalid")
    artifact = f"build_manifest_external_{name}"
    raw, info = _stable_regular_file_observation(
        path_value,
        artifact=artifact,
        expected_mode=expected_mode,
        require_owner=True,
    )
    return {
        "schema_version": EXTERNAL_DEPENDENCY_PROVENANCE_SCHEMA_VERSION,
        "source": "local_lstat",
        "path": str(path_value),
        "realpath": str(path_value.resolve(strict=True)),
        "owner_uid": info.st_uid,
        "mode": stat.S_IMODE(info.st_mode),
        "regular_file": True,
        "symlink": False,
        "link_count": info.st_nlink,
        "sha256": hashlib.sha256(raw).hexdigest(),
        "stable": True,
    }


def _external_release_dependency_provenance() -> dict[str, dict[str, Any]]:
    return {
        name: _external_dependency_observation(name, contract)
        for name, contract in sorted(EXTERNAL_RELEASE_DEPENDENCIES.items())
    }


def _release_prepare_file_sha256(value: Mapping[str, Any]) -> str:
    return hashlib.sha256((_canonical_json(value) + "\n").encode("utf-8")).hexdigest()


def _observe_release_approval_machine_identity(
    *,
    runner: Any = subprocess.run,
) -> dict[str, str]:
    for source, candidate in (
        ("etc_machine_id", Path("/etc/machine-id")),
        ("dbus_machine_id", Path("/var/lib/dbus/machine-id")),
    ):
        try:
            info = os.lstat(candidate)
            if stat.S_ISLNK(info.st_mode) or not stat.S_ISREG(info.st_mode):
                continue
            value = candidate.read_text(encoding="ascii").strip()
        except (OSError, UnicodeError):
            continue
        if re.fullmatch(r"[A-Za-z0-9-]{16,128}", value):
            return {
                "source": source,
                "sha256": hashlib.sha256(
                    f"{source}\0{value}".encode("utf-8")
                ).hexdigest(),
            }
    if platform.system() == "Darwin":
        try:
            completed = runner(
                ["/usr/sbin/ioreg", "-rd1", "-c", "IOPlatformExpertDevice"],
                check=False,
                capture_output=True,
                text=True,
                timeout=3,
            )
        except (OSError, subprocess.SubprocessError):
            completed = None
        if completed is not None and completed.returncode == 0:
            match = re.search(
                r'"IOPlatformUUID"\s*=\s*"([A-Fa-f0-9-]{16,64})"',
                str(completed.stdout or ""),
            )
            if match:
                source = "darwin_ioplatformuuid"
                return {
                    "source": source,
                    "sha256": hashlib.sha256(
                        f"{source}\0{match.group(1).lower()}".encode("utf-8")
                    ).hexdigest(),
                }
    raise EvidenceError("release_approval_machine_identity_unavailable")


def _release_approval_timestamp(value: Any, field: str) -> datetime:
    try:
        return _timestamp(value, field)
    except EvidenceError as exc:
        raise EvidenceError("release_approval_timestamp_invalid", field) from exc


def _release_approval_identity_requirement(
    value: Any,
    *,
    machine_identity: Mapping[str, Any],
) -> dict[str, Any]:
    identity = _mapping(value, "release_approval.identity")
    if set(identity) != {
        "schema_version",
        "method",
        "uid",
        "username",
        "machine_identity_source",
        "machine_identity_sha256",
    }:
        raise EvidenceError("release_approval_identity_shape_invalid")
    source = _required_text(
        machine_identity.get("source"),
        "release_approval.machine_identity.source",
    )
    machine_sha256 = _sha256_digest(
        machine_identity.get("sha256"),
        "release_approval.machine_identity.sha256",
    )
    if re.fullmatch(r"[a-z][a-z0-9_]{2,63}", source) is None:
        raise EvidenceError("release_approval_machine_identity_invalid")
    try:
        username = pwd.getpwuid(os.geteuid()).pw_name
    except KeyError as exc:
        raise EvidenceError("release_approval_local_identity_unavailable") from exc
    expected = {
        "schema_version": RELEASE_APPROVAL_IDENTITY_SCHEMA_VERSION,
        "method": RELEASE_APPROVAL_IDENTITY_METHOD,
        "uid": os.geteuid(),
        "username": username,
        "machine_identity_source": source,
        "machine_identity_sha256": machine_sha256,
    }
    if dict(identity) != expected:
        raise EvidenceError("release_approval_identity_mismatch")
    return expected


def _normalize_runtime_path_identity(
    value: Any,
    *,
    field: str,
    expected_path: Path,
    expected_mode: int,
    include_sha256: bool = False,
) -> dict[str, Any]:
    identity = _mapping(value, field)
    expected_fields = {"path", "device", "inode", "owner_uid", "mode"}
    if include_sha256:
        expected_fields.add("sha256")
    if set(identity) != expected_fields:
        raise EvidenceError("future_runtime_stage_identity_shape_invalid", field)
    path = _required_text(identity.get("path"), f"{field}.path")
    if path != str(expected_path) or not expected_path.is_absolute():
        raise EvidenceError("future_runtime_stage_identity_path_invalid", field)
    normalized = {
        "path": path,
        "device": _exact_int(identity.get("device"), f"{field}.device", minimum=0),
        "inode": _exact_int(identity.get("inode"), f"{field}.inode", minimum=1),
        "owner_uid": _exact_int(
            identity.get("owner_uid"), f"{field}.owner_uid", minimum=0
        ),
        "mode": _exact_int(identity.get("mode"), f"{field}.mode", minimum=0),
    }
    if normalized["owner_uid"] != os.geteuid() or normalized["mode"] != expected_mode:
        raise EvidenceError("future_runtime_stage_identity_owner_invalid", field)
    if include_sha256:
        normalized["sha256"] = _sha256_digest(
            identity.get("sha256"), f"{field}.sha256"
        )
    return normalized


def _normalize_workspace_runtime_identity(
    value: Any,
    *,
    field: str,
    canonical: bool,
) -> dict[str, Any]:
    identity = _mapping(value, field)
    if set(identity) != {
        "schema_version",
        "root",
        "manifest_path",
        "creator_path",
        "manifest_sha256",
        "closure_sha256",
        "source_commit",
        "file_sha256",
    } or identity.get("schema_version") != (
        workspace_runtime.WORKSPACE_RUNTIME_IDENTITY_SCHEMA_VERSION
    ):
        raise EvidenceError("workspace_runtime_identity_shape_invalid", field)
    root = Path(_required_text(identity.get("root"), f"{field}.root"))
    if not root.is_absolute():
        raise EvidenceError("workspace_runtime_identity_path_invalid", field)
    if canonical and root != CANONICAL_WORKSPACE_RUNTIME_ROOT:
        raise EvidenceError("workspace_runtime_canonical_root_invalid")
    if not canonical and root == CANONICAL_WORKSPACE_RUNTIME_ROOT:
        raise EvidenceError("workspace_runtime_staging_root_is_live")
    expected_manifest = root / workspace_runtime.WORKSPACE_RUNTIME_MANIFEST_NAME
    expected_creator = root / "bin" / "create_task_v2.py"
    if (
        identity.get("manifest_path") != str(expected_manifest)
        or identity.get("creator_path") != str(expected_creator)
    ):
        raise EvidenceError("workspace_runtime_identity_path_invalid", field)
    files = _mapping(identity.get("file_sha256"), f"{field}.file_sha256")
    if set(files) != set(workspace_runtime.WORKSPACE_RUNTIME_FILES):
        raise EvidenceError("workspace_runtime_identity_file_set_invalid")
    return {
        "schema_version": workspace_runtime.WORKSPACE_RUNTIME_IDENTITY_SCHEMA_VERSION,
        "root": str(root),
        "manifest_path": str(expected_manifest),
        "creator_path": str(expected_creator),
        "manifest_sha256": _sha256_digest(
            identity.get("manifest_sha256"), f"{field}.manifest_sha256"
        ),
        "closure_sha256": _sha256_digest(
            identity.get("closure_sha256"), f"{field}.closure_sha256"
        ),
        "source_commit": _commit_sha(
            identity.get("source_commit"), f"{field}.source_commit"
        ),
        "file_sha256": {
            relative: _sha256_digest(files.get(relative), f"{field}.{relative}")
            for relative in workspace_runtime.WORKSPACE_RUNTIME_FILES
        },
    }


def _normalize_workspace_runtime_release_binding(
    value: Any,
    *,
    workspace_component: Mapping[str, Any],
    field: str,
) -> dict[str, Any]:
    binding = _mapping(value, field)
    if set(binding) != {
        "schema_version",
        "staged_identity",
        "staged_identity_sha256",
        "canonical_identity",
        "canonical_identity_sha256",
    } or binding.get("schema_version") != (
        WORKSPACE_RUNTIME_RELEASE_BINDING_SCHEMA_VERSION
    ):
        raise EvidenceError("workspace_runtime_release_binding_shape_invalid")
    staged = _normalize_workspace_runtime_identity(
        binding.get("staged_identity"), field=f"{field}.staged_identity", canonical=False
    )
    canonical = _normalize_workspace_runtime_identity(
        binding.get("canonical_identity"),
        field=f"{field}.canonical_identity",
        canonical=True,
    )
    staged_sha256 = _sha256_digest(
        binding.get("staged_identity_sha256"), f"{field}.staged_identity_sha256"
    )
    canonical_sha256 = _sha256_digest(
        binding.get("canonical_identity_sha256"),
        f"{field}.canonical_identity_sha256",
    )
    if (
        staged_sha256 != _sha256_json(staged)
        or canonical_sha256 != _sha256_json(canonical)
    ):
        raise EvidenceError("workspace_runtime_release_binding_hash_mismatch")
    invariant_fields = {
        "schema_version",
        "manifest_sha256",
        "closure_sha256",
        "source_commit",
        "file_sha256",
    }
    if any(staged[name] != canonical[name] for name in invariant_fields):
        raise EvidenceError("workspace_runtime_canonical_projection_mismatch")
    workspace_commit = _commit_sha(
        workspace_component.get("commit"), f"{field}.workspace_commit"
    )
    closure = _mapping(
        workspace_component.get("execution_closure"), f"{field}.workspace_closure"
    )
    closure_files = _mapping(closure.get("files"), f"{field}.workspace_files")
    expected_files = {
        relative: _sha256_digest(
            _mapping(closure_files.get(relative), f"{field}.{relative}").get("sha256"),
            f"{field}.{relative}.sha256",
        )
        for relative in workspace_runtime.WORKSPACE_RUNTIME_FILES
    }
    if staged["source_commit"] != workspace_commit or staged["file_sha256"] != expected_files:
        raise EvidenceError("workspace_runtime_workspace_closure_mismatch")
    return {
        "schema_version": WORKSPACE_RUNTIME_RELEASE_BINDING_SCHEMA_VERSION,
        "staged_identity": staged,
        "staged_identity_sha256": staged_sha256,
        "canonical_identity": canonical,
        "canonical_identity_sha256": canonical_sha256,
    }


def _normalize_future_runtime_release_binding(
    value: Any,
    *,
    host_component: Mapping[str, Any],
    expected_launchd_config_sha256: str,
    field: str,
) -> dict[str, Any]:
    binding = _mapping(value, field)
    if set(binding) != {
        "schema_version",
        "runtime_stage_manifest_identity",
        "runtime_stage_manifest_identity_sha256",
        "runtime_stage_identity",
        "runtime_stage_identity_sha256",
        "future_runtime_projection",
        "future_runtime_projection_sha256",
        "render_manifest",
        "render_manifest_sha256",
    } or binding.get("schema_version") != FUTURE_RUNTIME_RELEASE_BINDING_SCHEMA_VERSION:
        raise EvidenceError("future_runtime_release_binding_shape_invalid")

    manifest_identity = _mapping(
        binding.get("runtime_stage_manifest_identity"),
        f"{field}.runtime_stage_manifest_identity",
    )
    if set(manifest_identity) != {
        "schema_version",
        "staging_root",
        "manifest_path",
        "manifest_sha256",
        "plan_sha256",
        "content_sha256",
        "source_commit",
        "source_tree",
        "canonical_live_root",
        "candidate_plist_sha256",
        "runtime_file_descriptors",
        "runtime_files_sha256",
    } or manifest_identity.get("schema_version") != runtime_stage.MANIFEST_SCHEMA_VERSION:
        raise EvidenceError("future_runtime_stage_manifest_identity_invalid")
    stage_root = Path(
        _required_text(manifest_identity.get("staging_root"), f"{field}.staging_root")
    )
    if not stage_root.is_absolute() or stage_root == CANONICAL_FUTURE_RUNTIME_ROOT:
        raise EvidenceError("future_runtime_stage_manifest_identity_invalid")
    candidate_plists = _mapping(
        manifest_identity.get("candidate_plist_sha256"),
        f"{field}.candidate_plist_sha256",
    )
    if set(candidate_plists) != set(FUTURE_RUNTIME_PLIST_FILENAMES):
        raise EvidenceError("future_runtime_candidate_plist_set_invalid")
    raw_runtime_descriptors = _mapping(
        manifest_identity.get("runtime_file_descriptors"),
        f"{field}.runtime_file_descriptors",
    )
    if not raw_runtime_descriptors or len(raw_runtime_descriptors) > runtime_stage.MAX_SOURCE_FILES:
        raise EvidenceError("future_runtime_manifest_file_set_invalid")
    normalized_runtime_descriptors: dict[str, dict[str, Any]] = {}
    manifest_runtime_hashes: dict[str, str] = {}
    total_runtime_bytes = 0
    for relative, raw_descriptor in sorted(raw_runtime_descriptors.items()):
        parsed = PurePosixPath(str(relative or ""))
        descriptor = _mapping(
            raw_descriptor,
            f"{field}.runtime_file_descriptors.{relative}",
        )
        if (
            not isinstance(relative, str)
            or parsed.is_absolute()
            or not parsed.parts
            or str(parsed) != relative
            or any(part in {"", ".", ".."} for part in parsed.parts)
            or relative in FUTURE_RUNTIME_PLIST_FILENAMES
            or relative in {"pyproject.toml", "uv.lock"}
            or set(descriptor)
            != {"path", "sha256", "size_bytes", "mode", "source_kind", "git_blob"}
            or descriptor.get("path") != relative
            or descriptor.get("mode") not in {"0644", "0755"}
            or descriptor.get("source_kind") != "regular"
        ):
            raise EvidenceError("future_runtime_manifest_file_descriptor_invalid", str(relative))
        size_bytes = _exact_int(
            descriptor.get("size_bytes"),
            f"{field}.{relative}.size_bytes",
            minimum=0,
        )
        if size_bytes > runtime_stage.MAX_SOURCE_FILE_BYTES:
            raise EvidenceError(
                "future_runtime_manifest_file_descriptor_invalid", relative
            )
        sha256 = _sha256_digest(
            descriptor.get("sha256"), f"{field}.{relative}.sha256"
        )
        normalized_runtime_descriptors[relative] = {
            "path": relative,
            "sha256": sha256,
            "size_bytes": size_bytes,
            "mode": descriptor["mode"],
            "source_kind": "regular",
            "git_blob": _git_object_id(
                descriptor.get("git_blob"), f"{field}.{relative}.git_blob"
            ),
        }
        manifest_runtime_hashes[relative] = sha256
        total_runtime_bytes += size_bytes
    if (
        total_runtime_bytes > runtime_stage.MAX_SOURCE_TOTAL_BYTES
        or not set(FUTURE_RUNTIME_RELATIVE_FILES).issubset(manifest_runtime_hashes)
    ):
        raise EvidenceError("future_runtime_manifest_file_set_invalid")
    manifest_runtime_sha256 = _sha256_digest(
        manifest_identity.get("runtime_files_sha256"),
        f"{field}.runtime_files_sha256",
    )
    if manifest_runtime_sha256 != _sha256_json(manifest_runtime_hashes):
        raise EvidenceError("future_runtime_manifest_file_hash_mismatch")
    normalized_manifest_identity = {
        "schema_version": runtime_stage.MANIFEST_SCHEMA_VERSION,
        "staging_root": str(stage_root),
        "manifest_path": str(stage_root / runtime_stage.MANIFEST_FILENAME),
        "manifest_sha256": _sha256_digest(
            manifest_identity.get("manifest_sha256"), f"{field}.manifest_sha256"
        ),
        "plan_sha256": _sha256_digest(
            manifest_identity.get("plan_sha256"), f"{field}.plan_sha256"
        ),
        "content_sha256": _sha256_digest(
            manifest_identity.get("content_sha256"), f"{field}.content_sha256"
        ),
        "source_commit": _commit_sha(
            manifest_identity.get("source_commit"), f"{field}.source_commit"
        ),
        "source_tree": _git_object_id(
            manifest_identity.get("source_tree"), f"{field}.source_tree"
        ),
        "canonical_live_root": _required_text(
            manifest_identity.get("canonical_live_root"),
            f"{field}.canonical_live_root",
        ),
        "candidate_plist_sha256": {
            filename: _sha256_digest(
                candidate_plists.get(filename), f"{field}.{filename}"
            )
            for filename in FUTURE_RUNTIME_PLIST_FILENAMES
        },
        "runtime_file_descriptors": normalized_runtime_descriptors,
        "runtime_files_sha256": manifest_runtime_sha256,
    }
    if (
        manifest_identity.get("manifest_path")
        != normalized_manifest_identity["manifest_path"]
        or normalized_manifest_identity["canonical_live_root"]
        != str(CANONICAL_FUTURE_RUNTIME_ROOT)
    ):
        raise EvidenceError("future_runtime_stage_manifest_identity_invalid")
    manifest_identity_sha256 = _sha256_digest(
        binding.get("runtime_stage_manifest_identity_sha256"),
        f"{field}.runtime_stage_manifest_identity_sha256",
    )
    if manifest_identity_sha256 != _sha256_json(normalized_manifest_identity):
        raise EvidenceError("future_runtime_stage_manifest_identity_hash_mismatch")

    stage_identity = _mapping(
        binding.get("runtime_stage_identity"), f"{field}.runtime_stage_identity"
    )
    if set(stage_identity) != {"root", "venv", "interpreter"}:
        raise EvidenceError("future_runtime_stage_identity_shape_invalid")
    normalized_stage_identity = {
        "root": _normalize_runtime_path_identity(
            stage_identity.get("root"),
            field=f"{field}.runtime_stage_identity.root",
            expected_path=stage_root,
            expected_mode=FUTURE_RUNTIME_STAGING_ROOT_MODE,
        ),
        "venv": _normalize_runtime_path_identity(
            stage_identity.get("venv"),
            field=f"{field}.runtime_stage_identity.venv",
            expected_path=stage_root / ".venv",
            expected_mode=FUTURE_RUNTIME_VENV_MODE,
        ),
        "interpreter": _normalize_runtime_path_identity(
            stage_identity.get("interpreter"),
            field=f"{field}.runtime_stage_identity.interpreter",
            expected_path=stage_root / ".venv" / "bin" / "python",
            expected_mode=0o755,
            include_sha256=True,
        ),
    }
    stage_identity_sha256 = _sha256_digest(
        binding.get("runtime_stage_identity_sha256"),
        f"{field}.runtime_stage_identity_sha256",
    )
    if stage_identity_sha256 != _sha256_json(normalized_stage_identity):
        raise EvidenceError("future_runtime_stage_identity_hash_mismatch")

    projection = _mapping(
        binding.get("future_runtime_projection"), f"{field}.projection"
    )
    if set(projection) != {
        "schema_version",
        "ok",
        "source_commit",
        "staging_root",
        "canonical_live_root",
        "render_manifest_sha256",
    } or (
        projection.get("schema_version") != FUTURE_RUNTIME_PROJECTION_SCHEMA_VERSION
        or projection.get("ok") is not True
    ):
        raise EvidenceError("future_runtime_projection_invalid")
    normalized_projection = {
        "schema_version": FUTURE_RUNTIME_PROJECTION_SCHEMA_VERSION,
        "ok": True,
        "source_commit": _commit_sha(
            projection.get("source_commit"), f"{field}.projection.source_commit"
        ),
        "staging_root": _required_text(
            projection.get("staging_root"), f"{field}.projection.staging_root"
        ),
        "canonical_live_root": _required_text(
            projection.get("canonical_live_root"),
            f"{field}.projection.canonical_live_root",
        ),
        "render_manifest_sha256": _sha256_digest(
            projection.get("render_manifest_sha256"),
            f"{field}.projection.render_manifest_sha256",
        ),
    }
    projection_sha256 = _sha256_digest(
        binding.get("future_runtime_projection_sha256"),
        f"{field}.future_runtime_projection_sha256",
    )
    if projection_sha256 != _sha256_json(normalized_projection):
        raise EvidenceError("future_runtime_projection_hash_mismatch")

    render = _mapping(binding.get("render_manifest"), f"{field}.render_manifest")
    if set(render) != {
        "schema_version",
        "source_repo_root",
        "source_commit",
        "staging_root",
        "canonical_live_root",
        "runtime_file_sha256",
        "runtime_files_sha256",
        "interpreter",
        "dependencies",
        "candidate_plists",
        "canonical_launchd_config_sha256",
        "canonical_runtime_config_sha256",
        "gateway_runtime",
    } or render.get("schema_version") != FUTURE_RUNTIME_RENDER_MANIFEST_SCHEMA_VERSION:
        raise EvidenceError("future_runtime_render_manifest_invalid")
    runtime_files = _mapping(
        render.get("runtime_file_sha256"), f"{field}.render.runtime_files"
    )
    if set(runtime_files) != set(manifest_runtime_hashes):
        raise EvidenceError("future_runtime_render_file_set_invalid")
    normalized_runtime_files = {
        relative: _sha256_digest(runtime_files.get(relative), f"{field}.{relative}")
        for relative in sorted(manifest_runtime_hashes)
    }
    if (
        normalized_runtime_files != manifest_runtime_hashes
        or render.get("runtime_files_sha256") != manifest_runtime_sha256
    ):
        raise EvidenceError("future_runtime_render_file_hash_mismatch")
    render_plists = _mapping(
        render.get("candidate_plists"), f"{field}.render.candidate_plists"
    )
    if set(render_plists) != set(FUTURE_RUNTIME_PLIST_FILENAMES):
        raise EvidenceError("future_runtime_candidate_plist_set_invalid")
    normalized_render_plists: dict[str, dict[str, Any]] = {}
    for filename in FUTURE_RUNTIME_PLIST_FILENAMES:
        descriptor = _mapping(render_plists.get(filename), f"{field}.{filename}")
        if set(descriptor) != {
            "label",
            "source_sha256",
            "staging_sha256",
            "canonical_sha256",
            "canonical_body_sha256",
        } or descriptor.get("label") != runtime_stage.CANDIDATE_PLISTS[filename][0]:
            raise EvidenceError("future_runtime_candidate_plist_invalid", filename)
        normalized_descriptor = {
            "label": descriptor["label"],
            "source_sha256": _sha256_digest(
                descriptor.get("source_sha256"), f"{field}.{filename}.source"
            ),
            "staging_sha256": _sha256_digest(
                descriptor.get("staging_sha256"), f"{field}.{filename}.staging"
            ),
            "canonical_sha256": _sha256_digest(
                descriptor.get("canonical_sha256"), f"{field}.{filename}.canonical"
            ),
            "canonical_body_sha256": _sha256_digest(
                descriptor.get("canonical_body_sha256"), f"{field}.{filename}.body"
            ),
        }
        if (
            normalized_descriptor["source_sha256"]
            != normalized_manifest_identity["candidate_plist_sha256"][filename]
            or normalized_descriptor["canonical_sha256"]
            != normalized_descriptor["source_sha256"]
        ):
            raise EvidenceError("future_runtime_candidate_plist_binding_mismatch", filename)
        normalized_render_plists[filename] = normalized_descriptor
    render_interpreter = _mapping(
        render.get("interpreter"), f"{field}.render.interpreter"
    )
    if set(render_interpreter) != {"staging_path", "canonical_path", "sha256"}:
        raise EvidenceError("future_runtime_render_interpreter_invalid")
    normalized_interpreter = {
        "staging_path": str(stage_root / ".venv" / "bin" / "python"),
        "canonical_path": str(CANONICAL_FUTURE_RUNTIME_ROOT / ".venv/bin/python"),
        "sha256": _sha256_digest(
            render_interpreter.get("sha256"), f"{field}.render.interpreter.sha256"
        ),
    }
    if (
        render_interpreter.get("staging_path") != normalized_interpreter["staging_path"]
        or render_interpreter.get("canonical_path") != normalized_interpreter["canonical_path"]
        or normalized_interpreter["sha256"]
        != normalized_stage_identity["interpreter"]["sha256"]
    ):
        raise EvidenceError("future_runtime_render_interpreter_invalid")
    dependencies = _mapping(render.get("dependencies"), f"{field}.dependencies")
    normalized_dependencies: dict[str, dict[str, str]] = {}
    for name, raw_dependency in sorted(dependencies.items()):
        dependency = _mapping(raw_dependency, f"{field}.dependencies.{name}")
        if set(dependency) != {"staging_path", "canonical_path", "sha256"}:
            raise EvidenceError("future_runtime_dependency_binding_invalid", str(name))
        staging_path = Path(
            _required_text(dependency.get("staging_path"), f"{field}.{name}.staging")
        )
        canonical_path = Path(
            _required_text(dependency.get("canonical_path"), f"{field}.{name}.canonical")
        )
        try:
            relative = staging_path.relative_to(stage_root)
        except ValueError as exc:
            raise EvidenceError("future_runtime_dependency_binding_invalid", str(name)) from exc
        if canonical_path != CANONICAL_FUTURE_RUNTIME_ROOT / relative:
            raise EvidenceError("future_runtime_dependency_binding_invalid", str(name))
        normalized_dependencies[str(name)] = {
            "staging_path": str(staging_path),
            "canonical_path": str(canonical_path),
            "sha256": _sha256_digest(
                dependency.get("sha256"), f"{field}.{name}.sha256"
            ),
        }
    gateway_runtime = dict(
        _mapping(render.get("gateway_runtime"), f"{field}.gateway_runtime")
    )
    gateway_origins = _mapping(
        gateway_runtime.get("module_origins"), f"{field}.gateway_runtime.module_origins"
    )
    if (
        gateway_runtime.get("sys_executable")
        != str(CANONICAL_FUTURE_RUNTIME_ROOT / ".venv/bin/python")
        or gateway_runtime.get("process_executable")
        != str(CANONICAL_FUTURE_RUNTIME_ROOT / ".venv/bin/python")
        or gateway_runtime.get("module_origins_sha256") != _sha256_json(gateway_origins)
    ):
        raise EvidenceError("future_runtime_gateway_binding_invalid")
    for raw_origin in gateway_origins.values():
        try:
            Path(_required_text(raw_origin, f"{field}.gateway_origin")).relative_to(
                CANONICAL_FUTURE_RUNTIME_ROOT
            )
        except ValueError as exc:
            raise EvidenceError("future_runtime_gateway_binding_invalid") from exc
    normalized_render = {
        **dict(render),
        "runtime_file_sha256": normalized_runtime_files,
        "runtime_files_sha256": _sha256_json(normalized_runtime_files),
        "interpreter": normalized_interpreter,
        "dependencies": normalized_dependencies,
        "candidate_plists": normalized_render_plists,
        "canonical_launchd_config_sha256": _sha256_digest(
            render.get("canonical_launchd_config_sha256"),
            f"{field}.canonical_launchd_config_sha256",
        ),
        "canonical_runtime_config_sha256": _sha256_digest(
            render.get("canonical_runtime_config_sha256"),
            f"{field}.canonical_runtime_config_sha256",
        ),
        "gateway_runtime": gateway_runtime,
    }
    render_sha256 = _sha256_digest(
        binding.get("render_manifest_sha256"), f"{field}.render_manifest_sha256"
    )
    host_commit = _commit_sha(host_component.get("commit"), f"{field}.host_commit")
    if (
        render_sha256 != _sha256_json(normalized_render)
        or normalized_projection["render_manifest_sha256"] != render_sha256
        or normalized_projection["source_commit"] != host_commit
        or normalized_manifest_identity["source_commit"] != host_commit
        or normalized_projection["staging_root"] != str(stage_root)
        or normalized_projection["canonical_live_root"]
        != str(CANONICAL_FUTURE_RUNTIME_ROOT)
        or render.get("source_repo_root") != host_component.get("repo_root")
        or render.get("source_commit") != host_commit
        or render.get("staging_root") != str(stage_root)
        or render.get("canonical_live_root") != str(CANONICAL_FUTURE_RUNTIME_ROOT)
        or normalized_render["canonical_runtime_config_sha256"]
        != expected_launchd_config_sha256
    ):
        raise EvidenceError("future_runtime_release_binding_mismatch")
    return {
        "schema_version": FUTURE_RUNTIME_RELEASE_BINDING_SCHEMA_VERSION,
        "runtime_stage_manifest_identity": normalized_manifest_identity,
        "runtime_stage_manifest_identity_sha256": manifest_identity_sha256,
        "runtime_stage_identity": normalized_stage_identity,
        "runtime_stage_identity_sha256": stage_identity_sha256,
        "future_runtime_projection": normalized_projection,
        "future_runtime_projection_sha256": projection_sha256,
        "render_manifest": normalized_render,
        "render_manifest_sha256": render_sha256,
    }


def _auxiliary_runtime_expectations(
    future_runtime_binding: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    render = _mapping(
        future_runtime_binding.get("render_manifest"),
        "auxiliary_runtime.render_manifest",
    )
    runtime_files = _mapping(
        render.get("runtime_file_sha256"), "auxiliary_runtime.runtime_files"
    )
    candidate_plists = _mapping(
        render.get("candidate_plists"), "auxiliary_runtime.candidate_plists"
    )
    interpreter = _mapping(
        render.get("interpreter"), "auxiliary_runtime.interpreter"
    )
    common_environment = {
        "HERMES_HOME": str(CANONICAL_FUTURE_RUNTIME_ROOT.parent.parent),
        "PATH": (
            f"{CANONICAL_FUTURE_RUNTIME_ROOT}/.venv/bin:"
            "/Users/songying/.local/bin:/Users/songying/bin:"
            "/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin"
        ),
        "PYTHONDONTWRITEBYTECODE": "1",
        "PYTHONNOUSERSITE": "1",
        "PYTHONUNBUFFERED": "1",
        "VIRTUAL_ENV": str(CANONICAL_FUTURE_RUNTIME_ROOT / ".venv"),
    }
    contracts = {
        "completion_relay": {
            "filename": "local.pnc.completion-notice-relay.candidate.plist",
            "health_path": str(COMPLETION_RELAY_HEALTH_PATH),
            "environment": {
                **common_environment,
                "PNC_COMPLETION_NOTICE_RELAY_HEALTH_PATH": str(
                    COMPLETION_RELAY_HEALTH_PATH
                ),
                "PNC_RELAY_WATCH_CANARY_LOOPS": "3",
                "PNC_TASK_CARD_MAX_FALLBACKS_PER_LOOP": "0",
            },
        },
        "vm_task_sync": {
            "filename": "local.pnc.vm-task-sync.candidate.plist",
            "completion_path": str(VM_TASK_SYNC_COMPLETION_PATH),
            "environment": {
                **common_environment,
                "PNC_VM_TASK_SYNC_RECEIPT_PATH": str(VM_TASK_SYNC_COMPLETION_PATH),
            },
        },
    }
    projected: dict[str, dict[str, Any]] = {}
    for name, raw_contract in contracts.items():
        contract = dict(raw_contract)
        filename = str(contract.pop("filename"))
        label, script_name = runtime_stage.CANDIDATE_PLISTS[filename]
        relative_script = f"scripts/{script_name}"
        descriptor = _mapping(
            candidate_plists.get(filename), f"auxiliary_runtime.{filename}"
        )
        program_arguments = [
            item.replace("{runtime}", str(CANONICAL_FUTURE_RUNTIME_ROOT))
            for item in runtime_stage.CANDIDATE_PLIST_ARGUMENTS[filename]
        ]
        environment = dict(contract.pop("environment"))
        projected[name] = {
            "service_label": label,
            "executable": str(CANONICAL_FUTURE_RUNTIME_ROOT / ".venv/bin/python"),
            "script": str(CANONICAL_FUTURE_RUNTIME_ROOT / relative_script),
            "cwd": str(CANONICAL_FUTURE_RUNTIME_ROOT),
            "script_sha256": _sha256_digest(
                runtime_files.get(relative_script),
                f"auxiliary_runtime.{name}.script_sha256",
            ),
            "interpreter_sha256": _sha256_digest(
                interpreter.get("sha256"),
                f"auxiliary_runtime.{name}.interpreter_sha256",
            ),
            "plist_path": str(
                Path("/Users/songying/Library/LaunchAgents") / f"{label}.plist"
            ),
            "plist_sha256": _sha256_digest(
                descriptor.get("canonical_sha256"),
                f"auxiliary_runtime.{name}.plist_sha256",
            ),
            "program_arguments": program_arguments,
            "program_arguments_sha256": _sha256_json(program_arguments),
            "environment": environment,
            "environment_sha256": _sha256_json(environment),
            **contract,
        }
    return projected


def _revalidate_workspace_runtime_release_binding(
    binding: Mapping[str, Any],
) -> None:
    expected = _mapping(
        binding.get("staged_identity"), "workspace_runtime.staged_identity"
    )
    try:
        observed = workspace_runtime.validate_staged_workspace_runtime(
            _required_text(expected.get("root"), "workspace_runtime.root")
        ).to_dict()
    except workspace_runtime.WorkspaceRuntimeError as exc:
        raise EvidenceError(exc.code, exc.detail) from exc
    except (OSError, ValueError) as exc:
        raise EvidenceError("workspace_runtime_live_revalidation_failed") from exc
    if observed != expected:
        raise EvidenceError("workspace_runtime_live_identity_mismatch")


def _revalidate_future_runtime_release_binding(
    binding: Mapping[str, Any],
) -> None:
    expected_manifest = _mapping(
        binding.get("runtime_stage_manifest_identity"),
        "future_runtime.runtime_stage_manifest_identity",
    )
    stage_root = Path(
        _required_text(expected_manifest.get("staging_root"), "future_runtime.root")
    )
    manifest_path = stage_root / runtime_stage.MANIFEST_FILENAME
    try:
        manifest_raw, _manifest_info = _stable_regular_file_observation(
            manifest_path,
            artifact="future_runtime_stage_manifest",
            expected_mode=0o600,
            require_owner=True,
        )
        observed_manifest = dict(runtime_stage.validate_staged_runtime(stage_root))
    except runtime_stage.RuntimeStageError as exc:
        raise EvidenceError(exc.code, exc.detail) from exc
    except (OSError, ValueError) as exc:
        raise EvidenceError("future_runtime_stage_live_revalidation_failed") from exc
    projection = _mapping(
        observed_manifest.get("future_canonical_projection"),
        "future_runtime.live_projection",
    )
    content = _mapping(
        observed_manifest.get("content"),
        "future_runtime.live_content",
    )
    source = _mapping(
        content.get("source"),
        "future_runtime.live_content.source",
    )
    runtime_file_descriptors = {
        str(relative): dict(_mapping(descriptor, f"future_runtime.live.{relative}"))
        for relative, descriptor in sorted(
            _mapping(
                source.get("runtime_files"),
                "future_runtime.live_content.source.runtime_files",
            ).items()
        )
    }
    live_manifest_identity = {
        "schema_version": runtime_stage.MANIFEST_SCHEMA_VERSION,
        "staging_root": str(stage_root),
        "manifest_path": str(manifest_path),
        "manifest_sha256": hashlib.sha256(manifest_raw).hexdigest(),
        "plan_sha256": observed_manifest.get("plan_sha256"),
        "content_sha256": observed_manifest.get("content_sha256"),
        "source_commit": projection.get("source_commit"),
        "source_tree": projection.get("source_tree"),
        "canonical_live_root": projection.get("canonical_live_root"),
        "candidate_plist_sha256": projection.get("candidate_plist_sha256"),
        "runtime_file_descriptors": runtime_file_descriptors,
        "runtime_files_sha256": projection.get("runtime_files_sha256"),
    }
    expected_stage = _mapping(
        binding.get("runtime_stage_identity"), "future_runtime.runtime_stage_identity"
    )
    try:
        interpreter_raw, interpreter_info = _stable_regular_file_observation(
            stage_root / ".venv/bin/python",
            artifact="future_runtime_staging_interpreter",
            expected_mode=0o755,
            require_owner=True,
        )
        live_stage_identity = {
            "root": _future_runtime_owned_directory(
                stage_root,
                artifact="future_runtime_staging_root",
                expected_mode=FUTURE_RUNTIME_STAGING_ROOT_MODE,
            ),
            "venv": _future_runtime_owned_directory(
                stage_root / ".venv",
                artifact="future_runtime_staging_venv",
                expected_mode=FUTURE_RUNTIME_VENV_MODE,
            ),
            "interpreter": {
                "path": str(stage_root / ".venv/bin/python"),
                "sha256": hashlib.sha256(interpreter_raw).hexdigest(),
                "owner_uid": interpreter_info.st_uid,
                "mode": stat.S_IMODE(interpreter_info.st_mode),
                "device": interpreter_info.st_dev,
                "inode": interpreter_info.st_ino,
            },
        }
    except (OSError, ValueError) as exc:
        raise EvidenceError("future_runtime_stage_live_revalidation_failed") from exc
    if live_manifest_identity != expected_manifest:
        raise EvidenceError("future_runtime_stage_manifest_live_mismatch")
    if live_stage_identity != expected_stage:
        raise EvidenceError("future_runtime_stage_identity_live_mismatch")


def _validate_release_approval_bom(value: Any) -> dict[str, Any]:
    bom = _mapping(value, "release_approval_request.bindings.release_bom")
    if set(bom) != {
        "schema_version",
        "components",
        "workspace_runtime",
        "future_runtime",
        "runtime_config_sha256",
        "launchd_config_sha256",
        "critical_files_sha256",
        "external_dependencies",
    } or bom.get("schema_version") != RELEASE_BOM_SCHEMA_VERSION:
        raise EvidenceError("release_approval_bom_shape_invalid")
    components = _mapping(bom.get("components"), "release_approval_bom.components")
    if set(components) != {"host", "workspace", "vm", "vm_worker"}:
        raise EvidenceError("release_approval_bom_components_invalid")
    normalized_components: dict[str, dict[str, Any]] = {}
    for name in ("host", "vm", "vm_worker"):
        component = _mapping(components.get(name), f"release_approval_bom.{name}")
        expected_fields = {
            "source",
            "repo_root",
            "commit",
            "tree_clean",
            "status_sha256",
        }
        if name in {"vm", "vm_worker"}:
            expected_fields |= {
                "tree",
                "entrypoint_path",
                "entrypoint_sha256",
                "entrypoint_committed_sha256",
                "entrypoint_git_mode",
                "entrypoint_blob",
            }
        if set(component) != expected_fields:
            raise EvidenceError("release_approval_bom_component_shape_invalid")
        if component.get("tree_clean") is not True:
            raise EvidenceError("release_approval_bom_component_dirty")
        normalized = dict(component)
        normalized["commit"] = _commit_sha(
            component.get("commit"), f"release_approval_bom.{name}.commit"
        )
        normalized["status_sha256"] = _sha256_digest(
            component.get("status_sha256"),
            f"release_approval_bom.{name}.status_sha256",
        )
        if normalized["status_sha256"] != EMPTY_GIT_STATUS_SHA256:
            raise EvidenceError("release_approval_bom_component_dirty")
        if name in {"vm", "vm_worker"}:
            normalized["tree"] = _git_object_id(
                component.get("tree"), f"release_approval_bom.{name}.tree"
            )
            normalized["entrypoint_sha256"] = _sha256_digest(
                component.get("entrypoint_sha256"),
                f"release_approval_bom.{name}.entrypoint_sha256",
            )
            normalized["entrypoint_committed_sha256"] = _sha256_digest(
                component.get("entrypoint_committed_sha256"),
                f"release_approval_bom.{name}.entrypoint_committed_sha256",
            )
            normalized["entrypoint_blob"] = _git_object_id(
                component.get("entrypoint_blob"),
                f"release_approval_bom.{name}.entrypoint_blob",
            )
            if (
                component.get("entrypoint_git_mode") not in {"100644", "100755"}
                or normalized["entrypoint_committed_sha256"]
                != normalized["entrypoint_sha256"]
            ):
                raise EvidenceError("release_approval_bom_entrypoint_invalid")
        normalized_components[name] = normalized
    workspace = _mapping(
        components.get("workspace"), "release_approval_bom.workspace"
    )
    if set(workspace) != {
        "source",
        "repo_root",
        "commit",
        "execution_closure",
        "execution_closure_sha256",
    } or workspace.get("source") != "local_git_scoped_closure":
        raise EvidenceError("release_approval_bom_workspace_shape_invalid")
    workspace_commit = _commit_sha(
        workspace.get("commit"), "release_approval_bom.workspace.commit"
    )
    workspace_root = _required_text(
        workspace.get("repo_root"), "release_approval_bom.workspace.repo_root"
    )
    closure = _normalize_workspace_execution_closure(
        workspace.get("execution_closure"),
        repo_root=workspace_root,
        commit=workspace_commit,
        field="release_approval_bom.workspace.execution_closure",
    )
    closure_sha256 = _sha256_digest(
        workspace.get("execution_closure_sha256"),
        "release_approval_bom.workspace.execution_closure_sha256",
    )
    if _sha256_json(closure) != closure_sha256:
        raise EvidenceError("release_approval_bom_workspace_hash_mismatch")
    normalized_components["workspace"] = {
        **dict(workspace),
        "commit": workspace_commit,
        "execution_closure": closure,
        "execution_closure_sha256": closure_sha256,
    }
    launchd_config_sha256 = _sha256_digest(
        bom.get("launchd_config_sha256"),
        "release_approval_bom.launchd_config_sha256",
    )
    workspace_runtime_binding = _normalize_workspace_runtime_release_binding(
        bom.get("workspace_runtime"),
        workspace_component=normalized_components["workspace"],
        field="release_approval_bom.workspace_runtime",
    )
    future_runtime_binding = _normalize_future_runtime_release_binding(
        bom.get("future_runtime"),
        host_component=normalized_components["host"],
        expected_launchd_config_sha256=launchd_config_sha256,
        field="release_approval_bom.future_runtime",
    )
    _revalidate_workspace_runtime_release_binding(workspace_runtime_binding)
    _revalidate_future_runtime_release_binding(future_runtime_binding)
    external = _normalize_external_dependencies(
        bom.get("external_dependencies"),
        field="release_approval_bom.external_dependencies",
    )
    return {
        "schema_version": RELEASE_BOM_SCHEMA_VERSION,
        "components": normalized_components,
        "workspace_runtime": workspace_runtime_binding,
        "future_runtime": future_runtime_binding,
        "runtime_config_sha256": _sha256_digest(
            bom.get("runtime_config_sha256"),
            "release_approval_bom.runtime_config_sha256",
        ),
        "launchd_config_sha256": launchd_config_sha256,
        "critical_files_sha256": _sha256_digest(
            bom.get("critical_files_sha256"),
            "release_approval_bom.critical_files_sha256",
        ),
        "external_dependencies": external,
    }


def validate_release_prepare_approval_binding(
    *,
    approval_request: Mapping[str, Any],
    approval_request_sha256: str,
    approval_receipt: Mapping[str, Any],
    approval_receipt_sha256: str,
    final_manifest_schema_version: str,
    now: datetime | None = None,
    machine_identity_observer: Callable[[], Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    """Validate the exact request/receipt pair before any cutover projection."""
    if final_manifest_schema_version != RELEASE_PREPARE_FINAL_MANIFEST_SCHEMA_VERSION:
        raise EvidenceError("release_approval_final_manifest_schema_invalid")
    request = _mapping(approval_request, "release_approval_request")
    if set(request) != {
        "schema_version",
        "release_id",
        "created_at",
        "production_effects_executed",
        "approval_required_for_finalize",
        "approval_identity_requirement",
        "action_set",
        "action_set_sha256",
        "bindings",
        "candidate_plist_sha256",
        "workspace_governance",
        "external_dependencies",
        "rollback",
        "side_effect_contract",
    }:
        raise EvidenceError("release_approval_request_shape_invalid")
    if request.get("schema_version") != RELEASE_APPROVAL_REQUEST_SCHEMA_VERSION:
        raise EvidenceError("release_approval_request_schema_invalid")
    request_sha256 = _sha256_digest(
        approval_request_sha256, "release_approval_request.raw_sha256"
    )
    if _release_prepare_file_sha256(request) != request_sha256:
        raise EvidenceError("release_approval_request_raw_hash_mismatch")
    release_id = _required_text(request.get("release_id"), "release_approval.release_id")
    if RELEASE_APPROVAL_RELEASE_ID_PATTERN.fullmatch(release_id) is None:
        raise EvidenceError("release_approval_release_id_invalid")
    current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    request_created_at = _release_approval_timestamp(
        request.get("created_at"), "release_approval_request.created_at"
    )
    request_age = (current - request_created_at).total_seconds()
    if request_age < -RELEASE_APPROVAL_MAX_FUTURE_SKEW_SECONDS:
        raise EvidenceError("release_approval_request_from_future")
    if request_age > DEFAULT_EVIDENCE_MAX_AGE_SECONDS:
        raise EvidenceError("release_approval_request_stale")
    if (
        request.get("production_effects_executed") is not False
        or request.get("approval_required_for_finalize") is not True
    ):
        raise EvidenceError("release_approval_request_effect_contract_invalid")
    action_set = request.get("action_set")
    expected_actions = list(RELEASE_PREPARE_ACTION_SET)
    if action_set != expected_actions:
        raise EvidenceError("release_approval_action_set_mismatch")
    action_set_sha256 = _sha256_digest(
        request.get("action_set_sha256"), "release_approval.action_set_sha256"
    )
    if action_set_sha256 != _sha256_json(expected_actions):
        raise EvidenceError("release_approval_action_hash_mismatch")
    observer = machine_identity_observer or _observe_release_approval_machine_identity
    try:
        machine_identity = _mapping(observer(), "release_approval.machine_identity")
    except EvidenceError:
        raise
    except Exception as exc:
        raise EvidenceError("release_approval_machine_identity_unavailable") from exc
    identity = _release_approval_identity_requirement(
        request.get("approval_identity_requirement"),
        machine_identity=machine_identity,
    )
    bindings = _mapping(request.get("bindings"), "release_approval_request.bindings")
    if set(bindings) != {
        "release_bom",
        "release_bom_sha256",
        "build_manifest_sha256",
        "runtime_config_sha256",
        "launchd_config_sha256",
        "t0",
        "t0_sha256",
        "rollback_config_sha256",
        "rollback_window_seconds",
        "workspace_closure_sha256",
        "workspace_runtime_sha256",
        "future_runtime_sha256",
    }:
        raise EvidenceError("release_approval_bindings_shape_invalid")
    bom = _validate_release_approval_bom(bindings.get("release_bom"))
    release_bom_sha256 = _sha256_digest(
        bindings.get("release_bom_sha256"), "release_approval.release_bom_sha256"
    )
    if _sha256_json(bom) != release_bom_sha256:
        raise EvidenceError("release_approval_release_bom_hash_mismatch")
    workspace_runtime_sha256 = _sha256_digest(
        bindings.get("workspace_runtime_sha256"),
        "release_approval.workspace_runtime_sha256",
    )
    future_runtime_sha256 = _sha256_digest(
        bindings.get("future_runtime_sha256"),
        "release_approval.future_runtime_sha256",
    )
    if (
        workspace_runtime_sha256 != _sha256_json(bom["workspace_runtime"])
        or future_runtime_sha256 != _sha256_json(bom["future_runtime"])
    ):
        raise EvidenceError("release_approval_runtime_binding_hash_mismatch")
    runtime_config_sha256 = _sha256_digest(
        bindings.get("runtime_config_sha256"),
        "release_approval.runtime_config_sha256",
    )
    launchd_config_sha256 = _sha256_digest(
        bindings.get("launchd_config_sha256"),
        "release_approval.launchd_config_sha256",
    )
    if (
        runtime_config_sha256 != bom["runtime_config_sha256"]
        or launchd_config_sha256 != bom["launchd_config_sha256"]
    ):
        raise EvidenceError("release_approval_runtime_fingerprint_mismatch")
    _sha256_digest(
        bindings.get("build_manifest_sha256"),
        "release_approval.build_manifest_sha256",
    )
    t0 = _mapping(bindings.get("t0"), "release_approval.t0")
    if set(t0) != {
        "schema_version",
        "topic",
        "group_id",
        "initial_offsets",
    } or t0.get("schema_version") != RELEASE_PREPARE_T0_SCHEMA_VERSION:
        raise EvidenceError("release_approval_t0_shape_invalid")
    _required_text(t0.get("topic"), "release_approval.t0.topic")
    _required_text(t0.get("group_id"), "release_approval.t0.group_id")
    offsets = _mapping(t0.get("initial_offsets"), "release_approval.t0.offsets")
    if not offsets or any(
        re.fullmatch(r"0|[1-9][0-9]*", str(partition)) is None
        or isinstance(offset, bool)
        or not isinstance(offset, int)
        or offset < 0
        for partition, offset in offsets.items()
    ):
        raise EvidenceError("release_approval_t0_offsets_invalid")
    t0_sha256 = _sha256_digest(
        bindings.get("t0_sha256"), "release_approval.t0_sha256"
    )
    if _sha256_json(t0) != t0_sha256:
        raise EvidenceError("release_approval_t0_hash_mismatch")
    rollback = _mapping(request.get("rollback"), "release_approval.rollback")
    if set(rollback) != {
        "schema_version",
        "owner",
        "procedure",
        "max_restore_seconds",
        "rollback_window_seconds",
    } or rollback.get("schema_version") != RELEASE_PREPARE_ROLLBACK_SCHEMA_VERSION:
        raise EvidenceError("release_approval_rollback_shape_invalid")
    _required_text(rollback.get("owner"), "release_approval.rollback.owner")
    _required_text(rollback.get("procedure"), "release_approval.rollback.procedure")
    max_restore_seconds = _exact_int(
        rollback.get("max_restore_seconds"),
        "release_approval.rollback.max_restore_seconds",
        minimum=1,
    )
    rollback_window_seconds = _exact_int(
        rollback.get("rollback_window_seconds"),
        "release_approval.rollback.rollback_window_seconds",
        minimum=max_restore_seconds,
    )
    rollback_sha256 = _sha256_digest(
        bindings.get("rollback_config_sha256"),
        "release_approval.rollback_config_sha256",
    )
    if (
        _sha256_json(rollback) != rollback_sha256
        or bindings.get("rollback_window_seconds") != rollback_window_seconds
    ):
        raise EvidenceError("release_approval_rollback_binding_mismatch")
    workspace = bom["components"]["workspace"]
    if bindings.get("workspace_closure_sha256") != workspace[
        "execution_closure_sha256"
    ]:
        raise EvidenceError("release_approval_workspace_closure_mismatch")
    candidate_plists = _mapping(
        request.get("candidate_plist_sha256"), "release_approval.candidate_plists"
    )
    if set(candidate_plists) != set(FUTURE_RUNTIME_PLIST_FILENAMES) or any(
        _sha256_digest(value, f"release_approval.candidate_plists.{name}") != value
        for name, value in candidate_plists.items()
    ):
        raise EvidenceError("release_approval_candidate_plists_invalid")
    governance = _mapping(
        request.get("workspace_governance"), "release_approval.workspace_governance"
    )
    if set(governance) != {
        "schema_version",
        "execution_closure",
        "unscoped_drift",
    } or governance.get("schema_version") != WORKSPACE_GOVERNANCE_SCHEMA_VERSION:
        raise EvidenceError("release_approval_workspace_governance_invalid")
    execution = _mapping(
        governance.get("execution_closure"),
        "release_approval.workspace_governance.execution_closure",
    )
    expected_file_sha256 = {
        relative: item["sha256"]
        for relative, item in workspace["execution_closure"]["files"].items()
    }
    if set(execution) != {"ok", "hash", "required_paths", "commit", "files"} or (
        execution
        != {
            "ok": True,
            "hash": workspace["execution_closure_sha256"],
            "required_paths": list(WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS),
            "commit": workspace["commit"],
            "files": expected_file_sha256,
        }
    ):
        raise EvidenceError("release_approval_workspace_governance_invalid")
    _normalize_unscoped_workspace_drift(governance.get("unscoped_drift"))
    external = _normalize_external_dependencies(
        request.get("external_dependencies"),
        field="release_approval.external_dependencies",
    )
    if external != bom["external_dependencies"]:
        raise EvidenceError("release_approval_external_dependencies_mismatch")
    side_effect_contract = _mapping(
        request.get("side_effect_contract"), "release_approval.side_effect_contract"
    )
    if side_effect_contract != {
        "live_files_written": False,
        "launchctl_invoked": False,
        "kafka_consumer_created": False,
        "kafka_offsets_mutated": False,
        "feishu_writes": False,
        "vm_files_written": False,
        "output_scope": "unique_owner_only_run_root",
    }:
        raise EvidenceError("release_approval_side_effect_contract_invalid")
    receipt = _mapping(approval_receipt, "release_approval_receipt")
    if set(receipt) != {
        "schema_version",
        "release_id",
        "decision",
        "created_at",
        "expires_at",
        "nonce",
        "action_set",
        "action_set_sha256",
        "approval_request_sha256",
        "release_bom_sha256",
        "workspace_runtime_sha256",
        "future_runtime_sha256",
        "runtime_config_sha256",
        "t0_sha256",
        "rollback_config_sha256",
        "rollback_window_seconds",
        "identity",
    }:
        raise EvidenceError("release_approval_receipt_shape_invalid")
    if receipt.get("schema_version") != RELEASE_APPROVAL_RECEIPT_SCHEMA_VERSION:
        raise EvidenceError("release_approval_receipt_schema_invalid")
    receipt_sha256 = _sha256_digest(
        approval_receipt_sha256, "release_approval_receipt.raw_sha256"
    )
    if _release_prepare_file_sha256(receipt) != receipt_sha256:
        raise EvidenceError("release_approval_receipt_raw_hash_mismatch")
    if receipt.get("release_id") != release_id:
        raise EvidenceError("release_approval_release_id_mismatch")
    if receipt.get("decision") != RELEASE_APPROVAL_DECISION:
        raise EvidenceError("release_approval_decision_invalid")
    nonce = receipt.get("nonce")
    if not isinstance(nonce, str) or RELEASE_APPROVAL_NONCE_PATTERN.fullmatch(nonce) is None:
        raise EvidenceError("release_approval_nonce_invalid")
    receipt_created_at = _release_approval_timestamp(
        receipt.get("created_at"), "release_approval_receipt.created_at"
    )
    expires_at = _release_approval_timestamp(
        receipt.get("expires_at"), "release_approval_receipt.expires_at"
    )
    validity = (expires_at - receipt_created_at).total_seconds()
    if (
        receipt_created_at < request_created_at
        or receipt_created_at - current
        > timedelta(seconds=RELEASE_APPROVAL_MAX_FUTURE_SKEW_SECONDS)
        or validity <= 0
        or validity > RELEASE_APPROVAL_MAX_VALIDITY_SECONDS
        or current >= expires_at
    ):
        raise EvidenceError("release_approval_time_binding_invalid")
    expected_receipt_bindings = {
        "action_set": expected_actions,
        "action_set_sha256": action_set_sha256,
        "approval_request_sha256": request_sha256,
        "release_bom_sha256": release_bom_sha256,
        "workspace_runtime_sha256": workspace_runtime_sha256,
        "future_runtime_sha256": future_runtime_sha256,
        "runtime_config_sha256": runtime_config_sha256,
        "t0_sha256": t0_sha256,
        "rollback_config_sha256": rollback_sha256,
        "rollback_window_seconds": rollback_window_seconds,
    }
    if any(receipt.get(key) != value for key, value in expected_receipt_bindings.items()):
        raise EvidenceError("release_approval_receipt_binding_mismatch")
    receipt_identity = _release_approval_identity_requirement(
        receipt.get("identity"), machine_identity=machine_identity
    )
    if receipt_identity != identity:
        raise EvidenceError("release_approval_identity_mismatch")
    return {
        "schema_version": RELEASE_APPROVAL_BINDING_VALIDATION_SCHEMA_VERSION,
        "ok": True,
        "approval_request_sha256": request_sha256,
        "approval_receipt_sha256": receipt_sha256,
        "cutover_plan_schema_version": CUTOVER_PLAN_SCHEMA_VERSION,
        "final_manifest_schema_version": RELEASE_PREPARE_FINAL_MANIFEST_SCHEMA_VERSION,
    }


def _feishu_ingress_artifact_sha256(value: Mapping[str, Any]) -> str:
    try:
        raw = feishu_ingress_hold._canonical_json(value)
    except feishu_ingress_hold.IngressHoldError as exc:
        raise EvidenceError("feishu_ingress_hold_gate_json_invalid") from exc
    return hashlib.sha256(raw).hexdigest()


def _validate_feishu_ingress_hold_plan(
    value: Any,
    *,
    plan_sha256: str,
) -> dict[str, Any]:
    plan = _mapping(value, "feishu_ingress_hold.plan")
    if set(plan) != {
        "schema_version",
        "hold_id",
        "created_at",
        "production_effects_executed",
        "phase",
        "chat_ids",
        "chat_set_sha256",
        "app_scope",
        "run_identity_sha256",
        "host_adapter_identity",
        "live_sidecar_identity",
        "window",
        "api_snapshot",
        "apply_contract",
        "future_install",
        "side_effect_contract",
    }:
        raise EvidenceError("feishu_ingress_hold_gate_plan_shape_invalid")
    if (
        plan.get("schema_version") != feishu_ingress_hold.PLAN_SCHEMA_VERSION
        or plan.get("production_effects_executed") is not False
        or plan.get("phase") != "plan"
        or feishu_ingress_hold.HOLD_ID_RE.fullmatch(
            str(plan.get("hold_id") or "")
        )
        is None
        or _feishu_ingress_artifact_sha256(plan) != plan_sha256
    ):
        raise EvidenceError("feishu_ingress_hold_gate_plan_invalid")
    try:
        feishu_ingress_hold._parse_timestamp(
            plan.get("created_at"), artifact="gate_plan_created"
        )
    except feishu_ingress_hold.IngressHoldError as exc:
        raise EvidenceError("feishu_ingress_hold_gate_plan_time_invalid") from exc
    chat_ids = plan.get("chat_ids")
    if (
        not isinstance(chat_ids, list)
        or not chat_ids
        or len(chat_ids) > 32
        or chat_ids != sorted(set(chat_ids))
        or any(
            not isinstance(chat_id, str)
            or feishu_ingress_hold.CHAT_ID_RE.fullmatch(chat_id) is None
            for chat_id in chat_ids
        )
        or plan.get("chat_set_sha256")
        != feishu_ingress_hold._sha256_json(chat_ids)
        or re.fullmatch(r"[0-9a-f]{32}", str(plan.get("app_scope") or ""))
        is None
    ):
        raise EvidenceError("feishu_ingress_hold_gate_chat_set_invalid")
    _sha256_digest(
        plan.get("run_identity_sha256"),
        "feishu_ingress_hold.plan.run_identity_sha256",
    )
    host = _mapping(
        plan.get("host_adapter_identity"),
        "feishu_ingress_hold.plan.host_adapter_identity",
    )
    if set(host) != {
        "schema_version",
        "repo_root",
        "host_commit",
        "tree_clean",
        "status_sha256",
        "adapter_relative_path",
        "adapter_sha256",
        "adapter_sidecar_schema",
    }:
        raise EvidenceError("feishu_ingress_hold_gate_host_identity_invalid")
    repo_root = Path(
        _required_text(host.get("repo_root"), "feishu_ingress_hold.host.repo_root")
    )
    if (
        host.get("schema_version")
        != feishu_ingress_hold.ADAPTER_IDENTITY_SCHEMA_VERSION
        or not repo_root.is_absolute()
        or repo_root != repo_root.expanduser().absolute()
        or host.get("tree_clean") is not True
        or host.get("status_sha256") != feishu_ingress_hold.EMPTY_SHA256
        or host.get("adapter_relative_path")
        != feishu_ingress_hold.ADAPTER_RELATIVE_PATH
        or host.get("adapter_sidecar_schema")
        != feishu_ingress_hold._API_POLL_SIDECAR_SCHEMA
    ):
        raise EvidenceError("feishu_ingress_hold_gate_host_identity_invalid")
    _commit_sha(host.get("host_commit"), "feishu_ingress_hold.host_commit")
    _sha256_digest(
        host.get("adapter_sha256"), "feishu_ingress_hold.host.adapter_sha256"
    )
    future_install = _mapping(
        plan.get("future_install"), "feishu_ingress_hold.plan.future_install"
    )
    if set(future_install) != {
        "performed",
        "requires_separate_cutover",
        "canonical_gateway_root",
        "canonical_sidecar_path",
        "procedure",
    }:
        raise EvidenceError("feishu_ingress_hold_gate_future_install_invalid")
    canonical_root = Path(
        _required_text(
            future_install.get("canonical_gateway_root"),
            "feishu_ingress_hold.canonical_gateway_root",
        )
    )
    canonical_sidecar = Path(
        _required_text(
            future_install.get("canonical_sidecar_path"),
            "feishu_ingress_hold.canonical_sidecar_path",
        )
    )
    if (
        future_install.get("performed") is not False
        or future_install.get("requires_separate_cutover") is not True
        or canonical_root != feishu_ingress_hold.DEFAULT_CANONICAL_GATEWAY_ROOT
        or not canonical_sidecar.is_absolute()
        or canonical_sidecar != canonical_sidecar.expanduser().absolute()
        or not isinstance(future_install.get("procedure"), str)
        or not future_install["procedure"].strip()
    ):
        raise EvidenceError("feishu_ingress_hold_gate_future_install_invalid")
    sidecar = _mapping(
        plan.get("live_sidecar_identity"),
        "feishu_ingress_hold.plan.live_sidecar_identity",
    )
    if set(sidecar) != {
        "schema_version",
        "state",
        "path",
        "sha256",
        "size_bytes",
        "revision",
        "semantic_sha256",
    }:
        raise EvidenceError("feishu_ingress_hold_gate_sidecar_identity_invalid")
    sidecar_size = _exact_int(
        sidecar.get("size_bytes"), "feishu_ingress_hold.sidecar.size_bytes"
    )
    sidecar_revision = _exact_int(
        sidecar.get("revision"), "feishu_ingress_hold.sidecar.revision"
    )
    if (
        sidecar.get("schema_version")
        != feishu_ingress_hold.SIDECAR_IDENTITY_SCHEMA_VERSION
        or sidecar.get("state") not in {"absent", "present"}
        or sidecar.get("path") != str(canonical_sidecar)
        or sidecar_size > feishu_ingress_hold.MAX_FILE_BYTES
        or (
            sidecar.get("state") == "absent"
            and (
                sidecar.get("sha256") != feishu_ingress_hold.EMPTY_SHA256
                or sidecar_size != 0
                or sidecar_revision != 0
            )
        )
    ):
        raise EvidenceError("feishu_ingress_hold_gate_sidecar_identity_invalid")
    _sha256_digest(sidecar.get("sha256"), "feishu_ingress_hold.sidecar.sha256")
    _sha256_digest(
        sidecar.get("semantic_sha256"),
        "feishu_ingress_hold.sidecar.semantic_sha256",
    )
    window = _mapping(plan.get("window"), "feishu_ingress_hold.plan.window")
    snapshot = _mapping(
        plan.get("api_snapshot"), "feishu_ingress_hold.plan.api_snapshot"
    )
    floors = _mapping(window.get("floor_by_chat"), "feishu_ingress_hold.plan.floors")
    if set(window) != {
        "hold_start_ms",
        "floor_by_chat",
        "snapshot_completed_at_ms",
    } or set(snapshot) != {"chats"}:
        raise EvidenceError("feishu_ingress_hold_gate_window_invalid")
    snapshots = _mapping(snapshot.get("chats"), "feishu_ingress_hold.plan.snapshots")
    hold_start_ms = _exact_int(
        window.get("hold_start_ms"), "feishu_ingress_hold.window.hold_start_ms"
    )
    completed_at_ms = _exact_int(
        window.get("snapshot_completed_at_ms"),
        "feishu_ingress_hold.window.snapshot_completed_at_ms",
    )
    if set(floors) != set(chat_ids) or set(snapshots) != set(chat_ids):
        raise EvidenceError("feishu_ingress_hold_gate_window_invalid")
    normalized_snapshots: dict[str, Mapping[str, Any]] = {}
    for chat_id in chat_ids:
        floor = _exact_int(
            floors.get(chat_id), f"feishu_ingress_hold.window.floor.{chat_id}"
        )
        if floor > hold_start_ms:
            raise EvidenceError("feishu_ingress_hold_gate_window_invalid")
        try:
            normalized = feishu_ingress_hold._normalize_snapshot(
                _mapping(
                    snapshots.get(chat_id),
                    f"feishu_ingress_hold.snapshot.{chat_id}",
                ),
                chat_id=chat_id,
                floor_ms=floor,
            )
        except feishu_ingress_hold.IngressHoldError as exc:
            raise EvidenceError("feishu_ingress_hold_gate_snapshot_invalid") from exc
        if normalized != snapshots[chat_id]:
            raise EvidenceError("feishu_ingress_hold_gate_snapshot_invalid")
        normalized_snapshots[chat_id] = normalized
    if completed_at_ms != max(
        snapshot_body["completed_at_ms"]
        for snapshot_body in normalized_snapshots.values()
    ):
        raise EvidenceError("feishu_ingress_hold_gate_window_invalid")
    if plan.get("apply_contract") != {
        "approval_schema_version": feishu_ingress_hold.APPROVAL_SCHEMA_VERSION,
        "cutover_binding_schema_version": (
            feishu_ingress_hold.CUTOVER_BINDING_SCHEMA_VERSION
        ),
        "gate_validator_required": (
            "validate_feishu_ingress_hold_cutover_binding"
        ),
        "watermark_policy": "preserve_or_increase_never_advance_for_pending",
        "live_install_performed_by_this_tool": False,
    } or plan.get("side_effect_contract") != {
        "feishu_message_writes": False,
        "live_sidecar_writes": False,
        "gateway_process_changes": False,
        "launchctl_invoked": False,
        "auth_token_exchange": True,
        "message_api": "GET_only",
        "output_scope": "unique_owner_only_run_root",
    }:
        raise EvidenceError("feishu_ingress_hold_gate_contract_invalid")
    return {
        "hold_id": plan["hold_id"],
        "chat_set_sha256": plan["chat_set_sha256"],
        "app_scope": plan["app_scope"],
        "host": dict(host),
        "sidecar": dict(sidecar),
        "canonical_root": str(canonical_root),
        "canonical_sidecar": str(canonical_sidecar),
    }


def validate_feishu_ingress_hold_cutover_binding(
    *,
    plan: Mapping[str, Any],
    plan_sha256: str,
    approval_receipt: Mapping[str, Any],
    approval_receipt_sha256: str,
    cutover_binding: Mapping[str, Any],
    cutover_binding_sha256: str,
    writer_stop_receipt: Mapping[str, Any],
    writer_stop_receipt_sha256: str,
) -> dict[str, Any]:
    """Validate the v2 ingress-hold authorization and stopped-writer binding."""
    normalized_plan_sha256 = _sha256_digest(
        plan_sha256, "feishu_ingress_hold.plan_sha256"
    )
    normalized_approval_sha256 = _sha256_digest(
        approval_receipt_sha256,
        "feishu_ingress_hold.approval_receipt_sha256",
    )
    normalized_cutover_sha256 = _sha256_digest(
        cutover_binding_sha256,
        "feishu_ingress_hold.cutover_binding_sha256",
    )
    normalized_writer_stop_sha256 = _sha256_digest(
        writer_stop_receipt_sha256,
        "feishu_ingress_hold.writer_stop_receipt_sha256",
    )
    plan_binding = _validate_feishu_ingress_hold_plan(
        plan,
        plan_sha256=normalized_plan_sha256,
    )
    approval = _mapping(
        approval_receipt, "feishu_ingress_hold.approval_receipt"
    )
    if set(approval) != {
        "schema_version",
        "hold_id",
        "decision",
        "created_at",
        "expires_at",
        "nonce",
        "plan_sha256",
        "chat_set_sha256",
        "host_commit",
        "adapter_sha256",
        "adapter_sidecar_schema",
        "live_sidecar_identity_sha256",
        "app_scope",
        "action_set",
        "action_set_sha256",
        "identity",
    } or _feishu_ingress_artifact_sha256(approval) != normalized_approval_sha256:
        raise EvidenceError("feishu_ingress_hold_gate_approval_shape_invalid")
    host = plan_binding["host"]
    sidecar = plan_binding["sidecar"]
    try:
        expected_identity = feishu_ingress_hold._approval_identity(
            feishu_ingress_hold._machine_identity()
        )
        approval_created = feishu_ingress_hold._parse_timestamp(
            approval.get("created_at"), artifact="gate_approval_created"
        )
        approval_expires = feishu_ingress_hold._parse_timestamp(
            approval.get("expires_at"), artifact="gate_approval_expires"
        )
    except feishu_ingress_hold.IngressHoldError as exc:
        raise EvidenceError("feishu_ingress_hold_gate_approval_invalid") from exc
    expected_approval = {
        "schema_version": feishu_ingress_hold.APPROVAL_SCHEMA_VERSION,
        "hold_id": plan_binding["hold_id"],
        "decision": "authorize_feishu_ingress_hold_staging",
        "plan_sha256": normalized_plan_sha256,
        "chat_set_sha256": plan_binding["chat_set_sha256"],
        "host_commit": host["host_commit"],
        "adapter_sha256": host["adapter_sha256"],
        "adapter_sidecar_schema": host["adapter_sidecar_schema"],
        "live_sidecar_identity_sha256": feishu_ingress_hold._sha256_json(sidecar),
        "app_scope": plan_binding["app_scope"],
        "action_set": list(feishu_ingress_hold.APPLY_ACTION_SET),
        "action_set_sha256": feishu_ingress_hold._sha256_json(
            list(feishu_ingress_hold.APPLY_ACTION_SET)
        ),
        "identity": expected_identity,
    }
    if any(approval.get(key) != value for key, value in expected_approval.items()):
        raise EvidenceError("feishu_ingress_hold_gate_approval_binding_mismatch")
    if (
        feishu_ingress_hold.NONCE_RE.fullmatch(str(approval.get("nonce") or ""))
        is None
        or approval_expires <= approval_created
        or (approval_expires - approval_created).total_seconds()
        > feishu_ingress_hold.MAX_APPROVAL_VALIDITY_SECONDS
    ):
        raise EvidenceError("feishu_ingress_hold_gate_approval_invalid")
    cutover = _mapping(cutover_binding, "feishu_ingress_hold.cutover_binding")
    if set(cutover) != {
        "schema_version",
        "hold_id",
        "release_id",
        "plan_sha256",
        "canonical_gateway_root",
        "canonical_sidecar_path",
        "host_commit",
        "adapter_sha256",
        "chat_set_sha256",
        "live_sidecar_identity_sha256",
        "gateway_writer_state",
        "writer_stop_receipt_path",
        "writer_stop_receipt_sha256",
        "cutover_lease_fingerprint",
        "release_prepare_manifest_sha256",
        "release_approval_receipt_sha256",
        "old_gateway_runtime_identity_sha256",
        "window_started_at",
        "window_expires_at",
    } or _feishu_ingress_artifact_sha256(cutover) != normalized_cutover_sha256:
        raise EvidenceError("feishu_ingress_hold_gate_cutover_shape_invalid")
    expected_cutover = {
        "schema_version": feishu_ingress_hold.CUTOVER_BINDING_SCHEMA_VERSION,
        "hold_id": plan_binding["hold_id"],
        "plan_sha256": normalized_plan_sha256,
        "canonical_gateway_root": plan_binding["canonical_root"],
        "canonical_sidecar_path": plan_binding["canonical_sidecar"],
        "host_commit": host["host_commit"],
        "adapter_sha256": host["adapter_sha256"],
        "chat_set_sha256": plan_binding["chat_set_sha256"],
        "live_sidecar_identity_sha256": feishu_ingress_hold._sha256_json(sidecar),
        "gateway_writer_state": "stopped",
        "writer_stop_receipt_sha256": normalized_writer_stop_sha256,
        "release_approval_receipt_sha256": normalized_approval_sha256,
    }
    if any(cutover.get(key) != value for key, value in expected_cutover.items()):
        raise EvidenceError("feishu_ingress_hold_gate_cutover_binding_mismatch")
    if feishu_ingress_hold.RELEASE_ID_RE.fullmatch(
        str(cutover.get("release_id") or "")
    ) is None:
        raise EvidenceError("feishu_ingress_hold_gate_release_id_invalid")
    writer_stop_path = Path(str(cutover.get("writer_stop_receipt_path") or ""))
    if (
        not writer_stop_path.is_absolute()
        or writer_stop_path != writer_stop_path.expanduser().absolute()
    ):
        raise EvidenceError("feishu_ingress_hold_gate_writer_stop_path_invalid")
    for field in (
        "cutover_lease_fingerprint",
        "release_prepare_manifest_sha256",
        "old_gateway_runtime_identity_sha256",
    ):
        _sha256_digest(cutover.get(field), f"feishu_ingress_hold.cutover.{field}")
    try:
        cutover_started = feishu_ingress_hold._parse_timestamp(
            cutover.get("window_started_at"), artifact="gate_cutover_started"
        )
        cutover_expires = feishu_ingress_hold._parse_timestamp(
            cutover.get("window_expires_at"), artifact="gate_cutover_expires"
        )
    except feishu_ingress_hold.IngressHoldError as exc:
        raise EvidenceError("feishu_ingress_hold_gate_cutover_window_invalid") from exc
    current = datetime.now(timezone.utc)
    if (
        current >= approval_expires
        or approval_created - current
        > timedelta(seconds=feishu_ingress_hold.MAX_FUTURE_SKEW_SECONDS)
        or cutover_expires <= cutover_started
        or (cutover_expires - cutover_started).total_seconds()
        > feishu_ingress_hold.MAX_CUTOVER_WINDOW_SECONDS
        or cutover_started - current
        > timedelta(seconds=feishu_ingress_hold.MAX_FUTURE_SKEW_SECONDS)
        or current >= cutover_expires
    ):
        raise EvidenceError("feishu_ingress_hold_gate_cutover_window_invalid")
    try:
        owned_writer_stop, normalized_writer_stop = (
            cutover_guard.read_writer_stop_receipt(
                writer_stop_path,
                now=current,
            )
        )
    except cutover_guard.CutoverGuardError as exc:
        raise EvidenceError(exc.code, exc.detail) from exc
    supplied_writer_stop = _mapping(
        writer_stop_receipt, "feishu_ingress_hold.writer_stop_receipt"
    )
    if (
        owned_writer_stop.path != writer_stop_path
        or owned_writer_stop.sha256 != normalized_writer_stop_sha256
        or dict(normalized_writer_stop) != dict(supplied_writer_stop)
    ):
        raise EvidenceError("feishu_ingress_hold_gate_writer_stop_mismatch")
    expected_writer_stop = {
        "release_id": cutover["release_id"],
        "hold_id": plan_binding["hold_id"],
        "plan_sha256": normalized_plan_sha256,
        "lease_fingerprint": cutover["cutover_lease_fingerprint"],
        "release_prepare_manifest_sha256": cutover[
            "release_prepare_manifest_sha256"
        ],
        "approval_receipt_sha256": normalized_approval_sha256,
        "old_gateway_runtime_identity_sha256": cutover[
            "old_gateway_runtime_identity_sha256"
        ],
        "live_sidecar_identity": sidecar,
        "live_sidecar_identity_sha256": feishu_ingress_hold._sha256_json(sidecar),
    }
    if any(
        normalized_writer_stop.get(key) != value
        for key, value in expected_writer_stop.items()
    ):
        raise EvidenceError("feishu_ingress_hold_gate_writer_stop_binding_mismatch")
    try:
        normalized_observation = cutover_guard.validate_writer_stop_observation(
            normalized_writer_stop.get("writer_stop_observation"),
            expected_live_runtime_identity=normalized_writer_stop[
                "old_gateway_runtime_identity"
            ],
            expected_live_sidecar_identity=sidecar,
        )
    except cutover_guard.CutoverGuardError as exc:
        raise EvidenceError(exc.code, exc.detail) from exc
    if normalized_observation != normalized_writer_stop["writer_stop_observation"]:
        raise EvidenceError("feishu_ingress_hold_gate_writer_stop_observation_invalid")
    return {
        "schema_version": feishu_ingress_hold.GATE_VALIDATION_SCHEMA_VERSION,
        "ok": True,
        "plan_sha256": normalized_plan_sha256,
        "approval_receipt_sha256": normalized_approval_sha256,
        "cutover_binding_sha256": normalized_cutover_sha256,
        "writer_stop_receipt_sha256": normalized_writer_stop_sha256,
        "cutover_lease_fingerprint": normalized_writer_stop["lease_fingerprint"],
        "old_gateway_runtime_identity_sha256": normalized_writer_stop[
            "old_gateway_runtime_identity_sha256"
        ],
        "gateway_writer_state": "stopped",
    }


def _cutover_gate_artifact_sha256(
    artifact_sha256: Mapping[str, str], name: str
) -> str:
    return _sha256_digest(
        artifact_sha256.get(name), f"production_cutover.{name}.raw_sha256"
    )


def _validate_cutover_prior_step(
    *,
    requested_step: str,
    live_identity_sha256: str | None,
    prior_step_receipt: Mapping[str, Any] | None,
    expected_live_identity_sha256: str,
) -> None:
    if requested_step == "plan":
        if live_identity_sha256 is not None or prior_step_receipt is not None:
            raise EvidenceError("production_cutover_plan_live_input_forbidden")
        return
    live_sha256 = _sha256_digest(
        live_identity_sha256, "production_cutover.live_identity_sha256"
    )
    if requested_step == CUTOVER_STEP_NAMES[0]:
        if prior_step_receipt is not None or live_sha256 != expected_live_identity_sha256:
            raise EvidenceError("production_cutover_initial_live_identity_mismatch")
        return
    step_index = CUTOVER_STEP_NAMES.index(requested_step)
    expected_prior_step = CUTOVER_STEP_NAMES[step_index - 1]
    prior = _mapping(
        prior_step_receipt, "production_cutover.prior_step_receipt"
    )
    if set(prior) != {"schema_version", "plan_sha256", "index", "step", "result"}:
        raise EvidenceError("production_cutover_prior_step_shape_invalid")
    result = _mapping(prior.get("result"), "production_cutover.prior_step_result")
    _sha256_digest(
        prior.get("plan_sha256"), "production_cutover.prior_step.plan_sha256"
    )
    if (
        prior.get("schema_version")
        != "pnc_rca_production_cutover_step_result_v1"
        or prior.get("index") != step_index
        or prior.get("step") != expected_prior_step
        or set(result)
        != {
            "schema_version",
            "step",
            "before_identity_sha256",
            "after_identity_sha256",
            "commands",
            "old_runtime_retained",
            "snapshot",
            "services",
            "evidence",
            "started_labels",
        }
        or result.get("schema_version")
        != "pnc_rca_production_cutover_step_result_v1"
        or result.get("step") != expected_prior_step
        or result.get("old_runtime_retained") is not True
        or result.get("after_identity_sha256") != live_sha256
    ):
        raise EvidenceError("production_cutover_prior_step_binding_invalid")
    _sha256_digest(
        result.get("before_identity_sha256"),
        "production_cutover.prior_step.before_identity_sha256",
    )
    evidence = result.get("evidence")
    if requested_step == "install_feishu_sidecar":
        evidence_map = _mapping(evidence, "production_cutover.writer_stop_evidence")
        if (
            evidence_map.get("schema_version") != "pnc_rca_writer_stop_evidence_v1"
            or evidence_map.get("writer_labels")
            != [*CUTOVER_GATEWAY_AUX_START_ORDER, *CUTOVER_RESIDENT_START_ORDER]
        ):
            raise EvidenceError("production_cutover_writer_stop_evidence_invalid")
        _sha256_digest(
            evidence_map.get("receipt_sha256"),
            "production_cutover.writer_stop_evidence.receipt_sha256",
        )
    if requested_step == "verify_gateway_aux" and result.get("started_labels") != list(
        CUTOVER_GATEWAY_AUX_START_ORDER
    ):
        raise EvidenceError("production_cutover_gateway_start_order_invalid")


def validate_rca_cutover_execution_authorization(
    *,
    artifacts: Mapping[str, Mapping[str, Any]],
    artifact_sha256: Mapping[str, str],
    cutover_lease_fingerprint: str,
    cutover_authorization: Mapping[str, Any],
    requested_step: str,
    live_identity_sha256: str | None,
    prior_step_receipt: Mapping[str, Any] | None,
) -> Mapping[str, Any]:
    """Pure fail-closed authorization for one production cutover step."""
    artifact_names = {
        "release_prepare_manifest",
        "approval_receipt",
        "writer_stop_receipt",
        "feishu_hold_plan",
        "feishu_hold_approval_receipt",
        "feishu_hold_cutover_binding",
        "feishu_hold_receipt",
        "env_stage_receipt",
        "runtime_stage_manifest",
        "workspace_runtime_manifest",
        "cutover_authorization_receipt",
    }
    if set(artifacts) != artifact_names or set(artifact_sha256) != artifact_names:
        raise EvidenceError("production_cutover_artifact_set_invalid")
    if requested_step not in {"plan", *CUTOVER_STEP_NAMES}:
        raise EvidenceError("production_cutover_requested_step_invalid")
    bodies = {
        name: _mapping(artifacts.get(name), f"production_cutover.{name}")
        for name in sorted(artifact_names)
    }
    hashes = {
        name: _cutover_gate_artifact_sha256(artifact_sha256, name)
        for name in sorted(artifact_names)
    }
    lease_fingerprint = _sha256_digest(
        cutover_lease_fingerprint, "production_cutover.lease_fingerprint"
    )
    prepare = bodies["release_prepare_manifest"]
    approval = bodies["approval_receipt"]
    writer = bodies["writer_stop_receipt"]
    hold_plan = bodies["feishu_hold_plan"]
    hold_approval = bodies["feishu_hold_approval_receipt"]
    hold_cutover = bodies["feishu_hold_cutover_binding"]
    hold = bodies["feishu_hold_receipt"]
    env_stage = bodies["env_stage_receipt"]
    runtime = bodies["runtime_stage_manifest"]
    workspace = bodies["workspace_runtime_manifest"]
    release_id = _required_text(
        prepare.get("release_id"), "production_cutover.release_id"
    )
    if (
        prepare.get("schema_version")
        != RELEASE_PREPARE_FINAL_MANIFEST_SCHEMA_VERSION
        or prepare.get("complete") is not True
        or prepare.get("plan_only") is not True
        or approval.get("schema_version") != RELEASE_APPROVAL_RECEIPT_SCHEMA_VERSION
        or approval.get("release_id") != release_id
        or prepare.get("approval_receipt_sha256") != hashes["approval_receipt"]
    ):
        raise EvidenceError("production_cutover_release_approval_invalid")
    release_bom_sha256 = _sha256_digest(
        prepare.get("release_bom_sha256"), "production_cutover.release_bom_sha256"
    )
    if hashes["approval_receipt"] == hashes["feishu_hold_approval_receipt"]:
        raise EvidenceError("production_cutover_approval_domains_not_separated")
    if (
        writer.get("schema_version")
        != cutover_guard.WRITER_STOP_RECEIPT_SCHEMA_VERSION
        or writer.get("release_id") != release_id
        or writer.get("lease_fingerprint") != lease_fingerprint
        or writer.get("release_prepare_manifest_sha256")
        != hashes["release_prepare_manifest"]
        or writer.get("approval_receipt_sha256")
        != hashes["feishu_hold_approval_receipt"]
    ):
        raise EvidenceError("production_cutover_writer_stop_invalid")
    writer_observation = _mapping(
        writer.get("writer_stop_observation"),
        "production_cutover.writer_stop_observation",
    )
    if (
        _mapping(
            writer_observation.get("launchd"),
            "production_cutover.writer_stop.launchd",
        ).get("pid")
        is not None
        or _mapping(
            writer_observation.get("process_census"),
            "production_cutover.writer_stop.process_census",
        ).get("matching_processes")
        != []
    ):
        raise EvidenceError("production_cutover_writer_not_stopped")
    precutover_services = _mapping(
        writer.get("precutover_service_state"),
        "production_cutover.precutover_service_state",
    )
    try:
        normalized_precutover_services = (
            cutover_guard._normalize_precutover_service_state(
                precutover_services,
                old_runtime=_mapping(
                    writer.get("old_gateway_runtime_identity"),
                    "production_cutover.old_gateway_runtime_identity",
                ),
            )
        )
    except cutover_guard.CutoverGuardError as exc:
        raise EvidenceError(exc.code, exc.detail) from exc
    if writer.get("precutover_service_state_sha256") != _sha256_json(
        normalized_precutover_services
    ):
        raise EvidenceError("production_cutover_precutover_service_state_invalid")
    if (
        hold_plan.get("schema_version") != feishu_ingress_hold.PLAN_SCHEMA_VERSION
        or hold_plan.get("production_effects_executed") is not False
        or hold_approval.get("schema_version")
        != feishu_ingress_hold.APPROVAL_SCHEMA_VERSION
        or hold_approval.get("hold_id") != hold_plan.get("hold_id")
        or hold_approval.get("plan_sha256") != hashes["feishu_hold_plan"]
        or hold_cutover.get("schema_version")
        != feishu_ingress_hold.CUTOVER_BINDING_SCHEMA_VERSION
        or hold_cutover.get("release_id") != release_id
        or hold_cutover.get("plan_sha256") != hashes["feishu_hold_plan"]
        or hold_cutover.get("writer_stop_receipt_sha256")
        != hashes["writer_stop_receipt"]
        or hold_cutover.get("cutover_lease_fingerprint") != lease_fingerprint
        or hold_cutover.get("release_prepare_manifest_sha256")
        != hashes["release_prepare_manifest"]
        or hold_cutover.get("release_approval_receipt_sha256")
        != hashes["feishu_hold_approval_receipt"]
        or hold.get("schema_version")
        != feishu_ingress_hold.APPLY_RECEIPT_SCHEMA_VERSION
        or hold.get("ok") is not True
        or hold.get("plan_sha256") != hashes["feishu_hold_plan"]
        or _mapping(hold.get("approval"), "production_cutover.hold.approval").get(
            "receipt_sha256"
        )
        != hashes["feishu_hold_approval_receipt"]
    ):
        raise EvidenceError("production_cutover_feishu_hold_chain_invalid")
    env_bindings = _mapping(
        env_stage.get("bindings"), "production_cutover.env_stage.bindings"
    )
    env_policy = _mapping(
        env_stage.get("policy"), "production_cutover.env_stage.policy"
    )
    capacity = _mapping(
        env_policy.get("capacity_admission"),
        "production_cutover.env_stage.capacity_admission",
    )
    stores_policy = _mapping(
        env_policy.get("stores"), "production_cutover.env_stage.stores"
    )
    bootstrap_binding = _mapping(
        env_bindings.get("bootstrap_authorization"),
        "production_cutover.env_stage.bootstrap_authorization",
    )
    candidate_env = _mapping(
        env_bindings.get("candidate_env"),
        "production_cutover.env_stage.candidate_env",
    )
    side_effect = _mapping(
        env_stage.get("side_effect_contract"),
        "production_cutover.env_stage.side_effect_contract",
    )
    active_release_binding_path = _required_text(
        side_effect.get("canonical_active_release_binding"),
        "production_cutover.active_release_binding_path",
    )
    active_path = Path(active_release_binding_path)
    approved_state_root = Path(
        _required_text(
            stores_policy.get("runtime_state_root"),
            "production_cutover.env_stage.runtime_state_root",
        )
    )
    if (
        env_stage.get("schema_version")
        != prod_bootstrap.ACTIVE_RELEASE_BINDING_SCHEMA_VERSION
        or env_stage.get("release_id") != release_id
        or env_stage.get("complete") is not True
        or env_stage.get("live_write_performed") is not False
        or _mapping(
            env_bindings.get("release_prepare_manifest"),
            "production_cutover.env_stage.release_prepare",
        ).get("sha256")
        != hashes["release_prepare_manifest"]
        or _mapping(
            env_bindings.get("release_approval"),
            "production_cutover.env_stage.release_approval",
        ).get("sha256")
        != hashes["approval_receipt"]
        or env_bindings.get("release_bom_sha256") != release_bom_sha256
        or capacity.get("capacity_mode") != "bootstrap"
        or capacity.get("release_bom_sha256") != release_bom_sha256
        or capacity.get("release_approval_id") != release_id
        or capacity.get("approval_evidence_sha256") != hashes["approval_receipt"]
        or bootstrap_binding.get("sha256")
        != capacity.get("bootstrap_authorization_sha256")
        or bootstrap_binding.get("receipt_fingerprint")
        != capacity.get("bootstrap_authorization_fingerprint")
        or not active_path.is_absolute()
        or not approved_state_root.is_absolute()
        or approved_state_root != AUXILIARY_RUNTIME_STATE_ROOT
        or stores_policy.get("control_database_shared") is not True
        or stores_policy.get("health_paths_explicit") is not True
        or active_path
        != approved_state_root / prod_bootstrap.ACTIVE_RELEASE_BINDING_NAME
    ):
        raise EvidenceError("production_cutover_env_stage_binding_invalid")
    candidate_env_sha256 = _sha256_digest(
        candidate_env.get("sha256"), "production_cutover.candidate_env_sha256"
    )
    runtime_content_sha256 = _sha256_digest(
        runtime.get("content_sha256"), "production_cutover.runtime_content_sha256"
    )
    workspace_runtime_sha256 = _sha256_digest(
        workspace.get("closure_sha256"),
        "production_cutover.workspace_runtime_sha256",
    )
    candidate_plists = _mapping(
        _mapping(
            runtime.get("future_canonical_projection"),
            "production_cutover.future_runtime",
        ).get("candidate_plist_sha256"),
        "production_cutover.candidate_plists",
    )
    expected_plists = {
        f"{label}.candidate.plist" for label in CUTOVER_RESIDENT_START_ORDER
    } | {
        "ai.hermes.gateway.candidate.plist",
        "local.pnc.completion-notice-relay.candidate.plist",
        "local.pnc.vm-task-sync.candidate.plist",
    }
    if set(candidate_plists) != expected_plists:
        raise EvidenceError("production_cutover_candidate_plist_set_invalid")
    for name, digest in candidate_plists.items():
        _sha256_digest(digest, f"production_cutover.candidate_plists.{name}")
    feishu_sidecar_sha256 = _sha256_digest(
        _mapping(
            hold.get("future_install"), "production_cutover.feishu_future_install"
        ).get("staged_sha256"),
        "production_cutover.feishu_sidecar_sha256",
    )
    authorization = _mapping(
        cutover_authorization, "production_cutover.authorization"
    )
    if set(authorization) != {
        "release_id",
        "receipt_sha256",
        "bindings",
        "expires_at",
        "nonce",
        "machine_identity_sha256",
    } or (
        authorization.get("release_id") != release_id
        or authorization.get("receipt_sha256")
        != hashes["cutover_authorization_receipt"]
    ):
        raise EvidenceError("production_cutover_authorization_invalid")
    auth_bindings = _mapping(
        authorization.get("bindings"), "production_cutover.authorization.bindings"
    )
    expected_authorization_bindings = {
        "release_prepare_manifest_sha256": hashes["release_prepare_manifest"],
        "approval_receipt_sha256": hashes["approval_receipt"],
        "release_bom_sha256": release_bom_sha256,
        "cutover_lease_fingerprint": lease_fingerprint,
        "writer_stop_receipt_sha256": hashes["writer_stop_receipt"],
        "feishu_hold_plan_sha256": hashes["feishu_hold_plan"],
        "feishu_hold_approval_receipt_sha256": hashes[
            "feishu_hold_approval_receipt"
        ],
        "feishu_hold_cutover_binding_sha256": hashes[
            "feishu_hold_cutover_binding"
        ],
        "feishu_hold_receipt_sha256": hashes["feishu_hold_receipt"],
        "env_stage_receipt_sha256": hashes["env_stage_receipt"],
        "candidate_env_sha256": candidate_env_sha256,
        "runtime_stage_manifest_sha256": hashes["runtime_stage_manifest"],
        "workspace_runtime_manifest_sha256": hashes[
            "workspace_runtime_manifest"
        ],
        "expected_live_identity_sha256": _sha256_digest(
            auth_bindings.get("expected_live_identity_sha256"),
            "production_cutover.expected_live_identity_sha256",
        ),
    }
    if dict(auth_bindings) != expected_authorization_bindings:
        raise EvidenceError("production_cutover_authorization_binding_mismatch")
    authorization_expires_at = _timestamp(
        authorization.get("expires_at"), "production_cutover.authorization_expires_at"
    )
    if datetime.now(timezone.utc) >= authorization_expires_at:
        raise EvidenceError("production_cutover_authorization_expired")
    _validate_cutover_prior_step(
        requested_step=requested_step,
        live_identity_sha256=live_identity_sha256,
        prior_step_receipt=prior_step_receipt,
        expected_live_identity_sha256=expected_authorization_bindings[
            "expected_live_identity_sha256"
        ],
    )
    activation_contract_sha256 = _sha256_json({
        "release_id": release_id,
        "bootstrap_epoch_id": capacity.get("bootstrap_epoch_id"),
        "release_bom_sha256": release_bom_sha256,
        "activation_required": _mapping(
            env_policy.get("kafka"), "production_cutover.env_stage.kafka"
        ).get("activation_required"),
    })
    target_live_identity_sha256 = _sha256_json({
        "runtime_content_sha256": runtime_content_sha256,
        "workspace_runtime_sha256": workspace_runtime_sha256,
        "candidate_env_sha256": candidate_env_sha256,
        "active_release_binding_sha256": hashes["env_stage_receipt"],
        "feishu_sidecar_sha256": feishu_sidecar_sha256,
        "candidate_plist_set_sha256": _sha256_json(dict(sorted(candidate_plists.items()))),
        "activation_contract_sha256": activation_contract_sha256,
    })
    return {
        "schema_version": CUTOVER_GATE_VALIDATION_SCHEMA_VERSION,
        "ok": True,
        "release_id": release_id,
        "release_prepare_manifest_sha256": hashes["release_prepare_manifest"],
        "release_approval_receipt_sha256": hashes["approval_receipt"],
        "release_bom_sha256": release_bom_sha256,
        "cutover_lease_fingerprint": lease_fingerprint,
        "writer_stop_receipt_sha256": hashes["writer_stop_receipt"],
        "feishu_hold_plan_sha256": hashes["feishu_hold_plan"],
        "feishu_hold_approval_receipt_sha256": hashes[
            "feishu_hold_approval_receipt"
        ],
        "feishu_hold_cutover_binding_sha256": hashes[
            "feishu_hold_cutover_binding"
        ],
        "feishu_hold_receipt_sha256": hashes["feishu_hold_receipt"],
        "env_stage_receipt_sha256": hashes["env_stage_receipt"],
        "active_release_binding_path": active_release_binding_path,
        "runtime_stage_manifest_sha256": hashes["runtime_stage_manifest"],
        "workspace_runtime_manifest_sha256": hashes[
            "workspace_runtime_manifest"
        ],
        "cutover_authorization_receipt_sha256": hashes[
            "cutover_authorization_receipt"
        ],
        "expected_live_identity_sha256": expected_authorization_bindings[
            "expected_live_identity_sha256"
        ],
        "rollback_live_identity_sha256": expected_authorization_bindings[
            "expected_live_identity_sha256"
        ],
        "target_live_identity_sha256": target_live_identity_sha256,
        "runtime_content_sha256": runtime_content_sha256,
        "workspace_runtime_sha256": workspace_runtime_sha256,
        "candidate_env_sha256": candidate_env_sha256,
        "feishu_sidecar_sha256": feishu_sidecar_sha256,
        "candidate_plist_set_sha256": _sha256_json(
            dict(sorted(candidate_plists.items()))
        ),
        "activation_contract_sha256": activation_contract_sha256,
        "gateway_aux_start_order": list(CUTOVER_GATEWAY_AUX_START_ORDER),
        "resident_start_order": list(CUTOVER_RESIDENT_START_ORDER),
        "allowed_next_step": requested_step,
        "authorization_expires_at": authorization_expires_at.isoformat(),
    }


def _local_git_provenance(
    repo_root: Path,
    *,
    component: str,
    entrypoint_relative: str | None = None,
) -> dict[str, Any]:
    if component == "workspace":
        if entrypoint_relative is not None:
            raise ValueError("workspace execution closure has fixed paths")
        return _workspace_git_provenance(repo_root)
    root = repo_root.expanduser().resolve()
    if not root.is_dir():
        raise EvidenceError(f"build_manifest_{component}_repo_missing")
    try:
        git_root = Path(_git_output(root, ["rev-parse", "--show-toplevel"])).resolve()
        commit = _commit_sha(
            _git_output(root, ["rev-parse", "--verify", "HEAD"]),
            f"build_provenance.{component}.commit",
        )
        status = _git_output(
            root,
            ["status", "--porcelain=v1", "--untracked-files=all"],
        )
        commit_after_status = _commit_sha(
            _git_output(root, ["rev-parse", "--verify", "HEAD"]),
            f"build_provenance.{component}.commit_after_status",
        )
    except EvidenceError as exc:
        raise EvidenceError(f"build_manifest_{component}_git_unavailable") from exc
    if git_root != root:
        raise EvidenceError(f"build_manifest_{component}_repo_root_mismatch")
    if commit_after_status != commit:
        raise EvidenceError(f"build_manifest_{component}_repo_unstable")
    if status:
        raise EvidenceError(f"build_manifest_{component}_tree_dirty")
    result = {
        "source": "local_git",
        "repo_root": str(root),
        "commit": commit,
        "tree_clean": True,
        "status_sha256": EMPTY_GIT_STATUS_SHA256,
        "stable": True,
    }
    if entrypoint_relative:
        entrypoint = root / entrypoint_relative
        if entrypoint.is_symlink() or not entrypoint.is_file():
            raise EvidenceError(f"build_manifest_{component}_entrypoint_missing")
        try:
            tracked = _git_output(
                root,
                ["ls-files", "--stage", "--", entrypoint_relative],
            )
            match = re.fullmatch(
                r"(100644|100755) ([0-9a-f]{40,64}) 0\t(.+)",
                tracked,
            )
            raw, _info = _stable_regular_file_observation(
                entrypoint,
                artifact=f"build_manifest_{component}_entrypoint",
            )
            committed = _git_output_bytes(
                root,
                ["cat-file", "blob", f"{commit}:{entrypoint_relative}"],
            )
            tree = _git_object_id(
                _git_output(root, ["rev-parse", f"{commit}^{{tree}}"]),
                f"build_provenance.{component}.tree",
            )
        except (EvidenceError, OSError) as exc:
            raise EvidenceError(
                f"build_manifest_{component}_entrypoint_unavailable"
            ) from exc
        if (
            match is None
            or match.group(3) != entrypoint_relative
            or raw != committed
        ):
            raise EvidenceError(f"build_manifest_{component}_entrypoint_untracked")
        result.update({
            "tree": tree,
            "entrypoint_path": str(entrypoint),
            "entrypoint_sha256": hashlib.sha256(raw).hexdigest(),
            "entrypoint_committed_sha256": hashlib.sha256(committed).hexdigest(),
            "entrypoint_git_mode": match.group(1),
            "entrypoint_blob": _git_object_id(
                match.group(2),
                f"build_provenance.{component}.entrypoint_blob",
            ),
        })
    return result


def _vm_git_probe_script(vm_repo_root: str, entrypoint_relative: str) -> str:
    root_literal = json.dumps(str(PurePosixPath(vm_repo_root)))
    entrypoint_literal = json.dumps(str(PurePosixPath(entrypoint_relative)))
    return f'''import hashlib
import json
from pathlib import Path
import subprocess

REPO_ROOT = {root_literal}
ENTRYPOINT_RELATIVE = {entrypoint_literal}


def git(*arguments):
    process = subprocess.run(
        ["git", "-c", "core.fileMode=false", "-C", REPO_ROOT, *arguments],
        check=False,
        capture_output=True,
        text=True,
        timeout=5,
    )
    if process.returncode != 0:
        raise SystemExit(2)
    return process.stdout.rstrip("\\n")


def git_bytes(*arguments):
    process = subprocess.run(
        ["git", "-c", "core.fileMode=false", "-C", REPO_ROOT, *arguments],
        check=False,
        capture_output=True,
        timeout=5,
    )
    if process.returncode != 0:
        raise SystemExit(2)
    return process.stdout


repo_root = git("rev-parse", "--show-toplevel").strip()
commit = git("rev-parse", "--verify", "HEAD").strip()
tree = git("rev-parse", commit + "^{{tree}}").strip()
status = git("status", "--porcelain=v1", "--untracked-files=all")
tracked_entrypoint = git("ls-files", "--stage", "--", ENTRYPOINT_RELATIVE).strip()
entrypoint = Path(REPO_ROOT) / ENTRYPOINT_RELATIVE
parts = tracked_entrypoint.split(" ", 2)
if len(parts) != 3 or "\\t" not in parts[2]:
    raise SystemExit(3)
git_mode, entrypoint_blob = parts[0], parts[1]
stage, tracked_path = parts[2].split("\\t", 1)
if (
    git_mode not in {{"100644", "100755"}}
    or stage != "0"
    or tracked_path != ENTRYPOINT_RELATIVE
    or entrypoint.is_symlink()
    or not entrypoint.is_file()
):
    raise SystemExit(3)
before = entrypoint.stat()
entrypoint_raw = entrypoint.read_bytes()
after = entrypoint.stat()
committed_raw = git_bytes("cat-file", "blob", commit + ":" + ENTRYPOINT_RELATIVE)
entrypoint_sha256 = hashlib.sha256(entrypoint_raw).hexdigest()
entrypoint_committed_sha256 = hashlib.sha256(committed_raw).hexdigest()
commit_after_status = git("rev-parse", "--verify", "HEAD").strip()
tree_after_status = git("rev-parse", commit_after_status + "^{{tree}}").strip()
final = entrypoint.stat()
final_raw = entrypoint.read_bytes()
if (
    (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
    != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    or (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    != (final.st_dev, final.st_ino, final.st_size, final.st_mtime_ns)
    or entrypoint_raw != final_raw
):
    raise SystemExit(3)
print(json.dumps({{
    "schema_version": "{VM_GIT_PROVENANCE_SCHEMA_VERSION}",
    "source": "ssh-mini-agent",
    "repo_root": repo_root,
    "commit": commit,
    "tree": tree,
    "tree_clean": status == "",
    "status_sha256": hashlib.sha256(status.encode("utf-8")).hexdigest(),
    "stable": commit_after_status == commit and tree_after_status == tree,
    "entrypoint_path": str(entrypoint),
    "entrypoint_sha256": entrypoint_sha256,
    "entrypoint_committed_sha256": entrypoint_committed_sha256,
    "entrypoint_git_mode": git_mode,
    "entrypoint_blob": entrypoint_blob,
}}, sort_keys=True))
'''


def _vm_git_provenance(
    vm_repo_root: str,
    *,
    component: str = "vm",
    runner: Any = subprocess.run,
) -> dict[str, Any]:
    if component not in {"vm", "vm_worker"}:
        raise ValueError("unsupported VM provenance component")
    entrypoint_contract = VM_COMPONENT_ENTRYPOINTS[component]
    try:
        result = runner(
            [str(DEFAULT_SSH_MINI_AGENT), "run_py_json"],
            input=_vm_git_probe_script(
                vm_repo_root,
                str(entrypoint_contract["relative"]),
            ),
            check=False,
            capture_output=True,
            text=True,
            timeout=VM_PROVENANCE_TIMEOUT_SECONDS,
        )
    except subprocess.TimeoutExpired as exc:
        raise EvidenceError(f"build_manifest_{component}_probe_timeout") from exc
    except (OSError, subprocess.SubprocessError) as exc:
        raise EvidenceError(f"build_manifest_{component}_probe_unavailable") from exc
    if result.returncode != 0:
        raise EvidenceError(f"build_manifest_{component}_probe_unavailable")
    raw = str(result.stdout or "")
    if len(raw.encode("utf-8")) > 16 * 1024:
        raise EvidenceError(f"build_manifest_{component}_probe_invalid")
    try:
        payload = _strict_json_loads(raw, artifact=f"build_manifest_{component}_probe")
        evidence = _mapping(payload, f"build_manifest.{component}_provenance")
        _require_schema(
            evidence,
            VM_GIT_PROVENANCE_SCHEMA_VERSION,
            f"build_manifest_{component}_probe",
        )
        source = _required_text(
            evidence.get("source"), f"build_manifest.{component}_provenance.source"
        )
        repo_root = _required_text(
            evidence.get("repo_root"),
            f"build_manifest.{component}_provenance.repo_root",
        )
        commit = _commit_sha(
            evidence.get("commit"),
            f"build_manifest.{component}_provenance.commit",
        )
        tree = _git_object_id(
            evidence.get("tree"),
            f"build_manifest.{component}_provenance.tree",
        )
        status_sha256 = _sha256_digest(
            evidence.get("status_sha256"),
            f"build_manifest.{component}_provenance.status_sha256",
        )
        entrypoint_path = _required_text(
            evidence.get("entrypoint_path"),
            f"build_manifest.{component}_provenance.entrypoint_path",
        )
        entrypoint_sha256 = _sha256_digest(
            evidence.get("entrypoint_sha256"),
            f"build_manifest.{component}_provenance.entrypoint_sha256",
        )
        entrypoint_committed_sha256 = _sha256_digest(
            evidence.get("entrypoint_committed_sha256"),
            (
                f"build_manifest.{component}_provenance."
                "entrypoint_committed_sha256"
            ),
        )
        entrypoint_blob = _git_object_id(
            evidence.get("entrypoint_blob"),
            f"build_manifest.{component}_provenance.entrypoint_blob",
        )
        entrypoint_git_mode = _required_text(
            evidence.get("entrypoint_git_mode"),
            f"build_manifest.{component}_provenance.entrypoint_git_mode",
        )
    except EvidenceError as exc:
        raise EvidenceError(f"build_manifest_{component}_probe_invalid") from exc
    if source != "ssh-mini-agent":
        raise EvidenceError(f"build_manifest_{component}_probe_invalid")
    if repo_root != str(PurePosixPath(vm_repo_root)):
        raise EvidenceError(f"build_manifest_{component}_repo_root_mismatch")
    expected_entrypoint_path = str(
        PurePosixPath(vm_repo_root) / str(entrypoint_contract["relative"])
    )
    if entrypoint_path != expected_entrypoint_path:
        raise EvidenceError(f"build_manifest_{component}_entrypoint_path_mismatch")
    if evidence.get("stable") is not True:
        raise EvidenceError(f"build_manifest_{component}_repo_unstable")
    if evidence.get("tree_clean") is not True:
        raise EvidenceError(f"build_manifest_{component}_tree_dirty")
    if status_sha256 != EMPTY_GIT_STATUS_SHA256:
        raise EvidenceError(f"build_manifest_{component}_tree_dirty")
    if (
        entrypoint_git_mode not in {"100644", "100755"}
        or entrypoint_committed_sha256 != entrypoint_sha256
    ):
        raise EvidenceError(f"build_manifest_{component}_entrypoint_hash_mismatch")
    return {
        "source": source,
        "repo_root": repo_root,
        "commit": commit,
        "tree": tree,
        "tree_clean": True,
        "status_sha256": status_sha256,
        "stable": True,
        "entrypoint_path": entrypoint_path,
        "entrypoint_sha256": entrypoint_sha256,
        "entrypoint_committed_sha256": entrypoint_committed_sha256,
        "entrypoint_git_mode": entrypoint_git_mode,
        "entrypoint_blob": entrypoint_blob,
    }


def verify_live_build_provenance(
    settings: ReleaseGateSettings,
    *,
    runner: Any = subprocess.run,
) -> dict[str, Any]:
    """Resolve machine-observed Git provenance for every release component."""
    external_dependencies = _external_release_dependency_provenance()
    host = _local_git_provenance(settings.host_repo_root, component="host")
    workspace = _local_git_provenance(
        settings.workspace_repo_root,
        component="workspace",
    )
    vm = _vm_git_provenance(settings.vm_repo_root, component="vm", runner=runner)
    vm_worker = _vm_git_provenance(
        settings.vm_worker_repo_root,
        component="vm_worker",
        runner=runner,
    )
    if _external_release_dependency_provenance() != external_dependencies:
        raise EvidenceError("build_manifest_external_dependencies_unstable")
    return {
        "schema_version": BUILD_PROVENANCE_SCHEMA_VERSION,
        "host": host,
        "workspace": workspace,
        "vm": vm,
        "vm_worker": vm_worker,
        "external_dependencies": external_dependencies,
    }


def _remote_reader_live_probe_script(vm_repo_root: str) -> str:
    return f"""
import hashlib
import importlib
import json
from pathlib import Path
import subprocess
import sys

REPO_ROOT = Path({vm_repo_root!r})
WHEEL = REPO_ROOT / {REMOTE_READER_WHEEL_RELATIVE!r}
MANIFEST = REPO_ROOT / {REMOTE_READER_MANIFEST_RELATIVE!r}
ADAPTER = REPO_ROOT / {REMOTE_READER_ADAPTER_RELATIVE!r}

def sha256_file(path):
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

if not REPO_ROOT.is_absolute():
    raise RuntimeError("remote_reader_repo_not_absolute")
for path in (WHEEL, MANIFEST, ADAPTER):
    if path.is_symlink() or not path.is_file():
        raise RuntimeError("remote_reader_fixed_artifact_missing")
sys.path[:0] = [str(WHEEL), str(REPO_ROOT)]
from api.g1q3_rca.remote_reader_adapter import remote_reader_dependency_doctor
doctor = remote_reader_dependency_doctor(check_runtime_environment=True)
reader_module = importlib.import_module("pdcl_pyclip.reader")
git_head = subprocess.run(
    ["git", "-C", str(REPO_ROOT), "rev-parse", "HEAD"],
    check=True,
    capture_output=True,
    text=True,
).stdout.strip()
git_status = subprocess.run(
    ["git", "-C", str(REPO_ROOT), "status", "--porcelain=v1", "--untracked-files=all"],
    check=True,
    capture_output=True,
    text=True,
).stdout
result = {{
    "schema_version": {REMOTE_READER_LIVE_PROBE_SCHEMA_VERSION!r},
    "repo_root": str(REPO_ROOT),
    "git_commit": git_head,
    "git_status_sha256": hashlib.sha256(git_status.encode("utf-8")).hexdigest(),
    "python_executable": str(Path(sys.executable).resolve(strict=True)),
    "module_path": str(getattr(reader_module, "__file__", "")),
    "wheel_path": str(WHEEL),
    "manifest_path": str(MANIFEST),
    "adapter_path": str(ADAPTER),
    "wheel_sha256": sha256_file(WHEEL),
    "manifest_sha256": sha256_file(MANIFEST),
    "adapter_sha256": sha256_file(ADAPTER),
    "manifest": json.loads(MANIFEST.read_text(encoding="utf-8")),
    "doctor": doctor,
}}
print(json.dumps(result, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False))
""".strip()


def verify_live_remote_reader(
    settings: ReleaseGateSettings,
    *,
    runner: Any = subprocess.run,
) -> dict[str, Any]:
    """Probe the fixed vendored reader from the live VM repository."""
    wrapper = Path(DEFAULT_SSH_MINI_AGENT)
    if not wrapper.is_absolute():
        raise EvidenceError("remote_reader_live_probe_wrapper_invalid")
    environment = os.environ.copy()
    environment["SSH_MINI_AGENT_TIMEOUT"] = str(REMOTE_READER_PROBE_TIMEOUT_SECONDS)
    try:
        proc = runner(
            [str(wrapper), "run_py_json"],
            input=_remote_reader_live_probe_script(settings.vm_repo_root),
            text=True,
            capture_output=True,
            timeout=REMOTE_READER_PROBE_TIMEOUT_SECONDS,
            env=environment,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise EvidenceError("remote_reader_live_probe_timeout") from exc
    except (OSError, subprocess.SubprocessError) as exc:
        raise EvidenceError("remote_reader_live_probe_unavailable") from exc
    if proc.returncode != 0:
        raise EvidenceError("remote_reader_live_probe_failed")
    raw = str(proc.stdout or "")
    if not raw.strip() or len(raw.encode("utf-8")) > MAX_EVIDENCE_BYTES:
        raise EvidenceError("remote_reader_live_probe_invalid")
    value = _strict_json_loads(raw, artifact="remote_reader_live_probe")
    if not isinstance(value, dict):
        raise EvidenceError("remote_reader_live_probe_invalid")
    return value


def _check_remote_reader_live_probe(
    value: Mapping[str, Any],
    *,
    settings: ReleaseGateSettings,
    expected_vm_commit: str,
    health_detail: Mapping[str, Any],
) -> dict[str, Any]:
    probe = _mapping(value, "remote_reader_live_probe")
    _require_schema(
        probe,
        REMOTE_READER_LIVE_PROBE_SCHEMA_VERSION,
        "remote_reader_live_probe",
    )
    repo_root = str(PurePosixPath(settings.vm_repo_root))
    expected_paths = {
        "repo_root": repo_root,
        "wheel_path": str(PurePosixPath(repo_root) / REMOTE_READER_WHEEL_RELATIVE),
        "manifest_path": str(
            PurePosixPath(repo_root) / REMOTE_READER_MANIFEST_RELATIVE
        ),
        "adapter_path": str(PurePosixPath(repo_root) / REMOTE_READER_ADAPTER_RELATIVE),
    }
    if any(probe.get(field) != expected for field, expected in expected_paths.items()):
        raise EvidenceError("remote_reader_live_probe_path_mismatch")
    if probe.get("git_commit") != expected_vm_commit:
        raise EvidenceError("remote_reader_live_probe_commit_mismatch")
    if probe.get("git_status_sha256") != EMPTY_GIT_STATUS_SHA256:
        raise EvidenceError("remote_reader_live_probe_tree_dirty")
    if probe.get("wheel_sha256") != APPROVED_SANITIZED_WHEEL_SHA256:
        raise EvidenceError("remote_reader_live_probe_wheel_mismatch")
    _sha256_digest(
        probe.get("manifest_sha256"), "remote_reader_live_probe.manifest_sha256"
    )
    _sha256_digest(
        probe.get("adapter_sha256"), "remote_reader_live_probe.adapter_sha256"
    )

    manifest = _mapping(probe.get("manifest"), "remote_reader_live_probe.manifest")
    expected_modules = {
        "pdcl_pyclip/reader.py": FIXED_REMOTE_READER_SANITIZED_MODULE_SHA256,
        "pdcl_pyclip/_config.py": FIXED_REMOTE_READER_SANITIZED_CONFIG_SHA256,
        "pdcl_pyclip/_storage.py": FIXED_REMOTE_READER_SANITIZED_STORAGE_SHA256,
        "pdcl_pyclip/writer.py": FIXED_REMOTE_READER_WRITER_SHA256,
    }
    if (
        manifest.get("schema_version") != "g1q3_rca_sanitized_dependency_v1"
        or manifest.get("distribution") != FIXED_REMOTE_ACCESS_CONTRACT["distribution"]
        or manifest.get("version") != FIXED_REMOTE_ACCESS_CONTRACT["required_version"]
        or manifest.get("wheel") != PurePosixPath(REMOTE_READER_WHEEL_RELATIVE).name
        or manifest.get("wheel_sha256") != APPROVED_SANITIZED_WHEEL_SHA256
        or manifest.get("source_commit") != FIXED_REMOTE_READER_SOURCE_COMMIT
        or manifest.get("sanitized_source_commit")
        != FIXED_REMOTE_READER_SANITIZED_SOURCE_COMMIT
        or manifest.get("patch_sha256") != FIXED_REMOTE_READER_PATCH_SHA256
        or manifest.get("module_sha256") != expected_modules
        or manifest.get("runtime_policy")
        != {
            "credentials": "env_only",
            "cache": "pre_mounted_read_only_admission",
            "automatic_mount": False,
            "package_install": False,
            "sudo": False,
            "input_materialization": False,
        }
    ):
        raise EvidenceError("remote_reader_live_probe_manifest_mismatch")
    upstream = _mapping(
        manifest.get("upstream"), "remote_reader_live_probe.manifest.upstream"
    )
    if upstream != {
        "repository": "pdcl/pdcl_pyclip",
        "commit": FIXED_REMOTE_READER_SOURCE_COMMIT,
        "release_wheel_sha256": FIXED_REMOTE_READER_UPSTREAM_WHEEL_SHA256,
    }:
        raise EvidenceError("remote_reader_live_probe_manifest_mismatch")

    doctor = _mapping(probe.get("doctor"), "remote_reader_live_probe.doctor")
    checks = _mapping(doctor.get("checks"), "remote_reader_live_probe.doctor.checks")
    required_checks = {
        "isolated_interpreter",
        "distribution",
        "vendored_wheel",
        "pdcl_pyclip/reader.py",
        "pdcl_pyclip/_config.py",
        "pdcl_pyclip/_storage.py",
        "dependency:mcap",
        "dependency:protobuf",
        "dependency:pdcl-dss",
        "dependency:typer",
        "module_import",
        "class:RemoteClipReader",
        "class:RemoteEventReader",
    }
    if (
        doctor.get("status") != "ready"
        or doctor.get("distribution") != FIXED_REMOTE_ACCESS_CONTRACT["distribution"]
        or doctor.get("required_version")
        != FIXED_REMOTE_ACCESS_CONTRACT["required_version"]
        or doctor.get("actual_version")
        != FIXED_REMOTE_ACCESS_CONTRACT["required_version"]
        or doctor.get("sanitized_policy") != "env_only_pre_mounted_cache_v1"
        or doctor.get("sanitized_patch_commit")
        != FIXED_REMOTE_READER_SANITIZED_SOURCE_COMMIT[:7]
        or doctor.get("sanitized_wheel_sha256") != APPROVED_SANITIZED_WHEEL_SHA256
        or not required_checks.issubset(checks)
        or any(value != "ok" for value in checks.values())
        or doctor.get("blocker_kind") not in {None, ""}
    ):
        raise EvidenceError("remote_reader_live_probe_doctor_failed")
    doctor_runtime = _mapping(
        doctor.get("runtime"), "remote_reader_live_probe.doctor.runtime"
    )
    doctor_runtime_environment = _mapping(
        doctor.get("runtime_environment"),
        "remote_reader_live_probe.doctor.runtime_environment",
    )
    expected_doctor_runtime = {
        "execution_mode": health_detail.get("execution_mode"),
        "dependency_domain": health_detail.get("dependency_domain"),
        "required_python_executable": health_detail.get("required_python_executable"),
        "resolved_required_python_executable": health_detail.get(
            "resolved_required_python_executable"
        ),
        "python_executable": health_detail.get("python_executable"),
        "python_version": health_detail.get("python_version"),
        "reader_import_scope": health_detail.get("reader_import_scope"),
        "timeout_seconds": 120,
    }
    if (
        probe.get("python_executable") != health_detail.get("python_executable")
        or probe.get("module_path") != health_detail.get("module_path")
        or doctor_runtime != expected_doctor_runtime
        or doctor_runtime_environment
        != health_detail.get("runtime_environment")
        or doctor.get("dependency_versions") != health_detail.get("dependency_versions")
    ):
        raise EvidenceError("remote_reader_live_probe_health_mismatch")
    return {
        "repo_root": repo_root,
        "git_commit": expected_vm_commit,
        "python_executable": probe["python_executable"],
        "dependency_domain": doctor_runtime["dependency_domain"],
        "execution_mode": doctor_runtime["execution_mode"],
        "module_path": probe["module_path"],
        "wheel_sha256": APPROVED_SANITIZED_WHEEL_SHA256,
        "manifest_sha256": probe["manifest_sha256"],
        "adapter_sha256": probe["adapter_sha256"],
        "doctor_status": "ready",
        "runtime_environment": dict(doctor_runtime_environment),
        "dependency_versions": dict(doctor.get("dependency_versions") or {}),
    }


def _critical_path(repo_root: Path, relative: Any) -> tuple[str, Path]:
    name = _required_text(relative, "build_manifest.critical_files.path")
    candidate = Path(name)
    if (
        candidate.is_absolute()
        or name != candidate.as_posix()
        or not candidate.parts
        or any(part in {"", ".", ".."} for part in candidate.parts)
    ):
        raise EvidenceError("build_manifest_critical_path_invalid")
    root = repo_root.resolve()
    unresolved = root / candidate
    if unresolved.is_symlink():
        raise EvidenceError("build_manifest_critical_path_symlink")
    path = unresolved.resolve()
    try:
        path.relative_to(root)
    except ValueError as exc:
        raise EvidenceError("build_manifest_critical_path_escape") from exc
    if not path.is_file():
        raise EvidenceError("build_manifest_critical_file_missing")
    return name, path


def _required_critical_files(repo_root: Path) -> set[str]:
    required = set(MINIMUM_CRITICAL_FILES)
    required.update(DELIVERY_CRITICAL_FILES)
    required.update(RCA_RUNTIME_RELATIVE_FILES)
    required.update(GATEWAY_RCA_RUNTIME_RELATIVE_FILES)
    required.update(
        path.name
        for path in repo_root.glob("local.pnc.rca-*.candidate.plist")
        if path.is_file()
    )
    return required


def _verify_dependency_pins(repo_root: Path, declared: Mapping[str, Any]) -> None:
    normalized = {str(key): str(value) for key, value in declared.items()}
    if normalized != EXPECTED_DEPENDENCY_VERSIONS:
        raise EvidenceError("build_manifest_dependency_versions_mismatch")
    try:
        pyproject = tomllib.loads(
            (repo_root / "pyproject.toml").read_text(encoding="utf-8")
        )
        optional = pyproject["project"]["optional-dependencies"]
        kafka_extra = optional["kafka"]
        feishu_extra = optional["feishu"]
    except (OSError, UnicodeError, tomllib.TOMLDecodeError, KeyError, TypeError) as exc:
        raise EvidenceError("build_manifest_dependency_pins_unverified") from exc
    if not isinstance(kafka_extra, list) or not isinstance(feishu_extra, list):
        raise EvidenceError("build_manifest_dependency_pins_unverified")
    if set(kafka_extra) != {
        f"{name}=={version}"
        for name, version in EXPECTED_KAFKA_DEPENDENCY_VERSIONS.items()
    }:
        raise EvidenceError("build_manifest_dependency_pins_mismatch")
    expected_feishu_pins = {
        f"{name}=={version}"
        for name, version in EXPECTED_FEISHU_OUTBOUND_DEPENDENCY_VERSIONS.items()
    }
    if not expected_feishu_pins.issubset(set(feishu_extra)):
        raise EvidenceError("build_manifest_feishu_dependency_pins_mismatch")


def check_runtime_dependencies(
    *,
    version_reader: Any = metadata.version,
    importer: Any = importlib.import_module,
) -> dict[str, Any]:
    """Verify exact versions used by the standalone RCA service interpreter."""
    versions: dict[str, str] = {}
    for distribution, expected in EXPECTED_DEPENDENCY_VERSIONS.items():
        try:
            actual = str(version_reader(distribution)).strip()
        except Exception as exc:
            raise EvidenceError("runtime_dependency_missing", distribution) from exc
        if actual != expected:
            raise EvidenceError("runtime_dependency_version_mismatch", distribution)
        versions[distribution] = actual

    modules: dict[str, str] = {}
    for module_name, required_attributes in EXPECTED_RUNTIME_MODULES.items():
        try:
            module = importer(module_name)
        except Exception as exc:
            raise EvidenceError(
                "runtime_dependency_import_failed", module_name
            ) from exc
        if any(
            not callable(getattr(module, attribute, None))
            for attribute in required_attributes
        ):
            raise EvidenceError("runtime_dependency_api_missing", module_name)
        modules[module_name] = "ok"
    coordinator_module = importer("kafka.coordinator.consumer")
    async_fetch = getattr(
        coordinator_module.ConsumerCoordinator,
        "fetch_committed_offsets_async",
        None,
    )
    if not inspect.iscoroutinefunction(async_fetch):
        raise EvidenceError(
            "runtime_dependency_async_offset_api_missing", "kafka-python"
        )
    return {
        "python_executable": sys.executable,
        "dependency_versions": versions,
        "module_imports": modules,
    }


def _verify_resident_loaded_runtime_projection(
    value: Any,
    *,
    virtual_env: Path,
    expected_sys_executable: str | Path,
    expected_process_executable: str | Path,
    expected_dependencies: Mapping[str, str],
    artifact: str,
) -> tuple[dict[str, Any], str]:
    """Re-hash the exact interpreter and dependency files sealed by residents."""
    code = f"{artifact}_loaded_runtime_invalid"
    snapshot = _mapping(value, f"{artifact}.loaded_runtime")
    if set(snapshot) != {
        "sys_executable",
        "sys_executable_sha256",
        "process_executable",
        "process_executable_sha256",
        "dependencies",
    }:
        raise EvidenceError(code)
    try:
        canonical_venv = virtual_env.expanduser().resolve(strict=True)
        sys_executable = Path(
            _required_text(
                snapshot.get("sys_executable"),
                f"{artifact}.loaded_runtime.sys_executable",
            )
        ).expanduser().resolve(strict=True)
        process_executable = Path(
            _required_text(
                snapshot.get("process_executable"),
                f"{artifact}.loaded_runtime.process_executable",
            )
        ).expanduser().resolve(strict=True)
        expected_sys = Path(expected_sys_executable).expanduser().resolve(strict=True)
        expected_process = (
            Path(expected_process_executable).expanduser().resolve(strict=True)
        )
    except (OSError, RuntimeError, ValueError, EvidenceError) as exc:
        raise EvidenceError(code) from exc
    if (
        not canonical_venv.is_dir()
        or str(sys_executable) != snapshot.get("sys_executable")
        or str(process_executable) != snapshot.get("process_executable")
        or sys_executable != expected_sys
        or process_executable != expected_process
    ):
        raise EvidenceError(code)
    try:
        sys_sha256 = file_sha256(sys_executable)
        process_sha256 = file_sha256(process_executable)
    except OSError as exc:
        raise EvidenceError(f"{artifact}_loaded_runtime_changed") from exc
    if (
        _sha256_digest(
            snapshot.get("sys_executable_sha256"),
            f"{artifact}.loaded_runtime.sys_executable_sha256",
        )
        != sys_sha256
        or _sha256_digest(
            snapshot.get("process_executable_sha256"),
            f"{artifact}.loaded_runtime.process_executable_sha256",
        )
        != process_sha256
    ):
        raise EvidenceError(f"{artifact}_loaded_runtime_changed")

    dependencies = _mapping(
        snapshot.get("dependencies"), f"{artifact}.loaded_runtime.dependencies"
    )
    if set(dependencies) != set(expected_dependencies):
        raise EvidenceError(code)
    normalized_dependencies: dict[str, dict[str, str]] = {}
    for distribution, module_name in sorted(expected_dependencies.items()):
        dependency = _mapping(
            dependencies.get(distribution),
            f"{artifact}.loaded_runtime.dependencies.{distribution}",
        )
        if set(dependency) != {"module", "origin", "sha256", "version"}:
            raise EvidenceError(code)
        if dependency.get("module") != module_name:
            raise EvidenceError(code)
        if dependency.get("version") != EXPECTED_DEPENDENCY_VERSIONS[distribution]:
            raise EvidenceError(f"{artifact}_loaded_dependency_version_mismatch")
        try:
            origin = Path(
                _required_text(
                    dependency.get("origin"),
                    f"{artifact}.loaded_runtime.dependencies.{distribution}.origin",
                )
            ).expanduser().resolve(strict=True)
            origin.relative_to(canonical_venv)
        except (OSError, RuntimeError, ValueError, EvidenceError) as exc:
            raise EvidenceError(
                f"{artifact}_loaded_dependency_origin_mismatch"
            ) from exc
        if str(origin) != dependency.get("origin") or not origin.is_file():
            raise EvidenceError(f"{artifact}_loaded_dependency_origin_mismatch")
        try:
            observed_sha256 = file_sha256(origin)
        except OSError as exc:
            raise EvidenceError(f"{artifact}_loaded_runtime_changed") from exc
        if _sha256_digest(
            dependency.get("sha256"),
            f"{artifact}.loaded_runtime.dependencies.{distribution}.sha256",
        ) != observed_sha256:
            raise EvidenceError(f"{artifact}_loaded_runtime_changed")
        normalized_dependencies[distribution] = {
            "module": module_name,
            "origin": str(origin),
            "sha256": observed_sha256,
            "version": EXPECTED_DEPENDENCY_VERSIONS[distribution],
        }
    normalized = {
        "sys_executable": str(sys_executable),
        "sys_executable_sha256": sys_sha256,
        "process_executable": str(process_executable),
        "process_executable_sha256": process_sha256,
        "dependencies": normalized_dependencies,
    }
    return normalized, _sha256_json(normalized)


def check_candidate_runtime_dependencies(
    repo_root: Path,
    *,
    runner: Any = subprocess.run,
    loaded_runtime_verifier: Any = _verify_resident_loaded_runtime_projection,
    config_environment: Mapping[str, str] | None = None,
) -> dict[str, Any]:
    """Probe all interpreters, scripts, and clean launchd candidate environments."""
    root = repo_root.expanduser().resolve()
    try:
        runtime_file_sha256 = rca_runtime_file_hashes(root)
        runtime_files_sha256 = rca_runtime_files_sha256(root)
    except OSError as exc:
        raise EvidenceError("runtime_candidate_shared_module_missing") from exc
    expected_interpreter = root / ".venv" / "bin" / "python"
    candidates: dict[str, dict[str, Any]] = {}
    forbidden_python_env = {"PYTHONPATH", "PYTHONHOME", "PYTHONUSERBASE"}
    runtime_config_environment: dict[str, str] = {}
    for key, value in (config_environment or {}).items():
        if (
            not isinstance(key, str)
            or not isinstance(value, str)
            or not (
                key.startswith("HERMES_RCA_")
                or key.startswith("HERMES_G1Q3_")
                or key == "G1Q3_GOVERNANCE_DOWNLOAD_ENABLED"
            )
            or "\x00" in key
            or "\x00" in value
        ):
            raise EvidenceError("runtime_candidate_config_environment_invalid")
        runtime_config_environment[key] = value
    for filename, (expected_label, expected_script_name) in CANDIDATE_SERVICES.items():
        plist_path = repo_root / filename
        try:
            raw_plist = plist_path.read_bytes()
            plist = plistlib.loads(raw_plist)
        except (OSError, plistlib.InvalidFileException) as exc:
            raise EvidenceError("runtime_candidate_plist_invalid", filename) from exc
        if not isinstance(plist, dict) or plist.get("Label") != expected_label:
            raise EvidenceError("runtime_candidate_plist_invalid", filename)
        arguments = plist.get("ProgramArguments")
        if (
            not isinstance(arguments, list)
            or len(arguments) != 2
            or not all(isinstance(item, str) and item for item in arguments)
        ):
            raise EvidenceError("runtime_candidate_arguments_invalid", filename)
        interpreter = Path(arguments[0])
        script = Path(arguments[1])
        working_directory = Path(str(plist.get("WorkingDirectory") or ""))
        if not interpreter.is_absolute() or not interpreter.is_file():
            raise EvidenceError("runtime_candidate_interpreter_missing", filename)
        if interpreter != expected_interpreter:
            raise EvidenceError("runtime_candidate_interpreter_mismatch", filename)
        expected_script = root / "scripts" / expected_script_name
        if not script.is_absolute() or not script.is_file():
            raise EvidenceError("runtime_candidate_script_missing", filename)
        if script != expected_script:
            raise EvidenceError("runtime_candidate_script_root_mismatch", filename)
        if not working_directory.is_absolute() or not working_directory.is_dir():
            raise EvidenceError("runtime_candidate_working_directory_missing", filename)
        if working_directory != root:
            raise EvidenceError(
                "runtime_candidate_working_directory_mismatch", filename
            )
        declared_env = plist.get("EnvironmentVariables")
        if not isinstance(declared_env, dict) or any(
            not isinstance(key, str) or not isinstance(value, str)
            for key, value in declared_env.items()
        ):
            raise EvidenceError("runtime_candidate_environment_invalid", filename)
        if forbidden_python_env & declared_env.keys():
            raise EvidenceError("runtime_candidate_python_path_injection", filename)
        if declared_env.get("PYTHONNOUSERSITE") != "1":
            raise EvidenceError(
                "runtime_candidate_python_no_user_site_required",
                filename,
            )
        if declared_env.get("PYTHONDONTWRITEBYTECODE") != "1":
            raise EvidenceError(
                "runtime_candidate_bytecode_write_forbidden",
                filename,
            )
        issue_capture_enabled = (
            str(declared_env.get("HERMES_G1Q3_ISSUE_CAPTURE_ENABLED", ""))
            .strip()
            .lower()
        )
        if issue_capture_enabled not in {"", "0", "false", "no", "off"}:
            raise EvidenceError("runtime_candidate_issue_capture_enabled", filename)
        if str(declared_env.get("HERMES_G1Q3_ISSUE_CAPTURE_ROOT", "")).strip():
            raise EvidenceError(
                "runtime_candidate_issue_capture_root_configured", filename
            )
        candidates[expected_label] = {
            "arguments": list(arguments),
            "interpreter": interpreter,
            "script": script,
            "working_directory": working_directory,
            "environment": {
                str(key): str(value) for key, value in declared_env.items()
            },
            "plist_path": plist_path.resolve(strict=True),
            "plist_sha256": hashlib.sha256(raw_plist).hexdigest(),
        }
    kafka_candidate = candidates["local.pnc.rca-kafka-consumer"]
    interpreter = kafka_candidate["interpreter"]
    working_directory = kafka_candidate["working_directory"]
    clean_env = kafka_candidate["environment"]
    probe = r"""
import hashlib
import importlib
from importlib import metadata
import inspect
import json
import os
from pathlib import Path
import psutil
import sys

try:
    versions = {
        "kafka-python": metadata.version("kafka-python"),
        "python-snappy": metadata.version("python-snappy"),
        "tinycss2": metadata.version("tinycss2"),
        "lark-oapi": metadata.version("lark-oapi"),
        "psutil": metadata.version("psutil"),
        "python-dotenv": metadata.version("python-dotenv"),
    }
    kafka = importlib.import_module("kafka")
    coordinator = importlib.import_module("kafka.coordinator.consumer")
    snappy = importlib.import_module("snappy")
    tinycss2 = importlib.import_module("tinycss2")
    lark = importlib.import_module("lark_oapi")
    dotenv = importlib.import_module("dotenv")
    from lark_oapi.api.im.v1 import (
        GetMessageRequest,
        ReplyMessageRequest,
        ReplyMessageRequestBody,
    )
    from lark_oapi.core import AccessTokenType, HttpMethod
    from lark_oapi.core.model import BaseRequest
    lark_client = (
        lark.Client.builder()
        .app_id("rca-release-gate-probe")
        .app_secret("rca-release-gate-probe")
        .build()
    )
    runtime_executable = str(Path(psutil.Process(os.getpid()).exe()).resolve())
    sys_executable = str(Path(sys.executable).resolve(strict=True))
    dependency_modules = {
        "kafka-python": ("kafka", kafka),
        "lark-oapi": ("lark_oapi", lark),
        "psutil": ("psutil", psutil),
        "python-dotenv": ("dotenv", dotenv),
        "python-snappy": ("snappy", snappy),
        "tinycss2": ("tinycss2", tinycss2),
    }
    def file_sha256(path):
        digest = hashlib.sha256()
        with Path(path).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()
    loaded_dependencies = {}
    for distribution, (module_name, module) in sorted(dependency_modules.items()):
        origin = str(Path(module.__file__).resolve(strict=True))
        loaded_dependencies[distribution] = {
            "module": module_name,
            "origin": origin,
            "sha256": file_sha256(origin),
            "version": versions[distribution],
        }
    loaded_runtime = {
        "sys_executable": sys_executable,
        "sys_executable_sha256": file_sha256(sys_executable),
        "process_executable": runtime_executable,
        "process_executable_sha256": file_sha256(runtime_executable),
        "dependencies": loaded_dependencies,
    }
    loaded_runtime_sha256 = hashlib.sha256(json.dumps(
        loaded_runtime,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")).hexdigest()
    payload = {
        "ok": True,
        "runtime_executable": runtime_executable,
        "loaded_runtime": loaded_runtime,
        "loaded_runtime_sha256": loaded_runtime_sha256,
        "versions": versions,
        "apis": {
            "KafkaConsumer": callable(getattr(kafka, "KafkaConsumer", None)),
            "AsyncConsumerRebalanceListener": callable(
                getattr(kafka, "AsyncConsumerRebalanceListener", None)
            ),
            "ConsumerCoordinator": callable(
                getattr(coordinator, "ConsumerCoordinator", None)
            ),
            "fetch_committed_offsets_async": inspect.iscoroutinefunction(
                getattr(
                    coordinator.ConsumerCoordinator,
                    "fetch_committed_offsets_async",
                    None,
                )
            ),
            "snappy_compress": callable(getattr(snappy, "compress", None)),
            "tinycss2_parse_stylesheet": callable(
                getattr(tinycss2, "parse_stylesheet", None)
            ),
        },
        "feishu_outbound": {
            "schema_version": "rca_feishu_outbound_runtime_check_v1",
            "dependency_install_attempted": False,
            "client_constructed": lark_client is not None,
            "apis": {
                "AccessTokenType.TENANT": hasattr(AccessTokenType, "TENANT"),
                "BaseRequest.builder": callable(getattr(BaseRequest, "builder", None)),
                "Client.builder": callable(getattr(lark.Client, "builder", None)),
                "Client.im.v1.message.create": callable(
                    getattr(lark_client.im.v1.message, "create", None)
                ),
                "Client.im.v1.message.get": callable(
                    getattr(lark_client.im.v1.message, "get", None)
                ),
                "Client.im.v1.message.reply": callable(
                    getattr(lark_client.im.v1.message, "reply", None)
                ),
                "Client.request": callable(getattr(lark_client, "request", None)),
                "GetMessageRequest.builder": callable(
                    getattr(GetMessageRequest, "builder", None)
                ),
                "HttpMethod.GET": hasattr(HttpMethod, "GET"),
                "ReplyMessageRequest.builder": callable(
                    getattr(ReplyMessageRequest, "builder", None)
                ),
                "ReplyMessageRequestBody.builder": callable(
                    getattr(ReplyMessageRequestBody, "builder", None)
                ),
            },
        },
    }
except Exception as exc:
    payload = {"ok": False, "error_type": type(exc).__name__}
print(json.dumps(payload, sort_keys=True, separators=(",", ":")))
raise SystemExit(0 if payload["ok"] else 2)
"""
    try:
        completed = runner(
            [str(interpreter), "-I", "-B", "-c", probe],
            cwd=str(working_directory),
            env=clean_env,
            text=True,
            capture_output=True,
            timeout=30,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise EvidenceError("runtime_candidate_probe_timeout") from exc
    except OSError as exc:
        raise EvidenceError("runtime_candidate_probe_failed") from exc
    stdout = str(completed.stdout or "")
    if len(stdout.encode("utf-8")) > 65_536:
        raise EvidenceError("runtime_candidate_probe_invalid")
    try:
        payload = _strict_json_loads(stdout, artifact="runtime_candidate_probe")
    except EvidenceError as exc:
        raise EvidenceError("runtime_candidate_probe_invalid") from exc
    if (
        not isinstance(payload, dict)
        or completed.returncode != 0
        or payload.get("ok") is not True
    ):
        code = (
            "runtime_dependency_missing"
            if payload.get("error_type")
            in {"ModuleNotFoundError", "PackageNotFoundError"}
            else "runtime_dependency_import_failed"
        )
        raise EvidenceError(code)
    versions = payload.get("versions")
    if versions != EXPECTED_DEPENDENCY_VERSIONS:
        raise EvidenceError("runtime_dependency_version_mismatch")
    probed_loaded_runtime_sha256 = _sha256_digest(
        payload.get("loaded_runtime_sha256"),
        "runtime_candidate_probe.loaded_runtime_sha256",
    )
    apis = payload.get("apis")
    if (
        not isinstance(apis, dict)
        or not apis
        or any(value is not True for value in apis.values())
    ):
        raise EvidenceError("runtime_dependency_api_missing")
    feishu_outbound = payload.get("feishu_outbound")
    if not isinstance(feishu_outbound, dict):
        raise EvidenceError("runtime_feishu_outbound_probe_invalid")
    feishu_apis = feishu_outbound.get("apis")
    if (
        feishu_outbound.get("schema_version") != FEISHU_OUTBOUND_RUNTIME_SCHEMA_VERSION
        or feishu_outbound.get("dependency_install_attempted") is not False
        or feishu_outbound.get("client_constructed") is not True
        or not isinstance(feishu_apis, dict)
        or set(feishu_apis) != EXPECTED_FEISHU_OUTBOUND_APIS
        or any(value is not True for value in feishu_apis.values())
    ):
        raise EvidenceError("runtime_feishu_outbound_api_missing")
    try:
        runtime_executable = Path(
            _required_text(
                payload.get("runtime_executable"),
                "runtime_candidate_probe.runtime_executable",
            )
        ).resolve(strict=True)
    except OSError as exc:
        raise EvidenceError("runtime_candidate_executable_invalid") from exc
    if not runtime_executable.is_file():
        raise EvidenceError("runtime_candidate_executable_invalid")
    loaded_runtime, loaded_runtime_sha256 = (
        loaded_runtime_verifier(
            payload.get("loaded_runtime"),
            virtual_env=root / ".venv",
            expected_sys_executable=interpreter,
            expected_process_executable=runtime_executable,
            expected_dependencies=RCA_LOADED_DEPENDENCIES,
            artifact="runtime_candidate_probe",
        )
    )
    if loaded_runtime_sha256 != probed_loaded_runtime_sha256:
        raise EvidenceError("runtime_candidate_probe_loaded_runtime_mismatch")
    service_checks: dict[str, str] = {}
    service_configs: dict[str, dict[str, Any]] = {}
    service_dependencies: dict[str, dict[str, Any]] = {}
    service_processes: dict[str, dict[str, Any]] = {}
    launchd_config: dict[str, Any] = {}
    for label, candidate in candidates.items():
        try:
            checked = runner(
                [*candidate["arguments"], "--check-config"],
                cwd=str(candidate["working_directory"]),
                env={
                    **candidate["environment"],
                    **runtime_config_environment,
                },
                text=True,
                capture_output=True,
                timeout=30,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            raise EvidenceError("runtime_candidate_config_timeout", label) from exc
        except OSError as exc:
            raise EvidenceError("runtime_candidate_config_failed", label) from exc
        try:
            checked_payload = _strict_json_loads(
                str(checked.stdout or ""), artifact="runtime_candidate_config"
            )
        except EvidenceError as exc:
            raise EvidenceError("runtime_candidate_config_invalid", label) from exc
        if (
            checked.returncode != 0
            or not isinstance(checked_payload, dict)
            or checked_payload.get("ok") is not True
        ):
            raise EvidenceError("runtime_candidate_config_invalid", label)
        checked_config = checked_payload.get("config")
        if not isinstance(checked_config, dict):
            raise EvidenceError("runtime_candidate_config_invalid", label)
        service_configs[label] = dict(checked_config)
        service_checks[label] = _sha256_json(checked_config)
        checked_dependencies = checked_payload.get("dependencies")
        if label == "local.pnc.rca-delivery-collector":
            if checked_dependencies != {
                "remote_css_parser": EXPECTED_REMOTE_CSS_RUNTIME_DEPENDENCY
            }:
                raise EvidenceError("runtime_remote_css_parser_unverified", label)
            service_dependencies[label] = dict(checked_dependencies)
        elif label == "local.pnc.rca-delivery-dispatcher":
            service_dependencies[label] = {
                "feishu_outbound": {
                    "schema_version": FEISHU_OUTBOUND_RUNTIME_SCHEMA_VERSION,
                    "distribution": "lark-oapi",
                    "version": EXPECTED_FEISHU_OUTBOUND_DEPENDENCY_VERSIONS[
                        "lark-oapi"
                    ],
                    "python_executable": str(runtime_executable),
                    "dependency_install_attempted": False,
                    "client_constructed": True,
                    "apis": dict(feishu_apis),
                }
            }
        resolved_interpreter = candidate["interpreter"].resolve(strict=True)
        resolved_script = candidate["script"].resolve(strict=True)
        resolved_working_directory = candidate["working_directory"].resolve(strict=True)
        service_loaded_runtime = {
            **{
                key: loaded_runtime[key]
                for key in (
                    "sys_executable",
                    "sys_executable_sha256",
                    "process_executable",
                    "process_executable_sha256",
                )
            },
            "dependencies": {
                distribution: loaded_runtime["dependencies"][distribution]
                for distribution in sorted(
                    RCA_LOADED_DEPENDENCIES_BY_SERVICE[label]
                )
            },
        }
        service_loaded_runtime_sha256 = _sha256_json(service_loaded_runtime)
        service_processes[label] = {
            "service_label": label,
            "interpreter": str(resolved_interpreter),
            "runtime_executable": str(runtime_executable),
            "script": str(resolved_script),
            "working_directory": str(resolved_working_directory),
            "script_sha256": hashlib.sha256(resolved_script.read_bytes()).hexdigest(),
            "runtime_file_sha256": dict(runtime_file_sha256),
            "runtime_files_sha256": runtime_files_sha256,
            "loaded_runtime": service_loaded_runtime,
            "loaded_runtime_sha256": service_loaded_runtime_sha256,
            "program_arguments": list(candidate["arguments"]),
            "environment": dict(candidate["environment"]),
            "verify_loaded_configuration": True,
            "candidate_plist_path": str(candidate["plist_path"]),
            "plist_path": str(
                Path.home() / "Library" / "LaunchAgents" / f"{label}.plist"
            ),
            "plist_sha256": candidate["plist_sha256"],
        }
        launchd_config[label] = {
            "program_arguments": candidate["arguments"],
            "working_directory": str(candidate["working_directory"]),
            "environment": candidate["environment"],
            "plist_sha256": candidate["plist_sha256"],
        }
    return {
        "python_executable": str(interpreter),
        "dependency_versions": versions,
        "loaded_runtime": loaded_runtime,
        "loaded_runtime_sha256": loaded_runtime_sha256,
        "module_imports": {name: "ok" for name in EXPECTED_RUNTIME_MODULES},
        "launchd_config_sha256": _sha256_json({
            "launchd": launchd_config,
            "service_configs": service_configs,
            "service_dependencies": service_dependencies,
            "service_processes": service_processes,
        }),
        "candidate_plist_sha256": {
            label: candidate["plist_sha256"] for label, candidate in candidates.items()
        },
        "service_config_checks": service_checks,
        "service_configs": service_configs,
        "service_dependencies": service_dependencies,
        "service_processes": service_processes,
        "isolated_probe": True,
    }


def _future_runtime_owned_directory(
    path: Path,
    *,
    artifact: str,
    expected_mode: int,
) -> dict[str, int | str]:
    candidate = path.expanduser().absolute()
    try:
        info = os.lstat(candidate)
        resolved = candidate.resolve(strict=True)
    except OSError as exc:
        raise EvidenceError(f"{artifact}_invalid") from exc
    if (
        stat.S_ISLNK(info.st_mode)
        or not stat.S_ISDIR(info.st_mode)
        or info.st_uid != os.geteuid()
        or stat.S_IMODE(info.st_mode) != expected_mode
        or resolved != candidate
    ):
        raise EvidenceError(f"{artifact}_invalid")
    return {
        "path": str(candidate),
        "device": info.st_dev,
        "inode": info.st_ino,
        "owner_uid": info.st_uid,
        "mode": stat.S_IMODE(info.st_mode),
    }


def _future_runtime_file_observation(
    root: Path,
    relative: str,
    *,
    artifact: str,
    require_owner: bool,
) -> dict[str, Any]:
    path = (root / relative).absolute()
    raw, info = _stable_regular_file_observation(
        path,
        artifact=artifact,
        require_owner=require_owner,
        allow_empty=True,
        max_bytes=runtime_stage.MAX_SOURCE_FILE_BYTES,
    )
    return {
        "path": str(path),
        "raw": raw,
        "sha256": hashlib.sha256(raw).hexdigest(),
        "size_bytes": len(raw),
        "mode": stat.S_IMODE(info.st_mode),
        "owner_uid": info.st_uid,
        "device": info.st_dev,
        "inode": info.st_ino,
    }


def _future_runtime_git_blob_oid(raw: bytes, *, object_format: str) -> str:
    payload = f"blob {len(raw)}\0".encode("ascii") + raw
    if object_format == "sha1":
        return hashlib.sha1(payload, usedforsecurity=False).hexdigest()
    if object_format == "sha256":
        return hashlib.sha256(payload).hexdigest()
    raise EvidenceError("future_runtime_git_object_format_invalid")


def _future_runtime_source_snapshot(
    root: Path,
    *,
    commit: str,
) -> tuple[dict[str, dict[str, Any]], tuple[str, ...]]:
    object_format = _git_output(root, ["rev-parse", "--show-object-format"])
    if object_format not in {"sha1", "sha256"}:
        raise EvidenceError("future_runtime_git_object_format_invalid")
    raw_tree = _git_output_bytes(
        root,
        ["ls-tree", "-rlz", "--full-tree", commit],
    )
    records = [record for record in raw_tree.split(b"\0") if record]
    excluded = set(FUTURE_RUNTIME_PLIST_FILENAMES) | {"pyproject.toml", "uv.lock"}
    if (
        not records
        or len(records) > runtime_stage.MAX_SOURCE_FILES + len(excluded)
    ):
        raise EvidenceError("future_runtime_source_tree_capacity_invalid")
    result: dict[str, dict[str, Any]] = {}
    runtime_relatives: list[str] = []
    total_bytes = 0
    for record in records:
        try:
            mode_raw, kind_raw, oid_raw, tail = record.split(b" ", 3)
            size_raw, relative_raw = tail.split(b"\t", 1)
            git_mode = mode_raw.decode("ascii")
            kind = kind_raw.decode("ascii")
            oid = oid_raw.decode("ascii")
            declared_size = int(size_raw.decode("ascii"))
            relative = relative_raw.decode("utf-8")
        except (UnicodeDecodeError, ValueError) as exc:
            raise EvidenceError("future_runtime_source_tree_invalid") from exc
        parsed = PurePosixPath(relative)
        expected_mode = {"100644": 0o644, "100755": 0o755}.get(git_mode)
        expected_oid_length = 40 if object_format == "sha1" else 64
        if (
            not relative
            or parsed.is_absolute()
            or str(parsed) != relative
            or ".." in parsed.parts
            or kind != "blob"
            or expected_mode is None
            or len(oid) != expected_oid_length
            or any(character not in "0123456789abcdef" for character in oid)
            or declared_size < 0
            or declared_size > runtime_stage.MAX_SOURCE_FILE_BYTES
            or relative in result
        ):
            raise EvidenceError("future_runtime_source_tree_invalid", relative)
        if relative in {"pyproject.toml", "uv.lock"}:
            continue
        observed = _future_runtime_file_observation(
            root,
            relative,
            artifact="future_runtime_source_file",
            require_owner=True,
        )
        if (
            observed["mode"] != expected_mode
            or observed["size_bytes"] != declared_size
            or _future_runtime_git_blob_oid(
                observed["raw"], object_format=object_format
            )
            != oid
        ):
            raise EvidenceError("future_runtime_source_blob_mismatch", relative)
        result[relative] = {
            **observed,
            "git_mode": git_mode,
            "git_blob": oid,
            "commit": commit,
        }
        if relative not in FUTURE_RUNTIME_PLIST_FILENAMES:
            runtime_relatives.append(relative)
            total_bytes += declared_size
            if (
                len(runtime_relatives) > runtime_stage.MAX_SOURCE_FILES
                or total_bytes > runtime_stage.MAX_SOURCE_TOTAL_BYTES
            ):
                raise EvidenceError("future_runtime_source_tree_capacity_invalid")
    if (
        not set(FUTURE_RUNTIME_RELATIVE_FILES).issubset(runtime_relatives)
        or set(FUTURE_RUNTIME_PLIST_FILENAMES) - set(result)
    ):
        raise EvidenceError("future_runtime_source_tree_incomplete")
    return result, tuple(sorted(runtime_relatives))


def _future_runtime_stage_snapshot(
    root: Path,
    *,
    runtime_relatives: Sequence[str],
) -> dict[str, dict[str, Any]]:
    return {
        relative: _future_runtime_file_observation(
            root,
            relative,
            artifact="future_runtime_stage_file",
            require_owner=True,
        )
        for relative in (*runtime_relatives, *FUTURE_RUNTIME_PLIST_FILENAMES)
    }


def _future_runtime_project_path(
    value: Any,
    *,
    physical_root: Path,
    canonical_root: Path,
    field: str,
    allow_root: bool = True,
) -> str:
    raw = _required_text(value, field)
    path = Path(raw)
    if not path.is_absolute() or ".." in path.parts:
        raise EvidenceError("future_runtime_path_invalid", field)
    try:
        relative = path.relative_to(physical_root)
    except ValueError as exc:
        raise EvidenceError("future_runtime_path_outside_root", field) from exc
    if not allow_root and not relative.parts:
        raise EvidenceError("future_runtime_path_invalid", field)
    return str(canonical_root / relative)


def _future_runtime_project_environment(
    value: Any,
    *,
    physical_root: Path,
    canonical_root: Path,
    field: str,
) -> dict[str, str]:
    environment = _mapping(value, field)
    if any(
        not isinstance(key, str) or not isinstance(item, str)
        for key, item in environment.items()
    ):
        raise EvidenceError("future_runtime_plist_environment_invalid", field)
    expected_hermes_home = str(CANONICAL_FUTURE_RUNTIME_ROOT.parent.parent)
    if (
        environment.get("HERMES_HOME") != expected_hermes_home
        or environment.get("VIRTUAL_ENV") != str(physical_root / ".venv")
        or environment.get("PYTHONDONTWRITEBYTECODE") != "1"
        or environment.get("PYTHONNOUSERSITE") != "1"
        or any(key.startswith(("DYLD_", "LD_")) for key in environment)
        or {"PYTHONPATH", "PYTHONHOME", "PYTHONUSERBASE"} & set(environment)
    ):
        raise EvidenceError("future_runtime_plist_environment_invalid", field)
    projected = {str(key): str(item) for key, item in environment.items()}
    projected["VIRTUAL_ENV"] = str(canonical_root / ".venv")
    path_value = environment.get("PATH")
    if not isinstance(path_value, str) or not path_value:
        raise EvidenceError("future_runtime_plist_environment_invalid", field)
    projected_path: list[str] = []
    for index, item in enumerate(path_value.split(":")):
        if not item:
            raise EvidenceError("future_runtime_plist_environment_invalid", field)
        if item == str(physical_root) or item.startswith(f"{physical_root}/"):
            projected_path.append(
                _future_runtime_project_path(
                    item,
                    physical_root=physical_root,
                    canonical_root=canonical_root,
                    field=f"{field}.PATH[{index}]",
                )
            )
        elif str(physical_root) in item:
            raise EvidenceError("future_runtime_prefix_ambiguous", field)
        else:
            projected_path.append(item)
    projected["PATH"] = ":".join(projected_path)
    for key, item in environment.items():
        if key in {"PATH", "VIRTUAL_ENV"}:
            continue
        if str(physical_root) in item:
            if item == str(physical_root) or item.startswith(f"{physical_root}/"):
                projected[key] = _future_runtime_project_path(
                    item,
                    physical_root=physical_root,
                    canonical_root=canonical_root,
                    field=f"{field}.{key}",
                )
            else:
                raise EvidenceError("future_runtime_prefix_ambiguous", f"{field}.{key}")
    return projected


def _future_runtime_project_plist(
    body: Any,
    *,
    filename: str,
    physical_root: Path,
    canonical_root: Path,
) -> dict[str, Any]:
    plist = _mapping(body, f"future_runtime.plist.{filename}")
    try:
        expected_label = runtime_stage.CANDIDATE_PLISTS[filename][0]
        argument_templates = runtime_stage.CANDIDATE_PLIST_ARGUMENTS[filename]
    except KeyError as exc:
        raise EvidenceError("future_runtime_plist_name_invalid", filename) from exc
    if plist.get("Label") != expected_label:
        raise EvidenceError("future_runtime_plist_label_invalid", filename)
    arguments = plist.get("ProgramArguments")
    if not isinstance(arguments, list) or not all(
        isinstance(item, str) and item for item in arguments
    ):
        raise EvidenceError("future_runtime_plist_arguments_invalid", filename)
    expected_arguments = [
        item.replace("{runtime}", str(physical_root))
        for item in argument_templates
    ]
    projected_arguments = [
        item.replace("{runtime}", str(canonical_root))
        for item in argument_templates
    ]
    if arguments != expected_arguments:
        raise EvidenceError("future_runtime_plist_arguments_invalid", filename)
    if plist.get("WorkingDirectory") != str(physical_root):
        raise EvidenceError("future_runtime_plist_working_directory_invalid", filename)
    projected = dict(plist)
    projected["ProgramArguments"] = projected_arguments
    projected["WorkingDirectory"] = str(canonical_root)
    projected["EnvironmentVariables"] = _future_runtime_project_environment(
        plist.get("EnvironmentVariables"),
        physical_root=physical_root,
        canonical_root=canonical_root,
        field=f"future_runtime.plist.{filename}.environment",
    )
    return projected


def _future_runtime_parse_plist(raw: bytes, *, filename: str) -> dict[str, Any]:
    try:
        body = plistlib.loads(raw)
    except plistlib.InvalidFileException as exc:
        raise EvidenceError("future_runtime_plist_invalid", filename) from exc
    return dict(_mapping(body, f"future_runtime.plist.{filename}"))


def _future_runtime_project_loaded_runtime(
    value: Any,
    *,
    stage_root: Path,
    canonical_root: Path,
    field: str,
) -> dict[str, Any]:
    loaded = _mapping(value, field)
    if set(loaded) != {
        "sys_executable",
        "sys_executable_sha256",
        "process_executable",
        "process_executable_sha256",
        "dependencies",
    }:
        raise EvidenceError("future_runtime_loaded_runtime_invalid", field)
    projected = {
        "sys_executable": _future_runtime_project_path(
            loaded.get("sys_executable"),
            physical_root=stage_root,
            canonical_root=canonical_root,
            field=f"{field}.sys_executable",
            allow_root=False,
        ),
        "sys_executable_sha256": _sha256_digest(
            loaded.get("sys_executable_sha256"), f"{field}.sys_executable_sha256"
        ),
        "process_executable": _future_runtime_project_path(
            loaded.get("process_executable"),
            physical_root=stage_root,
            canonical_root=canonical_root,
            field=f"{field}.process_executable",
            allow_root=False,
        ),
        "process_executable_sha256": _sha256_digest(
            loaded.get("process_executable_sha256"),
            f"{field}.process_executable_sha256",
        ),
    }
    dependencies = _mapping(loaded.get("dependencies"), f"{field}.dependencies")
    projected_dependencies: dict[str, dict[str, Any]] = {}
    for distribution, raw_dependency in sorted(dependencies.items()):
        dependency = _mapping(raw_dependency, f"{field}.{distribution}")
        if set(dependency) != {"module", "origin", "sha256", "version"}:
            raise EvidenceError("future_runtime_loaded_dependency_invalid", distribution)
        projected_dependencies[distribution] = {
            **dict(dependency),
            "origin": _future_runtime_project_path(
                dependency.get("origin"),
                physical_root=stage_root,
                canonical_root=canonical_root,
                field=f"{field}.{distribution}.origin",
                allow_root=False,
            ),
            "sha256": _sha256_digest(
                dependency.get("sha256"), f"{field}.{distribution}.sha256"
            ),
        }
    projected["dependencies"] = projected_dependencies
    return projected


def _future_runtime_dependency_observations(
    loaded_runtime: Mapping[str, Any],
    *,
    stage_root: Path,
) -> dict[str, dict[str, Any]]:
    dependencies = _mapping(
        loaded_runtime.get("dependencies"), "future_runtime.loaded_dependencies"
    )
    result: dict[str, dict[str, Any]] = {}
    for distribution, value in sorted(dependencies.items()):
        dependency = _mapping(value, f"future_runtime.{distribution}")
        origin = Path(
            _required_text(
                dependency.get("origin"), f"future_runtime.{distribution}.origin"
            )
        )
        try:
            relative = origin.relative_to(stage_root)
        except ValueError as exc:
            raise EvidenceError(
                "future_runtime_dependency_outside_stage", distribution
            ) from exc
        observed = _future_runtime_file_observation(
            stage_root,
            str(relative),
            artifact="future_runtime_dependency_file",
            require_owner=True,
        )
        if observed["sha256"] != dependency.get("sha256"):
            raise EvidenceError("future_runtime_dependency_hash_mismatch", distribution)
        result[distribution] = observed
    return result


def _future_runtime_project_service_dependencies(
    value: Any,
    *,
    stage_root: Path,
    canonical_root: Path,
) -> dict[str, Any]:
    dependencies = _mapping(value, "future_runtime.service_dependencies")
    projected = json.loads(_canonical_json(dependencies))
    for service in projected.values():
        if not isinstance(service, dict):
            raise EvidenceError("future_runtime_service_dependencies_invalid")
        feishu = service.get("feishu_outbound")
        if isinstance(feishu, dict) and "python_executable" in feishu:
            feishu["python_executable"] = _future_runtime_project_path(
                feishu["python_executable"],
                physical_root=stage_root,
                canonical_root=canonical_root,
                field="future_runtime.feishu.python_executable",
                allow_root=False,
            )
    return projected


def project_future_candidate_runtime(
    host_candidate: Path,
    staging_runtime_root: Path,
    *,
    candidate_plists: Sequence[Path] | None = None,
    canonical_live_root: Path = CANONICAL_FUTURE_RUNTIME_ROOT,
    runner: Any = subprocess.run,
    runtime_verifier: Callable[[Path], Mapping[str, Any]] | None = None,
    gateway_runtime_verifier: Callable[..., Mapping[str, Any]] | None = None,
    runtime_config_environment: Mapping[str, str] | None = None,
) -> dict[str, Any]:
    """Verify a staged runtime and project only exact root-relative paths live."""
    source_root = host_candidate.expanduser().resolve()
    stage_root = staging_runtime_root.expanduser().absolute()
    canonical_root = canonical_live_root.expanduser().absolute()
    if canonical_root != CANONICAL_FUTURE_RUNTIME_ROOT:
        raise EvidenceError("future_runtime_canonical_root_invalid")
    if source_root in {stage_root, canonical_root} or stage_root == canonical_root:
        raise EvidenceError("future_runtime_root_alias")
    source_provenance = _local_git_provenance(source_root, component="host")
    stage_identity = _future_runtime_owned_directory(
        stage_root,
        artifact="future_runtime_staging_root",
        expected_mode=FUTURE_RUNTIME_STAGING_ROOT_MODE,
    )
    venv_identity = _future_runtime_owned_directory(
        stage_root / ".venv",
        artifact="future_runtime_staging_venv",
        expected_mode=FUTURE_RUNTIME_VENV_MODE,
    )
    _future_runtime_owned_directory(
        stage_root / ".venv" / "bin",
        artifact="future_runtime_staging_venv_bin",
        expected_mode=FUTURE_RUNTIME_VENV_MODE,
    )
    interpreter_raw, interpreter_info = _stable_regular_file_observation(
        stage_root / ".venv" / "bin" / "python",
        artifact="future_runtime_staging_interpreter",
        expected_mode=0o755,
        require_owner=True,
    )
    interpreter_observation = {
        "path": str(stage_root / ".venv" / "bin" / "python"),
        "sha256": hashlib.sha256(interpreter_raw).hexdigest(),
        "owner_uid": interpreter_info.st_uid,
        "mode": stat.S_IMODE(interpreter_info.st_mode),
        "device": interpreter_info.st_dev,
        "inode": interpreter_info.st_ino,
    }
    source_snapshot, runtime_relatives = _future_runtime_source_snapshot(
        source_root,
        commit=source_provenance["commit"],
    )
    stage_snapshot = _future_runtime_stage_snapshot(
        stage_root,
        runtime_relatives=runtime_relatives,
    )
    for relative in runtime_relatives:
        source = source_snapshot[relative]
        staged = stage_snapshot[relative]
        if (
            source["raw"] != staged["raw"]
            or source["mode"] != staged["mode"]
            or (source["device"], source["inode"])
            == (staged["device"], staged["inode"])
        ):
            raise EvidenceError("future_runtime_source_stage_mismatch", relative)
    raw_plist_paths = tuple(candidate_plists or (
        stage_root / filename for filename in FUTURE_RUNTIME_PLIST_FILENAMES
    ))
    by_name: dict[str, Path] = {}
    for raw_path in raw_plist_paths:
        path = raw_path.expanduser().absolute()
        if path.name in by_name:
            raise EvidenceError("future_runtime_candidate_plist_duplicate")
        by_name[path.name] = path
    if set(by_name) != set(FUTURE_RUNTIME_PLIST_FILENAMES):
        raise EvidenceError("future_runtime_candidate_plist_set_invalid")
    canonical_plists: dict[str, dict[str, Any]] = {}
    plist_manifest: dict[str, dict[str, Any]] = {}
    for filename in FUTURE_RUNTIME_PLIST_FILENAMES:
        expected_stage_path = stage_root / filename
        if by_name[filename] != expected_stage_path:
            raise EvidenceError("future_runtime_candidate_plist_path_invalid", filename)
        source = source_snapshot[filename]
        staged = stage_snapshot[filename]
        if (
            source["mode"] != staged["mode"]
            or (source["device"], source["inode"])
            == (staged["device"], staged["inode"])
        ):
            raise EvidenceError("future_runtime_candidate_plist_identity_invalid", filename)
        source_body = _future_runtime_project_plist(
            _future_runtime_parse_plist(source["raw"], filename=filename),
            filename=filename,
            physical_root=canonical_root,
            canonical_root=canonical_root,
        )
        projected_stage_body = _future_runtime_project_plist(
            _future_runtime_parse_plist(staged["raw"], filename=filename),
            filename=filename,
            physical_root=stage_root,
            canonical_root=canonical_root,
        )
        if source_body != projected_stage_body:
            raise EvidenceError("future_runtime_candidate_plist_render_mismatch", filename)
        label = str(source_body["Label"])
        canonical_plists[label] = source_body
        plist_manifest[filename] = {
            "label": label,
            "source_sha256": source["sha256"],
            "staging_sha256": staged["sha256"],
            "canonical_sha256": source["sha256"],
            "canonical_body_sha256": _sha256_json(source_body),
        }
    if runtime_verifier is None:
        runtime_detail = check_candidate_runtime_dependencies(
            stage_root,
            runner=runner,
            config_environment=runtime_config_environment,
        )
    else:
        runtime_detail = dict(runtime_verifier(stage_root))
    if runtime_detail.get("python_executable") != interpreter_observation["path"]:
        raise EvidenceError("future_runtime_interpreter_projection_invalid")
    loaded_runtime = _mapping(
        runtime_detail.get("loaded_runtime"), "future_runtime.loaded_runtime"
    )
    if (
        loaded_runtime.get("sys_executable") != interpreter_observation["path"]
        or loaded_runtime.get("process_executable") != interpreter_observation["path"]
        or loaded_runtime.get("sys_executable_sha256")
        != interpreter_observation["sha256"]
        or loaded_runtime.get("process_executable_sha256")
        != interpreter_observation["sha256"]
    ):
        raise EvidenceError("future_runtime_interpreter_projection_invalid")
    dependency_observations = _future_runtime_dependency_observations(
        loaded_runtime,
        stage_root=stage_root,
    )
    candidate_hashes = _mapping(
        runtime_detail.get("candidate_plist_sha256"),
        "future_runtime.candidate_plist_sha256",
    )
    expected_stage_hashes = {
        CANDIDATE_SERVICES[filename][0]: stage_snapshot[filename]["sha256"]
        for filename in CANDIDATE_SERVICES
    }
    if candidate_hashes != expected_stage_hashes:
        raise EvidenceError("future_runtime_candidate_plist_probe_mismatch")
    service_processes = _mapping(
        runtime_detail.get("service_processes"), "future_runtime.service_processes"
    )
    projected_loaded_runtime = _future_runtime_project_loaded_runtime(
        loaded_runtime,
        stage_root=stage_root,
        canonical_root=canonical_root,
        field="future_runtime.loaded_runtime",
    )
    projected_processes: dict[str, dict[str, Any]] = {}
    for label, raw_process in sorted(service_processes.items()):
        process = dict(_mapping(raw_process, f"future_runtime.processes.{label}"))
        for field in (
            "interpreter",
            "runtime_executable",
            "script",
            "working_directory",
            "candidate_plist_path",
        ):
            process[field] = _future_runtime_project_path(
                process.get(field),
                physical_root=stage_root,
                canonical_root=canonical_root,
                field=f"future_runtime.processes.{label}.{field}",
            )
        process["program_arguments"] = [
            _future_runtime_project_path(
                item,
                physical_root=stage_root,
                canonical_root=canonical_root,
                field=f"future_runtime.processes.{label}.program_arguments",
            )
            for item in process.get("program_arguments", [])
        ]
        process["environment"] = _future_runtime_project_environment(
            process.get("environment"),
            physical_root=stage_root,
            canonical_root=canonical_root,
            field=f"future_runtime.processes.{label}.environment",
        )
        process["loaded_runtime"] = _future_runtime_project_loaded_runtime(
            process.get("loaded_runtime"),
            stage_root=stage_root,
            canonical_root=canonical_root,
            field=f"future_runtime.processes.{label}.loaded_runtime",
        )
        process["loaded_runtime_sha256"] = _sha256_json(process["loaded_runtime"])
        filename = next(
            name for name, contract in CANDIDATE_SERVICES.items() if contract[0] == label
        )
        process["plist_sha256"] = source_snapshot[filename]["sha256"]
        projected_processes[label] = process
    service_dependencies = _future_runtime_project_service_dependencies(
        runtime_detail.get("service_dependencies"),
        stage_root=stage_root,
        canonical_root=canonical_root,
    )
    gateway_checker = gateway_runtime_verifier or _gateway_interpreter_runtime_probe
    gateway_runtime = dict(
        gateway_checker(
            stage_root / ".venv" / "bin" / "python",
            repo_root=stage_root,
            virtual_env=stage_root / ".venv",
            runner=runner,
        )
    )
    if (
        gateway_runtime.get("sys_executable") != interpreter_observation["path"]
        or gateway_runtime.get("process_executable") != interpreter_observation["path"]
    ):
        raise EvidenceError("future_runtime_gateway_interpreter_invalid")
    gateway_origins = _mapping(
        gateway_runtime.get("module_origins"), "future_runtime.gateway.module_origins"
    )
    projected_gateway_origins: dict[str, str] = {}
    for module, raw_origin in sorted(gateway_origins.items()):
        origin = Path(_required_text(raw_origin, f"future_runtime.gateway.{module}"))
        try:
            relative = origin.relative_to(stage_root)
        except ValueError as exc:
            raise EvidenceError("future_runtime_gateway_origin_outside_stage", module) from exc
        observed = _future_runtime_file_observation(
            stage_root,
            str(relative),
            artifact="future_runtime_gateway_origin",
            require_owner=True,
        )
        projected_gateway_origins[module] = _future_runtime_project_path(
            observed["path"],
            physical_root=stage_root,
            canonical_root=canonical_root,
            field=f"future_runtime.gateway.{module}",
        )
    canonical_resident_plists = {
        label: {
            "program_arguments": body["ProgramArguments"],
            "working_directory": body["WorkingDirectory"],
            "environment": body["EnvironmentVariables"],
            "plist_sha256": plist_manifest[filename]["canonical_sha256"],
        }
        for filename, (label, _script) in CANDIDATE_SERVICES.items()
        for body in (canonical_plists[label],)
    }
    projected_runtime = {
        **dict(runtime_detail),
        "python_executable": str(canonical_root / ".venv" / "bin" / "python"),
        "loaded_runtime": projected_loaded_runtime,
        "loaded_runtime_sha256": _sha256_json(projected_loaded_runtime),
        "candidate_plist_sha256": {
            label: plist_manifest[filename]["canonical_sha256"]
            for filename, (label, _script) in CANDIDATE_SERVICES.items()
        },
        "service_dependencies": service_dependencies,
        "service_processes": projected_processes,
    }
    projected_runtime["launchd_config_sha256"] = _sha256_json({
        "launchd": canonical_resident_plists,
        "service_configs": projected_runtime["service_configs"],
        "service_dependencies": service_dependencies,
        "service_processes": projected_processes,
    })
    render_manifest = {
        "schema_version": FUTURE_RUNTIME_RENDER_MANIFEST_SCHEMA_VERSION,
        "source_repo_root": str(source_root),
        "source_commit": source_provenance["commit"],
        "staging_root": str(stage_root),
        "canonical_live_root": str(canonical_root),
        "runtime_file_sha256": {
            relative: stage_snapshot[relative]["sha256"]
            for relative in runtime_relatives
        },
        "runtime_files_sha256": _sha256_json({
            relative: stage_snapshot[relative]["sha256"]
            for relative in runtime_relatives
        }),
        "interpreter": {
            "staging_path": interpreter_observation["path"],
            "canonical_path": str(canonical_root / ".venv" / "bin" / "python"),
            "sha256": interpreter_observation["sha256"],
        },
        "dependencies": {
            name: {
                "staging_path": observation["path"],
                "canonical_path": _future_runtime_project_path(
                    observation["path"],
                    physical_root=stage_root,
                    canonical_root=canonical_root,
                    field=f"future_runtime.dependencies.{name}",
                ),
                "sha256": observation["sha256"],
            }
            for name, observation in dependency_observations.items()
        },
        "candidate_plists": plist_manifest,
        "canonical_launchd_config_sha256": _sha256_json(canonical_plists),
        "canonical_runtime_config_sha256": projected_runtime[
            "launchd_config_sha256"
        ],
        "gateway_runtime": {
            **gateway_runtime,
            "sys_executable": str(canonical_root / ".venv" / "bin" / "python"),
            "process_executable": str(
                canonical_root / ".venv" / "bin" / "python"
            ),
            "module_origins": projected_gateway_origins,
            "module_origins_sha256": _sha256_json(projected_gateway_origins),
        },
    }
    source_after = _local_git_provenance(source_root, component="host")
    if source_after != source_provenance:
        raise EvidenceError("future_runtime_source_changed_during_projection")
    if (
        _future_runtime_owned_directory(
            stage_root,
            artifact="future_runtime_staging_root",
            expected_mode=FUTURE_RUNTIME_STAGING_ROOT_MODE,
        )
        != stage_identity
        or _future_runtime_owned_directory(
            stage_root / ".venv",
            artifact="future_runtime_staging_venv",
            expected_mode=FUTURE_RUNTIME_VENV_MODE,
        )
        != venv_identity
        or _future_runtime_source_snapshot(
            source_root,
            commit=source_provenance["commit"],
        )
        != (source_snapshot, runtime_relatives)
        or _future_runtime_stage_snapshot(
            stage_root,
            runtime_relatives=runtime_relatives,
        )
        != stage_snapshot
        or _future_runtime_dependency_observations(
            loaded_runtime,
            stage_root=stage_root,
        )
        != dependency_observations
    ):
        raise EvidenceError("future_runtime_changed_during_projection")
    runtime_stage_identity = {
        "root": stage_identity,
        "venv": venv_identity,
        "interpreter": interpreter_observation,
    }
    return {
        **projected_runtime,
        "runtime_stage_identity": runtime_stage_identity,
        "future_runtime_projection": {
            "schema_version": FUTURE_RUNTIME_PROJECTION_SCHEMA_VERSION,
            "ok": True,
            "source_commit": source_provenance["commit"],
            "staging_root": str(stage_root),
            "canonical_live_root": str(canonical_root),
            "render_manifest_sha256": _sha256_json(render_manifest),
        },
        "render_manifest": render_manifest,
        "render_manifest_sha256": _sha256_json(render_manifest),
    }


def _normalize_workspace_execution_closure(
    value: Any,
    *,
    repo_root: str,
    commit: str,
    field: str,
) -> dict[str, Any]:
    closure = _mapping(value, field)
    if set(closure) != {
        "schema_version",
        "commit",
        "relative_paths",
        "files",
        "scoped_clean",
        "scoped_status_sha256",
    }:
        raise EvidenceError("build_manifest_workspace_closure_shape_invalid")
    _require_schema(
        closure,
        WORKSPACE_EXECUTION_CLOSURE_SCHEMA_VERSION,
        "workspace_execution_closure",
    )
    closure_commit = _commit_sha(closure.get("commit"), f"{field}.commit")
    if closure_commit != commit:
        raise EvidenceError("build_manifest_workspace_closure_cross_commit")
    if closure.get("relative_paths") != list(
        WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS
    ):
        raise EvidenceError("build_manifest_workspace_closure_paths_invalid")
    if closure.get("scoped_clean") is not True:
        raise EvidenceError("build_manifest_workspace_closure_dirty")
    scoped_status_sha256 = _sha256_digest(
        closure.get("scoped_status_sha256"),
        f"{field}.scoped_status_sha256",
    )
    if scoped_status_sha256 != EMPTY_GIT_STATUS_SHA256:
        raise EvidenceError("build_manifest_workspace_closure_dirty")
    files = _mapping(closure.get("files"), f"{field}.files")
    if set(files) != set(WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS):
        raise EvidenceError("build_manifest_workspace_closure_files_invalid")
    normalized_files: dict[str, dict[str, Any]] = {}
    for relative in WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS:
        item = _mapping(files.get(relative), f"{field}.files.{relative}")
        if set(item) != {
            "relative_path",
            "path",
            "commit",
            "git_mode",
            "tracked",
            "regular_file",
            "symlink",
            "sha256",
        }:
            raise EvidenceError("build_manifest_workspace_closure_file_shape_invalid")
        file_commit = _commit_sha(item.get("commit"), f"{field}.{relative}.commit")
        expected_path = str(Path(repo_root) / relative)
        if (
            item.get("relative_path") != relative
            or item.get("path") != expected_path
            or file_commit != commit
        ):
            raise EvidenceError("build_manifest_workspace_closure_cross_commit")
        if (
            item.get("git_mode") not in {"100644", "100755"}
            or item.get("tracked") is not True
            or item.get("regular_file") is not True
            or item.get("symlink") is not False
        ):
            raise EvidenceError("build_manifest_workspace_closure_file_invalid")
        normalized_files[relative] = {
            **dict(item),
            "sha256": _sha256_digest(
                item.get("sha256"),
                f"{field}.files.{relative}.sha256",
            ),
        }
    return {
        "schema_version": WORKSPACE_EXECUTION_CLOSURE_SCHEMA_VERSION,
        "commit": commit,
        "relative_paths": list(WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS),
        "files": normalized_files,
        "scoped_clean": True,
        "scoped_status_sha256": scoped_status_sha256,
    }


def _normalize_external_dependencies(
    value: Any,
    *,
    field: str,
) -> dict[str, dict[str, Any]]:
    dependencies = _mapping(value, field)
    if set(dependencies) != set(EXTERNAL_RELEASE_DEPENDENCIES):
        raise EvidenceError("build_manifest_external_dependencies_invalid")
    normalized: dict[str, dict[str, Any]] = {}
    for name, contract in sorted(EXTERNAL_RELEASE_DEPENDENCIES.items()):
        item = _mapping(dependencies.get(name), f"{field}.{name}")
        if set(item) != {
            "schema_version",
            "source",
            "path",
            "realpath",
            "owner_uid",
            "mode",
            "regular_file",
            "symlink",
            "link_count",
            "sha256",
            "stable",
        }:
            raise EvidenceError(f"build_manifest_external_{name}_shape_invalid")
        _require_schema(
            item,
            EXTERNAL_DEPENDENCY_PROVENANCE_SCHEMA_VERSION,
            f"external_dependency_{name}",
        )
        expected_path = str(contract["path"])
        if (
            item.get("source") != "local_lstat"
            or item.get("path") != expected_path
            or item.get("realpath") != expected_path
            or item.get("owner_uid") != os.getuid()
            or item.get("mode") != contract["mode"]
            or item.get("regular_file") is not True
            or item.get("symlink") is not False
            or item.get("link_count") != 1
            or item.get("stable") is not True
        ):
            raise EvidenceError(f"build_manifest_external_{name}_identity_invalid")
        normalized[name] = {
            **dict(item),
            "sha256": _sha256_digest(
                item.get("sha256"),
                f"{field}.{name}.sha256",
            ),
        }
    return normalized


def _normalize_unscoped_workspace_drift(value: Any) -> dict[str, Any]:
    drift = _mapping(value, "build_manifest.live_provenance.workspace.unscoped_drift")
    if set(drift) != {
        "classification",
        "dirty_count",
        "status_sha256",
        "blocking",
    }:
        raise EvidenceError("build_manifest_workspace_unscoped_drift_invalid")
    dirty_count = _exact_int(
        drift.get("dirty_count"),
        "build_manifest.workspace.unscoped_drift.dirty_count",
        minimum=0,
    )
    status_sha256 = _sha256_digest(
        drift.get("status_sha256"),
        "build_manifest.workspace.unscoped_drift.status_sha256",
    )
    if (
        drift.get("classification") != "DRIFT-PREEXISTING"
        or drift.get("blocking") is not False
        or (dirty_count == 0 and status_sha256 != EMPTY_GIT_STATUS_SHA256)
        or (dirty_count > 0 and status_sha256 == EMPTY_GIT_STATUS_SHA256)
    ):
        raise EvidenceError("build_manifest_workspace_unscoped_drift_invalid")
    return {
        "classification": "DRIFT-PREEXISTING",
        "dirty_count": dirty_count,
        "status_sha256": status_sha256,
        "blocking": False,
    }


def _check_build_manifest(
    body: Mapping[str, Any],
    *,
    settings: ReleaseGateSettings,
    now: datetime,
    max_age_seconds: int,
    expected_runtime_config_sha256: str,
    expected_launchd_config_sha256: str,
    provenance_verifier: BuildProvenanceVerifier,
) -> dict[str, Any]:
    artifact = "build_manifest"
    _require_schema(body, BUILD_MANIFEST_SCHEMA_VERSION, artifact)
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    root = settings.host_repo_root.expanduser().resolve()
    if not root.is_dir():
        raise EvidenceError("build_manifest_host_repo_missing")

    release_bom = _mapping(body.get("release_bom"), "build_manifest.release_bom")
    if set(release_bom) != {
        "schema_version",
        "components",
        "workspace_runtime",
        "future_runtime",
        "runtime_config_sha256",
        "launchd_config_sha256",
        "critical_files_sha256",
        "external_dependencies",
    }:
        raise EvidenceError("build_manifest_release_bom_shape_invalid")
    release_bom_sha256 = _sha256_digest(
        body.get("release_bom_sha256"),
        "build_manifest.release_bom_sha256",
    )
    if _sha256_json(release_bom) != release_bom_sha256:
        raise EvidenceError("build_manifest_release_bom_hash_mismatch")
    _require_schema(release_bom, RELEASE_BOM_SCHEMA_VERSION, "release_bom")
    runtime_config_sha256 = _sha256_digest(
        release_bom.get("runtime_config_sha256"),
        "build_manifest.release_bom.runtime_config_sha256",
    )
    if runtime_config_sha256 != expected_runtime_config_sha256:
        raise EvidenceError("build_manifest_runtime_config_mismatch")
    launchd_config_sha256 = _sha256_digest(
        release_bom.get("launchd_config_sha256"),
        "build_manifest.release_bom.launchd_config_sha256",
    )
    if launchd_config_sha256 != expected_launchd_config_sha256:
        raise EvidenceError("build_manifest_launchd_config_mismatch")

    components = _mapping(
        release_bom.get("components"), "build_manifest.release_bom.components"
    )
    expected_component_names = {"host", "workspace", "vm", "vm_worker"}
    if set(components) != expected_component_names:
        raise EvidenceError("build_manifest_components_invalid")
    expected_roots = {
        "host": str(root),
        "workspace": str(settings.workspace_repo_root.expanduser().resolve()),
        "vm": str(PurePosixPath(settings.vm_repo_root)),
        "vm_worker": str(PurePosixPath(settings.vm_worker_repo_root)),
    }
    expected_sources = {
        "host": "local_git",
        "workspace": "local_git_scoped_closure",
        "vm": "ssh-mini-agent",
        "vm_worker": "ssh-mini-agent",
    }
    expected_entrypoint_paths = {
        "vm": str(
            PurePosixPath(settings.vm_repo_root)
            / str(VM_COMPONENT_ENTRYPOINTS["vm"]["relative"])
        ),
        "vm_worker": str(
            PurePosixPath(settings.vm_worker_repo_root)
            / str(VM_COMPONENT_ENTRYPOINTS["vm_worker"]["relative"])
        ),
    }
    declared_components: dict[str, dict[str, Any]] = {}
    for component in sorted(expected_component_names):
        declared = _mapping(
            components.get(component),
            f"build_manifest.release_bom.components.{component}",
        )
        expected_declared_fields = {"source", "repo_root", "commit"}
        if component == "workspace":
            expected_declared_fields |= {
                "execution_closure",
                "execution_closure_sha256",
            }
        else:
            expected_declared_fields |= {"tree_clean", "status_sha256"}
        if component in expected_entrypoint_paths:
            expected_declared_fields |= {
                "tree",
                "entrypoint_path",
                "entrypoint_sha256",
                "entrypoint_committed_sha256",
                "entrypoint_git_mode",
                "entrypoint_blob",
            }
        if set(declared) != expected_declared_fields:
            raise EvidenceError(f"build_manifest_{component}_component_invalid")
        commit = _commit_sha(
            declared.get("commit"),
            f"build_manifest.release_bom.components.{component}.commit",
        )
        source = _required_text(
            declared.get("source"),
            f"build_manifest.release_bom.components.{component}.source",
        )
        repo_root = _required_text(
            declared.get("repo_root"),
            f"build_manifest.release_bom.components.{component}.repo_root",
        )
        if source != expected_sources[component]:
            raise EvidenceError(f"build_manifest_{component}_source_mismatch")
        if repo_root != expected_roots[component]:
            raise EvidenceError(f"build_manifest_{component}_repo_root_mismatch")
        normalized_component = {
            "source": source,
            "repo_root": repo_root,
            "commit": commit,
        }
        if component == "workspace":
            execution_closure = _normalize_workspace_execution_closure(
                declared.get("execution_closure"),
                repo_root=repo_root,
                commit=commit,
                field=(
                    "build_manifest.release_bom.components.workspace."
                    "execution_closure"
                ),
            )
            closure_sha256 = _sha256_digest(
                declared.get("execution_closure_sha256"),
                (
                    "build_manifest.release_bom.components.workspace."
                    "execution_closure_sha256"
                ),
            )
            if _sha256_json(execution_closure) != closure_sha256:
                raise EvidenceError("build_manifest_workspace_closure_hash_mismatch")
            normalized_component.update({
                "execution_closure": execution_closure,
                "execution_closure_sha256": closure_sha256,
            })
        else:
            status_sha256 = _sha256_digest(
                declared.get("status_sha256"),
                f"build_manifest.release_bom.components.{component}.status_sha256",
            )
            if declared.get("tree_clean") is not True:
                raise EvidenceError(
                    f"build_manifest_{component}_clean_evidence_missing"
                )
            if status_sha256 != EMPTY_GIT_STATUS_SHA256:
                raise EvidenceError(
                    f"build_manifest_{component}_clean_evidence_missing"
                )
            normalized_component.update({
                "tree_clean": True,
                "status_sha256": status_sha256,
            })
        if component in expected_entrypoint_paths:
            tree = _git_object_id(
                declared.get("tree"),
                f"build_manifest.release_bom.components.{component}.tree",
            )
            entrypoint_path = _required_text(
                declared.get("entrypoint_path"),
                f"build_manifest.release_bom.components.{component}.entrypoint_path",
            )
            entrypoint_sha256 = _sha256_digest(
                declared.get("entrypoint_sha256"),
                f"build_manifest.release_bom.components.{component}.entrypoint_sha256",
            )
            entrypoint_committed_sha256 = _sha256_digest(
                declared.get("entrypoint_committed_sha256"),
                (
                    f"build_manifest.release_bom.components.{component}."
                    "entrypoint_committed_sha256"
                ),
            )
            entrypoint_blob = _git_object_id(
                declared.get("entrypoint_blob"),
                f"build_manifest.release_bom.components.{component}.entrypoint_blob",
            )
            entrypoint_git_mode = _required_text(
                declared.get("entrypoint_git_mode"),
                (
                    f"build_manifest.release_bom.components.{component}."
                    "entrypoint_git_mode"
                ),
            )
            if entrypoint_path != expected_entrypoint_paths[component]:
                raise EvidenceError(
                    f"build_manifest_{component}_entrypoint_path_mismatch"
                )
            if (
                entrypoint_committed_sha256 != entrypoint_sha256
                or entrypoint_git_mode not in {"100644", "100755"}
            ):
                raise EvidenceError(
                    f"build_manifest_{component}_entrypoint_hash_mismatch"
                )
            normalized_component.update({
                "tree": tree,
                "entrypoint_path": entrypoint_path,
                "entrypoint_sha256": entrypoint_sha256,
                "entrypoint_committed_sha256": entrypoint_committed_sha256,
                "entrypoint_git_mode": entrypoint_git_mode,
                "entrypoint_blob": entrypoint_blob,
            })
        elif "entrypoint_path" in declared or "entrypoint_sha256" in declared:
            raise EvidenceError(f"build_manifest_{component}_entrypoint_unexpected")
        declared_components[component] = normalized_component

    workspace_runtime_binding = _normalize_workspace_runtime_release_binding(
        release_bom.get("workspace_runtime"),
        workspace_component=declared_components["workspace"],
        field="build_manifest.release_bom.workspace_runtime",
    )
    future_runtime_binding = _normalize_future_runtime_release_binding(
        release_bom.get("future_runtime"),
        host_component=declared_components["host"],
        expected_launchd_config_sha256=launchd_config_sha256,
        field="build_manifest.release_bom.future_runtime",
    )
    _revalidate_workspace_runtime_release_binding(workspace_runtime_binding)
    _revalidate_future_runtime_release_binding(future_runtime_binding)

    declared_external_dependencies = _normalize_external_dependencies(
        release_bom.get("external_dependencies"),
        field="build_manifest.release_bom.external_dependencies",
    )

    critical = _mapping(body.get("critical_files"), "build_manifest.critical_files")
    if not critical:
        raise EvidenceError("build_manifest_critical_files_missing")
    resolved: dict[str, tuple[Path, str]] = {}
    for raw_name, raw_digest in critical.items():
        name, path = _critical_path(root, raw_name)
        if name in resolved:
            raise EvidenceError("build_manifest_critical_path_duplicate")
        resolved[name] = (
            path,
            _sha256_digest(raw_digest, f"build_manifest.critical_files.{name}"),
        )
    required = _required_critical_files(root)
    missing = required - resolved.keys()
    if missing:
        raise EvidenceError("build_manifest_core_file_missing")

    for name, (path, expected_digest) in resolved.items():
        try:
            actual_digest = hashlib.sha256(path.read_bytes()).hexdigest()
        except OSError as exc:
            raise EvidenceError("build_manifest_critical_file_unreadable") from exc
        if actual_digest != expected_digest:
            raise EvidenceError("build_manifest_critical_hash_mismatch")
        _git_output(
            root,
            ["cat-file", "-e", f"{declared_components['host']['commit']}:{name}"],
        )
    relevant_status = _git_output(
        root,
        ["status", "--porcelain=v1", "--", *sorted(resolved)],
    )
    if relevant_status:
        raise EvidenceError("build_manifest_relevant_tree_dirty")

    critical_files_sha256 = _sha256_json({
        name: digest for name, (_, digest) in sorted(resolved.items())
    })
    declared_critical_files_sha256 = _sha256_digest(
        release_bom.get("critical_files_sha256"),
        "build_manifest.release_bom.critical_files_sha256",
    )
    if declared_critical_files_sha256 != critical_files_sha256:
        raise EvidenceError("build_manifest_critical_files_bom_mismatch")

    dependencies = _mapping(
        body.get("dependency_versions"), "build_manifest.dependency_versions"
    )
    _verify_dependency_pins(root, dependencies)

    try:
        live_provenance = _mapping(
            provenance_verifier(settings),
            "build_manifest.live_provenance",
        )
    except EvidenceError:
        raise
    except Exception as exc:
        raise EvidenceError("build_manifest_provenance_unavailable") from exc
    _require_schema(
        live_provenance,
        BUILD_PROVENANCE_SCHEMA_VERSION,
        "build_manifest_provenance",
    )
    if set(live_provenance) != expected_component_names | {
        "schema_version",
        "external_dependencies",
    }:
        raise EvidenceError("build_manifest_provenance_components_invalid")
    workspace_unscoped_drift: dict[str, Any] | None = None
    for component in sorted(expected_component_names):
        live = _mapping(
            live_provenance.get(component),
            f"build_manifest.live_provenance.{component}",
        )
        declared = declared_components[component]
        expected_live_fields = {
            "source",
            "repo_root",
            "commit",
            "stable",
        }
        if component == "workspace":
            expected_live_fields |= {
                "execution_closure",
                "execution_closure_sha256",
                "unscoped_drift",
            }
        else:
            expected_live_fields |= {"tree_clean", "status_sha256"}
        if component in expected_entrypoint_paths:
            expected_live_fields |= {
                "tree",
                "entrypoint_path",
                "entrypoint_sha256",
                "entrypoint_committed_sha256",
                "entrypoint_git_mode",
                "entrypoint_blob",
            }
        if set(live) != expected_live_fields:
            raise EvidenceError(f"build_manifest_{component}_provenance_invalid")
        if live.get("stable") is not True:
            raise EvidenceError(f"build_manifest_{component}_repo_unstable")
        live_commit = _commit_sha(
            live.get("commit"),
            f"build_manifest.live_provenance.{component}.commit",
        )
        for field in ("source", "repo_root"):
            if live.get(field) != declared[field]:
                raise EvidenceError(f"build_manifest_{component}_{field}_mismatch")
        if live_commit != declared["commit"]:
            raise EvidenceError(f"build_manifest_{component}_commit_mismatch")
        if component == "workspace":
            live_closure = _normalize_workspace_execution_closure(
                live.get("execution_closure"),
                repo_root=declared["repo_root"],
                commit=live_commit,
                field=(
                    "build_manifest.live_provenance.workspace.execution_closure"
                ),
            )
            live_closure_sha256 = _sha256_digest(
                live.get("execution_closure_sha256"),
                (
                    "build_manifest.live_provenance.workspace."
                    "execution_closure_sha256"
                ),
            )
            if (
                _sha256_json(live_closure) != live_closure_sha256
                or live_closure_sha256 != declared["execution_closure_sha256"]
                or live_closure != declared["execution_closure"]
            ):
                raise EvidenceError("build_manifest_workspace_closure_hash_mismatch")
            workspace_unscoped_drift = _normalize_unscoped_workspace_drift(
                live.get("unscoped_drift")
            )
            continue
        if live.get("tree_clean") is not True:
            raise EvidenceError(f"build_manifest_{component}_tree_dirty")
        live_status_sha256 = _sha256_digest(
            live.get("status_sha256"),
            f"build_manifest.live_provenance.{component}.status_sha256",
        )
        if live_status_sha256 != EMPTY_GIT_STATUS_SHA256:
            raise EvidenceError(f"build_manifest_{component}_tree_dirty")
        if component in expected_entrypoint_paths:
            live_tree = _git_object_id(
                live.get("tree"),
                f"build_manifest.live_provenance.{component}.tree",
            )
            live_entrypoint_path = _required_text(
                live.get("entrypoint_path"),
                f"build_manifest.live_provenance.{component}.entrypoint_path",
            )
            live_entrypoint_sha256 = _sha256_digest(
                live.get("entrypoint_sha256"),
                f"build_manifest.live_provenance.{component}.entrypoint_sha256",
            )
            live_entrypoint_committed_sha256 = _sha256_digest(
                live.get("entrypoint_committed_sha256"),
                (
                    f"build_manifest.live_provenance.{component}."
                    "entrypoint_committed_sha256"
                ),
            )
            live_entrypoint_blob = _git_object_id(
                live.get("entrypoint_blob"),
                f"build_manifest.live_provenance.{component}.entrypoint_blob",
            )
            live_entrypoint_git_mode = _required_text(
                live.get("entrypoint_git_mode"),
                (
                    f"build_manifest.live_provenance.{component}."
                    "entrypoint_git_mode"
                ),
            )
            if live_entrypoint_path != declared["entrypoint_path"]:
                raise EvidenceError(
                    f"build_manifest_{component}_entrypoint_path_mismatch"
                )
            if live_entrypoint_sha256 != declared["entrypoint_sha256"]:
                raise EvidenceError(
                    f"build_manifest_{component}_entrypoint_hash_mismatch"
                )
            if (
                live_tree != declared["tree"]
                or live_entrypoint_committed_sha256
                != declared["entrypoint_committed_sha256"]
                or live_entrypoint_blob != declared["entrypoint_blob"]
                or live_entrypoint_git_mode != declared["entrypoint_git_mode"]
            ):
                raise EvidenceError(
                    f"build_manifest_{component}_entrypoint_provenance_mismatch"
                )
    if workspace_unscoped_drift is None:
        raise EvidenceError("build_manifest_workspace_unscoped_drift_invalid")
    live_external_dependencies = _normalize_external_dependencies(
        live_provenance.get("external_dependencies"),
        field="build_manifest.live_provenance.external_dependencies",
    )
    for name in sorted(EXTERNAL_RELEASE_DEPENDENCIES):
        if live_external_dependencies[name] != declared_external_dependencies[name]:
            raise EvidenceError(f"build_manifest_external_{name}_drift")
    return {
        "observed_at": observed_at,
        "release_bom_sha256": release_bom_sha256,
        "host_commit": declared_components["host"]["commit"],
        "workspace_commit": declared_components["workspace"]["commit"],
        "vm_commit": declared_components["vm"]["commit"],
        "vm_tree": declared_components["vm"]["tree"],
        "vm_worker_commit": declared_components["vm_worker"]["commit"],
        "vm_service_entrypoint_sha256": declared_components["vm"]["entrypoint_sha256"],
        "vm_worker_entrypoint_sha256": declared_components["vm_worker"][
            "entrypoint_sha256"
        ],
        "workspace_runtime_sha256": _sha256_json(workspace_runtime_binding),
        "future_runtime_sha256": _sha256_json(future_runtime_binding),
        "auxiliary_runtime": _auxiliary_runtime_expectations(
            future_runtime_binding
        ),
        "runtime_config_sha256": runtime_config_sha256,
        "launchd_config_sha256": launchd_config_sha256,
        "provenance_sources": {
            component: declared_components[component]["source"]
            for component in sorted(expected_component_names)
        },
        "full_tree_clean": {
            component: True for component in ("host", "vm", "vm_worker")
        },
        "scoped_execution_clean": {
            "workspace": True,
        },
        "workspace_governance": {
            "schema_version": WORKSPACE_GOVERNANCE_SCHEMA_VERSION,
            "execution_closure": {
                "ok": True,
                "hash": declared_components["workspace"][
                    "execution_closure_sha256"
                ],
                "required_paths": list(
                    WORKSPACE_EXECUTION_CLOSURE_RELATIVE_PATHS
                ),
                "commit": declared_components["workspace"]["commit"],
                "files": {
                    relative: item["sha256"]
                    for relative, item in declared_components["workspace"][
                        "execution_closure"
                    ]["files"].items()
                },
            },
            "unscoped_drift": workspace_unscoped_drift,
        },
        "external_dependencies": declared_external_dependencies,
        "critical_file_count": len(resolved),
        "critical_files_sha256": critical_files_sha256,
        "critical_file_sha256": {
            name: digest for name, (_, digest) in sorted(resolved.items())
        },
        "canary_collector_sha256": resolved[CANARY_COLLECTOR_RELATIVE_PATH][1],
        "dependency_versions": EXPECTED_DEPENDENCY_VERSIONS,
    }


def _migration_duration(value: Any, field: str) -> float:
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(float(value))
        or float(value) < 0
    ):
        raise EvidenceError("store_migration_duration_invalid", field)
    return float(value)


def _migration_work_dir(value: Any) -> Path:
    raw = Path(_required_text(value, "store_migration_receipt.work_dir"))
    if not raw.is_absolute() or ".." in raw.parts or "\x00" in str(raw):
        raise EvidenceError("store_migration_work_dir_invalid")
    try:
        info = raw.lstat()
        resolved = raw.resolve(strict=True)
    except OSError as exc:
        raise EvidenceError("store_migration_work_dir_invalid") from exc
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
        raise EvidenceError("store_migration_work_dir_invalid")
    return resolved


def _migration_declared_file_observation(
    value: Any,
    *,
    field: str,
) -> tuple[dict[str, Any], Path]:
    declared = _mapping(value, field)
    if set(declared) != {
        "path",
        "device",
        "inode",
        "size_bytes",
        "mtime_ns",
        "sha256",
    }:
        raise EvidenceError("store_migration_artifact_shape_invalid")
    raw_path = Path(_required_text(declared.get("path"), f"{field}.path"))
    if not raw_path.is_absolute() or ".." in raw_path.parts or "\x00" in str(raw_path):
        raise EvidenceError("store_migration_artifact_path_invalid")
    normalized = {
        "path": str(raw_path),
        "device": _exact_int(declared.get("device"), f"{field}.device", minimum=1),
        "inode": _exact_int(declared.get("inode"), f"{field}.inode", minimum=1),
        "size_bytes": _exact_int(
            declared.get("size_bytes"), f"{field}.size_bytes", minimum=1
        ),
        "mtime_ns": _exact_int(
            declared.get("mtime_ns"), f"{field}.mtime_ns", minimum=1
        ),
        "sha256": _sha256_digest(declared.get("sha256"), f"{field}.sha256"),
    }
    return normalized, raw_path


def _migration_file_observation(
    value: Any,
    *,
    field: str,
    work_dir: Path | None,
) -> tuple[dict[str, Any], Path]:
    normalized, raw_path = _migration_declared_file_observation(
        value,
        field=field,
    )
    try:
        actual = observe_regular_file(raw_path)
    except MigrationDrillError as exc:
        raise EvidenceError("store_migration_artifact_invalid") from exc
    resolved = Path(str(actual["path"]))
    if work_dir is not None:
        try:
            resolved.relative_to(work_dir)
        except ValueError as exc:
            raise EvidenceError("store_migration_artifact_outside_work_dir") from exc
    if actual != normalized:
        raise EvidenceError("store_migration_artifact_identity_mismatch")
    return actual, resolved


def _migration_sqlite_validation(
    value: Any,
    *,
    path: Path,
    roles: Sequence[str],
    field: str,
) -> dict[str, Any]:
    declared = _mapping(value, field)
    try:
        actual = inspect_sqlite_read_only(path, roles)
    except MigrationDrillError as exc:
        raise EvidenceError("store_migration_sqlite_validation_failed") from exc
    if declared != actual:
        raise EvidenceError("store_migration_sqlite_validation_mismatch")
    return actual


def _migration_artifact(
    value: Any,
    *,
    roles: Sequence[str],
    field: str,
    work_dir: Path,
) -> tuple[dict[str, Any], dict[str, Any], Path]:
    item = _mapping(value, field)
    if set(item) not in (
        {"artifact", "validation"},
        {"artifact", "validation", "schema_transitions"},
    ):
        raise EvidenceError("store_migration_artifact_receipt_shape_invalid")
    if "schema_transitions" in item:
        expected_transitions = {
            role: {
                "from": (
                    CONTROL_PREDECESSOR_SCHEMA_VERSION
                    if role == "control"
                    else DELIVERY_PREDECESSOR_SCHEMA_VERSION
                ),
                "to": (
                    CONTROL_STORE_SCHEMA_VERSION
                    if role == "control"
                    else DELIVERY_STORE_SCHEMA_VERSION
                ),
            }
            for role in roles
        }
        if item.get("schema_transitions") != expected_transitions:
            raise EvidenceError("store_migration_schema_transitions_invalid")
    artifact, path = _migration_file_observation(
        item.get("artifact"),
        field=f"{field}.artifact",
        work_dir=work_dir,
    )
    validation = _migration_sqlite_validation(
        item.get("validation"),
        path=path,
        roles=roles,
        field=f"{field}.validation",
    )
    verified_again, verified_path = _migration_file_observation(
        item.get("artifact"),
        field=f"{field}.artifact",
        work_dir=work_dir,
    )
    if verified_again != artifact or verified_path != path:
        raise EvidenceError("store_migration_artifact_identity_mismatch")
    return artifact, validation, path


def _migration_source_bundle(
    value: Any,
    *,
    field: str,
    expected_database_identity: Mapping[str, Any] | None,
) -> dict[str, Any]:
    bundle = _mapping(value, field)
    sidecars = ("wal", "shm", "journal")
    if set(bundle) != {"database", *sidecars}:
        raise EvidenceError("store_migration_source_bundle_invalid")
    normalized: dict[str, Any] = {}
    for name in ("database", *sidecars):
        item = _mapping(bundle.get(name), f"{field}.{name}")
        if set(item) != {"present", "identity"} or not isinstance(
            item.get("present"), bool
        ):
            raise EvidenceError("store_migration_source_bundle_invalid")
        present = bool(item["present"])
        identity = item.get("identity")
        if present:
            declared, _ = _migration_declared_file_observation(
                identity,
                field=f"{field}.{name}.identity",
            )
        elif identity is None:
            declared = None
        else:
            raise EvidenceError("store_migration_source_bundle_invalid")
        normalized[name] = {"present": present, "identity": declared}
    expected_present = expected_database_identity is not None
    if (
        normalized["database"]["present"] is not expected_present
        or normalized["database"]["identity"] != expected_database_identity
        or any(
            normalized[name] != {"present": False, "identity": None}
            for name in sidecars
        )
    ):
        raise EvidenceError("store_migration_source_bundle_invalid")
    return normalized


def _migration_writer_backup_probe(value: Any, *, field: str) -> dict[str, Any]:
    probe = _mapping(value, field)
    if set(probe) != {"process_probe", "before", "after"}:
        raise EvidenceError("store_migration_writer_probe_invalid")
    if probe.get("process_probe") != WRITER_PROCESS_PROBE:
        raise EvidenceError("store_migration_writer_probe_invalid")
    try:
        before = validate_writer_process_probe_result(
            _mapping(probe.get("before"), f"{field}.before")
        )
        after = validate_writer_process_probe_result(
            _mapping(probe.get("after"), f"{field}.after")
        )
    except MigrationDrillError as exc:
        raise EvidenceError("store_migration_writer_probe_invalid") from exc
    return {
        "process_probe": WRITER_PROCESS_PROBE,
        "before": before,
        "after": after,
    }


def _expected_control_v9_activation_structure(
    *, present: bool
) -> dict[str, Any]:
    return {
        "tables": sorted(CONTROL_V9_ACTIVATION_TABLES) if present else [],
        "indexes": sorted(CONTROL_V9_ACTIVATION_INDEXES) if present else [],
        "columns": {
            table: sorted(columns) if present else []
            for table, columns in CONTROL_V9_ACTIVATION_COLUMNS.items()
        },
    }


def _check_migration_target_structure(
    validation: Mapping[str, Any],
    *,
    roles: Sequence[str],
) -> None:
    expected_schemas = {
        role: (
            CONTROL_STORE_SCHEMA_VERSION
            if role == "control"
            else DELIVERY_STORE_SCHEMA_VERSION
        )
        for role in roles
    }
    if validation.get("schemas") != expected_schemas:
        raise EvidenceError("store_migration_target_schema_mismatch")
    structure = _mapping(
        validation.get("structure"), "store_migration.restore.structure"
    )
    if "control" in roles:
        if set(structure.get("control_v8_indexes") or []) != set(
            CONTROL_V8_BASELINE_INDEXES
        ):
            raise EvidenceError("store_migration_target_schema_mismatch")
        if structure.get("control_v9_activation") != (
            _expected_control_v9_activation_structure(present=True)
        ):
            raise EvidenceError("store_migration_target_schema_mismatch")
    if "delivery" in roles and structure.get("delivery_task_id_notnull") != 0:
        raise EvidenceError("store_migration_target_schema_mismatch")
    if structure.get("host_runtime_transitions") != {
        "present": True,
        "columns": sorted(HOST_RUNTIME_TRANSITION_COLUMNS),
        "submission_index": ["submission_key", "transition_id"],
    }:
        raise EvidenceError("store_migration_target_schema_mismatch")


def _check_migration_predecessor_structure(
    validation: Mapping[str, Any],
    *,
    roles: Sequence[str],
) -> None:
    expected_schemas = {
        role: (
            CONTROL_PREDECESSOR_SCHEMA_VERSION
            if role == "control"
            else DELIVERY_PREDECESSOR_SCHEMA_VERSION
        )
        for role in roles
    }
    structure = _mapping(
        validation.get("structure"), "store_migration.predecessor.structure"
    )
    if validation.get("schemas") != expected_schemas:
        raise EvidenceError("store_migration_predecessor_drill_invalid")
    if "control" in roles:
        if set(structure.get("control_v8_indexes") or []) != set(
            CONTROL_V8_BASELINE_INDEXES
        ):
            raise EvidenceError("store_migration_predecessor_drill_invalid")
        if structure.get("control_v9_activation") != (
            _expected_control_v9_activation_structure(present=False)
        ):
            raise EvidenceError("store_migration_predecessor_drill_invalid")
    if "delivery" in roles and structure.get("delivery_task_id_notnull") != 0:
        raise EvidenceError("store_migration_predecessor_drill_invalid")
    transition_present = "control" in roles
    if structure.get("host_runtime_transitions") != {
        "present": transition_present,
        "columns": (
            sorted(HOST_RUNTIME_TRANSITION_COLUMNS) if transition_present else []
        ),
        "submission_index": (
            ["submission_key", "transition_id"] if transition_present else []
        ),
    }:
        raise EvidenceError("store_migration_predecessor_drill_invalid")


def _check_migration_supported_pre_structure(
    validation: Mapping[str, Any],
    *,
    roles: Sequence[str],
) -> None:
    schemas = _mapping(validation.get("schemas"), "store_migration.pre.schemas")
    structure = _mapping(validation.get("structure"), "store_migration.pre.structure")
    if "control" in roles:
        if set(structure.get("control_v8_indexes") or []) != set(
            CONTROL_V8_BASELINE_INDEXES
        ):
            raise EvidenceError("store_migration_pre_schema_structure_invalid")
        activation_present = schemas.get("control") == CONTROL_STORE_SCHEMA_VERSION
        if structure.get("control_v9_activation") != (
            _expected_control_v9_activation_structure(
                present=activation_present
            )
        ):
            raise EvidenceError("store_migration_pre_schema_structure_invalid")
    current = any(
        schemas.get(role)
        == (
            CONTROL_STORE_SCHEMA_VERSION
            if role == "control"
            else DELIVERY_STORE_SCHEMA_VERSION
        )
        for role in roles
    )
    predecessor = any(
        schemas.get(role)
        == (
            CONTROL_PREDECESSOR_SCHEMA_VERSION
            if role == "control"
            else DELIVERY_PREDECESSOR_SCHEMA_VERSION
        )
        for role in roles
    )
    transition_present = "control" in roles or current
    expected_transition = {
        "present": transition_present,
        "columns": (
            sorted(HOST_RUNTIME_TRANSITION_COLUMNS) if transition_present else []
        ),
        "submission_index": (
            ["submission_key", "transition_id"] if transition_present else []
        ),
    }
    if current and predecessor:
        raise EvidenceError("store_migration_pre_schema_structure_invalid")
    if structure.get("host_runtime_transitions") != expected_transition:
        raise EvidenceError("store_migration_pre_schema_structure_invalid")


def _check_migration_predecessor_validator(
    value: Any,
    *,
    candidate: Mapping[str, Any],
) -> dict[str, Any] | None:
    manifest = _mapping(value, "store_migration.predecessor_validator")
    if manifest == {
        "status": "not_configured",
        "protocol": PREDECESSOR_COMPATIBILITY_PROBE,
    }:
        return None
    if set(manifest) != {
        "status",
        "protocol",
        "artifact",
        "executable_mode",
        "owner_uid",
        "owner_gid",
        "link_count",
        "bom_binding",
    }:
        raise EvidenceError("store_migration_predecessor_validator_invalid")
    artifact = _mapping(
        manifest.get("artifact"),
        "store_migration.predecessor_validator.artifact",
    )
    try:
        live = _git_committed_executable(
            _required_text(
                artifact.get("path"),
                "store_migration.predecessor_validator.artifact.path",
            ),
            candidate=candidate,
        )
    except MigrationDrillError as exc:
        raise EvidenceError("store_migration_predecessor_validator_invalid") from exc
    if live != manifest:
        raise EvidenceError("store_migration_predecessor_validator_mismatch")
    return live


def _check_migration_predecessor_execution(
    value: Any,
    *,
    validator: Mapping[str, Any],
    rollback_artifact: Mapping[str, Any],
    rollback_path: Path,
    roles: Sequence[str],
    work_dir: Path,
    receipt_observed_at: datetime,
) -> dict[str, Any]:
    execution = _mapping(value, "store_migration.rollback.predecessor_execution")
    if set(execution) != {
        "schema_version",
        "observed_at",
        "protocol",
        "artifact_sha256",
        "database_artifact_before",
        "database_bundle_before",
        "database_bundle_after",
        "runtime",
        "exit_code",
        "duration_ms",
        "stdout_size_bytes",
        "stdout_sha256",
        "stderr_size_bytes",
        "stderr_sha256",
        "read_only_result",
    }:
        raise EvidenceError("store_migration_predecessor_execution_invalid")
    if (
        execution.get("schema_version")
        != "pnc_rca_predecessor_validator_execution_v1"
        or execution.get("protocol") != PREDECESSOR_COMPATIBILITY_PROBE
        or execution.get("artifact_sha256")
        != _mapping(validator.get("artifact"), "validator.artifact").get("sha256")
        or execution.get("database_artifact_before") != rollback_artifact
        or _exact_int(execution.get("exit_code"), "validator.exit_code") != 0
    ):
        raise EvidenceError("store_migration_predecessor_execution_invalid")
    observed_at = _timestamp(
        execution.get("observed_at"),
        "store_migration.rollback.predecessor_execution.observed_at",
    )
    if observed_at > receipt_observed_at:
        raise EvidenceError("store_migration_predecessor_execution_invalid")
    before_bundle = _migration_source_bundle(
        execution.get("database_bundle_before"),
        field="store_migration.rollback.predecessor_execution.database_bundle_before",
        expected_database_identity=rollback_artifact,
    )
    after_bundle = _migration_source_bundle(
        execution.get("database_bundle_after"),
        field="store_migration.rollback.predecessor_execution.database_bundle_after",
        expected_database_identity=rollback_artifact,
    )
    try:
        live_bundle = observe_sqlite_bundle(rollback_path)
    except MigrationDrillError as exc:
        raise EvidenceError("store_migration_predecessor_execution_invalid") from exc
    if before_bundle != after_bundle or after_bundle != live_bundle:
        raise EvidenceError("store_migration_predecessor_execution_invalid")
    expected_schemas = {
        role: (
            CONTROL_PREDECESSOR_SCHEMA_VERSION
            if role == "control"
            else DELIVERY_PREDECESSOR_SCHEMA_VERSION
        )
        for role in roles
    }
    expected_result = {
        "schema_version": PREDECESSOR_VALIDATOR_RESULT_SCHEMA_VERSION,
        "ok": True,
        "read_only": True,
        "side_effects": "none",
        "database_sha256": rollback_artifact["sha256"],
        "roles": list(roles),
        "schemas": expected_schemas,
        "quick_check": "ok",
        "foreign_key_check_rows": 0,
        "write_probe": "blocked_readonly",
    }
    if execution.get("read_only_result") != expected_result:
        raise EvidenceError("store_migration_predecessor_execution_invalid")
    expected_stdout = (
        json.dumps(
            expected_result,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        )
        + "\n"
    ).encode("utf-8")
    if (
        _exact_int(
            execution.get("stdout_size_bytes"),
            "validator.stdout_size_bytes",
        )
        != len(expected_stdout)
        or _sha256_digest(execution.get("stdout_sha256"), "validator.stdout_sha256")
        != hashlib.sha256(expected_stdout).hexdigest()
        or _exact_int(
            execution.get("stderr_size_bytes"),
            "validator.stderr_size_bytes",
        )
        != 0
        or _sha256_digest(execution.get("stderr_sha256"), "validator.stderr_sha256")
        != hashlib.sha256(b"").hexdigest()
    ):
        raise EvidenceError("store_migration_predecessor_execution_invalid")
    runtime = _mapping(execution.get("runtime"), "validator.runtime")
    if set(runtime) != {
        "child_pid",
        "parent_pid",
        "uid",
        "gid",
        "cwd",
        "platform",
        "machine",
        "argv",
        "argv_sha256",
        "environment_sha256",
    }:
        raise EvidenceError("store_migration_predecessor_execution_invalid")
    expected_argv = [
        str(_mapping(validator.get("artifact"), "validator.artifact")["path"]),
        "--database",
        str(rollback_path),
        "--roles-json",
        json.dumps(list(roles), ensure_ascii=True, separators=(",", ":")),
        "--expected-schemas-json",
        json.dumps(
            expected_schemas,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ),
    ]
    expected_environment = {
        "HOME": str(work_dir),
        "LANG": "C",
        "LC_ALL": "C",
        "PATH": "/usr/bin:/bin:/usr/sbin:/sbin",
    }
    if (
        _exact_int(runtime.get("child_pid"), "validator.child_pid", minimum=1) < 1
        or _exact_int(runtime.get("parent_pid"), "validator.parent_pid", minimum=1) < 1
        or _exact_int(runtime.get("uid"), "validator.uid") != os.getuid()
        or _exact_int(runtime.get("gid"), "validator.gid") != os.getgid()
        or runtime.get("cwd") != str(work_dir)
        or runtime.get("platform") != sys.platform
        or runtime.get("machine") != platform.machine()
        or runtime.get("argv") != expected_argv
        or _sha256_digest(runtime.get("argv_sha256"), "validator.argv_sha256")
        != _sha256_json(expected_argv)
        or _sha256_digest(
            runtime.get("environment_sha256"), "validator.environment_sha256"
        )
        != _sha256_json(expected_environment)
    ):
        raise EvidenceError("store_migration_predecessor_execution_invalid")
    _migration_duration(execution.get("duration_ms"), "validator.duration_ms")
    return dict(execution)


def _check_fresh_install_runtime_identity(
    value: Any,
    *,
    field: str,
) -> dict[str, Any]:
    identity = _mapping(value, field)
    if set(identity) != {
        "schema_version",
        "uid",
        "gid",
        "pid",
        "process_create_time",
        "executable_path",
        "executable_sha256",
        "argv_sha256",
    }:
        raise EvidenceError("fresh_install_runtime_identity_invalid")
    process_create_time = identity.get("process_create_time")
    executable_path = Path(
        _required_text(identity.get("executable_path"), f"{field}.executable_path")
    )
    if (
        identity.get("schema_version")
        != FRESH_INSTALL_RUNTIME_IDENTITY_SCHEMA_VERSION
        or _exact_int(identity.get("uid"), f"{field}.uid", minimum=0)
        != os.getuid()
        or _exact_int(identity.get("gid"), f"{field}.gid", minimum=0)
        != os.getgid()
        or _exact_int(identity.get("pid"), f"{field}.pid", minimum=1) < 1
        or isinstance(process_create_time, bool)
        or not isinstance(process_create_time, (int, float))
        or not math.isfinite(float(process_create_time))
        or float(process_create_time) <= 0
        or not executable_path.is_absolute()
        or ".." in executable_path.parts
    ):
        raise EvidenceError("fresh_install_runtime_identity_invalid")
    _sha256_digest(identity.get("executable_sha256"), f"{field}.executable_sha256")
    _sha256_digest(identity.get("argv_sha256"), f"{field}.argv_sha256")
    return dict(identity)


def _check_fresh_install_materialization(
    value: Any,
    *,
    raw_sha256: str,
    migration_raw_sha256: str,
    migration_observed_at: datetime,
    migration_drills: Sequence[Mapping[str, Any]],
    dispatcher: DispatcherConfig,
    candidate_commit: str,
    expected_config_sha256: str,
    activation: Mapping[str, Any] | None,
    work_dir: Path,
    now: datetime,
    max_age_seconds: int,
    release_mode: str,
) -> dict[str, Any]:
    receipt = _mapping(value, "fresh_install_materialization_receipt")
    if set(receipt) != {
        "schema_version",
        "observed_at",
        "ok",
        "migration_receipt",
        "genesis_intent",
        "parent_directory",
        "installation_lock",
        "destination_absence_before",
        "writer_stop_evidence",
        "process_probes",
        "strategy",
        "migration_receipt_raw_sha256",
        "candidate_commit",
        "config_sha256",
        "configured_databases",
        "genesis_intent_sha256",
        "db_instance_id",
        "audit",
        "capacity_identity",
        "capacity_transition",
        "capacity_initialization_receipt",
        "started_at",
        "completed_at",
        "runtime_identities",
        "materialization_journal",
        "destination",
        "rollback_contract",
        "materialization_binding_sha256",
    }:
        raise EvidenceError("fresh_install_materialization_receipt_shape_invalid")
    if (
        receipt.get("schema_version")
        != FRESH_INSTALL_MATERIALIZATION_RECEIPT_SCHEMA_VERSION
        or receipt.get("ok") is not True
        or receipt.get("strategy") != "fresh_install_preserve"
        or receipt.get("migration_receipt_raw_sha256") != migration_raw_sha256
        or receipt.get("candidate_commit") != candidate_commit
        or receipt.get("config_sha256") != expected_config_sha256
        or receipt.get("rollback_contract")
        != {
            "action": "disable_writers_and_preserve_store",
            "destructive_cleanup_allowed": False,
            "quarantine_before_replacement_required": True,
        }
    ):
        raise EvidenceError("fresh_install_materialization_receipt_invalid")
    materialized_at = _timestamp(
        receipt.get("observed_at"), "fresh_install_materialization.observed_at"
    )
    started_at = _timestamp(
        receipt.get("started_at"), "fresh_install_materialization.started_at"
    )
    completed_at = _timestamp(
        receipt.get("completed_at"), "fresh_install_materialization.completed_at"
    )
    activation_binding = activation or {}
    activation_created_at = (
        _timestamp(activation_binding.get("created_at"), "activation.created_at")
        if activation_binding
        else now.astimezone(timezone.utc)
    )
    if not activation_binding and release_mode != "preauthorization":
        raise EvidenceError("fresh_install_activation_binding_missing")
    if (
        not (
            migration_observed_at
            <= started_at
            <= completed_at
            == materialized_at
            <= activation_created_at
        )
        or (materialized_at - migration_observed_at).total_seconds()
        > max_age_seconds
        or (activation_created_at - materialized_at).total_seconds()
        > max_age_seconds
        or (completed_at - started_at).total_seconds() > max_age_seconds
        or (
            release_mode in {"preauthorization", "preproduction"}
            and (now.astimezone(timezone.utc) - materialized_at).total_seconds()
            > max_age_seconds
        )
        or (now.astimezone(timezone.utc) - materialized_at).total_seconds()
        < -MAX_HEALTH_FUTURE_SKEW_SECONDS
    ):
        raise EvidenceError("fresh_install_materialization_timeline_invalid")
    migration_observation, migration_path = _migration_declared_file_observation(
        receipt.get("migration_receipt"),
        field="fresh_install_materialization.migration_receipt",
    )
    if (
        migration_observation.get("sha256") != migration_raw_sha256
        or migration_path.name != "store_migration_receipt.json"
    ):
        raise EvidenceError("fresh_install_migration_receipt_binding_invalid")
    intent_observation, intent_path = _migration_declared_file_observation(
        receipt.get("genesis_intent"),
        field="fresh_install_materialization.genesis_intent",
    )
    try:
        intent, intent_raw, live_intent_observation = _read_json_regular_file(intent_path)
    except MigrationDrillError as exc:
        raise EvidenceError("fresh_install_genesis_intent_invalid") from exc
    if live_intent_observation != intent_observation or set(intent) != {
        "schema_version",
        "created_at",
        "db_instance_id",
        "configured_database",
        "migration_receipt_raw_sha256",
        "seed_sha256",
        "candidate_commit",
        "config_sha256",
        "journal_id",
        "maintenance_token_sha256",
        "audit",
        "capacity_identity",
    }:
        raise EvidenceError("fresh_install_genesis_intent_invalid")
    try:
        uuid.UUID(str(intent.get("db_instance_id") or ""))
    except ValueError as exc:
        raise EvidenceError("fresh_install_genesis_intent_invalid") from exc
    intent_sha256 = hashlib.sha256(intent_raw).hexdigest()
    intent_created_at = _timestamp(
        intent.get("created_at"), "fresh_install.genesis_intent.created_at"
    )
    if (
        intent.get("schema_version") != "pnc_rca_fresh_install_genesis_intent_v1"
        or intent.get("migration_receipt_raw_sha256") != migration_raw_sha256
        or intent.get("candidate_commit") != candidate_commit
        or intent.get("config_sha256") != expected_config_sha256
        or intent.get("db_instance_id") != receipt.get("db_instance_id")
        or intent.get("capacity_identity") != receipt.get("capacity_identity")
        or receipt.get("genesis_intent_sha256") != intent_sha256
        or intent_created_at != started_at
    ):
        raise EvidenceError("fresh_install_genesis_intent_invalid")
    expected_configured = {
        "control": str(dispatcher.control_db_path.expanduser().resolve(strict=False)),
        "delivery": str(dispatcher.delivery_db_path.expanduser().resolve(strict=False)),
        "same_database": (
            dispatcher.control_db_path.expanduser().resolve(strict=False)
            == dispatcher.delivery_db_path.expanduser().resolve(strict=False)
        ),
    }
    if receipt.get("configured_databases") != expected_configured:
        raise EvidenceError("fresh_install_configured_database_mismatch")
    configured_path = expected_configured["control"]
    if (
        expected_configured["same_database"] is not True
        or intent.get("configured_database") != configured_path
    ):
        raise EvidenceError("fresh_install_configured_database_mismatch")
    audit = _mapping(receipt.get("audit"), "fresh_install.audit")
    if set(audit) != {
        "release_id_sha256",
        "operator_sha256",
        "reason_sha256",
    }:
        raise EvidenceError("fresh_install_audit_invalid")
    for name in audit:
        _sha256_digest(audit.get(name), f"fresh_install.audit.{name}")
    if intent.get("audit") != audit:
        raise EvidenceError("fresh_install_audit_invalid")
    runtime_identities = _mapping(
        receipt.get("runtime_identities"), "fresh_install.runtime_identities"
    )
    if set(runtime_identities) != {"started", "completed"}:
        raise EvidenceError("fresh_install_runtime_identity_invalid")
    started_runtime = _check_fresh_install_runtime_identity(
        runtime_identities.get("started"),
        field="fresh_install.runtime_identities.started",
    )
    completed_runtime = _check_fresh_install_runtime_identity(
        runtime_identities.get("completed"),
        field="fresh_install.runtime_identities.completed",
    )
    journal = _mapping(
        receipt.get("materialization_journal"),
        "fresh_install.materialization_journal",
    )
    if set(journal) != {
        "schema_version",
        "journal_id",
        "maintenance_path",
        "maintenance_token_sha256",
        "prepared",
        "installed",
    }:
        raise EvidenceError("fresh_install_journal_invalid")
    journal_id = _sha256_digest(
        journal.get("journal_id"), "fresh_install.journal_id"
    )
    maintenance_token_sha256 = _sha256_digest(
        journal.get("maintenance_token_sha256"),
        "fresh_install.maintenance_token_sha256",
    )
    expected_maintenance_path = f"{configured_path}.pnc-rca-maintenance"
    if (
        journal.get("schema_version") != FRESH_INSTALL_JOURNAL_SCHEMA_VERSION
        or journal.get("maintenance_path") != expected_maintenance_path
        or intent.get("journal_id") != journal_id
        or intent.get("maintenance_token_sha256")
        != maintenance_token_sha256
    ):
        raise EvidenceError("fresh_install_journal_invalid")
    if Path(expected_maintenance_path).exists() or Path(
        expected_maintenance_path
    ).is_symlink():
        raise EvidenceError("fresh_install_maintenance_not_released")
    material = {
        key: receipt[key]
        for key in (
            "strategy",
            "migration_receipt_raw_sha256",
            "candidate_commit",
            "config_sha256",
            "configured_databases",
            "genesis_intent_sha256",
            "db_instance_id",
            "audit",
            "capacity_identity",
            "capacity_transition",
            "capacity_initialization_receipt",
            "started_at",
            "completed_at",
            "runtime_identities",
            "materialization_journal",
            "destination",
            "rollback_contract",
        )
    }
    material_sha256 = hashlib.sha256(
        (
            json.dumps(
                material,
                ensure_ascii=True,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            )
            + "\n"
        ).encode("utf-8")
    ).hexdigest()
    if receipt.get("materialization_binding_sha256") != material_sha256:
        raise EvidenceError("fresh_install_materialization_binding_invalid")
    phase_bodies: dict[str, dict[str, Any]] = {}
    phase_observations: dict[str, dict[str, Any]] = {}
    journal_root = intent_path.parent
    for phase in ("prepared", "installed"):
        declared_phase, phase_path = _migration_declared_file_observation(
            journal.get(phase),
            field=f"fresh_install.journal.{phase}",
        )
        if (
            phase_path.parent != journal_root
            or phase_path.name
            != f"fresh_install_materialization_journal.{journal_id}.{phase}.json"
        ):
            raise EvidenceError("fresh_install_journal_invalid")
        try:
            phase_body, _phase_raw, live_phase = _read_json_regular_file(
                phase_path
            )
        except MigrationDrillError as exc:
            raise EvidenceError("fresh_install_journal_invalid") from exc
        if live_phase != declared_phase:
            raise EvidenceError("fresh_install_journal_invalid")
        phase_bodies[phase] = phase_body
        phase_observations[phase] = live_phase
    prepared_phase = phase_bodies["prepared"]
    installed_phase = phase_bodies["installed"]
    if (
        set(prepared_phase)
        != {
            "schema_version",
            "phase",
            "journal_id",
            "maintenance_token_sha256",
            "started_at",
            "configured_database",
            "migration_receipt_raw_sha256",
            "candidate_commit",
            "config_sha256",
            "seed_sha256",
            "genesis_intent_sha256",
            "db_instance_id",
            "audit",
            "capacity_identity",
            "runtime_identity",
            "destination_absence_before",
        }
        or prepared_phase.get("schema_version")
        != FRESH_INSTALL_JOURNAL_SCHEMA_VERSION
        or prepared_phase.get("phase") != "prepared"
        or prepared_phase.get("journal_id") != journal_id
        or prepared_phase.get("maintenance_token_sha256")
        != maintenance_token_sha256
        or prepared_phase.get("started_at") != started_at.isoformat()
        or prepared_phase.get("configured_database") != configured_path
        or prepared_phase.get("migration_receipt_raw_sha256")
        != migration_raw_sha256
        or prepared_phase.get("candidate_commit") != candidate_commit
        or prepared_phase.get("config_sha256") != expected_config_sha256
        or prepared_phase.get("genesis_intent_sha256") != intent_sha256
        or prepared_phase.get("db_instance_id") != receipt.get("db_instance_id")
        or prepared_phase.get("audit") != audit
        or prepared_phase.get("capacity_identity")
        != receipt.get("capacity_identity")
        or prepared_phase.get("runtime_identity") != started_runtime
    ):
        raise EvidenceError("fresh_install_journal_invalid")
    if (
        set(installed_phase)
        != {
            "schema_version",
            "phase",
            "journal_id",
            "maintenance_token_sha256",
            "prepared_sha256",
            "installed_at",
            "destination_artifact",
            "genesis_intent_sha256",
            "db_instance_id",
            "capacity_identity",
            "capacity_transition",
            "capacity_initialization_receipt",
            "writer_stop_evidence",
            "process_probes",
            "runtime_identity",
        }
        or installed_phase.get("schema_version")
        != FRESH_INSTALL_JOURNAL_SCHEMA_VERSION
        or installed_phase.get("phase") != "installed"
        or installed_phase.get("journal_id") != journal_id
        or installed_phase.get("maintenance_token_sha256")
        != maintenance_token_sha256
        or installed_phase.get("prepared_sha256")
        != phase_observations["prepared"]["sha256"]
        or installed_phase.get("installed_at") != completed_at.isoformat()
        or installed_phase.get("genesis_intent_sha256") != intent_sha256
        or installed_phase.get("db_instance_id") != receipt.get("db_instance_id")
        or installed_phase.get("capacity_identity")
        != receipt.get("capacity_identity")
        or installed_phase.get("capacity_transition")
        != receipt.get("capacity_transition")
        or installed_phase.get("capacity_initialization_receipt")
        != receipt.get("capacity_initialization_receipt")
        or installed_phase.get("writer_stop_evidence")
        != receipt.get("writer_stop_evidence")
        or installed_phase.get("process_probes") != receipt.get("process_probes")
        or installed_phase.get("runtime_identity") != completed_runtime
    ):
        raise EvidenceError("fresh_install_journal_invalid")
    receipted_path = journal_root / (
        f"fresh_install_materialization_journal.{journal_id}.receipted.json"
    )
    try:
        receipted, _receipted_raw, _receipted_observation = (
            _read_json_regular_file(receipted_path)
        )
    except MigrationDrillError as exc:
        raise EvidenceError("fresh_install_journal_not_receipted") from exc
    receipt_observation = _mapping(
        receipted.get("receipt"), "fresh_install.journal.receipt"
    )
    declared_receipt, declared_receipt_path = (
        _migration_declared_file_observation(
            receipt_observation,
            field="fresh_install.journal.receipt",
        )
    )
    if (
        set(receipted)
        != {
            "schema_version",
            "phase",
            "journal_id",
            "maintenance_token_sha256",
            "installed_sha256",
            "receipt",
            "receipted_at",
            "maintenance_release_required",
        }
        or receipted.get("schema_version")
        != FRESH_INSTALL_JOURNAL_SCHEMA_VERSION
        or receipted.get("phase") != "receipted"
        or receipted.get("journal_id") != journal_id
        or receipted.get("maintenance_token_sha256")
        != maintenance_token_sha256
        or receipted.get("installed_sha256")
        != phase_observations["installed"]["sha256"]
        or receipted.get("receipted_at") != completed_at.isoformat()
        or receipted.get("maintenance_release_required") is not True
        or declared_receipt_path.parent != journal_root
        or declared_receipt_path.name
        != "fresh_install_materialization_receipt.json"
        or declared_receipt.get("sha256") != raw_sha256
    ):
        raise EvidenceError("fresh_install_journal_not_receipted")
    try:
        live_receipt, _live_receipt_raw, live_receipt_observation = (
            _read_json_regular_file(declared_receipt_path)
        )
    except MigrationDrillError as exc:
        raise EvidenceError("fresh_install_journal_not_receipted") from exc
    if live_receipt != receipt or live_receipt_observation != declared_receipt:
        raise EvidenceError("fresh_install_journal_not_receipted")
    if len(migration_drills) != 1:
        raise EvidenceError("fresh_install_materialization_destinations_invalid")
    drill = _mapping(migration_drills[0], "fresh_install.migration_drill")
    roles = tuple(str(role) for role in drill.get("roles") or ())
    if roles != ("control", "delivery"):
        raise EvidenceError("fresh_install_materialization_destinations_invalid")
    seed = _mapping(drill.get("installation_seed"), "fresh_install.seed")
    seed_artifact, seed_validation, seed_path = _migration_artifact(
        seed,
        roles=roles,
        field="fresh_install.seed",
        work_dir=work_dir,
    )
    _check_migration_target_structure(seed_validation, roles=roles)
    destination = _mapping(receipt.get("destination"), "fresh_install.destination")
    if set(destination) != {
        "roles",
        "configured_path",
        "artifact",
        "state",
        "validation",
        "seed_sha256",
        "seed_inheritance",
        "genesis_meta",
    } or destination.get("roles") != list(roles) or destination.get(
        "configured_path"
    ) != configured_path or destination.get("seed_sha256") != seed_artifact[
        "sha256"
    ] or intent.get(
        "seed_sha256"
    ) != seed_artifact[
        "sha256"
    ] or prepared_phase.get(
        "seed_sha256"
    ) != seed_artifact[
        "sha256"
    ]:
        raise EvidenceError("fresh_install_materialization_destination_invalid")
    initial_artifact = _mapping(
        destination.get("artifact"), "fresh_install.initial_artifact"
    )
    if set(initial_artifact) != {
        "path",
        "device",
        "inode",
        "size_bytes",
        "mtime_ns",
        "sha256",
    } or initial_artifact.get("path") != configured_path:
        raise EvidenceError("fresh_install_initial_artifact_invalid")
    for field_name in ("device", "inode", "size_bytes", "mtime_ns"):
        _exact_int(
            initial_artifact.get(field_name),
            f"fresh_install.initial_artifact.{field_name}",
            minimum=0,
        )
    _sha256_digest(
        initial_artifact.get("sha256"), "fresh_install.initial_artifact.sha256"
    )
    if installed_phase.get("destination_artifact") != initial_artifact:
        raise EvidenceError("fresh_install_journal_invalid")
    state = _mapping(destination.get("state"), "fresh_install.destination.state")
    expected_state_keys = {"database", "wal", "shm", "journal", "tombstone"}
    if set(state) != expected_state_keys:
        raise EvidenceError("fresh_install_initial_bundle_invalid")
    for name in expected_state_keys:
        item = _mapping(state.get(name), f"fresh_install.destination.state.{name}")
        expected_path = (
            configured_path
            if name == "database"
            else (
                f"{configured_path}.pnc-rca-tombstone"
                if name == "tombstone"
                else f"{configured_path}-{name}"
            )
        )
        if (
            set(item) != {"path", "present", "identity"}
            or item.get("path") != expected_path
            or item.get("present") is not (name == "database")
            or item.get("identity")
            != (dict(initial_artifact) if name == "database" else None)
        ):
            raise EvidenceError("fresh_install_initial_bundle_invalid")
    absence = _mapping(
        receipt.get("destination_absence_before"),
        "fresh_install.destination_absence_before",
    )
    if set(absence) != expected_state_keys or any(
        not isinstance(absence[name], Mapping)
        or absence[name].get("present") is not False
        or absence[name].get("identity") is not None
        or absence[name].get("path") != state[name].get("path")
        for name in expected_state_keys
    ):
        raise EvidenceError("fresh_install_destination_absence_invalid")
    if prepared_phase.get("destination_absence_before") != absence:
        raise EvidenceError("fresh_install_journal_invalid")
    if destination.get("validation") != seed_validation:
        raise EvidenceError("fresh_install_initial_validation_invalid")
    live_path = Path(configured_path)
    live_sidecars = {
        "wal": Path(f"{configured_path}-wal"),
        "shm": Path(f"{configured_path}-shm"),
        "journal": Path(f"{configured_path}-journal"),
        "tombstone": Path(f"{configured_path}.pnc-rca-tombstone"),
    }
    if any(path.exists() or path.is_symlink() for path in live_sidecars.values()):
        raise EvidenceError("fresh_install_live_sidecar_present")
    try:
        live_artifact = observe_regular_file(live_path)
        live_validation = inspect_sqlite_read_only(live_path, roles)
        live_inheritance = compare_sqlite_common_content(seed_path, live_path)
        live_genesis_meta = _read_genesis_meta(live_path)
    except MigrationDrillError as exc:
        raise EvidenceError("fresh_install_live_continuity_invalid") from exc
    if (
        (live_artifact["device"], live_artifact["inode"])
        != (initial_artifact.get("device"), initial_artifact.get("inode"))
        or live_validation.get("schemas")
        != {
            "control": CONTROL_STORE_SCHEMA_VERSION,
            "delivery": DELIVERY_STORE_SCHEMA_VERSION,
        }
        or destination.get("seed_inheritance") != live_inheritance
        or destination.get("genesis_meta") != live_genesis_meta
    ):
        raise EvidenceError("fresh_install_live_continuity_invalid")
    expected_meta = {
        f"{prefix}.{key}": str(value)
        for prefix in ("control", "delivery")
        for key, value in (
            ("fresh_install_db_instance_id", receipt.get("db_instance_id")),
            ("fresh_install_genesis_intent_sha256", intent_sha256),
            ("fresh_install_origin_commit", candidate_commit),
        )
    }
    if live_genesis_meta != expected_meta:
        raise EvidenceError("fresh_install_genesis_meta_invalid")
    parent = _mapping(receipt.get("parent_directory"), "fresh_install.parent")
    lock = _mapping(receipt.get("installation_lock"), "fresh_install.lock")
    try:
        parent_stat = Path(str(parent.get("path") or "")).lstat()
        lock_stat = Path(str(lock.get("path") or "")).lstat()
    except OSError as exc:
        raise EvidenceError("fresh_install_installation_identity_invalid") from exc
    if (
        set(parent) != {"path", "device", "inode", "owner_uid", "mode"}
        or (parent_stat.st_dev, parent_stat.st_ino)
        != (parent.get("device"), parent.get("inode"))
        or parent_stat.st_uid != os.getuid()
        or parent.get("owner_uid") != os.getuid()
        or parent.get("mode") != f"{stat.S_IMODE(parent_stat.st_mode):04o}"
        or stat.S_IMODE(parent_stat.st_mode) & 0o022
        or set(lock)
        != {"path", "device", "inode", "owner_pid", "owner_uid", "mode"}
        or not stat.S_ISREG(lock_stat.st_mode)
        or lock_stat.st_uid != os.getuid()
        or lock_stat.st_nlink != 1
        or stat.S_IMODE(lock_stat.st_mode) != 0o600
        or lock.get("owner_uid") != os.getuid()
        or lock.get("mode") != "0600"
        or (lock_stat.st_dev, lock_stat.st_ino)
        != (lock.get("device"), lock.get("inode"))
        or _exact_int(lock.get("owner_pid"), "fresh_install.lock.owner_pid", minimum=1)
        < 1
    ):
        raise EvidenceError("fresh_install_installation_identity_invalid")
    writer_stop = _mapping(
        receipt.get("writer_stop_evidence"), "fresh_install.writer_stop_evidence"
    )
    try:
        normalized_writer_stop = validate_writer_stop_evidence(
            writer_stop,
            now=materialized_at,
            max_age_seconds=900,
        )
        probes = _mapping(receipt.get("process_probes"), "fresh_install.probes")
        if set(probes) != {
            "initial",
            "locked",
            "immediate_pre_install",
            "post_install",
        } or any(
            validate_writer_process_probe_result(_mapping(probes[name], name))
            != probes[name]
            for name in probes
        ):
            raise MigrationDrillError("writer_stop_process_probe_invalid")
    except MigrationDrillError as exc:
        raise EvidenceError("fresh_install_writer_stop_invalid") from exc
    if normalized_writer_stop != writer_stop:
        raise EvidenceError("fresh_install_writer_stop_invalid")
    live_databases = {
        role: {
            "path": configured_path,
            "device": live_artifact["device"],
            "inode": live_artifact["inode"],
            "schema_version": live_validation["schemas"][role],
            "db_instance_id": receipt.get("db_instance_id"),
            "genesis_intent_sha256": intent_sha256,
        }
        for role in roles
    }
    expected_db_identity = {
        "schema_version": "pnc_rca_activation_db_identity_v1",
        "strategy": "fresh_install_preserve",
        "databases": live_databases,
        "migration_receipt_raw_sha256": migration_raw_sha256,
        "materialization_receipt_raw_sha256": raw_sha256,
        "host_commit": candidate_commit,
        "config_sha256": expected_config_sha256,
    }
    return {
        "observed_at": materialized_at.isoformat(),
        "raw_sha256": raw_sha256,
        "expected_db_logical_identity": expected_db_identity,
        "expected_db_logical_identity_sha256": _sha256_json(expected_db_identity),
        "destination_count": 1,
        "rollback_strategy": "disable_writers_preserve_current_store_v1",
    }
    if (
        "delivery" in roles
        and schemas.get("delivery") == DELIVERY_STORE_SCHEMA_VERSION
        and structure.get("delivery_task_id_notnull") != 0
    ):
        raise EvidenceError("store_migration_pre_schema_structure_invalid")


def _existing_activation_database_identity(
    *,
    dispatcher: DispatcherConfig,
    migration_raw_sha256: str,
    candidate_commit: str,
    config_sha256: str,
) -> dict[str, Any]:
    configured = {
        "control": dispatcher.control_db_path.expanduser().absolute(),
        "delivery": dispatcher.delivery_db_path.expanduser().absolute(),
    }
    databases: dict[str, Any] = {}
    try:
        origin_lineage = _read_genesis_meta(configured["control"])
    except MigrationDrillError:
        origin_lineage = {}
    for role, path in configured.items():
        resolved, observed = _observe_live_database_identity(
            path,
            unreadable_code="activation_database_unreadable",
            invalid_code="activation_database_invalid",
        )
        connection: sqlite3.Connection | None = None
        try:
            connection = sqlite3.connect(
                resolved.as_uri() + "?mode=ro",
                uri=True,
                timeout=5,
            )
            connection.execute("PRAGMA query_only=ON")
            connection.execute("PRAGMA trusted_schema=OFF")
            table = "control_meta" if role == "control" else "rca_delivery_meta"
            row = connection.execute(
                f"SELECT value FROM {table} WHERE key = 'schema_version'"
            ).fetchone()
        except sqlite3.Error as exc:
            raise EvidenceError("activation_database_unreadable") from exc
        finally:
            if connection is not None:
                connection.close()
        expected_schema = (
            CONTROL_STORE_SCHEMA_VERSION
            if role == "control"
            else DELIVERY_STORE_SCHEMA_VERSION
        )
        if row is None or str(row[0]) != expected_schema:
            raise EvidenceError("activation_database_schema_mismatch")
        databases[role] = {
            "path": str(resolved),
            "device": int(observed.st_dev),
            "inode": int(observed.st_ino),
            "schema_version": expected_schema,
            "db_instance_id": origin_lineage.get(
                f"{role}.fresh_install_db_instance_id"
            ),
            "genesis_intent_sha256": origin_lineage.get(
                f"{role}.fresh_install_genesis_intent_sha256"
            ),
        }
    return {
        "schema_version": "pnc_rca_activation_db_identity_v1",
        "strategy": "existing_database_preserve",
        "databases": databases,
        "migration_receipt_raw_sha256": migration_raw_sha256,
        "materialization_receipt_raw_sha256": hashlib.sha256(b"").hexdigest(),
        "host_commit": candidate_commit,
        "config_sha256": config_sha256,
    }


def _existing_database_origin_lineage(path: Path) -> dict[str, str] | None:
    try:
        lineage = _read_genesis_meta(path.expanduser().absolute())
    except MigrationDrillError:
        return None
    expected_keys = {
        f"{role}.{field}"
        for role in ("control", "delivery")
        for field in (
            "fresh_install_db_instance_id",
            "fresh_install_genesis_intent_sha256",
            "fresh_install_origin_commit",
        )
    }
    if set(lineage) != expected_keys:
        return None
    try:
        for role in ("control", "delivery"):
            uuid.UUID(lineage[f"{role}.fresh_install_db_instance_id"])
            _sha256_digest(
                lineage[f"{role}.fresh_install_genesis_intent_sha256"],
                f"store_migration.{role}.genesis_intent_sha256",
            )
            _commit_sha(
                lineage[f"{role}.fresh_install_origin_commit"],
                f"store_migration.{role}.origin_commit",
            )
    except (EvidenceError, ValueError):
        return None
    if any(
        lineage[f"control.{field}"] != lineage[f"delivery.{field}"]
        for field in (
            "fresh_install_db_instance_id",
            "fresh_install_genesis_intent_sha256",
            "fresh_install_origin_commit",
        )
    ):
        return None
    return dict(lineage)


def _check_store_migration_receipt(
    body: Mapping[str, Any],
    *,
    dispatcher: DispatcherConfig,
    settings: ReleaseGateSettings,
    expected_host_commit: str,
    now: datetime,
    max_age_seconds: int,
    release_mode: str,
    migration_raw_sha256: str,
    materialization_receipt: Mapping[str, Any] | None,
    materialization_raw_sha256: str | None,
    capacity_initialization_receipt: Mapping[str, Any] | None,
    capacity_initialization_raw_sha256: str | None,
    activation: Mapping[str, Any] | None,
    expected_config_sha256: str | None = None,
) -> dict[str, Any]:
    artifact = "store_migration_receipt"
    _require_schema(body, STORE_MIGRATION_RECEIPT_SCHEMA_VERSION, artifact)
    if set(body) != {
        "schema_version",
        "observed_at",
        "ok",
        "mode",
        "migration_state",
        "rollback_strategy",
        "materialization_required",
        "rollback_ready",
        "blockers",
        "work_dir",
        "configured_databases",
        "candidate",
        "writer_stop_evidence",
        "database_drills",
        "schema_transitions",
        "compatibility_probe",
        "predecessor_validator",
        "duration_ms",
    }:
        raise EvidenceError("store_migration_receipt_shape_invalid")
    receipt_observed_at = _timestamp(
        body.get("observed_at"), "store_migration_receipt.observed_at"
    )
    age_seconds = (now.astimezone(timezone.utc) - receipt_observed_at).total_seconds()
    if age_seconds < -MAX_HEALTH_FUTURE_SKEW_SECONDS:
        raise EvidenceError("store_migration_receipt_from_future")
    if release_mode == "preproduction" and age_seconds > max_age_seconds:
        raise EvidenceError("store_migration_receipt_stale")
    observed_at = receipt_observed_at.isoformat()
    if body.get("ok") is not True:
        raise EvidenceError("store_migration_receipt_not_ok")
    mode = _required_text(body.get("mode"), "store_migration_receipt.mode")
    if mode not in {"existing", "fresh_create", "mixed"}:
        raise EvidenceError("store_migration_mode_invalid")
    if body.get("compatibility_probe") != PREDECESSOR_COMPATIBILITY_PROBE:
        raise EvidenceError("store_migration_compatibility_probe_invalid")
    declared_migration_state = _required_text(
        body.get("migration_state"), "store_migration_receipt.migration_state"
    )
    if declared_migration_state not in {
        "migration_required",
        "fresh_install",
        "already_current",
        "mixed",
    }:
        raise EvidenceError("store_migration_state_invalid")
    if not isinstance(body.get("rollback_ready"), bool):
        raise EvidenceError("store_migration_rollback_readiness_invalid")
    declared_blockers = body.get("blockers")
    if (
        not isinstance(declared_blockers, list)
        or declared_blockers != sorted(set(declared_blockers))
        or not all(isinstance(value, str) and value for value in declared_blockers)
    ):
        raise EvidenceError("store_migration_blockers_invalid")
    declared_rollback_strategy = _required_text(
        body.get("rollback_strategy"),
        "store_migration_receipt.rollback_strategy",
    )
    if not isinstance(body.get("materialization_required"), bool):
        raise EvidenceError("store_migration_materialization_state_invalid")
    expected_schema_transitions = {
        "control": {
            "from": CONTROL_PREDECESSOR_SCHEMA_VERSION,
            "to": CONTROL_STORE_SCHEMA_VERSION,
        },
        "delivery": {
            "from": DELIVERY_PREDECESSOR_SCHEMA_VERSION,
            "to": DELIVERY_STORE_SCHEMA_VERSION,
        },
    }
    if body.get("schema_transitions") != expected_schema_transitions:
        raise EvidenceError("store_migration_schema_transitions_invalid")
    duration_ms = _migration_duration(
        body.get("duration_ms"), "store_migration_receipt.duration_ms"
    )
    work_dir = _migration_work_dir(body.get("work_dir"))

    expected_control = dispatcher.control_db_path.expanduser().resolve(strict=False)
    expected_delivery = dispatcher.delivery_db_path.expanduser().resolve(strict=False)
    configured = _mapping(
        body.get("configured_databases"),
        "store_migration_receipt.configured_databases",
    )
    if set(configured) != {"control", "delivery", "same_database"}:
        raise EvidenceError("store_migration_configured_databases_shape_invalid")
    same_database = expected_control == expected_delivery
    if not same_database and expected_control.exists() and expected_delivery.exists():
        try:
            control_identity = observe_regular_file(expected_control)
            delivery_identity = observe_regular_file(expected_delivery)
        except MigrationDrillError as exc:
            raise EvidenceError("store_migration_configured_database_invalid") from exc
        if (
            control_identity["device"],
            control_identity["inode"],
        ) == (
            delivery_identity["device"],
            delivery_identity["inode"],
        ):
            raise EvidenceError("store_migration_configured_database_alias")
    for configured_path in {expected_control, expected_delivery}:
        try:
            configured_path.relative_to(work_dir)
        except ValueError:
            pass
        else:
            raise EvidenceError("store_migration_source_inside_work_dir")
    if configured != {
        "control": str(expected_control),
        "delivery": str(expected_delivery),
        "same_database": same_database,
    }:
        raise EvidenceError("store_migration_configured_database_mismatch")

    candidate = _mapping(body.get("candidate"), "store_migration_receipt.candidate")
    if set(candidate) != {"repo_root", "commit", "migration_sources"}:
        raise EvidenceError("store_migration_candidate_shape_invalid")
    try:
        expected_repo_root = settings.host_repo_root.expanduser().resolve(strict=True)
    except OSError as exc:
        raise EvidenceError("store_migration_candidate_repo_invalid") from exc
    if candidate.get("repo_root") != str(expected_repo_root):
        raise EvidenceError("store_migration_candidate_repo_mismatch")
    candidate_commit = _commit_sha(
        candidate.get("commit"), "store_migration_receipt.candidate.commit"
    )
    if not expected_host_commit:
        raise EvidenceError("store_migration_build_unverified")
    if candidate_commit != expected_host_commit:
        raise EvidenceError("store_migration_candidate_commit_mismatch")
    migration_sources = _mapping(
        candidate.get("migration_sources"),
        "store_migration_receipt.candidate.migration_sources",
    )
    if set(migration_sources) != set(MIGRATION_SOURCE_RELATIVE_PATHS):
        raise EvidenceError("store_migration_candidate_sources_invalid")
    for relative in MIGRATION_SOURCE_RELATIVE_PATHS:
        declared_sha = _sha256_digest(
            migration_sources.get(relative),
            f"store_migration_receipt.candidate.migration_sources.{relative}",
        )
        try:
            source_observation = observe_regular_file(expected_repo_root / relative)
        except MigrationDrillError as exc:
            raise EvidenceError("store_migration_candidate_source_invalid") from exc
        if source_observation["sha256"] != declared_sha:
            raise EvidenceError("store_migration_candidate_source_mismatch")
    predecessor_validator = _check_migration_predecessor_validator(
        body.get("predecessor_validator"),
        candidate=candidate,
    )

    writer_stop = _mapping(
        body.get("writer_stop_evidence"),
        "store_migration_receipt.writer_stop_evidence",
    )
    try:
        normalized_writer_stop = validate_writer_stop_evidence(
            writer_stop,
            now=receipt_observed_at,
            max_age_seconds=max_age_seconds,
        )
    except MigrationDrillError as exc:
        if exc.code == "writer_stop_evidence_service_not_stopped":
            raise EvidenceError("store_migration_writer_not_stopped") from exc
        raise EvidenceError("store_migration_writer_stop_evidence_invalid") from exc
    if normalized_writer_stop != writer_stop:
        raise EvidenceError("store_migration_writer_stop_evidence_invalid")
    if (
        normalized_writer_stop.get("process_probe") != WRITER_PROCESS_PROBE
        or set(normalized_writer_stop.get("services") or {}) != STORE_WRITER_LABELS
    ):
        raise EvidenceError("store_migration_writer_stop_evidence_invalid")
    writer_stop_observed_at = _timestamp(
        normalized_writer_stop.get("observed_at"),
        "store_migration.writer_stop_evidence.observed_at",
    )
    if writer_stop_observed_at > receipt_observed_at:
        raise EvidenceError("store_migration_writer_stop_evidence_invalid")
    probe_started_at = _timestamp(
        normalized_writer_stop.get("probe_started_at"),
        "store_migration.writer_stop_evidence.probe_started_at",
    )
    probe_completed_at = _timestamp(
        normalized_writer_stop.get("probe_completed_at"),
        "store_migration.writer_stop_evidence.probe_completed_at",
    )
    if (
        writer_stop_observed_at > probe_started_at
        or probe_started_at > probe_completed_at
        or probe_completed_at > receipt_observed_at
    ):
        raise EvidenceError("store_migration_writer_stop_evidence_invalid")
    for service in normalized_writer_stop["services"].values():
        if (
            _timestamp(
                service.get("observed_at"),
                "store_migration.writer_stop_evidence.service.observed_at",
            )
            > writer_stop_observed_at
        ):
            raise EvidenceError("store_migration_writer_stop_evidence_invalid")

    expected_groups: dict[str, tuple[str, ...]] = {}
    expected_groups.setdefault(str(expected_control), tuple())
    expected_groups[str(expected_control)] = (
        *expected_groups[str(expected_control)],
        "control",
    )
    expected_groups.setdefault(str(expected_delivery), tuple())
    expected_groups[str(expected_delivery)] = (
        *expected_groups[str(expected_delivery)],
        "delivery",
    )
    expected_groups = {
        path: tuple(sorted(roles)) for path, roles in expected_groups.items()
    }
    raw_drills = body.get("database_drills")
    if not isinstance(raw_drills, list) or len(raw_drills) != len(expected_groups):
        raise EvidenceError("store_migration_database_drills_invalid")
    seen_configured_paths: set[str] = set()
    seen_artifact_paths: set[str] = set()
    seen_artifact_identities: set[tuple[int, int]] = set()
    source_identities: set[tuple[int, int]] = set()
    observed_source_modes: set[str] = set()
    drill_details: list[dict[str, Any]] = []
    supported_schemas = {
        "control": {
            CONTROL_PREDECESSOR_SCHEMA_VERSION,
            CONTROL_STORE_SCHEMA_VERSION,
        },
        "delivery": {
            DELIVERY_PREDECESSOR_SCHEMA_VERSION,
            DELIVERY_STORE_SCHEMA_VERSION,
        },
    }

    def register_artifact(observation: Mapping[str, Any], path: Path) -> None:
        identity = (int(observation["device"]), int(observation["inode"]))
        if (
            str(path) in seen_artifact_paths
            or identity in seen_artifact_identities
            or identity in source_identities
        ):
            raise EvidenceError("store_migration_artifact_duplicate")
        seen_artifact_paths.add(str(path))
        seen_artifact_identities.add(identity)

    for index, raw_drill in enumerate(raw_drills):
        drill = _mapping(raw_drill, f"store_migration_receipt.database_drills.{index}")
        if set(drill) != {
            "drill_id",
            "roles",
            "migration_state",
            "rollback_strategy",
            "materialization_required",
            "rollback_ready",
            "readiness_blockers",
            "schema_transitions",
            "source",
            "backup_writer_probe",
            "predecessor_fixture",
            "installation_seed",
            "backup",
            "restore",
            "rollback",
            "duration_ms",
        }:
            raise EvidenceError("store_migration_database_drill_shape_invalid")
        _migration_duration(
            drill.get("duration_ms"),
            f"store_migration.database_drills.{index}.duration_ms",
        )
        roles_value = drill.get("roles")
        if (
            not isinstance(roles_value, list)
            or roles_value != sorted(set(roles_value))
            or not set(roles_value).issubset({"control", "delivery"})
            or not roles_value
        ):
            raise EvidenceError("store_migration_roles_invalid")
        roles = tuple(str(role) for role in roles_value)
        migration_state = _required_text(
            drill.get("migration_state"),
            f"store_migration.database_drills.{index}.migration_state",
        )
        if migration_state not in {
            "migration_required",
            "fresh_install",
            "already_current",
        }:
            raise EvidenceError("store_migration_state_invalid")
        rollback_strategy = _required_text(
            drill.get("rollback_strategy"),
            f"store_migration.database_drills.{index}.rollback_strategy",
        )
        if not isinstance(drill.get("materialization_required"), bool):
            raise EvidenceError("store_migration_materialization_state_invalid")
        if not isinstance(drill.get("rollback_ready"), bool):
            raise EvidenceError("store_migration_rollback_readiness_invalid")
        readiness_blockers = drill.get("readiness_blockers")
        if (
            not isinstance(readiness_blockers, list)
            or readiness_blockers != sorted(set(readiness_blockers))
            or not all(isinstance(value, str) and value for value in readiness_blockers)
        ):
            raise EvidenceError("store_migration_blockers_invalid")
        expected_drill_transitions = {
            role: expected_schema_transitions[role] for role in roles
        }
        if drill.get("schema_transitions") != expected_drill_transitions:
            raise EvidenceError("store_migration_schema_transitions_invalid")
        expected_drill_id = "shared" if len(roles) == 2 else roles[0]
        if drill.get("drill_id") != expected_drill_id:
            raise EvidenceError("store_migration_drill_id_invalid")
        source = _mapping(
            drill.get("source"), f"store_migration.database_drills.{index}.source"
        )
        if set(source) != {
            "configured_path",
            "mode",
            "exists",
            "identity",
            "bundle_before",
            "bundle_after",
            "pre_validation",
            "unchanged",
        }:
            raise EvidenceError("store_migration_source_shape_invalid")
        configured_path = _required_text(
            source.get("configured_path"),
            f"store_migration.database_drills.{index}.source.configured_path",
        )
        if configured_path in seen_configured_paths:
            raise EvidenceError("store_migration_source_duplicate")
        seen_configured_paths.add(configured_path)
        if expected_groups.get(configured_path) != roles:
            raise EvidenceError("store_migration_source_role_mismatch")
        configured_path_object = Path(configured_path)
        source_mode = _required_text(
            source.get("mode"), f"store_migration.database_drills.{index}.source.mode"
        )
        if source_mode not in {"existing", "fresh_create"}:
            raise EvidenceError("store_migration_source_mode_invalid")
        observed_source_modes.add(source_mode)
        if source.get("unchanged") is not True:
            raise EvidenceError("store_migration_source_unchanged_unproven")

        if source_mode == "existing":
            if source.get("exists") is not True or source.get("identity") is None:
                raise EvidenceError("store_migration_source_identity_missing")
            source_identity, source_resolved = _migration_declared_file_observation(
                source.get("identity"),
                field=f"store_migration.database_drills.{index}.source.identity",
            )
            if source_resolved != configured_path_object:
                raise EvidenceError("store_migration_source_identity_mismatch")
            source_identities.add((
                int(source_identity["device"]),
                int(source_identity["inode"]),
            ))
            source_validation = _mapping(
                source.get("pre_validation"),
                f"store_migration.database_drills.{index}.source.pre_validation",
            )
            if drill.get("predecessor_fixture") is not None:
                raise EvidenceError("store_migration_predecessor_fixture_unexpected")
            if migration_state == "fresh_install":
                raise EvidenceError("store_migration_state_schema_mismatch")
        else:
            if source.get("exists") is not False or source.get("identity") is not None:
                raise EvidenceError("store_migration_fresh_source_invalid")
            predecessor = drill.get("predecessor_fixture")
            if predecessor is None:
                raise EvidenceError("store_migration_predecessor_drill_invalid")
            predecessor_artifact, source_validation, predecessor_path = (
                _migration_artifact(
                    predecessor,
                    roles=roles,
                    field=f"store_migration.database_drills.{index}.predecessor_fixture",
                    work_dir=work_dir,
                )
            )
            register_artifact(predecessor_artifact, predecessor_path)
            if source.get("pre_validation") != source_validation:
                raise EvidenceError("store_migration_predecessor_drill_invalid")
            _check_migration_predecessor_structure(source_validation, roles=roles)
            if migration_state != "fresh_install":
                raise EvidenceError("store_migration_state_schema_mismatch")

        bundle_before = _migration_source_bundle(
            source.get("bundle_before"),
            field=f"store_migration.database_drills.{index}.source.bundle_before",
            expected_database_identity=(
                source_identity if source_mode == "existing" else None
            ),
        )
        bundle_after = _migration_source_bundle(
            source.get("bundle_after"),
            field=f"store_migration.database_drills.{index}.source.bundle_after",
            expected_database_identity=(
                source_identity if source_mode == "existing" else None
            ),
        )
        if bundle_before != bundle_after:
            raise EvidenceError("store_migration_source_unchanged_unproven")
        _migration_writer_backup_probe(
            drill.get("backup_writer_probe"),
            field=f"store_migration.database_drills.{index}.backup_writer_probe",
        )

        schemas = _mapping(
            source_validation.get("schemas"),
            f"store_migration.database_drills.{index}.source.schemas",
        )
        if set(schemas) != set(roles) or any(
            schemas[role] not in supported_schemas[role] for role in roles
        ):
            raise EvidenceError("store_migration_pre_schema_unsupported")
        _check_migration_supported_pre_structure(source_validation, roles=roles)
        expected_predecessor_schemas = {
            role: expected_schema_transitions[role]["from"] for role in roles
        }
        expected_current_schemas = {
            role: expected_schema_transitions[role]["to"] for role in roles
        }
        if migration_state in {"migration_required", "fresh_install"}:
            if dict(schemas) != expected_predecessor_schemas:
                raise EvidenceError("store_migration_state_schema_mismatch")
            _check_migration_predecessor_structure(source_validation, roles=roles)
        elif dict(schemas) != expected_current_schemas:
            raise EvidenceError("store_migration_state_schema_mismatch")

        backup_artifact, backup_validation, backup_path = _migration_artifact(
            drill.get("backup"),
            roles=roles,
            field=f"store_migration.database_drills.{index}.backup",
            work_dir=work_dir,
        )
        register_artifact(backup_artifact, backup_path)
        if backup_validation != source_validation:
            raise EvidenceError("store_migration_backup_source_mismatch")
        try:
            with tempfile.TemporaryDirectory(
                prefix=".store-migration-current-",
                dir=work_dir,
            ) as snapshot_dir:
                current_snapshot = Path(snapshot_dir) / "current.sqlite3"
                sqlite_read_only_snapshot(configured_path_object, current_snapshot)
                current_validation = inspect_sqlite_read_only(current_snapshot, roles)
                _check_migration_target_structure(current_validation, roles=roles)
                current_inheritance = (
                    compare_sqlite_common_content(
                        backup_path,
                        current_snapshot,
                    )
                    if source_mode == "existing"
                    else None
                )
        except (MigrationDrillError, OSError) as exc:
            raise EvidenceError("store_migration_current_snapshot_invalid") from exc
        restore = _mapping(
            drill.get("restore"),
            f"store_migration.database_drills.{index}.restore",
        )
        if set(restore) != {
            "artifact",
            "source_backup_sha256",
            "validation",
            "migration_observations",
            "data_inheritance",
        }:
            raise EvidenceError("store_migration_restore_shape_invalid")
        restore_artifact, restore_path = _migration_file_observation(
            restore.get("artifact"),
            field=f"store_migration.database_drills.{index}.restore.artifact",
            work_dir=work_dir,
        )
        register_artifact(restore_artifact, restore_path)
        if restore.get("source_backup_sha256") != backup_artifact["sha256"]:
            raise EvidenceError("store_migration_restore_source_mismatch")
        restore_validation = _migration_sqlite_validation(
            restore.get("validation"),
            path=restore_path,
            roles=roles,
            field=f"store_migration.database_drills.{index}.restore.validation",
        )
        _check_migration_target_structure(restore_validation, roles=roles)
        try:
            data_inheritance = compare_sqlite_common_content(
                backup_path,
                restore_path,
            )
        except MigrationDrillError as exc:
            raise EvidenceError("store_migration_restore_data_mismatch") from exc
        if restore.get("data_inheritance") != data_inheritance:
            raise EvidenceError("store_migration_restore_data_mismatch")
        installation_seed = drill.get("installation_seed")
        if migration_state == "fresh_install":
            seed_artifact, seed_validation, seed_path = _migration_artifact(
                installation_seed,
                roles=roles,
                field=f"store_migration.database_drills.{index}.installation_seed",
                work_dir=work_dir,
            )
            if (
                seed_artifact != restore_artifact
                or seed_validation != restore_validation
                or seed_path != restore_path
            ):
                raise EvidenceError("fresh_install_seed_binding_invalid")
        elif installation_seed is not None:
            raise EvidenceError("fresh_install_seed_unexpected")
        restore_verified_again, restore_verified_path = _migration_file_observation(
            restore.get("artifact"),
            field=f"store_migration.database_drills.{index}.restore.artifact",
            work_dir=work_dir,
        )
        if (
            restore_verified_again != restore_artifact
            or restore_verified_path != restore_path
        ):
            raise EvidenceError("store_migration_artifact_identity_mismatch")
        migration_observations = _mapping(
            restore.get("migration_observations"),
            f"store_migration.database_drills.{index}.restore.migration_observations",
        )
        if set(migration_observations) != set(roles):
            raise EvidenceError("store_migration_observations_invalid")
        if "control" in roles:
            control_observation = _mapping(
                migration_observations.get("control"),
                "store_migration.restore.migration_observations.control",
            )
            expected_control_mode = (
                "steady"
                if schemas["control"] == CONTROL_STORE_SCHEMA_VERSION
                else "migration"
            )
            if (
                set(control_observation) != {"mode", "backfill_runs"}
                or control_observation.get("mode") != expected_control_mode
                or isinstance(control_observation.get("backfill_runs"), bool)
                or not isinstance(control_observation.get("backfill_runs"), int)
                or control_observation.get("backfill_runs") < 0
            ):
                raise EvidenceError("store_migration_observations_invalid")
        if "delivery" in roles and migration_observations.get("delivery") != {
            "mode": "candidate_store_initialize"
        }:
            raise EvidenceError("store_migration_observations_invalid")

        rollback = _mapping(
            drill.get("rollback"),
            f"store_migration.database_drills.{index}.rollback",
        )
        if set(rollback) != {
            "artifact",
            "source_artifact_sha256",
            "validation",
            "strategy",
            "compatibility_probe",
            "read_only_restore_proven",
            "predecessor_validator_execution",
            "rollback_ready",
            "preserve_store_proven",
        }:
            raise EvidenceError("store_migration_rollback_shape_invalid")
        rollback_artifact, rollback_path = _migration_file_observation(
            rollback.get("artifact"),
            field=f"store_migration.database_drills.{index}.rollback.artifact",
            work_dir=work_dir,
        )
        register_artifact(rollback_artifact, rollback_path)
        rollback_validation = _migration_sqlite_validation(
            rollback.get("validation"),
            path=rollback_path,
            roles=roles,
            field=f"store_migration.database_drills.{index}.rollback.validation",
        )
        try:
            rollback_source_path = (
                restore_path if migration_state == "fresh_install" else backup_path
            )
            rollback_snapshot_sha256 = sqlite_backup_snapshot_sha256(
                rollback_source_path,
                work_dir,
            )
        except MigrationDrillError as exc:
            raise EvidenceError("store_migration_rollback_proof_invalid") from exc
        if (
            rollback.get("source_artifact_sha256")
            != (
                restore_artifact["sha256"]
                if migration_state == "fresh_install"
                else backup_artifact["sha256"]
            )
            or rollback_snapshot_sha256 != rollback_artifact["sha256"]
            or rollback_validation
            != (
                restore_validation
                if migration_state == "fresh_install"
                else backup_validation
            )
        ):
            raise EvidenceError("store_migration_rollback_proof_invalid")
        predecessor_execution = rollback.get("predecessor_validator_execution")
        execution_verified = False
        if predecessor_execution is not None:
            if predecessor_validator is None:
                raise EvidenceError("store_migration_predecessor_execution_invalid")
            _check_migration_predecessor_execution(
                predecessor_execution,
                validator=predecessor_validator,
                rollback_artifact=rollback_artifact,
                rollback_path=rollback_path,
                roles=roles,
                work_dir=work_dir,
                receipt_observed_at=receipt_observed_at,
            )
            execution_verified = True
        expected_readiness_blockers: list[str] = []
        if migration_state == "already_current":
            expected_readiness_blockers.append("migration_source_already_current")
        if migration_state == "fresh_install":
            expected_readiness_blockers.append(
                "fresh_install_materialization_required"
            )
        if migration_state == "migration_required" and predecessor_validator is None:
            expected_readiness_blockers.append(
                "predecessor_validator_not_configured"
            )
        expected_readiness_blockers.sort()
        expected_rollback_ready = (
            (
                (
                    migration_state == "migration_required"
                    and source_mode == "existing"
                    and execution_verified
                )
            )
            and not expected_readiness_blockers
        )
        expected_rollback_strategy = {
            "migration_required": "restore_predecessor_snapshot_v1",
            "fresh_install": "disable_writers_preserve_current_store_v1",
            "already_current": "idempotency_only_v1",
        }[migration_state]
        if (
            readiness_blockers != expected_readiness_blockers
            or drill.get("rollback_ready") is not expected_rollback_ready
            or rollback.get("rollback_ready") is not expected_rollback_ready
            or rollback.get("read_only_restore_proven") is not execution_verified
            or rollback.get("compatibility_probe")
            != (
                PREDECESSOR_COMPATIBILITY_PROBE if execution_verified else None
            )
            or rollback_strategy != expected_rollback_strategy
            or rollback.get("strategy") != expected_rollback_strategy
            or rollback.get("preserve_store_proven")
            is not False
            or drill.get("materialization_required")
            is not (migration_state == "fresh_install")
        ):
            raise EvidenceError("store_migration_rollback_readiness_invalid")
        rollback_verified_again, rollback_verified_path = _migration_file_observation(
            rollback.get("artifact"),
            field=f"store_migration.database_drills.{index}.rollback.artifact",
            work_dir=work_dir,
        )
        if (
            rollback_verified_again != rollback_artifact
            or rollback_verified_path != rollback_path
        ):
            raise EvidenceError("store_migration_artifact_identity_mismatch")
        drill_details.append({
            "drill_id": expected_drill_id,
            "roles": list(roles),
            "source_mode": source_mode,
            "migration_state": migration_state,
            "rollback_ready": expected_rollback_ready,
            "rollback_strategy": expected_rollback_strategy,
            "readiness_blockers": expected_readiness_blockers,
            "pre_schemas": dict(schemas),
            "post_schemas": dict(restore_validation["schemas"]),
            "backup_sha256": backup_artifact["sha256"],
            "restore_sha256": restore_artifact["sha256"],
            "data_inheritance_sha256": data_inheritance["tables_sha256"],
            "current_schemas": dict(current_validation["schemas"]),
            "current_inheritance_sha256": (
                current_inheritance["tables_sha256"]
                if current_inheritance is not None
                else None
            ),
            "rollback_sha256": rollback_artifact["sha256"],
            "source_sha256": (
                source_identity["sha256"] if source_mode == "existing" else None
            ),
        })

    expected_mode = (
        next(iter(observed_source_modes))
        if len(observed_source_modes) == 1
        else "mixed"
    )
    if mode != expected_mode or seen_configured_paths != set(expected_groups):
        raise EvidenceError("store_migration_mode_mismatch")
    observed_migration_states = {
        detail["migration_state"] for detail in drill_details
    }
    expected_migration_state = (
        next(iter(observed_migration_states))
        if len(observed_migration_states) == 1
        else "mixed"
    )
    expected_blockers = sorted({
        blocker
        for detail in drill_details
        for blocker in detail["readiness_blockers"]
    })
    expected_rollback_ready = bool(drill_details) and all(
        detail["rollback_ready"] is True for detail in drill_details
    )
    observed_rollback_strategies = {
        detail["rollback_strategy"] for detail in drill_details
    }
    expected_rollback_strategy = (
        next(iter(observed_rollback_strategies))
        if len(observed_rollback_strategies) == 1
        else "mixed_v1"
    )
    if (
        declared_migration_state != expected_migration_state
        or declared_rollback_strategy != expected_rollback_strategy
        or declared_blockers != expected_blockers
        or body.get("rollback_ready") is not expected_rollback_ready
        or body.get("materialization_required")
        is not (expected_migration_state == "fresh_install")
    ):
        raise EvidenceError("store_migration_rollback_readiness_invalid")
    activation_binding = activation or {}
    bound_config_sha256 = str(
        expected_config_sha256 or activation_binding.get("config_sha256") or ""
    )
    _sha256_digest(bound_config_sha256, "store_migration.config_sha256")
    materialization_detail = None
    if expected_migration_state == "fresh_install":
        if materialization_receipt is None or materialization_raw_sha256 is None:
            raise EvidenceError("fresh_install_materialization_receipt_missing")
        materialization_detail = _check_fresh_install_materialization(
            materialization_receipt,
            raw_sha256=materialization_raw_sha256,
            migration_raw_sha256=migration_raw_sha256,
            migration_observed_at=receipt_observed_at,
            migration_drills=[
                _mapping(item, "store_migration.database_drill")
                for item in raw_drills
            ],
            dispatcher=dispatcher,
            candidate_commit=candidate_commit,
            expected_config_sha256=bound_config_sha256,
            activation=activation_binding or None,
            work_dir=work_dir,
            now=now,
            max_age_seconds=max_age_seconds,
            release_mode=release_mode,
        )
        if (
            activation_binding.get("db_logical_identity")
            != materialization_detail["expected_db_logical_identity"]
            or activation_binding.get("db_logical_identity_sha256")
            != materialization_detail["expected_db_logical_identity_sha256"]
        ) and activation_binding:
            raise EvidenceError("activation_database_identity_binding_invalid")
    elif materialization_receipt is not None:
        raise EvidenceError("fresh_install_materialization_receipt_unexpected")
    if (
        capacity_initialization_receipt is None
        or capacity_initialization_raw_sha256 is None
    ):
        raise EvidenceError("capacity_initialization_receipt_missing")
    capacity_receipt_path = (
        settings.evidence_dir / "capacity_transition_initialization_receipt.json"
    )
    origin_identity = capacity_initialization_receipt.get("capacity_identity")
    if not isinstance(origin_identity, Mapping) or set(origin_identity) != {
        "release_id",
        "bootstrap_epoch_id",
    }:
        raise EvidenceError("capacity_initialization_receipt_invalid")
    try:
        migration_observation = observe_regular_file(
            settings.evidence_dir / "store_migration_receipt.json"
        )
        validated_capacity = _validate_capacity_initialization_receipt(
            receipt_path=capacity_receipt_path,
            database_path=dispatcher.control_db_path,
            configured_databases=configured,
            migration_receipt_observation=migration_observation,
            expected_identity={
                "release_id": str(origin_identity.get("release_id") or ""),
                "bootstrap_epoch_id": str(
                    origin_identity.get("bootstrap_epoch_id") or ""
                ),
            },
            allowed_operations=(
                frozenset({"fresh_materialization"})
                if expected_migration_state == "fresh_install"
                else frozenset({"existing_migration"})
            ),
        )
    except MigrationDrillError as exc:
        raise EvidenceError("capacity_initialization_receipt_invalid") from exc
    if (
        validated_capacity["receipt"] != capacity_initialization_receipt
        or hashlib.sha256(validated_capacity["receipt_raw"]).hexdigest()
        != capacity_initialization_raw_sha256
        or capacity_initialization_receipt.get("schema_version")
        != CAPACITY_INITIALIZATION_RECEIPT_SCHEMA_VERSION
    ):
        raise EvidenceError("capacity_initialization_receipt_invalid")
    if expected_migration_state == "fresh_install" and (
        materialization_receipt is None
        or materialization_receipt.get("capacity_identity")
        != capacity_initialization_receipt.get("capacity_identity")
        or materialization_receipt.get("capacity_transition")
        != validated_capacity.get("initialization_transition")
        or materialization_receipt.get("capacity_initialization_receipt")
        != validated_capacity.get("receipt_observation")
    ):
        raise EvidenceError("fresh_install_capacity_initialization_binding_invalid")
    live_capacity_transition = validated_capacity["capacity_transition"]
    live_state = live_capacity_transition.get("state")
    bootstrap_is_current = (
        live_capacity_transition.get("release_id") == dispatcher.release_id
        and live_capacity_transition.get("bootstrap_epoch_id")
        == dispatcher.bootstrap_epoch_id
    )
    if (
        (
            live_state == "BOOTSTRAP_PRODUCTION"
            and (
                live_capacity_transition.get("generation") != 1
                or len(live_capacity_transition.get("audit_chain") or ()) != 1
                or not bootstrap_is_current
            )
        )
        or (
            live_state == "STEADY_ACTIVE"
            and (
                live_capacity_transition.get("generation") != 2
                or len(live_capacity_transition.get("audit_chain") or ()) != 2
            )
        )
        or live_state not in {"BOOTSTRAP_PRODUCTION", "STEADY_ACTIVE"}
    ):
        raise EvidenceError("capacity_initialization_live_latch_invalid")
    origin_lineage = _existing_database_origin_lineage(
        dispatcher.control_db_path
    )
    # Database-local lineage is continuity evidence, not external rollback provenance.
    already_current_idempotency_ready = False
    effective_rollback_ready = expected_rollback_ready or (
        expected_migration_state == "fresh_install"
        and materialization_detail is not None
    )
    if release_mode in {
        "preauthorization",
        "preproduction",
        "canary_bootstrap",
        *PRODUCTION_MODES,
    } and not effective_rollback_ready:
        raise EvidenceError("store_migration_rollback_not_ready")
    expected_db_identity = (
        materialization_detail["expected_db_logical_identity"]
        if materialization_detail is not None
        else _existing_activation_database_identity(
            dispatcher=dispatcher,
            migration_raw_sha256=migration_raw_sha256,
            candidate_commit=candidate_commit,
            config_sha256=bound_config_sha256,
        )
    )
    expected_db_identity_sha256 = _sha256_json(expected_db_identity)
    if activation_binding and (
        activation_binding.get("db_logical_identity") != expected_db_identity
        or activation_binding.get("db_logical_identity_sha256")
        != expected_db_identity_sha256
    ):
        raise EvidenceError("activation_database_identity_binding_invalid")
    return {
        "observed_at": observed_at,
        "mode": mode,
        "migration_state": expected_migration_state,
        "rollback_ready": effective_rollback_ready,
        "migration_receipt_rollback_ready": expected_rollback_ready,
        "already_current_idempotency_ready": already_current_idempotency_ready,
        "origin_lineage_sha256": (
            _sha256_json(origin_lineage) if origin_lineage is not None else None
        ),
        "materialization_required": expected_migration_state == "fresh_install",
        "rollback_strategy": expected_rollback_strategy,
        "blockers": expected_blockers,
        "same_database": same_database,
        "candidate_commit": candidate_commit,
        "migration_source_sha256": dict(migration_sources),
        "writer_stop_observed_at": writer_stop_observed_at.isoformat(),
        "writer_stop_service_count": len(STORE_WRITER_LABELS),
        "compatibility_probe": PREDECESSOR_COMPATIBILITY_PROBE,
        "predecessor_validator_sha256": (
            _mapping(predecessor_validator.get("artifact"), "validator.artifact")[
                "sha256"
            ]
            if predecessor_validator is not None
            else None
        ),
        "schema_transitions": expected_schema_transitions,
        "duration_ms": duration_ms,
        "database_drills": drill_details,
        "fresh_install_materialization": materialization_detail,
        "capacity_initialization": {
            "receipt_raw_sha256": capacity_initialization_raw_sha256,
            "operation": capacity_initialization_receipt.get("operation"),
            "release_id": live_capacity_transition["release_id"],
            "bootstrap_epoch_id": live_capacity_transition[
                "bootstrap_epoch_id"
            ],
            "state": live_capacity_transition["state"],
            "generation": live_capacity_transition["generation"],
            "origin_matches_current_release": bootstrap_is_current,
            "audit_chain_sha256": live_capacity_transition[
                "audit_chain_sha256"
            ],
        },
        "expected_db_logical_identity": expected_db_identity,
        "expected_db_logical_identity_sha256": expected_db_identity_sha256,
        "migration_receipt_raw_sha256": migration_raw_sha256,
        "materialization_receipt_raw_sha256": (
            materialization_raw_sha256
            if materialization_raw_sha256 is not None
            else hashlib.sha256(b"").hexdigest()
        ),
    }


def _check_cutover_plan(
    body: Mapping[str, Any],
    *,
    cutover: CutoverConfig,
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    artifact = "cutover_plan"
    _require_schema(body, CUTOVER_PLAN_SCHEMA_VERSION, artifact)
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("approved") is not True:
        raise EvidenceError("cutover_plan_not_approved")
    if body.get("legacy_entry_mode") != "read_only":
        raise EvidenceError("cutover_plan_legacy_entry_not_read_only")
    if body.get("legacy_auto_execution_disabled") is not True:
        raise EvidenceError("cutover_plan_legacy_execution_not_disabled")
    if (
        _exact_int(body.get("legacy_daily_quota"), "cutover_plan.legacy_daily_quota")
        != 0
    ):
        raise EvidenceError("cutover_plan_legacy_quota_not_zero")
    if body.get("legacy_governance_download_enabled") is not False:
        raise EvidenceError("cutover_plan_legacy_download_still_enabled")
    if body.get("data_access_mode") != FIXED_REMOTE_ACCESS_CONTRACT["mode"]:
        raise EvidenceError("cutover_plan_data_access_mode_mismatch")
    if body.get("mdi_download_allowed") is not False:
        raise EvidenceError("cutover_plan_mdi_download_allowed")
    if body.get("input_materialization") != "forbidden":
        raise EvidenceError("cutover_plan_input_materialization_not_forbidden")
    if body.get("legacy_storage_reservation_enabled") is not False:
        raise EvidenceError("cutover_plan_legacy_storage_reservation_enabled")
    if (
        body.get("derived_capacity_reservation_enabled") is not True
        or body.get("derived_capacity_atomic_reservation") is not True
    ):
        raise EvidenceError("cutover_plan_derived_capacity_reservation_missing")
    if body.get("delivery_collector_enabled") is not True:
        raise EvidenceError("cutover_plan_delivery_collector_not_enabled")
    if body.get("delivery_dispatcher_enabled") is not True:
        raise EvidenceError("cutover_plan_delivery_dispatcher_not_enabled")
    if cutover.legacy_auto_execution_disabled is not True:
        raise EvidenceError("legacy_auto_execution_disable_not_explicit")
    if cutover.legacy_daily_quota != 0:
        raise EvidenceError("legacy_auto_download_quota_not_zero")
    if cutover.legacy_governance_download_enabled is not False:
        raise EvidenceError("legacy_governance_download_not_disabled")
    if cutover.delivery_collector_enabled is not True:
        raise EvidenceError("delivery_collector_enable_not_explicit")
    if cutover.delivery_dispatcher_enabled is not True:
        raise EvidenceError("delivery_dispatcher_enable_not_explicit")
    if cutover.issue_capture_enabled is True:
        raise EvidenceError("issue_capture_must_be_disabled")
    if cutover.issue_capture_root_configured:
        raise EvidenceError("issue_capture_root_must_be_absent")
    rollback = _mapping(body.get("rollback"), "cutover_plan.rollback")
    owner = _required_text(rollback.get("owner"), "cutover_plan.rollback.owner")
    procedure = _required_text(
        rollback.get("procedure"), "cutover_plan.rollback.procedure"
    )
    max_restore_seconds = _exact_int(
        rollback.get("max_restore_seconds"),
        "cutover_plan.rollback.max_restore_seconds",
        minimum=1,
    )
    return {
        "observed_at": observed_at,
        "legacy_entry_mode": "read_only",
        "legacy_auto_execution_disabled": True,
        "legacy_daily_quota": 0,
        "legacy_governance_download_enabled": False,
        "data_access_mode": FIXED_REMOTE_ACCESS_CONTRACT["mode"],
        "mdi_download_allowed": False,
        "input_materialization": "forbidden",
        "legacy_storage_reservation_enabled": False,
        "derived_capacity_reservation_enabled": True,
        "derived_capacity_atomic_reservation": True,
        "delivery_collector_enabled": True,
        "delivery_dispatcher_enabled": True,
        "issue_capture_enabled": False,
        "issue_capture_root_configured": False,
        "rollback_owner": owner,
        "rollback_procedure_sha256": hashlib.sha256(
            procedure.encode("utf-8")
        ).hexdigest(),
        "rollback_max_restore_seconds": max_restore_seconds,
    }


def validate_terminal_delivery_canary(
    body: Mapping[str, Any],
    *,
    expected_manual_chat_ids: Sequence[str],
    expected_operator_config: CutoverConfig | None = None,
    expected_rule_version: str,
    expected_workflow_policy: Mapping[str, Any],
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    artifact = "manual_terminal_failure_canary"
    _require_schema(body, TERMINAL_CANARY_RECEIPT_SCHEMA_VERSION, artifact)
    if set(body) != {
        "schema_version",
        "observed_at",
        "ok",
        "observed_trigger_source",
        "admission",
        "submission_key",
        "business_key",
        "generation",
        "outcome",
        "terminal_state",
        "error_code",
        "watch",
        "delivery_job",
        "delivery_obligations",
    }:
        raise EvidenceError("manual_terminal_failure_canary_shape_invalid")
    observed_at = _require_fresh(
        body, now=now, max_age_seconds=max_age_seconds, artifact=artifact
    )
    if body.get("ok") is not True:
        raise EvidenceError("manual_terminal_failure_canary_not_ok")
    submission_key = _required_text(body.get("submission_key"), "submission_key")
    business_key = _required_text(body.get("business_key"), "business_key")
    generation = _exact_int(body.get("generation"), "generation", minimum=1)
    outcome = _required_text(body.get("outcome"), "outcome")
    terminal_state = _required_text(body.get("terminal_state"), "terminal_state")
    error_code = _required_text(body.get("error_code"), "error_code")
    if (
        outcome not in TERMINAL_DELIVERY_OUTCOMES
        or not re.fullmatch(r"[a-z][a-z0-9_]{0,119}", terminal_state)
        or not re.fullmatch(r"[a-z][a-z0-9_]{0,119}", error_code)
    ):
        raise EvidenceError("manual_terminal_failure_outcome_invalid")
    source = _check_trigger_source_projection(
        body.get("observed_trigger_source"),
        field="manual_terminal_failure_canary.observed_trigger_source",
        expected_business_key=business_key,
        expected_generation=generation,
        expected_manual_chat_ids=expected_manual_chat_ids,
        expected_operator_config=expected_operator_config,
    )
    if source.get("storage_source_kind") != "feishu_group_manual":
        raise EvidenceError("manual_terminal_failure_source_invalid")
    try:
        admission = validate_rca_admission(
            _mapping(body.get("admission"), "manual_terminal_failure_canary.admission")
        ).to_dict()
    except RcaAdmissionError as exc:
        raise EvidenceError("manual_terminal_failure_admission_invalid") from exc
    policy_detail = _check_manual_admission_policy(
        admission,
        expected_rule_version=expected_rule_version,
        expected_workflow_policy=expected_workflow_policy,
        artifact="manual_terminal_failure",
    )
    expected_trigger_kind = (
        (
            "manual_issue_request"
            if source.get("mode") == "run_or_join"
            else "manual_retrigger"
        )
        if source.get("binding_role") == "origin"
        else None
    )
    if (
        admission.get("business_key") != business_key
        or admission.get("submission_key") != submission_key
        or admission.get("generation") != generation
        or (
            expected_trigger_kind is not None
            and admission.get("trigger_kind") != expected_trigger_kind
        )
    ):
        raise EvidenceError("manual_terminal_failure_admission_mismatch")
    watch = _mapping(body.get("watch"), "manual_terminal_failure_canary.watch")
    if set(watch) != {
        "submission_outbox_id",
        "submission_key",
        "task_id",
        "state",
        "delivery_id",
        "terminal_at",
        "last_error_code",
    }:
        raise EvidenceError("manual_terminal_failure_watch_shape_invalid")
    _exact_int(watch.get("submission_outbox_id"), "watch.outbox_id", minimum=1)
    terminal_at = _timestamp(watch.get("terminal_at"), "watch.terminal_at")
    expected_task_id = None if outcome == "quarantined" else submission_key
    watch_error_code = _required_text(
        watch.get("last_error_code"), "watch.last_error_code"
    )
    if (
        watch.get("submission_key") != submission_key
        or watch.get("task_id") != expected_task_id
        or watch.get("state") != "delivery_created"
        or (outcome != "quarantined" and watch_error_code != error_code)
    ):
        raise EvidenceError("manual_terminal_failure_watch_invalid")
    job = _mapping(
        body.get("delivery_job"), "manual_terminal_failure_canary.delivery_job"
    )
    if set(job) != {
        "delivery_id",
        "status",
        "outcome",
        "outcome_key",
        "terminal_state",
        "terminal_error_code",
        "artifact_boundary",
    }:
        raise EvidenceError("manual_terminal_failure_job_shape_invalid")
    outcome_key = _required_text(job.get("outcome_key"), "job.outcome_key")
    if (
        job.get("status") != "delivered"
        or job.get("outcome") != outcome
        or job.get("terminal_state") != terminal_state
        or job.get("terminal_error_code") != error_code
        or not re.fullmatch(r"g1q3-rca-terminal-v1-[0-9a-f]{64}", outcome_key)
        or watch.get("delivery_id") != job.get("delivery_id")
    ):
        raise EvidenceError("manual_terminal_failure_job_invalid")
    boundary = _mapping(job.get("artifact_boundary"), "job.artifact_boundary")
    if boundary != {
        "manifest": {},
        "contract": {},
        "artifacts": [],
        "issue_url": "",
        "report_url": "",
    }:
        raise EvidenceError("manual_terminal_failure_artifact_boundary_invalid")
    obligations_raw = body.get("delivery_obligations")
    if not isinstance(obligations_raw, list) or len(obligations_raw) != 2:
        raise EvidenceError("manual_terminal_failure_obligations_incomplete")
    obligations = [
        _mapping(item, f"manual_terminal_failure_canary.obligations[{index}]")
        for index, item in enumerate(obligations_raw)
    ]
    if {item.get("effect_kind") for item in obligations} != {
        "feishu_issue_comment",
        "feishu_thread_reply",
    }:
        raise EvidenceError("manual_terminal_failure_obligations_incomplete")
    issue = next(
        item
        for item in obligations
        if item.get("effect_kind") == "feishu_issue_comment"
    )
    issue_payload = _mapping(issue.get("payload"), "terminal.issue_payload")
    try:
        primary = build_terminal_delivery(
            business_key=business_key,
            submission_key=submission_key,
            generation=generation,
            project_key=str(issue_payload.get("project_key") or ""),
            work_item_type_key=str(issue_payload.get("work_item_type_key") or ""),
            work_item_id=str(issue_payload.get("work_item_id") or ""),
            outcome=outcome,
            terminal_state=terminal_state,
            error_code=error_code,
        )
    except DeliveryContractError as exc:
        raise EvidenceError("manual_terminal_failure_contract_invalid") from exc
    if (
        job.get("delivery_id") != primary.delivery_id
        or outcome_key != primary.outcome_key
        or issue_payload != primary.effect_payload
    ):
        raise EvidenceError("manual_terminal_failure_identity_invalid")
    admission_refs = _mapping(
        admission.get("source_refs"),
        "manual_terminal_failure_canary.admission.source_refs",
    )
    if (
        admission_refs.get("project_key") != issue_payload.get("project_key")
        or admission_refs.get("work_item_type_key")
        != issue_payload.get("work_item_type_key")
        or admission_refs.get("work_item_id") != issue_payload.get("work_item_id")
    ):
        raise EvidenceError("manual_terminal_failure_admission_mismatch")
    transport = (
        str(admission_refs.get("topic") or ""),
        admission_refs.get("partition"),
        admission_refs.get("offset"),
    )
    if source.get("binding_role") == "origin":
        if transport != ("", None, None):
            raise EvidenceError("manual_terminal_failure_admission_mismatch")
    elif transport != ("", None, None) and (
        transport[0] != expected_workflow_policy.get("topic")
        or isinstance(transport[1], bool)
        or not isinstance(transport[1], int)
        or transport[1] < 0
        or isinstance(transport[2], bool)
        or not isinstance(transport[2], int)
        or transport[2] < 0
    ):
        raise EvidenceError("manual_terminal_failure_admission_mismatch")
    effect_timelines: list[tuple[datetime, datetime]] = []
    for obligation in obligations:
        if set(obligation) != {
            "subscription_key",
            "effect_kind",
            "target_key",
            "target",
            "required",
            "subscription_status",
            "delivery_id",
            "effect_key",
            "effect_status",
            "effect_outcome",
            "materialized_at",
            "completed_at",
            "remote_id",
            "attempt_outcome",
            "payload",
        }:
            raise EvidenceError("manual_terminal_failure_obligation_shape_invalid")
        materialized_at = _timestamp(
            obligation.get("materialized_at"), "obligation.materialized_at"
        )
        completed_at = _timestamp(
            obligation.get("completed_at"), "obligation.completed_at"
        )
        effect_timelines.append((materialized_at, completed_at))
        remote_id = _required_text(obligation.get("remote_id"), "obligation.remote_id")
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,511}", remote_id):
            raise EvidenceError("manual_terminal_failure_remote_id_invalid")
        if (
            obligation.get("required") is not True
            or obligation.get("subscription_status") != "materialized"
            or obligation.get("delivery_id") != primary.delivery_id
            or obligation.get("effect_status") != "succeeded"
            or obligation.get("effect_outcome") != outcome
            or obligation.get("attempt_outcome") not in {"ack", "reconciled"}
        ):
            raise EvidenceError("manual_terminal_failure_obligation_not_succeeded")
        target = _mapping(obligation.get("target"), "obligation.target")
        payload = _mapping(obligation.get("payload"), "obligation.payload")
        if obligation.get("effect_kind") == "feishu_issue_comment":
            expected_key = primary.effect_key
            expected_payload = primary.effect_payload
        else:
            try:
                expected_key, _expected_sha, expected_payload = (
                    build_terminal_thread_reply_effect(
                        issue_effect_payload=primary.effect_payload,
                        target_key=str(obligation.get("target_key") or ""),
                        target=target,
                    )
                )
            except DeliveryContractError as exc:
                raise EvidenceError(
                    "manual_terminal_failure_thread_contract_invalid"
                ) from exc
            root = str(source.get("thread_id") or "").removeprefix("topic:")
            if (
                obligation.get("target_key")
                != f"feishu_thread:{source.get('chat_id')}:{root}"
                or target.get("chat_id") != source.get("chat_id")
                or target.get("thread_id") != source.get("thread_id")
                or target.get("reply_anchor_message_id") != root
            ):
                raise EvidenceError("manual_terminal_failure_topic_binding_invalid")
        if obligation.get("effect_key") != expected_key or payload != expected_payload:
            raise EvidenceError("manual_terminal_failure_effect_binding_invalid")
    observed_timestamp = _timestamp(body.get("observed_at"), f"{artifact}.observed_at")
    source_created_at = _timestamp(
        source.get("created_at"), f"{artifact}.source_created_at"
    )
    source_bound_at = _timestamp(source.get("bound_at"), f"{artifact}.source_bound_at")
    if (
        not source_created_at <= source_bound_at <= terminal_at <= observed_timestamp
        or any(
            not terminal_at <= materialized_at <= completed_at <= observed_timestamp
            for materialized_at, completed_at in effect_timelines
        )
    ):
        raise EvidenceError("manual_terminal_failure_timeline_invalid")
    if (observed_timestamp - source_created_at).total_seconds() > max_age_seconds:
        raise EvidenceError("manual_terminal_failure_timeline_stale")
    authorization = _mapping(
        source.get("authorization"),
        "manual_terminal_failure_canary.observed_trigger_source.authorization",
    )
    gateway_runtime_identity = _check_gateway_runtime_identity(
        authorization.get("gateway_runtime_identity"),
        field="manual_terminal_failure_canary.gateway_runtime_identity",
    )
    return {
        "observed_at": observed_at,
        "outcome": outcome,
        "terminal_state": terminal_state,
        "error_code": error_code,
        "source_mode": str(source.get("mode") or ""),
        "operator_authorization_proven": source.get("mode") in {"rerun", "debug"},
        "source_id_sha256": hashlib.sha256(
            str(source["source_id"]).encode("utf-8")
        ).hexdigest(),
        "delivery_id_sha256": hashlib.sha256(
            primary.delivery_id.encode("utf-8")
        ).hexdigest(),
        "required_effects": ["feishu_issue_comment", "feishu_thread_reply"],
        "gateway_runtime_identity": gateway_runtime_identity,
        "gateway_runtime_identity_sha256": _sha256_json(gateway_runtime_identity),
        "observed_trigger_source": source,
        "admission": admission,
        "manual_policy": policy_detail,
    }


def _check_terminal_canary_sources(
    body: Mapping[str, Any],
    *,
    receipt: Mapping[str, Any],
    expected_collector: Path,
    expected_evidence_dir: Path,
    expected_control_db_path: Path,
    expected_delivery_db_path: Path,
    expected_group_binding_receipt_dir: Path,
    expected_manual_chat_ids: Sequence[str],
    expected_workflow_policy: Mapping[str, Any],
) -> dict[str, Any]:
    artifact = "manual_terminal_failure_canary_sources"
    _require_schema(body, TERMINAL_CANARY_SOURCE_SCHEMA_VERSION, artifact)
    if set(body) != {
        "schema_version",
        "collected_at",
        "read_only",
        "external_side_effects",
        "collector",
        "observed_trigger_source_sha256",
        "submission_key_sha256",
        "control_database",
        "delivery_database",
        "local_machine_sources",
        "receipt_sha256",
    }:
        raise EvidenceError("manual_terminal_failure_sources_shape_invalid")
    _timestamp(body.get("collected_at"), "terminal_sources.collected_at")
    if (
        body.get("read_only") is not True
        or body.get("external_side_effects") is not False
        or body.get("collected_at") != receipt.get("observed_at")
        or body.get("receipt_sha256") != _sha256_json(receipt)
        or body.get("observed_trigger_source_sha256")
        != _sha256_json(receipt.get("observed_trigger_source"))
        or body.get("submission_key_sha256")
        != hashlib.sha256(
            str(receipt.get("submission_key") or "").encode("utf-8")
        ).hexdigest()
    ):
        raise EvidenceError("manual_terminal_failure_sources_binding_invalid")
    collector = _mapping(body.get("collector"), "terminal_sources.collector")
    expected_path = expected_collector.resolve(strict=True)
    if (
        collector.get("path") != str(expected_path)
        or collector.get("sha256")
        != hashlib.sha256(expected_path.read_bytes()).hexdigest()
    ):
        raise EvidenceError("manual_terminal_failure_collector_mismatch")
    database_details: dict[str, dict[str, Any]] = {}
    for name, expected_database_path in (
        ("control_database", expected_control_db_path),
        ("delivery_database", expected_delivery_db_path),
    ):
        database = _mapping(body.get(name), f"terminal_sources.{name}")
        if set(database) != {
            "path",
            "device",
            "inode",
            "size_bytes",
            "mtime_ns",
            "query_mode",
            "snapshot_sha256",
        }:
            raise EvidenceError("manual_terminal_failure_database_shape_invalid")
        resolved_path, resolved_info = _observe_live_database_identity(
            expected_database_path,
            unreadable_code="manual_terminal_failure_database_unreadable",
            invalid_code="manual_terminal_failure_database_invalid",
        )
        if (
            database.get("path") != str(resolved_path)
            or database.get("query_mode") != "sqlite_mode_ro_query_only_transaction"
        ):
            raise EvidenceError("manual_terminal_failure_database_invalid")
        device = _exact_int(database.get("device"), f"{name}.device", minimum=1)
        inode = _exact_int(database.get("inode"), f"{name}.inode", minimum=1)
        size_bytes = _exact_int(
            database.get("size_bytes"), f"{name}.size_bytes", minimum=1
        )
        mtime_ns = _exact_int(database.get("mtime_ns"), f"{name}.mtime_ns", minimum=1)
        if device != resolved_info.st_dev or inode != resolved_info.st_ino:
            raise EvidenceError("manual_terminal_failure_database_identity_mismatch")
        database_details[name] = {
            "path": str(resolved_path),
            "device": device,
            "inode": inode,
            "size_bytes": size_bytes,
            "mtime_ns": mtime_ns,
            "snapshot_sha256": _sha256_digest(
                database.get("snapshot_sha256"), f"{name}.snapshot_sha256"
            ),
        }
    if (
        database_details["control_database"]["path"]
        == database_details["delivery_database"]["path"]
    ):
        if any(
            database_details["control_database"][field]
            != database_details["delivery_database"][field]
            for field in ("path", "device", "inode")
        ):
            raise EvidenceError("manual_terminal_failure_database_identity_mismatch")
    source = _mapping(
        receipt.get("observed_trigger_source"), "terminal.observed_trigger_source"
    )
    authorization = _mapping(source.get("authorization"), "terminal.authorization")
    machine = _mapping(body.get("local_machine_sources"), "terminal_sources.local")
    authorizations = _mapping(
        machine.get("group_binding_authorizations"),
        "terminal_sources.group_binding_authorizations",
    )
    source_record = _mapping(
        authorizations.get(source.get("source_id")),
        "terminal_sources.group_binding_authorization",
    )
    authorization_detail = _read_bound_group_authorization_source(
        _canary_source_record(
            {str(source.get("source_id")): source_record},
            str(source.get("source_id")),
            json_source=True,
        ),
        evidence=authorization,
        expected_root=expected_group_binding_receipt_dir,
    )
    live_database = _check_live_canary_database_binding(
        receipt=receipt,
        control_snapshot_sha256=database_details["control_database"][
            "snapshot_sha256"
        ],
        delivery_snapshot_sha256=database_details["delivery_database"][
            "snapshot_sha256"
        ],
        control_db_path=expected_control_db_path,
        delivery_db_path=expected_delivery_db_path,
        evidence_dir=expected_evidence_dir,
        group_binding_receipt_dir=expected_group_binding_receipt_dir,
        manual_chat_ids=expected_manual_chat_ids,
        expected_workflow_policy=expected_workflow_policy,
        terminal_failure=True,
    )
    return {
        "read_only": True,
        "collector_sha256": collector["sha256"],
        "control_snapshot_sha256": database_details["control_database"][
            "snapshot_sha256"
        ],
        "delivery_snapshot_sha256": database_details["delivery_database"][
            "snapshot_sha256"
        ],
        "authorization_source_sha256": authorization_detail["raw_sha256"],
        "authorization_sources": {
            str(source.get("source_id")): authorization_detail,
        },
        "live_database": live_database,
    }


def _check_manual_terminal_failure_delivery(
    *,
    mode: str,
    cutover: CutoverConfig,
    consumer: ConsumerConfig,
    dispatcher: DispatcherConfig,
    settings: ReleaseGateSettings,
    committed_evidence: Mapping[str, Any] | None,
    now: datetime,
) -> dict[str, Any]:
    if mode == "shadow":
        return {
            "manual_intake_enabled": cutover.manual_intake_enabled,
            "required": False,
        }
    if cutover.manual_intake_enabled is None:
        if mode in PRODUCTION_MODES:
            raise EvidenceError("manual_intake_enable_not_explicit")
        return {
            "manual_intake_enabled": None,
            "required": False,
        }
    if not cutover.manual_intake_enabled:
        if mode in PRODUCTION_MODES:
            raise EvidenceError("manual_intake_required_in_production")
        return {
            "manual_intake_enabled": False,
            "manual_operator_enabled": cutover.manual_operator_enabled,
            "manual_operator_capability": "not_open",
            "required": False,
        }
    if cutover.manual_intake_enabled:
        if cutover.manual_operator_enabled is None:
            raise EvidenceError("manual_operator_enable_not_explicit")
        if cutover.manual_operator_enabled:
            if not cutover.manual_operator_user_ids:
                raise EvidenceError("manual_operator_allowlist_empty")
            if cutover.manual_operator_rate_limit is None:
                raise EvidenceError("manual_operator_rate_limit_not_explicit")
            if cutover.manual_operator_rate_window_seconds is None:
                raise EvidenceError("manual_operator_rate_window_not_explicit")
        active_chat_ids = _normalized_manual_chat_ids(cutover.manual_chat_ids)
        if not active_chat_ids:
            raise EvidenceError("manual_chat_allowlist_invalid")
        if mode in PRODUCTION_MODES and G1Q3_RCA_GROUP_ID not in active_chat_ids:
            raise EvidenceError("manual_production_chat_required")
        if mode not in PRODUCTION_MODES and committed_evidence is None:
            return {
                "manual_intake_enabled": True,
                "manual_operator_enabled": cutover.manual_operator_enabled,
                "manual_operator_capability": (
                    "enabled" if cutover.manual_operator_enabled else "not_open"
                ),
                "configuration_loaded": True,
                "required": False,
            }
        if committed_evidence is None:
            raise EvidenceError("manual_terminal_failure_topic_receipt_required")
        if committed_evidence.get("evidence_role") != "manual_terminal_failure":
            raise EvidenceError("manual_terminal_failure_evidence_role_invalid")
        receipt = _mapping(
            committed_evidence.get("receipt"),
            "manual_terminal_failure_canary",
        )
        receipt_source = _mapping(
            receipt.get("observed_trigger_source"),
            "manual_terminal_failure_canary.observed_trigger_source",
        )
        if (
            mode in PRODUCTION_MODES
            and receipt_source.get("chat_id") != G1Q3_RCA_GROUP_ID
        ):
            raise EvidenceError("manual_production_chat_canary_required")
        detail = validate_terminal_delivery_canary(
            receipt,
            expected_manual_chat_ids=cutover.manual_chat_ids,
            expected_operator_config=cutover,
            expected_rule_version=settings.expected_rule_version,
            expected_workflow_policy=consumer.policy.to_dict(),
            now=now,
            max_age_seconds=settings.evidence_max_age_seconds,
        )
        if mode in PRODUCTION_MODES and detail.get("outcome") != "terminal_failed":
            raise EvidenceError(
                "manual_terminal_failure_post_submit_required"
            )
        sources = _mapping(
            committed_evidence.get("sources"),
            "manual_terminal_failure_canary_sources",
        )
        detail["sources"] = _check_terminal_canary_sources(
            sources,
            receipt=receipt,
            expected_collector=(
                settings.host_repo_root / "scripts" / "pnc_rca_canary_collector.py"
            ),
            expected_evidence_dir=settings.evidence_dir,
            expected_control_db_path=dispatcher.control_db_path,
            expected_delivery_db_path=dispatcher.delivery_db_path,
            expected_group_binding_receipt_dir=(
                settings.group_binding_receipt_dir
            ),
            expected_manual_chat_ids=cutover.manual_chat_ids,
            expected_workflow_policy=consumer.policy.to_dict(),
        )
        if (
            cutover.manual_operator_enabled
            and detail.get("operator_authorization_proven") is not True
        ):
            raise EvidenceError("manual_operator_authorization_canary_required")
        return {
            "manual_intake_enabled": True,
            "manual_operator_enabled": cutover.manual_operator_enabled,
            "manual_operator_capability": (
                "enabled" if cutover.manual_operator_enabled else "not_open"
            ),
            "required": True,
            **detail,
        }
    raise EvidenceError("manual_intake_configuration_invalid")


def _public_config(
    consumer: ConsumerConfig,
    dispatcher: DispatcherConfig,
    cutover: CutoverConfig,
) -> dict[str, Any]:
    consumer_public = consumer.public_dict()
    consumer_public["policy"] = consumer.policy.to_dict()
    return {
        "consumer": consumer_public,
        "dispatcher": dispatcher.public_dict(),
        "cutover": cutover.public_dict(),
    }


def _check_consumer_config(
    consumer: ConsumerConfig,
    *,
    mode: str,
    expected_topic: str,
    expected_rule_version: str,
) -> list[str]:
    errors: list[str] = []
    if (
        not kafka_principal_is_valid(consumer.username)
        or consumer.group_id != FIXED_KAFKA_GROUP_ID
        or consumer.client_id != FIXED_SERVICE_ID
    ):
        errors.append("consumer_identity_mismatch")
    if consumer.api_version != FIXED_API_VERSION:
        errors.append("consumer_api_version_mismatch")
    if consumer.request_timeout_ms != FIXED_REQUEST_TIMEOUT_MS:
        errors.append("consumer_request_timeout_mismatch")
    if consumer.security_protocol != "SASL_PLAINTEXT":
        errors.append("consumer_security_protocol_mismatch")
    if consumer.sasl_mechanism != "PLAIN":
        errors.append("consumer_sasl_mechanism_mismatch")
    if consumer.isolation_level != "read_committed":
        errors.append("consumer_isolation_level_mismatch")
    if consumer.auto_offset_reset != "none":
        errors.append("consumer_auto_offset_reset_mismatch")
    if consumer.topic != expected_topic or consumer.policy.topic != expected_topic:
        errors.append("consumer_topic_mismatch")
    if consumer.policy.policy_version != expected_rule_version:
        errors.append("consumer_rule_version_mismatch")
    required_submit = mode in {
        "preauthorization",
        "preproduction",
        *CANARY_MODES,
        *PRODUCTION_MODES,
    }
    if consumer.submit_enabled is not required_submit:
        errors.append("consumer_mode_switch_mismatch")
    if consumer.activation_required is not required_submit:
        errors.append("consumer_activation_mode_mismatch")
    return errors


def _check_dispatcher_config(
    dispatcher: DispatcherConfig,
    *,
    mode: str,
    target_cases_per_day: int,
) -> list[str]:
    errors: list[str] = []
    if dispatcher.service_id != FIXED_SERVICE_ID:
        errors.append("dispatcher_identity_mismatch")
    if mode in BOOTSTRAP_CAPACITY_MODES:
        if dispatcher.capacity_mode != "bootstrap":
            errors.append("dispatcher_bootstrap_capacity_mode_mismatch")
    elif mode in {"canary", "production"} and dispatcher.capacity_mode != "steady":
        errors.append("dispatcher_steady_capacity_mode_mismatch")
    required_enabled = mode in {
        "preauthorization",
        "preproduction",
        *CANARY_MODES,
        *PRODUCTION_MODES,
    }
    if dispatcher.dispatch_enabled is not required_enabled:
        errors.append("dispatcher_mode_switch_mismatch")
    if dispatcher.activation_required is not (mode != "shadow"):
        errors.append("dispatcher_activation_mode_mismatch")
    if dispatcher.allow_feishu_writeback:
        errors.append("dispatcher_writeback_must_be_disabled")
    if dispatcher.data_access_mode != FIXED_REMOTE_ACCESS_CONTRACT["mode"]:
        errors.append("dispatcher_data_access_mode_mismatch")
    if required_enabled and dispatcher.batch_size != 10:
        errors.append("dispatcher_activation_batch_size_mismatch")
    if (
        required_enabled
        and dispatcher.input_wait_max_age_seconds != FIXED_INPUT_WAIT_MAX_AGE_SECONDS
    ):
        errors.append("dispatcher_input_wait_horizon_mismatch")
    if dispatcher.storage_admission_enabled is not required_enabled:
        errors.append("dispatcher_storage_admission_mode_mismatch")
    if dispatcher.storage_reservation_enabled:
        errors.append("dispatcher_legacy_storage_reservation_enabled")
    if (
        required_enabled
        and getattr(dispatcher, "derived_capacity_atomic_reservation", False)
        is not True
    ):
        errors.append("derived_capacity_atomic_reservation_missing")
    if dispatcher.delivery_backpressure_enabled is not required_enabled:
        errors.append("dispatcher_delivery_backpressure_mode_mismatch")
    if required_enabled and dispatcher.storage_cases_per_day < target_cases_per_day:
        errors.append("dispatcher_storage_cases_per_day_below_target")
    if (
        required_enabled
        and dispatcher.storage_expected_artifact_cache_bytes
        != FIXED_STORAGE_EXPECTED_ARTIFACT_CACHE_BYTES
    ):
        errors.append("dispatcher_storage_artifact_cache_bytes_mismatch")
    if (
        required_enabled
        and dispatcher.storage_reserve_percent != FIXED_STORAGE_RESERVE_PERCENT
    ):
        errors.append("dispatcher_storage_reserve_percent_mismatch")
    return errors


def _check_candidate_service_configs(
    runtime_detail: Mapping[str, Any],
    *,
    consumer: ConsumerConfig,
    dispatcher: DispatcherConfig,
    cutover: CutoverConfig,
    mode: str,
) -> dict[str, Any]:
    configs = _mapping(
        runtime_detail.get("service_configs"),
        "runtime_dependencies.service_configs",
    )
    expected_labels = {
        "local.pnc.rca-kafka-consumer",
        "local.pnc.rca-outbox-dispatcher",
        "local.pnc.rca-delivery-collector",
        "local.pnc.rca-delivery-dispatcher",
    }
    if set(configs) != expected_labels:
        raise EvidenceError("runtime_candidate_service_configs_incomplete")
    kafka_config = _mapping(
        configs["local.pnc.rca-kafka-consumer"],
        "runtime_dependencies.kafka_config",
    )
    outbox_config = _mapping(
        configs["local.pnc.rca-outbox-dispatcher"],
        "runtime_dependencies.outbox_config",
    )
    expected_consumer = consumer.public_dict()
    expected_consumer["policy"] = consumer.policy.to_dict()
    if _sha256_json(kafka_config) != _sha256_json(expected_consumer):
        raise EvidenceError("runtime_candidate_consumer_config_mismatch")
    if _sha256_json(outbox_config) != _sha256_json(dispatcher.public_dict()):
        raise EvidenceError("runtime_candidate_outbox_config_mismatch")

    required_enabled = mode in {
        "preauthorization",
        "preproduction",
        *CANARY_MODES,
        *PRODUCTION_MODES,
    }
    activation_required = required_enabled
    activation_projection = {
        "gateway": cutover.activation_required,
        "kafka_consumer": kafka_config.get("activation_required"),
        "outbox_dispatcher": outbox_config.get("activation_required"),
    }
    if (
        activation_required
        and any(value is not True for value in activation_projection.values())
    ) or (
        not activation_required
        and any(
            value is not False
            for name, value in activation_projection.items()
            if name != "gateway"
        )
    ) or (not activation_required and cutover.activation_required is True):
        raise EvidenceError("runtime_candidate_activation_mode_mismatch")
    control_db_path = str(dispatcher.control_db_path)
    collector = _mapping(
        configs["local.pnc.rca-delivery-collector"],
        "runtime_dependencies.delivery_collector_config",
    )
    delivery_dispatcher = _mapping(
        configs["local.pnc.rca-delivery-dispatcher"],
        "runtime_dependencies.delivery_dispatcher_config",
    )
    activation_projection.update({
        "delivery_collector": collector.get("activation_required"),
        "delivery_dispatcher": delivery_dispatcher.get("activation_required"),
    })
    if (
        activation_required
        and any(value is not True for value in activation_projection.values())
    ) or (
        not activation_required
        and any(
            value is not False
            for name, value in activation_projection.items()
            if name != "gateway"
        )
    ):
        raise EvidenceError("runtime_candidate_activation_mode_mismatch")
    if collector.get("enabled") is not required_enabled:
        raise EvidenceError("runtime_candidate_delivery_collector_mode_mismatch")
    if collector.get("capacity_sample_enabled") is not required_enabled:
        raise EvidenceError(
            "runtime_candidate_delivery_capacity_sampling_mode_mismatch"
        )
    if delivery_dispatcher.get("enabled") is not required_enabled:
        raise EvidenceError("runtime_candidate_delivery_dispatcher_mode_mismatch")
    if (
        collector.get("control_db_path") != control_db_path
        or delivery_dispatcher.get("control_db_path") != control_db_path
    ):
        raise EvidenceError("runtime_candidate_delivery_control_db_mismatch")
    if collector.get("external_writes") is not False:
        raise EvidenceError(
            "runtime_candidate_delivery_collector_write_boundary_invalid"
        )
    if delivery_dispatcher.get("external_writes") is not required_enabled:
        raise EvidenceError(
            "runtime_candidate_delivery_dispatcher_write_boundary_invalid"
        )
    collector_lease = _exact_int(
        collector.get("lease_seconds"),
        "runtime_dependencies.delivery_collector_config.lease_seconds",
        minimum=1,
    )
    artifact_timeout = _exact_int(
        collector.get("artifact_read_timeout_seconds"),
        "runtime_dependencies.delivery_collector_config.artifact_read_timeout_seconds",
        minimum=1,
    )
    if collector_lease <= artifact_timeout:
        raise EvidenceError("runtime_candidate_delivery_collector_lease_invalid")
    collector_batch = _exact_int(
        collector.get("batch_size"),
        "runtime_dependencies.delivery_collector_config.batch_size",
        minimum=1,
    )
    if collector_batch > DELIVERY_COLLECTOR_MAX_BATCH_SIZE:
        raise EvidenceError("runtime_candidate_delivery_collector_batch_too_large")
    collector_backfill = _exact_int(
        collector.get("backfill_batch_size"),
        "runtime_dependencies.delivery_collector_config.backfill_batch_size",
        minimum=1,
    )
    if collector_backfill > DELIVERY_COLLECTOR_MAX_BACKFILL_BATCH_SIZE:
        raise EvidenceError(
            "runtime_candidate_delivery_collector_backfill_batch_too_large"
        )
    delivery_lease = _exact_int(
        delivery_dispatcher.get("lease_seconds"),
        "runtime_dependencies.delivery_dispatcher_config.lease_seconds",
        minimum=1,
    )
    external_timeout = _exact_int(
        delivery_dispatcher.get("max_external_boundary_timeout_seconds"),
        "runtime_dependencies.delivery_dispatcher_config.max_external_boundary_timeout_seconds",
        minimum=1,
    )
    margin = _exact_int(
        delivery_dispatcher.get("lease_boundary_margin_seconds"),
        "runtime_dependencies.delivery_dispatcher_config.lease_boundary_margin_seconds",
        minimum=1,
    )
    if delivery_lease <= external_timeout + margin:
        raise EvidenceError("runtime_candidate_delivery_dispatcher_lease_invalid")
    if delivery_dispatcher.get("effect_lease_keeper_enabled") is not True:
        raise EvidenceError(
            "runtime_candidate_delivery_dispatcher_lease_keeper_disabled"
        )
    lease_renew_interval = _exact_int(
        delivery_dispatcher.get("effect_lease_renew_interval_seconds"),
        (
            "runtime_dependencies.delivery_dispatcher_config."
            "effect_lease_renew_interval_seconds"
        ),
        minimum=1,
    )
    if lease_renew_interval > min(
        margin,
        DELIVERY_DISPATCHER_MAX_LEASE_RENEW_INTERVAL_SECONDS,
    ):
        raise EvidenceError(
            "runtime_candidate_delivery_dispatcher_lease_renew_interval_invalid"
        )
    delivery_batch = _exact_int(
        delivery_dispatcher.get("batch_size"),
        "runtime_dependencies.delivery_dispatcher_config.batch_size",
        minimum=1,
    )
    if delivery_batch > DELIVERY_DISPATCHER_MAX_BATCH_SIZE:
        raise EvidenceError("runtime_candidate_delivery_dispatcher_batch_too_large")
    for name, config in (
        ("delivery_collector", collector),
        ("delivery_dispatcher", delivery_dispatcher),
    ):
        _required_text(
            config.get("health_path"),
            f"runtime_dependencies.{name}_config.health_path",
        )
        health_max_age = _exact_int(
            config.get("health_max_age_seconds"),
            f"runtime_dependencies.{name}_config.health_max_age_seconds",
            minimum=1,
        )
        if health_max_age > DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS:
            raise EvidenceError(f"runtime_candidate_{name}_health_max_age_too_large")
    return {
        "service_configs_sha256": _sha256_json(configs),
        "control_db_path_sha256": hashlib.sha256(
            control_db_path.encode("utf-8")
        ).hexdigest(),
        "delivery_collector_enabled": collector["enabled"],
        "delivery_dispatcher_enabled": delivery_dispatcher["enabled"],
        "activation_required": activation_required,
        "activation_required_residents": dict(sorted(activation_projection.items())),
    }


REQUIRED_ACTIVATION_SLOTS = {
    "kafka_success": "kafka",
    "manual_success": "manual",
    "manual_terminal_failure": "manual",
}


def _activation_fence(value: Any, *, field: str) -> dict[str, dict[str, int]]:
    try:
        decoded = _strict_json_loads(_required_text(value, field), artifact=field)
    except EvidenceError as exc:
        raise EvidenceError("activation_partition_fence_invalid") from exc
    if not isinstance(decoded, dict) or not decoded:
        raise EvidenceError("activation_partition_fence_invalid")
    normalized: dict[str, dict[str, int]] = {}
    for raw_topic, raw_partitions in decoded.items():
        topic = str(raw_topic or "").strip()
        if (
            not topic
            or len(topic) > 249
            or not isinstance(raw_partitions, dict)
            or not raw_partitions
        ):
            raise EvidenceError("activation_partition_fence_invalid")
        partitions: dict[str, int] = {}
        for raw_partition, raw_offset in raw_partitions.items():
            partition = str(raw_partition).strip()
            if not partition.isdigit() or isinstance(raw_offset, bool):
                raise EvidenceError("activation_partition_fence_invalid")
            try:
                offset = int(raw_offset)
            except (TypeError, ValueError) as exc:
                raise EvidenceError("activation_partition_fence_invalid") from exc
            if int(partition) < 0 or offset < 0 or str(int(partition)) != partition:
                raise EvidenceError("activation_partition_fence_invalid")
            partitions[partition] = offset
        normalized[topic] = partitions
    if _canonical_json(normalized) != _required_text(value, field):
        raise EvidenceError("activation_partition_fence_not_canonical")
    return normalized


def _read_activation_database(path: Path) -> dict[str, Any]:
    resolved, initial = _observe_live_database_identity(
        path,
        unreadable_code="activation_database_unreadable",
        invalid_code="activation_database_invalid",
    )
    connection: sqlite3.Connection | None = None
    try:
        connection = sqlite3.connect(
            resolved.as_uri() + "?mode=ro",
            uri=True,
            timeout=5,
        )
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA query_only=ON")
        connection.execute("PRAGMA trusted_schema=OFF")
        connection.execute("BEGIN")
        schema_row = connection.execute(
            "SELECT value FROM control_meta WHERE key = 'schema_version'"
        ).fetchone()
        if schema_row is None or str(schema_row[0]) != CONTROL_STORE_SCHEMA_VERSION:
            raise EvidenceError("activation_control_schema_mismatch")
        epochs = connection.execute(
            "SELECT * FROM rca_activation_epochs WHERE is_current = 1"
        ).fetchall()
        if len(epochs) != 1:
            raise EvidenceError("activation_current_epoch_missing")
        epoch = epochs[0]
        epoch_id = str(epoch["epoch_id"])
        slot_rows = connection.execute(
            """
            SELECT s.slot_kind, s.authorized_source_kind,
                   s.authorized_identity_sha256, s.authorized_at,
                   s.authorized_operator, s.authorized_reason,
                   s.consumed_ledger_id, s.consumed_at,
                   al.ledger_id, al.epoch_id AS ledger_epoch_id,
                   al.entrypoint, al.source_kind,
                   al.source_identity_sha256,
                   al.slot_kind AS ledger_slot_kind, al.decision,
                   al.business_key, al.submission_key, al.generation,
                   al.bound_at,
                   t.activation_epoch_id AS trigger_epoch_id,
                   t.activation_ledger_id AS trigger_ledger_id,
                   o.activation_epoch_id AS outbox_epoch_id,
                   o.activation_ledger_id AS outbox_ledger_id,
                   o.status AS outbox_status, o.source_topic,
                   o.source_partition, o.source_offset
              FROM rca_activation_budget_slots AS s
         LEFT JOIN rca_activation_admission_ledger AS al
                ON al.ledger_id = s.consumed_ledger_id
               AND al.epoch_id = s.epoch_id
         LEFT JOIN business_triggers AS t
                ON t.business_key = al.business_key
               AND t.submission_key = al.submission_key
               AND t.generation = al.generation
         LEFT JOIN rca_outbox AS o
                ON o.business_key = al.business_key
               AND o.submission_key = al.submission_key
               AND o.generation = al.generation
             WHERE s.epoch_id = ? ORDER BY s.slot_kind
            """,
            (epoch_id,),
        ).fetchall()
        slots = [dict(row) for row in slot_rows]
        consumed_ids = {
            int(row["consumed_ledger_id"])
            for row in slot_rows
            if row["consumed_ledger_id"] is not None
        }
        unexpected_admissions = int(
            connection.execute(
                """
                SELECT COUNT(*) FROM rca_activation_admission_ledger
                 WHERE epoch_id = ? AND decision IN ('admit', 'join')
                   AND ledger_id NOT IN (
                       SELECT consumed_ledger_id
                         FROM rca_activation_budget_slots
                        WHERE epoch_id = ? AND consumed_ledger_id IS NOT NULL
                   )
                """,
                (epoch_id, epoch_id),
            ).fetchone()[0]
        )
        admitted_ledgers = int(
            connection.execute(
                """
                SELECT COUNT(*) FROM rca_activation_admission_ledger
                 WHERE epoch_id = ? AND decision = 'admit'
                """,
                (epoch_id,),
            ).fetchone()[0]
        )
        pending_inbox = int(
            connection.execute(
                "SELECT COUNT(*) FROM kafka_inbox WHERE decision = 'pending'"
            ).fetchone()[0]
        )
        unbound_ledger = int(
            connection.execute(
                """
                SELECT COUNT(*)
                  FROM rca_activation_admission_ledger AS al
                 WHERE al.epoch_id = ?
                   AND al.decision IN ('admit', 'shadow')
                   AND (
                       al.bound_at IS NULL
                    OR NOT EXISTS (
                        SELECT 1 FROM business_triggers AS t
                         WHERE t.activation_epoch_id = al.epoch_id
                           AND t.activation_ledger_id = al.ledger_id
                           AND t.business_key = al.business_key
                           AND t.submission_key = al.submission_key
                           AND t.generation = al.generation
                    )
                    OR NOT EXISTS (
                        SELECT 1 FROM rca_outbox AS o
                         WHERE o.activation_epoch_id = al.epoch_id
                           AND o.activation_ledger_id = al.ledger_id
                           AND o.business_key = al.business_key
                           AND o.submission_key = al.submission_key
                           AND o.generation = al.generation
                    )
                   )
                """
                ,
                (epoch_id,),
            ).fetchone()[0]
        )
        historical_blocked = int(
            connection.execute(
                """
                SELECT COUNT(*) FROM rca_outbox AS o
                 WHERE o.status IN ('pending', 'claimed')
                   AND (
                       o.activation_epoch_id IS NULL
                       OR o.activation_epoch_id != ?
                       OR o.activation_ledger_id IS NULL
                       OR NOT EXISTS (
                           SELECT 1
                             FROM rca_activation_admission_ledger AS al
                            WHERE al.ledger_id = o.activation_ledger_id
                              AND al.epoch_id = o.activation_epoch_id
                              AND al.decision = 'admit'
                       )
                   )
                """,
                (epoch_id,),
            ).fetchone()[0]
        )
        historical_held = int(
            connection.execute(
                """
                SELECT COUNT(*) FROM rca_outbox AS o
                 WHERE o.status = 'shadow'
                   AND (
                       o.activation_epoch_id IS NULL
                       OR o.activation_epoch_id != ?
                   )
                """,
                (epoch_id,),
            ).fetchone()[0]
        )
        unadjudicated_shadow = int(
            connection.execute(
                """
                SELECT COUNT(*) FROM rca_outbox AS o
                 WHERE o.status = 'shadow'
                   AND (
                       o.activation_ledger_id IS NULL
                       OR NOT EXISTS (
                           SELECT 1
                             FROM rca_activation_admission_ledger AS al
                            WHERE al.ledger_id = o.activation_ledger_id
                              AND al.epoch_id = o.activation_epoch_id
                              AND al.business_key = o.business_key
                              AND al.submission_key = o.submission_key
                              AND al.generation = o.generation
                       )
                   )
                """
            ).fetchone()[0]
        )
        current_dispatchable = int(
            connection.execute(
                """
                SELECT COUNT(*) FROM rca_outbox AS o
                 WHERE o.activation_epoch_id = ?
                   AND o.status IN ('pending', 'claimed')
                   AND EXISTS (
                       SELECT 1
                         FROM rca_activation_admission_ledger AS al
                        WHERE al.ledger_id = o.activation_ledger_id
                          AND al.epoch_id = o.activation_epoch_id
                          AND al.decision = 'admit'
                   )
                """,
                (epoch_id,),
            ).fetchone()[0]
        )
        inflight_writes = int(
            connection.execute(
                "SELECT COUNT(*) FROM rca_outbox WHERE status = 'claimed'"
            ).fetchone()[0]
        )
        delivery_effect_table = connection.execute(
            """
            SELECT 1 FROM sqlite_master
             WHERE type = 'table' AND name = 'rca_delivery_effects'
            """
        ).fetchone()
        if delivery_effect_table is not None:
            inflight_writes += int(
                connection.execute(
                    """
                    SELECT COUNT(*) FROM rca_delivery_effects
                     WHERE status = 'claimed'
                    """
                ).fetchone()[0]
            )
        sqlite_data_version = int(
            connection.execute("PRAGMA data_version").fetchone()[0]
        )
        snapshot = {
            "database": {
                "path": str(resolved),
                "device": int(initial.st_dev),
                "inode": int(initial.st_ino),
            },
            "sqlite_data_version": sqlite_data_version,
            "epoch": {
                key: epoch[key]
                for key in (
                    "epoch_id",
                    "state",
                    "preauthorization_fingerprint",
                    "preauthorization_gate_receipt_sha256",
                    "preauthorization_capsule_sha256",
                    "preproduction_fingerprint",
                    "preproduction_gate_receipt_sha256",
                    "preproduction_capsule_sha256",
                    "config_sha256",
                    "db_logical_identity_json",
                    "db_logical_identity_sha256",
                    "partition_start_fence_json",
                    "partition_start_fence_sha256",
                    "partition_end_fence_json",
                    "partition_end_fence_sha256",
                    "production_fingerprint",
                    "production_gate_receipt_sha256",
                    "bounded_activated_at",
                    "created_at",
                )
            },
            "slots": slots,
            "consumed_ledger_ids": sorted(consumed_ids),
            "admitted_ledgers": admitted_ledgers,
            "unexpected_admissions": unexpected_admissions,
            "pending_inbox": pending_inbox,
            "unbound_ledger": unbound_ledger,
            "historical_blocked": historical_blocked,
            "historical_held": historical_held,
            "unadjudicated_shadow": unadjudicated_shadow,
            "current_dispatchable": current_dispatchable,
            "inflight_writes": inflight_writes,
        }
        connection.rollback()
    except EvidenceError:
        if connection is not None and connection.in_transaction:
            connection.rollback()
        raise
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        if connection is not None and connection.in_transaction:
            connection.rollback()
        raise EvidenceError("activation_database_unreadable") from exc
    finally:
        if connection is not None:
            connection.close()
    _resolved_again, final = _observe_live_database_identity(
        path,
        unreadable_code="activation_database_unreadable",
        invalid_code="activation_database_invalid",
    )
    if (initial.st_dev, initial.st_ino) != (final.st_dev, final.st_ino):
        raise EvidenceError("activation_database_identity_changed")
    snapshot["snapshot_sha256"] = _sha256_json(snapshot)
    return snapshot


def _read_activation_bootstrap_database(path: Path) -> dict[str, Any]:
    """Read the bootstrap state without creating or migrating the database."""
    resolved, initial = _observe_live_database_identity(
        path,
        unreadable_code="activation_database_unreadable",
        invalid_code="activation_database_invalid",
    )
    connection: sqlite3.Connection | None = None
    try:
        connection = sqlite3.connect(
            resolved.as_uri() + "?mode=ro",
            uri=True,
            timeout=5,
        )
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA query_only=ON")
        connection.execute("PRAGMA trusted_schema=OFF")
        connection.execute("BEGIN")
        schema_row = connection.execute(
            "SELECT value FROM control_meta WHERE key = 'schema_version'"
        ).fetchone()
        if schema_row is None or str(schema_row[0]) != CONTROL_STORE_SCHEMA_VERSION:
            raise EvidenceError("activation_control_schema_mismatch")
        epochs = connection.execute(
            "SELECT * FROM rca_activation_epochs ORDER BY created_at, epoch_id"
        ).fetchall()
        current_epochs = [row for row in epochs if int(row["is_current"]) == 1]

        def table_exists(name: str) -> bool:
            return connection.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
                (name,),
            ).fetchone() is not None

        def count(query: str) -> int:
            return int(connection.execute(query).fetchone()[0])

        active = {
            "pending_inbox": count(
                "SELECT COUNT(*) FROM kafka_inbox WHERE decision = 'pending'"
            ),
            "active_activation_admissions": count(
                "SELECT COUNT(*) FROM rca_activation_admission_ledger AS al "
                "WHERE al.decision IN ('admit', 'join', 'shadow') AND ("
                "al.bound_at IS NULL OR EXISTS ("
                "SELECT 1 FROM rca_outbox AS o "
                "WHERE o.activation_epoch_id = al.epoch_id "
                "AND o.activation_ledger_id = al.ledger_id "
                "AND o.business_key = al.business_key "
                "AND o.submission_key = al.submission_key "
                "AND o.generation = al.generation "
                "AND o.status IN ('shadow', 'pending', 'claimed')"
                "))"
            ),
            "active_outbox": count(
                "SELECT COUNT(*) FROM rca_outbox "
                "WHERE status IN ('shadow', 'pending', 'claimed')"
            ),
            "pending_delivery_subscriptions": (
                count(
                    "SELECT COUNT(*) FROM rca_delivery_subscriptions "
                    "WHERE status = 'pending'"
                )
                if table_exists("rca_delivery_subscriptions")
                else 0
            ),
            "active_delivery_effects": (
                count(
                    "SELECT COUNT(*) FROM rca_delivery_effects "
                    "WHERE status IN "
                    "('pending', 'claimed', 'retry_wait', 'uncertain')"
                )
                if table_exists("rca_delivery_effects")
                else 0
            ),
        }
        current = dict(current_epochs[0]) if len(current_epochs) == 1 else None
        snapshot = {
            "database": {
                "path": str(resolved),
                "device": int(initial.st_dev),
                "inode": int(initial.st_ino),
            },
            "epoch_count": len(epochs),
            "current_epoch_count": len(current_epochs),
            "current_epoch": current,
            "active_effects": active,
            "active_effect_count": sum(active.values()),
            "sqlite_data_version": int(
                connection.execute("PRAGMA data_version").fetchone()[0]
            ),
        }
        connection.rollback()
    except EvidenceError:
        if connection is not None and connection.in_transaction:
            connection.rollback()
        raise
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        if connection is not None and connection.in_transaction:
            connection.rollback()
        raise EvidenceError("activation_database_unreadable") from exc
    finally:
        if connection is not None:
            connection.close()
    _resolved_again, final = _observe_live_database_identity(
        path,
        unreadable_code="activation_database_unreadable",
        invalid_code="activation_database_invalid",
    )
    if (initial.st_dev, initial.st_ino) != (final.st_dev, final.st_ino):
        raise EvidenceError("activation_database_identity_changed")
    snapshot["snapshot_sha256"] = _sha256_json(snapshot)
    return snapshot


def _check_activation_epoch_absent(*, control_db_path: Path) -> dict[str, Any]:
    snapshot = _read_activation_bootstrap_database(control_db_path)
    if (
        snapshot["epoch_count"] != 0
        or snapshot["current_epoch_count"] != 0
        or snapshot["active_effect_count"] != 0
    ):
        raise EvidenceError("activation_preauthorization_database_not_pristine")
    return {
        "state": "absent",
        "epoch_count": 0,
        "active_effect_count": 0,
        "database": dict(snapshot["database"]),
        "snapshot_sha256": snapshot["snapshot_sha256"],
    }


def _check_activation_epoch(
    *,
    control_db_path: Path,
    mode: str,
    expected_config_sha256: str,
) -> dict[str, Any]:
    if mode not in {"preproduction", *CANARY_MODES, *PRODUCTION_MODES}:
        raise EvidenceError("activation_mode_invalid")
    snapshot = _read_activation_database(control_db_path)
    epoch = _mapping(snapshot.get("epoch"), "activation.epoch")
    expected_state = {
        "preproduction": "safe_off",
        "canary_bootstrap": "bounded_active",
        "canary": "bounded_active",
        "production_bootstrap": "bounded_active",
        "production": "bounded_active",
    }[mode]
    if epoch.get("state") != expected_state:
        raise EvidenceError(f"activation_{mode}_state_mismatch")
    if epoch.get("config_sha256") != expected_config_sha256:
        raise EvidenceError("activation_config_fingerprint_mismatch")
    preauthorization_bindings = {
        field: _sha256_digest(epoch.get(field), f"activation.{field}")
        for field in (
            "preauthorization_fingerprint",
            "preauthorization_gate_receipt_sha256",
            "preauthorization_capsule_sha256",
        )
    }
    preproduction_fields = (
        "preproduction_fingerprint",
        "preproduction_gate_receipt_sha256",
        "preproduction_capsule_sha256",
    )
    if mode == "preproduction":
        if any(epoch.get(field) is not None for field in preproduction_fields):
            raise EvidenceError("activation_preproduction_binding_already_present")
        preproduction_bindings: dict[str, str | None] = {
            field: None for field in preproduction_fields
        }
    else:
        preproduction_bindings = {
            field: _sha256_digest(epoch.get(field), f"activation.{field}")
            for field in preproduction_fields
        }
    db_identity = _mapping(
        _strict_json_loads(
            _required_text(
                epoch.get("db_logical_identity_json"),
                "activation.db_logical_identity_json",
            ),
            artifact="activation.db_logical_identity_json",
        ),
        "activation.db_logical_identity",
    )
    if (
        not db_identity
        or _sha256_json(db_identity) != epoch.get("db_logical_identity_sha256")
    ):
        raise EvidenceError("activation_database_identity_binding_invalid")
    epoch_created_at = _timestamp(
        epoch.get("created_at"), "activation.epoch.created_at"
    )
    bounded_activated_at = (
        _timestamp(
            epoch.get("bounded_activated_at"),
            "activation.epoch.bounded_activated_at",
        )
        if expected_state == "bounded_active"
        else None
    )
    if bounded_activated_at is not None and bounded_activated_at < epoch_created_at:
        raise EvidenceError("activation_bounded_timestamp_invalid")
    start_fence = _activation_fence(
        epoch.get("partition_start_fence_json"),
        field="activation.partition_start_fence_json",
    )
    if _sha256_json(start_fence) != epoch.get("partition_start_fence_sha256"):
        raise EvidenceError("activation_partition_start_fence_hash_mismatch")
    slots = snapshot.get("slots")
    if not isinstance(slots, list) or {
        str(row.get("slot_kind") or "")
        for row in slots
        if isinstance(row, Mapping)
    } != set(REQUIRED_ACTIVATION_SLOTS) or len(slots) != len(
        REQUIRED_ACTIVATION_SLOTS
    ):
        raise EvidenceError("activation_slot_set_invalid")
    if int(snapshot.get("inflight_writes") or 0) != 0:
        raise EvidenceError("activation_writer_inflight")
    if mode in {"preproduction", *CANARY_MODES}:
        if (
            epoch.get("partition_end_fence_json") is not None
            or epoch.get("partition_end_fence_sha256") is not None
            or epoch.get("production_fingerprint") is not None
            or epoch.get("production_gate_receipt_sha256") is not None
            or snapshot.get("consumed_ledger_ids")
            or int(snapshot.get("admitted_ledgers") or 0) != 0
            or int(snapshot.get("current_dispatchable") or 0) != 0
            or int(snapshot.get("unbound_ledger") or 0) != 0
            or int(snapshot.get("unadjudicated_shadow") or 0) != 0
            or int(snapshot.get("historical_blocked") or 0) != 0
            or int(snapshot.get("historical_held") or 0) != 0
        ):
            raise EvidenceError("activation_preproduction_effects_not_held")
        if mode == "preproduction" and any(
            row.get("authorized_identity_sha256") is not None
            or row.get("authorized_source_kind") is not None
            or row.get("authorized_at") is not None
            or row.get("consumed_ledger_id") is not None
            for row in slots
        ):
            raise EvidenceError("activation_preproduction_slots_not_empty")
        if mode in CANARY_MODES:
            for raw_row in slots:
                row = _mapping(raw_row, "activation.canary_slot")
                slot_kind = str(row.get("slot_kind") or "")
                if (
                    row.get("authorized_source_kind")
                    != REQUIRED_ACTIVATION_SLOTS[slot_kind]
                    or not str(row.get("authorized_identity_sha256") or "")
                    or not str(row.get("authorized_at") or "")
                    or not str(row.get("authorized_operator") or "")
                    or not str(row.get("authorized_reason") or "")
                    or row.get("consumed_ledger_id") is not None
                    or row.get("consumed_at") is not None
                    or row.get("ledger_id") is not None
                ):
                    raise EvidenceError(
                        "activation_canary_slots_not_exactly_authorized"
                    )
        return {
            "epoch_id": str(epoch.get("epoch_id") or ""),
            "state": expected_state,
            **preauthorization_bindings,
            **preproduction_bindings,
            "config_sha256": expected_config_sha256,
            "db_logical_identity_sha256": epoch.get(
                "db_logical_identity_sha256"
            ),
            "db_logical_identity": dict(db_identity),
            "created_at": epoch_created_at.isoformat(),
            **(
                {"bounded_activated_at": bounded_activated_at.isoformat()}
                if bounded_activated_at is not None
                else {}
            ),
            "partition_start_fence_sha256": epoch.get(
                "partition_start_fence_sha256"
            ),
            "partition_start_fence": start_fence,
            "authorized_slots": sorted(
                str(row["slot_kind"])
                for row in slots
                if row.get("authorized_identity_sha256") is not None
            ),
            "slot_authorizations": {
                str(row["slot_kind"]): {
                    "source_kind": str(row["authorized_source_kind"]),
                    "source_identity_sha256": _sha256_digest(
                        row.get("authorized_identity_sha256"),
                        f"activation.{row['slot_kind']}.authorized_identity_sha256",
                    ),
                }
                for row in sorted(slots, key=lambda item: str(item["slot_kind"]))
            }
            if mode in CANARY_MODES
            else {},
            "authorization_complete": mode in CANARY_MODES,
            "slots_unconsumed": True,
            "side_effects_held": True,
            "inflight_writes": 0,
            "unadjudicated_shadow": 0,
            "unbound_ledger": 0,
            "historical_blocked": 0,
            "historical_held": 0,
            "snapshot_sha256": snapshot["snapshot_sha256"],
        }
    if (
        epoch.get("partition_end_fence_json") is not None
        or epoch.get("partition_end_fence_sha256") is not None
        or epoch.get("production_fingerprint") is not None
        or epoch.get("production_gate_receipt_sha256") is not None
    ):
        raise EvidenceError("activation_production_already_confirmed")
    bindings: dict[str, dict[str, Any]] = {}
    execution_bindings: dict[str, dict[str, Any]] = {}
    for raw_row in slots:
        row = _mapping(raw_row, "activation.slot")
        slot_kind = str(row.get("slot_kind") or "")
        ledger_id = row.get("ledger_id")
        if (
            row.get("authorized_source_kind")
            != REQUIRED_ACTIVATION_SLOTS[slot_kind]
            or not str(row.get("authorized_identity_sha256") or "")
            or not str(row.get("authorized_at") or "")
            or not str(row.get("authorized_operator") or "")
            or not str(row.get("authorized_reason") or "")
            or row.get("consumed_ledger_id") is None
            or not str(row.get("consumed_at") or "")
            or ledger_id is None
            or int(row["consumed_ledger_id"]) != int(ledger_id)
            or str(row.get("ledger_epoch_id") or "")
            != str(epoch.get("epoch_id") or "")
            or row.get("source_kind") != REQUIRED_ACTIVATION_SLOTS[slot_kind]
            or row.get("source_identity_sha256")
            != row.get("authorized_identity_sha256")
            or row.get("ledger_slot_kind") != slot_kind
            or row.get("decision") != "admit"
            or not str(row.get("bound_at") or "")
            or row.get("trigger_epoch_id") != epoch.get("epoch_id")
            or int(row.get("trigger_ledger_id") or 0) != int(ledger_id)
            or row.get("outbox_epoch_id") != epoch.get("epoch_id")
            or int(row.get("outbox_ledger_id") or 0) != int(ledger_id)
            or row.get("outbox_status") != "completed"
        ):
            raise EvidenceError("activation_bounded_canary_unbound")
        bindings[slot_kind] = {
            "business_key": str(row.get("business_key") or ""),
            "submission_key": str(row.get("submission_key") or ""),
            "generation": int(row.get("generation") or 0),
            "ledger_id": int(ledger_id),
            "source_identity_sha256": str(row["source_identity_sha256"]),
        }
        execution_bindings[slot_kind] = {
            "entrypoint": str(row["entrypoint"]),
            "source_kind": str(row["source_kind"]),
            "source_identity_sha256": str(row["source_identity_sha256"]),
        }
    kafka = next(
        row for row in slots if row.get("slot_kind") == "kafka_success"
    )
    topic = str(kafka.get("source_topic") or "")
    partition = str(kafka.get("source_partition"))
    offset_raw = kafka.get("source_offset")
    offset = int(offset_raw) if offset_raw is not None else -1
    if (
        topic not in start_fence
        or partition not in start_fence[topic]
        or offset < start_fence[topic][partition]
    ):
        raise EvidenceError("activation_kafka_canary_before_start_fence")
    if (
        int(snapshot.get("admitted_ledgers") or 0) != len(REQUIRED_ACTIVATION_SLOTS)
        or int(snapshot.get("unexpected_admissions") or 0) != 0
        or int(snapshot.get("pending_inbox") or 0) != 0
        or int(snapshot.get("unbound_ledger") or 0) != 0
        or int(snapshot.get("unadjudicated_shadow") or 0) != 0
    ):
        raise EvidenceError("activation_unexpected_admission")
    if (
        int(snapshot.get("historical_blocked") or 0) != 0
        or int(snapshot.get("historical_held") or 0) != 0
    ):
        raise EvidenceError("activation_historical_backlog_not_drained")
    release_binding = {
        "epoch_id": str(epoch.get("epoch_id") or ""),
        "state": expected_state,
        **preauthorization_bindings,
        **preproduction_bindings,
        "config_sha256": expected_config_sha256,
        "db_logical_identity_sha256": epoch.get("db_logical_identity_sha256"),
        "db_logical_identity": dict(db_identity),
        "created_at": epoch_created_at.isoformat(),
        **(
            {"bounded_activated_at": bounded_activated_at.isoformat()}
            if bounded_activated_at is not None
            else {}
        ),
        "partition_start_fence_sha256": epoch.get(
            "partition_start_fence_sha256"
        ),
        "partition_start_fence": start_fence,
        "kafka_coordinate": {
            "topic": topic,
            "partition": int(partition),
            "offset": offset,
        },
        "slot_bindings": bindings,
        "unexpected_admissions": 0,
        "historical_blocked": 0,
        "historical_held": 0,
        "pending_inbox": 0,
        "unbound_ledger": 0,
        "inflight_writes": 0,
    }
    release_binding["release_binding_sha256"] = _sha256_json({
        key: value
        for key, value in release_binding.items()
        if key not in {"db_logical_identity", "created_at"}
    })
    release_binding["snapshot_sha256"] = snapshot["snapshot_sha256"]
    release_binding["slot_execution_bindings"] = execution_bindings
    return release_binding


ACTIVATION_END_FENCE_SIDE_EFFECT_CONTRACT = {
    "consumer_group_join": False,
    "offset_commit": False,
    "offset_fetch": True,
    "partition_pause_mutation": False,
    "topic_write": False,
}


def _activation_end_fence_connection_config(
    consumer: ConsumerConfig,
    partition_start_fence: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "bootstrap_servers": list(consumer.bootstrap_servers),
        "topic": consumer.topic,
        "group_id": consumer.group_id,
        "api_version": list(consumer.api_version),
        "security_protocol": consumer.security_protocol,
        "sasl_mechanism": consumer.sasl_mechanism,
        "request_timeout_ms": consumer.request_timeout_ms,
        "client_id": consumer.client_id,
        "partitions": {
            topic: sorted(int(partition) for partition in partitions)
            for topic, partitions in partition_start_fence.items()
        },
    }


def _activation_offset_sources(
    value: Any,
    *,
    start_fence: Mapping[str, Mapping[str, int]],
    observed_offsets: Mapping[str, Mapping[str, int]],
) -> dict[str, dict[str, dict[str, Any]]]:
    sources = _mapping(value, "activation_end_fence.offset_sources")
    if set(sources) != set(start_fence):
        raise EvidenceError("activation_end_fence_offset_sources_invalid")
    normalized: dict[str, dict[str, dict[str, Any]]] = {}
    for topic, partitions in start_fence.items():
        raw_partitions = _mapping(
            sources.get(topic), f"activation_end_fence.offset_sources.{topic}"
        )
        if set(raw_partitions) != set(partitions):
            raise EvidenceError("activation_end_fence_offset_sources_invalid")
        normalized[topic] = {}
        for partition, start_offset in partitions.items():
            item = _mapping(
                raw_partitions.get(partition),
                f"activation_end_fence.offset_sources.{topic}.{partition}",
            )
            if set(item) != {
                "source",
                "offset",
                "broker_group_offset",
                "freeze_position",
                "start_offset",
            }:
                raise EvidenceError("activation_end_fence_offset_sources_invalid")
            source = str(item.get("source") or "")
            offset = _exact_int(item.get("offset"), "offset_source.offset", minimum=0)
            freeze_position = _exact_int(
                item.get("freeze_position"),
                "offset_source.freeze_position",
                minimum=0,
            )
            declared_start = _exact_int(
                item.get("start_offset"), "offset_source.start_offset", minimum=0
            )
            broker_offset = item.get("broker_group_offset")
            if broker_offset is not None:
                broker_offset = _exact_int(
                    broker_offset,
                    "offset_source.broker_group_offset",
                    minimum=-1,
                )
            expected_offset = int(observed_offsets[topic][partition])
            if (
                offset != expected_offset
                or freeze_position != expected_offset
                or declared_start != int(start_offset)
            ):
                raise EvidenceError("activation_end_fence_offset_sources_invalid")
            if source == "broker_committed":
                if broker_offset is None or broker_offset < 0 or broker_offset != offset:
                    raise EvidenceError("activation_end_fence_offset_sources_invalid")
            elif source == "activation_start_fence":
                if broker_offset not in {None, -1} or offset != int(start_offset):
                    raise EvidenceError("activation_end_fence_offset_sources_invalid")
            else:
                raise EvidenceError("activation_end_fence_offset_sources_invalid")
            normalized[topic][partition] = {
                "source": source,
                "offset": offset,
                "broker_group_offset": broker_offset,
                "freeze_position": freeze_position,
                "start_offset": declared_start,
            }
    return normalized


def _activation_freeze_receipt(
    value: Any,
    *,
    epoch_id: str,
    expected_offsets: Mapping[str, Any],
    expected_runtime_identity_sha256: str,
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    receipt = _mapping(value, "activation_end_fence.freeze_receipt")
    if set(receipt) != {
        "schema_version",
        "epoch_id",
        "state",
        "freeze_token",
        "paused_at",
        "observed_at",
        "consumer_runtime_identity_sha256",
        "partition_positions",
        "restart_required",
    }:
        raise EvidenceError("activation_ingress_freeze_receipt_invalid")
    paused_at = _timestamp(
        receipt.get("paused_at"), "activation_end_fence.freeze_receipt.paused_at"
    )
    observed_at = _timestamp(
        receipt.get("observed_at"),
        "activation_end_fence.freeze_receipt.observed_at",
    )
    age_seconds = (now.astimezone(timezone.utc) - observed_at).total_seconds()
    positions = _mapping(
        receipt.get("partition_positions"),
        "activation_end_fence.freeze_receipt.partition_positions",
    )
    normalized_positions = _activation_fence(
        _canonical_json(positions),
        field="activation_end_fence.freeze_receipt.partition_positions",
    )
    if (
        receipt.get("schema_version") != "pnc_rca_activation_ingress_freeze_v1"
        or receipt.get("epoch_id") != epoch_id
        or receipt.get("state") != "partitions_paused"
        or not _required_text(
            receipt.get("freeze_token"),
            "activation_end_fence.freeze_receipt.freeze_token",
        )
        or observed_at < paused_at
        or age_seconds < -MAX_HEALTH_FUTURE_SKEW_SECONDS
        or age_seconds > max_age_seconds
        or receipt.get("consumer_runtime_identity_sha256")
        != expected_runtime_identity_sha256
        or normalized_positions != expected_offsets
        or receipt.get("restart_required") is not False
    ):
        raise EvidenceError("activation_ingress_freeze_receipt_invalid")
    return {
        **dict(receipt),
        "paused_at": paused_at.isoformat(),
        "observed_at": observed_at.isoformat(),
        "partition_positions": normalized_positions,
    }


def _stable_activation_freeze_receipt(
    receipt: Mapping[str, Any],
) -> dict[str, Any]:
    stable = dict(receipt)
    stable.pop("observed_at", None)
    return stable


def _activation_ingress_freeze_binding(
    *,
    freeze_receipt: Mapping[str, Any],
    health_path: Path,
) -> dict[str, Any]:
    stable_receipt = _stable_activation_freeze_receipt(freeze_receipt)
    positions = _mapping(
        stable_receipt.get("partition_positions"),
        "activation_ingress_freeze_binding.partition_positions",
    )
    return {
        "schema_version": "pnc_rca_activation_ingress_freeze_binding_v1",
        "epoch_id": _required_text(
            stable_receipt.get("epoch_id"),
            "activation_ingress_freeze_binding.epoch_id",
        ),
        "health_path": str(health_path.expanduser().absolute()),
        "paused_at": _required_text(
            stable_receipt.get("paused_at"),
            "activation_ingress_freeze_binding.paused_at",
        ),
        "freeze_receipt_sha256": _sha256_json(stable_receipt),
        "freeze_token_sha256": hashlib.sha256(
            _required_text(
                stable_receipt.get("freeze_token"),
                "activation_ingress_freeze_binding.freeze_token",
            ).encode("utf-8")
        ).hexdigest(),
        "consumer_runtime_identity_sha256": _sha256_digest(
            stable_receipt.get("consumer_runtime_identity_sha256"),
            "activation_ingress_freeze_binding.consumer_runtime_identity_sha256",
        ),
        "partition_positions_sha256": _sha256_json(positions),
        "restart_required": False,
    }


def collect_live_activation_end_fence(
    *,
    consumer: ConsumerConfig,
    partition_start_fence: Mapping[str, Any],
    epoch_id: str,
    consumer_runtime_identity_sha256: str,
    host_repo_root: Path,
    now: datetime | None = None,
    admin_factory: Any = None,
) -> dict[str, Any]:
    """Read exact committed offsets and the resident's no-restart pause receipt."""
    from kafka import KafkaAdminClient, TopicPartition

    current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    start_fence = {
        str(topic): {str(partition): int(offset) for partition, offset in partitions.items()}
        for topic, partitions in partition_start_fence.items()
    }
    if set(start_fence) != {consumer.topic}:
        raise EvidenceError("activation_end_fence_topic_mismatch")
    health = _load_service_health(
        str(consumer.health_path),
        artifact="activation_end_fence_consumer_health",
    )
    identity = _mapping(
        health.get("runtime_identity"),
        "activation_end_fence_consumer_health.runtime_identity",
    )
    stats = _mapping(
        health.get("stats"), "activation_end_fence_consumer_health.stats"
    )
    if (
        _sha256_json(identity) != consumer_runtime_identity_sha256
        or health.get("state") != "activation_frozen"
        or health.get("healthy") is not True
        or health.get("ok") is not True
        or health.get("activation_required") is not True
        or _exact_int(
            stats.get("blocked_partitions"),
            "activation_end_fence_consumer_health.stats.blocked_partitions",
            minimum=0,
        )
        != 0
    ):
        raise EvidenceError("activation_end_fence_consumer_not_frozen")
    raw_freeze = _mapping(
        health.get("activation_freeze"),
        "activation_end_fence_consumer_health.activation_freeze",
    )
    freeze_positions = _activation_fence(
        _canonical_json(
            _mapping(
                raw_freeze.get("partition_positions"),
                "activation_end_fence_consumer_health.partition_positions",
            )
        ),
        field="activation_end_fence_consumer_health.partition_positions",
    )
    if (
        set(freeze_positions) != set(start_fence)
        or any(
            set(freeze_positions[topic]) != set(start_fence[topic])
            for topic in start_fence
        )
    ):
        raise EvidenceError("activation_ingress_freeze_receipt_invalid")
    freeze = _activation_freeze_receipt(
        raw_freeze,
        epoch_id=epoch_id,
        expected_offsets=freeze_positions,
        expected_runtime_identity_sha256=consumer_runtime_identity_sha256,
        now=current,
        max_age_seconds=DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS,
    )
    topic_partitions = [
        TopicPartition(topic, int(partition))
        for topic, partitions in start_fence.items()
        for partition in partitions
    ]
    factory = admin_factory or KafkaAdminClient
    admin = None
    try:
        admin = factory(
            bootstrap_servers=list(consumer.bootstrap_servers),
            client_id=f"{consumer.client_id}-activation-gate",
            api_version=consumer.api_version,
            security_protocol=consumer.security_protocol,
            sasl_mechanism=consumer.sasl_mechanism,
            sasl_plain_username=consumer.username,
            sasl_plain_password=consumer.password,
            request_timeout_ms=consumer.request_timeout_ms,
        )
        group_offsets = admin.list_group_offsets({
            consumer.group_id: topic_partitions
        })
    except Exception as exc:
        raise EvidenceError("activation_end_fence_broker_probe_failed") from exc
    finally:
        if admin is not None:
            try:
                admin.close()
            except Exception:
                pass
    if not isinstance(group_offsets, Mapping):
        raise EvidenceError("activation_end_fence_broker_offsets_incomplete")
    offsets = group_offsets.get(consumer.group_id, {})
    if not isinstance(offsets, Mapping) or not set(offsets).issubset(topic_partitions):
        raise EvidenceError("activation_end_fence_broker_offsets_incomplete")
    observed_offsets: dict[str, dict[str, int]] = {consumer.topic: {}}
    offset_sources: dict[str, dict[str, dict[str, Any]]] = {consumer.topic: {}}
    for topic_partition in topic_partitions:
        offset_and_metadata = offsets.get(topic_partition)
        broker_offset = (
            getattr(offset_and_metadata, "offset", None)
            if offset_and_metadata is not None
            else None
        )
        if (
            broker_offset is not None
            and (
                isinstance(broker_offset, bool)
                or not isinstance(broker_offset, int)
                or broker_offset < -1
            )
        ):
            raise EvidenceError("activation_end_fence_broker_offset_invalid")
        topic = topic_partition.topic
        partition = str(topic_partition.partition)
        freeze_position = int(freeze_positions[topic][partition])
        start_offset = int(start_fence[topic][partition])
        if broker_offset is not None and broker_offset >= 0:
            if broker_offset != freeze_position:
                raise EvidenceError("activation_end_fence_broker_freeze_mismatch")
            source = "broker_committed"
        else:
            if freeze_position != start_offset:
                raise EvidenceError(
                    "activation_end_fence_uncommitted_offset_not_at_start"
                )
            source = "activation_start_fence"
        observed_offsets[topic][partition] = freeze_position
        offset_sources[topic][partition] = {
            "source": source,
            "offset": freeze_position,
            "broker_group_offset": broker_offset,
            "freeze_position": freeze_position,
            "start_offset": start_offset,
        }
    offset_sources = _activation_offset_sources(
        offset_sources,
        start_fence=start_fence,
        observed_offsets=observed_offsets,
    )
    collector_path = (
        host_repo_root / "scripts" / "pnc_rca_release_gate.py"
    ).expanduser().resolve(strict=True)
    connection_config = _activation_end_fence_connection_config(
        consumer,
        start_fence,
    )
    return {
        "schema_version": "pnc_rca_activation_end_fence_collector_v3",
        "observed_at": current.isoformat(),
        "operation": "read_only_group_offsets_under_resident_pause",
        "group_id": consumer.group_id,
        "topic": consumer.topic,
        "consumer_runtime_identity_sha256": consumer_runtime_identity_sha256,
        "connection_config_sha256": _sha256_json(connection_config),
        "collector_path": str(collector_path),
        "collector_sha256": hashlib.sha256(collector_path.read_bytes()).hexdigest(),
        "observed_offsets": observed_offsets,
        "offset_sources": offset_sources,
        "offset_sources_sha256": _sha256_json(offset_sources),
        "freeze_receipt": freeze,
        "restart_required": False,
        "side_effect_contract": ACTIVATION_END_FENCE_SIDE_EFFECT_CONTRACT,
    }


def build_activation_production_candidate(
    *,
    activation: Mapping[str, Any],
    expected_config_sha256: str,
    collector: Mapping[str, Any],
    now: datetime | None = None,
) -> dict[str, Any]:
    current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    return {
        "schema_version": ACTIVATION_PRODUCTION_CANDIDATE_SCHEMA_VERSION,
        "observed_at": current.isoformat(),
        "read_only": True,
        "external_side_effects": False,
        "epoch_id": activation.get("epoch_id"),
        "config_sha256": expected_config_sha256,
        "partition_start_fence_sha256": activation.get(
            "partition_start_fence_sha256"
        ),
        "partition_end_fence": dict(
            _mapping(
                collector.get("observed_offsets"),
                "activation_production_candidate.collector.observed_offsets",
            )
        ),
        "collector": dict(collector),
    }


def _check_activation_production_candidate(
    body: Mapping[str, Any],
    *,
    activation: Mapping[str, Any],
    consumer: ConsumerConfig,
    expected_config_sha256: str,
    expected_consumer_runtime_identity_sha256: str,
    expected_host_repo_root: Path,
    live_collector: Mapping[str, Any],
    now: datetime,
    max_age_seconds: int,
) -> dict[str, Any]:
    artifact = "activation_production_candidate"
    _require_schema(body, ACTIVATION_PRODUCTION_CANDIDATE_SCHEMA_VERSION, artifact)
    if set(body) != {
        "schema_version",
        "observed_at",
        "read_only",
        "external_side_effects",
        "epoch_id",
        "config_sha256",
        "partition_start_fence_sha256",
        "partition_end_fence",
        "collector",
    }:
        raise EvidenceError("activation_production_candidate_shape_invalid")
    observed_at = _require_fresh(
        body,
        now=now,
        max_age_seconds=max_age_seconds,
        artifact=artifact,
    )
    if (
        body.get("read_only") is not True
        or body.get("external_side_effects") is not False
        or body.get("epoch_id") != activation.get("epoch_id")
        or body.get("config_sha256") != expected_config_sha256
        or body.get("partition_start_fence_sha256")
        != activation.get("partition_start_fence_sha256")
    ):
        raise EvidenceError("activation_production_candidate_binding_mismatch")
    start_fence = _mapping(
        activation.get("partition_start_fence"),
        "activation.partition_start_fence",
    )
    end_value = _mapping(
        body.get("partition_end_fence"),
        "activation_production_candidate.partition_end_fence",
    )
    end_fence = _activation_fence(
        _canonical_json(end_value),
        field="activation_production_candidate.partition_end_fence",
    )
    if set(start_fence) != set(end_fence) or any(
        set(start_fence[topic]) != set(end_fence[topic])
        or any(
            end_fence[topic][partition] < int(start_offset)
            for partition, start_offset in start_fence[topic].items()
        )
        for topic in start_fence
    ):
        raise EvidenceError("activation_partition_end_fence_invalid")
    kafka = _mapping(
        activation.get("kafka_coordinate"), "activation.kafka_coordinate"
    )
    topic = str(kafka.get("topic") or "")
    partition = str(kafka.get("partition"))
    offset = _exact_int(
        kafka.get("offset"), "activation.kafka_coordinate.offset", minimum=0
    )
    if (
        topic not in end_fence
        or partition not in end_fence[topic]
        or offset >= end_fence[topic][partition]
    ):
        raise EvidenceError("activation_kafka_canary_outside_end_fence")
    collector = _mapping(
        body.get("collector"), "activation_production_candidate.collector"
    )
    expected_collector_path = (
        expected_host_repo_root / "scripts" / "pnc_rca_release_gate.py"
    ).expanduser().resolve(strict=True)
    expected_collector_sha256 = hashlib.sha256(
        expected_collector_path.read_bytes()
    ).hexdigest()
    expected_connection_sha256 = _sha256_json(
        _activation_end_fence_connection_config(consumer, start_fence)
    )

    def validate_collector(
        value: Mapping[str, Any],
        *,
        field: str,
        expected_offsets: Mapping[str, Any] | None,
        freshness_seconds: int,
    ) -> dict[str, Any]:
        item = _mapping(value, field)
        if set(item) != {
            "schema_version",
            "observed_at",
            "operation",
            "group_id",
            "topic",
            "consumer_runtime_identity_sha256",
            "connection_config_sha256",
            "collector_path",
            "collector_sha256",
            "observed_offsets",
            "offset_sources",
            "offset_sources_sha256",
            "freeze_receipt",
            "restart_required",
            "side_effect_contract",
        }:
            raise EvidenceError("activation_end_fence_collector_invalid")
        collector_observed_at = _timestamp(
            item.get("observed_at"), f"{field}.observed_at"
        )
        age_seconds = (
            now.astimezone(timezone.utc) - collector_observed_at
        ).total_seconds()
        raw_offsets = _mapping(item.get("observed_offsets"), f"{field}.offsets")
        normalized_offsets = _activation_fence(
            _canonical_json(raw_offsets), field=f"{field}.observed_offsets"
        )
        normalized_sources = _activation_offset_sources(
            item.get("offset_sources"),
            start_fence=start_fence,
            observed_offsets=normalized_offsets,
        )
        freeze = _activation_freeze_receipt(
            item.get("freeze_receipt"),
            epoch_id=str(activation.get("epoch_id") or ""),
            expected_offsets=normalized_offsets,
            expected_runtime_identity_sha256=(
                expected_consumer_runtime_identity_sha256
            ),
            now=now,
            max_age_seconds=freshness_seconds,
        )
        if (
            item.get("schema_version")
            != "pnc_rca_activation_end_fence_collector_v3"
            or item.get("operation")
            != "read_only_group_offsets_under_resident_pause"
            or item.get("group_id") != consumer.group_id
            or item.get("topic") != consumer.topic
            or item.get("consumer_runtime_identity_sha256")
            != expected_consumer_runtime_identity_sha256
            or item.get("connection_config_sha256")
            != expected_connection_sha256
            or item.get("collector_path") != str(expected_collector_path)
            or item.get("collector_sha256") != expected_collector_sha256
            or item.get("offset_sources_sha256")
            != _sha256_json(normalized_sources)
            or (
                expected_offsets is not None
                and normalized_offsets != expected_offsets
            )
            or item.get("restart_required") is not False
            or item.get("side_effect_contract")
            != ACTIVATION_END_FENCE_SIDE_EFFECT_CONTRACT
            or age_seconds < -MAX_HEALTH_FUTURE_SKEW_SECONDS
            or age_seconds > freshness_seconds
        ):
            raise EvidenceError("activation_end_fence_collector_invalid")
        return {
            **dict(item),
            "observed_offsets": normalized_offsets,
            "offset_sources": normalized_sources,
            "freeze_receipt": freeze,
        }

    normalized_collector = validate_collector(
        collector,
        field="activation_production_candidate.collector",
        expected_offsets=end_fence,
        freshness_seconds=max_age_seconds,
    )
    normalized_live_collector = validate_collector(
        live_collector,
        field="activation_production_candidate.live_collector",
        expected_offsets=None,
        freshness_seconds=min(
            max_age_seconds,
            DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS,
        ),
    )

    def stable_collector(value: Mapping[str, Any]) -> dict[str, Any]:
        stable = dict(value)
        stable.pop("observed_at", None)
        stable["freeze_receipt"] = _stable_activation_freeze_receipt(
            _mapping(
                stable.get("freeze_receipt"),
                "activation_production_candidate.stable_freeze_receipt",
            )
        )
        return stable

    if stable_collector(normalized_collector) != stable_collector(
        normalized_live_collector
    ):
        raise EvidenceError("activation_end_fence_live_recheck_mismatch")
    ingress_freeze_binding = _activation_ingress_freeze_binding(
        freeze_receipt=_mapping(
            normalized_live_collector.get("freeze_receipt"),
            "activation_production_candidate.live_freeze_receipt",
        ),
        health_path=consumer.health_path,
    )
    end_fence_sha256 = _sha256_json(end_fence)
    confirm_input = {
        "epoch_id": activation.get("epoch_id"),
        "expected_state": "bounded_active",
        "target_state": "confirmed",
        "config_sha256": expected_config_sha256,
        "db_logical_identity_sha256": activation.get(
            "db_logical_identity_sha256"
        ),
        "partition_start_fence_sha256": activation.get(
            "partition_start_fence_sha256"
        ),
        "release_binding_sha256": activation.get("release_binding_sha256"),
        "partition_end_fence": end_fence,
        "partition_end_fence_sha256": end_fence_sha256,
        "production_fingerprint_source": "release_gate_report.fingerprint",
        "production_gate_receipt_sha256_source": (
            "sha256(exact_written_release_gate_receipt)"
        ),
        "restart_between_gate_and_confirm": False,
    }
    return {
        "observed_at": observed_at,
        "epoch_id": activation.get("epoch_id"),
        "partition_end_fence_sha256": end_fence_sha256,
        "collector_sha256": _sha256_json(normalized_collector),
        "live_collector_sha256": _sha256_json(normalized_live_collector),
        "ingress_frozen": True,
        "ingress_freeze_binding": ingress_freeze_binding,
        "confirm_input": confirm_input,
        "confirm_input_sha256": _sha256_json(confirm_input),
    }


def _check_activation_slot_plan(
    activation: Mapping[str, Any],
    slot_plan: Mapping[str, Any],
    *,
    require_consumed: bool,
) -> dict[str, Any]:
    planned = _mapping(slot_plan, "activation.canary_slot_plan")
    if set(planned) != set(REQUIRED_ACTIVATION_SLOTS):
        raise EvidenceError("activation_canary_plan_unverified")
    observed_field = "slot_bindings" if require_consumed else "slot_authorizations"
    observed = _mapping(
        activation.get(observed_field), f"activation.{observed_field}"
    )
    if set(observed) != set(REQUIRED_ACTIVATION_SLOTS):
        raise EvidenceError("activation_canary_plan_slot_set_mismatch")
    binding: dict[str, Any] = {}
    execution_bindings = (
        _mapping(
            activation.get("slot_execution_bindings"),
            "activation.slot_execution_bindings",
        )
        if require_consumed
        else {}
    )
    if require_consumed and set(execution_bindings) != set(
        REQUIRED_ACTIVATION_SLOTS
    ):
        raise EvidenceError("activation_canary_plan_slot_set_mismatch")
    for slot_kind in sorted(REQUIRED_ACTIVATION_SLOTS):
        expected = _mapping(
            planned.get(slot_kind), f"activation.canary_plan.{slot_kind}"
        )
        actual = _mapping(
            observed.get(slot_kind), f"activation.observed_slot.{slot_kind}"
        )
        execution = (
            _mapping(
                execution_bindings.get(slot_kind),
                f"activation.execution_slot.{slot_kind}",
            )
            if require_consumed
            else actual
        )
        if (
            execution.get("source_kind") != expected.get("source_kind")
            or (
                require_consumed
                and execution.get("entrypoint") != expected.get("entrypoint")
            )
            or execution.get("source_identity_sha256")
            != expected.get("source_identity_sha256")
        ):
            raise EvidenceError("activation_canary_plan_identity_mismatch")
        expected_admission = _mapping(
            expected.get("expected_admission"),
            f"activation.canary_plan.{slot_kind}.expected_admission",
        )
        admission_projection = {
            key: expected_admission.get(key)
            for key in ("business_key", "submission_key", "generation")
        }
        if require_consumed and any(
            actual.get(key) != value
            for key, value in admission_projection.items()
        ):
            raise EvidenceError("activation_canary_plan_admission_mismatch")
        binding[slot_kind] = {
            "source_kind": expected["source_kind"],
            "entrypoint": expected["entrypoint"],
            "source_identity_sha256": expected["source_identity_sha256"],
            "expected_admission": admission_projection,
            "consumed": require_consumed,
        }
    return {
        "slot_count": len(binding),
        "consumed": require_consumed,
        "slots_sha256": _sha256_json(planned),
        "binding_sha256": _sha256_json(binding),
    }


def _check_activation_canary_bindings(
    activation: Mapping[str, Any],
    *,
    slot_plan: Mapping[str, Any],
    kafka_admission: Mapping[str, Any],
    manual_success_admission: Mapping[str, Any],
    manual_terminal_admission: Mapping[str, Any],
    kafka_detail: Mapping[str, Any],
    manual_success_detail: Mapping[str, Any],
    manual_terminal_detail: Mapping[str, Any],
) -> dict[str, Any]:
    bindings = _mapping(
        activation.get("slot_bindings"), "activation.slot_bindings"
    )
    execution_bindings = _mapping(
        activation.get("slot_execution_bindings"),
        "activation.slot_execution_bindings",
    )
    expected = {
        "kafka_success": kafka_admission,
        "manual_success": manual_success_admission,
        "manual_terminal_failure": manual_terminal_admission,
    }
    details = {
        "kafka_success": kafka_detail,
        "manual_success": manual_success_detail,
        "manual_terminal_failure": manual_terminal_detail,
    }
    planned = _mapping(slot_plan, "activation.canary_slot_plan")
    if set(planned) != set(expected):
        raise EvidenceError("activation_canary_plan_unverified")
    normalized: dict[str, dict[str, Any]] = {}
    for slot_kind, admission_value in expected.items():
        admission = _mapping(admission_value, f"activation.{slot_kind}.admission")
        binding = _mapping(bindings.get(slot_kind), f"activation.{slot_kind}.binding")
        execution_binding = _mapping(
            execution_bindings.get(slot_kind),
            f"activation.{slot_kind}.execution_binding",
        )
        planned_slot = _mapping(
            planned.get(slot_kind), f"activation.canary_plan.{slot_kind}"
        )
        planned_admission = _mapping(
            planned_slot.get("expected_admission"),
            f"activation.canary_plan.{slot_kind}.expected_admission",
        )
        projection = {
            "business_key": _required_text(
                admission.get("business_key"), f"activation.{slot_kind}.business_key"
            ),
            "submission_key": _required_text(
                admission.get("submission_key"),
                f"activation.{slot_kind}.submission_key",
            ),
            "generation": _exact_int(
                admission.get("generation"),
                f"activation.{slot_kind}.generation",
                minimum=1,
            ),
        }
        planned_projection = {
            key: planned_admission.get(key)
            for key in ("business_key", "submission_key", "generation")
        }
        if (
            projection != planned_projection
            or any(binding.get(key) != value for key, value in projection.items())
            or execution_binding.get("source_kind")
            != planned_slot.get("source_kind")
            or execution_binding.get("entrypoint")
            != planned_slot.get("entrypoint")
            or execution_binding.get("source_identity_sha256")
            != planned_slot.get("source_identity_sha256")
        ):
            raise EvidenceError("activation_canary_receipt_binding_mismatch")
        detail = _mapping(details[slot_kind], f"activation.{slot_kind}.detail")
        planned_identity = _mapping(
            planned_slot.get("source_identity"),
            f"activation.canary_plan.{slot_kind}.source_identity",
        )
        if slot_kind == "kafka_success":
            source = _mapping(
                detail.get("execution_origin"),
                "activation.kafka_success.execution_origin",
            )
            event_uid = _required_text(
                source.get("kafka_event_uid"),
                "activation.kafka_success.kafka_event_uid",
            )
            parts = event_uid.rsplit(":", 2)
            if len(parts) != 3 or not parts[1].isdigit() or not parts[2].isdigit():
                raise EvidenceError("activation_canary_receipt_source_invalid")
            source_identity: dict[str, Any] = {
                "event_uid": event_uid,
                "offset": int(parts[2]),
                "partition": int(parts[1]),
                "topic": parts[0],
            }
            outcome = "success" if detail.get("outbox_status") == "completed" else ""
        else:
            source_field = (
                "execution_origin"
                if slot_kind == "manual_success"
                else "observed_trigger_source"
            )
            source = _mapping(
                detail.get(source_field),
                f"activation.{slot_kind}.{source_field}",
            )
            source_identity = {
                field: source.get(field)
                for field in (
                    "chat_id",
                    "requester_id",
                    "message_id",
                    "thread_id",
                    "mode",
                )
            }
            admission_refs = _mapping(
                admission.get("source_refs"),
                f"activation.{slot_kind}.admission.source_refs",
            )
            source_identity["issue_url"] = (
                "https://project.feishu.cn/"
                f"{_required_text(admission_refs.get('project_simple_name'), 'activation.project_simple_name')}"
                "/issue/detail/"
                f"{_required_text(admission_refs.get('work_item_id'), 'activation.work_item_id')}"
            )
            outcome = (
                "success"
                if slot_kind == "manual_success"
                and detail.get("outbox_status") == "completed"
                else str(detail.get("outcome") or "")
            )
        if (
            _sha256_json(source_identity)
            != planned_slot.get("source_identity_sha256")
            or source_identity != planned_identity
            or outcome != planned_slot.get("expected_outcome")
        ):
            raise EvidenceError("activation_canary_receipt_source_invalid")
        normalized[slot_kind] = {
            **projection,
            "source_identity_sha256": planned_slot["source_identity_sha256"],
            "outcome": outcome,
        }
    if len({item["submission_key"] for item in normalized.values()}) != len(
        REQUIRED_ACTIVATION_SLOTS
    ):
        raise EvidenceError("activation_canary_receipt_not_independent")
    return {
        "epoch_id": activation.get("epoch_id"),
        "slot_count": len(normalized),
        "slot_plan_sha256": _sha256_json(planned),
        "canary_bindings_sha256": _sha256_json(normalized),
    }


def _load_service_health(path_value: Any, *, artifact: str) -> dict[str, Any]:
    path = Path(_required_text(path_value, f"{artifact}.path")).expanduser()
    try:
        info = os.lstat(path)
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISREG(info.st_mode):
            raise EvidenceError(f"{artifact}_invalid_file")
        if info.st_size <= 0 or info.st_size > MAX_EVIDENCE_BYTES:
            raise EvidenceError(f"{artifact}_too_large")
        raw = path.read_text(encoding="utf-8")
    except EvidenceError:
        raise
    except (OSError, UnicodeError) as exc:
        raise EvidenceError(f"{artifact}_missing") from exc
    return _mapping(_strict_json_loads(raw, artifact=artifact), artifact)


def _launchctl_process_evidence(
    *,
    service_label: str,
    pid: int,
    artifact: str,
    expected_loaded_config: Mapping[str, Any] | None = None,
    runner: Any = subprocess.run,
) -> dict[str, Any]:
    command = [
        "/bin/launchctl",
        "print",
        f"gui/{os.getuid()}/{service_label}",
    ]
    try:
        completed = runner(
            command,
            text=True,
            capture_output=True,
            timeout=10,
            check=False,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise EvidenceError(f"{artifact}_launchctl_unavailable") from exc
    stdout = str(completed.stdout or "")
    if completed.returncode != 0 or len(stdout.encode("utf-8")) > 65_536:
        raise EvidenceError(f"{artifact}_launchctl_unavailable")
    if re.search(r"(?m)^\s*state\s*=\s*running\s*$", stdout) is None:
        raise EvidenceError(f"{artifact}_launchctl_not_running")
    launchd_pids = {
        int(match) for match in re.findall(r"(?m)^\s*pid\s*=\s*([0-9]+)\s*$", stdout)
    }
    if launchd_pids != {pid}:
        raise EvidenceError(f"{artifact}_launchctl_pid_mismatch")
    result = {
        "domain": f"gui/{os.getuid()}",
        "state": "running",
        "pid": pid,
    }
    if expected_loaded_config is not None:
        def scalar(name: str) -> str:
            matches = re.findall(
                rf"(?m)^\s*{re.escape(name)}\s*=\s*(.*?)\s*$",
                stdout,
            )
            if len(matches) != 1 or not matches[0]:
                raise EvidenceError(f"{artifact}_launchctl_config_unavailable")
            return matches[0]

        def block(name: str) -> list[str]:
            match = re.search(
                rf"(?ms)^\s*{re.escape(name)}\s*=\s*\{{\s*\n(.*?)^\s*\}}\s*$",
                stdout,
            )
            if match is None:
                raise EvidenceError(f"{artifact}_launchctl_config_unavailable")
            return [line.strip() for line in match.group(1).splitlines() if line.strip()]

        expected_arguments = expected_loaded_config.get("program_arguments")
        expected_environment = expected_loaded_config.get("environment")
        if (
            not isinstance(expected_arguments, list)
            or not all(isinstance(item, str) and item for item in expected_arguments)
            or not isinstance(expected_environment, Mapping)
        ):
            raise EvidenceError(f"{artifact}_launchctl_config_invalid")
        loaded_arguments = block("arguments")
        loaded_environment: dict[str, str] = {}
        for line in block("environment"):
            key, separator, value = line.partition(" => ")
            if not separator or not key or key in loaded_environment:
                raise EvidenceError(f"{artifact}_launchctl_config_unavailable")
            loaded_environment[key] = value
        allowed_launchd_extras = {"OSLogRateLimit", "XPC_SERVICE_NAME"}
        loaded_extra_keys = set(loaded_environment) - {
            str(key) for key in expected_environment
        }
        if (
            scalar("path") != expected_loaded_config.get("plist_path")
            or scalar("program") != expected_arguments[0]
            or loaded_arguments != expected_arguments
            or scalar("working directory")
            != expected_loaded_config.get("working_directory")
            or any(
                loaded_environment.get(str(key)) != str(value)
                for key, value in expected_environment.items()
            )
            or not loaded_extra_keys.issubset(allowed_launchd_extras)
            or _unsafe_runtime_environment_keys(loaded_environment)
            or (
                "XPC_SERVICE_NAME" in loaded_environment
                and loaded_environment["XPC_SERVICE_NAME"] != service_label
            )
        ):
            raise EvidenceError(f"{artifact}_launchctl_config_mismatch")
        result.update({
            "plist_path_sha256": hashlib.sha256(
                str(expected_loaded_config["plist_path"]).encode("utf-8")
            ).hexdigest(),
            "program_arguments_sha256": _sha256_json(loaded_arguments),
            "working_directory_sha256": hashlib.sha256(
                str(expected_loaded_config["working_directory"]).encode("utf-8")
            ).hexdigest(),
            "environment_sha256": _sha256_json(dict(sorted(loaded_environment.items()))),
            "required_environment_keys": sorted(str(key) for key in expected_environment),
        })
    return result


def _unsafe_runtime_environment_keys(environment: Mapping[str, Any]) -> set[str]:
    allowed_python = {"PYTHONDONTWRITEBYTECODE", "PYTHONNOUSERSITE"}
    return {
        str(key)
        for key in environment
        if str(key).startswith(("DYLD_", "LD_"))
        or (
            str(key).startswith("PYTHON")
            and str(key) not in allowed_python
        )
    }


def _verify_installed_launchd_plist(
    candidate: Mapping[str, Any],
    *,
    artifact: str,
) -> dict[str, Any]:
    path = Path(
        _required_text(candidate.get("plist_path"), f"{artifact}.plist_path")
    ).expanduser().absolute()
    expected_sha256 = _sha256_digest(
        candidate.get("plist_sha256"),
        f"{artifact}.plist_sha256",
    )
    descriptor = -1
    try:
        initial = os.lstat(path)
        if (
            stat.S_ISLNK(initial.st_mode)
            or not stat.S_ISREG(initial.st_mode)
            or initial.st_uid != os.getuid()
            or initial.st_nlink != 1
            or stat.S_IMODE(initial.st_mode) & 0o022
            or initial.st_size <= 0
            or initial.st_size > MAX_EVIDENCE_BYTES
            or path.resolve(strict=True) != path
        ):
            raise EvidenceError(f"{artifact}_installed_plist_invalid")
        descriptor = os.open(
            path,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
        )
        opened = os.fstat(descriptor)
        expected_identity = (
            initial.st_dev,
            initial.st_ino,
            initial.st_size,
            initial.st_mtime_ns,
        )
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_uid != os.getuid()
            or opened.st_nlink != 1
            or (opened.st_dev, opened.st_ino, opened.st_size, opened.st_mtime_ns)
            != expected_identity
        ):
            raise EvidenceError(f"{artifact}_installed_plist_invalid")
        remaining = opened.st_size
        chunks: list[bytes] = []
        while remaining:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise EvidenceError(f"{artifact}_installed_plist_invalid")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise EvidenceError(f"{artifact}_installed_plist_invalid")
        final_opened = os.fstat(descriptor)
        final_path = os.lstat(path)
        if (
            (
                final_opened.st_dev,
                final_opened.st_ino,
                final_opened.st_size,
                final_opened.st_mtime_ns,
            )
            != expected_identity
            or (
                final_path.st_dev,
                final_path.st_ino,
                final_path.st_size,
                final_path.st_mtime_ns,
            )
            != expected_identity
        ):
            raise EvidenceError(f"{artifact}_installed_plist_invalid")
        raw = b"".join(chunks)
    except EvidenceError:
        raise
    except OSError as exc:
        raise EvidenceError(f"{artifact}_installed_plist_invalid") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise EvidenceError(f"{artifact}_installed_plist_mismatch")
    try:
        body = plistlib.loads(raw)
    except plistlib.InvalidFileException as exc:
        raise EvidenceError(f"{artifact}_installed_plist_invalid") from exc
    expected_arguments = candidate.get("program_arguments")
    expected_environment = candidate.get("environment")
    if (
        not isinstance(body, dict)
        or body.get("Label") != candidate.get("service_label")
        or body.get("ProgramArguments") != expected_arguments
        or body.get("WorkingDirectory") != candidate.get("working_directory")
        or body.get("EnvironmentVariables") != expected_environment
    ):
        raise EvidenceError(f"{artifact}_installed_plist_mismatch")
    return {
        "path_sha256": hashlib.sha256(str(path).encode("utf-8")).hexdigest(),
        "sha256": expected_sha256,
    }


def _verify_delivery_service_process(
    identity: Mapping[str, Any],
    candidate: Mapping[str, Any],
    *,
    artifact: str,
    process_factory: Any = psutil.Process,
    boot_time_reader: Any = psutil.boot_time,
    launchctl_runner: Any = subprocess.run,
) -> dict[str, Any]:
    installed_plist = None
    if candidate.get("verify_loaded_configuration") is True:
        installed_plist = _verify_installed_launchd_plist(
            candidate,
            artifact=artifact,
        )
    pid = _exact_int(identity.get("pid"), f"{artifact}.runtime_identity.pid", minimum=1)
    expected_create_time = _number(
        identity.get("process_create_time"),
        f"{artifact}.runtime_identity.process_create_time",
        minimum=1,
    )
    expected_boot_time = _number(
        identity.get("boot_time"),
        f"{artifact}.runtime_identity.boot_time",
        minimum=1,
    )
    try:
        process = process_factory(pid)
        actual_create_time = float(process.create_time())
        actual_executable = str(Path(process.exe()).expanduser().resolve(strict=True))
        actual_cwd = str(Path(process.cwd()).expanduser().resolve(strict=True))
        actual_cmdline = list(process.cmdline())
        actual_boot_time = float(boot_time_reader())
        actual_environment = (
            dict(process.environ())
            if candidate.get("verify_loaded_configuration") is True
            else {}
        )
    except (psutil.Error, OSError, TypeError, ValueError, AttributeError) as exc:
        raise EvidenceError(f"{artifact}_process_unavailable") from exc
    if not math.isclose(
        actual_create_time,
        expected_create_time,
        rel_tol=0.0,
        abs_tol=0.05,
    ):
        raise EvidenceError(f"{artifact}_process_create_time_mismatch")
    if not math.isclose(
        actual_boot_time,
        expected_boot_time,
        rel_tol=0.0,
        abs_tol=1.0,
    ):
        raise EvidenceError(f"{artifact}_boot_time_mismatch")
    if actual_executable != identity.get("executable"):
        raise EvidenceError(f"{artifact}_process_executable_mismatch")
    if actual_cwd != identity.get("cwd"):
        raise EvidenceError(f"{artifact}_process_cwd_mismatch")
    expected_arguments = candidate.get("program_arguments")
    if (
        not isinstance(expected_arguments, list)
        or not all(isinstance(value, str) and value for value in expected_arguments)
        or len(actual_cmdline) != len(expected_arguments)
        or actual_cmdline[1:] != expected_arguments[1:]
    ):
        raise EvidenceError(f"{artifact}_process_cmdline_mismatch")
    allowed_argv0 = {
        expected_arguments[0],
        str(candidate.get("interpreter") or ""),
        str(candidate.get("runtime_executable") or ""),
    }
    if not actual_cmdline or actual_cmdline[0] not in allowed_argv0:
        raise EvidenceError(f"{artifact}_process_cmdline_mismatch")
    expected_environment = candidate.get("environment")
    if candidate.get("verify_loaded_configuration") is True:
        if (
            not isinstance(expected_environment, Mapping)
            or _unsafe_runtime_environment_keys(actual_environment)
            or any(
                actual_environment.get(str(key)) != str(value)
                for key, value in expected_environment.items()
            )
        ):
            raise EvidenceError(f"{artifact}_process_environment_mismatch")
    launchctl = _launchctl_process_evidence(
        service_label=str(identity.get("service_label") or ""),
        pid=pid,
        artifact=artifact,
        expected_loaded_config=(
            candidate if candidate.get("verify_loaded_configuration") is True else None
        ),
        runner=launchctl_runner,
    )
    return {
        "pid": pid,
        "process_create_time": actual_create_time,
        "boot_time": actual_boot_time,
        "executable": actual_executable,
        "cwd": actual_cwd,
        "cmdline_sha256": _sha256_json(actual_cmdline),
        "required_environment_sha256": (
            _sha256_json({
                str(key): actual_environment[str(key)]
                for key in sorted(expected_environment)
            })
            if isinstance(expected_environment, Mapping)
            and candidate.get("verify_loaded_configuration") is True
            else None
        ),
        "launchctl": launchctl,
        "installed_plist": installed_plist,
    }


def _normalize_auxiliary_runtime_identity(
    value: Any,
    *,
    expected_runtime: Mapping[str, Any],
    artifact: str,
) -> dict[str, str]:
    identity = _mapping(value, f"{artifact}.runtime_identity")
    fields = {
        "executable",
        "script",
        "cwd",
        "script_sha256",
        "interpreter_sha256",
        "plist_path",
        "plist_sha256",
        "program_arguments_sha256",
        "environment_sha256",
    }
    if set(identity) != fields:
        raise EvidenceError(f"{artifact}_runtime_identity_invalid")
    normalized: dict[str, str] = {}
    for field in sorted(fields):
        if field.endswith("_sha256"):
            normalized[field] = _sha256_digest(
                identity.get(field), f"{artifact}.{field}"
            )
        else:
            normalized[field] = _required_text(
                identity.get(field), f"{artifact}.{field}"
            )
        if normalized[field] != expected_runtime.get(field):
            raise EvidenceError(f"{artifact}_runtime_identity_mismatch")
    return normalized


def _verify_auxiliary_code_and_plist(
    expected_runtime: Mapping[str, Any],
    *,
    artifact: str,
) -> dict[str, Any]:
    for field, digest_field in (
        ("script", "script_sha256"),
        ("executable", "interpreter_sha256"),
    ):
        path = Path(_required_text(expected_runtime.get(field), f"{artifact}.{field}"))
        try:
            actual_sha256 = file_sha256(path)
        except (OSError, ValueError) as exc:
            raise EvidenceError(f"{artifact}_runtime_file_unavailable") from exc
        if actual_sha256 != expected_runtime.get(digest_field):
            raise EvidenceError(f"{artifact}_runtime_file_mismatch")
    candidate = {
        "service_label": expected_runtime.get("service_label"),
        "plist_path": expected_runtime.get("plist_path"),
        "plist_sha256": expected_runtime.get("plist_sha256"),
        "program_arguments": expected_runtime.get("program_arguments"),
        "working_directory": expected_runtime.get("cwd"),
        "environment": expected_runtime.get("environment"),
    }
    installed = _verify_installed_launchd_plist(candidate, artifact=artifact)
    return {
        "script_sha256": expected_runtime["script_sha256"],
        "interpreter_sha256": expected_runtime["interpreter_sha256"],
        "installed_plist": installed,
    }


def _verify_completion_relay_process(
    *,
    pid: int,
    process_create_time: float,
    expected_runtime: Mapping[str, Any],
    process_factory: Any = psutil.Process,
    launchctl_runner: Any = subprocess.run,
) -> dict[str, Any]:
    artifact = "completion_relay_health"
    code = _verify_auxiliary_code_and_plist(expected_runtime, artifact=artifact)
    try:
        process = process_factory(pid)
        observed_create_time = float(process.create_time())
        executable = str(Path(process.exe()).resolve(strict=True))
        cwd = str(Path(process.cwd()).resolve(strict=True))
        cmdline = list(process.cmdline())
        environment = dict(process.environ())
    except (psutil.Error, OSError, TypeError, ValueError, AttributeError) as exc:
        raise EvidenceError("completion_relay_health_process_unavailable") from exc
    if (
        not math.isclose(
            observed_create_time, process_create_time, rel_tol=0.0, abs_tol=0.05
        )
        or executable != expected_runtime.get("executable")
        or cwd != expected_runtime.get("cwd")
        or cmdline != expected_runtime.get("program_arguments")
        or _unsafe_runtime_environment_keys(environment)
        or any(
            environment.get(str(key)) != str(value)
            for key, value in _mapping(
                expected_runtime.get("environment"),
                "completion_relay_health.environment",
            ).items()
        )
    ):
        raise EvidenceError("completion_relay_health_process_identity_mismatch")
    launchctl = _launchctl_process_evidence(
        service_label=str(expected_runtime.get("service_label")),
        pid=pid,
        artifact=artifact,
        expected_loaded_config={
            "plist_path": expected_runtime.get("plist_path"),
            "program_arguments": expected_runtime.get("program_arguments"),
            "working_directory": expected_runtime.get("cwd"),
            "environment": expected_runtime.get("environment"),
        },
        runner=launchctl_runner,
    )
    return {
        **code,
        "pid": pid,
        "process_create_time": observed_create_time,
        "cmdline_sha256": _sha256_json(cmdline),
        "launchctl": launchctl,
    }


def _launchctl_loaded_config_evidence(
    expected_runtime: Mapping[str, Any],
    *,
    runner: Any = subprocess.run,
) -> dict[str, Any]:
    artifact = "vm_task_sync_completion"
    code = _verify_auxiliary_code_and_plist(expected_runtime, artifact=artifact)
    service_label = str(expected_runtime.get("service_label"))
    command = [
        "/bin/launchctl",
        "print",
        f"gui/{os.getuid()}/{service_label}",
    ]
    try:
        completed = runner(
            command,
            text=True,
            capture_output=True,
            timeout=10,
            check=False,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise EvidenceError("vm_task_sync_completion_launchctl_unavailable") from exc
    stdout = str(completed.stdout or "")
    if completed.returncode != 0 or len(stdout.encode("utf-8")) > 65_536:
        raise EvidenceError("vm_task_sync_completion_launchctl_unavailable")

    def scalar(name: str) -> str:
        matches = re.findall(
            rf"(?m)^\s*{re.escape(name)}\s*=\s*(.*?)\s*$",
            stdout,
        )
        if len(matches) != 1 or not matches[0]:
            raise EvidenceError("vm_task_sync_completion_launchctl_config_unavailable")
        return matches[0]

    def block(name: str) -> list[str]:
        match = re.search(
            rf"(?ms)^\s*{re.escape(name)}\s*=\s*\{{\s*\n(.*?)^\s*\}}\s*$",
            stdout,
        )
        if match is None:
            raise EvidenceError("vm_task_sync_completion_launchctl_config_unavailable")
        return [line.strip() for line in match.group(1).splitlines() if line.strip()]

    loaded_environment: dict[str, str] = {}
    for line in block("environment"):
        key, separator, value = line.partition(" => ")
        if not separator or not key or key in loaded_environment:
            raise EvidenceError("vm_task_sync_completion_launchctl_config_unavailable")
        loaded_environment[key] = value
    expected_environment = _mapping(
        expected_runtime.get("environment"), "vm_task_sync_completion.environment"
    )
    extra_keys = set(loaded_environment) - {str(key) for key in expected_environment}
    if (
        scalar("path") != expected_runtime.get("plist_path")
        or scalar("program") != expected_runtime.get("executable")
        or block("arguments") != expected_runtime.get("program_arguments")
        or scalar("working directory") != expected_runtime.get("cwd")
        or any(
            loaded_environment.get(str(key)) != str(value)
            for key, value in expected_environment.items()
        )
        or not extra_keys.issubset({"OSLogRateLimit", "XPC_SERVICE_NAME"})
        or _unsafe_runtime_environment_keys(loaded_environment)
    ):
        raise EvidenceError("vm_task_sync_completion_launchctl_config_mismatch")
    return {
        **code,
        "loaded": True,
        "current_pid_required": False,
        "program_arguments_sha256": _sha256_json(block("arguments")),
        "environment_sha256": _sha256_json(dict(sorted(loaded_environment.items()))),
    }


def validate_completion_relay_runtime_health(
    body: Mapping[str, Any],
    *,
    now: datetime,
    expected_runtime: Mapping[str, Any],
    process_verifier: Callable[..., Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    artifact = "completion_relay_health"
    health = _mapping(body, artifact)
    if set(health) != {
        "schema_version",
        "service_label",
        "observed_at",
        "started_at",
        "pid",
        "process_create_time",
        "loop_count",
        "startup_canary_loops_required",
        "startup_canary_loops_completed",
        "startup_canary_completed_at",
        "configured_max_card_fallbacks_per_loop",
        "effective_max_card_fallbacks_per_loop",
        "card_fallback_attempted_count",
        "card_fallback_sent_count",
        "healthy",
        "errors",
        "runtime_identity",
    } or health.get("schema_version") != COMPLETION_RELAY_HEALTH_SCHEMA_VERSION:
        raise EvidenceError("completion_relay_health_shape_invalid")
    observed_at = _timestamp(health.get("observed_at"), f"{artifact}.observed_at")
    started_at = _timestamp(health.get("started_at"), f"{artifact}.started_at")
    completed_at = _timestamp(
        health.get("startup_canary_completed_at"),
        f"{artifact}.startup_canary_completed_at",
    )
    age = (now.astimezone(timezone.utc) - observed_at).total_seconds()
    loop_count = _exact_int(health.get("loop_count"), f"{artifact}.loop_count", minimum=3)
    required = _exact_int(
        health.get("startup_canary_loops_required"),
        f"{artifact}.startup_canary_loops_required",
        minimum=3,
    )
    completed = _exact_int(
        health.get("startup_canary_loops_completed"),
        f"{artifact}.startup_canary_loops_completed",
        minimum=3,
    )
    errors = health.get("errors")
    if (
        health.get("service_label") != expected_runtime.get("service_label")
        or age < -MAX_HEALTH_FUTURE_SKEW_SECONDS
        or age > DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS
        or not started_at <= completed_at <= observed_at
        or required != 3
        or completed < required
        or completed > loop_count
        or health.get("configured_max_card_fallbacks_per_loop") != 0
        or health.get("effective_max_card_fallbacks_per_loop") != 0
        or health.get("card_fallback_attempted_count") != 0
        or health.get("card_fallback_sent_count") != 0
        or health.get("healthy") is not True
        or errors != []
    ):
        raise EvidenceError("completion_relay_health_not_ready")
    identity = _normalize_auxiliary_runtime_identity(
        health.get("runtime_identity"),
        expected_runtime=expected_runtime,
        artifact=artifact,
    )
    pid = _exact_int(health.get("pid"), f"{artifact}.pid", minimum=1)
    create_time = _number(
        health.get("process_create_time"), f"{artifact}.process_create_time", minimum=1
    )
    verifier = process_verifier or _verify_completion_relay_process
    process = dict(
        verifier(
            pid=pid,
            process_create_time=create_time,
            expected_runtime=expected_runtime,
        )
    )
    return {
        "observed_at": observed_at.isoformat(),
        "startup_canary_completed_at": completed_at.isoformat(),
        "loop_count": loop_count,
        "runtime_identity_sha256": _sha256_json(identity),
        "process": process,
    }


def validate_vm_task_sync_completion_receipt(
    body: Mapping[str, Any],
    *,
    now: datetime,
    not_before: datetime,
    expected_runtime: Mapping[str, Any],
    launchd_verifier: Callable[[Mapping[str, Any]], Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    artifact = "vm_task_sync_completion"
    receipt = _mapping(body, artifact)
    if set(receipt) != {
        "schema_version",
        "service_label",
        "run_id",
        "started_at",
        "completed_at",
        "pid",
        "exit_code",
        "ok",
        "skipped",
        "candidate_count",
        "synced_count",
        "error_count",
        "errors",
        "result_sha256",
        "runtime_identity",
    } or receipt.get("schema_version") != VM_TASK_SYNC_COMPLETION_SCHEMA_VERSION:
        raise EvidenceError("vm_task_sync_completion_shape_invalid")
    run_id = _required_text(receipt.get("run_id"), f"{artifact}.run_id")
    started_at = _timestamp(receipt.get("started_at"), f"{artifact}.started_at")
    completed_at = _timestamp(receipt.get("completed_at"), f"{artifact}.completed_at")
    age = (now.astimezone(timezone.utc) - completed_at).total_seconds()
    candidate_count = _exact_int(
        receipt.get("candidate_count"), f"{artifact}.candidate_count", minimum=0
    )
    synced_count = _exact_int(
        receipt.get("synced_count"), f"{artifact}.synced_count", minimum=0
    )
    error_count = _exact_int(
        receipt.get("error_count"), f"{artifact}.error_count", minimum=0
    )
    errors = receipt.get("errors")
    result = {
        "candidate_count": candidate_count,
        "synced_count": synced_count,
        "error_count": error_count,
        "errors": errors,
    }
    if (
        re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{7,127}", run_id) is None
        or receipt.get("service_label") != expected_runtime.get("service_label")
        or not not_before.astimezone(timezone.utc) <= started_at <= completed_at
        or age < -MAX_HEALTH_FUTURE_SKEW_SECONDS
        or age > 180
        or receipt.get("exit_code") != 0
        or receipt.get("ok") is not True
        or receipt.get("skipped") is not False
        or synced_count > candidate_count
        or error_count != 0
        or errors != []
        or receipt.get("result_sha256") != _sha256_json(result)
    ):
        raise EvidenceError("vm_task_sync_completion_not_ready")
    _exact_int(receipt.get("pid"), f"{artifact}.pid", minimum=1)
    identity = _normalize_auxiliary_runtime_identity(
        receipt.get("runtime_identity"),
        expected_runtime=expected_runtime,
        artifact=artifact,
    )
    verifier = launchd_verifier or _launchctl_loaded_config_evidence
    launchd = dict(verifier(expected_runtime))
    return {
        "run_id": run_id,
        "started_at": started_at.isoformat(),
        "completed_at": completed_at.isoformat(),
        "result_sha256": receipt["result_sha256"],
        "runtime_identity_sha256": _sha256_json(identity),
        "launchd": launchd,
    }


def _load_owner_runtime_receipt(path: Path, *, artifact: str) -> dict[str, Any]:
    try:
        raw, _info = _stable_regular_file_observation(
            path,
            artifact=artifact,
            expected_mode=0o600,
            require_owner=True,
        )
    except (OSError, ValueError) as exc:
        raise EvidenceError(f"{artifact}_missing") from exc
    if not raw or len(raw) > MAX_EVIDENCE_BYTES:
        raise EvidenceError(f"{artifact}_size_invalid")
    return dict(
        _mapping(_strict_json_loads(raw, artifact=artifact), artifact)
    )


def _check_auxiliary_runtime_health(
    *,
    build_detail: Mapping[str, Any],
    activation: Mapping[str, Any],
    now: datetime,
    relay_process_verifier: Callable[..., Mapping[str, Any]] | None = None,
    vm_launchd_verifier: Callable[[Mapping[str, Any]], Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    expected = _mapping(
        build_detail.get("auxiliary_runtime"), "auxiliary_runtime.expected"
    )
    if set(expected) != {"completion_relay", "vm_task_sync"}:
        raise EvidenceError("auxiliary_runtime_build_binding_missing")
    relay_expected = _mapping(
        expected.get("completion_relay"), "auxiliary_runtime.completion_relay"
    )
    sync_expected = _mapping(
        expected.get("vm_task_sync"), "auxiliary_runtime.vm_task_sync"
    )
    if (
        relay_expected.get("health_path") != str(COMPLETION_RELAY_HEALTH_PATH)
        or sync_expected.get("completion_path") != str(VM_TASK_SYNC_COMPLETION_PATH)
    ):
        raise EvidenceError("auxiliary_runtime_path_binding_invalid")
    not_before_value = (
        activation.get("bounded_activated_at") or activation.get("created_at")
    )
    not_before = _timestamp(not_before_value, "auxiliary_runtime.not_before")
    relay = validate_completion_relay_runtime_health(
        _load_owner_runtime_receipt(
            COMPLETION_RELAY_HEALTH_PATH,
            artifact="completion_relay_health",
        ),
        now=now,
        expected_runtime=relay_expected,
        process_verifier=relay_process_verifier,
    )
    sync = validate_vm_task_sync_completion_receipt(
        _load_owner_runtime_receipt(
            VM_TASK_SYNC_COMPLETION_PATH,
            artifact="vm_task_sync_completion",
        ),
        now=now,
        not_before=not_before,
        expected_runtime=sync_expected,
        launchd_verifier=vm_launchd_verifier,
    )
    return {
        "not_before": not_before.isoformat(),
        "completion_relay": relay,
        "vm_task_sync": sync,
        "runtime_binding_sha256": _sha256_json(expected),
    }


def _gateway_manual_runtime_public_config(
    cutover: CutoverConfig,
    consumer: ConsumerConfig,
) -> dict[str, Any]:
    chat_ids = _normalized_manual_chat_ids(cutover.manual_chat_ids)
    operator_user_ids = _normalized_manual_operator_user_ids(
        cutover.manual_operator_user_ids
    )
    return {
        "schema_version": "pnc_rca_gateway_manual_runtime_config_v3",
        "activation_required": cutover.activation_required is True,
        "manual_intake_enabled": cutover.manual_intake_enabled is True,
        "manual_chat_ids": list(chat_ids),
        "manual_chat_allowlist_valid": bool(chat_ids),
        "manual_chat_allowlist_sha256": _sha256_json(list(chat_ids)),
        "manual_operator_enabled": cutover.manual_operator_enabled is True,
        "manual_operator_user_count": len(operator_user_ids),
        "manual_operator_user_ids_sha256": _sha256_json(list(operator_user_ids)),
        "manual_operator_rate_limit": cutover.manual_operator_rate_limit or 3,
        "manual_operator_rate_window_seconds": (
            cutover.manual_operator_rate_window_seconds or 600
        ),
        "workflow_event_policy": consumer.policy.to_dict(),
        "workflow_event_policy_sha256": _sha256_json(consumer.policy.to_dict()),
        "creation_rule_version": consumer.policy.policy_version,
        "kafka_outbox_high_watermark": consumer.outbox_high_watermark,
    }


def _gateway_interpreter_runtime_probe(
    interpreter: Path,
    *,
    repo_root: Path,
    virtual_env: Path,
    runner: Any = subprocess.run,
) -> dict[str, Any]:
    script = r'''import importlib.util
from importlib import metadata
import json
from pathlib import Path
import psutil
import sys

root = Path(sys.argv[1]).resolve(strict=True)
sys.path.insert(0, str(root))
modules = {}
for name in (
    "hermes_cli.main",
    "gateway.run",
    "gateway.pnc_rca_policy_config",
    "gateway.pnc_rca_runtime_identity",
    "psutil",
    "dotenv",
):
    spec = importlib.util.find_spec(name)
    origin = getattr(spec, "origin", None) if spec is not None else None
    if not origin:
        raise RuntimeError("module_origin_missing:" + name)
    modules[name] = str(Path(origin).resolve(strict=True))
print(json.dumps({
    "sys_executable": str(Path(sys.executable).resolve(strict=True)),
    "process_executable": str(Path(psutil.Process().exe()).resolve(strict=True)),
    "module_origins": modules,
    "dependency_versions": {
        "psutil": metadata.version("psutil"),
        "python-dotenv": metadata.version("python-dotenv"),
    },
}, sort_keys=True, separators=(",", ":")))
'''
    environment = {
        "PATH": f"{virtual_env / 'bin'}:/usr/bin:/bin:/usr/sbin:/sbin",
        "VIRTUAL_ENV": str(virtual_env),
        "PYTHONDONTWRITEBYTECODE": "1",
        "PYTHONNOUSERSITE": "1",
        "HOME": str(Path.home()),
    }
    try:
        completed = runner(
            [str(interpreter), "-c", script, str(repo_root)],
            cwd=str(repo_root),
            env=environment,
            text=True,
            capture_output=True,
            timeout=15,
            check=False,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise EvidenceError("manual_gateway_runtime_interpreter_probe_unavailable") from exc
    stdout = str(completed.stdout or "")
    if completed.returncode != 0 or len(stdout.encode("utf-8")) > 16_384:
        raise EvidenceError("manual_gateway_runtime_interpreter_probe_unavailable")
    body = _mapping(
        _strict_json_loads(stdout, artifact="manual_gateway_runtime_interpreter_probe"),
        "manual_gateway_runtime_interpreter_probe",
    )
    if set(body) != {
        "sys_executable",
        "process_executable",
        "module_origins",
        "dependency_versions",
    }:
        raise EvidenceError("manual_gateway_runtime_interpreter_probe_invalid")
    origins = _mapping(body.get("module_origins"), "gateway_interpreter.module_origins")
    versions = _mapping(
        body.get("dependency_versions"),
        "gateway_interpreter.dependency_versions",
    )
    if versions != EXPECTED_GATEWAY_RUNTIME_DEPENDENCY_VERSIONS:
        raise EvidenceError("manual_gateway_runtime_dependency_version_mismatch")
    expected_repo_origins = {
        "hermes_cli.main": repo_root / "hermes_cli" / "main.py",
        "gateway.run": repo_root / "gateway" / "run.py",
        "gateway.pnc_rca_policy_config": (
            repo_root / "gateway" / "pnc_rca_policy_config.py"
        ),
        "gateway.pnc_rca_runtime_identity": (
            repo_root / "gateway" / "pnc_rca_runtime_identity.py"
        ),
    }
    if set(origins) != set(expected_repo_origins) | {"psutil", "dotenv"}:
        raise EvidenceError("manual_gateway_runtime_module_origin_invalid")
    for module_name, expected_path in expected_repo_origins.items():
        if origins.get(module_name) != str(expected_path.resolve(strict=True)):
            raise EvidenceError("manual_gateway_runtime_module_origin_mismatch")
    for module_name in ("psutil", "dotenv"):
        try:
            origin = Path(str(origins[module_name])).resolve(strict=True)
            origin.relative_to(virtual_env)
        except (OSError, ValueError) as exc:
            raise EvidenceError("manual_gateway_runtime_dependency_origin_mismatch") from exc
    return {
        "sys_executable": _required_text(
            body.get("sys_executable"), "gateway_interpreter.sys_executable"
        ),
        "process_executable": _required_text(
            body.get("process_executable"), "gateway_interpreter.process_executable"
        ),
        "module_origins_sha256": _sha256_json(origins),
        "module_origins": dict(origins),
        "dependency_versions": dict(versions),
        "repo_module_count": len(expected_repo_origins),
        "venv_dependency_count": 2,
    }


def _gateway_virtual_env(
    *,
    raw_interpreter: Path,
    environment: Mapping[str, Any],
    repo_root: Path,
    approved_shared_root: Path | None = None,
) -> Path:
    virtual_env = Path(
        _required_text(environment.get("VIRTUAL_ENV"), "gateway_plist.VIRTUAL_ENV")
    ).expanduser().absolute()
    approved_shared_root = (
        approved_shared_root
        or Path.home() / ".hermes" / "runtime" / "venvs"
    ).expanduser().absolute()
    approved_repo_venv = (repo_root / ".venv").absolute()
    try:
        info = os.lstat(virtual_env)
        bin_info = os.lstat(virtual_env / "bin")
        interpreter_info = os.lstat(raw_interpreter)
        resolved = virtual_env.resolve(strict=True)
        is_approved = False
        if approved_repo_venv.is_dir() and not approved_repo_venv.is_symlink():
            is_approved = resolved == approved_repo_venv.resolve(strict=True)
        if not is_approved:
            shared_root = approved_shared_root.resolve(strict=True)
            resolved.relative_to(shared_root)
            is_approved = resolved.parent == shared_root
    except (OSError, ValueError) as exc:
        raise EvidenceError("manual_gateway_runtime_virtualenv_invalid") from exc
    if (
        not is_approved
        or stat.S_ISLNK(info.st_mode)
        or not stat.S_ISDIR(info.st_mode)
        or info.st_uid != os.getuid()
        or stat.S_IMODE(info.st_mode) & 0o022
        or stat.S_ISLNK(bin_info.st_mode)
        or not stat.S_ISDIR(bin_info.st_mode)
        or bin_info.st_uid != os.getuid()
        or stat.S_IMODE(bin_info.st_mode) & 0o022
        or not (
            stat.S_ISREG(interpreter_info.st_mode)
            or stat.S_ISLNK(interpreter_info.st_mode)
        )
        or interpreter_info.st_uid != os.getuid()
        or interpreter_info.st_nlink != 1
        or raw_interpreter.absolute() != virtual_env / "bin" / "python"
        or str(environment.get("PATH") or "").split(":", 1)[0]
        != str(virtual_env / "bin")
    ):
        raise EvidenceError("manual_gateway_runtime_virtualenv_invalid")
    return resolved


def _approved_gateway_launchd_candidate(
    repo_root: Path,
) -> dict[str, Any]:
    path = repo_root / GATEWAY_CANDIDATE_PLIST_RELATIVE_PATH
    try:
        info = os.lstat(path)
        if (
            stat.S_ISLNK(info.st_mode)
            or not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.getuid()
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) & 0o022
            or info.st_size <= 0
            or info.st_size > MAX_EVIDENCE_BYTES
        ):
            raise EvidenceError("manual_gateway_runtime_candidate_plist_invalid")
        before, _before_aggregate = runtime_file_snapshot(
            repo_root,
            (GATEWAY_CANDIDATE_PLIST_RELATIVE_PATH,),
        )
        raw = path.read_bytes()
        after, _after_aggregate = runtime_file_snapshot(
            repo_root,
            (GATEWAY_CANDIDATE_PLIST_RELATIVE_PATH,),
        )
    except EvidenceError:
        raise
    except (OSError, ValueError) as exc:
        raise EvidenceError(
            "manual_gateway_runtime_candidate_plist_invalid"
        ) from exc
    digest = hashlib.sha256(raw).hexdigest()
    if before != after or before.get(GATEWAY_CANDIDATE_PLIST_RELATIVE_PATH) != digest:
        raise EvidenceError("manual_gateway_runtime_candidate_plist_changed")
    try:
        body = plistlib.loads(raw)
    except plistlib.InvalidFileException as exc:
        raise EvidenceError("manual_gateway_runtime_candidate_plist_invalid") from exc
    if not isinstance(body, dict):
        raise EvidenceError("manual_gateway_runtime_candidate_plist_invalid")
    return {
        "path": path,
        "raw": raw,
        "sha256": digest,
        "body": body,
    }


def _verify_gateway_runtime_identity(
    identity_value: Mapping[str, Any],
    *,
    repo_root: Path,
    cutover: CutoverConfig,
    consumer: ConsumerConfig,
    plist_path: Path | None = None,
    candidate_plist_path: Path | None = None,
    process_verifier: Any = None,
    interpreter_probe: Any = None,
) -> dict[str, Any]:
    identity = _check_gateway_runtime_identity(
        identity_value,
        field="manual_gateway_runtime.runtime_identity",
    )
    try:
        root = repo_root.expanduser().resolve(strict=True)
        expected_script = (root / "gateway" / "run.py").resolve(strict=True)
        runtime_file_hashes, runtime_files_sha256 = runtime_file_snapshot(
            root,
            GATEWAY_RCA_RUNTIME_RELATIVE_FILES,
        )
    except (OSError, ValueError) as exc:
        raise EvidenceError("manual_gateway_runtime_candidate_unavailable") from exc
    public_config = _gateway_manual_runtime_public_config(cutover, consumer)
    if (
        identity.get("script") != str(expected_script)
        or identity.get("cwd") != str(root)
        or identity.get("script_sha256")
        != hashlib.sha256(expected_script.read_bytes()).hexdigest()
        or identity.get("runtime_files_sha256") != runtime_files_sha256
        or identity.get("public_config_sha256") != _sha256_json(public_config)
    ):
        raise EvidenceError("manual_gateway_runtime_candidate_mismatch")

    approved = _approved_gateway_launchd_candidate(root)
    approved_path = Path(approved["path"])
    if candidate_plist_path is not None:
        try:
            requested_candidate = candidate_plist_path.expanduser().resolve(strict=True)
        except OSError as exc:
            raise EvidenceError("manual_gateway_runtime_candidate_plist_invalid") from exc
        if requested_candidate != approved_path:
            raise EvidenceError("manual_gateway_runtime_candidate_plist_mismatch")
    plist = _mapping(approved.get("body"), "manual_gateway_runtime.candidate_plist")
    arguments = plist.get("ProgramArguments")
    working_directory = str(plist.get("WorkingDirectory") or "")
    environment = plist.get("EnvironmentVariables")
    expected_log_root = Path.home() / ".hermes" / "logs"
    if (
        set(plist)
        != {
            "EnvironmentVariables",
            "ExitTimeOut",
            "KeepAlive",
            "Label",
            "ProcessType",
            "ProgramArguments",
            "RunAtLoad",
            "StandardErrorPath",
            "StandardOutPath",
            "ThrottleInterval",
            "Umask",
            "WorkingDirectory",
        }
        or plist.get("KeepAlive") != {"SuccessfulExit": False}
        or plist.get("RunAtLoad") is not True
        or plist.get("ExitTimeOut") != 30
        or plist.get("ProcessType") != "Background"
        or plist.get("ThrottleInterval") != 10
        or plist.get("Umask") != 0o077
        or plist.get("StandardErrorPath")
        != str(expected_log_root / "gateway.error.log")
        or plist.get("StandardOutPath") != str(expected_log_root / "gateway.log")
    ):
        raise EvidenceError("manual_gateway_runtime_candidate_plist_invalid")

    installed_plist = (
        plist_path
        or Path.home() / "Library" / "LaunchAgents" / "ai.hermes.gateway.plist"
    ).expanduser().absolute()
    installed_candidate = {
        "service_label": "ai.hermes.gateway",
        "program_arguments": list(arguments) if isinstance(arguments, list) else None,
        "working_directory": working_directory,
        "environment": dict(environment) if isinstance(environment, dict) else None,
        "plist_path": str(installed_plist),
        "plist_sha256": approved["sha256"],
    }
    installed_plist_detail = _verify_installed_launchd_plist(
        installed_candidate,
        artifact="manual_gateway_runtime",
    )
    if (
        not isinstance(plist, dict)
        or plist.get("Label") != "ai.hermes.gateway"
        or not isinstance(arguments, list)
        or len(arguments) != 6
        or not all(isinstance(item, str) and item for item in arguments)
        or arguments[1:] != [
            "-m",
            "hermes_cli.main",
            "gateway",
            "run",
            "--replace",
        ]
        or not isinstance(environment, dict)
        or _unsafe_runtime_environment_keys(environment)
    ):
        raise EvidenceError("manual_gateway_runtime_plist_invalid")
    try:
        raw_interpreter = Path(arguments[0]).expanduser().absolute()
        interpreter = raw_interpreter.resolve(strict=True)
        plist_root = Path(working_directory).expanduser().resolve(strict=True)
    except OSError as exc:
        raise EvidenceError("manual_gateway_runtime_plist_invalid") from exc
    if (
        not interpreter.is_file()
        or not os.access(raw_interpreter, os.X_OK)
        or plist_root != root
    ):
        raise EvidenceError("manual_gateway_runtime_plist_candidate_mismatch")
    virtual_env = _gateway_virtual_env(
        raw_interpreter=raw_interpreter,
        environment=environment,
        repo_root=root,
    )
    probe = (interpreter_probe or _gateway_interpreter_runtime_probe)(
        raw_interpreter,
        repo_root=root,
        virtual_env=virtual_env,
    )
    if probe.get("sys_executable") != str(interpreter):
        raise EvidenceError("manual_gateway_runtime_interpreter_mismatch")
    process_executable = Path(
        _required_text(
            probe.get("process_executable"),
            "manual_gateway_runtime.process_executable",
        )
    ).resolve(strict=True)
    if identity.get("executable") != str(process_executable):
        raise EvidenceError("manual_gateway_runtime_executable_mismatch")
    module_origins = _mapping(
        probe.get("module_origins"),
        "manual_gateway_runtime.module_origins",
    )
    dependency_versions = _mapping(
        probe.get("dependency_versions"),
        "manual_gateway_runtime.dependency_versions",
    )
    dependency_runtime: dict[str, dict[str, str]] = {}
    for distribution, module_name in GATEWAY_LOADED_DEPENDENCIES.items():
        if dependency_versions.get(distribution) != (
            EXPECTED_GATEWAY_RUNTIME_DEPENDENCY_VERSIONS[distribution]
        ):
            raise EvidenceError("manual_gateway_runtime_dependency_version_mismatch")
        try:
            origin = Path(
                _required_text(
                    module_origins.get(module_name),
                    f"manual_gateway_runtime.module_origins.{module_name}",
                )
            ).resolve(strict=True)
            origin.relative_to(virtual_env)
        except (OSError, ValueError) as exc:
            raise EvidenceError(
                "manual_gateway_runtime_dependency_origin_mismatch"
            ) from exc
        dependency_runtime[distribution] = {
            "module": module_name,
            "origin": str(origin),
            "sha256": file_sha256(origin),
            "version": str(dependency_versions[distribution]),
        }
    loaded_runtime_sha256 = _sha256_json({
        "sys_executable": str(interpreter),
        "sys_executable_sha256": file_sha256(interpreter),
        "process_executable": str(process_executable),
        "process_executable_sha256": file_sha256(process_executable),
        "dependencies": dependency_runtime,
    })
    if identity.get("loaded_runtime_sha256") != loaded_runtime_sha256:
        raise EvidenceError("manual_gateway_runtime_loaded_code_mismatch")

    candidate = {
        **installed_candidate,
        "service_label": "ai.hermes.gateway",
        "interpreter": str(raw_interpreter),
        "runtime_executable": str(process_executable),
        "script": str(expected_script),
        "working_directory": str(root),
        "script_sha256": hashlib.sha256(expected_script.read_bytes()).hexdigest(),
        "runtime_file_sha256": runtime_file_hashes,
        "runtime_files_sha256": runtime_files_sha256,
        "program_arguments": list(arguments),
        "environment": dict(environment),
        "verify_loaded_configuration": True,
    }
    verifier = process_verifier or _verify_delivery_service_process
    process = verifier(identity, candidate, artifact="manual_gateway_runtime")
    return {
        "service_label": "ai.hermes.gateway",
        "runtime_identity_sha256": _sha256_json(identity),
        "runtime_files_sha256": runtime_files_sha256,
        "runtime_file_sha256": runtime_file_hashes,
        "public_config_sha256": _sha256_json(public_config),
        "plist_path": str(installed_plist),
        "plist_sha256": candidate["plist_sha256"],
        "candidate_plist_path": str(approved_path),
        "candidate_plist_sha256": approved["sha256"],
        "interpreter_path": str(raw_interpreter),
        "interpreter_sha256": file_sha256(interpreter),
        "process_executable_sha256": file_sha256(process_executable),
        "virtual_env_sha256": hashlib.sha256(
            str(virtual_env).encode("utf-8")
        ).hexdigest(),
        "module_origins_sha256": probe["module_origins_sha256"],
        "loaded_runtime_sha256": loaded_runtime_sha256,
        "dependency_files_sha256": _sha256_json(dependency_runtime),
        "process": process,
        "installed_plist": installed_plist_detail,
    }


RCA_RESIDENT_LABELS = frozenset(
    label for label, _script in CANDIDATE_SERVICES.values()
)


def _matching_process_ids(markers: Sequence[str]) -> list[int]:
    matches: set[int] = set()
    try:
        processes = psutil.process_iter(("pid", "cmdline"))
        for process in processes:
            try:
                cmdline = process.info.get("cmdline") or []
                rendered = "\x00".join(str(item) for item in cmdline)
                if all(marker in rendered for marker in markers):
                    matches.add(int(process.info["pid"]))
            except (KeyError, TypeError, ValueError, psutil.Error):
                continue
    except psutil.Error as exc:
        raise EvidenceError("activation_bootstrap_process_probe_unavailable") from exc
    return sorted(matches)


def _live_launchd_pid(
    label: str,
    *,
    runner: Any = subprocess.run,
) -> int | None:
    try:
        completed = runner(
            ["/bin/launchctl", "print", f"gui/{os.getuid()}/{label}"],
            text=True,
            capture_output=True,
            timeout=10,
            check=False,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise EvidenceError("activation_bootstrap_launchctl_unavailable") from exc
    stdout = str(completed.stdout or "")
    if len(stdout.encode("utf-8")) > 65_536:
        raise EvidenceError("activation_bootstrap_launchctl_invalid")
    if completed.returncode != 0:
        return None
    if re.search(r"(?m)^\s*state\s*=\s*running\s*$", stdout) is None:
        raise EvidenceError("activation_bootstrap_launchctl_not_running")
    pids = {
        int(match)
        for match in re.findall(r"(?m)^\s*pid\s*=\s*([0-9]+)\s*$", stdout)
    }
    if len(pids) != 1:
        raise EvidenceError("activation_bootstrap_launchctl_pid_invalid")
    return next(iter(pids))


def _collect_gateway_candidate_runtime(
    *,
    repo_root: Path,
    cutover: CutoverConfig,
    consumer: ConsumerConfig,
) -> dict[str, Any]:
    pid = _live_launchd_pid("ai.hermes.gateway")
    rogue_pids = _matching_process_ids(("hermes_cli.main", "gateway", "run"))
    if pid is None:
        if rogue_pids:
            raise EvidenceError("activation_bootstrap_gateway_unmanaged")
        return {"state": "stopped", "runtime_identity": None, "verified": None}
    if rogue_pids != [pid]:
        raise EvidenceError("activation_bootstrap_gateway_process_ambiguous")
    approved = _approved_gateway_launchd_candidate(repo_root)
    plist = _mapping(approved.get("body"), "activation_bootstrap.gateway_plist")
    arguments = plist.get("ProgramArguments")
    environment = plist.get("EnvironmentVariables")
    if (
        not isinstance(arguments, list)
        or not arguments
        or not isinstance(environment, Mapping)
    ):
        raise EvidenceError("activation_bootstrap_gateway_candidate_invalid")
    raw_interpreter = Path(str(arguments[0])).expanduser().absolute()
    virtual_env = _gateway_virtual_env(
        raw_interpreter=raw_interpreter,
        environment=environment,
        repo_root=repo_root,
    )
    probe = _gateway_interpreter_runtime_probe(
        raw_interpreter,
        repo_root=repo_root,
        virtual_env=virtual_env,
    )
    process = psutil.Process(pid)
    dependency_runtime: dict[str, dict[str, str]] = {}
    origins = _mapping(probe.get("module_origins"), "activation_bootstrap.origins")
    versions = _mapping(
        probe.get("dependency_versions"), "activation_bootstrap.versions"
    )
    for distribution, module_name in GATEWAY_LOADED_DEPENDENCIES.items():
        origin = Path(
            _required_text(
                origins.get(module_name),
                f"activation_bootstrap.origins.{module_name}",
            )
        ).resolve(strict=True)
        dependency_runtime[distribution] = {
            "module": module_name,
            "origin": str(origin),
            "sha256": file_sha256(origin),
            "version": _required_text(
                versions.get(distribution),
                f"activation_bootstrap.versions.{distribution}",
            ),
        }
    sys_executable = Path(
        _required_text(probe.get("sys_executable"), "activation_bootstrap.sys_executable")
    ).resolve(strict=True)
    process_executable = Path(
        _required_text(
            probe.get("process_executable"),
            "activation_bootstrap.process_executable",
        )
    ).resolve(strict=True)
    loaded_runtime = {
        "sys_executable": str(sys_executable),
        "sys_executable_sha256": file_sha256(sys_executable),
        "process_executable": str(process_executable),
        "process_executable_sha256": file_sha256(process_executable),
        "dependencies": dependency_runtime,
    }
    _runtime_map, runtime_files_sha256 = runtime_file_snapshot(
        repo_root,
        GATEWAY_RCA_RUNTIME_RELATIVE_FILES,
    )
    script = (repo_root / "gateway" / "run.py").resolve(strict=True)
    identity = {
        "service_label": "ai.hermes.gateway",
        "pid": pid,
        "process_create_time": float(process.create_time()),
        "boot_time": float(psutil.boot_time()),
        "executable": str(Path(process.exe()).resolve(strict=True)),
        "script": str(script),
        "cwd": str(Path(process.cwd()).resolve(strict=True)),
        "script_sha256": file_sha256(script),
        "runtime_files_sha256": runtime_files_sha256,
        "public_config_sha256": _sha256_json(
            _gateway_manual_runtime_public_config(cutover, consumer)
        ),
        "loaded_runtime_sha256": _sha256_json(loaded_runtime),
    }
    verified = _verify_gateway_runtime_identity(
        identity,
        repo_root=repo_root,
        cutover=cutover,
        consumer=consumer,
    )
    return {
        "state": "running_safe",
        "runtime_identity": identity,
        "verified": verified,
    }


def _collect_activation_bootstrap_runtime(
    *,
    repo_root: Path,
    cutover: CutoverConfig,
    consumer: ConsumerConfig,
    require_rca_residents_stopped: bool,
) -> dict[str, Any]:
    residents: dict[str, Any] = {}
    if require_rca_residents_stopped:
        script_by_label = {
            label: script_name
            for _filename, (label, script_name) in CANDIDATE_SERVICES.items()
        }
        for label in sorted(RCA_RESIDENT_LABELS):
            launchd_pid = _live_launchd_pid(label)
            matching_pids = _matching_process_ids((script_by_label[label],))
            if launchd_pid is not None or matching_pids:
                raise EvidenceError("activation_bootstrap_rca_resident_running")
            residents[label] = {
                "launchd_state": "absent",
                "matching_pids": [],
                "state": "stopped",
            }
    gateway = _collect_gateway_candidate_runtime(
        repo_root=repo_root,
        cutover=cutover,
        consumer=consumer,
    )
    return {
        "rca_residents": residents,
        "rca_residents_required_stopped": require_rca_residents_stopped,
        "gateway": gateway,
    }


def _check_activation_bootstrap_runtime(
    *,
    mode: str,
    control_db_path: Path,
    repo_root: Path,
    cutover: CutoverConfig,
    consumer: ConsumerConfig,
    activation: Mapping[str, Any],
    previous_gateway_binding: Mapping[str, Any] | None = None,
    collector: Callable[..., Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    if mode not in {
        "preauthorization",
        "preproduction",
        *CANARY_MODES,
        *PRODUCTION_MODES,
    }:
        raise EvidenceError("activation_bootstrap_mode_invalid")
    if cutover.activation_required is not True:
        raise EvidenceError("activation_bootstrap_gateway_activation_not_required")
    require_stopped = mode in {"preauthorization", "preproduction"}
    observed = dict((collector or _collect_activation_bootstrap_runtime)(
        repo_root=repo_root,
        cutover=cutover,
        consumer=consumer,
        require_rca_residents_stopped=require_stopped,
    ))
    residents = _mapping(
        observed.get("rca_residents"), "activation_bootstrap.rca_residents"
    )
    if require_stopped and (
        set(residents) != RCA_RESIDENT_LABELS
        or any(
            _mapping(value, "activation_bootstrap.resident").get("state")
            != "stopped"
            for value in residents.values()
        )
    ):
        raise EvidenceError("activation_bootstrap_rca_resident_running")
    database = _read_activation_bootstrap_database(control_db_path)
    expected_database_state = {
        "preauthorization": "absent",
        "preproduction": "safe_off",
        "canary_bootstrap": "bounded_active",
        "canary": "bounded_active",
        "production_bootstrap": "bounded_active",
        "production": "bounded_active",
    }[mode]
    current = database.get("current_epoch")
    observed_state = (
        str(_mapping(current, "activation_bootstrap.current_epoch").get("state"))
        if current is not None
        else "absent"
    )
    if (
        observed_state != expected_database_state
        or database.get("active_effect_count") != 0
        or (
            mode == "preauthorization"
            and (database.get("epoch_count") != 0 or activation.get("state") != "absent")
        )
        or (
            mode != "preauthorization"
            and (
                database.get("current_epoch_count") != 1
                or not current
                or current.get("epoch_id") != activation.get("epoch_id")
            )
        )
    ):
        raise EvidenceError("activation_bootstrap_database_not_safe")
    gateway = _mapping(observed.get("gateway"), "activation_bootstrap.gateway")
    gateway_state = gateway.get("state")
    if gateway_state != "running_safe":
        raise EvidenceError("activation_bootstrap_gateway_not_running")
    identity = _check_gateway_runtime_identity(
        gateway.get("runtime_identity"),
        field="activation_bootstrap.gateway.runtime_identity",
    )
    verified = _mapping(
        gateway.get("verified"), "activation_bootstrap.gateway.verified"
    )
    if (
        verified.get("runtime_identity_sha256") != _sha256_json(identity)
        or verified.get("public_config_sha256")
        != _sha256_json(_gateway_manual_runtime_public_config(cutover, consumer))
    ):
        raise EvidenceError("activation_bootstrap_gateway_binding_invalid")
    gateway_binding: dict[str, Any] = {
        "state": "running_safe",
        "pid": identity["pid"],
        "process_create_time": identity["process_create_time"],
        "runtime_identity_sha256": _sha256_json(identity),
        "runtime_identity": identity,
        "verified_runtime_sha256": _sha256_json(verified),
    }
    prior = dict(previous_gateway_binding or {})
    if previous_gateway_binding is not None and gateway_binding != prior:
        raise EvidenceError("activation_bootstrap_gateway_restarted")
    return {
        "mode": mode,
        "rca_resident_count": len(RCA_RESIDENT_LABELS),
        "rca_residents_stopped": require_stopped,
        "gateway": gateway_binding,
        "gateway_activation_required": True,
        "manual_rca_admission": (
            "fail_closed_by_activation_state"
            if mode in {"preauthorization", "preproduction"}
            else "bounded_activation_only"
        ),
        "database_state": expected_database_state,
        "active_effect_count": 0,
        "database_snapshot_sha256": database["snapshot_sha256"],
    }


def _check_manual_canary_gateway_runtime(
    manual_success_detail: Mapping[str, Any],
    manual_terminal_detail: Mapping[str, Any],
) -> dict[str, Any]:
    manual_observed_source = _mapping(
        manual_success_detail.get("observed_trigger_source"),
        "manual_success_canary.validated_observed_source",
    )
    manual_authorization = _mapping(
        manual_observed_source.get("authorization"),
        "manual_success_canary.validated_authorization",
    )
    manual_identity = _check_gateway_runtime_identity(
        manual_authorization.get("gateway_runtime_identity"),
        field="manual_success_canary.gateway_runtime_identity",
    )
    terminal_identity = _check_gateway_runtime_identity(
        manual_terminal_detail.get("gateway_runtime_identity"),
        field="manual_terminal_failure_canary.gateway_runtime_identity",
    )
    if manual_identity != terminal_identity:
        raise EvidenceError("manual_canary_gateway_runtime_mismatch")
    return {
        "runtime_identity_sha256": _sha256_json(manual_identity),
        "runtime_identity": manual_identity,
    }


def _bind_canary_transitions_to_residents(
    databases: Mapping[str, Any],
    residents: Mapping[str, Any],
) -> dict[str, Any]:
    service_artifacts = {
        "local.pnc.rca-kafka-consumer": "kafka_consumer_health",
        "local.pnc.rca-outbox-dispatcher": "outbox_dispatcher_health",
        "local.pnc.rca-delivery-collector": "delivery_collector_health",
        "local.pnc.rca-delivery-dispatcher": "delivery_dispatcher_health",
    }
    if set(databases) != {"kafka_success", "manual_success", "manual_terminal"}:
        raise EvidenceError("manual_gateway_runtime_barrier_databases_invalid")
    if set(residents) != set(service_artifacts.values()):
        raise EvidenceError("manual_gateway_runtime_barrier_residents_invalid")
    bound_services: set[str] = set()
    transition_digests: dict[str, str] = {}
    for canary_name in sorted(databases):
        database = _mapping(
            databases.get(canary_name),
            f"manual_gateway_runtime_barrier.databases.{canary_name}",
        )
        transitions = database.get("host_runtime_transitions")
        if not isinstance(transitions, list) or not transitions:
            raise EvidenceError(
                "manual_gateway_runtime_barrier_transitions_unverified"
            )
        for index, raw in enumerate(transitions):
            transition = _mapping(
                raw,
                f"manual_gateway_runtime_barrier.{canary_name}.transitions[{index}]",
            )
            label = _required_text(
                transition.get("service_label"),
                f"manual_gateway_runtime_barrier.{canary_name}.service_label",
            )
            artifact = service_artifacts.get(label)
            if artifact is None:
                raise EvidenceError(
                    "manual_gateway_runtime_barrier_transition_service_invalid"
                )
            resident = _mapping(
                residents.get(artifact),
                f"manual_gateway_runtime_barrier.residents.{artifact}",
            )
            identity = _mapping(
                transition.get("runtime_identity"),
                f"manual_gateway_runtime_barrier.{canary_name}.runtime_identity",
            )
            if (
                transition.get("runtime_identity_sha256")
                != resident.get("runtime_identity_sha256")
                or identity.get("pid") != resident.get("pid")
                or _number(
                    identity.get("process_create_time"),
                    f"manual_gateway_runtime_barrier.{canary_name}.process_create_time",
                    minimum=1,
                )
                != _number(
                    resident.get("process_create_time"),
                    f"manual_gateway_runtime_barrier.{artifact}.process_create_time",
                    minimum=1,
                )
            ):
                raise EvidenceError(
                    "manual_gateway_runtime_barrier_transition_resident_mismatch"
                )
            bound_services.add(label)
        transition_digests[canary_name] = _sha256_json(transitions)
    if bound_services != set(service_artifacts):
        raise EvidenceError(
            "manual_gateway_runtime_barrier_transition_services_incomplete"
        )
    return {
        "services": sorted(bound_services),
        "canary_transition_sha256": transition_digests,
        "binding_sha256": _sha256_json(transition_digests),
    }


def _project_resident_runtime_bindings(
    value: Mapping[str, Any],
    *,
    artifact: str,
) -> dict[str, dict[str, Any]]:
    residents = _mapping(value, artifact)
    expected_artifacts = {
        "kafka_consumer_health",
        "outbox_dispatcher_health",
        "delivery_collector_health",
        "delivery_dispatcher_health",
    }
    if set(residents) != expected_artifacts:
        raise EvidenceError(f"{artifact}_invalid")
    projection: dict[str, dict[str, Any]] = {}
    for resident_artifact in sorted(expected_artifacts):
        summary = _mapping(
            residents.get(resident_artifact),
            f"{artifact}.{resident_artifact}",
        )
        process = _mapping(
            summary.get("process"),
            f"{artifact}.{resident_artifact}.process",
        )
        launchctl = _mapping(
            process.get("launchctl"),
            f"{artifact}.{resident_artifact}.launchctl",
        )
        installed_plist = _mapping(
            process.get("installed_plist"),
            f"{artifact}.{resident_artifact}.installed_plist",
        )
        if (
            launchctl.get("state") != "running"
            or launchctl.get("pid") != process.get("pid")
            or not {
                "plist_path_sha256",
                "program_arguments_sha256",
                "working_directory_sha256",
                "environment_sha256",
            }.issubset(launchctl)
        ):
            raise EvidenceError(f"{artifact}_process_invalid")
        projection[resident_artifact] = {
            "runtime_identity_sha256": _sha256_digest(
                summary.get("runtime_identity_sha256"),
                f"{artifact}.{resident_artifact}.identity",
            ),
            "loaded_runtime_sha256": _sha256_digest(
                summary.get("loaded_runtime_sha256"),
                f"{artifact}.{resident_artifact}.loaded_runtime",
            ),
            "pid": _exact_int(
                process.get("pid"),
                f"{artifact}.{resident_artifact}.pid",
                minimum=1,
            ),
            "process_create_time": _number(
                process.get("process_create_time"),
                f"{artifact}.{resident_artifact}.process_create_time",
                minimum=1,
            ),
            "boot_time": _number(
                process.get("boot_time"),
                f"{artifact}.{resident_artifact}.boot_time",
                minimum=1,
            ),
            "executable": _required_text(
                process.get("executable"),
                f"{artifact}.{resident_artifact}.executable",
            ),
            "cwd": _required_text(
                process.get("cwd"),
                f"{artifact}.{resident_artifact}.cwd",
            ),
            "cmdline_sha256": _sha256_digest(
                process.get("cmdline_sha256"),
                f"{artifact}.{resident_artifact}.cmdline_sha256",
            ),
            "required_environment_sha256": _sha256_digest(
                process.get("required_environment_sha256"),
                f"{artifact}.{resident_artifact}.environment_sha256",
            ),
            "launchctl_sha256": _sha256_json(launchctl),
            "installed_plist_sha256": _sha256_json(installed_plist),
        }
        if resident_artifact == "outbox_dispatcher_health":
            projection[resident_artifact]["capacity_admission"] = dict(
                _mapping(
                    summary.get("capacity_admission"),
                    f"{artifact}.{resident_artifact}.capacity_admission",
                )
            )
    return projection


def _check_manual_gateway_runtime_barrier(
    *,
    manual_success_detail: Mapping[str, Any],
    manual_terminal_detail: Mapping[str, Any],
    manual_success_sources_verified: bool,
    manual_terminal_sources_verified: bool,
    build_detail: Mapping[str, Any],
    settings: ReleaseGateSettings,
    cutover: CutoverConfig,
    consumer: ConsumerConfig,
    gateway_verifier: Any = None,
    resident_verifier: Any = None,
    database_verifier: Any = None,
) -> dict[str, Any]:
    if (
        not manual_success_detail
        or not manual_terminal_detail
        or not manual_success_sources_verified
        or not manual_terminal_sources_verified
        or not build_detail
    ):
        raise EvidenceError("manual_gateway_runtime_barrier_prerequisite_unverified")
    binding = _check_manual_canary_gateway_runtime(
        manual_success_detail,
        manual_terminal_detail,
    )
    identity = _mapping(
        binding.get("runtime_identity"),
        "manual_gateway_runtime_barrier.identity",
    )
    def observe_authorizations() -> dict[str, str]:
        observed: dict[str, str] = {}
        for name, detail in (
            ("manual_success", manual_success_detail),
            ("manual_terminal", manual_terminal_detail),
        ):
            source = _mapping(
                detail.get("observed_trigger_source"),
                f"manual_gateway_runtime_barrier.{name}.observed_trigger_source",
            )
            authorization = _mapping(
                source.get("authorization"),
                f"manual_gateway_runtime_barrier.{name}.authorization",
            )
            source_details = _mapping(
                detail.get("sources"),
                f"manual_gateway_runtime_barrier.{name}.sources",
            )
            authorization_sources = _mapping(
                source_details.get("authorization_sources"),
                f"manual_gateway_runtime_barrier.{name}.authorization_sources",
            )
            source_id = _required_text(
                source.get("source_id"),
                f"manual_gateway_runtime_barrier.{name}.source_id",
            )
            record = _mapping(
                authorization_sources.get(source_id),
                f"manual_gateway_runtime_barrier.{name}.authorization_source",
            )
            rechecked = _read_bound_group_authorization_source(
                record,
                evidence=authorization,
                expected_root=settings.group_binding_receipt_dir,
            )
            observed[name] = rechecked["raw_sha256"]
        return observed
    expected_commit = _commit_sha(
        build_detail.get("host_commit"),
        "manual_gateway_runtime_barrier.host_commit",
    )
    expected_critical = _mapping(
        build_detail.get("critical_file_sha256"),
        "manual_gateway_runtime_barrier.critical_file_sha256",
    )
    if not expected_critical:
        raise EvidenceError("manual_gateway_runtime_barrier_build_unverified")
    expected_critical_map = {
        _required_text(name, "manual_gateway_runtime_barrier.critical_file"): (
            _sha256_digest(
                digest,
                f"manual_gateway_runtime_barrier.critical_file_sha256.{name}",
            )
        )
        for name, digest in expected_critical.items()
    }
    expected_critical_sha256 = _sha256_digest(
        build_detail.get("critical_files_sha256"),
        "manual_gateway_runtime_barrier.critical_files_sha256",
    )
    verifier = gateway_verifier or _verify_gateway_runtime_identity
    gateway_observations: list[dict[str, Any]] = []
    if resident_verifier is None:
        raise EvidenceError("manual_gateway_runtime_barrier_residents_unverified")
    if database_verifier is None:
        raise EvidenceError("manual_gateway_runtime_barrier_databases_unverified")
    resident_observations: list[dict[str, Any]] = []
    source_observations: list[dict[str, Any]] = []

    def observe_host() -> dict[str, Any]:
        try:
            provenance = _local_git_provenance(
                settings.host_repo_root,
                component="host",
            )
        except EvidenceError as exc:
            raise EvidenceError(
                "manual_gateway_runtime_barrier_host_unverified"
            ) from exc
        if provenance.get("commit") != expected_commit:
            raise EvidenceError("manual_gateway_runtime_barrier_commit_mismatch")
        try:
            file_map, aggregate = runtime_file_snapshot(
                settings.host_repo_root,
                tuple(sorted(expected_critical_map)),
            )
        except (OSError, ValueError) as exc:
            raise EvidenceError(
                "manual_gateway_runtime_barrier_file_snapshot_unavailable"
            ) from exc
        if (
            file_map != expected_critical_map
            or aggregate != expected_critical_sha256
        ):
            raise EvidenceError("manual_gateway_runtime_barrier_file_mismatch")
        return {
            "commit": provenance["commit"],
            "critical_files_sha256": aggregate,
        }

    def observe_gateway() -> dict[str, Any]:
        try:
            observed = verifier(
                identity,
                repo_root=settings.host_repo_root,
                cutover=cutover,
                consumer=consumer,
            )
        except EvidenceError:
            raise
        except Exception as exc:
            raise EvidenceError(
                "manual_gateway_runtime_barrier_gateway_unavailable"
            ) from exc
        if not isinstance(observed, Mapping):
            raise EvidenceError("manual_gateway_runtime_barrier_gateway_invalid")
        return dict(observed)

    def observe_residents() -> dict[str, Any]:
        try:
            observed = resident_verifier()
        except EvidenceError:
            raise
        except Exception as exc:
            raise EvidenceError(
                "manual_gateway_runtime_barrier_residents_unavailable"
            ) from exc
        return _project_resident_runtime_bindings(
            observed,
            artifact="manual_gateway_runtime_barrier_residents",
        )

    def observe_sources() -> dict[str, Any]:
        try:
            databases = database_verifier()
        except EvidenceError:
            raise
        except Exception as exc:
            raise EvidenceError(
                "manual_gateway_runtime_barrier_databases_unavailable"
            ) from exc
        database_projection = _mapping(
            databases,
            "manual_gateway_runtime_barrier.databases",
        )
        if set(database_projection) != {
            "kafka_success",
            "manual_success",
            "manual_terminal",
        }:
            raise EvidenceError("manual_gateway_runtime_barrier_databases_invalid")
        database_details: dict[str, Any] = {}
        for name in sorted(database_projection):
            detail = _mapping(
                database_projection.get(name),
                f"manual_gateway_runtime_barrier.databases.{name}",
            )
            projection_sha256 = _sha256_digest(
                detail.get("projection_sha256"),
                f"manual_gateway_runtime_barrier.databases.{name}.projection",
            )
            transitions = detail.get("host_runtime_transitions")
            if not isinstance(transitions, list) or not transitions:
                raise EvidenceError(
                    "manual_gateway_runtime_barrier_transitions_unverified"
                )
            transition_sha256 = _sha256_digest(
                detail.get("host_runtime_transitions_sha256"),
                f"manual_gateway_runtime_barrier.databases.{name}.transitions",
            )
            if transition_sha256 != _sha256_json(transitions):
                raise EvidenceError(
                    "manual_gateway_runtime_barrier_transitions_invalid"
                )
            database_details[name] = {
                "projection_sha256": projection_sha256,
                "host_runtime_transitions_sha256": transition_sha256,
                "host_runtime_transitions": [dict(_mapping(
                    item,
                    f"manual_gateway_runtime_barrier.databases.{name}.transition",
                )) for item in transitions],
            }
        return {
            "authorizations": observe_authorizations(),
            "databases": database_details,
        }

    host_observations: list[dict[str, Any]] = []
    for _round in range(3):
        host_observations.append(observe_host())
        resident_observations.append(observe_residents())
        gateway_observations.append(observe_gateway())
        source_observations.append(observe_sources())
    # Final closeout observes durable sources before the processes that must
    # have created them, then closes on the immutable host file set.
    source_observations.append(observe_sources())
    resident_observations.append(observe_residents())
    gateway_observations.append(observe_gateway())
    host_observations.append(observe_host())
    if (
        host_observations[0] != host_observations[1]
        or host_observations[1] != host_observations[2]
        or host_observations[2] != host_observations[3]
        or gateway_observations[0] != gateway_observations[1]
        or gateway_observations[1] != gateway_observations[2]
        or gateway_observations[2] != gateway_observations[3]
        or resident_observations[0] != resident_observations[1]
        or resident_observations[1] != resident_observations[2]
        or resident_observations[2] != resident_observations[3]
        or source_observations[0] != source_observations[1]
        or source_observations[1] != source_observations[2]
        or source_observations[2] != source_observations[3]
    ):
        raise EvidenceError("manual_gateway_runtime_barrier_unstable")
    transition_binding = _bind_canary_transitions_to_residents(
        source_observations[3]["databases"],
        resident_observations[3],
    )
    gateway = gateway_observations[3]
    runtime_map = _mapping(
        gateway.get("runtime_file_sha256"),
        "manual_gateway_runtime_barrier.runtime_file_sha256",
    )
    if (
        set(runtime_map) != set(GATEWAY_RCA_RUNTIME_RELATIVE_FILES)
        or any(
            expected_critical_map.get(name) != digest
            for name, digest in runtime_map.items()
        )
        or gateway.get("runtime_files_sha256") != _sha256_json(runtime_map)
        or gateway.get("runtime_files_sha256")
        != identity.get("runtime_files_sha256")
        or gateway.get("public_config_sha256")
        != identity.get("public_config_sha256")
        or gateway.get("loaded_runtime_sha256")
        != identity.get("loaded_runtime_sha256")
    ):
        raise EvidenceError("manual_gateway_runtime_barrier_build_mismatch")
    process = _mapping(
        gateway.get("process"),
        "manual_gateway_runtime_barrier.process",
    )
    launchctl = process.get("launchctl")
    if (
        process.get("pid") != identity.get("pid")
        or not isinstance(launchctl, Mapping)
        or launchctl.get("state") != "running"
        or launchctl.get("pid") != identity.get("pid")
        or not {
            "plist_path_sha256",
            "program_arguments_sha256",
            "working_directory_sha256",
            "environment_sha256",
        }.issubset(launchctl)
    ):
        raise EvidenceError("manual_gateway_runtime_barrier_process_mismatch")
    for field in (
        "plist_sha256",
        "interpreter_sha256",
        "process_executable_sha256",
        "module_origins_sha256",
        "loaded_runtime_sha256",
        "dependency_files_sha256",
    ):
        _sha256_digest(gateway.get(field), f"manual_gateway_runtime_barrier.{field}")
    return {
        "host_commit": expected_commit,
        "critical_files_sha256": expected_critical_sha256,
        "runtime_identity_sha256": binding["runtime_identity_sha256"],
        "runtime_files_sha256": gateway.get("runtime_files_sha256"),
        "public_config_sha256": gateway.get("public_config_sha256"),
        "plist_sha256": gateway.get("plist_sha256"),
        "interpreter_sha256": gateway.get("interpreter_sha256"),
        "process_executable_sha256": gateway.get("process_executable_sha256"),
        "module_origins_sha256": gateway.get("module_origins_sha256"),
        "loaded_runtime_sha256": gateway.get("loaded_runtime_sha256"),
        "dependency_files_sha256": gateway.get("dependency_files_sha256"),
        "pid": process["pid"],
        "process_create_time": process.get("process_create_time"),
        "launchctl_config_sha256": _sha256_json(launchctl),
        "authorization_sources_sha256": _sha256_json(
            source_observations[3]["authorizations"]
        ),
        "database_sources_sha256": _sha256_json(
            source_observations[3]["databases"]
        ),
        "resident_runtime_sha256": _sha256_json(resident_observations[3]),
        "resident_runtime_binding": resident_observations[3],
        "canary_transition_binding_sha256": transition_binding["binding_sha256"],
        "verification_rounds": 4,
        "host_verification_rounds": 4,
        "source_verification_rounds": 4,
        "resident_verification_rounds": 4,
        "gateway_verification_rounds": 4,
        "final_host_observation": True,
    }


def _check_outbox_delivery_backpressure_health(
    boundary: Mapping[str, Any],
    *,
    config: Mapping[str, Any],
    now: datetime,
    artifact: str,
) -> dict[str, Any]:
    if (
        boundary.get("enabled") is not True
        or boundary.get("active") is not False
        or boundary.get("last_error") is not None
    ):
        raise EvidenceError(f"{artifact}_delivery_backpressure_not_ready")
    high_watermark = _exact_int(
        boundary.get("high_watermark"),
        f"{artifact}.delivery_backpressure.high_watermark",
        minimum=1,
    )
    resume_watermark = _exact_int(
        boundary.get("resume_watermark"),
        f"{artifact}.delivery_backpressure.resume_watermark",
        minimum=0,
    )
    if (
        high_watermark != config.get("delivery_high_watermark")
        or resume_watermark != config.get("delivery_resume_watermark")
        or resume_watermark >= high_watermark
    ):
        raise EvidenceError(f"{artifact}_delivery_backpressure_config_mismatch")
    raw_snapshot = boundary.get("last_snapshot")
    if not isinstance(raw_snapshot, dict):
        raise EvidenceError(f"{artifact}_delivery_backpressure_not_ready")
    snapshot = raw_snapshot
    _require_schema(
        snapshot,
        DELIVERY_BACKPRESSURE_SNAPSHOT_SCHEMA_VERSION,
        f"{artifact}_delivery_backpressure",
    )
    observed_at = _timestamp(
        snapshot.get("observed_at"),
        f"{artifact}.delivery_backpressure.last_snapshot.observed_at",
    )
    age_seconds = (now.astimezone(timezone.utc) - observed_at).total_seconds()
    if age_seconds < -30:
        raise EvidenceError(f"{artifact}_delivery_backpressure_from_future")
    if age_seconds > DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS:
        raise EvidenceError(f"{artifact}_delivery_backpressure_stale")
    if snapshot.get("db_path") != config.get("delivery_db_path"):
        raise EvidenceError(f"{artifact}_delivery_backpressure_db_mismatch")
    effect_counts = _mapping(
        snapshot.get("effect_counts"),
        f"{artifact}.delivery_backpressure.last_snapshot.effect_counts",
    )
    expected_effect_states = {"pending", "claimed", "retry_wait", "uncertain"}
    if set(effect_counts) != expected_effect_states:
        raise EvidenceError(f"{artifact}_delivery_backpressure_contract_invalid")
    normalized_effect_counts = {
        state: _exact_int(
            effect_counts.get(state),
            f"{artifact}.delivery_backpressure.effect_counts.{state}",
            minimum=0,
        )
        for state in sorted(expected_effect_states)
    }
    unresolved_effects = _exact_int(
        snapshot.get("unresolved_effects"),
        f"{artifact}.delivery_backpressure.unresolved_effects",
        minimum=0,
    )
    if unresolved_effects != sum(normalized_effect_counts.values()):
        raise EvidenceError(f"{artifact}_delivery_backpressure_contract_invalid")
    pipeline_counts = _mapping(
        snapshot.get("pipeline_counts"),
        f"{artifact}.delivery_backpressure.last_snapshot.pipeline_counts",
    )
    expected_pipeline_states = {
        "untracked_completed_submissions",
        "pending_watches",
        "running_watches",
    }
    if set(pipeline_counts) != expected_pipeline_states:
        raise EvidenceError(f"{artifact}_delivery_backpressure_contract_invalid")
    normalized_pipeline_counts = {
        state: _exact_int(
            pipeline_counts.get(state),
            f"{artifact}.delivery_backpressure.pipeline_counts.{state}",
            minimum=0,
        )
        for state in sorted(expected_pipeline_states)
    }
    unresolved_work = _exact_int(
        snapshot.get("unresolved_work"),
        f"{artifact}.delivery_backpressure.unresolved_work",
        minimum=0,
    )
    if unresolved_work != unresolved_effects + sum(normalized_pipeline_counts.values()):
        raise EvidenceError(f"{artifact}_delivery_backpressure_contract_invalid")
    outcome_slo = _mapping(
        snapshot.get("delivery_outcome_slo"),
        f"{artifact}.delivery_backpressure.last_snapshot.delivery_outcome_slo",
    )
    try:
        outcome_slo_healthy = validate_delivery_outcome_slo(
            outcome_slo,
            expected_observed_at=str(snapshot.get("observed_at") or ""),
        )
    except (TypeError, ValueError) as exc:
        raise EvidenceError(
            f"{artifact}_delivery_backpressure_contract_invalid"
        ) from exc
    if not outcome_slo_healthy:
        raise EvidenceError(f"{artifact}_delivery_outcome_slo_failed")
    circuit = _mapping(
        snapshot.get("delivery_dispatcher_circuit"),
        f"{artifact}.delivery_backpressure.last_snapshot.circuit",
    )
    circuits = _mapping(
        snapshot.get("delivery_dispatcher_circuits"),
        f"{artifact}.delivery_backpressure.last_snapshot.circuits",
    )
    required_circuits = {"feishu_issue_comment", "feishu_thread_reply"}
    if set(circuits) != required_circuits:
        raise EvidenceError(f"{artifact}_delivery_backpressure_contract_invalid")
    normalized_circuits: dict[str, dict[str, Any]] = {}
    for name in sorted(required_circuits):
        item = _mapping(circuits.get(name), f"{artifact}.delivery_circuit.{name}")
        if set(item) != {
            "state",
            "reason_code",
            "reason_detail",
            "opened_at",
            "updated_at",
        }:
            raise EvidenceError(f"{artifact}_delivery_backpressure_contract_invalid")
        if item.get("state") != "closed":
            raise EvidenceError(f"{artifact}_delivery_backpressure_circuit_open")
        _timestamp(item.get("updated_at"), f"{artifact}.delivery_circuit.updated_at")
        normalized_circuits[name] = dict(item)
    if circuit.get("state") != "closed":
        raise EvidenceError(f"{artifact}_delivery_backpressure_circuit_open")
    if circuit != normalized_circuits["feishu_issue_comment"]:
        raise EvidenceError(f"{artifact}_delivery_backpressure_contract_invalid")
    return {
        "snapshot_sha256": _sha256_json(snapshot),
        "observed_at": observed_at.isoformat(),
        "unresolved_work": unresolved_work,
        "delivery_outcome_slo_sha256": _sha256_json(outcome_slo),
        "circuit_state": "closed",
        "circuit_states": {name: "closed" for name in sorted(required_circuits)},
    }


def _check_capacity_runtime_projection(
    value: Any,
    *,
    config: Mapping[str, Any],
    artifact: str,
) -> dict[str, Any]:
    runtime = _mapping(value, f"{artifact}.capacity_admission.runtime")
    expected_fields = {
        "schema_version",
        "configured",
        "legacy_compatibility",
        "initial_policy",
        "effective_state",
        "effective_mode",
        "generation",
        "irreversible",
        "ready",
        "reason_code",
        "current_release_id",
        "current_bootstrap_epoch_id",
        "ratchet_origin_release_id",
        "ratchet_origin_bootstrap_epoch_id",
        "active_release_binding_sha256",
        "ledger",
        "artifacts",
        "lock",
    }
    if (
        set(runtime) != expected_fields
        or runtime.get("schema_version")
        != capacity_runtime.RUNTIME_DECISION_SCHEMA_VERSION
        or runtime.get("configured") is not True
        or runtime.get("legacy_compatibility") is not False
        or runtime.get("ready") is not True
    ):
        raise EvidenceError(f"{artifact}_capacity_runtime_contract_invalid")
    configured_mode = str(config.get("capacity_mode") or "")
    mode = str(runtime.get("effective_mode") or "")
    state = str(runtime.get("effective_state") or "")
    if (
        configured_mode not in {"bootstrap", "steady"}
        or mode not in {"bootstrap", "steady"}
        or (configured_mode == "steady" and mode != "steady")
        or runtime.get("initial_policy") != configured_mode
        or runtime.get("current_release_id") != config.get("release_id")
        or runtime.get("current_bootstrap_epoch_id")
        != config.get("bootstrap_epoch_id")
    ):
        raise EvidenceError(f"{artifact}_capacity_runtime_binding_invalid")
    lock = _mapping(runtime.get("lock"), f"{artifact}.capacity_admission.runtime.lock")
    if (
        set(lock) != {"held", "latency_ms", "error_code"}
        or lock.get("held") is not True
        or lock.get("error_code") not in {"", None}
        or not isinstance(lock.get("latency_ms"), (int, float))
        or isinstance(lock.get("latency_ms"), bool)
        or not math.isfinite(float(lock["latency_ms"]))
        or float(lock["latency_ms"]) < 0
    ):
        raise EvidenceError(f"{artifact}_capacity_runtime_lock_invalid")
    ledger = _mapping(
        runtime.get("ledger"), f"{artifact}.capacity_admission.runtime.ledger"
    )
    if set(ledger) != {
        "sample_count",
        "sha256",
        "window_seconds",
        "max_gap_seconds",
        "first_observed_at",
        "last_observed_at",
        "steady_qualified",
    }:
        raise EvidenceError(f"{artifact}_capacity_runtime_ledger_invalid")
    sample_count = _exact_int(
        ledger.get("sample_count"),
        f"{artifact}.capacity_admission.runtime.ledger.sample_count",
        minimum=0,
    )
    _sha256_digest(
        ledger.get("sha256"),
        f"{artifact}.capacity_admission.runtime.ledger.sha256",
    )
    for field in ("window_seconds", "max_gap_seconds"):
        raw = ledger.get(field)
        if (
            isinstance(raw, bool)
            or not isinstance(raw, (int, float))
            or not math.isfinite(float(raw))
            or float(raw) < 0
        ):
            raise EvidenceError(f"{artifact}_capacity_runtime_ledger_invalid")
    if sample_count:
        _timestamp(
            ledger.get("first_observed_at"),
            f"{artifact}.capacity_admission.runtime.ledger.first_observed_at",
        )
        _timestamp(
            ledger.get("last_observed_at"),
            f"{artifact}.capacity_admission.runtime.ledger.last_observed_at",
        )
    elif ledger.get("first_observed_at") is not None or ledger.get(
        "last_observed_at"
    ) is not None:
        raise EvidenceError(f"{artifact}_capacity_runtime_ledger_invalid")

    generation = _exact_int(
        runtime.get("generation"),
        f"{artifact}.capacity_admission.runtime.generation",
        minimum=1,
    )
    active_binding = _sha256_digest(
        runtime.get("active_release_binding_sha256"),
        f"{artifact}.capacity_admission.runtime.active_release_binding_sha256",
    )
    if mode == "bootstrap":
        if (
            state not in {"BOOTSTRAP_PRODUCTION", "STEADY_READY"}
            or generation != 1
            or runtime.get("irreversible") is not False
            or runtime.get("artifacts") is not None
            or ledger.get("steady_qualified") is not (state == "STEADY_READY")
        ):
            raise EvidenceError(f"{artifact}_capacity_runtime_bootstrap_invalid")
    else:
        artifacts = _mapping(
            runtime.get("artifacts"),
            f"{artifact}.capacity_admission.runtime.artifacts",
        )
        expected_artifacts = {
            "transition_intent_sha256",
            "transition_intent_fingerprint",
            "transition_authorization_sha256",
            "transition_authorization_fingerprint",
            "transition_receipt_sha256",
            "transition_receipt_fingerprint",
            "commit_marker_sha256",
            "commit_marker_fingerprint",
            "evidence_bundle_sha256",
            "evidence_bundle_fingerprint",
        }
        if (
            state != "STEADY_ACTIVE"
            or generation != 2
            or runtime.get("irreversible") is not True
            or runtime.get("reason_code") != "rca_capacity_steady_commit_valid"
            or sample_count < 20
            or ledger.get("steady_qualified") is not True
            or set(artifacts) != expected_artifacts
        ):
            raise EvidenceError(f"{artifact}_capacity_runtime_steady_invalid")
        for field in expected_artifacts:
            _sha256_digest(
                artifacts.get(field),
                f"{artifact}.capacity_admission.runtime.artifacts.{field}",
            )
    for field in (
        "ratchet_origin_release_id",
        "ratchet_origin_bootstrap_epoch_id",
    ):
        _required_text(
            runtime.get(field), f"{artifact}.capacity_admission.runtime.{field}"
        )
    return {
        "effective_mode": mode,
        "effective_state": state,
        "generation": generation,
        "active_release_binding_sha256": active_binding,
        "sample_count": sample_count,
    }


def _check_outbox_capacity_admission_health(
    value: Any,
    *,
    config: Mapping[str, Any],
    now: datetime,
    artifact: str,
) -> dict[str, Any]:
    status = _mapping(value, f"{artifact}.capacity_admission")
    base_fields = {
        "required",
        "ready",
        "state",
        "error_code",
        "capacity_mode",
        "authorization",
    }
    if frozenset(status) not in {
        frozenset(base_fields),
        frozenset({*base_fields, "runtime"}),
    }:
        raise EvidenceError(f"{artifact}_capacity_admission_contract_invalid")
    configured_mode = str(config.get("capacity_mode") or "")
    runtime_detail = (
        _check_capacity_runtime_projection(
            status.get("runtime"), config=config, artifact=artifact
        )
        if "runtime" in status
        else None
    )
    capacity_mode = (
        str(runtime_detail["effective_mode"])
        if runtime_detail is not None
        else configured_mode
    )
    if (
        status.get("capacity_mode") != capacity_mode
        or configured_mode not in {"bootstrap", "steady"}
        or (configured_mode == "steady" and capacity_mode != "steady")
    ):
        raise EvidenceError(f"{artifact}_capacity_admission_mode_mismatch")
    if capacity_mode == "steady":
        expected_required = bool(
            runtime_detail is not None
            and (
                config.get("dispatch_enabled") is True
                or config.get("activation_required") is True
            )
        )
        if (
            status.get("required") is not expected_required
            or status.get("ready") is not True
            or status.get("error_code") != ""
            or status.get("authorization") is not None
            or (
                runtime_detail is None
                and status.get("state") != "steady"
            )
            or (
                runtime_detail is not None
                and status.get("state") != runtime_detail["effective_state"]
            )
        ):
            raise EvidenceError(f"{artifact}_capacity_admission_not_ready")
        return {
            **dict(status),
            "runtime_projection": runtime_detail,
        }
    if capacity_mode != "bootstrap":
        raise EvidenceError(f"{artifact}_capacity_admission_mode_mismatch")
    authorization = _mapping(
        status.get("authorization"), f"{artifact}.capacity_admission.authorization"
    )
    expected_bootstrap_state = (
        runtime_detail["effective_state"]
        if runtime_detail is not None
        else "ready"
    )
    if (
        status.get("required") is not True
        or status.get("ready") is not True
        or status.get("state") != expected_bootstrap_state
        or status.get("error_code") != ""
        or set(authorization)
        != {
            "bootstrap_epoch_id",
            "started_at",
            "deadline",
            "receipt_fingerprint",
            "authorization_receipt_sha256",
            "active_release_binding_sha256",
            "candidate_env_sha256",
            "release_bom_sha256",
            "release_approval_id",
            "approval_evidence_sha256",
        }
    ):
        raise EvidenceError(f"{artifact}_capacity_admission_not_ready")
    if (
        runtime_detail is not None
        and runtime_detail["active_release_binding_sha256"]
        != authorization.get("active_release_binding_sha256")
    ):
        raise EvidenceError(f"{artifact}_capacity_admission_runtime_mismatch")
    try:
        expected_epoch_id = _required_text(
            config.get("bootstrap_epoch_id"),
            f"{artifact}.config.bootstrap_epoch_id",
        )
        expected_release_id = _required_text(
            config.get("release_id"), f"{artifact}.config.release_id"
        )
        active_binding = prod_bootstrap.load_active_release_binding(
            path=Path(
                _required_text(
                    config.get("active_release_binding_path"),
                    f"{artifact}.config.active_release_binding_path",
                )
            ),
            live_env_path=Path(
                _required_text(
                    config.get("live_env_path"),
                    f"{artifact}.config.live_env_path",
                )
            ),
            expected_release_id=expected_release_id,
            expected_epoch_id=expected_epoch_id,
        )
        live = prod_bootstrap.load_bootstrap_authorization(
            now=now,
            expected_epoch_id=expected_epoch_id,
            expected_release_bom_sha256=active_binding["release_bom_sha256"],
            expected_release_approval_id=expected_release_id,
            expected_approval_evidence_sha256=active_binding[
                "approval_evidence_sha256"
            ],
        )
    except prod_bootstrap.RcaBootstrapAuthorizationError as exc:
        raise EvidenceError(
            f"{artifact}_capacity_admission_live_{exc.code}"
        ) from exc
    normalized = {
        "bootstrap_epoch_id": _required_text(
            authorization.get("bootstrap_epoch_id"),
            f"{artifact}.capacity_admission.bootstrap_epoch_id",
        ),
        "started_at": _timestamp(
            authorization.get("started_at"),
            f"{artifact}.capacity_admission.started_at",
        ).isoformat(),
        "deadline": _timestamp(
            authorization.get("deadline"),
            f"{artifact}.capacity_admission.deadline",
        ).isoformat(),
        "receipt_fingerprint": _sha256_digest(
            authorization.get("receipt_fingerprint"),
            f"{artifact}.capacity_admission.receipt_fingerprint",
        ),
        "authorization_receipt_sha256": _sha256_digest(
            authorization.get("authorization_receipt_sha256"),
            f"{artifact}.capacity_admission.authorization_receipt_sha256",
        ),
        "active_release_binding_sha256": _sha256_digest(
            authorization.get("active_release_binding_sha256"),
            f"{artifact}.capacity_admission.active_release_binding_sha256",
        ),
        "candidate_env_sha256": _sha256_digest(
            authorization.get("candidate_env_sha256"),
            f"{artifact}.capacity_admission.candidate_env_sha256",
        ),
        "release_bom_sha256": _sha256_digest(
            authorization.get("release_bom_sha256"),
            f"{artifact}.capacity_admission.release_bom_sha256",
        ),
        "release_approval_id": _required_text(
            authorization.get("release_approval_id"),
            f"{artifact}.capacity_admission.release_approval_id",
        ),
        "approval_evidence_sha256": _sha256_digest(
            authorization.get("approval_evidence_sha256"),
            f"{artifact}.capacity_admission.approval_evidence_sha256",
        ),
    }
    expected_live = {
        **{
            key: live[key]
            for key in (
                "bootstrap_epoch_id",
                "receipt_fingerprint",
                "authorization_receipt_sha256",
                "release_bom_sha256",
                "release_approval_id",
                "approval_evidence_sha256",
            )
        },
        "started_at": prod_admission._timestamp(live["started_at"]).isoformat(),
        "deadline": prod_admission._timestamp(live["deadline"]).isoformat(),
        "active_release_binding_sha256": active_binding[
            "binding_receipt_sha256"
        ],
        "candidate_env_sha256": active_binding["candidate_env_sha256"],
    }
    if normalized != expected_live:
        raise EvidenceError(f"{artifact}_capacity_admission_live_mismatch")
    return {
        "required": True,
        "ready": True,
        "state": expected_bootstrap_state,
        "error_code": "",
        "capacity_mode": "bootstrap",
        "authorization": normalized,
        "runtime_projection": runtime_detail,
    }


def _bind_outbox_bootstrap_capacity_health(
    health: Mapping[str, Any],
    authorization: Mapping[str, Any],
) -> None:
    outbox = _mapping(
        health.get("outbox_dispatcher_health"),
        "bootstrap_capacity.outbox_dispatcher_health",
    )
    capacity = _mapping(
        outbox.get("capacity_admission"),
        "bootstrap_capacity.outbox_dispatcher_health.capacity_admission",
    )
    observed = _mapping(
        capacity.get("authorization"),
        "bootstrap_capacity.outbox_dispatcher_health.authorization",
    )
    if any(
        observed.get(observed_name) != authorization.get(expected_name)
        for observed_name, expected_name in (
            ("bootstrap_epoch_id", "bootstrap_epoch_id"),
            ("started_at", "started_at"),
            ("deadline", "deadline"),
            ("receipt_fingerprint", "authorization_fingerprint"),
            ("authorization_receipt_sha256", "authorization_receipt_sha256"),
            ("active_release_binding_sha256", "active_release_binding_sha256"),
            ("candidate_env_sha256", "candidate_env_sha256"),
            ("release_bom_sha256", "release_bom_sha256"),
            ("release_approval_id", "release_id"),
            ("approval_evidence_sha256", "approval_evidence_sha256"),
        )
    ):
        raise EvidenceError("bootstrap_capacity_outbox_health_binding_mismatch")


def _check_delivery_service_health(
    service_configs: Mapping[str, Any],
    service_processes: Mapping[str, Any],
    service_dependencies: Mapping[str, Any],
    *,
    now: datetime,
    process_verifier: Any = None,
    loaded_runtime_verifier: Any = None,
) -> dict[str, Any]:
    requirements = (
        (
            "kafka_consumer_health",
            "local.pnc.rca-kafka-consumer",
            "pnc_rca_kafka_consumer_health_v2",
            "heartbeat_at",
            "kafka_consumer",
        ),
        (
            "outbox_dispatcher_health",
            "local.pnc.rca-outbox-dispatcher",
            "pnc_rca_outbox_dispatcher_health_v2",
            "heartbeat_at",
            "outbox_dispatcher",
        ),
        (
            "delivery_collector_health",
            "local.pnc.rca-delivery-collector",
            "pnc_rca_delivery_collector_health_v2",
            "updated_at",
            "delivery_collector",
        ),
        (
            "delivery_dispatcher_health",
            "local.pnc.rca-delivery-dispatcher",
            "pnc_rca_delivery_dispatcher_health_v2",
            "updated_at",
            "delivery_dispatcher",
        ),
    )
    summaries: dict[str, Any] = {}
    verifier = process_verifier or _verify_delivery_service_process
    loaded_verifier = (
        loaded_runtime_verifier or _verify_resident_loaded_runtime_projection
    )
    for artifact, label, schema, timestamp_field, service_kind in requirements:
        config = _mapping(service_configs.get(label), f"{artifact}.config")
        candidate = _mapping(
            service_processes.get(label), f"{artifact}.candidate_process"
        )
        if candidate.get("service_label") != label:
            raise EvidenceError(f"{artifact}_candidate_process_invalid")
        _required_text(candidate.get("plist_path"), f"{artifact}.candidate.plist_path")
        _sha256_digest(
            candidate.get("plist_sha256"), f"{artifact}.candidate.plist_sha256"
        )
        runtime_file_hashes = _mapping(
            candidate.get("runtime_file_sha256"),
            f"{artifact}.candidate.runtime_file_sha256",
        )
        if set(runtime_file_hashes) != set(RCA_RUNTIME_RELATIVE_FILES):
            raise EvidenceError(f"{artifact}_candidate_runtime_files_invalid")
        normalized_runtime_file_hashes = {
            relative: _sha256_digest(
                runtime_file_hashes.get(relative),
                f"{artifact}.candidate.runtime_file_sha256.{relative}",
            )
            for relative in RCA_RUNTIME_RELATIVE_FILES
        }
        if _sha256_json(normalized_runtime_file_hashes) != candidate.get(
            "runtime_files_sha256"
        ):
            raise EvidenceError(f"{artifact}_candidate_runtime_files_invalid")
        candidate_loaded_runtime = _mapping(
            candidate.get("loaded_runtime"),
            f"{artifact}.candidate.loaded_runtime",
        )
        candidate_loaded_runtime_sha256 = _sha256_digest(
            candidate.get("loaded_runtime_sha256"),
            f"{artifact}.candidate.loaded_runtime_sha256",
        )
        interpreter = Path(
            _required_text(
                candidate.get("interpreter"),
                f"{artifact}.candidate.interpreter",
            )
        )
        loaded_runtime, loaded_runtime_sha256 = loaded_verifier(
            candidate_loaded_runtime,
            virtual_env=interpreter.parent.parent,
            expected_sys_executable=interpreter,
            expected_process_executable=_required_text(
                candidate.get("runtime_executable"),
                f"{artifact}.candidate.runtime_executable",
            ),
            expected_dependencies=RCA_LOADED_DEPENDENCIES_BY_SERVICE[label],
            artifact=artifact,
        )
        if (
            candidate_loaded_runtime != loaded_runtime
            or candidate_loaded_runtime_sha256 != loaded_runtime_sha256
        ):
            raise EvidenceError(f"{artifact}_candidate_loaded_runtime_mismatch")
        body = _load_service_health(config.get("health_path"), artifact=artifact)
        activation_retry_evidence: dict[str, Any] = {}
        readiness_evidence: dict[str, Any] = {}
        _require_schema(body, schema, artifact)
        observed_at = _timestamp(
            body.get(timestamp_field), f"{artifact}.{timestamp_field}"
        )
        age_seconds = (now.astimezone(timezone.utc) - observed_at).total_seconds()
        effective_max_age = DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS
        if service_kind.startswith("delivery_"):
            max_age = _exact_int(
                config.get("health_max_age_seconds"),
                f"{artifact}.max_age_seconds",
                minimum=1,
            )
            effective_max_age = min(max_age, effective_max_age)
        if age_seconds < -MAX_HEALTH_FUTURE_SKEW_SECONDS:
            raise EvidenceError(f"{artifact}_from_future")
        if age_seconds > effective_max_age:
            raise EvidenceError(f"{artifact}_stale")
        if body.get("healthy") is not True:
            raise EvidenceError(f"{artifact}_unhealthy")
        if (
            service_kind in {"kafka_consumer", "outbox_dispatcher"}
            and body.get("ok") is not True
        ):
            raise EvidenceError(f"{artifact}_unhealthy")
        identity = _mapping(
            body.get("runtime_identity"), f"{artifact}.runtime_identity"
        )
        identity_fields = {
            "service_label",
            "pid",
            "process_create_time",
            "boot_time",
            "executable",
            "script",
            "cwd",
            "script_sha256",
            "runtime_files_sha256",
            "public_config_sha256",
            "loaded_runtime_sha256",
        }
        if set(identity) != identity_fields:
            raise EvidenceError(f"{artifact}_runtime_identity_invalid")
        expected_identity = {
            "service_label": label,
            "executable": _required_text(
                candidate.get("runtime_executable"),
                f"{artifact}.candidate.runtime_executable",
            ),
            "script": _required_text(
                candidate.get("script"), f"{artifact}.candidate.script"
            ),
            "cwd": _required_text(
                candidate.get("working_directory"),
                f"{artifact}.candidate.working_directory",
            ),
            "script_sha256": _sha256_digest(
                candidate.get("script_sha256"),
                f"{artifact}.candidate.script_sha256",
            ),
            "runtime_files_sha256": _sha256_digest(
                candidate.get("runtime_files_sha256"),
                f"{artifact}.candidate.runtime_files_sha256",
            ),
            "public_config_sha256": _sha256_json(config),
            "loaded_runtime_sha256": _sha256_digest(
                candidate.get("loaded_runtime_sha256"),
                f"{artifact}.candidate.loaded_runtime_sha256",
            ),
        }
        for field, expected in expected_identity.items():
            if identity.get(field) != expected:
                raise EvidenceError(f"{artifact}_runtime_identity_mismatch")
        _exact_int(identity.get("pid"), f"{artifact}.runtime_identity.pid", minimum=1)
        _number(
            identity.get("process_create_time"),
            f"{artifact}.runtime_identity.process_create_time",
            minimum=1,
        )
        _number(
            identity.get("boot_time"),
            f"{artifact}.runtime_identity.boot_time",
            minimum=1,
        )
        if service_kind == "kafka_consumer":
            if body.get("enabled") is not True or str(body.get("state") or "") not in {
                "starting",
                "recovered_pending",
                "idle",
                "running",
                "activation_frozen",
                "activation_resumed",
            }:
                raise EvidenceError(f"{artifact}_disabled_or_inactive")
            body_config = _mapping(body.get("config"), f"{artifact}.config")
            if _sha256_json(body_config) != _sha256_json(config):
                raise EvidenceError(f"{artifact}_config_mismatch")
            assignment = _mapping(body.get("assignment"), f"{artifact}.assignment")
            if (
                not assignment.get("assigned_partitions")
                or assignment.get("callback_errors") != 0
            ):
                raise EvidenceError(f"{artifact}_assignment_not_ready")
            if config.get("activation_required") is True:
                stats = _mapping(body.get("stats"), f"{artifact}.stats")
                activation_deferred = _exact_int(
                    stats.get("activation_deferred"),
                    f"{artifact}.stats.activation_deferred",
                    minimum=0,
                )
                activation_resumed = _exact_int(
                    stats.get("activation_resumed"),
                    f"{artifact}.stats.activation_resumed",
                    minimum=0,
                )
                blocked_partitions = _exact_int(
                    stats.get("blocked_partitions"),
                    f"{artifact}.stats.blocked_partitions",
                    minimum=0,
                )
                if (
                    body.get("activation_required") is not True
                    or body.get("mode") != "outbox_pending"
                    or blocked_partitions != 0
                    or activation_resumed > activation_deferred
                ):
                    raise EvidenceError(
                        f"{artifact}_activation_retry_contract_invalid"
                    )
                activation_retry_evidence = {
                    "deferred": activation_deferred,
                    "resumed": activation_resumed,
                    "blocked_partitions": blocked_partitions,
                    "retry_without_restart": True,
                }
        elif service_kind == "outbox_dispatcher":
            if body.get("enabled") is not True or str(body.get("state") or "") in {
                "",
                "disabled",
                "error",
                "circuit_open",
                "downstream_backpressure",
                "downstream_error",
                "lease_lost",
            }:
                raise EvidenceError(f"{artifact}_disabled_or_inactive")
            body_config = _mapping(body.get("config"), f"{artifact}.config")
            if _sha256_json(body_config) != _sha256_json(config):
                raise EvidenceError(f"{artifact}_config_mismatch")
            readiness_observed_at = _timestamp(
                body.get("readiness_observed_at"),
                f"{artifact}.readiness_observed_at",
            )
            readiness_age = (
                now.astimezone(timezone.utc) - readiness_observed_at
            ).total_seconds()
            if readiness_age < -MAX_HEALTH_FUTURE_SKEW_SECONDS:
                raise EvidenceError(f"{artifact}_readiness_from_future")
            if readiness_age > DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS:
                raise EvidenceError(f"{artifact}_readiness_stale")
            readiness = _mapping(
                body.get("readiness"), f"{artifact}.readiness"
            )
            liveness = _mapping(body.get("liveness"), f"{artifact}.liveness")
            if (
                set(readiness)
                != {"state", "healthy", "ready_for_dispatch", "observed_at"}
                or readiness.get("state") != body.get("state")
                or readiness.get("healthy") is not True
                or readiness.get("ready_for_dispatch") is not True
                or readiness.get("observed_at")
                != body.get("readiness_observed_at")
                or set(liveness)
                != {"state", "heartbeat_at", "readiness_observed_at"}
                or liveness.get("state")
                not in {"reporting", "processing", "waiting"}
                or liveness.get("heartbeat_at") != body.get("heartbeat_at")
                or liveness.get("readiness_observed_at")
                != body.get("readiness_observed_at")
            ):
                raise EvidenceError(f"{artifact}_readiness_contract_invalid")
            readiness_evidence = {
                "observed_at": readiness_observed_at.isoformat(),
                "snapshot_sha256": _sha256_json(readiness),
                "liveness_state": str(liveness["state"]),
            }
            capacity_admission_evidence = (
                _check_outbox_capacity_admission_health(
                    body.get("capacity_admission"),
                    config=config,
                    now=now,
                    artifact=artifact,
                )
            )
            boundary = _mapping(
                body.get("delivery_backpressure"),
                f"{artifact}.delivery_backpressure",
            )
            backpressure_evidence = _check_outbox_delivery_backpressure_health(
                boundary,
                config=config,
                now=now,
                artifact=artifact,
            )
        elif service_kind == "delivery_collector":
            if body.get("enabled") is not True:
                raise EvidenceError(f"{artifact}_disabled")
            expected_dependency = EXPECTED_REMOTE_CSS_RUNTIME_DEPENDENCY
            candidate_dependencies = _mapping(
                service_dependencies.get(label),
                f"{artifact}.candidate_dependencies",
            )
            if candidate_dependencies != {"remote_css_parser": expected_dependency}:
                raise EvidenceError(f"{artifact}_dependency_mismatch")
            dependencies = _mapping(
                body.get("dependencies"), f"{artifact}.dependencies"
            )
            if set(dependencies) != {"remote_css_parser"}:
                raise EvidenceError(f"{artifact}_dependency_receipt_invalid")
            parser_receipt = _mapping(
                dependencies.get("remote_css_parser"),
                f"{artifact}.dependencies.remote_css_parser",
            )
            if {
                key: value
                for key, value in parser_receipt.items()
                if key != "observed_at"
            } != expected_dependency or set(parser_receipt) != {
                *expected_dependency,
                "observed_at",
            }:
                raise EvidenceError(f"{artifact}_dependency_receipt_invalid")
            dependency_observed_at = _timestamp(
                parser_receipt.get("observed_at"),
                f"{artifact}.dependencies.remote_css_parser.observed_at",
            )
            dependency_age = (
                now.astimezone(timezone.utc) - dependency_observed_at
            ).total_seconds()
            if dependency_age < -30:
                raise EvidenceError(f"{artifact}_dependency_receipt_from_future")
            if dependency_age > DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS:
                raise EvidenceError(f"{artifact}_dependency_receipt_stale")
        elif service_kind == "delivery_dispatcher":
            body_config = _mapping(body.get("config"), f"{artifact}.config")
            if body_config.get("enabled") is not True:
                raise EvidenceError(f"{artifact}_disabled")
            candidate_dependencies = _mapping(
                service_dependencies.get(label),
                f"{artifact}.candidate_dependencies",
            )
            if set(candidate_dependencies) != {"feishu_outbound"}:
                raise EvidenceError(f"{artifact}_dependency_mismatch")
            feishu_outbound = _mapping(
                candidate_dependencies.get("feishu_outbound"),
                f"{artifact}.candidate_dependencies.feishu_outbound",
            )
            feishu_apis = _mapping(
                feishu_outbound.get("apis"),
                f"{artifact}.candidate_dependencies.feishu_outbound.apis",
            )
            if (
                set(feishu_outbound)
                != {
                    "schema_version",
                    "distribution",
                    "version",
                    "python_executable",
                    "dependency_install_attempted",
                    "client_constructed",
                    "apis",
                }
                or feishu_outbound.get("schema_version")
                != FEISHU_OUTBOUND_RUNTIME_SCHEMA_VERSION
                or feishu_outbound.get("distribution") != "lark-oapi"
                or feishu_outbound.get("version")
                != EXPECTED_FEISHU_OUTBOUND_DEPENDENCY_VERSIONS["lark-oapi"]
                or feishu_outbound.get("python_executable")
                != candidate.get("runtime_executable")
                or feishu_outbound.get("dependency_install_attempted") is not False
                or feishu_outbound.get("client_constructed") is not True
                or set(feishu_apis) != EXPECTED_FEISHU_OUTBOUND_APIS
                or any(value is not True for value in feishu_apis.values())
            ):
                raise EvidenceError(f"{artifact}_dependency_mismatch")
        else:
            raise EvidenceError(f"{artifact}_service_kind_invalid")
        store = _mapping(body.get("store"), f"{artifact}.store")
        if store.get("ok") is not True or store.get("db_path") != config.get(
            "control_db_path"
        ):
            raise EvidenceError(f"{artifact}_business_not_ready")
        expected_store_schema = (
            DELIVERY_STORE_SCHEMA_VERSION
            if service_kind.startswith("delivery_")
            else CONTROL_STORE_SCHEMA_VERSION
        )
        if store.get("schema_version") != expected_store_schema:
            raise EvidenceError(f"{artifact}_store_schema_mismatch")
        if service_kind.startswith("delivery_") and (
            store.get("process_healthy") is not True
            or store.get("business_ready") is not True
        ):
            raise EvidenceError(f"{artifact}_business_not_ready")
        if service_kind.startswith("delivery_"):
            outcome_slo = _mapping(
                store.get("delivery_outcome_slo"),
                f"{artifact}.store.delivery_outcome_slo",
            )
            try:
                outcome_slo_healthy = validate_delivery_outcome_slo(outcome_slo)
            except (TypeError, ValueError) as exc:
                raise EvidenceError(
                    f"{artifact}_delivery_outcome_slo_contract_invalid"
                ) from exc
            if not outcome_slo_healthy:
                raise EvidenceError(f"{artifact}_delivery_outcome_slo_failed")
            delivery_circuits = _mapping(
                store.get("delivery_dispatcher_circuits"),
                f"{artifact}.store.delivery_dispatcher_circuits",
            )
            if set(delivery_circuits) != {
                "feishu_issue_comment",
                "feishu_thread_reply",
            } or any(
                not isinstance(value, Mapping) or value.get("state") != "closed"
                for value in delivery_circuits.values()
            ):
                raise EvidenceError(f"{artifact}_delivery_circuit_not_ready")
        process_evidence = verifier(identity, candidate, artifact=artifact)
        summaries[artifact] = {
            timestamp_field: observed_at.isoformat(),
            "state": str(body.get("state") or ""),
            "runtime_identity_sha256": _sha256_json(identity),
            "loaded_runtime_sha256": loaded_runtime_sha256,
            "process": process_evidence,
        }
        if activation_retry_evidence:
            summaries[artifact]["activation_retry"] = activation_retry_evidence
        if readiness_evidence:
            summaries[artifact]["readiness"] = readiness_evidence
        if service_kind == "outbox_dispatcher":
            summaries[artifact]["delivery_backpressure"] = backpressure_evidence
            summaries[artifact]["capacity_admission"] = (
                capacity_admission_evidence
            )
    return summaries


def _sanitized_contract_result(result: Mapping[str, Any]) -> dict[str, Any]:
    sanitized = {
        key: result[key]
        for key in ("ok", "status", "error", "sha256", "host_sha256", "vm_sha256")
        if key in result
    }
    if "missing" in result:
        sanitized["missing_count"] = len(result.get("missing") or ())
    return sanitized


def evaluate_release_gate(
    *,
    consumer: ConsumerConfig,
    dispatcher: DispatcherConfig,
    settings: ReleaseGateSettings,
    cutover: CutoverConfig | None = None,
    now: datetime | None = None,
    build_provenance_verifier: BuildProvenanceVerifier | None = None,
    remote_reader_live_verifier: RemoteReaderLiveVerifier | None = None,
    activation_end_fence_verifier: Callable[..., Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    """Evaluate release artifacts; canary+ verifies live Git provenance."""
    current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    checks = _Checks()
    evidence_hashes: dict[str, str] = {}
    cutover_config = cutover or CutoverConfig(None, None, None)
    public_config = _public_config(consumer, dispatcher, cutover_config)
    config_sha256 = _sha256_json(public_config)
    gate_policy = {
        "evidence_max_age_seconds": settings.evidence_max_age_seconds,
        "shadow_soak_min_seconds": settings.shadow_soak_min_seconds,
        "min_storage_horizon_days": settings.min_storage_horizon_days,
        "target_cases_per_day": settings.target_cases_per_day,
        "min_capacity_horizon_days": settings.min_capacity_horizon_days,
    }
    warnings: list[str] = []
    runtime_launchd_config_sha256 = ""
    runtime_detail: dict[str, Any] = {}
    verified_host_commit = ""
    verified_vm_commit = ""
    verified_vm_tree = ""
    verified_vm_worker_commit = ""
    verified_vm_service_entrypoint_sha256 = ""
    verified_vm_worker_entrypoint_sha256 = ""
    verified_canary_collector_sha256 = ""
    verified_build_detail: dict[str, Any] = {}
    bootstrap_authorization_detail: dict[str, Any] = {}
    service_configs: dict[str, Any] = {}
    service_processes: dict[str, Any] = {}
    service_dependencies: dict[str, Any] = {}
    health_detail: dict[str, Any] = {}
    activation_detail: dict[str, Any] = {}
    migration_detail: dict[str, Any] = {}
    workload_manifest: dict[str, Any] = {}
    bootstrap_runtime_detail: dict[str, Any] = {}
    activation_candidate_detail: dict[str, Any] = {}
    committed_canary_evidence: dict[str, dict[str, Any]] = {}
    committed_canary_errors: dict[str, EvidenceError] = {}
    committed_roles: tuple[str, ...] = ()
    if settings.mode in PRODUCTION_MODES:
        committed_roles = (
            "primary",
            "manual_success",
            "manual_terminal_failure",
        )
    elif (
        settings.mode in {*CANARY_MODES, "preproduction"}
        and cutover_config.manual_intake_enabled is True
        and (
            settings.evidence_dir
            / COMMITTED_CANARY_EVIDENCE_SPECS[
                "manual_terminal_failure"
            ].manifest_filename
        ).is_file()
    ):
        committed_roles = ("manual_terminal_failure",)
    for evidence_role in committed_roles:
        try:
            committed_canary_evidence[evidence_role] = (
                _load_committed_canary_evidence(
                    settings.evidence_dir,
                    evidence_role,
                    evidence_hashes,
                )
            )
        except EvidenceError as exc:
            committed_canary_errors[evidence_role] = exc

    consumer_errors = _check_consumer_config(
        consumer,
        mode=settings.mode,
        expected_topic=settings.expected_topic,
        expected_rule_version=settings.expected_rule_version,
    )
    if consumer_errors:
        checks.fail(
            "consumer_config",
            consumer_errors[0],
            {"errors": consumer_errors},
        )
    else:
        checks.pass_("consumer_config")

    dispatcher_errors = _check_dispatcher_config(
        dispatcher,
        mode=settings.mode,
        target_cases_per_day=settings.target_cases_per_day,
    )
    if dispatcher_errors:
        checks.fail(
            "dispatcher_config",
            dispatcher_errors[0],
            {"errors": dispatcher_errors},
        )
    else:
        checks.pass_("dispatcher_config")

    manual_terminal_detail: dict[str, Any] = {}
    try:
        if "manual_terminal_failure" in committed_canary_errors:
            try:
                _check_manual_terminal_failure_delivery(
                    mode=settings.mode,
                    cutover=cutover_config,
                    consumer=consumer,
                    dispatcher=dispatcher,
                    settings=settings,
                    committed_evidence=None,
                    now=current,
                )
            except EvidenceError as config_error:
                if (
                    config_error.code
                    != "manual_terminal_failure_topic_receipt_required"
                ):
                    raise
            raise committed_canary_errors["manual_terminal_failure"]
        manual_terminal_detail = _check_manual_terminal_failure_delivery(
            mode=settings.mode,
            cutover=cutover_config,
            consumer=consumer,
            dispatcher=dispatcher,
            settings=settings,
            committed_evidence=committed_canary_evidence.get(
                "manual_terminal_failure"
            ),
            now=current,
        )
        manual_terminal_public = dict(manual_terminal_detail)
        manual_terminal_public.pop("observed_trigger_source", None)
        checks.pass_("manual_terminal_failure_delivery", manual_terminal_public)
    except EvidenceError as exc:
        checks.fail("manual_terminal_failure_delivery", exc.code)

    try:
        runtime_detail = check_candidate_runtime_dependencies(settings.host_repo_root)
        try:
            runtime_launchd_config_sha256 = _sha256_digest(
                runtime_detail.get("launchd_config_sha256"),
                "runtime_dependencies.launchd_config_sha256",
            )
        except EvidenceError as exc:
            raise EvidenceError(
                "runtime_candidate_launchd_fingerprint_invalid"
            ) from exc
        checks.pass_(
            "runtime_dependencies",
            runtime_detail,
        )
    except EvidenceError as exc:
        checks.fail("runtime_dependencies", exc.code)

    try:
        candidate_config_detail = _check_candidate_service_configs(
            runtime_detail,
            consumer=consumer,
            dispatcher=dispatcher,
            cutover=cutover_config,
            mode=settings.mode,
        )
        checks.pass_("candidate_service_configs", candidate_config_detail)
    except EvidenceError as exc:
        checks.fail("candidate_service_configs", exc.code)

    if settings.mode == "preauthorization":
        try:
            activation_detail = _check_activation_epoch_absent(
                control_db_path=dispatcher.control_db_path,
            )
            checks.pass_("activation_epoch", activation_detail)
        except EvidenceError as exc:
            checks.fail("activation_epoch", exc.code)
    elif settings.mode in {"preproduction", *CANARY_MODES, *PRODUCTION_MODES}:
        try:
            activation_detail = _check_activation_epoch(
                control_db_path=dispatcher.control_db_path,
                mode=settings.mode,
                expected_config_sha256=config_sha256,
            )
            checks.pass_("activation_epoch", activation_detail)
        except EvidenceError as exc:
            checks.fail("activation_epoch", exc.code)

    if settings.mode in {*CANARY_MODES, *PRODUCTION_MODES}:
        try:
            service_configs = dict(_mapping(
                runtime_detail.get("service_configs"),
                "runtime_dependencies.service_configs",
            ))
            service_processes = dict(_mapping(
                runtime_detail.get("service_processes"),
                "runtime_dependencies.service_processes",
            ))
            service_dependencies = dict(_mapping(
                runtime_detail.get("service_dependencies"),
                "runtime_dependencies.service_dependencies",
            ))
            health_detail = _check_delivery_service_health(
                service_configs,
                service_processes,
                service_dependencies,
                now=current,
            )
            checks.pass_("delivery_service_health", health_detail)
        except EvidenceError as exc:
            checks.fail("delivery_service_health", exc.code)

    if settings.mode in PRODUCTION_MODES:
        try:
            if not activation_detail:
                raise EvidenceError(
                    "activation_production_candidate_epoch_unverified"
                )
            consumer_health = _mapping(
                health_detail.get("kafka_consumer_health"),
                "activation_production_candidate.kafka_consumer_health",
            )
            candidate = _load_evidence(
                settings.evidence_dir,
                "activation_production_candidate.json",
                evidence_hashes,
            )
            consumer_runtime_sha256 = _sha256_digest(
                consumer_health.get("runtime_identity_sha256"),
                "activation_production_candidate.consumer_runtime_identity_sha256",
            )
            live_collector = (
                activation_end_fence_verifier
                or collect_live_activation_end_fence
            )(
                consumer=consumer,
                partition_start_fence=_mapping(
                    activation_detail.get("partition_start_fence"),
                    "activation_production_candidate.partition_start_fence",
                ),
                epoch_id=str(activation_detail.get("epoch_id") or ""),
                consumer_runtime_identity_sha256=consumer_runtime_sha256,
                host_repo_root=settings.host_repo_root,
                now=current,
            )
            activation_candidate_detail = (
                _check_activation_production_candidate(
                    candidate,
                    activation=activation_detail,
                    consumer=consumer,
                    expected_config_sha256=config_sha256,
                    expected_consumer_runtime_identity_sha256=(
                        consumer_runtime_sha256
                    ),
                    expected_host_repo_root=settings.host_repo_root,
                    live_collector=live_collector,
                    now=current,
                    max_age_seconds=settings.evidence_max_age_seconds,
                )
            )
            checks.pass_(
                "activation_production_candidate",
                activation_candidate_detail,
            )
        except EvidenceError as exc:
            checks.fail("activation_production_candidate", exc.code)

    try:
        contract_result = check_contract_drift(
            settings.host_contract_path,
            settings.vm_contract_path,
        )
    except (OSError, ValueError):
        contract_result = {
            "ok": False,
            "status": "contract_unverified",
            "error": "contract_unreadable",
        }
    contract_public = _sanitized_contract_result(contract_result)
    if contract_result.get("ok") is True:
        checks.pass_("contract_drift", contract_public)
    else:
        checks.fail(
            "contract_drift",
            str(contract_result.get("error") or contract_result.get("status")),
            contract_public,
        )

    broker_partitions: list[int] = []
    try:
        broker = _load_evidence(
            settings.evidence_dir, "broker_metadata.json", evidence_hashes
        )
        broker_partitions, detail = _check_broker_metadata(
            broker,
            consumer=consumer,
            kafka_env_file=settings.kafka_env_file,
            host_repo_root=settings.host_repo_root,
            expected_topic=settings.expected_topic,
            now=current,
            max_age_seconds=settings.evidence_max_age_seconds,
        )
        checks.pass_("broker_metadata", detail)
    except EvidenceError as exc:
        checks.fail("broker_metadata", exc.code)

    try:
        t0 = _load_evidence(settings.evidence_dir, "t0_offsets.json", evidence_hashes)
        if not broker_partitions:
            raise EvidenceError("t0_offsets_broker_partitions_unverified")
        detail = _check_t0_offsets(
            t0,
            consumer=consumer,
            expected_topic=settings.expected_topic,
            broker_partitions=broker_partitions,
            now=current,
            max_age_seconds=settings.evidence_max_age_seconds,
        )
        checks.pass_("t0_offsets", detail)
    except EvidenceError as exc:
        checks.fail("t0_offsets", exc.code)

    try:
        fixtures = _load_evidence(
            settings.evidence_dir, "workflow_fixtures.json", evidence_hashes
        )
        detail = _check_workflow_fixtures(
            fixtures,
            consumer=consumer,
            expected_topic=settings.expected_topic,
            expected_rule_version=settings.expected_rule_version,
            now=current,
            max_age_seconds=settings.evidence_max_age_seconds,
        )
        checks.pass_("workflow_fixtures", detail)
    except EvidenceError as exc:
        checks.fail("workflow_fixtures", exc.code)

    build_manifest_path = settings.evidence_dir / "build_manifest.json"
    build_manifest_required = settings.mode in {
        "preauthorization",
        "preproduction",
        *CANARY_MODES,
        *PRODUCTION_MODES,
    }
    if build_manifest_required or build_manifest_path.is_file():
        try:
            build_manifest = _load_evidence(
                settings.evidence_dir, "build_manifest.json", evidence_hashes
            )
            detail = _check_build_manifest(
                build_manifest,
                settings=settings,
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
                expected_runtime_config_sha256=config_sha256,
                expected_launchd_config_sha256=runtime_launchd_config_sha256,
                provenance_verifier=(
                    build_provenance_verifier or verify_live_build_provenance
                ),
            )
            verified_host_commit = str(detail.get("host_commit") or "")
            verified_vm_commit = str(detail.get("vm_commit") or "")
            verified_vm_tree = str(detail.get("vm_tree") or "")
            verified_vm_worker_commit = str(detail.get("vm_worker_commit") or "")
            verified_vm_service_entrypoint_sha256 = str(
                detail.get("vm_service_entrypoint_sha256") or ""
            )
            verified_vm_worker_entrypoint_sha256 = str(
                detail.get("vm_worker_entrypoint_sha256") or ""
            )
            verified_canary_collector_sha256 = str(
                detail.get("canary_collector_sha256") or ""
            )
            verified_build_detail = dict(detail)
            checks.pass_("build_manifest", detail)
        except EvidenceError as exc:
            checks.fail("build_manifest", exc.code)
    else:
        warnings.append("build_manifest_missing")

    if settings.mode in {
        "preauthorization",
        "preproduction",
        *CANARY_MODES,
        *PRODUCTION_MODES,
    }:
        try:
            if not verified_build_detail:
                raise EvidenceError("kafka_recent_replay_build_unverified")
            if not broker_partitions:
                raise EvidenceError("kafka_recent_replay_broker_unverified")
            critical_files = _mapping(
                verified_build_detail.get("critical_file_sha256"),
                "kafka_recent_replay.build.critical_file_sha256",
            )
            recent_replay = _load_canonical_owner_only_evidence(
                settings.evidence_dir,
                KAFKA_RECENT_REPLAY_FILENAME,
                artifact="kafka_recent_replay",
                evidence_hashes=evidence_hashes,
            )
            detail = _check_kafka_recent_replay(
                recent_replay,
                consumer=consumer,
                kafka_env_file=settings.kafka_env_file,
                expected_partitions=broker_partitions,
                expected_host_commit=verified_host_commit,
                expected_module_sha256=_sha256_digest(
                    critical_files.get(KAFKA_RECENT_REPLAY_MODULE),
                    "kafka_recent_replay.module_sha256",
                ),
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
            )
            checks.pass_("kafka_recent_replay", detail)
        except EvidenceError as exc:
            checks.fail("kafka_recent_replay", exc.code)

    if settings.mode in BOOTSTRAP_CAPACITY_MODES:
        try:
            if not verified_build_detail:
                raise EvidenceError(
                    "bootstrap_capacity_build_manifest_unverified"
                )
            bootstrap_authorization_detail = (
                _check_bootstrap_capacity_authorization(
                    dispatcher=dispatcher,
                    evidence_dir=settings.evidence_dir,
                    evidence_hashes=evidence_hashes,
                    expected_release_bom_sha256=_sha256_digest(
                        verified_build_detail.get("release_bom_sha256"),
                        "bootstrap_capacity.release_bom_sha256",
                    ),
                    now=current,
                    require_producer_window=(
                        settings.mode == "production_bootstrap"
                    ),
                )
            )
            if settings.mode in {*CANARY_MODES, *PRODUCTION_MODES}:
                if not health_detail:
                    raise EvidenceError(
                        "bootstrap_capacity_outbox_health_unverified"
                    )
                _bind_outbox_bootstrap_capacity_health(
                    health_detail,
                    bootstrap_authorization_detail,
                )
            checks.pass_(
                "bootstrap_capacity_authorization",
                bootstrap_authorization_detail,
            )
        except EvidenceError as exc:
            checks.fail("bootstrap_capacity_authorization", exc.code)

    if settings.mode in {"preproduction", *PRODUCTION_MODES}:
        try:
            if not verified_build_detail or not activation_detail:
                raise EvidenceError("auxiliary_runtime_prerequisite_unverified")
            auxiliary_runtime_detail = _check_auxiliary_runtime_health(
                build_detail=verified_build_detail,
                activation=activation_detail,
                now=current,
            )
            checks.pass_("auxiliary_runtime_health", auxiliary_runtime_detail)
        except EvidenceError as exc:
            checks.fail("auxiliary_runtime_health", exc.code)

    canary_event_uid = ""
    canary_request_sha256 = ""
    canary_admission: dict[str, Any] = {}
    canary_requested_scope: dict[str, Any] = {}
    canary_slot_plan: dict[str, Any] = {}
    canary_detail: dict[str, Any] = {}
    remote_reader_fingerprint = ""
    remote_reader_health_detail: dict[str, Any] = {}
    remote_reader_health_body: dict[str, Any] = {}
    if settings.mode in {
        "preauthorization",
        "preproduction",
        *CANARY_MODES,
        *PRODUCTION_MODES,
    }:
        try:
            migration_receipt = _load_evidence(
                settings.evidence_dir,
                "store_migration_receipt.json",
                evidence_hashes,
            )
            materialization_receipt = None
            materialization_raw_sha256 = None
            if migration_receipt.get("migration_state") == "fresh_install":
                materialization_receipt = _load_evidence(
                    settings.evidence_dir,
                    "fresh_install_materialization_receipt.json",
                    evidence_hashes,
                )
                materialization_raw_sha256 = evidence_hashes[
                    "fresh_install_materialization_receipt.json"
                ]
            capacity_initialization_receipt = _load_evidence(
                settings.evidence_dir,
                "capacity_transition_initialization_receipt.json",
                evidence_hashes,
            )
            detail = _check_store_migration_receipt(
                migration_receipt,
                dispatcher=dispatcher,
                settings=settings,
                expected_host_commit=verified_host_commit,
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
                release_mode=settings.mode,
                migration_raw_sha256=evidence_hashes[
                    "store_migration_receipt.json"
                ],
                materialization_receipt=materialization_receipt,
                materialization_raw_sha256=materialization_raw_sha256,
                capacity_initialization_receipt=(
                    capacity_initialization_receipt
                ),
                capacity_initialization_raw_sha256=evidence_hashes[
                    "capacity_transition_initialization_receipt.json"
                ],
                activation=(
                    None
                    if settings.mode == "preauthorization"
                    else activation_detail
                ),
                expected_config_sha256=config_sha256,
            )
            migration_detail = dict(detail)
            checks.pass_("store_migration", detail)
        except EvidenceError as exc:
            checks.fail("store_migration", exc.code)

        try:
            reader_health = _load_evidence(
                settings.evidence_dir, "remote_reader_health.json", evidence_hashes
            )
            remote_reader_health_body = dict(reader_health)
            detail = _check_remote_reader_health(
                reader_health,
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
                production=settings.mode in PRODUCTION_MODES,
            )
            remote_reader_health_detail = detail
            remote_reader_fingerprint = str(detail["reader_fingerprint"])
            checks.pass_("remote_reader_health", detail)
        except EvidenceError as exc:
            checks.fail("remote_reader_health", exc.code)

        try:
            if not verified_vm_commit:
                raise EvidenceError("remote_reader_live_probe_build_unverified")
            if not remote_reader_health_detail:
                raise EvidenceError("remote_reader_live_probe_health_unverified")
            live_probe = (remote_reader_live_verifier or verify_live_remote_reader)(
                settings
            )
            detail = _check_remote_reader_live_probe(
                live_probe,
                settings=settings,
                expected_vm_commit=verified_vm_commit,
                health_detail=remote_reader_health_detail,
            )
            checks.pass_("remote_reader_live_probe", detail)
        except EvidenceError as exc:
            checks.fail("remote_reader_live_probe", exc.code)
        except Exception:
            checks.fail(
                "remote_reader_live_probe",
                "remote_reader_live_probe_unavailable",
            )

        try:
            cutover_plan = _load_evidence(
                settings.evidence_dir, "cutover_plan.json", evidence_hashes
            )
            detail = _check_cutover_plan(
                cutover_plan,
                cutover=cutover_config,
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
            )
            checks.pass_("cutover_plan", detail)
        except EvidenceError as exc:
            checks.fail("cutover_plan", exc.code)

        if settings.mode in POST_LAUNCH_OBSERVATION_MODES:
            checks.pass_(
                "shadow_soak",
                {
                    "status": "deferred_to_post_launch",
                    "blocks_bootstrap_release": False,
                    "required_for_steady_capacity": True,
                },
            )
        else:
            try:
                soak = _load_evidence(
                    settings.evidence_dir, "shadow_soak.json", evidence_hashes
                )
                detail = _check_shadow_soak(
                    soak,
                    now=current,
                    max_age_seconds=settings.evidence_max_age_seconds,
                    minimum_duration_seconds=settings.shadow_soak_min_seconds,
                    minimum_storage_horizon_days=settings.min_storage_horizon_days,
                    expected_partitions=broker_partitions,
                    target_cases_per_day=settings.target_cases_per_day,
                    expected_build_manifest_sha256=evidence_hashes.get(
                        "build_manifest.json", ""
                    ),
                    expected_config_sha256=config_sha256,
                )
                checks.pass_("shadow_soak", detail)
            except EvidenceError as exc:
                checks.fail("shadow_soak", exc.code)

        try:
            plan = _load_evidence(
                settings.evidence_dir, "canary_plan.json", evidence_hashes
            )
            (
                canary_event_uid,
                canary_request_sha256,
                canary_admission,
                canary_requested_scope,
                canary_slot_plan,
                detail,
            ) = _check_canary_plan(
                plan,
                expected_topic=settings.expected_topic,
                expected_rule_version=settings.expected_rule_version,
                configured_t0=dict(consumer.initial_offsets),
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
            )
            checks.pass_("canary_plan", detail)
        except EvidenceError as exc:
            checks.fail("canary_plan", exc.code)

        if settings.mode in POST_LAUNCH_OBSERVATION_MODES:
            workload_manifest = {}
            checks.pass_(
                "remote_reader_workload_provenance",
                {
                    "status": "deferred_to_post_launch",
                    "blocks_bootstrap_release": False,
                    "balanced_case_target": 200,
                },
            )
        else:
            try:
                workload_manifest = _load_remote_reader_soak_manifest(
                    settings.evidence_dir,
                    evidence_hashes,
                )
                workload_provenance = _load_remote_reader_workload_provenance(
                    settings.evidence_dir,
                    evidence_hashes,
                )
                critical_files = _mapping(
                    verified_build_detail.get("critical_file_sha256"),
                    "remote_reader_workload.build.critical_file_sha256",
                )
                detail = _check_remote_reader_workload_provenance(
                    workload_provenance,
                    workload_manifest=workload_manifest,
                    evidence_hashes=evidence_hashes,
                    expected_host_commit=verified_host_commit,
                    expected_exporter_sha256=_sha256_digest(
                        critical_files.get(REMOTE_READER_WORKLOAD_EXPORT_MODULE),
                        "remote_reader_workload.exporter_module_sha256",
                    ),
                )
                checks.pass_("remote_reader_workload_provenance", detail)
            except EvidenceError as exc:
                workload_manifest = {}
                checks.fail("remote_reader_workload_provenance", exc.code)

        if settings.mode in POST_LAUNCH_OBSERVATION_MODES:
            checks.pass_(
                "remote_reader_soak",
                {
                    "status": "deferred_to_post_launch",
                    "blocks_bootstrap_release": False,
                    "required_for_steady_capacity": True,
                },
            )
        else:
            try:
                if not remote_reader_fingerprint:
                    raise EvidenceError("remote_reader_soak_health_unverified")
                if not canary_requested_scope:
                    raise EvidenceError("remote_reader_soak_scope_unverified")
                if not verified_vm_commit or not verified_vm_tree:
                    raise EvidenceError("remote_reader_soak_build_unverified")
                if not remote_reader_health_detail:
                    raise EvidenceError("remote_reader_soak_health_unverified")
                if not workload_manifest:
                    raise EvidenceError(
                        "remote_reader_soak_manifest_provenance_unverified"
                    )
                soak = _load_evidence(
                    settings.evidence_dir, "remote_reader_soak.json", evidence_hashes
                )
                detail = _check_remote_reader_soak(
                    soak,
                    workload_manifest_body=workload_manifest,
                    expected_reader_fingerprint=remote_reader_fingerprint,
                    expected_vm_commit=verified_vm_commit,
                    expected_vm_tree=verified_vm_tree,
                    expected_remote_reader_health_sha256=_sha256_digest(
                        evidence_hashes.get("remote_reader_health.json"),
                        "remote_reader_soak.remote_reader_health_sha256",
                    ),
                    remote_reader_health_detail=remote_reader_health_detail,
                    dispatcher=dispatcher,
                    target_cases_per_day=settings.target_cases_per_day,
                    now=current,
                    max_age_seconds=settings.evidence_max_age_seconds,
                )
                checks.pass_("remote_reader_soak", detail)
            except EvidenceError as exc:
                checks.fail("remote_reader_soak", exc.code)
    elif (
        cutover_config.legacy_auto_execution_disabled is not True
        or cutover_config.legacy_daily_quota != 0
        or cutover_config.legacy_governance_download_enabled is not False
    ):
        warnings.append("legacy_auto_execution_still_enabled")

    if settings.mode in {
        "preauthorization",
        "preproduction",
        *CANARY_MODES,
        *PRODUCTION_MODES,
    }:
        try:
            if not migration_detail:
                raise EvidenceError("activation_bootstrap_migration_unverified")
            previous_gateway_binding: Mapping[str, Any] | None = None
            if settings.mode == "preproduction":
                if settings.preauthorization_capsule_path is None:
                    raise EvidenceError(
                        "activation_preauthorization_capsule_required"
                    )
                prior = _read_activation_preauthorization_capsule_bundle(
                    settings.preauthorization_capsule_path,
                    control_db_path=dispatcher.control_db_path,
                    now=current,
                )
                previous_gateway_binding = _mapping(
                    prior.get("gateway_binding"),
                    "activation_preauthorization.gateway_binding",
                )
                prior_input = _mapping(
                    prior.get("normalized"),
                    "activation_preauthorization.normalized",
                )
                if any(
                    activation_detail.get(observed_field)
                    != prior_input.get(expected_field)
                    for observed_field, expected_field in (
                        (
                            "preauthorization_fingerprint",
                            "preauthorization_fingerprint",
                        ),
                        (
                            "preauthorization_gate_receipt_sha256",
                            "preauthorization_gate_receipt_sha256",
                        ),
                        (
                            "preauthorization_capsule_sha256",
                            "preauthorization_capsule_sha256",
                        ),
                        ("config_sha256", "config_sha256"),
                        (
                            "db_logical_identity_sha256",
                            "db_logical_identity_sha256",
                        ),
                        (
                            "partition_start_fence_sha256",
                            "partition_start_fence_sha256",
                        ),
                    )
                ):
                    raise EvidenceError(
                        "activation_preauthorization_epoch_binding_changed"
                    )
            elif settings.mode in {*CANARY_MODES, *PRODUCTION_MODES}:
                if settings.preproduction_capsule_path is None:
                    raise EvidenceError("activation_preproduction_capsule_required")
                prior = _read_activation_preproduction_capsule_bundle(
                    settings.preproduction_capsule_path,
                    control_db_path=dispatcher.control_db_path,
                    current_activation=activation_detail,
                    now=current,
                    allowed_current_states=frozenset({
                        str(activation_detail.get("state") or "")
                    }),
                )
                previous_gateway_binding = _mapping(
                    prior.get("gateway_binding"),
                    "activation_preproduction.gateway_binding",
                )
                frozen_transition = _mapping(
                    prior.get("normalized"),
                    "activation_preproduction.normalized",
                )
                frozen_slot_plan = dict(
                    _mapping(
                        frozen_transition.get("canary_slot_plan"),
                        "activation_preproduction.canary_slot_plan",
                    )
                )
                observed_slot_plan = canary_slot_plan
                canary_slot_plan = frozen_slot_plan
                if evidence_hashes.get("canary_plan.json") != _sha256_digest(
                    prior.get("canary_plan_raw_sha256"),
                    "activation_preproduction.canary_plan_raw_sha256",
                ):
                    raise EvidenceError(
                        "activation_canary_plan_raw_sha256_mismatch"
                    )
                if (
                    observed_slot_plan != frozen_slot_plan
                    or frozen_transition.get("canary_slot_plan_sha256")
                    != _sha256_json(frozen_slot_plan)
                ):
                    raise EvidenceError("activation_canary_plan_capsule_mismatch")
            expected_start_fence = {
                consumer.topic: {
                    str(partition): offset
                    for partition, offset in sorted(
                        dict(consumer.initial_offsets).items()
                    )
                }
            }
            if settings.mode != "preauthorization" and (
                activation_detail.get("partition_start_fence")
                != expected_start_fence
            ):
                raise EvidenceError("activation_partition_start_fence_mismatch")
            slot_plan_binding: dict[str, Any] | None = None
            if settings.mode in {*CANARY_MODES, *PRODUCTION_MODES}:
                if not canary_slot_plan:
                    raise EvidenceError("activation_canary_plan_unverified")
                slot_plan_binding = _check_activation_slot_plan(
                    activation_detail,
                    canary_slot_plan,
                    require_consumed=settings.mode in PRODUCTION_MODES,
                )
            bootstrap_runtime_detail = _check_activation_bootstrap_runtime(
                mode=settings.mode,
                control_db_path=dispatcher.control_db_path,
                repo_root=settings.host_repo_root,
                cutover=cutover_config,
                consumer=consumer,
                activation=activation_detail,
                previous_gateway_binding=previous_gateway_binding,
            )
            if slot_plan_binding is not None:
                bootstrap_runtime_detail["canary_slot_plan"] = slot_plan_binding
            checks.pass_("activation_bootstrap_runtime", bootstrap_runtime_detail)
        except EvidenceError as exc:
            checks.fail("activation_bootstrap_runtime", exc.code)

    if settings.mode in PRODUCTION_MODES:
        receipt: dict[str, Any] = {}
        try:
            if "primary" in committed_canary_errors:
                raise committed_canary_errors["primary"]
            primary_evidence = _mapping(
                committed_canary_evidence.get("primary"),
                "canary_receipt_committed_evidence",
            )
            receipt = _mapping(
                primary_evidence.get("receipt"),
                "canary_receipt",
            )
            if not canary_event_uid:
                raise EvidenceError("canary_receipt_plan_unverified")
            if not canary_request_sha256:
                raise EvidenceError("canary_receipt_request_plan_unverified")
            if not canary_admission:
                raise EvidenceError("canary_receipt_admission_plan_unverified")
            if not remote_reader_fingerprint:
                raise EvidenceError("canary_receipt_reader_health_unverified")
            if not canary_requested_scope:
                raise EvidenceError("canary_receipt_requested_scope_unverified")
            if not verified_vm_worker_commit:
                raise EvidenceError("canary_receipt_vm_worker_provenance_unverified")
            if not verified_vm_commit:
                raise EvidenceError("canary_receipt_vm_provenance_unverified")
            if not verified_vm_service_entrypoint_sha256:
                raise EvidenceError("canary_receipt_vm_service_entrypoint_unverified")
            if not verified_vm_worker_entrypoint_sha256:
                raise EvidenceError("canary_receipt_vm_worker_entrypoint_unverified")
            canary_detail = validate_canary_receipt(
                receipt,
                expected_execution_origin_id=_stable_trigger_source_id(
                    "kafka_workflow_event", canary_event_uid
                ),
                expected_execution_origin_kind="kafka_issue_created",
                expected_observed_source_id=_stable_trigger_source_id(
                    "kafka_workflow_event", canary_event_uid
                ),
                expected_observed_source_kind="kafka_issue_created",
                expected_request_sha256=canary_request_sha256,
                expected_admission=canary_admission,
                expected_reader_fingerprint=remote_reader_fingerprint,
                expected_requested_scope=canary_requested_scope,
                expected_vm_commit=verified_vm_commit,
                expected_vm_worker_commit=verified_vm_worker_commit,
                expected_vm_service_entrypoint_sha256=(
                    verified_vm_service_entrypoint_sha256
                ),
                expected_vm_worker_entrypoint_sha256=(
                    verified_vm_worker_entrypoint_sha256
                ),
                expected_capacity_mode=(
                    "bootstrap"
                    if settings.mode in BOOTSTRAP_CAPACITY_MODES
                    else "steady"
                ),
                expected_release_bom_sha256=_sha256_digest(
                    verified_build_detail.get("release_bom_sha256"),
                    "canary_receipt.release_bom_sha256",
                ),
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
            )
            if settings.mode == "production_bootstrap":
                if not bootstrap_authorization_detail:
                    raise EvidenceError(
                        "canary_vm_bootstrap_live_authorization_unverified"
                    )
                _bind_canary_bootstrap_authorization(
                    canary_detail,
                    bootstrap_authorization_detail,
                )
            checks.pass_("canary_receipt", canary_detail)
        except EvidenceError as exc:
            checks.fail("canary_receipt", exc.code)

        try:
            if "primary" in committed_canary_errors:
                raise committed_canary_errors["primary"]
            sources = _mapping(
                committed_canary_evidence.get("primary", {}).get("sources"),
                "canary_receipt_sources",
            )
            if not receipt:
                raise EvidenceError("canary_receipt_sources_receipt_unverified")
            if not verified_canary_collector_sha256:
                raise EvidenceError("canary_receipt_sources_collector_bom_unverified")
            if not remote_reader_health_body:
                raise EvidenceError("canary_receipt_sources_reader_health_unverified")
            detail = validate_canary_source_provenance(
                sources,
                receipt=receipt,
                settings=settings,
                expected_collector_sha256=verified_canary_collector_sha256,
                expected_control_db_path=dispatcher.control_db_path,
                expected_delivery_db_path=dispatcher.delivery_db_path,
                expected_reader_health=remote_reader_health_body,
                expected_workflow_policy=consumer.policy.to_dict(),
            )
            checks.pass_("canary_receipt_sources", detail)
        except EvidenceError as exc:
            checks.fail("canary_receipt_sources", exc.code)

        manual_success_receipt: dict[str, Any] = {}
        manual_success_detail: dict[str, Any] = {}
        manual_success_sources_verified = False
        try:
            if "manual_success" in committed_canary_errors:
                raise committed_canary_errors["manual_success"]
            manual_success_receipt = _mapping(
                committed_canary_evidence.get("manual_success", {}).get("receipt"),
                "manual_success_canary",
            )
            if cutover_config.manual_intake_enabled is not True:
                raise EvidenceError("manual_success_canary_intake_unverified")
            if not remote_reader_fingerprint:
                raise EvidenceError("manual_success_canary_reader_health_unverified")
            if not canary_requested_scope:
                raise EvidenceError("manual_success_canary_requested_scope_unverified")
            if not verified_vm_commit or not verified_vm_worker_commit:
                raise EvidenceError("manual_success_canary_vm_provenance_unverified")
            if (
                not verified_vm_service_entrypoint_sha256
                or not verified_vm_worker_entrypoint_sha256
            ):
                raise EvidenceError("manual_success_canary_entrypoint_unverified")
            manual_success_detail = validate_manual_success_canary(
                manual_success_receipt,
                expected_manual_chat_ids=cutover_config.manual_chat_ids,
                expected_operator_config=cutover_config,
                expected_reader_fingerprint=remote_reader_fingerprint,
                expected_requested_scope=canary_requested_scope,
                expected_vm_commit=verified_vm_commit,
                expected_vm_worker_commit=verified_vm_worker_commit,
                expected_vm_service_entrypoint_sha256=(
                    verified_vm_service_entrypoint_sha256
                ),
                expected_vm_worker_entrypoint_sha256=(
                    verified_vm_worker_entrypoint_sha256
                ),
                expected_rule_version=settings.expected_rule_version,
                expected_workflow_policy=consumer.policy.to_dict(),
                expected_capacity_mode=(
                    "bootstrap"
                    if settings.mode in BOOTSTRAP_CAPACITY_MODES
                    else "steady"
                ),
                expected_release_bom_sha256=_sha256_digest(
                    verified_build_detail.get("release_bom_sha256"),
                    "manual_success_canary.release_bom_sha256",
                ),
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
            )
            if settings.mode == "production_bootstrap":
                if not bootstrap_authorization_detail:
                    raise EvidenceError(
                        "canary_vm_bootstrap_live_authorization_unverified"
                    )
                _bind_canary_bootstrap_authorization(
                    manual_success_detail,
                    bootstrap_authorization_detail,
                )
            if not canary_detail:
                raise EvidenceError("manual_success_canary_kafka_canary_unverified")
            kafka_admission = _mapping(
                canary_detail.get("admission"), "canary_receipt.validated_admission"
            )
            manual_admission = _mapping(
                manual_success_detail.get("admission"),
                "manual_success_canary.validated_admission",
            )
            if (
                canary_detail.get("execution_origin", {}).get("source_id")
                == manual_success_detail.get("execution_origin", {}).get("source_id")
                or kafka_admission.get("business_key")
                == manual_admission.get("business_key")
                or kafka_admission.get("submission_key")
                == manual_admission.get("submission_key")
                or canary_detail.get("artifact_set_id")
                == manual_success_detail.get("artifact_set_id")
            ):
                raise EvidenceError("manual_success_canary_not_independent")
            checks.pass_("manual_success_canary", manual_success_detail)
        except EvidenceError as exc:
            checks.fail("manual_success_canary", exc.code)

        try:
            if "manual_success" in committed_canary_errors:
                raise committed_canary_errors["manual_success"]
            manual_success_sources = _mapping(
                committed_canary_evidence.get("manual_success", {}).get("sources"),
                "manual_success_canary_sources",
            )
            if not manual_success_receipt or not manual_success_detail:
                raise EvidenceError("manual_success_canary_sources_receipt_unverified")
            if not verified_canary_collector_sha256:
                raise EvidenceError("manual_success_canary_sources_collector_unverified")
            if not remote_reader_health_body:
                raise EvidenceError("manual_success_canary_sources_reader_unverified")
            manual_success_source_detail = validate_canary_source_provenance(
                manual_success_sources,
                receipt=manual_success_receipt,
                settings=settings,
                expected_collector_sha256=verified_canary_collector_sha256,
                expected_control_db_path=dispatcher.control_db_path,
                expected_delivery_db_path=dispatcher.delivery_db_path,
                expected_reader_health=remote_reader_health_body,
                expected_workflow_policy=consumer.policy.to_dict(),
                expected_manual_chat_ids=cutover_config.manual_chat_ids,
            )
            checks.pass_(
                "manual_success_canary_sources", manual_success_source_detail
            )
            manual_success_detail["sources"] = manual_success_source_detail
            manual_success_sources_verified = True
        except EvidenceError as exc:
            checks.fail("manual_success_canary_sources", exc.code)

        try:
            if not activation_detail:
                raise EvidenceError("activation_canary_epoch_unverified")
            detail = _check_activation_canary_bindings(
                activation_detail,
                slot_plan=canary_slot_plan,
                kafka_admission=_mapping(
                    receipt.get("admission"),
                    "activation.kafka_canary.admission",
                ),
                manual_success_admission=_mapping(
                    manual_success_receipt.get("admission"),
                    "activation.manual_success.admission",
                ),
                manual_terminal_admission=_mapping(
                    manual_terminal_detail.get("admission"),
                    "activation.manual_terminal.admission",
                ),
                kafka_detail=canary_detail,
                manual_success_detail=manual_success_detail,
                manual_terminal_detail=manual_terminal_detail,
            )
            checks.pass_("activation_canary_bindings", detail)
        except EvidenceError as exc:
            checks.fail("activation_canary_bindings", exc.code)

        try:
            capacity = _load_evidence(
                settings.evidence_dir, "capacity_receipt.json", evidence_hashes
            )
            detail = _check_capacity_receipt(
                capacity,
                dispatcher=dispatcher,
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
                target_cases_per_day=settings.target_cases_per_day,
                min_capacity_horizon_days=settings.min_capacity_horizon_days,
            )
            checks.pass_("capacity_receipt", detail)
        except EvidenceError as exc:
            checks.fail("capacity_receipt", exc.code)

        try:
            def verify_final_manual_databases() -> dict[str, Any]:
                def stable_pair(evidence_role: str) -> dict[str, Any]:
                    expected = committed_canary_evidence.get(evidence_role)
                    if not isinstance(expected, Mapping):
                        raise EvidenceError(
                            "manual_gateway_runtime_barrier_evidence_unverified"
                        )
                    return _recheck_committed_canary_evidence(
                        settings.evidence_dir,
                        expected,
                    )

                def recheck(
                    evidence_role: str,
                    *,
                    terminal_failure: bool,
                ) -> dict[str, Any]:
                    pair = stable_pair(evidence_role)
                    observed_receipt = _mapping(
                        pair.get("receipt"),
                        f"manual_gateway_runtime_barrier.{evidence_role}.receipt",
                    )
                    observed_sources = _mapping(
                        pair.get("sources"),
                        f"manual_gateway_runtime_barrier.{evidence_role}.sources",
                    )
                    sources_name = COMMITTED_CANARY_EVIDENCE_SPECS[
                        evidence_role
                    ].sources_stem
                    control_source = _mapping(
                        observed_sources.get("control_database"),
                        f"manual_gateway_runtime_barrier.{sources_name}.control",
                    )
                    delivery_source = _mapping(
                        observed_sources.get("delivery_database"),
                        f"manual_gateway_runtime_barrier.{sources_name}.delivery",
                    )
                    return _check_live_canary_database_binding(
                        receipt=observed_receipt,
                        control_snapshot_sha256=_sha256_digest(
                            control_source.get("snapshot_sha256"),
                            f"{sources_name}.control.snapshot_sha256",
                        ),
                        delivery_snapshot_sha256=_sha256_digest(
                            delivery_source.get("snapshot_sha256"),
                            f"{sources_name}.delivery.snapshot_sha256",
                        ),
                        control_db_path=dispatcher.control_db_path,
                        delivery_db_path=dispatcher.delivery_db_path,
                        evidence_dir=settings.evidence_dir,
                        group_binding_receipt_dir=(
                            settings.group_binding_receipt_dir
                        ),
                        manual_chat_ids=cutover_config.manual_chat_ids,
                        expected_workflow_policy=consumer.policy.to_dict(),
                        terminal_failure=terminal_failure,
                    )

                return {
                    "kafka_success": recheck(
                        "primary",
                        terminal_failure=False,
                    ),
                    "manual_success": recheck(
                        "manual_success",
                        terminal_failure=False,
                    ),
                    "manual_terminal": recheck(
                        "manual_terminal_failure",
                        terminal_failure=True,
                    ),
                }

            def verify_final_residents() -> dict[str, Any]:
                final_now = (
                    current
                    if now is not None
                    else datetime.now(timezone.utc)
                )
                return _check_delivery_service_health(
                    service_configs,
                    service_processes,
                    service_dependencies,
                    now=final_now,
                )

            detail = _check_manual_gateway_runtime_barrier(
                manual_success_detail=manual_success_detail,
                manual_terminal_detail=manual_terminal_detail,
                manual_success_sources_verified=manual_success_sources_verified,
                manual_terminal_sources_verified=isinstance(
                    manual_terminal_detail.get("sources"), Mapping
                ),
                build_detail=verified_build_detail,
                settings=settings,
                cutover=cutover_config,
                consumer=consumer,
                resident_verifier=verify_final_residents,
                database_verifier=verify_final_manual_databases,
            )
            bootstrap_gateway = _mapping(
                bootstrap_runtime_detail.get("gateway"),
                "manual_gateway_runtime_barrier.bootstrap_gateway",
            )
            if (
                bootstrap_gateway.get("state") != "running_safe"
                or detail.get("pid") != bootstrap_gateway.get("pid")
                or detail.get("process_create_time")
                != bootstrap_gateway.get("process_create_time")
                or detail.get("runtime_identity_sha256")
                != bootstrap_gateway.get("runtime_identity_sha256")
            ):
                raise EvidenceError("manual_gateway_runtime_barrier_bootstrap_changed")
            checks.pass_("manual_gateway_runtime_barrier", detail)
        except EvidenceError as exc:
            checks.fail("manual_gateway_runtime_barrier", exc.code)

        try:
            if not activation_detail:
                raise EvidenceError("activation_writer_barrier_prerequisite_unverified")
            if not activation_candidate_detail:
                raise EvidenceError("activation_writer_barrier_prerequisite_unverified")
            final_activation = _check_activation_epoch(
                control_db_path=dispatcher.control_db_path,
                mode=settings.mode,
                expected_config_sha256=config_sha256,
            )
            if final_activation.get("release_binding_sha256") != (
                activation_detail.get("release_binding_sha256")
            ):
                raise EvidenceError("activation_writer_barrier_changed")
            final_candidate = _load_evidence(
                settings.evidence_dir,
                "activation_production_candidate.json",
                evidence_hashes,
            )
            consumer_health = _mapping(
                health_detail.get("kafka_consumer_health"),
                "activation_writer_barrier.kafka_consumer_health",
            )
            consumer_runtime_sha256 = _sha256_digest(
                consumer_health.get("runtime_identity_sha256"),
                "activation_writer_barrier.consumer_runtime_identity_sha256",
            )
            barrier_now = (
                current
                if now is not None
                else datetime.now(timezone.utc)
            )
            final_live_collector = (
                activation_end_fence_verifier
                or collect_live_activation_end_fence
            )(
                consumer=consumer,
                partition_start_fence=_mapping(
                    final_activation.get("partition_start_fence"),
                    "activation_writer_barrier.partition_start_fence",
                ),
                epoch_id=str(final_activation.get("epoch_id") or ""),
                consumer_runtime_identity_sha256=consumer_runtime_sha256,
                host_repo_root=settings.host_repo_root,
                now=barrier_now,
            )
            final_candidate_detail = _check_activation_production_candidate(
                final_candidate,
                activation=final_activation,
                consumer=consumer,
                expected_config_sha256=config_sha256,
                expected_consumer_runtime_identity_sha256=(
                    consumer_runtime_sha256
                ),
                expected_host_repo_root=settings.host_repo_root,
                live_collector=final_live_collector,
                now=barrier_now,
                max_age_seconds=settings.evidence_max_age_seconds,
            )
            if final_candidate_detail.get("confirm_input_sha256") != (
                activation_candidate_detail.get("confirm_input_sha256")
            ) or final_candidate_detail.get("ingress_freeze_binding") != (
                activation_candidate_detail.get("ingress_freeze_binding")
            ):
                raise EvidenceError("activation_writer_barrier_changed")
            checks.pass_(
                "activation_writer_barrier",
                {
                    "epoch_id": final_activation.get("epoch_id"),
                    "state": "bounded_active",
                    "release_binding_sha256": final_activation.get(
                        "release_binding_sha256"
                    ),
                    "transition_performed": False,
                    "production_confirmation_required": True,
                    "ingress_freeze_binding": final_candidate_detail.get(
                        "ingress_freeze_binding"
                    ),
                    "confirm_input": final_candidate_detail.get("confirm_input"),
                    "confirm_input_sha256": final_candidate_detail.get(
                        "confirm_input_sha256"
                    ),
                },
            )
        except EvidenceError as exc:
            checks.fail("activation_writer_barrier", exc.code)

    blockers = [item["code"] for item in checks.items if not item["ok"]]
    fingerprint_input = {
        "schema_version": RELEASE_GATE_SCHEMA_VERSION,
        "mode": settings.mode,
        "expected_topic": settings.expected_topic,
        "expected_rule_version": settings.expected_rule_version,
        "config": public_config,
        "gate_policy": gate_policy,
        "contract": contract_public,
        "evidence_sha256": dict(sorted(evidence_hashes.items())),
        "checks": checks.items,
        "blockers": blockers,
        "warnings": warnings,
    }
    evaluated_at = (
        current
        if now is not None
        else datetime.now(timezone.utc).astimezone(timezone.utc)
    )
    return {
        "schema_version": RELEASE_GATE_SCHEMA_VERSION,
        "evaluated_at": evaluated_at.isoformat(),
        "mode": settings.mode,
        "ok": not blockers,
        "fingerprint": _sha256_json(fingerprint_input),
        "config": public_config,
        "gate_policy": gate_policy,
        "checks": checks.items,
        "blockers": blockers,
        "warnings": warnings,
        "evidence_sha256": dict(sorted(evidence_hashes.items())),
    }


def _configuration_failure(
    *, mode: str, code: str, detail: str, now: datetime | None = None
) -> dict[str, Any]:
    current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    check = {
        "name": "configuration_load",
        "ok": False,
        "code": code,
        "detail": {"error": detail},
    }
    fingerprint_input = {
        "schema_version": RELEASE_GATE_SCHEMA_VERSION,
        "mode": mode,
        "checks": [check],
        "blockers": [code],
        "warnings": [],
    }
    return {
        "schema_version": RELEASE_GATE_SCHEMA_VERSION,
        "evaluated_at": current.isoformat(),
        "mode": mode,
        "ok": False,
        "fingerprint": _sha256_json(fingerprint_input),
        "config": {},
        "checks": [check],
        "blockers": [code],
        "warnings": [],
        "evidence_sha256": {},
    }


def load_redacted_configs(
    env_file: Path,
    *,
    environment: Mapping[str, str] | None = None,
    hermes_home: Path | None = None,
) -> tuple[ConsumerConfig, DispatcherConfig]:
    """Load the real config classes; callers only serialize their public views."""
    source = _load_env_source(env_file, environment=environment)
    home = hermes_home or Path(source.get("HERMES_HOME", "~/.hermes")).expanduser()
    return (
        ConsumerConfig.from_env(source, hermes_home=home),
        DispatcherConfig.from_env(source, hermes_home=home),
    )


def _load_env_source(
    env_file: Path,
    *,
    environment: Mapping[str, str] | None = None,
) -> dict[str, str]:
    base: Mapping[str, str] = {} if environment is None else environment
    source = {str(key): str(value) for key, value in base.items()}
    if env_file.is_file():
        for key, value in dotenv_values(env_file, interpolate=False).items():
            if value is not None and key not in source:
                source[str(key)] = str(value)
    return source


def load_cutover_config(
    env_file: Path,
    *,
    environment: Mapping[str, str] | None = None,
) -> CutoverConfig:
    return CutoverConfig.from_env(_load_env_source(env_file, environment=environment))


def write_receipt_atomic(path: Path, report: Mapping[str, Any]) -> None:
    path = path.expanduser()
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    payload = json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    temporary_name = ""
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            dir=path.parent,
            prefix=f".{path.name}.",
            suffix=".tmp",
            delete=False,
        ) as handle:
            temporary_name = handle.name
            os.chmod(handle.name, 0o600)
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary_name, path)
        os.chmod(path, 0o600)
        _fsync_directory(path.parent)
    finally:
        if temporary_name:
            try:
                Path(temporary_name).unlink(missing_ok=True)
            except OSError:
                pass


def activation_confirmation_capsule_path(receipt_path: Path) -> Path:
    receipt = receipt_path.expanduser()
    return receipt.with_name(f"{receipt.stem}.activation-confirmation.json")


def activation_confirmation_pair_commit_path(receipt_path: Path) -> Path:
    receipt = receipt_path.expanduser()
    return receipt.with_name(f"{receipt.stem}.activation-confirmation.commit.json")


def activation_preauthorization_capsule_path(receipt_path: Path) -> Path:
    receipt = receipt_path.expanduser()
    return receipt.with_name(f"{receipt.stem}.activation-preauthorization.json")


def activation_preproduction_capsule_path(receipt_path: Path) -> Path:
    receipt = receipt_path.expanduser()
    return receipt.with_name(f"{receipt.stem}.activation-preproduction.json")


def activation_stage_pair_commit_path(receipt_path: Path, *, mode: str) -> Path:
    if mode not in {"preauthorization", "preproduction"}:
        raise EvidenceError("activation_stage_mode_invalid")
    receipt = receipt_path.expanduser()
    return receipt.with_name(f"{receipt.stem}.activation-{mode}.commit.json")


def _read_exact_release_gate_receipt(
    path: Path, expected_report: Mapping[str, Any]
) -> tuple[bytes, dict[str, Any]]:
    receipt = path.expanduser().absolute()
    descriptor = -1
    try:
        initial = os.lstat(receipt)
        if (
            stat.S_ISLNK(initial.st_mode)
            or not stat.S_ISREG(initial.st_mode)
            or initial.st_uid != os.getuid()
            or initial.st_nlink != 1
            or stat.S_IMODE(initial.st_mode) != 0o600
            or initial.st_size <= 0
            or initial.st_size > MAX_EVIDENCE_BYTES
        ):
            raise EvidenceError("activation_gate_receipt_invalid")
        descriptor = os.open(
            receipt,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
        )
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or (opened.st_dev, opened.st_ino, opened.st_size)
            != (initial.st_dev, initial.st_ino, initial.st_size)
        ):
            raise EvidenceError("activation_gate_receipt_invalid")
        remaining = opened.st_size
        chunks: list[bytes] = []
        while remaining:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise EvidenceError("activation_gate_receipt_invalid")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise EvidenceError("activation_gate_receipt_invalid")
        final_opened = os.fstat(descriptor)
        final_path = os.lstat(receipt)
        if (
            (
                final_opened.st_dev,
                final_opened.st_ino,
                final_opened.st_size,
                final_opened.st_mtime_ns,
            )
            != (
                initial.st_dev,
                initial.st_ino,
                initial.st_size,
                initial.st_mtime_ns,
            )
            or (
                final_path.st_dev,
                final_path.st_ino,
                final_path.st_size,
                final_path.st_mtime_ns,
            )
            != (
                initial.st_dev,
                initial.st_ino,
                initial.st_size,
                initial.st_mtime_ns,
            )
        ):
            raise EvidenceError("activation_gate_receipt_changed")
        raw = b"".join(chunks)
    except EvidenceError:
        raise
    except OSError as exc:
        raise EvidenceError("activation_gate_receipt_invalid") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    try:
        decoded = raw.decode("utf-8")
    except UnicodeError as exc:
        raise EvidenceError("activation_gate_receipt_invalid") from exc
    body = _mapping(
        _strict_json_loads(decoded, artifact="activation_gate_receipt"),
        "activation_gate_receipt",
    )
    if body != dict(expected_report):
        raise EvidenceError("activation_gate_receipt_body_mismatch")
    return raw, dict(body)


def _fsync_directory(path: Path) -> None:
    descriptor = -1
    try:
        descriptor = os.open(
            path,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_DIRECTORY", 0),
        )
        os.fsync(descriptor)
    except OSError as exc:
        raise EvidenceError("activation_publication_directory_sync_failed") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)


@contextmanager
def _activation_publication_lock(path: Path):
    destination = path.expanduser().absolute()
    destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    directory_fd = _open_secure_evidence_directory(
        destination.parent,
        artifact="activation_publication_directory",
    )
    os.close(directory_fd)
    lock_path = destination.parent / f".{destination.name}.publication.lock"
    descriptor = -1
    try:
        descriptor = os.open(
            lock_path,
            os.O_RDWR
            | os.O_CREAT
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            0o600,
        )
        os.fchmod(descriptor, 0o600)
        info = os.fstat(descriptor)
        current = os.lstat(lock_path)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.getuid()
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) != 0o600
            or (info.st_dev, info.st_ino) != (current.st_dev, current.st_ino)
        ):
            raise EvidenceError("activation_publication_lock_invalid")
        fcntl.flock(descriptor, fcntl.LOCK_EX)
        yield
    except EvidenceError:
        raise
    except OSError as exc:
        raise EvidenceError("activation_publication_lock_failed") from exc
    finally:
        if descriptor >= 0:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            except OSError:
                pass
            os.close(descriptor)


def _recover_interrupted_no_clobber_link(
    destination: Path,
    *,
    payload: bytes,
    conflict_code: str,
) -> None:
    try:
        info = os.lstat(destination)
    except FileNotFoundError:
        return
    except OSError as exc:
        raise EvidenceError(conflict_code) from exc
    if info.st_nlink == 1:
        return
    if (
        not stat.S_ISREG(info.st_mode)
        or info.st_uid != os.getuid()
        or info.st_nlink != 2
        or stat.S_IMODE(info.st_mode) != 0o600
        or info.st_size != len(payload)
    ):
        raise EvidenceError(conflict_code)
    matches: list[Path] = []
    pattern = f".{destination.name}.*.no-clobber.tmp"
    try:
        candidates = list(destination.parent.glob(pattern))
    except OSError as exc:
        raise EvidenceError(conflict_code) from exc
    for candidate in candidates:
        try:
            candidate_info = os.lstat(candidate)
        except OSError:
            continue
        if (
            stat.S_ISREG(candidate_info.st_mode)
            and candidate_info.st_uid == os.getuid()
            and stat.S_IMODE(candidate_info.st_mode) == 0o600
            and (candidate_info.st_dev, candidate_info.st_ino)
            == (info.st_dev, info.st_ino)
        ):
            matches.append(candidate)
    if len(matches) != 1:
        raise EvidenceError(conflict_code)
    descriptor = -1
    try:
        descriptor = os.open(
            matches[0],
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
        )
        recovered = b""
        while len(recovered) < len(payload):
            chunk = os.read(descriptor, len(payload) - len(recovered))
            if not chunk:
                break
            recovered += chunk
        if recovered != payload or os.read(descriptor, 1):
            raise EvidenceError(conflict_code)
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    matches[0].unlink()
    _fsync_directory(destination.parent)
    repaired = os.lstat(destination)
    if repaired.st_nlink != 1:
        raise EvidenceError(conflict_code)


def _recover_existing_no_clobber_member(
    destination: Path,
    *,
    conflict_code: str,
) -> None:
    candidate = destination.expanduser().absolute()
    try:
        info = os.lstat(candidate)
    except FileNotFoundError:
        return
    except OSError as exc:
        raise EvidenceError(conflict_code) from exc
    if info.st_nlink == 1:
        return
    pattern = f".{candidate.name}.*.no-clobber.tmp"
    matches: list[Path] = []
    for temporary in candidate.parent.glob(pattern):
        try:
            temporary_info = os.lstat(temporary)
        except OSError:
            continue
        if (
            stat.S_ISREG(temporary_info.st_mode)
            and temporary_info.st_uid == os.getuid()
            and (temporary_info.st_dev, temporary_info.st_ino)
            == (info.st_dev, info.st_ino)
        ):
            matches.append(temporary)
    if info.st_nlink != 2 or len(matches) != 1:
        raise EvidenceError(conflict_code)
    try:
        payload = matches[0].read_bytes()
    except OSError as exc:
        raise EvidenceError(conflict_code) from exc
    _recover_interrupted_no_clobber_link(
        candidate,
        payload=payload,
        conflict_code=conflict_code,
    )


def write_receipt_no_clobber(
    path: Path,
    report: Mapping[str, Any],
    *,
    conflict_code: str,
) -> None:
    destination = path.expanduser().absolute()
    destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    payload = (
        json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    with _activation_publication_lock(destination):
        _recover_interrupted_no_clobber_link(
            destination,
            payload=payload,
            conflict_code=conflict_code,
        )
        temporary_name = ""
        try:
            with tempfile.NamedTemporaryFile(
                mode="wb",
                dir=destination.parent,
                prefix=f".{destination.name}.",
                suffix=".no-clobber.tmp",
                delete=False,
            ) as handle:
                temporary_name = handle.name
                os.fchmod(handle.fileno(), 0o600)
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            try:
                os.link(temporary_name, destination, follow_symlinks=False)
            except FileExistsError:
                try:
                    existing_raw, _existing_body = _read_exact_release_gate_receipt(
                        destination,
                        report,
                    )
                except EvidenceError as exc:
                    raise EvidenceError(conflict_code) from exc
                if existing_raw != payload:
                    raise EvidenceError(conflict_code)
                return
            Path(temporary_name).unlink()
            temporary_name = ""
            _fsync_directory(destination.parent)
            written = os.lstat(destination)
            if (
                not stat.S_ISREG(written.st_mode)
                or written.st_uid != os.getuid()
                or written.st_nlink != 1
                or stat.S_IMODE(written.st_mode) != 0o600
                or written.st_size != len(payload)
            ):
                raise EvidenceError(f"{conflict_code}_write_invalid")
        except EvidenceError:
            raise
        except OSError as exc:
            raise EvidenceError(f"{conflict_code}_write_failed") from exc
        finally:
            if temporary_name:
                try:
                    Path(temporary_name).unlink(missing_ok=True)
                    _fsync_directory(destination.parent)
                except (OSError, EvidenceError):
                    pass


def _release_check_map(
    report: Mapping[str, Any],
    *,
    expected_names: frozenset[str],
    artifact: str,
) -> dict[str, dict[str, Any]]:
    raw_checks = report.get("checks")
    if not isinstance(raw_checks, list):
        raise EvidenceError(f"{artifact}_checks_invalid")
    checks = [
        _mapping(item, f"{artifact}.checks.{index}")
        for index, item in enumerate(raw_checks)
    ]
    if (
        len(checks) != len(expected_names)
        or {str(item.get("name") or "") for item in checks} != expected_names
        or any(set(item) != {"name", "ok", "code", "detail"} for item in checks)
        or any(item.get("ok") is not True or item.get("code") != "pass" for item in checks)
    ):
        raise EvidenceError(f"{artifact}_checks_invalid")
    return {str(item["name"]): dict(item) for item in checks}


def _validate_activation_stage_release_report(
    report: Mapping[str, Any],
    *,
    mode: str,
) -> tuple[str, dict[str, dict[str, Any]]]:
    artifact = f"activation_{mode}"
    if mode not in {"preauthorization", "preproduction"}:
        raise EvidenceError("activation_stage_mode_invalid")
    if set(report) != {
        "schema_version",
        "evaluated_at",
        "mode",
        "ok",
        "fingerprint",
        "config",
        "gate_policy",
        "checks",
        "blockers",
        "warnings",
        "evidence_sha256",
    }:
        raise EvidenceError(f"{artifact}_report_shape_invalid")
    _timestamp(report.get("evaluated_at"), f"{artifact}.evaluated_at")
    checks = _release_check_map(
        report,
        expected_names=(
            PREPRODUCTION_RELEASE_CHECK_NAMES
            if mode == "preproduction"
            else ACTIVATION_STAGE_RELEASE_CHECK_NAMES
        ),
        artifact=artifact,
    )
    if (
        report.get("schema_version") != RELEASE_GATE_SCHEMA_VERSION
        or report.get("mode") != mode
        or report.get("ok") is not True
        or report.get("blockers") != []
        or report.get("warnings") != []
    ):
        raise EvidenceError(f"{artifact}_report_not_successful")
    activation = _mapping(
        checks["activation_epoch"].get("detail"), f"{artifact}.activation"
    )
    migration = _mapping(
        checks["store_migration"].get("detail"), f"{artifact}.migration"
    )
    runtime = _mapping(
        checks["activation_bootstrap_runtime"].get("detail"),
        f"{artifact}.bootstrap_runtime",
    )
    expected_state = "absent" if mode == "preauthorization" else "safe_off"
    if (
        activation.get("state") != expected_state
        or migration.get("rollback_ready") is not True
        or migration.get("writer_stop_service_count") != len(STORE_WRITER_LABELS)
        or runtime.get("mode") != mode
        or runtime.get("database_state") != expected_state
        or runtime.get("active_effect_count") != 0
        or runtime.get("rca_resident_count") != len(RCA_RESIDENT_LABELS)
        or runtime.get("rca_residents_stopped") is not True
        or runtime.get("gateway_activation_required") is not True
        or runtime.get("manual_rca_admission")
        != "fail_closed_by_activation_state"
    ):
        raise EvidenceError(f"{artifact}_bootstrap_binding_invalid")
    config = _mapping(report.get("config"), f"{artifact}.config")
    consumer = _mapping(config.get("consumer"), f"{artifact}.consumer")
    policy = _mapping(consumer.get("policy"), f"{artifact}.policy")
    contract = _mapping(
        checks["contract_drift"].get("detail"), f"{artifact}.contract"
    )
    fingerprint_input = {
        "schema_version": RELEASE_GATE_SCHEMA_VERSION,
        "mode": mode,
        "expected_topic": _required_text(
            consumer.get("topic"), f"{artifact}.consumer.topic"
        ),
        "expected_rule_version": _required_text(
            policy.get("policy_version"), f"{artifact}.policy.policy_version"
        ),
        "config": dict(config),
        "gate_policy": dict(
            _mapping(report.get("gate_policy"), f"{artifact}.gate_policy")
        ),
        "contract": dict(contract),
        "evidence_sha256": dict(
            sorted(
                _mapping(
                    report.get("evidence_sha256"),
                    f"{artifact}.evidence_sha256",
                ).items()
            )
        ),
        "checks": [dict(item) for item in report["checks"]],
        "blockers": [],
        "warnings": [],
    }
    fingerprint = _sha256_digest(
        report.get("fingerprint"), f"{artifact}.fingerprint"
    )
    if fingerprint != _sha256_json(fingerprint_input):
        raise EvidenceError(f"{artifact}_fingerprint_invalid")
    return fingerprint, checks


def _secure_stage_evidence(
    evidence_dir: Path,
    filename: str,
    *,
    expected_raw_sha256: str,
    artifact: str,
) -> dict[str, Any]:
    directory_fd = _open_secure_evidence_directory(evidence_dir, artifact=artifact)
    try:
        observed = _secure_read_evidence_json_at(
            directory_fd,
            filename,
            artifact=artifact,
            max_bytes=MAX_EVIDENCE_BYTES,
        )
    finally:
        os.close(directory_fd)
    expected = _sha256_digest(expected_raw_sha256, f"{artifact}.expected_sha256")
    if observed.get("raw_sha256") != expected:
        raise EvidenceError(f"{artifact}_raw_sha256_mismatch")
    return observed


def _activation_stage_material(
    report: Mapping[str, Any],
    checks: Mapping[str, Mapping[str, Any]],
    *,
    evidence_dir: Path,
    control_db_path: Path,
) -> dict[str, Any]:
    hashes = _mapping(
        report.get("evidence_sha256"), "activation_stage.evidence_sha256"
    )
    required = {
        "broker_metadata.json",
        "canary_plan.json",
        "t0_offsets.json",
        "store_migration_receipt.json",
    }
    if not required.issubset(hashes):
        raise EvidenceError("activation_stage_evidence_binding_missing")
    observations = {
        filename: _secure_stage_evidence(
            evidence_dir,
            filename,
            expected_raw_sha256=str(hashes[filename]),
            artifact=f"activation_stage_{Path(filename).stem}",
        )
        for filename in sorted(required)
    }
    migration = _mapping(
        checks["store_migration"].get("detail"), "activation_stage.migration"
    )
    materialization_sha256 = _sha256_digest(
        migration.get("materialization_receipt_raw_sha256"),
        "activation_stage.materialization_receipt_raw_sha256",
    )
    if migration.get("materialization_required") is True:
        filename = "fresh_install_materialization_receipt.json"
        if filename not in hashes:
            raise EvidenceError("activation_stage_materialization_binding_missing")
        observation = _secure_stage_evidence(
            evidence_dir,
            filename,
            expected_raw_sha256=str(hashes[filename]),
            artifact="activation_stage_materialization_receipt",
        )
        observations[filename] = observation
        if observation.get("raw_sha256") != materialization_sha256:
            raise EvidenceError("activation_stage_materialization_binding_invalid")
    elif materialization_sha256 != hashlib.sha256(b"").hexdigest():
        raise EvidenceError("activation_stage_materialization_binding_invalid")
    migration_sha256 = _sha256_digest(
        migration.get("migration_receipt_raw_sha256"),
        "activation_stage.migration_receipt_raw_sha256",
    )
    if observations["store_migration_receipt.json"].get("raw_sha256") != (
        migration_sha256
    ):
        raise EvidenceError("activation_stage_migration_binding_invalid")
    config = _mapping(report.get("config"), "activation_stage.config")
    config_sha256 = _sha256_json(config)
    db_identity = _mapping(
        migration.get("expected_db_logical_identity"),
        "activation_stage.db_logical_identity",
    )
    db_identity_sha256 = _sha256_digest(
        migration.get("expected_db_logical_identity_sha256"),
        "activation_stage.db_logical_identity_sha256",
    )
    if (
        _sha256_json(db_identity) != db_identity_sha256
        or db_identity.get("config_sha256") != config_sha256
        or db_identity.get("migration_receipt_raw_sha256") != migration_sha256
        or db_identity.get("materialization_receipt_raw_sha256")
        != materialization_sha256
    ):
        raise EvidenceError("activation_stage_database_identity_invalid")
    t0 = _mapping(
        observations["t0_offsets.json"].get("body"), "activation_stage.t0"
    )
    consumer = _mapping(config.get("consumer"), "activation_stage.consumer")
    topic = _required_text(consumer.get("topic"), "activation_stage.topic")
    offsets = _partition_offsets(t0.get("partition_offsets"), "partition_offsets")
    start_fence = {
        topic: {str(partition): offsets[partition] for partition in sorted(offsets)}
    }
    configured_offsets = _mapping(
        consumer.get("initial_offsets"), "activation_stage.initial_offsets"
    )
    if (
        t0.get("topic") != topic
        or {str(key): value for key, value in configured_offsets.items()}
        != start_fence[topic]
    ):
        raise EvidenceError("activation_stage_t0_binding_invalid")
    broker_t0_observation = {
        "broker_metadata_raw_sha256": observations["broker_metadata.json"][
            "raw_sha256"
        ],
        "t0_offsets_raw_sha256": observations["t0_offsets.json"]["raw_sha256"],
        "topic": topic,
        "partition_start_fence": start_fence,
    }
    _validate_activation_database_identity(
        db_identity,
        control_db_path=control_db_path,
    )
    return {
        "config_sha256": config_sha256,
        "db_logical_identity": dict(db_identity),
        "db_logical_identity_sha256": db_identity_sha256,
        "partition_start_fence": start_fence,
        "partition_start_fence_sha256": _sha256_json(start_fence),
        "migration_receipt_raw_sha256": migration_sha256,
        "materialization_receipt_raw_sha256": materialization_sha256,
        "broker_t0_observation_sha256": _sha256_json(broker_t0_observation),
        "canary_plan_raw_sha256": observations["canary_plan.json"]["raw_sha256"],
    }


def _validate_activation_database_identity(
    value: Mapping[str, Any],
    *,
    control_db_path: Path,
) -> None:
    identity = _mapping(value, "activation_db_identity")
    if set(identity) != {
        "schema_version",
        "strategy",
        "databases",
        "migration_receipt_raw_sha256",
        "materialization_receipt_raw_sha256",
        "host_commit",
        "config_sha256",
    } or identity.get("schema_version") != "pnc_rca_activation_db_identity_v1":
        raise EvidenceError("activation_database_identity_shape_invalid")
    strategy = identity.get("strategy")
    if strategy not in {"fresh_install_preserve", "existing_database_preserve"}:
        raise EvidenceError("activation_database_identity_strategy_invalid")
    databases = _mapping(identity.get("databases"), "activation_db_identity.databases")
    if set(databases) != {"control", "delivery"}:
        raise EvidenceError("activation_database_identity_databases_invalid")
    for role in ("control", "delivery"):
        database = _mapping(
            databases.get(role), f"activation_db_identity.databases.{role}"
        )
        if set(database) != {
            "path",
            "device",
            "inode",
            "schema_version",
            "db_instance_id",
            "genesis_intent_sha256",
        }:
            raise EvidenceError("activation_database_identity_database_invalid")
        path = Path(
            _required_text(database.get("path"), f"activation_db_identity.{role}.path")
        ).expanduser().absolute()
        if role == "control" and path != control_db_path.expanduser().absolute():
            raise EvidenceError("activation_database_identity_control_path_mismatch")
        resolved, observed = _observe_live_database_identity(
            path,
            unreadable_code="activation_database_unreadable",
            invalid_code="activation_database_invalid",
        )
        expected_schema = (
            CONTROL_STORE_SCHEMA_VERSION
            if role == "control"
            else DELIVERY_STORE_SCHEMA_VERSION
        )
        if (
            str(resolved) != database.get("path")
            or int(observed.st_dev) != database.get("device")
            or int(observed.st_ino) != database.get("inode")
            or database.get("schema_version") != expected_schema
        ):
            raise EvidenceError("activation_database_identity_live_mismatch")
        connection: sqlite3.Connection | None = None
        try:
            connection = sqlite3.connect(
                resolved.as_uri() + "?mode=ro", uri=True, timeout=5
            )
            connection.execute("PRAGMA query_only=ON")
            connection.execute("PRAGMA trusted_schema=OFF")
            table = "control_meta" if role == "control" else "rca_delivery_meta"
            schema_row = connection.execute(
                f"SELECT value FROM {table} WHERE key='schema_version'"
            ).fetchone()
        except sqlite3.Error as exc:
            raise EvidenceError("activation_database_unreadable") from exc
        finally:
            if connection is not None:
                connection.close()
        if schema_row is None or str(schema_row[0]) != expected_schema:
            raise EvidenceError("activation_database_identity_live_mismatch")
    if strategy == "fresh_install_preserve":
        control_path = Path(str(databases["control"]["path"]))
        try:
            genesis = _read_genesis_meta(control_path)
        except MigrationDrillError as exc:
            raise EvidenceError("activation_database_genesis_invalid") from exc
        for role in ("control", "delivery"):
            database = _mapping(databases[role], f"activation_db_identity.{role}")
            if (
                genesis.get(f"{role}.fresh_install_db_instance_id")
                != database.get("db_instance_id")
                or genesis.get(f"{role}.fresh_install_genesis_intent_sha256")
                != database.get("genesis_intent_sha256")
            ):
                raise EvidenceError("activation_database_genesis_invalid")
    elif any(
        databases[role].get("db_instance_id") is not None
        or databases[role].get("genesis_intent_sha256") is not None
        for role in ("control", "delivery")
    ):
        control_path = Path(str(databases["control"]["path"]))
        lineage = _existing_database_origin_lineage(control_path)
        if lineage is None:
            raise EvidenceError("activation_database_identity_existing_invalid")
        for role in ("control", "delivery"):
            database = _mapping(databases[role], f"activation_db_identity.{role}")
            if (
                lineage.get(f"{role}.fresh_install_db_instance_id")
                != database.get("db_instance_id")
                or lineage.get(f"{role}.fresh_install_genesis_intent_sha256")
                != database.get("genesis_intent_sha256")
            ):
                raise EvidenceError("activation_database_identity_existing_invalid")


def _check_activation_capsule_freshness(
    *,
    report: Mapping[str, Any],
    capsule_created_at: Any,
    now: datetime,
    artifact: str,
) -> datetime:
    evaluated_at = _timestamp(report.get("evaluated_at"), f"{artifact}.evaluated_at")
    created_at = _timestamp(capsule_created_at, f"{artifact}.created_at")
    policy = _mapping(report.get("gate_policy"), f"{artifact}.gate_policy")
    max_age = _exact_int(
        policy.get("evidence_max_age_seconds"),
        f"{artifact}.evidence_max_age_seconds",
        minimum=1,
    )
    if max_age > DEFAULT_EVIDENCE_MAX_AGE_SECONDS or created_at != evaluated_at:
        raise EvidenceError(f"{artifact}_freshness_policy_invalid")
    current = now.astimezone(timezone.utc)
    age = (current - created_at).total_seconds()
    if age < -MAX_HEALTH_FUTURE_SKEW_SECONDS:
        raise EvidenceError(f"{artifact}_from_future")
    if age > ACTIVATION_STAGE_CAPSULE_MAX_AGE_SECONDS:
        raise EvidenceError(f"{artifact}_stale")
    return created_at


def _recheck_capsule_gateway_binding(
    value: Mapping[str, Any],
) -> None:
    binding = _mapping(value, "activation_capsule.gateway_binding")
    if set(binding) != {
        "state",
        "pid",
        "process_create_time",
        "runtime_identity_sha256",
        "runtime_identity",
        "verified_runtime_sha256",
    } or binding.get("state") != "running_safe":
        raise EvidenceError("activation_capsule_gateway_binding_invalid")
    identity = _check_gateway_runtime_identity(
        binding.get("runtime_identity"),
        field="activation_capsule.gateway_runtime_identity",
    )
    pid = _exact_int(binding.get("pid"), "activation_capsule.gateway.pid", minimum=1)
    if (
        _live_launchd_pid("ai.hermes.gateway") != pid
        or binding.get("runtime_identity_sha256") != _sha256_json(identity)
        or identity.get("pid") != pid
        or identity.get("process_create_time") != binding.get("process_create_time")
    ):
        raise EvidenceError("activation_capsule_gateway_restarted")
    try:
        process = psutil.Process(pid)
        create_time = float(process.create_time())
        script = Path(str(identity["script"]))
        root = Path(str(identity["cwd"]))
        _runtime_map, runtime_sha256 = runtime_file_snapshot(
            root,
            GATEWAY_RCA_RUNTIME_RELATIVE_FILES,
        )
    except (OSError, ValueError, psutil.Error) as exc:
        raise EvidenceError("activation_capsule_gateway_restarted") from exc
    if (
        create_time != float(binding["process_create_time"])
        or file_sha256(script) != identity.get("script_sha256")
        or runtime_sha256 != identity.get("runtime_files_sha256")
    ):
        raise EvidenceError("activation_capsule_gateway_restarted")


def _stage_receipt_binding(
    receipt_path: Path,
    report: Mapping[str, Any],
) -> tuple[bytes, dict[str, Any]]:
    raw, verified = _read_exact_release_gate_receipt(receipt_path, report)
    return raw, {
        "path": str(receipt_path.expanduser().absolute()),
        "size_bytes": len(raw),
        "raw_sha256": hashlib.sha256(raw).hexdigest(),
        "report_fingerprint": _sha256_digest(
            verified.get("fingerprint"), "activation_stage.report_fingerprint"
        ),
    }


def _stage_epoch_id(report: Mapping[str, Any], fingerprint: str) -> str:
    evaluated_at = _timestamp(report.get("evaluated_at"), "activation_stage.evaluated_at")
    return f"rca:{evaluated_at.strftime('%Y%m%dT%H%M%SZ')}:{fingerprint[:20]}"


def _activation_stage_pair_material(
    *,
    mode: str,
    receipt_path: Path,
    raw_receipt: bytes,
    report: Mapping[str, Any],
    capsule_path: Path,
    raw_capsule: bytes,
    capsule: Mapping[str, Any],
) -> dict[str, Any]:
    fingerprint, _checks = _validate_activation_stage_release_report(
        report,
        mode=mode,
    )
    receipt_file = receipt_path.expanduser().absolute()
    capsule_file = capsule_path.expanduser().absolute()
    expected_capsule = (
        activation_preauthorization_capsule_path(receipt_file)
        if mode == "preauthorization"
        else activation_preproduction_capsule_path(receipt_file)
    ).absolute()
    expected_schema = (
        ACTIVATION_PREAUTHORIZATION_CAPSULE_SCHEMA_VERSION
        if mode == "preauthorization"
        else ACTIVATION_PREPRODUCTION_CAPSULE_SCHEMA_VERSION
    )
    transition_field = (
        "activation_input" if mode == "preauthorization" else "transition_input"
    )
    transition_hash_field = f"{transition_field}_sha256"
    transition = _mapping(
        capsule.get(transition_field),
        f"activation_{mode}_pair.{transition_field}",
    )
    receipt_binding = _mapping(
        capsule.get("release_gate_receipt"),
        f"activation_{mode}_pair.release_gate_receipt",
    )
    receipt_raw_sha256 = hashlib.sha256(raw_receipt).hexdigest()
    if (
        capsule_file != expected_capsule
        or capsule.get("schema_version") != expected_schema
        or capsule.get(transition_hash_field) != _sha256_json(transition)
        or receipt_binding
        != {
            "path": str(receipt_file),
            "size_bytes": len(raw_receipt),
            "raw_sha256": receipt_raw_sha256,
            "report_fingerprint": fingerprint,
        }
    ):
        raise EvidenceError(f"activation_{mode}_pair_binding_invalid")
    return {
        "release_gate_receipt": {
            "path": str(receipt_file),
            "size_bytes": len(raw_receipt),
            "raw_sha256": receipt_raw_sha256,
            "report_fingerprint": fingerprint,
        },
        "stage_capsule": {
            "path": str(capsule_file),
            "size_bytes": len(raw_capsule),
            "raw_sha256": hashlib.sha256(raw_capsule).hexdigest(),
            "transition_sha256": _sha256_json(transition),
        },
    }


def write_activation_stage_pair_commit(
    receipt_path: Path,
    report: Mapping[str, Any],
    *,
    mode: str,
    capsule_path: Path,
) -> Path:
    receipt_file = receipt_path.expanduser().absolute()
    capsule_file = capsule_path.expanduser().absolute()
    raw_receipt, verified_report = _read_exact_release_gate_receipt(
        receipt_file,
        report,
    )
    loaded_capsule = _load_evidence(capsule_file.parent, capsule_file.name, {})
    raw_capsule, verified_capsule = _read_exact_release_gate_receipt(
        capsule_file,
        loaded_capsule,
    )
    material = _activation_stage_pair_material(
        mode=mode,
        receipt_path=receipt_file,
        raw_receipt=raw_receipt,
        report=verified_report,
        capsule_path=capsule_file,
        raw_capsule=raw_capsule,
        capsule=verified_capsule,
    )
    marker = {
        "schema_version": ACTIVATION_STAGE_PAIR_COMMIT_SCHEMA_VERSION,
        "stage": mode,
        "created_at": _required_text(
            verified_report.get("evaluated_at"),
            f"activation_{mode}_pair.created_at",
        ),
        **material,
        "pair_sha256": _sha256_json(material),
        "publication_complete": True,
        "operator_supplied_scope_fields": [],
    }
    destination = activation_stage_pair_commit_path(receipt_file, mode=mode)
    write_receipt_no_clobber(
        destination,
        marker,
        conflict_code=f"activation_{mode}_pair_commit_conflict",
    )
    return destination


def _read_activation_stage_pair_commit(
    *,
    mode: str,
    receipt_path: Path,
    raw_receipt: bytes,
    report: Mapping[str, Any],
    capsule_path: Path,
    raw_capsule: bytes,
    capsule: Mapping[str, Any],
) -> dict[str, Any]:
    commit_path = activation_stage_pair_commit_path(receipt_path, mode=mode).absolute()
    loaded = _load_evidence(commit_path.parent, commit_path.name, {})
    _raw_commit, marker = _read_exact_release_gate_receipt(commit_path, loaded)
    if set(marker) != {
        "schema_version",
        "stage",
        "created_at",
        "release_gate_receipt",
        "stage_capsule",
        "pair_sha256",
        "publication_complete",
        "operator_supplied_scope_fields",
    }:
        raise EvidenceError(f"activation_{mode}_pair_commit_shape_invalid")
    material = _activation_stage_pair_material(
        mode=mode,
        receipt_path=receipt_path,
        raw_receipt=raw_receipt,
        report=report,
        capsule_path=capsule_path,
        raw_capsule=raw_capsule,
        capsule=capsule,
    )
    if (
        marker.get("schema_version") != ACTIVATION_STAGE_PAIR_COMMIT_SCHEMA_VERSION
        or marker.get("stage") != mode
        or marker.get("created_at") != report.get("evaluated_at")
        or marker.get("release_gate_receipt") != material["release_gate_receipt"]
        or marker.get("stage_capsule") != material["stage_capsule"]
        or marker.get("pair_sha256") != _sha256_json(material)
        or marker.get("publication_complete") is not True
        or marker.get("operator_supplied_scope_fields") != []
    ):
        raise EvidenceError(f"activation_{mode}_pair_commit_invalid")
    return dict(marker)


def write_activation_preauthorization_capsule(
    receipt_path: Path,
    report: Mapping[str, Any],
    *,
    evidence_dir: Path,
    control_db_path: Path,
) -> Path:
    fingerprint, checks = _validate_activation_stage_release_report(
        report,
        mode="preauthorization",
    )
    raw_receipt, receipt_binding = _stage_receipt_binding(receipt_path, report)
    if receipt_binding["report_fingerprint"] != fingerprint:
        raise EvidenceError("activation_preauthorization_receipt_binding_invalid")
    trusted_evidence_dir = evidence_dir.expanduser().absolute()
    directory_fd = _open_secure_evidence_directory(
        trusted_evidence_dir,
        artifact="activation_preauthorization_evidence",
    )
    os.close(directory_fd)
    material = _activation_stage_material(
        report,
        checks,
        evidence_dir=trusted_evidence_dir,
        control_db_path=control_db_path,
    )
    bootstrap = _mapping(
        checks["activation_bootstrap_runtime"].get("detail"),
        "activation_preauthorization.bootstrap",
    )
    gateway_binding = _mapping(
        bootstrap.get("gateway"), "activation_preauthorization.gateway"
    )
    activation_input = {
        "epoch_id": _stage_epoch_id(report, fingerprint),
        "initial_state": "safe_off",
        **material,
    }
    capsule = {
        "schema_version": ACTIVATION_PREAUTHORIZATION_CAPSULE_SCHEMA_VERSION,
        "created_at": _required_text(
            report.get("evaluated_at"), "activation_preauthorization.created_at"
        ),
        "evidence_directory": str(trusted_evidence_dir),
        "release_gate_receipt": receipt_binding,
        "activation_input": activation_input,
        "activation_input_sha256": _sha256_json(activation_input),
        "gateway_binding": dict(gateway_binding),
        "gateway_binding_sha256": _sha256_json(gateway_binding),
        "same_file_descriptor_verification_required": True,
    }
    destination = activation_preauthorization_capsule_path(receipt_path)
    write_receipt_no_clobber(
        destination,
        capsule,
        conflict_code="activation_preauthorization_capsule_conflict",
    )
    write_activation_stage_pair_commit(
        receipt_path,
        report,
        mode="preauthorization",
        capsule_path=destination,
    )
    if not raw_receipt:
        raise EvidenceError("activation_preauthorization_receipt_binding_invalid")
    return destination


def _load_owner_only_json(path: Path, *, artifact: str) -> tuple[bytes, dict[str, Any]]:
    candidate = path.expanduser().absolute()
    loaded = _load_evidence(candidate.parent, candidate.name, {})
    return _read_exact_release_gate_receipt(candidate, loaded)


def _read_activation_preauthorization_capsule_bundle(
    capsule_path: Path,
    *,
    control_db_path: Path,
    now: datetime,
    allowed_epoch_states: frozenset[str] = frozenset({"safe_off"}),
) -> dict[str, Any]:
    raw_capsule, capsule = _load_owner_only_json(
        capsule_path,
        artifact="activation_preauthorization_capsule",
    )
    if set(capsule) != {
        "schema_version",
        "created_at",
        "evidence_directory",
        "release_gate_receipt",
        "activation_input",
        "activation_input_sha256",
        "gateway_binding",
        "gateway_binding_sha256",
        "same_file_descriptor_verification_required",
    } or capsule.get("schema_version") != (
        ACTIVATION_PREAUTHORIZATION_CAPSULE_SCHEMA_VERSION
    ):
        raise EvidenceError("activation_preauthorization_capsule_shape_invalid")
    receipt_binding = _mapping(
        capsule.get("release_gate_receipt"),
        "activation_preauthorization.release_gate_receipt",
    )
    if set(receipt_binding) != {
        "path",
        "size_bytes",
        "raw_sha256",
        "report_fingerprint",
    }:
        raise EvidenceError("activation_preauthorization_receipt_binding_invalid")
    receipt_path = Path(
        _required_text(
            receipt_binding.get("path"), "activation_preauthorization.receipt_path"
        )
    ).expanduser().absolute()
    if capsule_path.expanduser().absolute() != activation_preauthorization_capsule_path(
        receipt_path
    ).absolute():
        raise EvidenceError("activation_preauthorization_capsule_path_invalid")
    raw_receipt, report = _load_owner_only_json(
        receipt_path,
        artifact="activation_preauthorization_receipt",
    )
    fingerprint, checks = _validate_activation_stage_release_report(
        report,
        mode="preauthorization",
    )
    if (
        receipt_binding.get("path") != str(receipt_path)
        or receipt_binding.get("size_bytes") != len(raw_receipt)
        or receipt_binding.get("raw_sha256")
        != hashlib.sha256(raw_receipt).hexdigest()
        or receipt_binding.get("report_fingerprint") != fingerprint
    ):
        raise EvidenceError("activation_preauthorization_receipt_binding_invalid")
    _read_activation_stage_pair_commit(
        mode="preauthorization",
        receipt_path=receipt_path,
        raw_receipt=raw_receipt,
        report=report,
        capsule_path=capsule_path,
        raw_capsule=raw_capsule,
        capsule=capsule,
    )
    _check_activation_capsule_freshness(
        report=report,
        capsule_created_at=capsule.get("created_at"),
        now=now,
        artifact="activation_preauthorization_capsule",
    )
    evidence_dir = Path(
        _required_text(
            capsule.get("evidence_directory"),
            "activation_preauthorization.evidence_directory",
        )
    ).expanduser().absolute()
    material = _activation_stage_material(
        report,
        checks,
        evidence_dir=evidence_dir,
        control_db_path=control_db_path,
    )
    expected_input = {
        "epoch_id": _stage_epoch_id(report, fingerprint),
        "initial_state": "safe_off",
        **material,
    }
    activation_input = _mapping(
        capsule.get("activation_input"), "activation_preauthorization.activation_input"
    )
    gateway_binding = _mapping(
        capsule.get("gateway_binding"), "activation_preauthorization.gateway_binding"
    )
    report_gateway = _mapping(
        _mapping(
            checks["activation_bootstrap_runtime"].get("detail"),
            "activation_preauthorization.bootstrap",
        ).get("gateway"),
        "activation_preauthorization.report_gateway",
    )
    if (
        dict(activation_input) != expected_input
        or capsule.get("activation_input_sha256") != _sha256_json(expected_input)
        or dict(gateway_binding) != dict(report_gateway)
        or capsule.get("gateway_binding_sha256") != _sha256_json(gateway_binding)
        or capsule.get("same_file_descriptor_verification_required") is not True
    ):
        raise EvidenceError("activation_preauthorization_capsule_binding_invalid")
    normalized = {
        **expected_input,
        "preauthorization_fingerprint": fingerprint,
        "preauthorization_gate_receipt_sha256": hashlib.sha256(
            raw_receipt
        ).hexdigest(),
        "preauthorization_capsule_sha256": hashlib.sha256(raw_capsule).hexdigest(),
    }
    database = _read_activation_bootstrap_database(control_db_path)
    if database.get("active_effect_count") != 0:
        raise EvidenceError("activation_preauthorization_database_not_pristine")
    if database.get("epoch_count") == 0:
        if database.get("current_epoch_count") != 0:
            raise EvidenceError("activation_preauthorization_database_not_pristine")
    else:
        current = _mapping(
            database.get("current_epoch"),
            "activation_preauthorization.current_epoch",
        )
        expected_current = {
            "epoch_id": normalized["epoch_id"],
            "preauthorization_fingerprint": normalized[
                "preauthorization_fingerprint"
            ],
            "preauthorization_gate_receipt_sha256": normalized[
                "preauthorization_gate_receipt_sha256"
            ],
            "preauthorization_capsule_sha256": normalized[
                "preauthorization_capsule_sha256"
            ],
            "config_sha256": normalized["config_sha256"],
            "db_logical_identity_sha256": normalized[
                "db_logical_identity_sha256"
            ],
            "partition_start_fence_sha256": normalized[
                "partition_start_fence_sha256"
            ],
        }
        if (
            database.get("epoch_count") != 1
            or database.get("current_epoch_count") != 1
            or current.get("state") not in allowed_epoch_states
            or any(current.get(key) != value for key, value in expected_current.items())
        ):
            raise EvidenceError("activation_preauthorization_epoch_binding_changed")
    _recheck_capsule_gateway_binding(gateway_binding)
    return {
        "normalized": normalized,
        "gateway_binding": dict(gateway_binding),
        "raw_capsule": raw_capsule,
        "capsule_path": str(capsule_path.expanduser().absolute()),
        "report": report,
    }


def read_activation_preauthorization_capsule(
    path: Path,
    *,
    control_db_path: Path,
) -> dict[str, Any]:
    bundle = _read_activation_preauthorization_capsule_bundle(
        path,
        control_db_path=control_db_path,
        now=datetime.now(timezone.utc),
    )
    return dict(_mapping(bundle.get("normalized"), "activation_preauthorization"))


def write_activation_preproduction_capsule(
    receipt_path: Path,
    report: Mapping[str, Any],
    *,
    evidence_dir: Path,
    control_db_path: Path,
    preauthorization_capsule: Path,
) -> Path:
    fingerprint, checks = _validate_activation_stage_release_report(
        report,
        mode="preproduction",
    )
    _raw_receipt, receipt_binding = _stage_receipt_binding(receipt_path, report)
    if receipt_binding["report_fingerprint"] != fingerprint:
        raise EvidenceError("activation_preproduction_receipt_binding_invalid")
    trusted_evidence_dir = evidence_dir.expanduser().absolute()
    directory_fd = _open_secure_evidence_directory(
        trusted_evidence_dir,
        artifact="activation_preproduction_evidence",
    )
    os.close(directory_fd)
    material = _activation_stage_material(
        report,
        checks,
        evidence_dir=trusted_evidence_dir,
        control_db_path=control_db_path,
    )
    prior = _read_activation_preauthorization_capsule_bundle(
        preauthorization_capsule,
        control_db_path=control_db_path,
        now=_timestamp(report.get("evaluated_at"), "activation_preproduction.now"),
    )
    prior_input = _mapping(prior.get("normalized"), "activation_preproduction.prior")
    for field in (
        "config_sha256",
        "db_logical_identity_sha256",
        "partition_start_fence_sha256",
        "migration_receipt_raw_sha256",
        "materialization_receipt_raw_sha256",
        "broker_t0_observation_sha256",
        "canary_plan_raw_sha256",
    ):
        if material.get(field) != prior_input.get(field):
            raise EvidenceError("activation_preproduction_scope_changed")
    activation = _mapping(
        checks["activation_epoch"].get("detail"),
        "activation_preproduction.activation",
    )
    expected_prior = {
        "preauthorization_fingerprint": prior_input[
            "preauthorization_fingerprint"
        ],
        "preauthorization_gate_receipt_sha256": prior_input[
            "preauthorization_gate_receipt_sha256"
        ],
        "preauthorization_capsule_sha256": prior_input[
            "preauthorization_capsule_sha256"
        ],
        "config_sha256": prior_input["config_sha256"],
        "db_logical_identity_sha256": prior_input["db_logical_identity_sha256"],
        "partition_start_fence_sha256": prior_input[
            "partition_start_fence_sha256"
        ],
    }
    if (
        activation.get("epoch_id") != prior_input.get("epoch_id")
        or activation.get("state") != "safe_off"
        or any(activation.get(key) != value for key, value in expected_prior.items())
    ):
        raise EvidenceError("activation_preproduction_epoch_binding_changed")
    bootstrap = _mapping(
        checks["activation_bootstrap_runtime"].get("detail"),
        "activation_preproduction.bootstrap",
    )
    gateway_binding = _mapping(
        bootstrap.get("gateway"), "activation_preproduction.gateway"
    )
    prior_gateway = _mapping(
        prior.get("gateway_binding"), "activation_preproduction.prior_gateway"
    )
    if gateway_binding != prior_gateway:
        raise EvidenceError("activation_preproduction_gateway_restarted")
    canary_detail = _mapping(
        checks["canary_plan"].get("detail"),
        "activation_preproduction.canary_plan",
    )
    canary_slots = _mapping(
        canary_detail.get("slots"),
        "activation_preproduction.canary_plan.slots",
    )
    if (
        canary_detail.get("admission_mode") != "direct_bounded"
        or canary_detail.get("promotion_budget") != 0
        or canary_detail.get("slot_count") != len(REQUIRED_ACTIVATION_SLOTS)
        or set(canary_slots) != set(REQUIRED_ACTIVATION_SLOTS)
        or canary_detail.get("slots_sha256") != _sha256_json(canary_slots)
    ):
        raise EvidenceError("activation_preproduction_canary_plan_invalid")
    canary_slot_plan = {
        slot_kind: dict(
            _mapping(
                canary_slots[slot_kind],
                f"activation_preproduction.canary_plan.{slot_kind}",
            )
        )
        for slot_kind in sorted(REQUIRED_ACTIVATION_SLOTS)
    }
    transition_input = {
        "epoch_id": prior_input["epoch_id"],
        "expected_state": "safe_off",
        "target_state": "preauthorized",
        "expected_preauthorization_fingerprint": prior_input[
            "preauthorization_fingerprint"
        ],
        "expected_preauthorization_gate_receipt_sha256": prior_input[
            "preauthorization_gate_receipt_sha256"
        ],
        "expected_preauthorization_capsule_sha256": prior_input[
            "preauthorization_capsule_sha256"
        ],
        "expected_config_sha256": prior_input["config_sha256"],
        "expected_db_logical_identity_sha256": prior_input[
            "db_logical_identity_sha256"
        ],
        "expected_partition_start_fence_sha256": prior_input[
            "partition_start_fence_sha256"
        ],
        "canary_slot_plan": canary_slot_plan,
        "canary_slot_plan_sha256": _sha256_json(canary_slot_plan),
    }
    capsule = {
        "schema_version": ACTIVATION_PREPRODUCTION_CAPSULE_SCHEMA_VERSION,
        "created_at": _required_text(
            report.get("evaluated_at"), "activation_preproduction.created_at"
        ),
        "evidence_directory": str(trusted_evidence_dir),
        "release_gate_receipt": receipt_binding,
        "preauthorization_capsule": {
            "path": str(preauthorization_capsule.expanduser().absolute()),
            "size_bytes": len(prior["raw_capsule"]),
            "raw_sha256": hashlib.sha256(prior["raw_capsule"]).hexdigest(),
        },
        "transition_input": transition_input,
        "transition_input_sha256": _sha256_json(transition_input),
        "gateway_binding": dict(gateway_binding),
        "gateway_binding_sha256": _sha256_json(gateway_binding),
        "same_file_descriptor_verification_required": True,
    }
    destination = activation_preproduction_capsule_path(receipt_path)
    write_receipt_no_clobber(
        destination,
        capsule,
        conflict_code="activation_preproduction_capsule_conflict",
    )
    write_activation_stage_pair_commit(
        receipt_path,
        report,
        mode="preproduction",
        capsule_path=destination,
    )
    return destination


def _read_activation_preproduction_capsule_bundle(
    capsule_path: Path,
    *,
    control_db_path: Path,
    current_activation: Mapping[str, Any],
    now: datetime,
    allowed_current_states: frozenset[str] = frozenset(
        {"safe_off", "preauthorized"}
    ),
) -> dict[str, Any]:
    raw_capsule, capsule = _load_owner_only_json(
        capsule_path,
        artifact="activation_preproduction_capsule",
    )
    if set(capsule) != {
        "schema_version",
        "created_at",
        "evidence_directory",
        "release_gate_receipt",
        "preauthorization_capsule",
        "transition_input",
        "transition_input_sha256",
        "gateway_binding",
        "gateway_binding_sha256",
        "same_file_descriptor_verification_required",
    } or capsule.get("schema_version") != ACTIVATION_PREPRODUCTION_CAPSULE_SCHEMA_VERSION:
        raise EvidenceError("activation_preproduction_capsule_shape_invalid")
    receipt_binding = _mapping(
        capsule.get("release_gate_receipt"),
        "activation_preproduction.release_gate_receipt",
    )
    receipt_path = Path(
        _required_text(
            receipt_binding.get("path"), "activation_preproduction.receipt_path"
        )
    ).expanduser().absolute()
    if capsule_path.expanduser().absolute() != activation_preproduction_capsule_path(
        receipt_path
    ).absolute():
        raise EvidenceError("activation_preproduction_capsule_path_invalid")
    raw_receipt, report = _load_owner_only_json(
        receipt_path,
        artifact="activation_preproduction_receipt",
    )
    fingerprint, checks = _validate_activation_stage_release_report(
        report,
        mode="preproduction",
    )
    if (
        set(receipt_binding)
        != {"path", "size_bytes", "raw_sha256", "report_fingerprint"}
        or receipt_binding.get("path") != str(receipt_path)
        or receipt_binding.get("size_bytes") != len(raw_receipt)
        or receipt_binding.get("raw_sha256")
        != hashlib.sha256(raw_receipt).hexdigest()
        or receipt_binding.get("report_fingerprint") != fingerprint
    ):
        raise EvidenceError("activation_preproduction_receipt_binding_invalid")
    _read_activation_stage_pair_commit(
        mode="preproduction",
        receipt_path=receipt_path,
        raw_receipt=raw_receipt,
        report=report,
        capsule_path=capsule_path,
        raw_capsule=raw_capsule,
        capsule=capsule,
    )
    _check_activation_capsule_freshness(
        report=report,
        capsule_created_at=capsule.get("created_at"),
        now=now,
        artifact="activation_preproduction_capsule",
    )
    evidence_dir = Path(
        _required_text(
            capsule.get("evidence_directory"),
            "activation_preproduction.evidence_directory",
        )
    ).expanduser().absolute()
    material = _activation_stage_material(
        report,
        checks,
        evidence_dir=evidence_dir,
        control_db_path=control_db_path,
    )
    prior_binding = _mapping(
        capsule.get("preauthorization_capsule"),
        "activation_preproduction.preauthorization_capsule",
    )
    if set(prior_binding) != {"path", "size_bytes", "raw_sha256"}:
        raise EvidenceError("activation_preproduction_preauthorization_invalid")
    prior_path = Path(
        _required_text(prior_binding.get("path"), "activation_preproduction.prior_path")
    ).expanduser().absolute()
    prior = _read_activation_preauthorization_capsule_bundle(
        prior_path,
        control_db_path=control_db_path,
        now=now,
        allowed_epoch_states=frozenset({str(current_activation.get("state") or "")}),
    )
    if (
        prior_binding.get("size_bytes") != len(prior["raw_capsule"])
        or prior_binding.get("raw_sha256")
        != hashlib.sha256(prior["raw_capsule"]).hexdigest()
    ):
        raise EvidenceError("activation_preproduction_preauthorization_invalid")
    prior_input = _mapping(prior.get("normalized"), "activation_preproduction.prior")
    for field in (
        "config_sha256",
        "db_logical_identity_sha256",
        "partition_start_fence_sha256",
        "migration_receipt_raw_sha256",
        "materialization_receipt_raw_sha256",
        "broker_t0_observation_sha256",
        "canary_plan_raw_sha256",
    ):
        expected = (
            prior_input[field]
            if field in prior_input
            else None
        )
        if material.get(field) != expected:
            raise EvidenceError("activation_preproduction_scope_changed")
    expected_transition = {
        "epoch_id": prior_input["epoch_id"],
        "expected_state": "safe_off",
        "target_state": "preauthorized",
        "expected_preauthorization_fingerprint": prior_input[
            "preauthorization_fingerprint"
        ],
        "expected_preauthorization_gate_receipt_sha256": prior_input[
            "preauthorization_gate_receipt_sha256"
        ],
        "expected_preauthorization_capsule_sha256": prior_input[
            "preauthorization_capsule_sha256"
        ],
        "expected_config_sha256": prior_input["config_sha256"],
        "expected_db_logical_identity_sha256": prior_input[
            "db_logical_identity_sha256"
        ],
        "expected_partition_start_fence_sha256": prior_input[
            "partition_start_fence_sha256"
        ],
    }
    canary_detail = _mapping(
        checks["canary_plan"].get("detail"),
        "activation_preproduction.canary_plan",
    )
    canary_slots = _mapping(
        canary_detail.get("slots"),
        "activation_preproduction.canary_plan.slots",
    )
    if (
        canary_detail.get("admission_mode") != "direct_bounded"
        or canary_detail.get("promotion_budget") != 0
        or canary_detail.get("slot_count") != len(REQUIRED_ACTIVATION_SLOTS)
        or set(canary_slots) != set(REQUIRED_ACTIVATION_SLOTS)
        or canary_detail.get("slots_sha256") != _sha256_json(canary_slots)
    ):
        raise EvidenceError("activation_preproduction_canary_plan_invalid")
    canary_slot_plan = {
        slot_kind: dict(
            _mapping(
                canary_slots[slot_kind],
                f"activation_preproduction.canary_plan.{slot_kind}",
            )
        )
        for slot_kind in sorted(REQUIRED_ACTIVATION_SLOTS)
    }
    expected_transition.update(
        {
            "canary_slot_plan": canary_slot_plan,
            "canary_slot_plan_sha256": _sha256_json(canary_slot_plan),
        }
    )
    transition = _mapping(
        capsule.get("transition_input"), "activation_preproduction.transition_input"
    )
    gateway_binding = _mapping(
        capsule.get("gateway_binding"), "activation_preproduction.gateway_binding"
    )
    report_gateway = _mapping(
        _mapping(
            checks["activation_bootstrap_runtime"].get("detail"),
            "activation_preproduction.bootstrap",
        ).get("gateway"),
        "activation_preproduction.report_gateway",
    )
    if (
        dict(transition) != expected_transition
        or capsule.get("transition_input_sha256")
        != _sha256_json(expected_transition)
        or dict(gateway_binding) != dict(report_gateway)
        or capsule.get("gateway_binding_sha256") != _sha256_json(gateway_binding)
        or capsule.get("same_file_descriptor_verification_required") is not True
    ):
        raise EvidenceError("activation_preproduction_capsule_binding_invalid")
    normalized = {
        **expected_transition,
        "preproduction_fingerprint": fingerprint,
        "preproduction_gate_receipt_sha256": hashlib.sha256(raw_receipt).hexdigest(),
        "preproduction_capsule_sha256": hashlib.sha256(raw_capsule).hexdigest(),
    }
    expected_current = {
        "epoch_id": normalized["epoch_id"],
        "preauthorization_fingerprint": normalized[
            "expected_preauthorization_fingerprint"
        ],
        "preauthorization_gate_receipt_sha256": normalized[
            "expected_preauthorization_gate_receipt_sha256"
        ],
        "preauthorization_capsule_sha256": normalized[
            "expected_preauthorization_capsule_sha256"
        ],
        "config_sha256": normalized["expected_config_sha256"],
        "db_logical_identity_sha256": normalized[
            "expected_db_logical_identity_sha256"
        ],
        "partition_start_fence_sha256": normalized[
            "expected_partition_start_fence_sha256"
        ],
    }
    if any(current_activation.get(key) != value for key, value in expected_current.items()):
        raise EvidenceError("activation_preproduction_epoch_binding_changed")
    state = current_activation.get("state")
    if state not in allowed_current_states:
        raise EvidenceError("activation_preproduction_state_changed")
    if state != "safe_off":
        if any(
            current_activation.get(field) != normalized[field]
            for field in (
                "preproduction_fingerprint",
                "preproduction_gate_receipt_sha256",
                "preproduction_capsule_sha256",
            )
        ):
            raise EvidenceError("activation_preproduction_binding_conflict")
    database = _read_activation_bootstrap_database(control_db_path)
    live_current = _mapping(
        database.get("current_epoch"), "activation_preproduction.live_epoch"
    )
    if (
        database.get("current_epoch_count") != 1
        or database.get("active_effect_count") != 0
        or live_current.get("epoch_id") != normalized["epoch_id"]
        or live_current.get("state") != state
    ):
        raise EvidenceError("activation_preproduction_database_changed")
    _recheck_capsule_gateway_binding(gateway_binding)
    return {
        "normalized": normalized,
        "gateway_binding": dict(gateway_binding),
        "canary_plan_raw_sha256": _sha256_digest(
            prior_input.get("canary_plan_raw_sha256"),
            "activation_preproduction.canary_plan_raw_sha256",
        ),
        "raw_capsule": raw_capsule,
        "capsule_path": str(capsule_path.expanduser().absolute()),
        "report": report,
    }


def read_activation_preproduction_capsule(
    path: Path,
    *,
    control_db_path: Path,
    current_activation: Mapping[str, Any],
    allowed_current_states: frozenset[str] = frozenset(
        {"safe_off", "preauthorized"}
    ),
) -> dict[str, Any]:
    bundle = _read_activation_preproduction_capsule_bundle(
        path,
        control_db_path=control_db_path,
        current_activation=current_activation,
        now=datetime.now(timezone.utc),
        allowed_current_states=allowed_current_states,
    )
    return dict(_mapping(bundle.get("normalized"), "activation_preproduction"))


def _publish_or_resume_activation_stage(
    *,
    mode: str,
    receipt_path: Path,
    report: Mapping[str, Any] | None,
    evidence_dir: Path,
    control_db_path: Path,
    consumer: ConsumerConfig,
    dispatcher: DispatcherConfig,
    cutover: CutoverConfig,
    preauthorization_capsule: Path | None = None,
) -> dict[str, Any] | None:
    if mode not in {"preauthorization", "preproduction"}:
        raise EvidenceError("activation_stage_mode_invalid")
    receipt_file = receipt_path.expanduser().absolute()
    capsule_file = (
        activation_preauthorization_capsule_path(receipt_file)
        if mode == "preauthorization"
        else activation_preproduction_capsule_path(receipt_file)
    ).absolute()
    commit_file = activation_stage_pair_commit_path(
        receipt_file,
        mode=mode,
    ).absolute()
    members_exist = tuple(
        _path_lexists(path) for path in (receipt_file, capsule_file, commit_file)
    )
    if not any(members_exist) and report is None:
        return None
    if not members_exist[0] and any(members_exist[1:]):
        raise EvidenceError(f"activation_{mode}_orphan_publication")

    if members_exist[0]:
        with _activation_publication_lock(receipt_file):
            _recover_existing_no_clobber_member(
                receipt_file,
                conflict_code=f"{mode}_release_gate_receipt_conflict",
            )
        loaded_report = _load_evidence(receipt_file.parent, receipt_file.name, {})
        _validate_activation_stage_release_report(loaded_report, mode=mode)
        _read_exact_release_gate_receipt(receipt_file, loaded_report)
        selected_report = loaded_report
        if report is not None and dict(report) != selected_report:
            raise EvidenceError(f"{mode}_release_gate_receipt_conflict")
    else:
        if report is None:
            raise EvidenceError(f"activation_{mode}_receipt_missing")
        selected_report = dict(report)
        _validate_activation_stage_release_report(selected_report, mode=mode)
        write_receipt_no_clobber(
            receipt_file,
            selected_report,
            conflict_code=f"{mode}_release_gate_receipt_conflict",
        )

    if selected_report.get("config") != _public_config(
        consumer,
        dispatcher,
        cutover,
    ):
        raise EvidenceError(f"activation_{mode}_runtime_config_changed")
    if all(members_exist):
        database = _read_activation_bootstrap_database(control_db_path)
        current_value = database.get("current_epoch")
        allowed_states = frozenset({"safe_off"})
        if current_value is not None:
            current = _mapping(
                current_value,
                f"activation_{mode}.current_epoch",
            )
            allowed_states = frozenset({str(current.get("state") or "")})
        if mode == "preauthorization":
            _read_activation_preauthorization_capsule_bundle(
                capsule_file,
                control_db_path=control_db_path,
                now=datetime.now(timezone.utc),
                allowed_epoch_states=allowed_states,
            )
        else:
            if current_value is None:
                raise EvidenceError("activation_preproduction_epoch_missing")
            _read_activation_preproduction_capsule_bundle(
                capsule_file,
                control_db_path=control_db_path,
                current_activation=current,
                now=datetime.now(timezone.utc),
                allowed_current_states=allowed_states,
            )
        return selected_report
    if mode == "preauthorization":
        capsule_file = write_activation_preauthorization_capsule(
            receipt_file,
            selected_report,
            evidence_dir=evidence_dir,
            control_db_path=control_db_path,
        )
        _read_activation_preauthorization_capsule_bundle(
            capsule_file,
            control_db_path=control_db_path,
            now=datetime.now(timezone.utc),
        )
    else:
        if preauthorization_capsule is None:
            raise EvidenceError("activation_preauthorization_capsule_required")
        capsule_file = write_activation_preproduction_capsule(
            receipt_file,
            selected_report,
            evidence_dir=evidence_dir,
            control_db_path=control_db_path,
            preauthorization_capsule=preauthorization_capsule,
        )
        database = _read_activation_bootstrap_database(control_db_path)
        current = _mapping(
            database.get("current_epoch"),
            "activation_preproduction.current_epoch",
        )
        _read_activation_preproduction_capsule_bundle(
            capsule_file,
            control_db_path=control_db_path,
            current_activation=current,
            now=datetime.now(timezone.utc),
            allowed_current_states=frozenset({str(current.get("state") or "")}),
        )
    return selected_report


def _validated_activation_ingress_freeze_binding(
    value: Any,
    *,
    expected_epoch_id: str,
    expected_health_path: Path,
) -> dict[str, Any]:
    binding = _mapping(value, "activation_confirmation.ingress_freeze_binding")
    if set(binding) != {
        "schema_version",
        "epoch_id",
        "health_path",
        "paused_at",
        "freeze_receipt_sha256",
        "freeze_token_sha256",
        "consumer_runtime_identity_sha256",
        "partition_positions_sha256",
        "restart_required",
    }:
        raise EvidenceError("activation_confirmation_freeze_binding_invalid")
    _timestamp(
        binding.get("paused_at"),
        "activation_confirmation.ingress_freeze_binding.paused_at",
    )
    normalized_health_path = str(expected_health_path.expanduser().absolute())
    if (
        binding.get("schema_version")
        != "pnc_rca_activation_ingress_freeze_binding_v1"
        or binding.get("epoch_id") != expected_epoch_id
        or binding.get("health_path") != normalized_health_path
        or binding.get("restart_required") is not False
    ):
        raise EvidenceError("activation_confirmation_freeze_binding_invalid")
    for name in (
        "freeze_receipt_sha256",
        "freeze_token_sha256",
        "consumer_runtime_identity_sha256",
        "partition_positions_sha256",
    ):
        _sha256_digest(
            binding.get(name),
            f"activation_confirmation.ingress_freeze_binding.{name}",
        )
    return dict(binding)


def _validate_production_release_report(report: Mapping[str, Any]) -> str:
    if set(report) != {
        "schema_version",
        "evaluated_at",
        "mode",
        "ok",
        "fingerprint",
        "config",
        "gate_policy",
        "checks",
        "blockers",
        "warnings",
        "evidence_sha256",
    }:
        raise EvidenceError("activation_confirmation_report_shape_invalid")
    _timestamp(report.get("evaluated_at"), "activation_confirmation.evaluated_at")
    raw_checks = report.get("checks")
    if not isinstance(raw_checks, list):
        raise EvidenceError("activation_confirmation_checks_invalid")
    report_mode = str(report.get("mode") or "")
    if report_mode not in PRODUCTION_MODES:
        raise EvidenceError("activation_confirmation_checks_invalid")
    expected_check_names = set(PRODUCTION_RELEASE_CHECK_NAMES)
    if report_mode == "production_bootstrap":
        expected_check_names.add("bootstrap_capacity_authorization")
    checks = [
        _mapping(item, f"activation_confirmation.checks.{index}")
        for index, item in enumerate(raw_checks)
    ]
    if (
        len(checks) != len(expected_check_names)
        or {str(item.get("name") or "") for item in checks}
        != expected_check_names
        or any(set(item) != {"name", "ok", "code", "detail"} for item in checks)
        or any(item.get("ok") is not True or item.get("code") != "pass" for item in checks)
        or report.get("blockers") != []
        or report.get("warnings") != []
        or report.get("ok") is not True
        or report.get("schema_version") != RELEASE_GATE_SCHEMA_VERSION
    ):
        raise EvidenceError("activation_confirmation_checks_invalid")
    by_name = {str(item["name"]): item for item in checks}
    config = _mapping(report.get("config"), "activation_confirmation.config")
    consumer = _mapping(config.get("consumer"), "activation_confirmation.consumer")
    policy = _mapping(
        consumer.get("policy"), "activation_confirmation.consumer.policy"
    )
    contract = _mapping(
        by_name["contract_drift"].get("detail"),
        "activation_confirmation.contract_drift",
    )
    activation = _mapping(
        by_name["activation_epoch"].get("detail"),
        "activation_confirmation.activation_epoch",
    )
    candidate = _mapping(
        by_name["activation_production_candidate"].get("detail"),
        "activation_confirmation.activation_candidate",
    )
    canaries = _mapping(
        by_name["activation_canary_bindings"].get("detail"),
        "activation_confirmation.activation_canaries",
    )
    barrier = _mapping(
        by_name["activation_writer_barrier"].get("detail"),
        "activation_confirmation.activation_barrier",
    )
    candidate_confirm = _mapping(
        candidate.get("confirm_input"),
        "activation_confirmation.candidate_confirm_input",
    )
    barrier_confirm = _mapping(
        barrier.get("confirm_input"),
        "activation_confirmation.barrier_confirm_input",
    )
    expected_health_path = Path(
        _required_text(
            consumer.get("health_path"),
            "activation_confirmation.consumer.health_path",
        )
    )
    candidate_freeze_binding = _validated_activation_ingress_freeze_binding(
        candidate.get("ingress_freeze_binding"),
        expected_epoch_id=_required_text(
            candidate_confirm.get("epoch_id"),
            "activation_confirmation.candidate_confirm_input.epoch_id",
        ),
        expected_health_path=expected_health_path,
    )
    barrier_freeze_binding = _validated_activation_ingress_freeze_binding(
        barrier.get("ingress_freeze_binding"),
        expected_epoch_id=_required_text(
            barrier_confirm.get("epoch_id"),
            "activation_confirmation.barrier_confirm_input.epoch_id",
        ),
        expected_health_path=expected_health_path,
    )
    if (
        activation.get("state") != "bounded_active"
        or candidate.get("ingress_frozen") is not True
        or canaries.get("slot_count") != len(REQUIRED_ACTIVATION_SLOTS)
        or barrier.get("state") != "bounded_active"
        or barrier.get("transition_performed") is not False
        or barrier.get("production_confirmation_required") is not True
        or candidate_confirm != barrier_confirm
        or candidate_freeze_binding != barrier_freeze_binding
        or candidate.get("confirm_input_sha256") != _sha256_json(candidate_confirm)
        or barrier.get("confirm_input_sha256") != _sha256_json(barrier_confirm)
        or barrier.get("release_binding_sha256")
        != activation.get("release_binding_sha256")
    ):
        raise EvidenceError("activation_confirmation_binding_invalid")
    expected_topic = _required_text(
        consumer.get("topic"), "activation_confirmation.consumer.topic"
    )
    expected_rule_version = _required_text(
        policy.get("policy_version"),
        "activation_confirmation.consumer.policy_version",
    )
    fingerprint_input = {
        "schema_version": RELEASE_GATE_SCHEMA_VERSION,
        "mode": report_mode,
        "expected_topic": expected_topic,
        "expected_rule_version": expected_rule_version,
        "config": dict(config),
        "gate_policy": dict(
            _mapping(report.get("gate_policy"), "activation_confirmation.gate_policy")
        ),
        "contract": dict(contract),
        "evidence_sha256": dict(
            sorted(
                _mapping(
                    report.get("evidence_sha256"),
                    "activation_confirmation.evidence_sha256",
                ).items()
            )
        ),
        "checks": [dict(item) for item in checks],
        "blockers": [],
        "warnings": [],
    }
    fingerprint = _sha256_digest(
        report.get("fingerprint"), "activation_confirmation.fingerprint"
    )
    if fingerprint != _sha256_json(fingerprint_input):
        raise EvidenceError("activation_confirmation_fingerprint_invalid")
    return fingerprint


def _production_check_detail(
    report: Mapping[str, Any],
    name: str,
    *,
    artifact: str,
) -> dict[str, Any]:
    matches = [
        item
        for item in report.get("checks", ())
        if isinstance(item, Mapping) and item.get("name") == name
    ]
    if len(matches) != 1 or matches[0].get("ok") is not True:
        raise EvidenceError(f"{artifact}_missing")
    return dict(_mapping(matches[0].get("detail"), artifact))


def _confirmation_runtime_continuity_binding(
    report: Mapping[str, Any],
) -> dict[str, Any]:
    bootstrap = _production_check_detail(
        report,
        "activation_bootstrap_runtime",
        artifact="activation_confirmation_bootstrap_runtime",
    )
    gateway = _mapping(
        bootstrap.get("gateway"), "activation_confirmation.gateway"
    )
    if gateway.get("state") != "running_safe":
        raise EvidenceError("activation_confirmation_gateway_binding_invalid")
    health = _production_check_detail(
        report,
        "delivery_service_health",
        artifact="activation_confirmation_delivery_service_health",
    )
    residents = _project_resident_runtime_bindings(
        health,
        artifact="activation_confirmation_residents",
    )
    barrier = _production_check_detail(
        report,
        "manual_gateway_runtime_barrier",
        artifact="activation_confirmation_manual_runtime_barrier",
    )
    barrier_residents = _mapping(
        barrier.get("resident_runtime_binding"),
        "activation_confirmation_manual_runtime_barrier.residents",
    )
    gateway_verification_fields = (
        "host_commit",
        "critical_files_sha256",
        "runtime_identity_sha256",
        "runtime_files_sha256",
        "public_config_sha256",
        "plist_sha256",
        "interpreter_sha256",
        "process_executable_sha256",
        "module_origins_sha256",
        "loaded_runtime_sha256",
        "dependency_files_sha256",
        "pid",
        "process_create_time",
        "launchctl_config_sha256",
    )
    gateway_verification = {
        field: barrier.get(field) for field in gateway_verification_fields
    }
    _commit_sha(
        gateway_verification.get("host_commit"),
        "activation_confirmation.gateway_verification.host_commit",
    )
    for field in (
        "critical_files_sha256",
        "runtime_identity_sha256",
        "runtime_files_sha256",
        "public_config_sha256",
        "plist_sha256",
        "interpreter_sha256",
        "process_executable_sha256",
        "module_origins_sha256",
        "loaded_runtime_sha256",
        "dependency_files_sha256",
        "launchctl_config_sha256",
    ):
        _sha256_digest(
            gateway_verification.get(field),
            f"activation_confirmation.gateway_verification.{field}",
        )
    if (
        dict(barrier_residents) != residents
        or barrier.get("resident_runtime_sha256") != _sha256_json(residents)
        or gateway_verification.get("runtime_identity_sha256")
        != gateway.get("runtime_identity_sha256")
        or gateway_verification.get("pid") != gateway.get("pid")
        or gateway_verification.get("process_create_time")
        != gateway.get("process_create_time")
    ):
        raise EvidenceError("activation_confirmation_runtime_binding_invalid")
    return {
        "gateway": dict(gateway),
        "gateway_verification": gateway_verification,
        "residents": residents,
        "residents_sha256": _sha256_json(residents),
    }


def _recheck_confirmation_runtime_continuity(
    value: Mapping[str, Any],
    *,
    report: Mapping[str, Any],
    now: datetime,
) -> None:
    binding = _mapping(value, "activation_confirmation.runtime_continuity")
    expected = _confirmation_runtime_continuity_binding(report)
    if dict(binding) != expected:
        raise EvidenceError("activation_confirmation_runtime_binding_invalid")
    _recheck_capsule_gateway_binding(
        _mapping(binding.get("gateway"), "activation_confirmation.gateway")
    )
    runtime = _production_check_detail(
        report,
        "runtime_dependencies",
        artifact="activation_confirmation_runtime_dependencies",
    )
    fresh_health = _check_delivery_service_health(
        _mapping(
            runtime.get("service_configs"),
            "activation_confirmation.runtime.service_configs",
        ),
        _mapping(
            runtime.get("service_processes"),
            "activation_confirmation.runtime.service_processes",
        ),
        _mapping(
            runtime.get("service_dependencies"),
            "activation_confirmation.runtime.service_dependencies",
        ),
        now=now,
    )
    fresh_residents = _project_resident_runtime_bindings(
        fresh_health,
        artifact="activation_confirmation_live_residents",
    )
    if (
        fresh_residents != binding.get("residents")
        or _sha256_json(fresh_residents) != binding.get("residents_sha256")
    ):
        raise EvidenceError("activation_confirmation_resident_restarted")


def write_activation_confirmation_capsule(
    receipt_path: Path,
    report: Mapping[str, Any],
) -> Path:
    validated_fingerprint = _validate_production_release_report(report)
    matching = [
        item
        for item in report.get("checks", ())
        if isinstance(item, Mapping)
        and item.get("name") == "activation_writer_barrier"
    ]
    if len(matching) != 1 or matching[0].get("ok") is not True:
        raise EvidenceError("activation_confirmation_barrier_missing")
    detail = _mapping(
        matching[0].get("detail"), "activation_confirmation.barrier"
    )
    confirm = _mapping(
        detail.get("confirm_input"), "activation_confirmation.confirm_input"
    )
    ingress_freeze_binding = _mapping(
        detail.get("ingress_freeze_binding"),
        "activation_confirmation.ingress_freeze_binding",
    )
    if (
        detail.get("state") != "bounded_active"
        or detail.get("production_confirmation_required") is not True
        or confirm.get("expected_state") != "bounded_active"
        or confirm.get("target_state") != "confirmed"
        or detail.get("confirm_input_sha256") != _sha256_json(confirm)
    ):
        raise EvidenceError("activation_confirmation_barrier_invalid")
    raw_receipt, receipt_body = _read_exact_release_gate_receipt(
        receipt_path,
        report,
    )
    receipt_sha256 = hashlib.sha256(raw_receipt).hexdigest()
    production_fingerprint = _sha256_digest(
        receipt_body.get("fingerprint"),
        "activation_confirmation.production_fingerprint",
    )
    if production_fingerprint != validated_fingerprint:
        raise EvidenceError("activation_confirmation_fingerprint_invalid")
    runtime_continuity = _confirmation_runtime_continuity_binding(report)
    transition_input = {
        "epoch_id": _required_text(
            confirm.get("epoch_id"), "activation_confirmation.epoch_id"
        ),
        "expected_state": "bounded_active",
        "target_state": "confirmed",
        "config_sha256": _sha256_digest(
            confirm.get("config_sha256"),
            "activation_confirmation.config_sha256",
        ),
        "db_logical_identity_sha256": _sha256_digest(
            confirm.get("db_logical_identity_sha256"),
            "activation_confirmation.db_logical_identity_sha256",
        ),
        "partition_start_fence_sha256": _sha256_digest(
            confirm.get("partition_start_fence_sha256"),
            "activation_confirmation.partition_start_fence_sha256",
        ),
        "release_binding_sha256": _sha256_digest(
            confirm.get("release_binding_sha256"),
            "activation_confirmation.release_binding_sha256",
        ),
        "partition_end_fence": dict(
            _mapping(
                confirm.get("partition_end_fence"),
                "activation_confirmation.partition_end_fence",
            )
        ),
        "partition_end_fence_sha256": _sha256_digest(
            confirm.get("partition_end_fence_sha256"),
            "activation_confirmation.partition_end_fence_sha256",
        ),
        "production_fingerprint": production_fingerprint,
        "production_gate_receipt_sha256": receipt_sha256,
    }
    if (
        _sha256_json(transition_input["partition_end_fence"])
        != transition_input["partition_end_fence_sha256"]
        or confirm.get("restart_between_gate_and_confirm") is not False
    ):
        raise EvidenceError("activation_confirmation_end_fence_invalid")
    capsule = {
        "schema_version": ACTIVATION_CONFIRMATION_CAPSULE_SCHEMA_VERSION,
        "created_at": _required_text(
            receipt_body.get("evaluated_at"),
            "activation_confirmation.created_at",
        ),
        "release_gate_receipt": {
            "path": str(receipt_path.expanduser().absolute()),
            "size_bytes": len(raw_receipt),
            "raw_sha256": receipt_sha256,
            "report_fingerprint": production_fingerprint,
        },
        "ingress_freeze_binding": dict(ingress_freeze_binding),
        "runtime_continuity_binding": runtime_continuity,
        "transition_input": transition_input,
        "transition_input_sha256": _sha256_json(transition_input),
        "operator_supplied_scope_fields": [],
        "same_file_descriptor_verification_required": True,
    }
    destination = activation_confirmation_capsule_path(receipt_path)
    write_receipt_no_clobber(
        destination,
        capsule,
        conflict_code="activation_confirmation_capsule_conflict",
    )
    return destination


def _activation_confirmation_pair_material(
    *,
    receipt_path: Path,
    raw_receipt: bytes,
    report: Mapping[str, Any],
    capsule_path: Path,
    raw_capsule: bytes,
    capsule: Mapping[str, Any],
) -> dict[str, Any]:
    receipt_file = receipt_path.expanduser().absolute()
    capsule_file = capsule_path.expanduser().absolute()
    expected_capsule = activation_confirmation_capsule_path(receipt_file).absolute()
    transition = _mapping(
        capsule.get("transition_input"),
        "activation_confirmation_pair.transition_input",
    )
    receipt_binding = _mapping(
        capsule.get("release_gate_receipt"),
        "activation_confirmation_pair.release_gate_receipt",
    )
    report_fingerprint = _sha256_digest(
        report.get("fingerprint"),
        "activation_confirmation_pair.report_fingerprint",
    )
    receipt_raw_sha256 = hashlib.sha256(raw_receipt).hexdigest()
    if (
        capsule_file != expected_capsule
        or capsule.get("schema_version")
        != ACTIVATION_CONFIRMATION_CAPSULE_SCHEMA_VERSION
        or capsule.get("transition_input_sha256") != _sha256_json(transition)
        or receipt_binding
        != {
            "path": str(receipt_file),
            "size_bytes": len(raw_receipt),
            "raw_sha256": receipt_raw_sha256,
            "report_fingerprint": report_fingerprint,
        }
    ):
        raise EvidenceError("activation_confirmation_pair_binding_invalid")
    return {
        "release_gate_receipt": {
            "path": str(receipt_file),
            "size_bytes": len(raw_receipt),
            "raw_sha256": receipt_raw_sha256,
            "report_fingerprint": report_fingerprint,
        },
        "confirmation_capsule": {
            "path": str(capsule_file),
            "size_bytes": len(raw_capsule),
            "raw_sha256": hashlib.sha256(raw_capsule).hexdigest(),
            "transition_input_sha256": _sha256_json(transition),
        },
    }


def write_activation_confirmation_pair_commit(
    receipt_path: Path,
    report: Mapping[str, Any],
    *,
    capsule_path: Path | None = None,
) -> Path:
    _validate_production_release_report(report)
    receipt_file = receipt_path.expanduser().absolute()
    raw_receipt, verified_report = _read_exact_release_gate_receipt(
        receipt_file,
        report,
    )
    capsule_file = (
        capsule_path.expanduser().absolute()
        if capsule_path is not None
        else activation_confirmation_capsule_path(receipt_file).absolute()
    )
    loaded_capsule = _load_evidence(capsule_file.parent, capsule_file.name, {})
    raw_capsule, verified_capsule = _read_exact_release_gate_receipt(
        capsule_file,
        loaded_capsule,
    )
    material = _activation_confirmation_pair_material(
        receipt_path=receipt_file,
        raw_receipt=raw_receipt,
        report=verified_report,
        capsule_path=capsule_file,
        raw_capsule=raw_capsule,
        capsule=verified_capsule,
    )
    marker = {
        "schema_version": ACTIVATION_CONFIRMATION_PAIR_COMMIT_SCHEMA_VERSION,
        "created_at": _required_text(
            verified_report.get("evaluated_at"),
            "activation_confirmation_pair.created_at",
        ),
        **material,
        "pair_sha256": _sha256_json(material),
        "publication_complete": True,
        "operator_supplied_scope_fields": [],
    }
    destination = activation_confirmation_pair_commit_path(receipt_file)
    write_receipt_no_clobber(
        destination,
        marker,
        conflict_code="activation_confirmation_pair_commit_conflict",
    )
    return destination


def _read_activation_confirmation_pair_commit(
    *,
    receipt_path: Path,
    raw_receipt: bytes,
    report: Mapping[str, Any],
    capsule_path: Path,
    raw_capsule: bytes,
    capsule: Mapping[str, Any],
) -> dict[str, Any]:
    commit_path = activation_confirmation_pair_commit_path(receipt_path).absolute()
    loaded = _load_evidence(commit_path.parent, commit_path.name, {})
    _raw_commit, marker = _read_exact_release_gate_receipt(commit_path, loaded)
    if set(marker) != {
        "schema_version",
        "created_at",
        "release_gate_receipt",
        "confirmation_capsule",
        "pair_sha256",
        "publication_complete",
        "operator_supplied_scope_fields",
    }:
        raise EvidenceError("activation_confirmation_pair_commit_shape_invalid")
    material = _activation_confirmation_pair_material(
        receipt_path=receipt_path,
        raw_receipt=raw_receipt,
        report=report,
        capsule_path=capsule_path,
        raw_capsule=raw_capsule,
        capsule=capsule,
    )
    if (
        marker.get("schema_version")
        != ACTIVATION_CONFIRMATION_PAIR_COMMIT_SCHEMA_VERSION
        or marker.get("created_at") != report.get("evaluated_at")
        or marker.get("release_gate_receipt")
        != material["release_gate_receipt"]
        or marker.get("confirmation_capsule")
        != material["confirmation_capsule"]
        or marker.get("pair_sha256") != _sha256_json(material)
        or marker.get("publication_complete") is not True
        or marker.get("operator_supplied_scope_fields") != []
    ):
        raise EvidenceError("activation_confirmation_pair_commit_invalid")
    return dict(marker)


def read_activation_confirmation_capsule(
    capsule_path: Path,
    *,
    receipt_path: Path,
    current_activation: Mapping[str, Any],
) -> dict[str, Any]:
    expected_capsule_path = activation_confirmation_capsule_path(receipt_path)
    if capsule_path.expanduser().absolute() != expected_capsule_path.absolute():
        raise EvidenceError("activation_confirmation_capsule_path_invalid")
    receipt_file = receipt_path.expanduser().absolute()
    report = _load_evidence(receipt_file.parent, receipt_file.name, {})
    production_fingerprint = _validate_production_release_report(report)
    raw_receipt, _verified_report = _read_exact_release_gate_receipt(
        receipt_file,
        report,
    )
    capsule_file = capsule_path.expanduser().absolute()
    capsule = _load_evidence(capsule_file.parent, capsule_file.name, {})
    raw_capsule, verified_capsule = _read_exact_release_gate_receipt(
        capsule_file,
        capsule,
    )
    _read_activation_confirmation_pair_commit(
        receipt_path=receipt_file,
        raw_receipt=raw_receipt,
        report=_verified_report,
        capsule_path=capsule_file,
        raw_capsule=raw_capsule,
        capsule=verified_capsule,
    )
    if set(verified_capsule) != {
        "schema_version",
        "created_at",
        "release_gate_receipt",
        "ingress_freeze_binding",
        "runtime_continuity_binding",
        "transition_input",
        "transition_input_sha256",
        "operator_supplied_scope_fields",
        "same_file_descriptor_verification_required",
    }:
        raise EvidenceError("activation_confirmation_capsule_shape_invalid")
    capsule_created_at = _timestamp(
        verified_capsule.get("created_at"),
        "activation_confirmation_capsule.created_at",
    )
    receipt_binding = _mapping(
        verified_capsule.get("release_gate_receipt"),
        "activation_confirmation_capsule.release_gate_receipt",
    )
    transition = _mapping(
        verified_capsule.get("transition_input"),
        "activation_confirmation_capsule.transition_input",
    )
    report_config = _mapping(
        _verified_report.get("config"),
        "activation_confirmation_capsule.report_config",
    )
    report_consumer = _mapping(
        report_config.get("consumer"),
        "activation_confirmation_capsule.report_consumer",
    )
    trusted_health_path = Path(
        _required_text(
            report_consumer.get("health_path"),
            "activation_confirmation_capsule.consumer.health_path",
        )
    ).expanduser().absolute()
    ingress_freeze_binding = _validated_activation_ingress_freeze_binding(
        verified_capsule.get("ingress_freeze_binding"),
        expected_epoch_id=_required_text(
            transition.get("epoch_id"),
            "activation_confirmation_capsule.transition_input.epoch_id",
        ),
        expected_health_path=trusted_health_path,
    )
    runtime_continuity = _mapping(
        verified_capsule.get("runtime_continuity_binding"),
        "activation_confirmation_capsule.runtime_continuity_binding",
    )
    report_checks = _verified_report.get("checks")
    if not isinstance(report_checks, list):
        raise EvidenceError("activation_confirmation_capsule_binding_invalid")
    report_barriers = [
        item
        for item in report_checks
        if isinstance(item, Mapping)
        and item.get("name") == "activation_writer_barrier"
    ]
    if len(report_barriers) != 1:
        raise EvidenceError("activation_confirmation_capsule_binding_invalid")
    report_barrier = _mapping(
        report_barriers[0].get("detail"),
        "activation_confirmation_capsule.report_barrier",
    )
    if (
        set(receipt_binding)
        != {"path", "size_bytes", "raw_sha256", "report_fingerprint"}
        or receipt_binding.get("path") != str(receipt_file)
        or receipt_binding.get("size_bytes") != len(raw_receipt)
        or receipt_binding.get("raw_sha256")
        != hashlib.sha256(raw_receipt).hexdigest()
        or receipt_binding.get("report_fingerprint") != production_fingerprint
        or verified_capsule.get("transition_input_sha256")
        != _sha256_json(transition)
        or verified_capsule.get("operator_supplied_scope_fields") != []
        or verified_capsule.get("same_file_descriptor_verification_required")
        is not True
        or verified_capsule.get("schema_version")
        != ACTIVATION_CONFIRMATION_CAPSULE_SCHEMA_VERSION
        or ingress_freeze_binding
        != _mapping(
            report_barrier.get("ingress_freeze_binding"),
            "activation_confirmation_capsule.report_freeze_binding",
        )
        or dict(runtime_continuity)
        != _confirmation_runtime_continuity_binding(_verified_report)
    ):
        raise EvidenceError("activation_confirmation_capsule_binding_invalid")
    end_fence = _mapping(
        transition.get("partition_end_fence"),
        "activation_confirmation_capsule.partition_end_fence",
    )
    evaluated_at = _timestamp(
        _verified_report.get("evaluated_at"),
        "activation_confirmation_capsule.report_evaluated_at",
    )
    current_state = current_activation.get("state")
    if (
        transition.get("expected_state") != "bounded_active"
        or transition.get("target_state") != "confirmed"
        or transition.get("production_fingerprint") != production_fingerprint
        or transition.get("production_gate_receipt_sha256")
        != hashlib.sha256(raw_receipt).hexdigest()
        or transition.get("partition_end_fence_sha256")
        != _sha256_json(end_fence)
        or capsule_created_at != evaluated_at
        or current_state not in {"bounded_active", "confirmed"}
        or transition.get("epoch_id") != current_activation.get("epoch_id")
        or transition.get("config_sha256")
        != current_activation.get("config_sha256")
        or transition.get("db_logical_identity_sha256")
        != current_activation.get("db_logical_identity_sha256")
        or transition.get("partition_start_fence_sha256")
        != current_activation.get("partition_start_fence_sha256")
    ):
        raise EvidenceError("activation_confirmation_transition_binding_invalid")

    if current_state == "confirmed":
        if (
            transition.get("partition_end_fence_sha256")
            != current_activation.get("partition_end_fence_sha256")
            or transition.get("production_fingerprint")
            != current_activation.get("production_fingerprint")
            or transition.get("production_gate_receipt_sha256")
            != current_activation.get("production_gate_receipt_sha256")
        ):
            raise EvidenceError("activation_confirmation_idempotency_binding_invalid")
        return dict(transition)

    if transition.get("release_binding_sha256") != current_activation.get(
        "release_binding_sha256"
    ):
        raise EvidenceError("activation_confirmation_transition_binding_invalid")
    gate_policy = _mapping(
        _verified_report.get("gate_policy"),
        "activation_confirmation_capsule.gate_policy",
    )
    evidence_max_age_seconds = _exact_int(
        gate_policy.get("evidence_max_age_seconds"),
        "activation_confirmation_capsule.gate_policy.evidence_max_age_seconds",
        minimum=1,
    )
    if evidence_max_age_seconds > DEFAULT_EVIDENCE_MAX_AGE_SECONDS:
        raise EvidenceError("activation_confirmation_gate_policy_invalid")
    confirmation_now = datetime.now(timezone.utc)
    _recheck_confirmation_runtime_continuity(
        runtime_continuity,
        report=_verified_report,
        now=confirmation_now,
    )
    for observed in (evaluated_at, capsule_created_at):
        receipt_age_seconds = (confirmation_now - observed).total_seconds()
        if receipt_age_seconds < -MAX_HEALTH_FUTURE_SKEW_SECONDS:
            raise EvidenceError("activation_confirmation_receipt_from_future")
        if receipt_age_seconds > evidence_max_age_seconds:
            raise EvidenceError("activation_confirmation_receipt_stale")

    loaded_health = _load_service_health(
        str(trusted_health_path),
        artifact="activation_confirmation_consumer_health",
    )
    _raw_health, verified_health = _read_exact_release_gate_receipt(
        trusted_health_path,
        loaded_health,
    )
    runtime_identity = _mapping(
        verified_health.get("runtime_identity"),
        "activation_confirmation_consumer_health.runtime_identity",
    )
    runtime_identity_sha256 = _sha256_json(runtime_identity)
    stats = _mapping(
        verified_health.get("stats"),
        "activation_confirmation_consumer_health.stats",
    )
    normalized_end_fence = _activation_fence(
        _canonical_json(end_fence),
        field="activation_confirmation_consumer_health.partition_end_fence",
    )
    current_freeze = _activation_freeze_receipt(
        verified_health.get("activation_freeze"),
        epoch_id=_required_text(
            transition.get("epoch_id"),
            "activation_confirmation_consumer_health.epoch_id",
        ),
        expected_offsets=normalized_end_fence,
        expected_runtime_identity_sha256=runtime_identity_sha256,
        now=confirmation_now,
        max_age_seconds=DELIVERY_HEALTH_HARD_MAX_AGE_SECONDS,
    )
    current_freeze_binding = _activation_ingress_freeze_binding(
        freeze_receipt=current_freeze,
        health_path=trusted_health_path,
    )
    if (
        verified_health.get("state") != "activation_frozen"
        or verified_health.get("healthy") is not True
        or verified_health.get("ok") is not True
        or verified_health.get("activation_required") is not True
        or _exact_int(
            stats.get("blocked_partitions"),
            "activation_confirmation_consumer_health.stats.blocked_partitions",
            minimum=0,
        )
        != 0
        or runtime_identity_sha256
        != ingress_freeze_binding.get("consumer_runtime_identity_sha256")
        or current_freeze_binding != ingress_freeze_binding
    ):
        raise EvidenceError("activation_confirmation_consumer_not_frozen")
    _recheck_confirmation_runtime_continuity(
        runtime_continuity,
        report=_verified_report,
        now=datetime.now(timezone.utc),
    )
    return dict(transition)


def _path_lexists(path: Path) -> bool:
    return os.path.lexists(path.expanduser().absolute())


def _publish_or_resume_activation_confirmation(
    *,
    receipt_path: Path,
    report: Mapping[str, Any] | None,
    consumer: ConsumerConfig,
    dispatcher: DispatcherConfig,
    cutover: CutoverConfig,
) -> dict[str, Any] | None:
    receipt_file = receipt_path.expanduser().absolute()
    capsule_file = activation_confirmation_capsule_path(receipt_file).absolute()
    commit_file = activation_confirmation_pair_commit_path(receipt_file).absolute()
    members_exist = tuple(
        _path_lexists(path) for path in (receipt_file, capsule_file, commit_file)
    )
    if not any(members_exist) and report is None:
        return None
    if not members_exist[0] and any(members_exist[1:]):
        raise EvidenceError("activation_confirmation_orphan_publication")

    if members_exist[0]:
        with _activation_publication_lock(receipt_file):
            _recover_existing_no_clobber_member(
                receipt_file,
                conflict_code="production_release_gate_receipt_conflict",
            )
        loaded_report = _load_evidence(receipt_file.parent, receipt_file.name, {})
        _validate_production_release_report(loaded_report)
        _read_exact_release_gate_receipt(receipt_file, loaded_report)
        selected_report = loaded_report
        if report is not None and dict(report) != selected_report:
            raise EvidenceError("production_release_gate_receipt_conflict")
    else:
        if report is None:
            raise EvidenceError("activation_confirmation_receipt_missing")
        selected_report = dict(report)
        _validate_production_release_report(selected_report)
        write_receipt_no_clobber(
            receipt_file,
            selected_report,
            conflict_code="production_release_gate_receipt_conflict",
        )

    expected_config = _public_config(consumer, dispatcher, cutover)
    if selected_report.get("config") != expected_config:
        raise EvidenceError("activation_confirmation_runtime_config_changed")
    capsule_file = write_activation_confirmation_capsule(
        receipt_file,
        selected_report,
    )
    write_activation_confirmation_pair_commit(
        receipt_file,
        selected_report,
        capsule_path=capsule_file,
    )
    config_sha256 = _sha256_json(expected_config)
    current_activation = _check_activation_epoch(
        control_db_path=dispatcher.control_db_path,
        mode=str(selected_report.get("mode") or ""),
        expected_config_sha256=config_sha256,
    )
    read_activation_confirmation_capsule(
        capsule_file,
        receipt_path=receipt_file,
        current_activation=current_activation,
    )
    return selected_report


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--mode", required=True, choices=sorted(ALLOWED_MODES))
    parser.add_argument("--evidence-dir", type=Path, required=True)
    parser.add_argument("--env-file", type=Path)
    parser.add_argument("--expected-topic")
    parser.add_argument("--expected-rule-version")
    parser.add_argument("--host-contract", type=Path, default=default_host_path())
    parser.add_argument("--vm-contract", type=Path, default=default_vm_path())
    parser.add_argument("--host-repo-root", type=Path, default=REPO_ROOT)
    parser.add_argument("--workspace-repo-root", type=Path)
    parser.add_argument("--vm-repo-root", default=DEFAULT_VM_REPO_ROOT)
    parser.add_argument("--vm-worker-repo-root", default=DEFAULT_VM_WORKER_REPO_ROOT)
    parser.add_argument(
        "--evidence-max-age-seconds",
        type=int,
        default=DEFAULT_EVIDENCE_MAX_AGE_SECONDS,
    )
    parser.add_argument(
        "--shadow-soak-min-seconds",
        type=int,
        default=DEFAULT_SHADOW_SOAK_MIN_SECONDS,
    )
    parser.add_argument(
        "--min-storage-horizon-days",
        type=int,
        default=DEFAULT_MIN_STORAGE_HORIZON_DAYS,
    )
    parser.add_argument(
        "--target-cases-per-day",
        type=int,
        default=DEFAULT_TARGET_CASES_PER_DAY,
    )
    parser.add_argument(
        "--min-capacity-horizon-days",
        type=float,
        default=DEFAULT_MIN_CAPACITY_HORIZON_DAYS,
    )
    parser.add_argument("--receipt", type=Path)
    parser.add_argument(
        "--preauthorization-capsule",
        type=Path,
        help="immutable preauthorization capsule required by preproduction",
    )
    parser.add_argument(
        "--preproduction-capsule",
        type=Path,
        help="immutable preproduction capsule required by canary and production",
    )
    parser.add_argument(
        "--collect-activation-production-candidate",
        type=Path,
        help=(
            "write the required read-only activation_production_candidate.json "
            "after the resident consumer has published a partition-pause receipt"
        ),
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _build_parser().parse_args(argv)
    home = Path(os.environ.get("HERMES_HOME", "~/.hermes")).expanduser()
    env_file = (args.env_file or home / ".env").expanduser()
    expected_topic = str(
        args.expected_topic or os.environ.get("HERMES_RCA_RELEASE_EXPECTED_TOPIC", "")
    ).strip()
    expected_rule = str(
        args.expected_rule_version
        or os.environ.get("HERMES_RCA_RELEASE_EXPECTED_RULE_VERSION", "")
    ).strip()
    try:
        settings = ReleaseGateSettings(
            mode=args.mode,
            evidence_dir=args.evidence_dir.expanduser(),
            expected_topic=expected_topic,
            expected_rule_version=expected_rule,
            host_contract_path=args.host_contract.expanduser(),
            vm_contract_path=args.vm_contract.expanduser(),
            kafka_env_file=env_file,
            preauthorization_capsule_path=(
                args.preauthorization_capsule.expanduser()
                if args.preauthorization_capsule is not None
                else None
            ),
            preproduction_capsule_path=(
                args.preproduction_capsule.expanduser()
                if args.preproduction_capsule is not None
                else None
            ),
            group_binding_receipt_dir=(
                home / "pnc_agent" / "receipts" / "g1q3_rca"
            ),
            host_repo_root=args.host_repo_root.expanduser(),
            workspace_repo_root=(
                args.workspace_repo_root or home / "workspace-work"
            ).expanduser(),
            vm_repo_root=args.vm_repo_root,
            vm_worker_repo_root=args.vm_worker_repo_root,
            evidence_max_age_seconds=args.evidence_max_age_seconds,
            shadow_soak_min_seconds=args.shadow_soak_min_seconds,
            min_storage_horizon_days=args.min_storage_horizon_days,
            target_cases_per_day=args.target_cases_per_day,
            min_capacity_horizon_days=args.min_capacity_horizon_days,
        )
        if (
            args.mode in {"preauthorization", "preproduction"}
            or (
                args.mode in PRODUCTION_MODES
                and args.collect_activation_production_candidate is None
            )
        ) and args.receipt is None:
            raise ValueError("activation stage modes require --receipt")
        consumer, dispatcher = load_redacted_configs(env_file, hermes_home=home)
        cutover = load_cutover_config(env_file)
        if args.collect_activation_production_candidate is not None:
            if args.mode not in PRODUCTION_MODES:
                raise ValueError(
                    "activation production candidate collection requires production mode"
                )
            destination = (
                args.collect_activation_production_candidate.expanduser().absolute()
            )
            expected_destination = (
                args.evidence_dir.expanduser().absolute()
                / "activation_production_candidate.json"
            )
            if destination != expected_destination:
                raise ValueError(
                    "activation production candidate must use the canonical filename"
                )
            public_config = _public_config(consumer, dispatcher, cutover)
            config_sha256 = _sha256_json(public_config)
            runtime_detail = check_candidate_runtime_dependencies(
                settings.host_repo_root
            )
            _check_candidate_service_configs(
                runtime_detail,
                consumer=consumer,
                dispatcher=dispatcher,
                cutover=cutover,
                mode=args.mode,
            )
            service_configs = _mapping(
                runtime_detail.get("service_configs"),
                "activation_candidate.service_configs",
            )
            service_processes = _mapping(
                runtime_detail.get("service_processes"),
                "activation_candidate.service_processes",
            )
            service_dependencies = _mapping(
                runtime_detail.get("service_dependencies"),
                "activation_candidate.service_dependencies",
            )
            current = datetime.now(timezone.utc)
            health = _check_delivery_service_health(
                service_configs,
                service_processes,
                service_dependencies,
                now=current,
            )
            activation = _check_activation_epoch(
                control_db_path=dispatcher.control_db_path,
                mode=args.mode,
                expected_config_sha256=config_sha256,
            )
            consumer_health = _mapping(
                health.get("kafka_consumer_health"),
                "activation_candidate.kafka_consumer_health",
            )
            runtime_identity_sha256 = _sha256_digest(
                consumer_health.get("runtime_identity_sha256"),
                "activation_candidate.consumer_runtime_identity_sha256",
            )
            live_collector = collect_live_activation_end_fence(
                consumer=consumer,
                partition_start_fence=_mapping(
                    activation.get("partition_start_fence"),
                    "activation_candidate.partition_start_fence",
                ),
                epoch_id=str(activation.get("epoch_id") or ""),
                consumer_runtime_identity_sha256=runtime_identity_sha256,
                host_repo_root=settings.host_repo_root,
                now=current,
            )
            candidate = build_activation_production_candidate(
                activation=activation,
                expected_config_sha256=config_sha256,
                collector=live_collector,
                now=current,
            )
            _check_activation_production_candidate(
                candidate,
                activation=activation,
                consumer=consumer,
                expected_config_sha256=config_sha256,
                expected_consumer_runtime_identity_sha256=(
                    runtime_identity_sha256
                ),
                expected_host_repo_root=settings.host_repo_root,
                live_collector=live_collector,
                now=current,
                max_age_seconds=settings.evidence_max_age_seconds,
            )
            write_receipt_atomic(destination, candidate)
            print(json.dumps(candidate, ensure_ascii=False, sort_keys=True))
            return 0
        if (
            args.mode in {"preauthorization", "preproduction"}
            and args.receipt is not None
        ):
            resumed = _publish_or_resume_activation_stage(
                mode=args.mode,
                receipt_path=args.receipt,
                report=None,
                evidence_dir=settings.evidence_dir,
                control_db_path=dispatcher.control_db_path,
                consumer=consumer,
                dispatcher=dispatcher,
                cutover=cutover,
                preauthorization_capsule=settings.preauthorization_capsule_path,
            )
            if resumed is not None:
                print(json.dumps(resumed, ensure_ascii=False, sort_keys=True))
                return 0
        if args.mode in PRODUCTION_MODES and args.receipt is not None:
            resumed = _publish_or_resume_activation_confirmation(
                receipt_path=args.receipt,
                report=None,
                consumer=consumer,
                dispatcher=dispatcher,
                cutover=cutover,
            )
            if resumed is not None:
                print(json.dumps(resumed, ensure_ascii=False, sort_keys=True))
                return 0
        report = evaluate_release_gate(
            consumer=consumer,
            dispatcher=dispatcher,
            settings=settings,
            cutover=cutover,
        )
    except (OSError, ValueError, EvidenceError) as exc:
        report = _configuration_failure(
            mode=args.mode,
            code=(
                exc.code if isinstance(exc, EvidenceError) else "configuration_invalid"
            ),
            detail=type(exc).__name__,
        )
    if args.receipt:
        try:
            immutable_mode = report.get("mode") in {
                "preauthorization",
                "preproduction",
                *PRODUCTION_MODES,
            }
            if (
                report.get("ok") is True
                and report.get("mode") in PRODUCTION_MODES
            ):
                published = _publish_or_resume_activation_confirmation(
                    receipt_path=args.receipt,
                    report=report,
                    consumer=consumer,
                    dispatcher=dispatcher,
                    cutover=cutover,
                )
                if published is None:
                    raise EvidenceError("activation_confirmation_publication_failed")
                report = published
            elif report.get("ok") is True and report.get("mode") in {
                "preauthorization",
                "preproduction",
            }:
                published = _publish_or_resume_activation_stage(
                    mode=str(report["mode"]),
                    receipt_path=args.receipt,
                    report=report,
                    evidence_dir=settings.evidence_dir,
                    control_db_path=dispatcher.control_db_path,
                    consumer=consumer,
                    dispatcher=dispatcher,
                    cutover=cutover,
                    preauthorization_capsule=(
                        settings.preauthorization_capsule_path
                    ),
                )
                if published is None:
                    raise EvidenceError("activation_stage_publication_failed")
                report = published
            elif report.get("ok") is True and immutable_mode:
                write_receipt_no_clobber(
                    args.receipt,
                    report,
                    conflict_code=(
                        f"{report.get('mode')}_release_gate_receipt_conflict"
                    ),
                )
            elif not immutable_mode:
                write_receipt_atomic(args.receipt, report)
        except EvidenceError as exc:
            report = _configuration_failure(
                mode=args.mode,
                code=exc.code,
                detail="release_receipt_persistence_failed",
            )
    print(json.dumps(report, ensure_ascii=False, sort_keys=True))
    return 0 if report["ok"] else 2


if __name__ == "__main__":
    raise SystemExit(main())
